__modules["Scripts.dynamic-mission-test.main"] = "-- dynamic-mission-test\n-- Trigger-script ENTRY POINT (thin shim). The entire EECH-style dynamic campaign lives in\n-- game_loop.lua and its sub-modules; this file only wires the boot sequence:\n--   1. install the spawn-queue interception FIRST (before ANY spawn happens),\n--   2. nuke the previous injection (clean re-injection into the same running mission),\n--   3. start the campaign game loop,\n--   4. start the spawn-queue drain (everything above only ENQUEUED its spawns).\n--\n-- HISTORY: a legacy parallel supply / helicopter-CAP / ground-patrol wave layer used to live here\n-- (gated behind _G.DMT_ENABLE_LEGACY_LAYER). It fired a transport/CAP/patrol to EVERY base at once \226\128\148\n-- redundant with, and less EECH-faithful than, the game_loop campaign (task-board-driven supply,\n-- heli_war, frontline patrols). It was retired 2026-07-06 and DELETED entirely in Cluster H\n-- (2026-07-09); the campaign feel now comes solely from the EECH port.\n\nlocal cs = require(\"campaign_state\")\n-- Install the spawn-queue interception FIRST, before any spawn happens (reset + game_loop init):\n-- all coalition.addGroup / addStaticObject calls now enqueue and drain over time.\nrequire(\"spawn_queue\")\n\nlocal dynamic_mission_test = {}\ndynamic_mission_test.name    = \"dynamic-mission-test\"\ndynamic_mission_test.version = \"0.2.0\"\n\nlocal function info(msg)\n    env.info(string.format(\"[%s] %s\", dynamic_mission_test.name, msg))\nend\n\n-- \226\148\128\226\148\128 Entry point \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction dynamic_mission_test.start()\n    info(\"loaded v\" .. dynamic_mission_test.version)\n    cs.dbg(\"loop\", \"main.start(): generation=%d\", cs.GENERATION)\n\n    -- RESET FIRST: nuke the previous injection's world objects, event handlers, and F-10 marks so\n    -- each inject starts a fresh campaign in the SAME running mission (no DCS restart to iterate).\n    -- Runs before game_loop registers new handlers / spawns, so old-group deaths hit no handler.\n    require(\"reset\").nuke(info)\n    cs.dbg(\"loop\", \"main.start(): reset done; single game_loop.start() follows\")\nend\n\ndynamic_mission_test.start()\n\n-- Load + validate SCENARIO configuration (config.lua / _G.DMT_CONFIG) AFTER reset.nuke but BEFORE the\n-- game loop and its sub-modules are required (they read config.C at module scope) \226\128\148 so bad author\n-- overrides are caught and fall back to defaults before anything spawns. See config.lua header.\ncs.dbg(\"loop\", \"main.lua: config.load_and_validate() before game_loop require\")\nrequire(\"config\").load_and_validate(info)\n\n-- Start the EECH-inspired campaign game loop (attack waves, ground offensives, territory control,\n-- win conditions). Defined in game_loop.lua and its sub-modules.\ncs.dbg(\"loop\", \"main.lua: single unconditional require(\\\"game_loop\\\").start() call\")\nlocal game_loop = require(\"game_loop\")\ngame_loop.start()\n\n-- Everything above only ENQUEUED its spawns (spawn_queue intercepts addGroup). Start draining now\n-- that the full init burst is queued \226\128\148 one spawn per tick so the sim advances between each.\ncs.dbg(\"spawn\", \"main.lua: starting spawn_queue drain\")\nrequire(\"spawn_queue\").schedule_drain()\n\nreturn dynamic_mission_test\n"
__modules["attack_waves"] = "-- attack_waves.lua\n-- Inspired by:\n--   aphavoc/source/ai/highlevl/highlevl.c   create_oca_strike_tasks (every 30 min campaign),\n--                                            create_keysite_strike_tasks (every 7.5 min),\n--                                            create_bai_tasks (every 20 min),\n--                                            add_high_level_ai_function + staggered offset\n--   aphavoc/source/ai/highlevl/reaction.c   escort created reactively when task difficulty\n--                                            >= escort_required_threshold\n--   aphavoc/source/ai/taskgen/taskgen.h     create_escort_task factory function\n--   aphavoc/source/ai/highlevl/suitable.c   suitability matrix: ARMED_FW for strike,\n--                                            FIGHTER for escort (category-based selection)\n--\n-- Generates periodic fixed-wing strike packages against enemy airbases.\n-- Wave composition (strikers + escort) scales with campaign phase,\n-- mirroring EECH's skirmish-vs-campaign frequency compression and\n-- the reaction.c escort threshold gate.\n-- Losing side receives shorter strike interval, mirroring regen_frequency\n-- difficulty modifier (rg_updt.c).\n\nlocal cs       = require(\"campaign_state\")\nlocal keysite  = require(\"keysite\")\nlocal croute   = require(\"croute\")\nlocal supply   = require(\"supply\")\nlocal ov       = require(\"map_overlay\")\nlocal config   = require(\"config\")\nlocal board    = require(\"task_board\")\nlocal recon    = require(\"recon\")\nlocal fow      = require(\"fog_of_war\")\nlocal S        = cs.S\nlocal M        = {}\n\n-- FOW gate for the OCA-strike generator (highlevl.c:1433: fow(sector) >= 0.25 * FOW maximum). OCA has\n-- NO recon fallback (unlike the keysite-strike fork) \226\128\148 a fogged #1 target yields no OCA this cycle.\nlocal FOW_OCA_THRESHOLD = 0.25   -- highlevl.c:1433\n\n-- Side \226\134\146 pylon table for striker and escort (config.payloads[side].{striker,escort}; payloads.lua).\nlocal PYLON = config.C.payloads\n\n-- \226\148\128\226\148\128 Aircraft configuration \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Hoisted to config.lua (types.aircraft + countries; validated at boot). Unit type names verified\n-- against live DCS install (Unit.getDescByName, category=0).\nlocal AC = {}\nfor _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n    AC[side] = {\n        country = config.C.countries[side],\n        striker = config.C.types.aircraft[side].striker,   -- ARMED_FW / ground attack\n        escort  = config.C.types.aircraft[side].escort,    -- FIGHTER / air superiority\n    }\nend\n\n-- \226\148\128\226\148\128 Strike package size \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH's create_keysite_strike_tasks assigns the best resident group; a strike group's size is its\n-- member_count, not a per-cadence \"wave\" figure \226\128\148 there is no EECH per-task striker count. The old\n-- WAVE phase table (2/2/4 strikers + 0/1/2 escorts by invented phase) is removed: a single documented\n-- flight size, and escorts are now THREAT-thresholded per EECH's escort_required model (cs.escort_count,\n-- assign.c:598-627), computed on the actual launch\226\134\146target leg \226\128\148 NOT by elapsed-time phase.\nlocal STRIKE_PACKAGE_SIZE = 2   -- a standard 2-ship strike flight (documented port constant)\n\n-- Flight constants \226\128\148 in-air spawns only (TakeOffParking causes off-map spawns)\nlocal STRIKE_ALT   = 6000   -- m AMSL cruise altitude\nlocal ESCORT_ALT   = 7000   -- m, above strikers\nlocal STRIKE_SPEED = 220    -- m/s \226\137\136 428 kt\n\n-- Installation strike attrition (Cluster G): deterministic damage per sortie applied at time-on-\n-- target (static objects can't be EngageTargets'd, so this is the guaranteed destruction path).\nlocal INSTALLATION_STRIKE_DMG      = 0.5    -- ~2 sorties destroy an installation (health 1.0 \226\134\146 \226\137\1640.1);\n                                            -- with the concentration bias the economy war bites fast\nlocal INSTALLATION_TIME_ON_TARGET  = 150    -- s after launch (fly out + attack run) \226\128\148 quicker credit\n\n-- Airbase keysite-strike attrition (mirrors EECH create_keysite_strike_tasks reducing keysite\n-- strength). A keysite has far more \"buildings\" than an installation, so a package neutralises it\n-- over several strikes rather than ~3. KStrike (dedicated ground strike ON the keysite) hits harder\n-- than an OCA strike (counter-air, primarily suppressing the airfield's air ops).\nlocal KEYSITE_STRIKE_DMG           = 0.28   -- KStrike: 1.0 \226\134\146 capturable (<0.3) in ~3 focused strikes\nlocal OCA_STRIKE_DMG               = 0.16   -- OCA strike: lighter structural damage\nlocal KEYSITE_TIME_ON_TARGET       = 240    -- s after launch (fly out + attack run)\n\n-- \226\148\128\226\148\128 Strike package spawn \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors EECH's create_keysite_strike_tasks task-assignment model:\n-- find the nearest friendly keysite (airbase) to the target, spawn aircraft\n-- there using a real TakeOff waypoint \226\128\148 aircraft depart from their actual base\n-- just as EECH tasks existing aircraft at the nearest keysite.\n\n-- intent: \"oca\" (create_oca_strike_tasks \226\128\148 counter-air against airfield) or\n--         \"ground\" (create_keysite_strike_tasks \226\128\148 ground strike against installations).\n-- Both bomb the target keysite; they differ in cadence (7.5 min vs 30 min) and group-name\n-- prefix. When non-airbase keysites exist, targeting will diverge on oca_target vs\n-- ground_strike_target flags (see keysite flags); with airbase-only keysites the set is shared.\n-- \226\148\128\226\148\128 build_strike_package(side, base_name, tname, log_fn, intent) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- BUILDER (task-board contract): spawns the strike package FROM base_name. The board has already\n-- consumed STRIKE_PACKAGE_SIZE \"striker\" from base_name's ledger (refunds on nil). The escort\n-- sub-package is a SECONDARY consumption drawn directly from the SAME base's escort ledger, sized by\n-- the threat threshold (escort created at assignment, assign.c:598-627), with its own refund.\n-- Returns the strike group on success, nil on fail.\nlocal function build_strike_package(side, base_name, tname, log_fn, intent)\n    log_fn = log_fn or function() end\n    intent = intent or \"ground\"\n\n    local cfg      = AC[side]\n    local strikers = STRIKE_PACKAGE_SIZE\n    -- Target may be an airbase keysite OR a non-airbase installation (depot/radar/etc, Cluster G).\n    local is_installation = (S.base_pos[tname] == nil)\n    local tpos = S.base_pos[tname]\n              or (S.keysites and S.keysites[tname] and S.keysites[tname].pos)\n    if not tpos then\n        log_fn(\"strike: no position for \" .. tname)\n        cs.dbg(\"strike\", \"%s build_strike_package ABORT: no position for target %s\", cs.SIDE_NAME[side], tostring(tname))\n        return nil\n    end\n\n    local home_ab = Airbase.getByName(base_name)\n    if not home_ab then\n        cs.dbg(\"strike\", \"%s build_strike_package ABORT: base %s not found\", cs.SIDE_NAME[side], tostring(base_name))\n        return nil\n    end\n\n    local ab_pos = home_ab:getPosition().p\n    local bx, by = cs.wp_xy(ab_pos)\n    local tx, ty = cs.wp_xy(tpos)\n    local hdg    = cs.heading_to(ab_pos.x, ab_pos.z, tpos.x, tpos.z)\n    local sid    = cs.next_id()\n    local prefix = (intent == \"oca\") and \"OCAStrike\" or \"KStrike\"\n    local sname  = string.format(\"%s-%d\", prefix, sid)\n\n    -- Escort by threat (assign.c:598-627): count = 0/1/2 from route difficulty vs the strike escort\n    -- threshold (ground_strike / oca_strike = 3, CRITICAL 2-ship at difficulty >= 6). Replaces the\n    -- WAVE phase-table escort count. Computed on the real launch(ab_pos)\226\134\146target(tpos) leg.\n    local escorts = cs.escort_count((intent == \"oca\") and \"oca_strike\" or \"ground_strike\",\n                                    side, ab_pos, tpos, log_fn)\n\n    -- Units start on the ground at the airbase\n    local s_units = {}\n    for i = 1, strikers do\n        s_units[i] = {\n            name     = sname .. \"-\" .. i,\n            type     = cfg.striker,\n            skill    = \"Good\",\n            x        = ab_pos.x + (i-1) * 20,\n            y        = ab_pos.z,\n            alt      = ab_pos.y,\n            alt_type = \"BARO\",\n            speed    = 0,\n            heading  = hdg,\n            payload  = { fuel = 4900, flare = 60, chaff = 60, gun = 100, pylons = PYLON[side].striker },\n        }\n    end\n\n    local strike_grp = coalition.addGroup(cfg.country, Group.Category.AIRPLANE, {\n        name        = sname,\n        task        = \"Ground Attack\",\n        hidden      = false,\n        airdromeId  = home_ab:getID(),\n        units       = s_units,\n        -- Biased route (croute.c): valley-following / enemy-avoiding nav points spliced into each leg.\n        route = {\n            points = croute.expand({\n                {   -- TakeOff from the nearest friendly airbase\n                    type=\"TakeOff\", action=\"From Parking Area\",\n                    airdromeId = home_ab:getID(),\n                    alt=ab_pos.y, alt_type=\"BARO\", speed=0,\n                    ETA=0, ETA_locked=true,\n                    x=bx, y=by,\n                    name=\"Depart\", formation_template=\"\",\n                },\n                {   -- Attack run over the target\n                    type=\"Turning Point\", action=\"Turning Point\",\n                    alt=STRIKE_ALT, alt_type=\"BARO\", speed=STRIKE_SPEED,\n                    ETA=0, ETA_locked=false, x=tx, y=ty,\n                    name=\"Strike\", formation_template=\"\",\n                    task = {\n                        id = \"ComboTask\",\n                        params = { tasks = { [1] = {\n                            number=1, auto=true, id=\"EngageTargets\", enabled=true,\n                            params = { maxDist=10000, priority=0,\n                                       targetTypes = { \"Ground Units\", \"Helicopters\" } },\n                        }}},\n                    },\n                },\n                {   -- RTB\n                    type=\"Land\", action=\"Landing\",\n                    airdromeId = home_ab:getID(),\n                    alt=ab_pos.y, alt_type=\"BARO\", speed=STRIKE_SPEED,\n                    ETA=0, ETA_locked=false,\n                    x=bx, y=by,\n                    name=\"RTB\", formation_template=\"\",\n                },\n            }, side, { alt=STRIKE_ALT, alt_type=\"BARO\", speed=STRIKE_SPEED, name=\"Nav\" }),\n        },\n    })\n\n    if strike_grp then\n        -- Register the mission for BOTH airbase and installation keysites: EECH's\n        -- entity_is_object_of_task dedup spans the task's whole life (highlevl.c:1227-1231) and the\n        -- DEAD/LAND handlers clear the record. For installations the BIRTH-side CAP reaction\n        -- naturally no-ops (S.base_pos[tname]=nil \226\134\146 no obj_pos; matches factory requires_cap=FALSE,\n        -- ks_dbase.c:214) and LAND fires react_strike_complete (BDA/follow-on, reaction.c:609).\n        cs.register_task(sname, {\n            task_type   = (intent == \"oca\") and \"oca_strike\" or \"ground_strike\",\n            side        = side,\n            target_base = tname,\n            target_pos  = tpos,\n            objective   = { kind = \"keysite\", base = tname },\n            born_time   = timer.getTime(),\n            -- Item 3: capture target efficiency BEFORE the strike lands (assess_task ground-strike rating\n            -- = eff_before - eff_after, eech task.c:384). Airbase \226\134\146 base_health; installation \226\134\146 keysites.\n            eff_before  = S.base_health[tname]\n                or (S.keysites and S.keysites[tname] and S.keysites[tname].health) or 1.0,\n        })\n        if not is_installation then\n            -- Degrade the target keysite's building strength at time-on-target (mirrors EECH\n            -- keysite_strength reduction). Deterministic \226\128\148 an empty airfield yields no unit-kills,\n            -- so this is the guaranteed keysite-attrition source that lets bases fall and be captured.\n            local dmg = (intent == \"oca\") and OCA_STRIKE_DMG or KEYSITE_STRIKE_DMG\n            local my_gen = _DMT_GEN\n            timer.scheduleFunction(function()\n                if _DMT_GEN == my_gen then keysite.strike_damage(tname, dmg, log_fn) end\n                return nil\n            end, nil, timer.getTime() + KEYSITE_TIME_ON_TARGET)\n        else\n            -- DCS AI does not engage static objects via EngageTargets and no unit-kills occur in the\n            -- installation's rear, so credit deterministic damage after the package's time-on-target.\n            -- ~3 sorties destroy an installation; this is the guaranteed attrition source of truth.\n            local my_gen = _DMT_GEN\n            timer.scheduleFunction(function()\n                if _DMT_GEN == my_gen then\n                    require(\"installations\").damage(tname, INSTALLATION_STRIKE_DMG, log_fn)\n                end\n                return nil\n            end, nil, timer.getTime() + INSTALLATION_TIME_ON_TARGET)\n        end\n        log_fn(string.format(\"Strike %d: %s %dx%s from %s \226\134\146 %s (escorts=%d)\",\n            sid, cs.SIDE_NAME[side], strikers, cfg.striker,\n            home_ab:getName(), tname, escorts))\n        ov.add_task_arrow(sname, ab_pos, tpos, side)   -- Item 4: key by group name (clear_task reaps it)\n        cs.dbg(\"strike\", \"%s Strike #%d (%s) spawned from %s -> %s (installation=%s, dmg scheduled +%.0fs)\",\n            cs.SIDE_NAME[side], sid, intent, home_ab:getName(), tname, tostring(is_installation),\n            is_installation and INSTALLATION_TIME_ON_TARGET or KEYSITE_TIME_ON_TARGET)\n    else\n        -- Strike group creation failed \226\134\146 return nil; the board refunds the striker ledger.\n        log_fn(string.format(\"Strike %d FAILED: %s \226\134\146 %s\", sid, cs.SIDE_NAME[side], tname))\n        cs.dbg(\"strike\", \"%s Strike #%d (%s) SPAWN FAILED -> %s\", cs.SIDE_NAME[side], sid, intent, tname)\n        return nil\n    end\n\n    -- Escort (assign.c:598-627 threshold gate): secondary consumption from the SAME launch base's\n    -- escort ledger. Refunded to that base on spawn failure. Count from cs.escort_count above.\n    if escorts > 0 and supply.consume_base(base_name, \"escort\", escorts) then\n        local eid   = cs.next_id()\n        local ename = string.format(\"Escort-%d\", eid)\n\n        local e_units = {}\n        for i = 1, escorts do\n            e_units[i] = {\n                name     = ename .. \"-\" .. i,\n                type     = cfg.escort,\n                skill    = \"High\",\n                x        = ab_pos.x + (i-1) * 20,\n                y        = ab_pos.z,\n                alt      = ab_pos.y,\n                alt_type = \"BARO\",\n                speed    = 0,\n                heading  = hdg,\n                payload  = { fuel = 5200, flare = 120, chaff = 120, gun = 100, pylons = PYLON[side].escort },\n            }\n        end\n\n        -- pcall the escort addGroup: a THROW here must NOT propagate out of the builder (the strike\n        -- group already spawned+registered \226\128\148 a propagating throw would make the board double-credit\n        -- strikers and leak the escort). Contained throw/nil \226\134\146 refund the escort ledger only (MED-2).\n        local ok_e, escort_grp = pcall(coalition.addGroup, cfg.country, Group.Category.AIRPLANE, {\n            name       = ename,\n            task       = \"Fighter Sweep\",\n            hidden     = false,\n            airdromeId = home_ab:getID(),\n            units      = e_units,\n            route = {\n                points = croute.expand({\n                    {\n                        type=\"TakeOff\", action=\"From Parking Area\",\n                        airdromeId = home_ab:getID(),\n                        alt=ab_pos.y, alt_type=\"BARO\", speed=0,\n                        ETA=0, ETA_locked=true,\n                        x=bx, y=by,\n                        name=\"Depart\", formation_template=\"\",\n                    },\n                    {\n                        type=\"Turning Point\", action=\"Turning Point\",\n                        alt=ESCORT_ALT, alt_type=\"BARO\", speed=STRIKE_SPEED,\n                        ETA=0, ETA_locked=false, x=tx, y=ty,\n                        name=\"Sweep\", formation_template=\"\",\n                        task = {\n                            id = \"ComboTask\",\n                            params = { tasks = { [1] = {\n                                number=1, auto=true, id=\"EngageTargets\", enabled=true,\n                                params = { maxDist=40000, priority=0,\n                                           targetTypes = { \"Air\" } },\n                            }}},\n                        },\n                    },\n                    {\n                        type=\"Land\", action=\"Landing\",\n                        airdromeId = home_ab:getID(),\n                        alt=ab_pos.y, alt_type=\"BARO\", speed=STRIKE_SPEED,\n                        ETA=0, ETA_locked=false,\n                        x=bx, y=by,\n                        name=\"RTB\", formation_template=\"\",\n                    },\n                }, side, { alt=ESCORT_ALT, alt_type=\"BARO\", speed=STRIKE_SPEED, name=\"Nav\" }),\n            },\n        })\n\n        if ok_e and escort_grp then\n            log_fn(string.format(\"Escort %d: %s %dx%s from %s for Strike-%d\",\n                eid, cs.SIDE_NAME[side], escorts, cfg.escort,\n                home_ab:getName(), sid))\n            cs.dbg(\"strike\", \"%s Escort #%d spawned for Strike-%d\", cs.SIDE_NAME[side], eid, sid)\n        else\n            supply.recycle_base(base_name, \"escort\", escorts)  -- refund: escort spawn failed/threw\n            cs.dbg(\"strike\", \"%s Escort for Strike-%d FAILED (pcall_ok=%s) -> refunded\", cs.SIDE_NAME[side], sid, tostring(ok_e))\n        end\n    end\n    return strike_grp\nend\n\n-- \226\148\128\226\148\128 create_strike_task: enqueue a strike package task on the board \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- The board picks the launch base from the \"striker\" ledger (nearest, in range, package-sized stock)\n-- and calls build_strike_package. count = STRIKE_PACKAGE_SIZE (so the ledger consume matches the units\n-- build). Escort is a secondary threat-thresholded consume inside build_strike_package.\n-- immediate=true for the reaction single-shots so follow-on strikes assign without waiting a tick.\n-- `critical` (optional, WAVE 3 Item 4): when the reaction chain creates this task it passes true so the\n-- board sorts it at \195\1512 priority (assign.c:201-204) \226\128\148 EECH's reaction create_*_task calls all pass the\n-- critical argument = TRUE (reaction.c:459 OCA / :486 & :663 ground strike). Generator callers omit it\n-- (nil) \226\134\146 M.create_task falls back to the per-type M.CRITICAL default, so their behaviour is unchanged.\nlocal function create_strike_task(side, tname, log_fn, intent, immediate, critical)\n    log_fn = log_fn or function() end\n    intent = intent or \"ground\"\n    local tpos = S.base_pos[tname]\n              or (S.keysites and S.keysites[tname] and S.keysites[tname].pos)\n    if not tpos then\n        log_fn(\"strike: no position for \" .. tname)\n        cs.dbg(\"strike\", \"%s create_strike_task ABORT: no position for %s\", cs.SIDE_NAME[side], tostring(tname))\n        return false\n    end\n    local ttype = (intent == \"oca\") and \"oca_strike\" or \"ground_strike\"\n    cs.dbg(\"strike\", \"%s create_strike_task: %s vs %s (strikers=%d, immediate=%s)\",\n        cs.SIDE_NAME[side], ttype, tname, STRIKE_PACKAGE_SIZE, tostring(immediate))\n    board.create_task({\n        type = ttype, side = side, count = STRIKE_PACKAGE_SIZE, log_fn = log_fn, immediate = immediate,\n        critical = critical,   -- nil for generators (uses M.CRITICAL default); true from the reaction chain\n        -- target.base is ALWAYS the keysite name (airbase OR installation): the board's synthetic\n        -- dedup marker keys on it, and EECH's entity_is_object_of_task dedup covers every keysite\n        -- type (highlevl.c:1227-1231) \226\128\148 keying only real airbases left installation strikes\n        -- invisible to has_task_against, re-tasking the same installation every cycle.\n        target = { base = tname, pos = tpos },\n        builder = function(base_name)\n            return build_strike_package(side, base_name, tname, log_fn, intent)\n        end,\n    })\n    return true\nend\n\n-- \226\148\128\226\148\128 Scheduler registration \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH registers TWO distinct strike task creators (highlevl.c campaign branch):\n--   create_keysite_strike_tasks : 7.5 min / 15 s  \226\128\148 frequent ground strike vs installations\n--   create_oca_strike_tasks     : 30  min / 6.5 min \226\128\148 infrequent counter-air vs airfields\n-- These are separate tasks with separate cadence; the port must run both (a prior \"fix\"\n-- collapsed them into one at the OCA cadence, deleting the high-tempo strike \226\128\148 restored here).\n-- Item 5: mode-selected via campaign_mode.lua (campaign byte-identical to the prior literals).\nlocal mode                  = require(\"campaign_mode\")\nlocal KEYSITE_STRIKE_PERIOD = mode.SCHED.keysite_strike.period  -- highlevl.c:252 campaign / :228 skirmish\nlocal OCA_STRIKE_PERIOD     = mode.SCHED.oca_strike.period      -- highlevl.c:268 campaign / :242 skirmish\n\n-- create_keysite_strike_tasks (ground) scans the WHOLE ground_strike_target keysite set \226\128\148 airbases\n-- AND non-airbase installations \226\128\148 with ONE rating formula (keysite.pick_targets \226\134\146 keysite.\n-- strike_candidates), then applies the ratio gate + recon-first fork + eff/dedup gates. This replaces\n-- the old two-stream airbase/installation interleave and the invented installation STRIKE_VALUE table.\n-- create_oca_strike_tasks scores oca_target keysites only (airfields) with the OCA weights + FOW gate.\n\nlocal function run_scheduled_strike(side, intent, log_fn)\n    -- EECH generates strike tasks regardless of force strength (no survival mode; see\n    -- campaign_state.lua posture note + highlevl.c create_keysite_strike_tasks/create_oca_strike_tasks\n    -- which never inspect force_percentage). The former STRENGTH_SURVIVAL skip here was invented\n    -- (Cluster E).\n    if intent == \"ground\" then\n        -- CREATE_KEYSITE_STRIKE_TASK_COUNT = 3 (highlevl.c:94). keysite.pick_targets returns the funnel\n        -- decisions (strike vs recon) after the ratio/fork/eff/dedup gates; we just execute them.\n        local COUNT = 3\n        local decisions = keysite.pick_targets(side, COUNT, log_fn)\n        if #decisions == 0 then\n            log_fn(cs.SIDE_NAME[side] .. \": no valid ground strike target\")\n            return\n        end\n        for _, d in ipairs(decisions) do\n            if d.action == \"recon\" then\n                -- Recon-first fork (highlevl.c:1179-1205): reconnoitre the keysite; the GROUND STRIKE\n                -- is created on recon completion by the reaction chain (react_recon_complete_keysite).\n                -- objective.base is the airbase keysite so the reaction re-strikes the right target.\n                recon.spawn_recon(side, d.pos, \"KStrikeRecon\", log_fn, { kind = \"keysite\", base = d.name })\n            else\n                create_strike_task(side, d.name, log_fn, \"ground\")\n            end\n        end\n    else\n        -- create_oca_strike_tasks (highlevl.c:1286-1467): best oca_target airbase by the OCA weights,\n        -- then FOW>=0.25 gate + dedup vs oca_strike/bda/troop_insertion. Count = 1 (ratio gate moot).\n        local tname = keysite.pick_target(side, log_fn, keysite.RATE_OCA_STRIKE)\n        if not tname then\n            log_fn(cs.SIDE_NAME[side] .. \": no valid oca strike target\")\n            cs.dbg(\"strike\", \"%s OCA strike: no valid target\", cs.SIDE_NAME[side])\n            return\n        end\n        local fow_val = fow.get(tname, side) or 0.0            -- airbase name is a FOW sector key\n        if fow_val < FOW_OCA_THRESHOLD then\n            cs.dbg(\"strike\", \"%s OCA strike SKIPPED: %s fogged (fow=%.2f < %.2f)\",\n                cs.SIDE_NAME[side], tname, fow_val, FOW_OCA_THRESHOLD)   -- highlevl.c:1433\n        elseif cs.has_task_against(\"oca_strike\", tname, side)\n            or cs.has_task_against(\"bda\", tname, side)\n            or cs.has_task_against(\"troop_insertion\", tname, side) then\n            cs.dbg(\"strike\", \"%s OCA strike SKIPPED: %s already tasked (dedup)\",\n                cs.SIDE_NAME[side], tname)                               -- highlevl.c:1435-1440\n        else\n            create_strike_task(side, tname, log_fn, \"oca\")\n        end\n    end\nend\n\n-- create_keysite_strike_tasks \226\128\148 ground strike, 7.5 min campaign period.\nfunction M.schedule_keysite_strikes(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"strike\", \"%s keysite-strike scheduler REGISTERED offset=%.0fs period=%.0fs\",\n        cs.SIDE_NAME[side], initial_offset, KEYSITE_STRIKE_PERIOD)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end   -- re-injection guard: cancel superseded closure\n        -- Item 6 (LITERAL post-victory semantics): generators keep running after the win is declared \226\128\148\n        -- EECH fc_msgs.c:163 gates ONLY the win-check re-award (INT_TYPE_SESSION_COMPLETE), never the\n        -- highlevl.c task generators. The prior Cluster-E generator suppression is removed (was a proxy).\n        cs.dbg(\"strike\", \"%s keysite-strike FIRE\", cs.SIDE_NAME[side])\n        run_scheduled_strike(side, \"ground\", log_fn)\n        return t + KEYSITE_STRIKE_PERIOD\n    end, nil, timer.getTime() + initial_offset)\nend\n\n-- create_oca_strike_tasks \226\128\148 offensive counter-air, 30 min campaign period.\nfunction M.schedule_oca_strikes(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"strike\", \"%s oca-strike scheduler REGISTERED offset=%.0fs period=%.0fs\",\n        cs.SIDE_NAME[side], initial_offset, OCA_STRIKE_PERIOD)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end   -- re-injection guard: cancel superseded closure\n        -- Item 6: generators keep running post-victory (EECH fc_msgs.c:163 gates only the win re-award).\n        cs.dbg(\"strike\", \"%s oca-strike FIRE\", cs.SIDE_NAME[side])\n        run_scheduled_strike(side, \"oca\", log_fn)\n        return t + OCA_STRIKE_PERIOD\n    end, nil, timer.getTime() + initial_offset)\nend\n\n-- \226\148\128\226\148\128 Single-shot spawns (called by reaction.lua for follow-on strike tasks) \226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH creates DISTINCT follow-on tasks: create_ground_strike_task (reaction.c:663) and\n-- create_oca_strike_task (reaction.c:490). Kept as separate entry points so reaction.lua\n-- can stop calling one generic run_strike for both (react-M5 fix, Cluster C).\nlocal function run_single(side, intent, tname_override, log_fn, critical)\n    log_fn = log_fn or function() end\n    -- No survival gate: EECH's reaction-chain follow-on strikes (reaction.c) never check force strength.\n    -- reaction always passes an override; the pick path (weights per intent) is a defensive fallback.\n    local weights = (intent == \"oca\") and keysite.RATE_OCA_STRIKE or keysite.RATE_GROUND_STRIKE\n    local tname = tname_override or keysite.pick_target(side, log_fn, weights)\n    if tname then\n        cs.dbg(\"strike\", \"%s run_single(%s): single-shot vs %s (override=%s)\",\n            cs.SIDE_NAME[side], intent, tname, tostring(tname_override ~= nil))\n        -- immediate=true: reaction follow-ons assign this tick (create_ground/oca_strike_task). critical\n        -- threaded from the reaction caller (reaction.c create_*_strike_task pass TRUE).\n        local ok, err = pcall(create_strike_task, side, tname, log_fn, intent, true, critical)\n        if not ok then log_fn(\"run_\" .. intent .. \"_strike error: \" .. tostring(err)) end\n    else\n        cs.dbg(\"strike\", \"%s run_single(%s) ABORT: no target resolved\", cs.SIDE_NAME[side], intent)\n    end\nend\n\n-- create_ground_strike_task \226\128\148 ground strike against installations. `critical` (optional, WAVE 3 Item 4)\n-- is passed true by reaction.lua (reaction.c:486/:663 create_ground_strike_task critical=TRUE); the\n-- scheduled generator does not call this export, so the added trailing arg never affects a generator path.\nfunction M.run_strike(side, log_fn, tname, critical)\n    run_single(side, \"ground\", tname, log_fn, critical)\nend\n\n-- create_oca_strike_task \226\128\148 offensive counter-air against an airfield. `critical` (optional) is passed\n-- true by reaction.lua (reaction.c:459 create_oca_strike_task critical=TRUE); oca_strike is already in\n-- M.CRITICAL so the explicit true is behaviour-preserving, threaded for consistency with the chain.\nfunction M.run_oca_strike(side, log_fn, tname, critical)\n    run_single(side, \"oca\", tname, log_fn, critical)\nend\n\nreturn M\n"
__modules["base_defenses"] = "-- base_defenses.lua\n-- EECH source: aphavoc/source/gunships/campaign/populate/popread.c\n--   read_population_sam_placements (popread.c:2148-2212): for EVERY population AAA/SAM placement point\n--   the engine spawns an ENTITY_SUB_TYPE_GROUP_ANTI_AIRCRAFT group, formation\n--   FORMATION_COMPONENT_LIGHT_SAM_AAA_GROUP (popread.c:2204), member count = max(0, component_count-1)\n--   = 2 (popread.c:2208), side = the initial sector side. The placement POINTS come from the map\n--   population templates (TEMPLATE_TYPE_AIRFIELD / TEMPLATE_TYPE_AAASAM, popread.c:100-101), which seed\n--   SEVERAL such points around every airfield/town \226\134\146 EECH keysites, especially airbases, are ringed by\n--   many AA groups.\n--\n-- This module ports that: each basing keysite (and each installation keysite) is ringed with N\n-- LIGHT_SAM_AAA_GROUP groups. Because the per-keysite point DENSITY lives in the map population data\n-- (not the C tree), N is a DOCUMENTED DESIGNER PROXY (config.defenses.groups_per: airbase=3, farp=1,\n-- installation=1; author sets 0 to opt a class out). The per-group composition is FORMCOMP.DAT:535-545\n-- LIGHT_SAM_AAA_GROUP's first TWO slots (popread.c:2208 count-1=2): BLUE {M48 Chaparral, Vulcan},\n-- RED {2S6 Tunguska (SA-19), Strela-10M3 (SA-13)}. FORMCOMP HEAVY_SAM_AAA_GROUP:516-530 has no code\n-- consumer in the shipped tree (popread.c:2204 uses LIGHT only) \226\134\146 deliberately NOT ported.\n--\n-- CLASSIFICATION (critical): these groups are SITE AA (EECH air_attack_strength==10 non-frontline AA,\n-- highlevl.c:1981) \226\134\146 SEAD targets, NOT campaign ground groups. Their name prefix \"AD-\" does NOT match\n-- the protected campaign-group tag set (^GndCol / ^Arty / -def$ / ^Patrol), so cas_bai_sead's\n-- group_frontline_flag returns nil \226\134\146 get_enemy_aa_targets picks them up and get_enemy_ground_targets\n-- excludes them (their lead unit has a SAM/AAA attribute). imap.update_air_defence scans AA by unit\n-- attribute with no name filter, so they feed the AIR_DEFENCE layer automatically.\n--\n-- ECONOMY: FREE OOB placement \226\128\148 no force_reserve consume. EECH population AA is engine-placed at map\n-- load and never draws on force_info hardware (popread.c:2148-2212); the old garrison here also spawned\n-- free. They are NOT registered as keysite assets (register_static_death untouched) \226\128\148 they defend;\n-- keysite health stays building-driven.\n--\n-- Spawned through coalition.addGroup \226\134\146 intercepted by spawn_queue, so the rings drain in over time.\n-- reset.nuke clears them; they re-seed on the next injection (S.base_ad_groups is cleared at init).\n--\n-- POPULATION FIRING POINTS (added): popread.c:1389-1439 (read_population_sam_placements' building\n-- scene-link branch) additionally spawns SINGLE-UNIT GROUP_STATIC_INFANTRY groups at each population\n-- building link \226\128\148 LIGHT/MEDIUM/HEAVY_FIRING_POINT MG posts (FORMCOMP.DAT:693-717 :COUNT 1) and\n-- INFANTRY_SAM_STANDING/KNEELING MANPAD soldiers (FORMCOMP.DAT:617-631 :COUNT 1), linked to the closest\n-- keysite, sector-side owned. This module scatters an even MG/MANPAD mix inside each keysite's footprint\n-- (config.defenses.firing_points count = designer proxy for the map population density). CLASSIFICATION:\n-- GROUP_STATIC_INFANTRY frontline_flag = NONE (gp_dbase.c:887) and air_attack_strength = 6 (:896) \226\134\146 the\n-- \"FP-\" name maps to group_frontline_flag 0: a target of NEITHER CAS(==1) nor BAI(>1), and excluded from\n-- the generator SEAD's get_enemy_aa_targets (highlevl.c:1981 wants air_attack==10 site AA). MANPADs still\n-- feed the AIR_DEFENCE imap by attribute (desired). Tracked in S.base_fp_groups; re-manned on capture.\n\nlocal cs     = require(\"campaign_state\")\nlocal config = require(\"config\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- Per-group composition = FORMCOMP.DAT:535-545 LIGHT_SAM_AAA_GROUP first 2 slots (popread.c:2208).\nlocal DEF = config.C.defenses\nlocal GROUP_UNITS = {}\nlocal MG_TYPE, MANPAD_TYPE = {}, {}\nfor _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n    GROUP_UNITS[side]  = DEF.group[side]\n    MG_TYPE[side]      = DEF.mg[side]        -- population FIRING-POINT MG post (proxy soldier)\n    MANPAD_TYPE[side]  = DEF.manpad[side]    -- population INFANTRY_SAM MANPAD soldier\nend\n\n-- Group count for a keysite class (config.defenses.groups_per; designer proxy for popread density).\nlocal function groups_for_kind(kind)\n    local gp = DEF.groups_per\n    if kind == \"airbase\" then return gp.airbase or 0 end\n    if kind == \"farp\"    then return gp.farp or 0 end\n    return gp.installation or 0   -- every non-basing keysite class\nend\n\n-- Firing-point count for a keysite class (config.defenses.firing_points; designer proxy for the\n-- popread population FIRING-POINT / MANPAD scene-link density, popread.c:1389-1439).\nlocal function firing_points_for_kind(kind)\n    local fp = DEF.firing_points\n    if kind == \"airbase\" then return fp.airbase or 0 end\n    if kind == \"farp\"    then return fp.farp or 0 end\n    return fp.installation or 0\nend\n\n-- Spawn `n` LIGHT_SAM_AAA_GROUP air-defence groups evenly around `pos` at DEF.ring_radius. `key` names\n-- the S.base_ad_groups bucket (for regarrison teardown); `tag` is the readable name stem. Returns the\n-- number of groups placed. FREE (no reserve consume); groups are recorded for capture re-garrison only.\nlocal function spawn_ring(key, tag, side, pos, n, log_fn)\n    if not n or n <= 0 then return 0 end\n    local proto   = GROUP_UNITS[side]\n    local country = config.C.countries[side]\n    if not proto or #proto == 0 or not country or not pos then\n        cs.dbg(\"basedef\", \"spawn_ring ABORT %s: proto=%s country=%s pos=%s\",\n            tostring(tag), tostring(proto ~= nil), tostring(country ~= nil), tostring(pos ~= nil))\n        return 0\n    end\n    S.base_ad_groups = S.base_ad_groups or {}\n    local recorded = S.base_ad_groups[key] or {}\n    local placed = 0\n    for i = 1, n do\n        local ang = (i - 1) * (2 * math.pi / n)\n        -- ground units: x = north, y = east(z). Snap the RING slot off water (coastal keysite \226\128\148\n        -- Batumi) to the nearest land; fallback = the keysite/base centre `pos` (always land).\n        local sp  = cs.snap_land(pos.x + math.cos(ang) * DEF.ring_radius,\n                                 pos.z + math.sin(ang) * DEF.ring_radius, pos.x, pos.z)\n        local gx  = sp.x\n        local gz  = sp.z\n        -- \"AD-<tag>-<id>\" \226\128\148 MUST NOT collide with the protected tag set (^GndCol/^Arty/-def$/^Patrol),\n        -- so these classify as SITE AA (SEAD targets), never campaign ground groups.\n        local gname = string.format(\"AD-%s-%d\", tag, cs.next_id())\n        local units = {}\n        for j, utype in ipairs(proto) do\n            units[j] = {\n                name = gname .. \"-\" .. j, type = utype, skill = \"Average\",\n                x = gx + (j - 1) * 30, y = gz, heading = 0,\n            }\n        end\n        local ok = pcall(coalition.addGroup, country, Group.Category.GROUND, {\n            name = gname, task = \"Ground Nothing\", units = units,\n            route = { points = { {\n                x = gx, y = gz, type = \"Turning Point\", action = \"Off Road\", speed = 0,\n                ETA = 0, ETA_locked = true,\n            } } },\n        })\n        if ok then\n            placed = placed + 1\n            recorded[#recorded + 1] = gname\n        end\n    end\n    S.base_ad_groups[key] = recorded\n    return placed\nend\n\n-- Scatter `n` single-unit population FIRING-POINT groups inside `key`'s footprint. EECH popread.c:\n-- 1389-1439 spawns one GROUP_STATIC_INFANTRY group per population building scene-link:\n-- LIGHT/MEDIUM/HEAVY_FIRING_POINT (MG posts, FORMCOMP.DAT:693-717 :COUNT 1) and INFANTRY_SAM_STANDING/\n-- KNEELING (MANPAD soldier, FORMCOMP.DAT:617-631 :COUNT 1), owned by the sector side. The port scatters\n-- an even MG/MANPAD mix (alternating) at random points within DEF.ring_radius of the keysite centre, at\n-- land height (like the infantry patrols). FREE (no reserve consume \226\128\148 population placement). Records the\n-- group names in S.base_fp_groups[key] for capture re-garrison teardown. Returns the count placed.\nlocal function spawn_firing_points(key, tag, side, pos, n, log_fn)\n    if not n or n <= 0 then return 0 end\n    local country = config.C.countries[side]\n    local mg, man = MG_TYPE[side], MANPAD_TYPE[side]\n    if not country or not pos or not mg or not man then\n        cs.dbg(\"basedef\", \"spawn_firing_points ABORT %s: country=%s pos=%s mg=%s manpad=%s\",\n            tostring(tag), tostring(country ~= nil), tostring(pos ~= nil), tostring(mg ~= nil), tostring(man ~= nil))\n        return 0\n    end\n    S.base_fp_groups = S.base_fp_groups or {}\n    local recorded = S.base_fp_groups[key] or {}\n    local placed = 0\n    for i = 1, n do\n        -- Alternate MG / MANPAD \226\134\146 ~half each (popread mixes firing-point posts and MANPAD soldiers).\n        local utype = (i % 2 == 1) and mg or man\n        local ang   = math.random() * 2 * math.pi\n        local r     = math.random() * DEF.ring_radius   -- scatter INSIDE the keysite footprint\n        -- Snap the scattered firing-point off water (a 300 m ring at a coastal site can be wet);\n        -- fallback = the keysite/base centre `pos` (always land).\n        local sp    = cs.snap_land(pos.x + math.cos(ang) * r, pos.z + math.sin(ang) * r, pos.x, pos.z)\n        local gx    = sp.x\n        local gz    = sp.z\n        local gy    = land.getHeight({ x = gx, y = gz })\n        -- \"FP-<tag>-<id>\" \226\128\148 cas_bai_sead.group_frontline_flag maps ^FP- \226\134\146 flag 0 (NONE): a target of\n        -- NEITHER CAS(==1) nor BAI(>1), and excluded from the generator SEAD's get_enemy_aa_targets.\n        local gname = string.format(\"FP-%s-%d\", tag, cs.next_id())\n        local ok = pcall(coalition.addGroup, country, Group.Category.GROUND, {\n            name = gname, task = \"Ground Nothing\",\n            units = {{ name = gname .. \"-1\", type = utype, skill = \"Average\",\n                       x = gx, y = gz, alt = gy, alt_type = \"BARO\", heading = 0 }},\n            route = { points = { {\n                x = gx, y = gz, type = \"Turning Point\", action = \"Off Road\", speed = 0,\n                ETA = 0, ETA_locked = true,\n            } } },\n        })\n        if ok then\n            placed = placed + 1\n            recorded[#recorded + 1] = gname\n        end\n    end\n    S.base_fp_groups[key] = recorded\n    return placed\nend\n\n-- Seed the air-defence rings at every keysite. Called from game_loop init AFTER keysite OOB\n-- (S.base_owner / S.base_kind / S.base_pos) and installations init (S.keysites). Works in BOTH the\n-- zone-authored and auto theatres \226\128\148 air-defence UNITS are campaign OOB (like ground columns/patrols),\n-- engine-placed by popread, never author-placed (the register-don't-spawn directive governs keysite\n-- ASSETS/statics, not defence units).\nfunction M.init(log_fn)\n    log_fn = log_fn or function() end\n    S.base_ad_groups = {}   -- fresh registry each injection (reset.nuke already destroyed the groups)\n    S.base_fp_groups = {}   -- fresh FIRING-POINT registry (population statics, popread.c:1389-1439)\n    local zoned = require(\"zones\").has_keysite_zones()\n    local n_groups, n_sites, n_fp = 0, 0, 0\n\n    -- (A) Basing keysites: airbases + FARPs (S.base_kind distinguishes; default airbase).\n    for base_name, side in pairs(S.base_owner) do\n        if side == coalition.side.BLUE or side == coalition.side.RED then\n            local kind   = (S.base_kind and S.base_kind[base_name]) or \"airbase\"\n            local pos    = S.base_pos[base_name]\n            local placed = spawn_ring(base_name, base_name:sub(1, 10), side, pos, groups_for_kind(kind), log_fn)\n            n_fp = n_fp + spawn_firing_points(base_name, base_name:sub(1, 10), side, pos,\n                firing_points_for_kind(kind), log_fn)\n            n_groups = n_groups + placed\n            if placed > 0 then n_sites = n_sites + 1 end\n        end\n    end\n\n    -- (B) Installation keysites (non-basing): one ring each, EXCEPT auto-template keysites, which\n    -- already spawned their own -aaa/-sam defence elements from the empty-zone TEMPLATE (no double AD).\n    -- Skips the \"AB-<name>\" airbase-asset records (kind==\"airbase\", already ringed by their airbase).\n    for kname, rec in pairs(S.keysites or {}) do\n        if rec.kind ~= \"airbase\" and rec.pos and not rec.templated then\n            local ok_i, inst = pcall(require, \"installations\")\n            local side = rec.side or (ok_i and inst and inst.side_of and inst.side_of(rec))\n                       or (rec.home_base and S.base_owner[rec.home_base])\n            if side == coalition.side.BLUE or side == coalition.side.RED then\n                local placed = spawn_ring(kname, kname:sub(1, 12), side, rec.pos,\n                    groups_for_kind(\"installation\"), log_fn)\n                n_fp = n_fp + spawn_firing_points(kname, kname:sub(1, 12), side, rec.pos,\n                    firing_points_for_kind(\"installation\"), log_fn)\n                n_groups = n_groups + placed\n                if placed > 0 then n_sites = n_sites + 1 end\n            end\n        end\n    end\n\n    log_fn(string.format(\n        \"base_defenses: air-defence rings seeded \226\128\148 %d LIGHT_SAM_AAA groups + %d firing-point/MANPAD groups across %d keysites%s\",\n        n_groups, n_fp, n_sites, zoned and \" (zone-authored theatre)\" or \" (auto theatre)\"))\n    cs.dbg(\"basedef\", \"init: %d AD groups + %d firing-point groups across %d keysites (zoned=%s)\",\n        n_groups, n_fp, n_sites, tostring(zoned))\nend\n\n-- Re-garrison a keysite when it changes hands (called from keysite.do_capture). A base is only\n-- capturable after its efficiency falls below the minimum \226\128\148 its own defences were ground down by the\n-- strikes that neutralised it \226\128\148 but any surviving AD from the old owner would otherwise fight the\n-- incoming ring, so we TEAR DOWN the recorded old-owner groups first, then seed the new owner's ring.\n-- Mirrors the sector flipping ownership of its population AA (popread.c places per initial sector side;\n-- the port re-places on capture so the new owner is defended). Idempotent: destroy() no-ops on the\n-- already-dead survivors, and the registry bucket is rebuilt from scratch.\nfunction M.regarrison(base_name, new_side, log_fn)\n    log_fn = log_fn or function() end\n    S.base_ad_groups = S.base_ad_groups or {}\n    S.base_fp_groups = S.base_fp_groups or {}\n    local torn, torn_fp = 0, 0\n    for _, gname in ipairs(S.base_ad_groups[base_name] or {}) do\n        local g = Group.getByName(gname)\n        if g then pcall(function() g:destroy() end); torn = torn + 1 end\n    end\n    S.base_ad_groups[base_name] = nil\n    -- Firing points flip owner too (popread.c places per sector side; on capture the new owner re-mans\n    -- them). Tear down any surviving old-owner FP/MANPAD groups, then re-scatter the captor's.\n    for _, gname in ipairs(S.base_fp_groups[base_name] or {}) do\n        local g = Group.getByName(gname)\n        if g then pcall(function() g:destroy() end); torn_fp = torn_fp + 1 end\n    end\n    S.base_fp_groups[base_name] = nil\n    local kind   = (S.base_kind and S.base_kind[base_name]) or \"airbase\"\n    local pos    = S.base_pos[base_name]\n    local placed = spawn_ring(base_name, base_name:sub(1, 10), new_side, pos, groups_for_kind(kind), log_fn)\n    local fp     = spawn_firing_points(base_name, base_name:sub(1, 10), new_side, pos,\n        firing_points_for_kind(kind), log_fn)\n    log_fn(string.format(\"base_defenses: re-garrisoned %s for %s (%d AD + %d firing-point groups, %d+%d old torn down)\",\n        base_name, cs.SIDE_NAME[new_side] or \"?\", placed, fp, torn, torn_fp))\n    cs.dbg(\"basedef\", \"regarrison %s -> %s: %d AD + %d FP groups placed, %d+%d survivors torn down\",\n        base_name, cs.SIDE_NAME[new_side] or \"?\", placed, fp, torn, torn_fp)\nend\n\nreturn M\n"
__modules["campaign_mode"] = "-- campaign_mode.lua \226\128\148 scheduler cadence set selected by campaign mode (CAMPAIGN | SKIRMISH).\n-- EECH source:\n--   aphavoc/source/ai/highlevl/highlevl.c  start_high_level_ai (:181-287): registers every\n--     create_*_tasks generator with a period + start_time. There are TWO tables \226\128\148 a SKIRMISH branch\n--     (get_game_type()==GAME_TYPE_SKIRMISH, :218-242, faster periods) and the campaign branch\n--     (the else, :246-268). A DCS session == campaign mode, which the port hardcoded across modules;\n--     this module centralises BOTH so config.C.mode selects the cadence set.\n--\n-- WHAT LIVES HERE (and why it is not in config.lua): these are EECH-CITED ENGINE CONSTANTS (each value\n-- cites its highlevl.c line), so per CLAUDE.md they stay in a module, not the scenario-data config. The\n-- ONLY config knob is the selector `config.C.mode` (\"campaign\"|\"skirmish\"); a bad/absent value falls\n-- back to CAMPAIGN here (defensive default \226\128\148 this module loads before config.load_and_validate runs).\n--\n-- SCHED[gen] = { period = seconds, blue = offset_s, red = offset_s }:\n--   * period + `blue` (the port's BLUE-side start delay) trace to the cited EECH period/start_time.\n--   * `red` is the port's per-side stagger of the single EECH generator into a BLUE and a RED pass\n--     (EECH has one function per task; the port runs one per side). The stagger rule is a PORT\n--     construct, applied IDENTICALLY in both modes so the two are structurally parallel:\n--       - keysite_strike / oca_strike / ground \226\134\146 red = blue + floor(period/2)  (half-period offset)\n--       - cas                                   \226\134\146 blue 5, red 30  (EECH start_time 0 bumped to 5: DCS\n--                                                 silently drops a timer scheduled at getTime()+0)\n--       - every other generator                 \226\134\146 red = blue + 30 (fixed 30 s stagger)\n--   The CAMPAIGN column is BYTE-IDENTICAL to the port's prior hardcoded module periods + game_loop\n--   offset expressions (verified value-by-value against the pre-change literals).\n\nlocal config = require(\"config\")\nlocal M = {}\n\nlocal MIN = 60\n\n-- \226\148\128\226\148\128 CAMPAIGN cadence (highlevl.c:246-268 else-branch) \226\128\148 byte-identical to prior port values \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- period      blue   red         highlevl.c line (campaign start_time)          prior port literal\nlocal CAMPAIGN = {\n    cas             = { period = 15   * MIN, blue = 5,   red = 30   },  -- :246 15min off 0.0 (blue bumped 0\226\134\1465; cas_bai_sead PERIOD_CAS, game_loop cas 5/30)\n    patrol          = { period = 5    * MIN, blue = 5,   red = 35   },  -- :248 5min  off 5.0  (troop PERIOD_PATROL; game_loop patrol 5.0 / 5.0+30)\n    ground          = { period = 12   * MIN, blue = 12,  red = 372  },  -- :250 12min off 12.0 (ground GND_PERIOD; game_loop 12 / 12+floor(720/2)=372)\n    keysite_strike  = { period = 7.5  * MIN, blue = 15,  red = 240  },  -- :252 7.5min off 15.0 (attack_waves KEYSITE_STRIKE_PERIOD; 15 / 15+floor(450/2)=240)\n    artillery       = { period = 15   * MIN, blue = 45,  red = 75   },  -- :254 15min off 45.0 (cas_bai_sead PERIOD_ARTY; game_loop 45 / 45+30)\n    troop_insertion = { period = 2    * MIN, blue = 60,  red = 90   },  -- :256 2min  off 60.0 (troop PERIOD_TI; game_loop 60 / 60+30)\n    oca_sweep       = { period = 30   * MIN, blue = 90,  red = 120  },  -- :258 30min off 90.0 (cas_bai_sead PERIOD_OCA_SWEP; game_loop 90 / 90+30)\n    hc_transfer     = { period = 7.5  * MIN, blue = 120, red = 150  },  -- :260 7.5min off 120.0 (transfer PERIOD_HC; game_loop 120 / 120+30)\n    fw_transfer     = { period = 15   * MIN, blue = 150, red = 180  },  -- :262 15min off 150.0 (transfer PERIOD_FW; game_loop 150 / 150+30)\n    sead            = { period = 12   * MIN, blue = 180, red = 210  },  -- :264 12min off 180.0 (cas_bai_sead PERIOD_SEAD; game_loop 180 / 180+30)\n    bai             = { period = 20   * MIN, blue = 300, red = 330  },  -- :266 20min off 300.0 (cas_bai_sead PERIOD_BAI; game_loop 300 / 300+30)\n    oca_strike      = { period = 30   * MIN, blue = 390, red = 1290 },  -- :268 30min off 390.0 (attack_waves OCA_STRIKE_PERIOD; 390 / 390+floor(1800/2)=1290)\n}\n\n-- \226\148\128\226\148\128 SKIRMISH cadence (highlevl.c:218-242 GAME_TYPE_SKIRMISH branch) \226\128\148 faster periods \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Same stagger rule as CAMPAIGN above; each value cites its highlevl.c skirmish line + EECH start_time.\nlocal SKIRMISH = {\n    cas             = { period = 6    * MIN, blue = 5,   red = 30   },  -- :220 6min  off 0.0  (blue bumped 0\226\134\1465, red 30 \226\128\148 as campaign)\n    sead            = { period = 10   * MIN, blue = 2,   red = 32   },  -- :222 10min off 2.0  (red +30)\n    ground          = { period = 15   * MIN, blue = 12,  red = 462  },  -- :224 15min off 12.0 (red +floor(900/2)=462)\n    artillery       = { period = 12   * MIN, blue = 8,   red = 38   },  -- :226 12min off 8.0  (red +30)\n    keysite_strike  = { period = 10   * MIN, blue = 15,  red = 315  },  -- :228 10min off 15.0 (red +floor(600/2)=315)\n    patrol          = { period = 10   * MIN, blue = 5,   red = 35   },  -- :230 10min off 5.0  (red +30)\n    fw_transfer     = { period = 15   * MIN, blue = 34,  red = 64   },  -- :232 15min off 34.0 (red +30)\n    troop_insertion = { period = 2    * MIN, blue = 60,  red = 90   },  -- :234 2min  off 60.0 (red +30)\n    bai             = { period = 10   * MIN, blue = 90,  red = 120  },  -- :236 10min off 90.0 (red +30)\n    hc_transfer     = { period = 10   * MIN, blue = 180, red = 210  },  -- :238 10min off 180.0=3.0*ONE_MINUTE (red +30)\n    oca_sweep       = { period = 20   * MIN, blue = 240, red = 270  },  -- :240 20min off 240.0=4.0*ONE_MINUTE (red +30)\n    oca_strike      = { period = 30   * MIN, blue = 300, red = 1200 },  -- :242 30min off 300.0=5.0*ONE_MINUTE (red +floor(1800/2)=1200)\n}\n\n-- Defensive select: only \"skirmish\" switches away from campaign; anything else (typo, nil, non-string)\n-- falls back to CAMPAIGN. config.load_and_validate additionally sanitises + logs a bad user value.\nlocal mode = (type(config.C.mode) == \"string\") and string.lower(config.C.mode) or \"campaign\"\nif mode ~= \"skirmish\" then mode = \"campaign\" end\n\nM.mode     = mode\nM.CAMPAIGN = CAMPAIGN\nM.SKIRMISH = SKIRMISH\nM.SCHED    = (mode == \"skirmish\") and SKIRMISH or CAMPAIGN\n\nreturn M\n"
__modules["campaign_state"] = "-- campaign_state.lua\n-- Inspired by:\n--   aphavoc/source/entity/special/session/session.c   SESSION root entity: elapsed_time, start_time\n--   aphavoc/source/entity/special/session/ss_updt.c   session periodic update\n--   aphavoc/source/entity/special/force/force.h       FORCE per-side: kills, losses, hardware counts\n--   aphavoc/source/entity/special/force/fc_funcs.c    add/remove_from_force_info hardware registry\n--   aphavoc/source/ai/highlevl/imaps.c                normalise_importance_imaps balance-of-power\n--\n-- Singleton state table for the entire campaign session.\n-- All other modules require this and read/write M.S directly.\n-- Mirrors SESSION (root) + FORCE (per-side) entity data.\n\nlocal M = {}\n\n-- \226\148\128\226\148\128 Phase thresholds (DISPLAY-ONLY \226\128\148 no behavioural consumer) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH has NO explicit campaign phases; difficulty emerges from imap/threat state (Cluster F).\n-- These elapsed-time buckets USED to drive wave-escort escalation (attack_waves WAVE table) \226\128\148\n-- that invented consumer was removed in Cluster F (escorts are now threat-thresholded per EECH's\n-- escort_required model, assign.c:598-627). current_phase() now feeds ONLY the status log\n-- (game_loop.lua) and the pilot brief (pilots.lua); the fields are retained for that display and\n-- carry NO behavioural weight. Do NOT re-attach a behavioural consumer (EECH has no phases).\nM.PHASE_MID  = 15 * 60   -- 15 min \226\134\146 mid  (display label only)\nM.PHASE_LATE = 35 * 60   -- 35 min \226\134\146 late (display label only)\n\n-- \226\148\128\226\148\128 Keysite health thresholds \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors keysite.keysite_usable_state: USABLE / REPAIRING / UNUSABLE.\n-- HEALTH_NEUTRALISED is the OPERATIONAL floor for launching/regenerating from a base. In EECH this\n-- is EXACTLY the keysite USABLE-state line: a keysite with efficiency < minimum_efficiency is\n-- UNUSABLE (keysite.c:827-830) and can neither launch sorties nor regenerate \226\128\148 the same threshold\n-- capture/win tests use. It is therefore UNIFIED with MINIMUM_EFFICIENCY (0.3, ks_dbase.c). The\n-- previous 0.35 \"buffer\" had NO EECH source (tuned-by-feel) and was a latent divergence (03-F11) \226\128\148\n-- removed. Kept as a named alias so launch/regen call sites read \"neutralised floor\" rather than\n-- \"capture line\", but the value is the one EECH usable-state threshold.\nM.MINIMUM_EFFICIENCY = 0.3   -- eech ks_dbase.c minimum_efficiency (all keysite types); ks_float.c:285-291\nM.HEALTH_NEUTRALISED = M.MINIMUM_EFFICIENCY   -- unified with the EECH USABLE line (keysite.c:827-830)\nM.HEALTH_DESTROYED   = 0.0\n\n-- \226\148\128\226\148\128 Keysite minimum efficiency (EECH capture / usable-state line) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- M.MINIMUM_EFFICIENCY (0.3) is defined with the health thresholds above (unified with\n-- HEALTH_NEUTRALISED). Capture semantics: a keysite with efficiency < minimum is UNUSABLE (eech\n-- keysite.c:827-830) and is the ONLY state in which troop-insertion (capture) tasks are generated\n-- against it (eech highlevl.c:1732). All port keysites are equal-importance airbases.\n\n-- \226\148\128\226\148\128 Campaign objectives per side \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- eech ai/highlevl/setup.c:79  NUMBER_OF_CAMPAIGN_OBJECTIVES_PER_SIDE = 5\n-- Each side is assigned a fixed set of ENEMY keysites at OOB; the side wins when it OWNS all\n-- of them (all port keysites are troop_insertion_targets \226\134\146 \"must own\", eech fc_msgs.c:180-211).\nM.OBJECTIVES_PER_SIDE = 5\n\n-- \226\148\128\226\148\128 Force strength posture: DELIBERATELY ABSENT \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH has NO strength/attitude-gated \"survival mode\": FORCE.force_attitude is parsed\n-- (parsgen.c:1474) and stored (fc_creat.c:134 default NORMAL, fc_int.c:106/215) but read by ZERO AI\n-- code \226\128\148 highlevl.c never inspects force strength/attitude, so create_*_tasks generate offensive\n-- tasks regardless of how badly a side is losing (verified E:\\eech_source_code, empty grep of\n-- highlevl.c for force_percentage/FORCE_ATTITUDE). The old STRENGTH_SURVIVAL(40)/STRENGTH_DEFEAT(5)\n-- constants gated strike/TI/ground/heli generation and a bogus 4th win criterion \226\128\148 all invented,\n-- all removed in Cluster E. Do NOT reintroduce a posture threshold.\n\n-- \226\148\128\226\148\128 Keysite attrition: structural death ONLY (no generic kill-proximity bleed) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH keysite_strength changes ONLY when the keysite's own buildings/structures die (keysite.c:854\n-- notify_keysite_structure_under_attack + the destroy path), NOT from nearby unit kills. The port's\n-- old generic KILL_RADIUS/KILL_DMG channel (a base bled structure from every air-to-air kill within\n-- 8 km) was an INVENTION that double-dipped with the deterministic strike_damage / registered-static-\n-- death channels \226\128\148 removed in Cluster G (B4 note). Airbase attrition now comes exclusively from\n-- keysite.strike_damage (deterministic per-sortie strike) and registered-asset death; installation\n-- attrition from installations.damage + register_static_death.\n\n-- \226\148\128\226\148\128 Session state (S) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors SESSION.elapsed_time, SESSION.start_time (session.c)\n-- and per-side FORCE.strength, kills, losses (force.h)\n\n-- Generation counter: incremented on each fresh injection so old timer closures\n-- can detect they belong to a superseded campaign and self-cancel (return nil).\n_DMT_GEN = (_DMT_GEN or 0) + 1\nM.GENERATION = _DMT_GEN\n\n-- \226\148\128\226\148\128 Debug logging channel \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Toggleable STRUCTURED logging for tracing campaign LOGIC (not just headline events) \226\128\148 decisions,\n-- funnels, task lifecycle, spawn success/failure, state transitions. Every module calls\n--   cs.dbg(\"<tag>\", \"fmt\", ...)   \226\134\146 env.info(\"[dmt:<tag>] ...\")\n-- Gate with the _DMT_DEBUG global so a production run can silence the firehose without touching call\n-- sites:  net.dostring_in('server','_DMT_DEBUG=false')  (or =true to re-enable). Defaults ON (dev\n-- campaign). A pcall guards format errors so a malformed dbg() call can never abort a scheduler tick.\n-- Tags mirror the module/subsystem: cas, bai, sead, board, heli, strike, oca, troop, recon, regen,\n-- reaction, ground, supply, keysite, capture, imap, fow, transfer, win, econ, spawn, loop.\nif _DMT_DEBUG == nil then _DMT_DEBUG = true end\nfunction M.dbg(tag, fmt, ...)\n    if not _DMT_DEBUG then return end\n    local ok, s = pcall(string.format, fmt, ...)\n    env.info(\"[dmt:\" .. tostring(tag) .. \"] \" .. (ok and s or (\"FMT-ERR \" .. tostring(fmt))))\nend\n\nM.S = {\n    start_time = 0,      -- timer.getTime() at campaign start (mirrors SESSION.start_time)\n    phase      = \"early\",\n    game_over  = false,\n    winner     = nil,\n\n    -- mirrors KEYSITE.side, KEYSITE.keysite_strength, KEYSITE.position (keysite.h)\n    base_health = {},    -- [name] = 0.0\226\128\1471.0\n    base_owner  = {},    -- [name] = coalition.side.*\n    base_pos    = {},    -- [name] = { x=north, z=east }\n\n    -- mirrors FLOAT_TYPE_EFFICIENCY per keysite (eech ks_float.c:260-275):\n    --   efficiency = keysite_strength / keysite_maximum_strength   (building-strength model)\n    -- Supply (ammo/fuel) is DELIBERATELY EXCLUDED \226\128\148 EECH efficiency is purely the sum of live\n    -- building importance over the max (KEYSITE-F3). In the port base_health IS strength/max\n    -- (starts 1.0, decremented by structural kill damage), so efficiency == base_health.\n    -- Updated every KEYSITE_UPDATE_SLEEP_TIMER (60 s) by keysite_repair.lua.\n    -- Used by T.I. scoring, capture roll, recon reaction chain, and transfer scoring.\n    base_efficiency = {},   -- [name] = 0.0\226\128\1471.0\n\n    -- Per-side campaign objective keysites (eech force campaign_objective_root; setup.c:126-289).\n    -- [side] = { enemy_base_name, ... } \226\128\148 the ENEMY keysites this side must capture to win.\n    objectives = {},\n\n    -- mirrors FORCE.relative_strength (fc_updt.c balance-of-power formula)\n    strength = {\n        [coalition.side.BLUE] = 100,\n        [coalition.side.RED]  = 100,\n    },\n\n    -- Standing frontline: a registry of ground groups per side (mirrors EECH ground registry /\n    -- armoured divisions \226\128\148 NOT a single column). ground_forces.lua populates this at OOB.\n    -- [side] = { [gname] = { grp, target_base, home_base, want } }\n    ground_groups = {\n        [coalition.side.BLUE] = {},\n        [coalition.side.RED]  = {},\n    },\n\n    -- Standing SELF-PROPELLED ARTILLERY groups per side (mirrors EECH FRONTLINE_FORCE_ARTILLERY\n    -- placement, faction.c:1602-1661 \226\128\148 SP artillery / MLRS groups at artillery nodes supporting the\n    -- frontline). Kept SEPARATE from ground_groups so advance_retreat never drives batteries into\n    -- contact (EECH artillery holds and fires at range). ground_forces.lua populates this at OOB;\n    -- cas_bai_sead.run_artillery finds own shooters (attribute or \"Arty-\" name) and enemy batteries\n    -- (this registry) as counter-fire targets.  [side] = { [gname] = { grp, home_base } }\n    arty_groups = {\n        [coalition.side.BLUE] = {},\n        [coalition.side.RED]  = {},\n    },\n\n    -- COUNTER-BATTERY dedup markers (Cluster F / REACT-F13). map firing-battery group_name \226\134\146 expiry\n    -- time; the victim side does not raise a 2nd BAI/RECON against a battery already object of one\n    -- (mirrors EECH entity_is_object_of_task(group, BAI/RECON) gate, reaction.c:740-744). On S so it\n    -- survives across ticks; lazy-init in reaction.lua.\n    counter_battery = {},\n\n    -- PER-BASE IDLE INVENTORY LEDGER (Cluster 4 \226\128\148 task-board assignment source).\n    -- Replaces the old single per-SIDE reserve pool. DCS cannot keep hundreds of parked AI\n    -- aircraft alive (parking/perf), so idle aircraft are a per-base LEDGER (counts by role at\n    -- each OWNED base) \226\128\148 a documented proxy for EECH's live aircraft parked at keysites\n    -- (force.h:95 force_info_reserve_hardware, but localised to keysites as the task engine's\n    -- resident-group source, assign.c LIST_TYPE_KEYSITE_GROUP). Seeded from RESERVE_PER_BASE at\n    -- OOB, DECREMENTED on assignment/spawn from the CHOSEN base, re-credited on RTB to the\n    -- LANDING base, by production to a producer base, and by regen. The per-SIDE reserve is now\n    -- the SUM of base ledgers (supply.reserve_side); consume_side/recycle_side pick a base.\n    -- [baseName] = { striker=N, escort=N, heli=N, recon=N, transport=N, vehicle=N }\n    base_ledger = {},\n\n    -- LANDING-SLOT / BASING-CAPACITY ARBITRATION (Cluster 5). EECH throttles sortie tempo per\n    -- keysite through LANDING entities holding slot counts (reserved/free/total landing sites;\n    -- landing.h:102-105) \226\128\148 availability = free - reserved (eech keysite.c:324; spec 07 TASK-F23).\n    -- Port proxy (per-SORTIE, not per-airframe): base_inflight[base] = number of sorties currently\n    -- airborne that LAUNCHED from `base`; a base at slot capacity (keysite.base_slot_capacity)\n    -- is skipped by the assignment gate. group_launch_base[gname] = the launch base of an in-flight\n    -- sortie, so its slot is released on RTB-land / death. See keysite.lua (slot API) + task_board.\n    -- [baseName] = integer sorties in flight;  [group_name] = launch base name.\n    base_inflight     = {},\n    group_launch_base = {},\n\n    -- mirrors force_info_current_hardware[side][catagory]: count of live fielded units.\n    -- Computed as a live census from coalition.getGroups each recalc_strength (DCS can\n    -- enumerate cheaply, so we census rather than maintain a drift-prone ++/-- tally).\n    -- WRITE-ONLY DIAGNOSTIC (B3): recalc_strength derives S.strength from the census inline and does\n    -- not read force_current back; it is KEPT intentionally as a cheap per-side hardware snapshot for\n    -- logging / a future status surface. Harmless. [side] = total alive mobile-unit count\n    force_current = {},\n\n    -- mirrors GROUP_MODE_IDLE group count per keysite (transfer scoring proxy).\n    -- Updated each transfer tick by counting alive groups near each base.\n    -- [baseName] = integer count of alive DCS groups within 5 km\n    base_idle_groups = {},\n\n    -- mirrors task entity tracking: which group was assigned what task, targeting where.\n    -- Populated on group BIRTH by reaction.lua; consumed on group death.\n    -- [group_name] = { task_type=\"Strike\"|\"OCA-Sweep\"|\"Recon\"|\"BDA\", side=N,\n    --                  target_base=name_or_nil, born_time=t }\n    active_tasks = {},\n\n    -- TASK BOARD (Cluster 4): the UNASSIGNED-task queue that the assignment engine drains.\n    -- Mirrors keysite LIST_TYPE_UNASSIGNED_TASK (task.c:561-589) + task_state machine (en_task.h:83).\n    -- Each generator create_task(...)s a record here; task_board.tick() matches idle base inventory\n    -- to it (assign.c) and physically spawns; records past their unassigned-expiry become FAILED\n    -- (ts_updt.c:99-124) \226\128\148 the task-failure path the fresh-spawn port never had. Records: see\n    -- task_board.lua. board_failed counts EXPIRE_TIME_REACHED failures for observability.\n    board_tasks  = {},\n    board_failed = 0,\n\n    -- \226\148\128\226\148\128 DORMANT-FARP ACTIVATION (Item 1 \226\128\148 eech keysite.c:507-568 initialise_keysite_farp_enable) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- EECH FARP keysites are created in_use=FALSE (ks_creat.c:157) and only ACTIVATE (in_use=TRUE,\n    -- usable) when their SECTOR's side == the FARP's force side (keysite.c:541-547) \226\128\148 i.e. as the front\n    -- reaches them. A not-in_use keysite is excluded from nearest-keysite search (keysite.c:369), the\n    -- win-check usable-airbase census (fc_msgs.c:234 requires ALIVE && IN_USE), imap and supply. Port\n    -- proxy on bases-as-sectors: a FARP activates when the nearest NON-FARP base to it is friendly.\n    -- [farpName] = true once activated (latch \226\128\148 EECH only clears in_use on destroy, ks_dstry.c:325).\n    -- Non-FARP bases are ALWAYS active (cs.base_is_active); this table only tracks FARPs.\n    farp_active = {},\n\n    -- \226\148\128\226\148\128 PER-SIDE + PER-TASK STATS (Item 2 \226\128\148 eech force.h:98-99 kills[]/losses[] per FORCE) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- EECH FORCE carries kills[NUM_ENTITY_SUB_TYPE_GROUPS] and losses[NUM_ENTITY_SUB_TYPE_GROUPS],\n    -- indexed by the victim's group sub_type (a category), incremented on kill/death\n    -- (force.c:307-361 add_mobile_to_force_kills_stats / _losses_stats: kill \226\134\146 killer force, indexed by\n    -- victim category; loss \226\134\146 victim force). Port buckets by DCS unit category (air/heli/ground/ship/\n    -- structure) as the sub_type proxy. tasks_created/completed/partial/failed mirror the task-board\n    -- lifecycle + the per-task completion assessment (task.c). sorties counts registered missions flown.\n    -- [side] = { kills={cat->n}, losses={cat->n}, sorties, tasks_created, tasks_completed, tasks_partial, tasks_failed }\n    stats = {\n        [coalition.side.BLUE] = { kills = {}, losses = {}, sorties = 0,\n                                  tasks_created = 0, tasks_completed = 0, tasks_partial = 0, tasks_failed = 0 },\n        [coalition.side.RED]  = { kills = {}, losses = {}, sorties = 0,\n                                  tasks_created = 0, tasks_completed = 0, tasks_partial = 0, tasks_failed = 0 },\n    },\n\n    -- TROOP-INSERTION RESOLVED MARKERS (Cluster C): map group_name \226\134\146 true once an insertion's\n    -- capture roll has RESOLVED (won or lost). EECH's TROOP_CAPTURE waypoint event fires once per\n    -- task (mb_msgs.c:2260); a repelled heli loitering at its final waypoint must not re-roll every\n    -- tick. On S (persistence surface, gap B3).\n    pending_captures = {},\n\n    -- IMAP INFLUENCE-MAP LAYER STORE (Wave 1 \226\128\148 moved onto S for the persistence surface, GOAL P2).\n    -- imap.lua previously held these as module-local tables reachable only via imap.get(); they now\n    -- live on S so the whole influence-map state is enumerable/serialisable with the rest of the\n    -- campaign. imap.lua keeps module-local imap_raw/imap_nrm as REFERENCES into these sub-tables \226\128\148 the\n    -- get()/update API and every consumer are unchanged. Rebuilt per inject by imap.init() (S itself is\n    -- fresh each inject, so this starts empty and is repopulated exactly as before).\n    --   raw[layer][side][base_name] = float (unnormalised);  nrm[layer][side][base_name] = 0.0\226\128\1471.0\n    imap = { raw = {}, nrm = {} },\n}\n\nM.SIDE_NAME = { [coalition.side.BLUE] = \"BLUE\", [coalition.side.RED] = \"RED\" }\nM.ENEMY     = { [coalition.side.BLUE] = coalition.side.RED,\n                [coalition.side.RED]  = coalition.side.BLUE }\n\n-- \226\148\128\226\148\128 Sequence IDs \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Starts at 2000 to avoid collision with main.lua's counter (which starts at 0)\n\nlocal _seq = 2000\nfunction M.next_id()\n    _seq = _seq + 1\n    return _seq\nend\n\n-- \226\148\128\226\148\128 Task registry \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors the EECH task entity list: each spawned mission registers itself here at spawn\n-- time so the reactive AI (reaction.lua) knows the EXACT objective (target keysite/group),\n-- rather than guessing from spawn position. Also drives \"task completed\" follow-ons.\n-- info = { task_type, side (attacker), target_base, target_pos, objective = {kind, base}, born_time }\nfunction M.register_task(gname, info)\n    M.S.active_tasks = M.S.active_tasks or {}\n    M.S.active_tasks[gname] = info\n    -- Sortie counter (Item 2): a registered mission == a flown sortie for its side (force.h stats).\n    if info and info.side ~= nil then M.stat_sortie(info.side) end\nend\n\nfunction M.get_task(gname)\n    return M.S.active_tasks and M.S.active_tasks[gname]\nend\n\n-- Task-end hook (Item 4): map_overlay registers M.task_end_hook = remove_task_arrow so cs.clear_task \226\128\148\n-- the SINGLE chokepoint every task-end path funnels through (reaction LAND/DEAD, troop capture,\n-- keysite capture-termination, supply RTB) \226\128\148 reliably reaps the task's map arrow. campaign_state stays\n-- dependency-root: map_overlay depends on us, so we call OUT via this slot rather than requiring it.\nM.task_end_hook = nil\n\nfunction M.clear_task(gname)\n    if M.S.active_tasks then M.S.active_tasks[gname] = nil end\n    if M.task_end_hook then pcall(M.task_end_hook, gname) end\nend\n\n-- entity_is_object_of_task proxy: is there an active task of `task_type` against `target_base`\n-- for `side`? Used for the EECH dedup guards (don't create a 2nd OCA/TI/strike on one objective).\nfunction M.has_task_against(task_type, target_base, side)\n    if not M.S.active_tasks then return false end\n    for _, t in pairs(M.S.active_tasks) do\n        if t.task_type == task_type and t.target_base == target_base and t.side == side then\n            return true\n        end\n    end\n    return false\nend\n\n-- \226\148\128\226\148\128 Phase \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors SESSION.elapsed_time driving task scheduler behaviour\n\nfunction M.current_phase()\n    local t = timer.getTime() - M.S.start_time\n    if     t >= M.PHASE_LATE then return \"late\"\n    elseif t >= M.PHASE_MID  then return \"mid\"\n    else                           return \"early\" end\nend\n\n-- \226\148\128\226\148\128 Current-hardware census \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors force_info_current_hardware: count of live fielded mobile units for a side.\n-- EECH maintains a ++/-- tally; we enumerate live units directly (DCS lets us, so the\n-- count can never drift). Sums aircraft + helicopters + ground vehicles/infantry \226\128\148\n-- the same union of categories fc_updt.c:148-161 sums over (FLOAT_TYPE_FORCE_PERCENTAGE):\n--   for loop = ARMED_FIXED_WING .. NUM_FORCE_INFO_CATAGORIES: this_force += current_hardware[loop].\n-- Static buildings/keysites are NOT force_info hardware in EECH, so we skip them.\n--\n-- HUMANS IN THE CENSUS (goal-03 P1): the player's gunship is a member of a force group, so EECH's\n-- census walks it like any other member \226\128\148 fc_updt.c:148-161 has NO player exclusion (verified: the\n-- sum is over force_info_current_hardware categories, populated by add/remove_from_force_info for\n-- every group member regardless of AI/human). The port matches by counting via coalition.getGroups,\n-- which INCLUDES client/player groups once slotted \226\128\148 so player gunships already count toward force\n-- strength here, exactly as EECH intends. This census is strictly READ-ONLY: it never destroys,\n-- recycles, or regenerates a unit (those paths \226\128\148 regen.make_dead_handler, supply.make_land_handler \226\128\148\n-- carry their own explicit getPlayerName guards), so counting players is guardrail-safe.\nfunction M.count_current_hardware(side)\n    local n = 0\n    local grps = coalition.getGroups(side)\n    if grps then\n        for _, grp in ipairs(grps) do\n            if grp and grp.isExist and grp:isExist() then\n                local units = grp:getUnits()\n                if units then\n                    for _, u in ipairs(units) do\n                        if u and u:isExist() and u:getLife() > 1.0 then n = n + 1 end\n                    end\n                end\n            end\n        end\n    end\n    return n\nend\n\n-- \226\148\128\226\148\128 Strength recalculation \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors fc_updt.c:140-161 balance-of-power exactly:\n--   force_percentage[side] = this_force / total_forces\n--     this_force   = \206\163 current_hardware[side]  over all categories\n--     total_forces = \206\163 current_hardware[side] + current_hardware[enemy]\n-- Stored as an integer 0..100 (EECH campaign_criteria count = force_percentage*100).\n-- Territory (base ownership) and keysite efficiency are SEPARATE campaign criteria,\n-- evaluated in win_condition.lua \226\128\148 NOT folded into strength (matches EECH criteria split).\nfunction M.recalc_strength()\n    local cur = {}\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        cur[side] = M.count_current_hardware(side)\n        M.S.force_current[side] = cur[side]\n    end\n\n    local total = cur[coalition.side.BLUE] + cur[coalition.side.RED]\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        if total > 0 then\n            M.S.strength[side] = math.floor(cur[side] / total * 100 + 0.5)\n        else\n            M.S.strength[side] = 50   -- no units fielded on either side \226\134\146 even\n        end\n    end\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- DORMANT-FARP ACTIVATION GATE (Item 1 \226\128\148 eech keysite.c:507-568 / in_use participation)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- base_is_active(name): does the base PARTICIPATE in the campaign (== EECH keysite in_use)? Non-FARP\n-- bases (airbase/fob) are always in_use. A FARP is in_use only once activated (S.farp_active), which\n-- farps.update latches when its sector becomes friendly (the eech keysite.c:541 sector-side gate).\n-- Consulted by the launch-candidate gate (task_board.owned_bases, \226\137\136 nearest-keysite search\n-- keysite.c:369) and the win usable-airbase census (win_condition, \226\137\136 fc_msgs.c:234 ALIVE && IN_USE).\nfunction M.base_is_active(name)\n    if M.S.base_kind and M.S.base_kind[name] == \"farp\" then\n        return M.S.farp_active[name] == true\n    end\n    return true   -- airbases / FOBs always participate (only FARPs are gated by in_use)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- PER-SIDE + PER-TASK STATS (Item 2 \226\128\148 eech force.h:98-99 kills[]/losses[]; force.c:307-361)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\nM.STAT_CATEGORIES = { \"air\", \"heli\", \"ground\", \"ship\", \"structure\", \"other\" }\n\n-- Bucket a DCS object into a stats category (proxy for EECH group sub_type). pcall-guarded \226\128\148 a kill\n-- event target may be a Unit, a StaticObject (structure) or an already-cleaned handle.\nfunction M.unit_category(obj)\n    if not obj then return \"other\" end\n    -- Prefer the group category for live units (airplane / helicopter / ground / ship).\n    local okg, grp = pcall(function() return obj.getGroup and obj:getGroup() end)\n    if okg and grp then\n        local okc, gc = pcall(function() return grp:getCategory() end)\n        if okc then\n            if     gc == Group.Category.AIRPLANE   then return \"air\"\n            elseif gc == Group.Category.HELICOPTER then return \"heli\"\n            elseif gc == Group.Category.GROUND     then return \"ground\"\n            elseif gc == Group.Category.SHIP       then return \"ship\" end\n        end\n    end\n    -- No group (static/scenery) \226\134\146 attributes, then STATIC category, then \"structure\"/\"other\".\n    local okd, desc = pcall(function() return obj.getDesc and obj:getDesc() end)\n    if okd and type(desc) == \"table\" and type(desc.attributes) == \"table\" then\n        local a = desc.attributes\n        if     a[\"Helicopters\"] then return \"heli\"\n        elseif a[\"Air\"] or a[\"Planes\"] then return \"air\"\n        elseif a[\"Ships\"] then return \"ship\"\n        elseif a[\"Ground Units\"] or a[\"Vehicles\"] then return \"ground\"\n        elseif a[\"Buildings\"] or a[\"Fortifications\"] then return \"structure\" end\n    end\n    local okoc, ocat = pcall(function() return obj.getCategory and obj:getCategory() end)\n    if okoc and Object and Object.Category and ocat == Object.Category.STATIC then return \"structure\" end\n    return \"other\"\nend\n\n-- kill \226\134\146 killer force's kills[victim_category]++, victim force's losses[victim_category]++\n-- (force.c:307-331 credits the killer force indexed by the victim's category; :337-361 the loss).\nfunction M.stat_kill(killer_side, victim_side, category)\n    category = category or \"other\"\n    local st = M.S.stats\n    if killer_side and st[killer_side] then\n        st[killer_side].kills[category] = (st[killer_side].kills[category] or 0) + 1\n    end\n    if victim_side and st[victim_side] then\n        st[victim_side].losses[category] = (st[victim_side].losses[category] or 0) + 1\n    end\nend\n\nfunction M.stat_sortie(side)\n    local st = M.S.stats and M.S.stats[side]\n    if st then st.sorties = (st.sorties or 0) + 1 end\nend\n\nfunction M.stat_task_created(side)\n    local st = M.S.stats and M.S.stats[side]\n    if st then st.tasks_created = (st.tasks_created or 0) + 1 end\nend\n\n-- result \226\136\136 \"success\" | \"partial\" | \"failure\" \226\128\148 the three EECH task_completed outcomes (task.c:496-501).\nfunction M.stat_task_result(side, result)\n    local st = M.S.stats and M.S.stats[side]\n    if not st then return end\n    if     result == \"failure\" then st.tasks_failed    = (st.tasks_failed    or 0) + 1\n    elseif result == \"partial\" then st.tasks_partial   = (st.tasks_partial   or 0) + 1\n    elseif result == \"success\" then st.tasks_completed = (st.tasks_completed or 0) + 1 end\nend\n\nlocal function _stat_total(t) local n = 0; for _, v in pairs(t) do n = n + v end; return n end\n\n-- One-line summary for the 2-min STATUS log (game_loop).\nfunction M.stats_summary_line()\n    local st = M.S.stats\n    local b, r = st[coalition.side.BLUE], st[coalition.side.RED]\n    return string.format(\"STATS kills B=%d R=%d | losses B=%d R=%d | tasks(ok/part/fail) B=%d/%d/%d R=%d/%d/%d | sorties B=%d R=%d\",\n        _stat_total(b.kills), _stat_total(r.kills), _stat_total(b.losses), _stat_total(r.losses),\n        b.tasks_completed, b.tasks_partial, b.tasks_failed,\n        r.tasks_completed, r.tasks_partial, r.tasks_failed, b.sorties, r.sorties)\nend\n\n-- Multi-line per-side breakdown for the F-10 \"Campaign Stats\" menu entry (display text).\nfunction M.stats_text()\n    local st = M.S.stats\n    local function bycat(t)\n        local parts = {}\n        for _, c in ipairs(M.STAT_CATEGORIES) do\n            if (t[c] or 0) > 0 then parts[#parts + 1] = c .. \":\" .. t[c] end\n        end\n        return (#parts > 0) and table.concat(parts, \" \") or \"none\"\n    end\n    local function block(side)\n        local s = st[side]\n        return string.format(\"%s\\n  kills %d (%s)\\n  losses %d (%s)\\n  sorties %d\\n  tasks: created %d, done %d, partial %d, failed %d\",\n            M.SIDE_NAME[side], _stat_total(s.kills), bycat(s.kills), _stat_total(s.losses), bycat(s.losses),\n            s.sorties, s.tasks_created, s.tasks_completed, s.tasks_partial, s.tasks_failed)\n    end\n    return \"=== CAMPAIGN STATS ===\\n\" .. block(coalition.side.BLUE) .. \"\\n\" .. block(coalition.side.RED)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- TASK COMPLETION ASSESSMENT (Item 3 \226\128\148 eech task.c:110-502 get task_completed rating)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Faithful port of the per-task-type completion rating (task.c switch, :150-490). `terminated`:\n--   \"route_complete\" \226\128\148 the mission ended cleanly (RTB/landed) == EECH TASK_TERMINATED_WAYPOINT_ROUTE_\n--                      COMPLETE / OBJECTIVE_MESSAGE / STOP_TIME_REACHED (a successful terminator).\n--   \"terminated\"     \226\128\148 the group was destroyed before completing == a failure terminator.\n-- Returns (result, rating): result \226\136\136 \"success\"|\"partial\"|\"failure\", rating 0..1 (task.c FLOAT_TYPE_RATING).\n-- NOTE ON THRESHOLDS: EECH reads task_pass_percentage_success/partial from task_database (task.c:138-140),\n-- which is WUT WARZONE DATA, not a constant in the C tree \226\128\148 so no citable engine default exists. For the\n-- efficiency-based GROUND_STRIKE rating we use documented proxy thresholds (SUCCESS 0.25 / PARTIAL 0.10):\n-- the port's per-sortie keysite damage is deterministic (attack_waves KEYSITE_STRIKE_DMG), so a single\n-- arriving strike drops efficiency by ~that fraction \226\128\148 success when a meaningful chunk fell. Every other\n-- registered port task type follows the EECH structural rule (route-complete \226\134\146 success, else failure)\n-- which needs no threshold. A strike arriving after the base was already captured/repaired scores by the\n-- SAME rule (unusable/below-min \226\134\146 success rating 1.0; no further drop \226\134\146 failure) \226\128\148 faithful, not trivial.\nfunction M.assess_task(task, terminated)\n    local ttype       = task and task.task_type\n    local success_end = (terminated == \"route_complete\")\n    if ttype == \"ground_strike\" then\n        -- eech ENTITY_SUB_TYPE_TASK_GROUND_STRIKE (task.c:347-427): efficiency before/after vs 0.8*min.\n        local base    = task.target_base\n        local min_eff = M.MINIMUM_EFFICIENCY * 0.8   -- task.c:364 (stop repairing-one-structure gaming)\n        -- efficiency source of truth: airbase \226\134\146 base_health; installation \226\134\146 keysites[name].health.\n        local eff_after = base and (M.S.base_health[base]\n            or (M.S.keysites and M.S.keysites[base] and M.S.keysites[base].health) or 1.0) or 1.0\n        if base and ((not M.base_is_active(base)) or eff_after < min_eff) then\n            return \"success\", 1.0                     -- task.c:366-377 not-in-use / below-min \226\134\146 success\n        end\n        local rating = (task.eff_before or 1.0) - eff_after   -- task.c:384\n        if rating < 0 then rating = 0 elseif rating > 1 then rating = 1 end\n        local SUCCESS_THR, PARTIAL_THR = 0.25, 0.10   -- documented proxies (task_pass_percentage is WUT data)\n        if     rating >= SUCCESS_THR then return \"success\", rating   -- task.c:388-391\n        elseif rating >= PARTIAL_THR then return \"partial\", rating   -- task.c:392-395\n        elseif success_end            then return \"partial\", rating   -- task.c:410-416 route-complete \226\134\146 partial\n        else                               return \"failure\", rating end -- task.c:418-424\n    elseif ttype == \"recon\" or ttype == \"bda\" then\n        -- eech BDA/RECON (task.c:432-456): success iff the objective message fired (target reached).\n        if success_end then return \"success\", 1.0 else return \"failure\", 0.0 end\n    else\n        -- oca_strike / oca_sweep / troop_patrol / cap / barcap / transfer / troop_insertion etc.\n        -- (task.c:153-204 route/stop-time group + :461-472 route-complete group): success on a clean\n        -- mission end, failure if terminated early.\n        if success_end then return \"success\", 1.0 else return \"failure\", 0.0 end\n    end\nend\n\n-- \226\148\128\226\148\128 Shared math helpers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n-- DCS world: x=north, z=east.  Waypoint/unit position: x=north, y=east.\nfunction M.wp_xy(world_pos)\n    return world_pos.x, world_pos.z\nend\n\nfunction M.dist2d(ax, az, bx, bz)\n    local dx, dz = ax - bx, az - bz\n    return math.sqrt(dx * dx + dz * dz)\nend\n\n-- Heading in radians toward (bx,bz) from (ax,az)\nfunction M.heading_to(ax, az, bx, bz)\n    return math.atan2(bz - az, bx - ax)\nend\n\nfunction M.group_is_alive(g)\n    if not g then return false end\n    if not g:isExist() then return false end\n    local units = g:getUnits()\n    if not units then return false end\n    for _, u in ipairs(units) do\n        if u and u:isExist() then return true end\n    end\n    return false\nend\n\n-- \226\148\128\226\148\128 Land-snap: keep COMPUTED ground/static placements out of the water \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- DCS coastal keysites (Batumi!) drop ring / scatter / rear-offset positions into the sea, where\n-- ground units and statics fail to spawn or strand on the shoreline. snap_land nudges a computed\n-- placement point to the nearest LAND before it feeds addGroup / addStaticObject / a ground route.\n-- NOT an EECH port: EECH keysites are authored terrain 3D-object clusters (popread.c) so its placement\n-- never lands in water \226\128\148 this is a DCS-side placement-safety proxy with no EECH constant to cite.\n-- Applied ONLY to COMPUTED ground/static offsets (rings, scatter, rear standoffs, template grids),\n-- NEVER to authored zone/base centres, aircraft parking, or air routes.\n--\n-- CONTRACT (analyzer-safe by construction \226\128\148 the historical snap failure was the static analyzer, which\n-- does NOT narrow multiple returns / and-or guards): PURE, deterministic, bounded. ALWAYS returns a\n-- TABLE {x=,z=} \226\128\148 never nil, never a bare return \226\128\148 so callers read .x/.z with zero nil-narrowing\n-- (single-value-per-variable style throughout). Every land.* touch is pcall-guarded. Bearings are\n-- DETERMINISTIC (no random). Bounded: 5 radii x 8 bearings = 40 probes maximum, then fallback.\n-- DCS land.getSurfaceType enum: LAND=1, SHALLOW_WATER=2, WATER=3, ROAD=4, RUNWAY=5 \226\128\148 LAND/ROAD/RUNWAY\n-- are placeable; the two water types are not.\nlocal SNAP_RADII = { 200, 500, 1000, 2000, 4000 }   -- spiral search radii (m), inner \226\134\146 outer\n\n-- pcall-guarded surface probe \226\134\146 a numeric SurfaceType, or nil if the land API threw / is unavailable.\nlocal function surface_at(x, z)\n    local ok, st = pcall(land.getSurfaceType, { x = x, y = z })\n    if ok and type(st) == \"number\" then return st end\n    return nil\nend\n\n-- A placeable (dry) surface: LAND(1) / ROAD(4) / RUNWAY(5). Water(2/3), and a nil probe, are NOT dry.\nlocal function is_dry(st)\n    return st == 1 or st == 4 or st == 5\nend\n\n-- snap_land(x, z, fx, fz) \226\134\146 { x = SAFE, z = SAFE }, guaranteed non-nil.\n--   dry at (x,z)                 \226\134\146 returned as-is (NO log \226\128\148 the common land case, avoid spam).\n--   water/shallow at (x,z)       \226\134\146 spiral search (SNAP_RADII x 8 deterministic 45\194\176 bearings); the\n--                                  FIRST dry candidate wins (inner radii first \226\134\146 smallest nudge).\n--   nothing dry found / API dead \226\134\146 fallback (fx,fz): the keysite / base centre the caller passes\n--                                  (airbases are always land; authored zone centres assumed on land).\n--                                  Returned even if the fallback is itself wet (never loops forever) \226\128\148\n--                                  a warning is logged so a genuinely bad authored centre is visible.\n-- Exactly ONE dbg line is emitted, and only when a point actually MOVED (spiral hit) or no land was\n-- found \226\128\148 the common as-is case is silent.\nfunction M.snap_land(x, z, fx, fz)\n    local bx, bz = fx or x, fz or z            -- fallback defaults to the input point when not supplied\n    local st = surface_at(x, z)\n    if is_dry(st) then return { x = x, z = z } end   -- already on land \226\128\148 return as-is, no log\n    for ri = 1, #SNAP_RADII do\n        local r = SNAP_RADII[ri]\n        for b = 0, 7 do\n            local ang = b * (math.pi / 4)      -- deterministic 45\194\176 steps (8 bearings, fixed order)\n            local px = x + math.cos(ang) * r\n            local pz = z + math.sin(ang) * r\n            if is_dry(surface_at(px, pz)) then\n                M.dbg(\"snap\", \"moved (%.0f,%.0f) surf=%s -> land (%.0f,%.0f) r=%dm\",\n                    x, z, tostring(st), px, pz, r)\n                return { x = px, z = pz }\n            end\n        end\n    end\n    M.dbg(\"snap\", \"NO land within %dm of (%.0f,%.0f) surf=%s -> fallback (%.0f,%.0f)\",\n        SNAP_RADII[#SNAP_RADII], x, z, tostring(st), bx, bz)\n    return { x = bx, z = bz }\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- ESCORT MODEL \226\128\148 threat-based, mirroring EECH escort_required (Cluster F)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- On task assignment EECH assesses route difficulty and creates an escort iff\n--   difficulty >= task_database[type].escort_required_threshold           (assign.c:598-627)\n-- with a CRITICAL escort at difficulty >= ESCORT_CRITICAL (ts_dbase.h:156).\n-- Route difficulty (assess_task_difficulty \226\134\146 assess_task_sector_difficulty, task.c:880-909):\n--   walk the leg's sectors; +1 air_threat per sector with enemy S-A defence,\n--   +1 enemy_sector per sector not owned by `side`; then\n--   difficulty = min(air_threats >> 1, 5) + min(enemy_sectors >> 1, 5).\n-- Port proxy: bases are the sector grid. Sample the launch\226\134\146target leg; each sample's NEAREST base\n-- is its sector. air_threat if IMAP_AIR_DEFENCE[side] (= enemy AA coverage) > 0 there; enemy_sector\n-- if the base is not owned by `side`. The C's >>1 halving is NOT applied (coarse-grid calibration\n-- \226\128\148 see the note inside route_difficulty); the caps of 5 are kept.\nM.ESCORT_CRITICAL = 6   -- ts_dbase.h:156 (#define ESCORT_CRITICAL 6)\n\n-- Per-task escort thresholds. NOTE: the shipped ts_dbase.c defaults are ALL ESCORT_NEVER (=15,\n-- ts_dbase.h:154) \226\128\148 the operative per-type thresholds are WARZONE DATA (parsed by\n-- wutcfg.c:1590 escort_required_threshold; assign.c reads task_database[type].escort_required_threshold).\n-- No C constant exists, so these are the researched warzone values (gap analysis 07-F15): a strike\n-- (ground/OCA) and troop-insertion escort at difficulty >= 3, SEAD at >= 5. Absent from this table =\n-- ESCORT_NEVER (CAS/BAI are rotary attack-heli sections, never fixed-wing-escorted). Designer data.\nM.ESCORT_THRESHOLD = {\n    ground_strike   = 3,\n    oca_strike      = 3,\n    sead            = 5,\n    troop_insertion = 3,\n    supply          = 6,   -- ts_dbase.c:1406 TASK_SUPPLY Escort Required Threshold = 6 (== ESCORT_CRITICAL).\n                           -- In practice INERT: supply routes run over own REAR area (launch\226\134\146producer\226\134\146\n                           -- consumer are all friendly keysites), so route_difficulty \226\137\136 0 << 6 and no\n                           -- escort is created \226\128\148 faithful to EECH, whose rear resupply legs cross no\n                           -- enemy sectors either. Wired for fidelity; fires only if the front overruns\n                           -- the supply corridor.\n}\n\nlocal ESCORT_SECTOR_STEP = 25000   -- m between leg samples (sector-walk proxy; base spacing scale)\n\n-- route_difficulty(side, from_pos, to_pos) \226\134\146 difficulty (0..10), air_threats, enemy_sectors.\n-- Faithful port of assess_task_difficulty (task.c:880-909) onto bases-as-sectors.\nfunction M.route_difficulty(side, from_pos, to_pos)\n    if not from_pos or not to_pos then return 0, 0, 0 end\n    local imap = require(\"imap\")   -- deferred require: avoids the imap\226\134\146campaign_state load cycle\n    local dx, dz = to_pos.x - from_pos.x, to_pos.z - from_pos.z\n    local len = math.sqrt(dx * dx + dz * dz)\n    local n = math.max(1, math.floor(len / ESCORT_SECTOR_STEP))\n    local seen, air_threats, enemy_sectors = {}, 0, 0\n    for i = 0, n do\n        local t  = i / n\n        local px = from_pos.x + dx * t\n        local pz = from_pos.z + dz * t\n        -- nearest base to the sample = its sector (mirrors get_x/z_sector of a route node, task.c:876)\n        local best, best_d2 = nil, math.huge\n        for name, bpos in pairs(M.S.base_pos) do\n            if M.S.base_owner[name] then\n                local ex, ez = px - bpos.x, pz - bpos.z\n                local d2 = ex * ex + ez * ez\n                if d2 < best_d2 then best_d2 = d2; best = name end\n            end\n        end\n        if best and not seen[best] then\n            seen[best] = true\n            local bpos = M.S.base_pos[best]\n            -- +1 air_threat per sector with enemy surface-to-air defence (task.c:930-935)\n            if imap.get(side, imap.AIR_DEFENCE, bpos) > 0.0 then air_threats = air_threats + 1 end\n            -- +1 enemy_sector per sector whose side != this side (task.c:937-939)\n            if M.S.base_owner[best] ~= side then enemy_sectors = enemy_sectors + 1 end\n        end\n    end\n    -- GRID-COARSENESS CALIBRATION: EECH's >>1 halving (task.c:890 `min((air_threats >> 1), 5)`,\n    -- :901 `min((enemy_sectors >> 1), 5)`) is calibrated to its FINE ~4 km sector grid, where a\n    -- strike leg crosses tens of sectors. The port's bases-as-sectors grid is ~25-100 km coarse \226\128\148\n    -- ONE base-sector spans many EECH sectors \226\128\148 so a typical leg touches only 2-5 base-sectors and\n    -- halving crushes the counts to 0-1, below every threshold (escorts would silently never fire).\n    -- Faithful proxy: count each coarse base-sector at full weight, keeping the C's caps of 5.\n    -- Sanity: a 60 km leg over 2 defended enemy bases \226\134\146 difficulty 4 (strike threshold 3 met);\n    -- deep multi-base legs reach the SEAD threshold 5; CRITICAL 6 stays rare.\n    local air = math.min(air_threats, 5)     -- cap 5 (task.c:890); no >>1 on the coarse grid (see above)\n    local ens = math.min(enemy_sectors, 5)   -- cap 5 (task.c:901); no >>1 on the coarse grid (see above)\n    return air + ens, air_threats, enemy_sectors\nend\n\n-- escort_count(task_type, side, from_pos, to_pos, log_fn) \226\134\146 number of escorts to create (0/1/2).\n-- 0 below threshold; 1 at/above threshold; 2 (CRITICAL) at difficulty >= ESCORT_CRITICAL.\n-- PROXY NOTE: in EECH the CRITICAL flag (assign.c:619, threat >= ESCORT_CRITICAL) marks the escort\n-- TASK critical \226\134\146 higher assignment PRIORITY (\195\1512 sort), not a larger escort. The port spawns escorts\n-- directly (no priority queue for the secondary consume), so criticality has no priority meaning here;\n-- the closest observable analog is a heavier (2-ship) escort on a critical-threat leg. Documented proxy.\n-- Logs difficulty-vs-threshold at the decision point (Cluster F dbg requirement).\nfunction M.escort_count(task_type, side, from_pos, to_pos, log_fn)\n    local thr = M.ESCORT_THRESHOLD[task_type]\n    if not thr then return 0 end            -- ESCORT_NEVER task type\n    local diff = M.route_difficulty(side, from_pos, to_pos)\n    local want = (diff >= thr) and ((diff >= M.ESCORT_CRITICAL) and 2 or 1) or 0\n    M.dbg(\"escort\", \"%s %s escort: route difficulty=%d vs threshold=%d -> %d escort(s)%s\",\n        M.SIDE_NAME[side] or \"?\", task_type, diff, thr, want,\n        (diff >= M.ESCORT_CRITICAL) and \" (CRITICAL)\" or \"\")\n    return want\nend\n\nreturn M\n"
__modules["cas_bai_sead"] = "-- cas_bai_sead.lua\n-- EECH source: aphavoc/source/ai/highlevl/highlevl.c\n--\n-- create_cas_tasks() line 815\n--   Period: 6 min (skirmish) / 15 min (campaign); offset 0.0\n--   Targets: LIST_TYPE_GROUND_REGISTRY groups where INT_TYPE_FRONTLINE==1 (highlevl.c:877)\n--            \226\134\146 PRIMARY frontline group TYPE (armour), not a sector-distance value.\n--   Score: (1-airdef)*1 + base_dist*3 + sector_ratio*2; max=6.0\n--   Limits: CREATE_CAS_TASK_COUNT=2, MAX_SECTOR_CAS_TASK_COUNT=1\n--   FOW: NO FOW check (CAS proceeds regardless of fog)\n--\n-- create_bai_tasks() line 575\n--   Period: 10 min (skirmish) / 20 min (campaign); offset 90 s / 5 min\n--   Targets: LIST_TYPE_GROUND_REGISTRY groups where INT_TYPE_FRONTLINE>1 (highlevl.c:637)\n--            \226\134\146 SECONDARY(2)/support + ARTILLERY(3) group TYPES (second-line).\n--   Score: (1-airdef)*2 + base_dist*3 + sector_ratio*2; max=7.0\n--   Limits: CREATE_BAI_TASK_COUNT=2, MAX_SECTOR_BAI_TASK_COUNT=1\n--   FOW: fow > 0.5 * maximum (CONFIRMED at line 757 \226\128\148 HIGHER threshold than other tasks)\n--\n-- ECHELON SPLIT (Cluster B): INT_TYPE_FRONTLINE is group_database[sub_type].frontline_flag\n-- (gp_int.c:389-392) \226\128\148 a STATIC per-group-TYPE flag (NONE=0/PRIMARY=1/SECONDARY=2/ARTILLERY=3,\n-- group.h:199-202), NOT a distance. The port's ground groups are undifferentiated, so the\n-- echelon is proxied POSITIONALLY via frontline.echelon_of(pos): a target whose nearest owned\n-- base is a Gabriel-frontline base \226\134\146 \"frontline\" (CAS), else \226\134\146 \"second\" (BAI/SEAD). See\n-- frontline.lua:echelon_of. This is the first real consumer of the Gabriel frontline flags and\n-- replaces the old invented `is_near_friendly` 200 km band (frontl.FRONTLINE_RADIUS, traced to\n-- nothing in EECH) that starved BAI on any scoped theatre.\n--\n-- create_sead_tasks() line 1918\n--   Period: 10 min (skirmish) / 12 min (campaign); offset 2 s / 3 min\n--   Targets: enemy groups with air_attack_strength==10 AND !frontline_flag (highlevl.c:1981)\n--            \226\134\146 rear/site AA (NONE echelon), not frontline-attached AA. Proxied via\n--              frontline.echelon_of(pos)==\"second\".\n--   Score: base_dist*4 + sector_ratio*3; max=7.0\n--   Limits: CREATE_SEAD_TASK_COUNT=2, MAX_SECTOR_SEAD_TASK_COUNT=1\n--   FOW: fow >= 0.25 * maximum\n--\n-- create_oca_sweep_tasks() line 1473\n--   Period: 20 min (skirmish) / 30 min (campaign); offset 4 min / 1.5 min\n--   Targets: enemy keysites where keysite_database[type].oca_target == true\n--   Score: (1-airdef)*1 + base_dist*4 + sector_ratio*2; max=7.0\n--   Limits: CREATE_OCA_SWEEP_TASK_COUNT=2, MIN_TASK_CREATION_RATIO=0.75\n--   FOW: fow >= 0.25 * maximum\n--\n-- create_artillery_strike_tasks() line 2836\n--   Period: 12 min (skirmish) / 15 min (campaign); offset 8 s / 45 s\n--   Groups: own artillery groups (GROUP_FRONTLINE_FLAG_ARTILLERY)\n--   Targets: enemy frontline groups + ground_strike keysites within max_weapon_range\n--   FOW: fow > 0.25 * maximum (per target sector)\n--   Limit: MAX_ARTILLERY_STRIKE_COUNT=5\n--\n-- highlevl.c line 84-100 constants:\n--   MAX_HIGHLEVEL_TARGET_CHECKS = 160\n--   MIN_TASK_CREATION_RATIO     = 0.75\n--   CREATE_CAS_TASK_COUNT       = 2\n--   MAX_SECTOR_CAS_TASK_COUNT   = 1\n--   CREATE_BAI_TASK_COUNT       = 2\n--   MAX_SECTOR_BAI_TASK_COUNT   = 1\n--   CREATE_OCA_SWEEP_TASK_COUNT = 2\n--   CREATE_SEAD_TASK_COUNT      = 2\n--   MAX_SECTOR_SEAD_TASK_COUNT  = 1\n--   MAX_ARTILLERY_STRIKE_COUNT  = 5 (line 2836)\n\nlocal cs       = require(\"campaign_state\")\nlocal croute   = require(\"croute\")\nlocal imap_m   = require(\"imap\")\nlocal fow_m    = require(\"fog_of_war\")\nlocal frontl   = require(\"frontline\")\nlocal ov       = require(\"map_overlay\")\nlocal recon    = require(\"recon\")\nlocal config   = require(\"config\")\nlocal board    = require(\"task_board\")\nlocal supply   = require(\"supply\")   -- SEAD-escort secondary consume/refund (spawn_sead_escort);\n                                     -- was referenced as an undeclared global \226\134\146 every SEAD builder\n                                     -- threw at :273 (live-caught; the analyzer does not flag\n                                     -- unknown globals \226\128\148 checker blind spot)\nlocal S        = cs.S\nlocal M        = {}\n\n-- \226\148\128\226\148\128 EECH constants (exact mirror, highlevl.c line 84\226\128\147100, 2836) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal MAX_HIGHLEVEL_TARGET_CHECKS = 160\nlocal MIN_TASK_CREATION_RATIO     = 0.75\nlocal CREATE_CAS_TASK_COUNT       = 2\nlocal MAX_SECTOR_CAS_TASK_COUNT   = 1\nlocal CREATE_BAI_TASK_COUNT       = 2\nlocal MAX_SECTOR_BAI_TASK_COUNT   = 1\nlocal CREATE_OCA_SWEEP_TASK_COUNT = 2\nlocal CREATE_SEAD_TASK_COUNT      = 2\nlocal MAX_SECTOR_SEAD_TASK_COUNT  = 1\nlocal MAX_ARTILLERY_STRIKE_COUNT  = 5\n\n-- \226\148\128\226\148\128 FOW thresholds (exact from highlevl.c usage) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- CAS: no FOW check (line 980\226\128\1471000, no fow conditional)\n-- BAI: fow > 0.5 * maximum (line 757)\n-- SEAD/OCA/Artillery: fow >= 0.25 * maximum (lines 2072, 1620, 3062)\nlocal FOW_THRESHOLD_BAI  = 0.50  -- line 757\nlocal FOW_THRESHOLD_SEAD = 0.25  -- line 2072\nlocal FOW_THRESHOLD_OCA  = 0.25  -- line 1620\nlocal FOW_THRESHOLD_ART  = 0.25  -- line 3062\n\n-- \226\148\128\226\148\128 Periods (from highlevl.c add_high_level_ai_function calls; Item 5: mode-selected) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Campaign (highlevl.c:246-266) vs SKIRMISH (:220-240) is chosen by config.C.mode via campaign_mode.lua\n-- (the single cadence source). Campaign values are byte-identical to the prior hardcoded literals.\nlocal mode            = require(\"campaign_mode\")\nlocal PERIOD_CAS      = mode.SCHED.cas.period        -- :246 15min campaign / :220 6min skirmish\nlocal PERIOD_BAI      = mode.SCHED.bai.period        -- :266 20min campaign / :236 10min skirmish\nlocal PERIOD_SEAD     = mode.SCHED.sead.period       -- :264 12min campaign / :222 10min skirmish\nlocal PERIOD_OCA_SWEP = mode.SCHED.oca_sweep.period  -- :258 30min campaign / :240 20min skirmish\nlocal PERIOD_ARTY     = mode.SCHED.artillery.period  -- :254 15min campaign / :226 12min skirmish\n\n-- \226\148\128\226\148\128 Initial offsets (exact from add_high_level_ai_function, campaign mode) \226\148\128\226\148\128\226\148\128\226\148\128\nlocal OFFSET_CAS      = 0.0           -- line 246: offset 0\nlocal OFFSET_BAI      = 5.0 * 60      -- line 266: offset 5 min\nlocal OFFSET_SEAD     = 3.0 * 60      -- line 264: offset 3 min\nlocal OFFSET_OCA_SWEP = 1.5 * 60      -- line 258: offset 1.5 min\nlocal OFFSET_ARTY     = 45.0          -- line 254: offset 45 s\n\n-- \226\148\128\226\148\128 Aircraft configuration (hoisted to config.lua; matches attack_waves.lua for consistency) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal AC = {}\nfor _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n    AC[side] = {\n        country = config.C.countries[side],\n        striker = config.C.types.aircraft[side].striker,\n        escort  = config.C.types.aircraft[side].escort,\n    }\nend\n\nlocal PYLON = config.C.payloads\n\nlocal STRIKE_ALT   = 6000\nlocal ESCORT_ALT   = 7000\nlocal STRIKE_SPEED = 220\n\n-- \226\148\128\226\148\128 Sector ratio proxy (mirrors get_local_sector_side_ratio, sector.c) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH: get_local_sector_side_ratio(x,z,side) = fraction of the local sector\n-- neighbourhood painted by `side` (keysite 1/d\194\178 influence over the sector grid).\n-- DCS proxy: fraction of owned bases within SECTOR_RATIO_RADIUS of (x,z) that\n-- belong to `side` \226\128\148 a coarse keysite-influence stand-in.\n-- NOTE: this is its OWN named constant, INDEPENDENT of the (now-deleted) frontline\n-- echelon band. Cluster B decoupled the echelon split from this value; the 200 km\n-- here is the sector-influence proxy radius and is NOT an EECH-derived constant\n-- (no C source paints influence at a fixed metric radius), so it remains a\n-- designer-tunable proxy \226\128\148 kept at 200 km, deliberately not re-tuned in this cluster.\nlocal SECTOR_RATIO_RADIUS = 200000  -- metres; keysite-influence sector-paint proxy radius\n\nlocal function sector_ratio(pos, side)\n    if not pos then return 0.0 end\n    local r2      = SECTOR_RATIO_RADIUS * SECTOR_RATIO_RADIUS\n    local friendly, total = 0, 0\n    for name, owner in pairs(S.base_owner) do\n        local bpos = S.base_pos[name]\n        if bpos then\n            local dx = pos.x - bpos.x\n            local dz = pos.z - bpos.z\n            if dx*dx + dz*dz <= r2 then\n                total = total + 1\n                if owner == side then friendly = friendly + 1 end\n            end\n        end\n    end\n    if total == 0 then return 0.0 end\n    return friendly / total\nend\n\n-- \226\148\128\226\148\128 Score sorting (mirrors quicksort_entity_list) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function sort_targets(list)\n    table.sort(list, function(a, b) return a.rating > b.rating end)\nend\n\n-- \226\148\128\226\148\128 Sector proxy \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH reads get_local_sector_entity(pos); the port has no sector grid, so the nearest\n-- keysite to a position is its \"sector\". Used for both the per-sector task cap and the\n-- fog-of-war lookup (which is tracked per base).\nlocal function nearest_base_to(pos)\n    local best, best_d2 = nil, math.huge\n    for name, bpos in pairs(S.base_pos) do\n        local dx = pos.x - bpos.x\n        local dz = pos.z - bpos.z\n        local d2 = dx*dx + dz*dz\n        if d2 < best_d2 then best_d2 = d2; best = name end\n    end\n    return best\nend\n\n-- Normalised (0..1) fog-of-war value at a target position for `side` = FOW of the target's\n-- sector (nearest base). fow_m.get() already returns raw/FOW_MAX. Mirrors\n-- get_sector_fog_of_war_value(sector_of(pos), side). Fixes the old 200 km-cap proxy that made\n-- distant targets permanently un-strikeable AND un-reconnable (audit L4).\nlocal function fow_at(pos, side)\n    local base = nearest_base_to(pos)\n    if not base then return 0.0 end\n    return fow_m.get(base, side) or 0.0\nend\n\n-- Echelon classification (Cluster B): frontl.echelon_of(pos) returns \"frontline\"\n-- (PRIMARY-frontline target TYPE, INT_TYPE_FRONTLINE==1, highlevl.c:877 \226\134\146 CAS) or\n-- \"second\" (SECONDARY/ARTILLERY, INT_TYPE_FRONTLINE>1, highlevl.c:637 \226\134\146 BAI; and\n-- rear AA, !frontline_flag, highlevl.c:1981 \226\134\146 SEAD). See frontline.lua:echelon_of\n-- for the group-database-flag-vs-positional-proxy rationale. This replaces the\n-- deleted `is_near_friendly` 200 km band that traced to nothing in EECH.\n\n-- \226\148\128\226\148\128 EECH post-sort strike-vs-recon fork (highlevl.c:731-800) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Score ALL candidates ignoring FOW, sort, then for the top CREATE_*_TASK_COUNT:\n--   ratio = rating[i]/rating[0]; require ratio >= MIN_TASK_CREATION_RATIO\n--   require the target's sector has < MAX_SECTOR_*_TASK_COUNT existing tasks this cycle\n--   if sector FOW passes the task's threshold \226\134\146 create the STRIKE\n--   else                                      \226\134\146 create a RECON of that sector instead\n-- This is a FORK, not a filter: fogged high-value targets get reconned (revealed) rather than\n-- silently dropped, and the #1 target keeps setting the ratio baseline either way.\n-- cfg = { count, sector_max, fow_threshold (normalised 0..1, or nil = no FOW gate / never recon),\n--         fow_strict (true \226\134\146 strict '>' as EECH BAI, else '>='), side, label,\n--         spawn = function(entry) -> bool,\n--         recon_obj = function(entry) -> objective table for reaction's recon-completed chain }\nlocal function apply_fork(rated, cfg)\n    local tag = cfg.dbg_tag or \"cas\"\n    if #rated == 0 then return end\n    sort_targets(rated)\n    local max_r = rated[1].rating\n    if max_r <= 0 then return end\n    local count = math.min(#rated, cfg.count)\n    local sectors_used = {}\n    local n_struck, n_reconned, n_ratio_dropped, n_sector_capped = 0, 0, 0, 0\n\n    for i = 1, count do\n        local e = rated[i]\n        if e.rating / max_r >= MIN_TASK_CREATION_RATIO then\n            local base = nearest_base_to(e.pos)      -- the sector whose FOW the gate reads\n            local sk   = base or tostring(i)\n            local used = sectors_used[sk] or 0\n            if used < cfg.sector_max then\n                local ok\n                if cfg.fow_threshold == nil then\n                    -- CAS: no FOW gate, always strike (never recon).\n                    ok = cfg.spawn(e)\n                    if ok then n_struck = n_struck + 1 end\n                else\n                    local fow  = fow_at(e.pos, cfg.side)\n                    local pass = cfg.fow_strict and (fow > cfg.fow_threshold)\n                                                 or (not cfg.fow_strict and fow >= cfg.fow_threshold)\n                    if pass then\n                        ok = cfg.spawn(e)                              -- reconned \226\134\146 strike\n                        if ok then n_struck = n_struck + 1 end\n                    else\n                        -- Fogged \226\134\146 RECON. Aim at the SECTOR BASE (the FOW value the gate reads),\n                        -- not the raw target, so the overflight actually raises that base's FOW\n                        -- and the target becomes strikeable next cycle (self-heal for all task types).\n                        local recon_pos = (base and S.base_pos[base]) or e.pos\n                        local obj = cfg.recon_obj and cfg.recon_obj(e) or nil\n                        ok = recon.spawn_recon(cfg.side, recon_pos, cfg.label, cfg.log_fn, obj)\n                        if ok then n_reconned = n_reconned + 1 end\n                    end\n                end\n                if ok then sectors_used[sk] = used + 1 end\n            else\n                n_sector_capped = n_sector_capped + 1\n            end\n        else\n            n_ratio_dropped = n_ratio_dropped + 1\n        end\n    end\n    cs.dbg(tag, \"%s %s fork: %d rated -> top %d checked: %d struck, %d reconned (fogged), %d below ratio, %d sector-capped\",\n        cs.SIDE_NAME[cfg.side], cfg.label, #rated, count, n_struck, n_reconned, n_ratio_dropped, n_sector_capped)\nend\n\n-- \226\148\128\226\148\128 SEAD escort (assign.c:598-627 escort_required, threshold model) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH creates an escort at task assignment when route difficulty >= escort_required_threshold; SEAD's\n-- warzone threshold is the highest (5) so escort only fires on genuinely deep/defended legs. Fixed-wing\n-- fighters resident at the launch base; SECONDARY escort ledger consume with refund-on-fail (dev-loop).\nlocal function spawn_sead_escort(side, home_ab, ab_pos, target_pos, n, log_fn)\n    if n <= 0 then return end\n    local base_name = home_ab:getName()\n    if not supply.consume_base(base_name, \"escort\", n) then\n        cs.dbg(\"sead\", \"%s SEAD escort ABORT at %s: no escort stock\", cs.SIDE_NAME[side], base_name)\n        return\n    end\n    local cfg    = AC[side]\n    local bx, by = cs.wp_xy(ab_pos)\n    local tx, ty = cs.wp_xy(target_pos)\n    local eid    = cs.next_id()\n    local ename  = string.format(\"Escort-%d\", eid)\n    local e_units = {}\n    for i = 1, n do\n        e_units[i] = { name = ename..\"-\"..i, type = cfg.escort, skill = \"High\",\n            x = ab_pos.x + (i-1)*20, y = ab_pos.z, alt = ab_pos.y, alt_type = \"BARO\", speed = 0, heading = 0,\n            payload = { fuel = 5200, flare = 120, chaff = 120, gun = 100, pylons = PYLON[side].escort } }\n    end\n    local ok_e, grp = pcall(coalition.addGroup, cfg.country, Group.Category.AIRPLANE, {\n        name = ename, task = \"Fighter Sweep\", hidden = false, airdromeId = home_ab:getID(), units = e_units,\n        route = { points = croute.expand({\n            { type=\"TakeOff\", action=\"From Parking Area\", airdromeId=home_ab:getID(),\n              alt=ab_pos.y, alt_type=\"BARO\", speed=0, ETA=0, ETA_locked=true, x=bx, y=by, name=\"Depart\", formation_template=\"\" },\n            { type=\"Turning Point\", action=\"Turning Point\", alt=ESCORT_ALT, alt_type=\"BARO\", speed=STRIKE_SPEED,\n              ETA=0, ETA_locked=false, x=tx, y=ty, name=\"Sweep\", formation_template=\"\",\n              task = { id=\"ComboTask\", params={ tasks={ [1]={ number=1, auto=true, id=\"EngageTargets\",\n                enabled=true, params={ maxDist=40000, priority=0, targetTypes={\"Air\"} } } }}}},\n            { type=\"Land\", action=\"Landing\", airdromeId=home_ab:getID(),\n              alt=ab_pos.y, alt_type=\"BARO\", speed=STRIKE_SPEED, ETA=0, ETA_locked=false, x=bx, y=by, name=\"RTB\", formation_template=\"\" },\n        }, side, { alt=ESCORT_ALT, alt_type=\"BARO\", speed=STRIKE_SPEED, name=\"Nav\" }) },\n    })\n    if ok_e and grp then\n        cs.dbg(\"sead\", \"%s SEAD escort #%d (%dx%s) spawned from %s\", cs.SIDE_NAME[side], eid, n, cfg.escort, base_name)\n    else\n        supply.recycle_base(base_name, \"escort\", n)   -- refund: escort spawn failed/threw\n        cs.dbg(\"sead\", \"%s SEAD escort #%d FAILED (pcall_ok=%s) -> refunded\", cs.SIDE_NAME[side], eid, tostring(ok_e))\n    end\nend\n\n-- \226\148\128\226\148\128 build_air_strike(side, base_name, target_pos, task_label, log_fn) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- BUILDER (task-board contract): spawns a striker FROM base_name at target_pos. The board has\n-- already consumed 1 \"striker\" from base_name's ledger (refunds on nil). Shared by CAS/BAI/SEAD.\n-- Returns the group on success, nil on failure.\nlocal function build_air_strike(side, base_name, target_pos, task_label, log_fn)\n    local dbg_tag = task_label:find(\"SEAD\") and \"sead\" or (task_label:find(\"BAI\") and \"bai\" or \"cas\")\n    local home_ab = Airbase.getByName(base_name)\n    if not home_ab then\n        cs.dbg(dbg_tag, \"%s build_air_strike ABORT: base %s not found\", cs.SIDE_NAME[side], tostring(base_name))\n        return nil\n    end\n\n    local cfg    = AC[side]\n    local ab_pos = home_ab:getPosition().p\n    local bx, by = cs.wp_xy(ab_pos)\n    local tx, ty = cs.wp_xy(target_pos)\n    local sid    = cs.next_id()\n    local gname  = string.format(\"%s-%d-%d\", task_label, side, sid)\n\n    -- SEAD role (#16): dedicated SEAD tasking so the AI prioritises radars/air-defence rather than\n    -- generic ground units. NOTE: an anti-radiation loadout (AGM-88 HARM / Kh-25MP) needs weapon\n    -- CLSIDs verified against the live DCS DB (guardrail) \226\128\148 swap PYLON[side].sead in once verified;\n    -- the striker payload (Kh-29T / GBU can still kill radars) is the interim verified loadout.\n    local is_sead    = task_label:find(\"SEAD\") ~= nil\n    local dcs_task   = is_sead and \"SEAD\" or \"Ground Attack\"\n    local target_set = is_sead and { \"Air Defence\" } or { \"Ground Units\", \"Helicopters\" }\n\n    local grp = coalition.addGroup(cfg.country, Group.Category.AIRPLANE, {\n        name        = gname,\n        task        = dcs_task,\n        hidden      = false,\n        airdromeId  = home_ab:getID(),\n        units = {{\n            name     = gname .. \"-1\",\n            type     = cfg.striker,\n            skill    = \"Good\",\n            x        = ab_pos.x,\n            y        = ab_pos.z,\n            alt      = ab_pos.y,\n            alt_type = \"BARO\",\n            speed    = 0,\n            heading  = cs.heading_to(ab_pos.x, ab_pos.z, target_pos.x, target_pos.z),\n            payload  = { fuel = 4900, flare = 60, chaff = 60, gun = 100, pylons = PYLON[side].striker },\n        }},\n        route = { points = croute.expand({\n            {\n                type = \"TakeOff\", action = \"From Parking Area\",\n                airdromeId = home_ab:getID(),\n                alt = ab_pos.y, alt_type = \"BARO\", speed = 0,\n                ETA = 0, ETA_locked = true,\n                x = bx, y = by, name = \"Depart\", formation_template = \"\",\n            },\n            {\n                type = \"Turning Point\", action = \"Turning Point\",\n                alt = STRIKE_ALT, alt_type = \"BARO\", speed = STRIKE_SPEED,\n                ETA = 0, ETA_locked = false, x = tx, y = ty,\n                name = \"Attack\", formation_template = \"\",\n                task = {\n                    id = \"ComboTask\",\n                    params = { tasks = { [1] = {\n                        number = 1, auto = true, id = \"EngageTargets\", enabled = true,\n                        params = { maxDist = 15000, priority = 0,\n                                   targetTypes = { \"Ground Units\", \"Helicopters\" } },\n                    }}},\n                },\n            },\n            {\n                type = \"Land\", action = \"Landing\",\n                airdromeId = home_ab:getID(),\n                alt = ab_pos.y, alt_type = \"BARO\", speed = STRIKE_SPEED,\n                ETA = 0, ETA_locked = false,\n                x = bx, y = by, name = \"RTB\", formation_template = \"\",\n            },\n        }, side, { alt=STRIKE_ALT, alt_type=\"BARO\", speed=STRIKE_SPEED, name=\"Nav\" })},\n    })\n\n    if grp then\n        ov.add_task_arrow(gname, ab_pos, target_pos, side)   -- Item 4: key by group name (GC backstop reaps it)\n        -- Escort by threat (assign.c:598-627): SEAD flights get fighter escort iff route difficulty\n        -- >= the SEAD escort threshold (5). Only SEAD is escort-eligible here (CAS/BAI are rotary).\n        if is_sead then\n            local ec = cs.escort_count(\"sead\", side, ab_pos, target_pos, log_fn)\n            spawn_sead_escort(side, home_ab, ab_pos, target_pos, ec, log_fn)\n        end\n        log_fn(string.format(\"%s %s #%d from %s\", cs.SIDE_NAME[side], task_label, sid, home_ab:getName()))\n        cs.dbg(dbg_tag, \"%s %s #%d spawned from %s (task=%s)\", cs.SIDE_NAME[side], task_label, sid,\n            home_ab:getName(), dcs_task)\n        return grp\n    end\n    log_fn(string.format(\"%s %s #%d SPAWN FAILED\", cs.SIDE_NAME[side], task_label, sid))\n    cs.dbg(dbg_tag, \"%s %s #%d SPAWN FAILED (addGroup returned nil)\", cs.SIDE_NAME[side], task_label, sid)\n    return nil\nend\n\n-- Create a board task for a striker sortie (task_type = \"cas\"|\"bai\"|\"sead\"; label drives the DCS\n-- task/target set inside build_air_strike). Returns true (task placed) for the per-sector cap.\n-- `critical` (optional, WAVE 3 Item 4): reaction callers pass true (SEAD reaction.c:540/highlevl.c:2659,\n-- BAI-from-recon reaction.c:583) or false (counter-battery BAI reaction.c:788) so the board sorts the\n-- task at the C's critical setting (assign.c:201-204). Generator callers omit it \226\134\146 M.CRITICAL default.\nlocal function create_air_strike_task(side, target_pos, task_type, task_label, log_fn, immediate, critical)\n    -- CAS and BAI are the ROTARY frontline fight in EECH (heli-eligible, ts_dbase.c landing_types\n    -- :511/:329) \226\128\148 they launch ATTACK-HELICOPTER sections. The board's \"heli\" role assigns them to\n    -- the nearest heli-capable base; forward FARPs win, so the front becomes a helicopter war (this\n    -- is what the retired heli_war anti_armour/hunter_killer layer was faking). SEAD stays fixed-wing.\n    local builder\n    if task_type == \"cas\" or task_type == \"bai\" then\n        local hw = require(\"heli_war\")\n        builder = function(base_name)\n            return hw.build_attack_heli(side, base_name, target_pos, task_type, log_fn)\n        end\n    else\n        builder = function(base_name)\n            return build_air_strike(side, base_name, target_pos, task_label, log_fn)\n        end\n    end\n    board.create_task({\n        type = task_type, side = side, count = 1, log_fn = log_fn, immediate = immediate,\n        critical = critical,   -- nil for generators (M.CRITICAL default); set by the reaction chain\n        target = { pos = target_pos },\n        builder = builder,\n    })\n    return true\nend\n\n-- \226\148\128\226\148\128 Echelon-by-GROUP-TYPE (Cluster F, fold-in from Cluster B) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH splits ground targets between CAS/BAI/SEAD by the STATIC per-group-TYPE flag\n-- group_database[sub_type].frontline_flag (INT_TYPE_FRONTLINE, gp_int.c:389-392); the enum is\n-- NONE=0 / PRIMARY=1 / SECONDARY=2 / ARTILLERY=3 (group.h:199-202):\n--   create_cas_tasks  keeps FRONTLINE==1 (PRIMARY armour, highlevl.c:877)          \226\134\146 CAS\n--   create_bai_tasks  keeps FRONTLINE >1 (SECONDARY support + ARTILLERY, hl.c:637) \226\134\146 BAI\n--   create_sead_tasks keeps !frontline_flag AA (NONE, highlevl.c:1981)             \226\134\146 SEAD\n-- The port now tags its spawned ground groups by NAME, so we can read the flag by TYPE directly:\n--   \"GndCol-\"  = COMBINED-ARMS PRIMARY frontline (FORMCOMP.DAT:434-469: tanks + IFVs + ORGANIC AD\n--                slots 4/6 + APCs; gp_dbase.c:723 frontline_flag PRIMARY) \226\134\146 flag 1\n--   \"GndSec-\"  = SECONDARY second-echelon frontline group (FORMCOMP.DAT:475-511: tanks + IFVs +\n--                organic SHORAD + trucks/scout; GROUP_SECONDARY_FRONTLINE frontline_flag SECONDARY,\n--                gp_dbase.c:764) \226\134\146 flag 2. FRONTLINE>1 \226\134\146 these are the CANONICAL BAI targets\n--                (highlevl.c:637), never CAS (==1), never SEAD (tagged \226\134\146 not a get_enemy_aa_targets\n--                candidate even when attrition compacts its lead onto the organic Chaparral/SA-13).\n--   \"Arty-\"    = SP-artillery / MLRS battery (FORMCOMP.DAT:549-579; gp_dbase.c:805/846) \226\134\146 flag 3\n--   \"*-def\"    = installation garrison company \226\134\146 flag 2 (SECONDARY)\n--   \"Patrol-\"  = 4-man infantry keysite patrol \226\134\146 flag 0 (NONE): EECH's infantry-patrol group type is\n--                not a frontline group (frontline_flag NONE, gp_int.c:389-392 returns the database\n--                flag), and BOTH generators exclude 0 \226\128\148 CAS keeps ==1 (highlevl.c:877), BAI keeps\n--                >1 (highlevl.c:637) \226\128\148 so patrols are a target of NEITHER.\n--   \"FP-\"      = population FIRING POINT / MANPAD (GROUP_STATIC_INFANTRY, gp_dbase.c:887 frontline_flag\n--                NONE; air_attack_strength 6, gp_dbase.c:896) \226\134\146 flag 0 (NONE): matched by NEITHER CAS\n--                (==1) nor BAI (>1), and \226\128\148 being non-nil-flagged (tagged) \226\128\148 excluded from the generator\n--                SEAD's get_enemy_aa_targets (highlevl.c:1981 wants air_attack==10 SITE AA; a MANPAD\n--                soldier is not). NOTE: EECH's REACTION SEAD-around-keysite (highlevl.c:2620) filters on\n--                default_entity_type==ANTI_AIRCRAFT, which GROUP_STATIC_INFANTRY IS (gp_dbase.c:876), so\n--                firing-point MANPADs DO count there \226\128\148 reaction.create_sead_around_keysite is left\n--                untagged/unchanged to stay faithful. MANPADs also feed the AIR_DEFENCE imap by\n--                attribute (desired, small contribution).\n-- GENUINELY unknown combat groups (no tag) fall back to the POSITIONAL proxy frontl.echelon_of(pos)\n-- from Cluster B. Type-first, position-as-fallback (used FIRST per the Cluster F spec).\nlocal function group_frontline_flag(grp)\n    local n = (grp and grp.getName and grp:getName()) or \"\"\n    if n:match(\"^GndCol\")  then return 1 end   -- PRIMARY   (gp_dbase.c:723)\n    if n:match(\"^GndSec\")  then return 2 end   -- SECONDARY (gp_dbase.c:764) \226\134\146 BAI target\n    if n:match(\"^Arty\")    then return 3 end   -- ARTILLERY (gp_dbase.c:805/846)\n    if n:match(\"%-def$\")   then return 2 end   -- installation garrison \226\134\146 SECONDARY\n    if n:match(\"^Patrol\")  then return 0 end   -- infantry patrol \226\134\146 NONE (excluded from CAS AND BAI)\n    if n:match(\"^FP%-\")    then return 0 end   -- population firing point / MANPAD \226\134\146 NONE (gp_dbase.c:887)\n    return nil                                  -- unknown \226\134\146 positional fallback\nend\n\n-- Echelon of a ground target: type flag first (0 \226\134\146 \"none\": neither generator; 1 \226\134\146 \"frontline\"/CAS;\n-- >1 \226\134\146 \"second\"/BAI), else the Cluster B positional proxy for untagged combat groups.\nlocal function target_echelon(t)\n    local f = group_frontline_flag(t.group)\n    if f == 0 then return \"none\" end        -- NONE: matched by neither ==1 nor >1 (highlevl.c:877/:637)\n    if f == 1 then return \"frontline\" end\n    if f then return \"second\" end           -- 2 (SECONDARY) / 3 (ARTILLERY)\n    return frontl.echelon_of(t.pos)\nend\n\n-- \226\148\128\226\148\128 Collect enemy ground group targets \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors EECH LIST_TYPE_GROUND_REGISTRY scan in create_cas/bai_tasks().\n-- EECH iterates all registered ground groups per force. DCS proxy: scan\n-- coalition.getGroups(enemy) for GROUND category groups, excluding AA (\226\134\146 SEAD).\n-- Enemy ARTILLERY is NOT excluded: EECH create_bai_tasks keeps FRONTLINE>1 which includes\n-- ARTILLERY(3) \226\128\148 batteries are legitimate BAI targets (and counter-battery targets). They classify\n-- as \"second\" via target_echelon so they flow to BAI, never CAS. This closes the single-column limit.\nlocal function get_enemy_ground_targets(side)\n    local enemy   = cs.ENEMY[side]\n    local targets = {}\n    local grps = coalition.getGroups(enemy)\n    if not grps then return targets end\n\n    for _, grp in ipairs(grps) do\n        if #targets >= MAX_HIGHLEVEL_TARGET_CHECKS then break end\n        if grp and grp:isExist() and grp:getCategory() == Group.Category.GROUND then\n            local u = grp:getUnit(1)\n            if u and u:isExist() then\n                -- TAG PRIORITY (organic-AD guard): PRIMARY groups now carry ORGANIC AD (FORMCOMP.DAT\n                -- slots 4/6 \226\128\148 Avenger/SA-19, Chaparral/SA-13). This scan classifies by unit(1)\n                -- attributes, and after attrition the lead unit can compact onto an AD vehicle \226\128\148\n                -- which would silently reclassify the whole GndCol as an AA group. A NAME-tagged\n                -- campaign group's echelon flag is authoritative (EECH's frontline_flag is per\n                -- GROUP TYPE, gp_int.c:389-392, never per member), so tagged groups are always\n                -- ground targets; the unit-level is_aa filter applies only to untagged groups.\n                local tagged = group_frontline_flag(grp) ~= nil\n                local desc = u:getDesc()\n                local attr = desc and desc.attributes\n                -- Exclude only untagged AA (air_attack_strength==10 \226\134\146 SEAD's job, highlevl.c:1981).\n                local is_aa  = attr and (attr[\"SAM\"] or attr[\"AAA\"] or attr[\"SR SAM\"] or\n                                          attr[\"LR SAM\"] or attr[\"MR SAM\"] or attr[\"IR Guided SAM\"])\n                if tagged or not is_aa then\n                    targets[#targets + 1] = { group = grp, pos = u:getPosition().p }\n                end\n            end\n        end\n    end\n    return targets\nend\n\n-- \226\148\128\226\148\128 Collect enemy AA group targets \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors EECH: air_attack_strength==10 groups in LIST_TYPE_GROUND_REGISTRY.\n-- TAG PRIORITY (organic-AD guard, mirror of get_enemy_ground_targets): a NAME-tagged campaign\n-- ground group is NEVER a SEAD target even if its lead unit compacts onto an organic AD vehicle\n-- (FORMCOMP.DAT slots 4/6) \226\128\148 EECH SEADs only air_attack_strength==10 site-AA groups\n-- (highlevl.c:1981); a PRIMARY frontline group's stat is 6 (gp_dbase.c:732) and its\n-- frontline_flag is per GROUP TYPE (gp_int.c:389-392), so it stays a CAS/BAI ground target.\nlocal function get_enemy_aa_targets(enemy_side)\n    local targets = {}\n    local grps = coalition.getGroups(enemy_side)\n    if not grps then return targets end\n    for _, grp in ipairs(grps) do\n        if grp and grp:isExist() and #targets < MAX_HIGHLEVEL_TARGET_CHECKS then\n            local u = grp:getUnit(1)\n            if u and u:isExist() and group_frontline_flag(grp) == nil then\n                local desc = u:getDesc()\n                if desc and desc.attributes and (\n                    desc.attributes[\"SAM\"] or desc.attributes[\"AAA\"] or\n                    desc.attributes[\"SR SAM\"] or desc.attributes[\"LR SAM\"] or\n                    desc.attributes[\"MR SAM\"] or desc.attributes[\"IR Guided SAM\"]\n                ) then\n                    targets[#targets + 1] = { group = grp, pos = u:getPosition().p }\n                end\n            end\n        end\n    end\n    return targets\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- 1. CAS \226\128\148 create_cas_tasks (highlevl.c line 815)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Score = (1-airdef)*1 + base_dist*3 + sector_ratio*2;  max=6.0\n-- Targets: frontline enemy ground groups (FRONTLINE==1)\n-- No FOW check\nlocal function run_cas(side, log_fn)\n    local targets = get_enemy_ground_targets(side)\n    if #targets == 0 then\n        log_fn(cs.SIDE_NAME[side] .. \" CAS: no ground targets found\")\n        cs.dbg(\"cas\", \"%s CAS: no ground targets found, skipping\", cs.SIDE_NAME[side])\n        return\n    end\n\n    -- Score each target (mirrors create_cas_tasks loop). FOW is NOT applied here \226\128\148 the fork\n    -- handles it. CAS keeps PRIMARY-frontline targets (INT_TYPE_FRONTLINE==1, highlevl.c:877),\n    -- proxied by frontl.echelon_of(pos)==\"frontline\". Second-line targets fall through to BAI.\n    local rated = {}\n    local n_front, n_second = 0, 0\n    for _, t in ipairs(targets) do\n        local pos    = t.pos\n        local front  = target_echelon(t) == \"frontline\"\n        if front then n_front = n_front + 1 else n_second = n_second + 1 end\n\n        if front then\n            -- ORIENTATION FIX (Cluster F review): AIR_DEFENCE[side] = the AA that SIDE faces (imap's\n            -- updater scans SIDE's enemy's AA groups), so the ATTACKER reads its OWN side's layer \226\128\148\n            -- get(side, ...). The old get(enemy, ...) returned the attacker's own AA, inverting the\n            -- (1-airdef) term. Matches EECH get_imap_value(IMAP_AIR_DEFENCE, side, ...) semantics.\n            local airdef = imap_m.get(side, imap_m.AIR_DEFENCE, pos)\n            local bdist  = imap_m.get(side, imap_m.BASE_DISTANCE, pos)\n            local sratio = sector_ratio(pos, side)\n\n            -- EECH formula: (1-airdef)*1 + base_dist*3 + sector_ratio*2; max=6.0\n            local rating = (1.0 - airdef) * 1.0 + bdist * 3.0 + sratio * 2.0\n            if rating > 0.0 then\n                rated[#rated + 1] = { pos = pos, group = t.group, rating = rating }\n            end\n        end\n    end\n\n    cs.dbg(\"cas\", \"%s cas-scan: %d groups, %d frontline (cas), %d second-line (bai) -> %d rated (up to %d tasks)\",\n        cs.SIDE_NAME[side], #targets, n_front, n_second, #rated, CREATE_CAS_TASK_COUNT)\n\n    -- CAS has NO fog-of-war gate in EECH \226\134\146 fow_threshold = nil (always strike, never recon).\n    apply_fork(rated, {\n        count = CREATE_CAS_TASK_COUNT, sector_max = MAX_SECTOR_CAS_TASK_COUNT,\n        fow_threshold = nil, side = side, label = \"CAS\", log_fn = log_fn, dbg_tag = \"cas\",\n        spawn = function(e) return create_air_strike_task(side, e.pos, \"cas\", \"CAS\", log_fn) end,\n    })\nend\n\nfunction M.schedule_cas(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    -- Offset MUST be strictly > 0: DCS silently drops a timer scheduled at timer.getTime()+0, so an\n    -- offset of 0 means the scheduler never fires (this is exactly what suppressed BLUE's whole\n    -- attack-heli war). Clamp to a 1 s floor so a 0 can never silently disable a side again.\n    local offset = math.max(initial_offset or OFFSET_CAS, 1)\n    cs.dbg(\"cas\", \"%s CAS scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], offset, PERIOD_CAS)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        -- Item 6 (LITERAL post-victory semantics): the world runs on after victory \226\128\148 EECH fc_msgs.c:163\n        -- gates ONLY the win-check re-award (INT_TYPE_SESSION_COMPLETE), never the highlevl.c generators.\n        -- The prior Cluster-E generator suppression is removed (it was a proxy, not the literal C).\n        cs.dbg(\"cas\", \"%s CAS FIRE\", cs.SIDE_NAME[side])\n        local ok, err = pcall(run_cas, side, log_fn)\n        if not ok then log_fn(\"CAS error: \" .. tostring(err)) end\n        return t + PERIOD_CAS\n    end, nil, timer.getTime() + offset)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- 2. BAI \226\128\148 create_bai_tasks (highlevl.c line 575)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Score = (1-airdef)*2 + base_dist*3 + sector_ratio*2;  max=7.0\n-- Targets: enemy ground groups where FRONTLINE>1 (NOT primary frontline \226\134\146 second-line)\n-- FOW: fow > 0.5 * maximum (line 757 \226\128\148 confirmed 0.5, higher than other checks)\nlocal function run_bai(side, log_fn)\n    local targets = get_enemy_ground_targets(side)\n    if #targets == 0 then\n        cs.dbg(\"bai\", \"%s BAI: no ground targets found, skipping\", cs.SIDE_NAME[side])\n        return\n    end\n\n    -- Score ALL candidates ignoring FOW (the fork applies FOW). BAI keeps second-line targets\n    -- (INT_TYPE_FRONTLINE>1 \226\134\146 SECONDARY/ARTILLERY, highlevl.c:637), proxied by\n    -- frontl.echelon_of(pos)==\"second\". Primary-frontline targets are CAS's.\n    local rated = {}\n    local n_front, n_second = 0, 0\n    for _, t in ipairs(targets) do\n        local pos    = t.pos\n        local second = target_echelon(t) == \"second\"\n        if second then n_second = n_second + 1 else n_front = n_front + 1 end\n\n        if second then\n            -- ORIENTATION FIX: AIR_DEFENCE[side] = the AA that SIDE faces \226\134\146 attacker reads its own\n            -- side's layer, get(side, ...) (see run_cas note; old get(enemy,...) was inverted).\n            local airdef = imap_m.get(side, imap_m.AIR_DEFENCE, pos)\n            local bdist  = imap_m.get(side, imap_m.BASE_DISTANCE, pos)\n            local sratio = sector_ratio(pos, side)\n\n            -- EECH formula: (1-airdef)*2 + base_dist*3 + sector_ratio*2; max=7.0\n            local rating = (1.0 - airdef) * 2.0 + bdist * 3.0 + sratio * 2.0\n            if rating > 0.0 then\n                rated[#rated + 1] = { pos = pos, group = t.group, rating = rating }\n            end\n        end\n    end\n\n    cs.dbg(\"bai\", \"%s bai-scan: %d groups, %d frontline (cas), %d second-line (bai) -> %d rated (up to %d tasks)\",\n        cs.SIDE_NAME[side], #targets, n_front, n_second, #rated, CREATE_BAI_TASK_COUNT)\n\n    -- FOW gate (line 757): fow > 0.5 \195\151 max (STRICT) \226\134\146 BAI strike; else \226\134\146 RECON of the sector.\n    apply_fork(rated, {\n        count = CREATE_BAI_TASK_COUNT, sector_max = MAX_SECTOR_BAI_TASK_COUNT,\n        fow_threshold = FOW_THRESHOLD_BAI, fow_strict = true,\n        side = side, label = \"BAI\", log_fn = log_fn, dbg_tag = \"bai\",\n        spawn = function(e) return create_air_strike_task(side, e.pos, \"bai\", \"BAI\", log_fn) end,\n        recon_obj = function(e) return { kind = \"frontline_group\", pos = e.pos, group = e.group } end,\n    })\nend\n\nfunction M.schedule_bai(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    local offset = initial_offset or OFFSET_BAI\n    cs.dbg(\"bai\", \"%s BAI scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], offset, PERIOD_BAI)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        -- Item 6: generators keep running post-victory (EECH fc_msgs.c:163 gates only the win re-award).\n        cs.dbg(\"bai\", \"%s BAI FIRE\", cs.SIDE_NAME[side])\n        local ok, err = pcall(run_bai, side, log_fn)\n        if not ok then log_fn(\"BAI error: \" .. tostring(err)) end\n        return t + PERIOD_BAI\n    end, nil, timer.getTime() + offset)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- 3. SEAD \226\128\148 create_sead_tasks (highlevl.c line 1918)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Score = base_dist*4 + sector_ratio*3;  max=7.0\n-- Targets: enemy groups with air_attack_strength==10 AND NOT frontline\n-- FOW: fow >= 0.25 * maximum (line 2072)\nlocal function run_sead(side, log_fn)\n    local enemy   = cs.ENEMY[side]\n    local targets = get_enemy_aa_targets(enemy)\n    if #targets == 0 then\n        cs.dbg(\"sead\", \"%s SEAD: no enemy AA targets found, skipping\", cs.SIDE_NAME[side])\n        return\n    end\n\n    -- EECH SEADs only NON-frontline AA (highlevl.c:1981 `!group_database[type].frontline_flag`):\n    -- rear SAM sites and standalone air-defence, NOT frontline-attached AA (which the CAS/BAI\n    -- package suppresses incidentally). The port has no per-group-type frontline_flag, so it\n    -- proxies via echelon position: keep AA whose nearest owned base is NOT a frontline base\n    -- (frontl.echelon_of(pos)==\"second\"). Frontline-sector AA is excluded, matching the C filter.\n    local rated = {}\n    local n_rear, n_front = 0, 0\n    for _, t in ipairs(targets) do\n        local pos = t.pos\n        -- AA groups carry no GndCol/Arty/-def name tag \226\134\146 target_echelon falls back to the positional\n        -- proxy (identical to the Cluster B behaviour), keeping frontline-attached AA out of SEAD.\n        if target_echelon(t) == \"second\" then\n            n_rear = n_rear + 1\n            local bdist  = imap_m.get(side, imap_m.BASE_DISTANCE, pos)\n            local sratio = sector_ratio(pos, side)\n\n            -- EECH formula: base_dist*4 + sector_ratio*3; max=7.0\n            -- (commented-out terms in source not used: airdef, importance)\n            local rating = bdist * 4.0 + sratio * 3.0\n            if rating > 0.0 then\n                rated[#rated + 1] = { pos = pos, group = t.group, rating = rating }\n            end\n        else\n            n_front = n_front + 1\n        end\n    end\n\n    cs.dbg(\"sead\", \"%s sead-scan: %d AA groups, %d rear (sead), %d frontline-attached (excluded) -> %d rated (up to %d tasks)\",\n        cs.SIDE_NAME[side], #targets, n_rear, n_front, #rated, CREATE_SEAD_TASK_COUNT)\n\n    -- FOW gate (line 2072): fow >= 0.25 \195\151 max \226\134\146 SEAD strike; else \226\134\146 RECON of the sector.\n    apply_fork(rated, {\n        count = CREATE_SEAD_TASK_COUNT, sector_max = MAX_SECTOR_SEAD_TASK_COUNT,\n        fow_threshold = FOW_THRESHOLD_SEAD, side = side, label = \"SEAD\", log_fn = log_fn, dbg_tag = \"sead\",\n        spawn = function(e) return create_air_strike_task(side, e.pos, \"sead\", \"SEAD\", log_fn) end,\n        recon_obj = function(e) return { kind = \"aa_group\", group = e.group, pos = e.pos } end,\n    })\nend\n\nfunction M.schedule_sead(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    local offset = initial_offset or OFFSET_SEAD\n    cs.dbg(\"sead\", \"%s SEAD scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], offset, PERIOD_SEAD)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        -- Item 6: generators keep running post-victory (EECH fc_msgs.c:163 gates only the win re-award).\n        cs.dbg(\"sead\", \"%s SEAD FIRE\", cs.SIDE_NAME[side])\n        local ok, err = pcall(run_sead, side, log_fn)\n        if not ok then log_fn(\"SEAD error: \" .. tostring(err)) end\n        return t + PERIOD_SEAD\n    end, nil, timer.getTime() + offset)\nend\n\n-- Also expose direct SEAD spawn for reaction.lua to call\n-- Mirrors EECH: create_sead_task called from reaction chain when AA found near strike target\n-- SINGLE-SHOT EXPORTS (never-replace list) \226\128\148 reimplemented as immediate create_task wrappers.\n-- `critical` (optional): reaction SEAD is critical=TRUE (reaction.c:540, highlevl.c:2659) \226\128\148 reaction.lua\n-- passes true. Signature back-compatible: existing callers that omit it get the M.CRITICAL default.\nfunction M.spawn_sead_against(side, aa_group, log_fn, critical)\n    log_fn = log_fn or function() end\n    if not aa_group or not aa_group:isExist() then\n        cs.dbg(\"sead\", \"%s spawn_sead_against ABORT: aa_group missing/dead\", cs.SIDE_NAME[side])\n        return false\n    end\n    local u = aa_group:getUnit(1)\n    if not u or not u:isExist() then\n        cs.dbg(\"sead\", \"%s spawn_sead_against ABORT: aa_group has no live unit\", cs.SIDE_NAME[side])\n        return false\n    end\n    cs.dbg(\"sead\", \"%s spawn_sead_against: reaction-triggered SEAD task queued (immediate)\", cs.SIDE_NAME[side])\n    return create_air_strike_task(side, u:getPosition().p, \"sead\", \"SEAD-React\", log_fn, true, critical)\nend\n\n-- Direct BAI spawn for reaction.lua's recon-of-frontline-group \226\134\146 BAI chain (reaction.c:568).\n-- `critical` (optional): the recon-of-frontline BAI is critical=TRUE (reaction.c:583) but the\n-- counter-battery BAI (create_reaction_to_artillery_fire) is critical=FALSE (reaction.c:788) \226\128\148 reaction.lua\n-- passes the C's value per call site. Omitting it (existing callers) keeps the M.CRITICAL default.\nfunction M.spawn_bai_against(side, pos, log_fn, critical)\n    log_fn = log_fn or function() end\n    if not pos then\n        cs.dbg(\"bai\", \"%s spawn_bai_against ABORT: no pos\", cs.SIDE_NAME[side])\n        return false\n    end\n    cs.dbg(\"bai\", \"%s spawn_bai_against: reaction-triggered BAI task queued (immediate)\", cs.SIDE_NAME[side])\n    return create_air_strike_task(side, pos, \"bai\", \"BAI-React\", log_fn, true, critical)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- 4. OCA Sweep \226\128\148 create_oca_sweep_tasks (highlevl.c line 1473)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Score = (1-airdef)*1 + base_dist*4 + sector_ratio*2;  max=7.0\n-- Targets: enemy keysites where keysite_database[type].oca_target == true\n--          (DCS proxy: all enemy-owned airbases)\n-- FOW: fow >= 0.25 * maximum (line 1620)\n-- Spawns: ESCORT (fighter) aircraft for CAP orbit rather than strike\n-- BUILDER: spawn a fighter sweep (escort) FROM base_name over the target airfield. The board has\n-- already consumed 1 \"escort\" from base_name's ledger (refunds on nil). Returns group or nil.\nlocal function build_oca_sweep(side, base_name, target_pos, target_name, log_fn)\n    local home_ab = Airbase.getByName(base_name)\n    if not home_ab then\n        cs.dbg(\"oca\", \"%s build_oca_sweep ABORT: base %s not found\", cs.SIDE_NAME[side], tostring(base_name))\n        return nil\n    end\n    local cfg    = AC[side]\n    local ab_pos = home_ab:getPosition().p\n    local bx, by = cs.wp_xy(ab_pos)\n    local tx, ty = cs.wp_xy(target_pos)\n    local sid    = cs.next_id()\n    local gname  = string.format(\"OCA-Sweep-%d-%d\", side, sid)\n\n    local sweep_grp = coalition.addGroup(cfg.country, Group.Category.AIRPLANE, {\n        name        = gname,\n        task        = \"Fighter Sweep\",\n        hidden      = false,\n        airdromeId  = home_ab:getID(),\n        units = {{\n            name = gname..\"-1\", type = cfg.escort, skill = \"High\",\n            x = ab_pos.x, y = ab_pos.z, alt = ab_pos.y, alt_type = \"BARO\",\n            speed = 0, heading = 0,\n            payload = { fuel = 5200, flare = 120, chaff = 120, gun = 100, pylons = PYLON[side].escort },\n        }},\n        route = { points = croute.expand({\n            { type=\"TakeOff\", action=\"From Parking Area\", airdromeId=home_ab:getID(),\n              alt=ab_pos.y, alt_type=\"BARO\", speed=0, ETA=0, ETA_locked=true,\n              x=bx, y=by, name=\"Depart\", formation_template=\"\" },\n            { type=\"Turning Point\", action=\"Turning Point\",\n              alt=ESCORT_ALT, alt_type=\"BARO\", speed=STRIKE_SPEED,\n              ETA=0, ETA_locked=false, x=tx, y=ty, name=\"Sweep\", formation_template=\"\",\n              task = { id=\"ComboTask\", params={ tasks={ [1]={ number=1, auto=true,\n                id=\"EngageTargets\", enabled=true,\n                params={ maxDist=40000, priority=0, targetTypes={\"Air\"} } }}}},\n            },\n            { type=\"Land\", action=\"Landing\", airdromeId=home_ab:getID(),\n              alt=ab_pos.y, alt_type=\"BARO\", speed=STRIKE_SPEED, ETA=0, ETA_locked=false,\n              x=bx, y=by, name=\"RTB\", formation_template=\"\" },\n        }, side, { alt=ESCORT_ALT, alt_type=\"BARO\", speed=STRIKE_SPEED, name=\"Nav\" })},\n    })\n    if sweep_grp then\n        -- Offensive keysite task \226\134\146 registered so the defender scrambles CAP/BARCAP at target_name.\n        cs.register_task(gname, {\n            task_type   = \"oca_sweep\",\n            side        = side,\n            target_base = target_name,\n            target_pos  = target_pos,\n            objective   = { kind = \"keysite\", base = target_name },\n            born_time   = timer.getTime(),\n        })\n        ov.add_task_arrow(gname, ab_pos, target_pos, side)   -- Item 4: key by group name (clear_task reaps it)\n        log_fn(string.format(\"%s OCA Sweep #%d from %s \226\134\146 %s\", cs.SIDE_NAME[side], sid, home_ab:getName(), target_name or \"?\"))\n        cs.dbg(\"oca\", \"%s OCA Sweep #%d spawned from %s -> %s\", cs.SIDE_NAME[side], sid, home_ab:getName(), target_name or \"?\")\n        return sweep_grp\n    end\n    cs.dbg(\"oca\", \"%s OCA Sweep #%d SPAWN FAILED\", cs.SIDE_NAME[side], sid)\n    return nil\nend\n\n-- Create a board task for an OCA sweep (role escort). target has a base name (airfield objective).\nlocal function create_oca_sweep_task(side, target_pos, target_name, log_fn)\n    board.create_task({\n        type = \"oca_sweep\", side = side, count = 1, log_fn = log_fn,\n        target = { base = target_name, pos = target_pos, objective = { kind = \"keysite\", base = target_name } },\n        builder = function(base_name)\n            return build_oca_sweep(side, base_name, target_pos, target_name, log_fn)\n        end,\n    })\n    return true\nend\n\nlocal function run_oca_sweep(side, log_fn)\n    local enemy = cs.ENEMY[side]\n\n    -- Score ALL enemy airfields ignoring FOW (the fork applies FOW).\n    local rated = {}\n    for tname, towner in pairs(S.base_owner) do\n        if towner == enemy then\n            local tpos = S.base_pos[tname]\n            if tpos then\n                -- ORIENTATION FIX: AIR_DEFENCE[side] = the AA that SIDE faces \226\134\146 attacker reads its\n                -- own side's layer, get(side, ...) (see run_cas note; old get(enemy,...) was inverted).\n                local airdef = imap_m.get(side, imap_m.AIR_DEFENCE, tpos)\n                local bdist  = imap_m.get(side, imap_m.BASE_DISTANCE, tpos)\n                local sratio = sector_ratio(tpos, side)\n\n                -- EECH formula: (1-airdef)*1 + base_dist*4 + sector_ratio*2; max=7.0\n                local rating = (1.0 - airdef) * 1.0 + bdist * 4.0 + sratio * 2.0\n                if rating > 0.0 then\n                    rated[#rated + 1] = { name = tname, pos = tpos, rating = rating }\n                end\n            end\n        end\n    end\n\n    cs.dbg(\"oca\", \"%s OCA Sweep: %d enemy airfields rated (creating up to %d tasks)\",\n        cs.SIDE_NAME[side], #rated, CREATE_OCA_SWEEP_TASK_COUNT)\n\n    -- FOW gate (line 1620): fow >= 0.25 \195\151 max \226\134\146 sweep; else \226\134\146 RECON of the airfield.\n    apply_fork(rated, {\n        count = CREATE_OCA_SWEEP_TASK_COUNT, sector_max = 1,\n        fow_threshold = FOW_THRESHOLD_OCA, side = side, label = \"OCA-Sweep\", log_fn = log_fn, dbg_tag = \"oca\",\n        spawn = function(e) return create_oca_sweep_task(side, e.pos, e.name, log_fn) end,\n        recon_obj = function(e) return { kind = \"keysite\", base = e.name, pos = e.pos } end,\n    })\nend\n\n-- \226\148\128\226\148\128 Single-shot spawn (called by reaction.lua for follow-on OCA Sweep) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- SINGLE-SHOT EXPORT (never-replace list). Backward-compatible signature \226\128\148 the two new args are\n-- OPTIONAL; existing generator/no-target callers are unaffected:\n--   \226\128\162 no target      \226\134\146 re-run the whole generator scan (unchanged legacy behaviour);\n--   \226\128\162 target_name(+pos) \226\134\146 create ONE OCA_SWEEP task ON that recon'd objective. EECH's follow-on sweep\n--     (create_reaction_to_recon_task_completed, reaction.c:469-471) passes the recon'd `objective` to\n--     create_oca_sweep_task, so the sweep hits the SAME base the recon revealed \226\128\148 NOT a fresh scan\n--     that could pick a different base and double-charge the 2-task (CREATE_OCA_SWEEP_TASK_COUNT)\n--     generator budget. The reaction call site now passes the objective + its position.\nfunction M.run_oca_sweep(side, log_fn, target_name, target_pos)\n    log_fn = log_fn or function() end\n    if target_name then\n        local tpos = target_pos or S.base_pos[target_name]\n        if not tpos then\n            cs.dbg(\"oca\", \"%s run_oca_sweep DIRECTED SKIP vs %s: no position\", cs.SIDE_NAME[side], tostring(target_name))\n            return\n        end\n        cs.dbg(\"oca\", \"%s run_oca_sweep: DIRECTED (reaction follow-on) OCA sweep ON %s (reaction.c:469-471)\",\n            cs.SIDE_NAME[side], target_name)\n        local ok, err = pcall(create_oca_sweep_task, side, tpos, target_name, log_fn)\n        if not ok then log_fn(\"run_oca_sweep(directed) error: \" .. tostring(err)) end\n        return\n    end\n    cs.dbg(\"oca\", \"%s run_oca_sweep: single-shot invocation (generator scan)\", cs.SIDE_NAME[side])\n    local ok, err = pcall(run_oca_sweep, side, log_fn)\n    if not ok then log_fn(\"run_oca_sweep error: \" .. tostring(err)) end\nend\n\nfunction M.schedule_oca_sweep(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    local offset = initial_offset or OFFSET_OCA_SWEP\n    cs.dbg(\"oca\", \"%s OCA Sweep scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], offset, PERIOD_OCA_SWEP)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        -- Item 6: generators keep running post-victory (EECH fc_msgs.c:163 gates only the win re-award).\n        cs.dbg(\"oca\", \"%s OCA Sweep FIRE\", cs.SIDE_NAME[side])\n        local ok, err = pcall(run_oca_sweep, side, log_fn)\n        if not ok then log_fn(\"OCA Sweep error: \" .. tostring(err)) end\n        return t + PERIOD_OCA_SWEP\n    end, nil, timer.getTime() + offset)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- 5. Artillery \226\128\148 create_artillery_strike_tasks (highlevl.c line 2836)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Find own artillery groups (GROUP_FRONTLINE_FLAG_ARTILLERY proxy: DCS Artillery attribute)\n-- Find enemy frontline targets (groups + ground_strike keysites) within max weapon range\n-- Assign via setTask(engageTargets / engageTargetsInZone)\n-- FOW > 0.25 * maximum per target (line 3062)\n-- MAX_ARTILLERY_STRIKE_COUNT = 5\nlocal ARTY_DEFAULT_RANGE = 20000  -- metres; proxy for get_local_group_max_weapon_range\n\nlocal function run_artillery(side, log_fn)\n    local enemy = cs.ENEMY[side]\n\n    -- Collect own artillery groups (mirrors GROUP_FRONTLINE_FLAG_ARTILLERY list, gp_dbase.c:805/846).\n    -- Belt-and-braces: match the DCS \"Artillery\" attribute OR the \"Arty-\" group name the OOB tags them\n    -- with (ground_forces.spawn_arty_group) \226\128\148 so a chosen DCS type that lacks the attribute still fires.\n    local arty_groups = {}\n    local own_grps = coalition.getGroups(side)\n    if own_grps then\n        for _, grp in ipairs(own_grps) do\n            if grp and grp:isExist() then\n                local u = grp:getUnit(1)\n                if u and u:isExist() then\n                    local desc = u:getDesc()\n                    local is_art = desc and desc.attributes and desc.attributes[\"Artillery\"]\n                    local by_name = grp:getName():match(\"^Arty\")\n                    if is_art or by_name then\n                        arty_groups[#arty_groups + 1] = grp\n                    end\n                end\n            end\n        end\n    end\n    if #arty_groups == 0 then\n        cs.dbg(\"cas\", \"%s Artillery: no own artillery groups, skipping\", cs.SIDE_NAME[side])\n        return\n    end\n\n    -- Collect enemy targets: frontline ground groups + enemy bases within range\n    local target_positions = {}\n    -- Enemy frontline groups (whole standing frontline, not a single column)\n    for _, rec in pairs((S.ground_groups and S.ground_groups[enemy]) or {}) do\n        if cs.group_is_alive(rec.grp) then\n            local u = rec.grp:getUnit(1)\n            if u and u:isExist() then\n                target_positions[#target_positions + 1] = u:getPosition().p\n            end\n        end\n    end\n    -- Enemy artillery batteries (counter-battery: EECH BAI/artillery both target FRONTLINE>1 incl.\n    -- ARTILLERY, gp_dbase.c:805). Own artillery counter-fires enemy batteries when in range.\n    for _, rec in pairs((S.arty_groups and S.arty_groups[enemy]) or {}) do\n        if cs.group_is_alive(rec.grp) then\n            local u = rec.grp:getUnit(1)\n            if u and u:isExist() then\n                target_positions[#target_positions + 1] = u:getPosition().p\n            end\n        end\n    end\n    -- Enemy non-airbase installations (ground_strike_target keysites, Cluster G)\n    do\n        local ok, inst = pcall(require, \"installations\")\n        if ok and inst then\n            for _, t in ipairs(inst.strike_targets(side)) do\n                target_positions[#target_positions + 1] = t.pos\n            end\n        end\n    end\n    -- Enemy bases as keysite targets (ground_strike_target == true proxy: all bases)\n    for ename, eowner in pairs(S.base_owner) do\n        if eowner == enemy then\n            local epos = S.base_pos[ename]\n            if epos then target_positions[#target_positions + 1] = epos end\n        end\n    end\n\n    if #target_positions == 0 then\n        cs.dbg(\"cas\", \"%s Artillery: %d arty groups but no targets in range, skipping\", cs.SIDE_NAME[side], #arty_groups)\n        return\n    end\n\n    -- Assign artillery to targets (mirrors group_index/target_index loops)\n    local assigned = 0\n    for _, arty in ipairs(arty_groups) do\n        if assigned >= MAX_ARTILLERY_STRIKE_COUNT then break end\n        local au = arty:getUnit(1)\n        if au and au:isExist() then\n            local apos   = au:getPosition().p\n            local max_r2 = ARTY_DEFAULT_RANGE * ARTY_DEFAULT_RANGE\n\n            for _, tpos in ipairs(target_positions) do\n                if assigned >= MAX_ARTILLERY_STRIKE_COUNT then break end\n                local dx = apos.x - tpos.x\n                local dz = apos.z - tpos.z\n                local d2 = dx*dx + dz*dz\n\n                if d2 < max_r2 then\n                    -- FOW check: fow > 0.25 * maximum (line 3062)\n                    -- Find nearest enemy base to target pos\n                    local fow_ok = false\n                    for ename, eowner in pairs(S.base_owner) do\n                        if eowner == enemy then\n                            local epos = S.base_pos[ename]\n                            if epos then\n                                local dx2 = tpos.x - epos.x\n                                local dz2 = tpos.z - epos.z\n                                if dx2*dx2 + dz2*dz2 < 200000*200000 then\n                                    if fow_m.get(ename, side) > FOW_THRESHOLD_ART then\n                                        fow_ok = true; break\n                                    end\n                                end\n                            end\n                        end\n                    end\n\n                    if fow_ok then\n                        -- mirrors engage_targets_in_area(group, target_pos, 1.0*KILOMETRE, ...)\n                        local ctrl = arty:getController()\n                        if ctrl then\n                            ctrl:setTask({\n                                id = \"FireAtPoint\",\n                                params = {\n                                    point    = { x = tpos.x, y = tpos.z },\n                                    radius   = 1000,    -- 1 km; mirrors 1.0*KILOMETRE in EECH\n                                    expendQty = 20,\n                                    expendQtyEnabled = true,\n                                },\n                            })\n                            assigned = assigned + 1\n                            log_fn(string.format(\"%s Artillery \226\134\146 (%.0f, %.0f)\", cs.SIDE_NAME[side], tpos.x, tpos.z))\n                            -- The shot IS the \"artillery fire\" notification (EECH notify_local_entity\n                            -- ARTILLERY_FIRE \226\134\146 create_reaction_to_artillery_fire): the VICTIM side raises\n                            -- counter-battery BAI/RECON against THIS battery (reaction.c:703-810).\n                            local ok_r, react = pcall(require, \"reaction\")\n                            if ok_r and react and react.on_artillery_fire then\n                                pcall(react.on_artillery_fire, cs.ENEMY[side], arty, apos, log_fn)\n                            end\n                            break  -- each artillery group gets one target\n                        end\n                    end\n                end\n            end\n        end\n    end\n    cs.dbg(\"cas\", \"%s Artillery: %d groups, %d targets -> %d fire missions assigned\", cs.SIDE_NAME[side],\n        #arty_groups, #target_positions, assigned)\nend\n\nfunction M.schedule_artillery(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    local offset = initial_offset or OFFSET_ARTY\n    cs.dbg(\"cas\", \"%s Artillery scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], offset, PERIOD_ARTY)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        -- Item 6: generators keep running post-victory (EECH fc_msgs.c:163 gates only the win re-award).\n        local ok, err = pcall(run_artillery, side, log_fn)\n        if not ok then log_fn(\"Artillery error: \" .. tostring(err)) end\n        return t + PERIOD_ARTY\n    end, nil, timer.getTime() + offset)\nend\n\nreturn M\n"
__modules["config"] = "-- config.lua \226\128\148 SCENARIO-DATA configuration loader (the port's \"warzone data file\").\n--\n-- WHAT THIS IS (and is NOT):\n--   EECH itself splits its campaign into two layers: hard ENGINE CONSTANTS compiled into the C source\n--   (cadences, formulas, thresholds \226\128\148 highlevl.c / reaction.c / ks_dbase.c / force.c) and DATA files\n--   loaded from disk (FORMCOMP.DAT formation compositions, the WUT warzone-unit tables, faction rosters).\n--   This module is the port's equivalent of that DATA layer: the SCENARIO warzone data a mission author\n--   may legitimately re-skin \226\128\148 unit type names, countries, weapon payloads, reserve counts, installation\n--   statics, and a handful of documented designer/proxy theatre knobs.\n--\n--   EECH-CITED ENGINE CONSTANTS ARE DELIBERATELY **NOT** HERE (CLAUDE.md prime directive). Cadences,\n--   strike/repair/capture formulas, MINIMUM_EFFICIENCY, ESCORT thresholds, FOW gates, damage fractions,\n--   ETA-gate speeds, CRUISE_SPEED and all spawn kinematics (alt/speed/fuel) stay hardcoded in their\n--   modules with their file:line citations. If a value traces to the EECH C source it is not tunable.\n--\n-- HOW AN AUTHOR OVERRIDES IT:\n--   Set a global table `_G.DMT_CONFIG` BEFORE the campaign script runs (a MISSION START \226\134\146 DO SCRIPT\n--   trigger, or a dofile before injection). It is deep-merged OVER the DEFAULTS below (user wins per\n--   LEAF key; ARRAYS \226\128\148 slot lists, pylon lists, unit lists \226\128\148 replace wholesale, never merge per-index).\n--   The merged result is exposed as `config.C` and also on `_G.DMT_ACTIVE_CONFIG` for inspection.\n--\n--   SIDE-KEYED tables use the STRING keys \"blue\" / \"red\" in DMT_CONFIG (NOT coalition.side numbers \226\128\148\n--   those collide with array indices and would break the deep-merge). `config.C` re-keys them to\n--   coalition.side.BLUE / coalition.side.RED for the consuming modules. See README \"Configuring the\n--   campaign (DMT_CONFIG)\".\n--\n-- BOOT VALIDATION:\n--   main.lua calls `config.load_and_validate(log_fn)` AFTER reset.nuke but BEFORE game_loop starts (so\n--   before ANY spawn). It DB-checks every aircraft/ground unit type (Unit.getDescByName), structurally\n--   checks statics/payloads (they cannot be verified from the mission env), and falls each bad USER\n--   override back to its DEFAULT (resilient boot). A DEFAULT that itself fails the DB check (e.g. the\n--   AH-64D module is not installed \226\128\148 a real past incident) raises a LOUD warning + on-screen outText\n--   naming the missing types and the fix. Boot continues either way; spawn-path pcall+refund keeps the\n--   economy safe on any residual failure.\n--\n-- Hoisted from (defaults trace back to these literals, citations preserved):\n--   attack_waves.lua / cas_bai_sead.lua / reaction.lua / recon.lua / regen.lua / heli_war.lua (aircraft\n--   + pylon tables), troop.lua (transport heli + infantry), ground_forces.lua (FORMCOMP.DAT slot rows),\n--   installations.lua (KINDS/PALETTE/garrison/EWR/AAA/SAM), base_defenses.lua (AD-ring composition,\n--   counts, radius \226\134\146 the `defenses` section),\n--   farps.lua (FARP static + fixed-wing count + front distance), supply.lua (reserve allotments),\n--   payloads.lua (the pylon/CLSID tables \226\128\148 this module exposes them).\n\nlocal cs       = require(\"campaign_state\")\nlocal payloads = require(\"payloads\")\n\nlocal BLUE = coalition.side.BLUE\nlocal RED  = coalition.side.RED\n\nlocal M = {}\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- DEFAULTS \226\128\148 string side keys (\"blue\"/\"red\"); re-keyed to coalition.side in build().\n-- Values are the EXACT current literals from the modules named above (a pure hoist).\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\nlocal DEFAULTS = {\n\n    -- Campaign scheduler MODE selector (campaign_mode.lua): \"campaign\" (default) or \"skirmish\".\n    -- Selects which of EECH's two start_high_level_ai cadence tables the schedulers use \226\128\148 campaign\n    -- (highlevl.c:246-268) or the faster SKIRMISH branch (highlevl.c:218-242). The cadence VALUES are\n    -- EECH-cited engine constants and live in campaign_mode.lua; this is only the selector. Default\n    -- \"campaign\" preserves EECH fidelity for a DCS session (== campaign game type).\n    mode = \"campaign\",\n\n    -- Country id per side (single source; ground_forces/installations/farps/base_defenses + the\n    -- aircraft spawners all draw their coalition country from here).\n    countries = { blue = country.id.USA, red = country.id.RUSSIA },\n\n    types = {\n        -- \226\148\128\226\148\128 Aircraft roster per side \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n        -- striker/escort: attack_waves.lua AC + cas_bai_sead.lua AC; recon: recon.lua AC;\n        -- attack_heli: heli_war.lua ATTACK + regen.lua AC.heli; transport_heli: troop.lua AC_HELI;\n        -- bda_heli: reaction.lua AC.heli (BDA/CAP-transport airframe). All verified via Unit.getDescByName.\n        aircraft = {\n            blue = {\n                striker        = \"F-16C bl.52d\",   -- ARMED_FW / ground attack\n                escort         = \"F-15C\",           -- FIGHTER / air superiority\n                recon          = \"F-15C\",           -- fast high overflight (recon.lua)\n                attack_heli    = \"AH-64D\",          -- primary anti-armour/CAS/BAI arm (heli_war/regen)\n                transport_heli = \"UH-60A\",          -- troop insertion + FARP resupply (user pref\n                                                    -- 2026-07-10: Black Hawk over Huey; live-DB-verified)\n                transport_fw   = \"C-130\",           -- MEDIUM lift (gp_dbase.c:590 C-130J Hercules II)\n                transport_fw_heavy = \"C-17A\",       -- HEAVY lift (gp_dbase.c:631 C-17 Globemaster III;\n                                                    -- alternates with medium per supply flight)\n                bda_heli       = \"UH-60A\",          -- BDA overflight (Black Hawk, ditto)\n            },\n            red = {\n                striker        = \"Su-25T\",\n                escort         = \"Su-27\",\n                recon          = \"Su-27\",\n                attack_heli    = \"Mi-24V\",\n                transport_heli = \"Mi-8MT\",\n                transport_fw   = \"An-26B\",          -- MEDIUM lift (gp_dbase.c:591 An-12B Cub; DCS has\n                                                    -- no An-12 \226\134\146 An-26B is the documented analog)\n                transport_fw_heavy = \"IL-76MD\",     -- HEAVY lift (gp_dbase.c:632 IL-76MD Candid B;\n                                                    -- alternates with medium per supply flight)\n                bda_heli       = \"Mi-8MT\",\n            },\n        },\n\n        ground = {\n            -- PRIMARY_FRONTLINE_GROUP ordered slots (ground_forces.lua; FORMCOMP.DAT:434-469, :COUNT 16\n            -- at :436). Each row = { BLUE DCS type, RED DCS type }; FORMCOMP line pair cited per row.\n            -- ARRAY \226\128\148 replaced wholesale on override.\n            primary_slots = {\n                { \"M-1 Abrams\",    \"T-80UD\"       },  -- :438/:439  M1A2_ABRAMS / T80U        (both verified)\n                { \"M-1 Abrams\",    \"T-80UD\"       },  -- :440/:441  M1A2_ABRAMS / T80U\n                { \"M2A2 Bradley\",  \"BMP-2\"        },  -- :442/:443  M2A2_BRADLEY / BMP2       (both verified)\n                { \"M1097 Avenger\", \"2S6 Tunguska\" },  -- :444/:445  M1037_AVENGER / SA19_GRISON (RED UNVERIFIED-IN-LIVE-DB)\n                { \"M2A2 Bradley\",  \"BMP-3\"        },  -- :446/:447  M2A2_BRADLEY / BMP3 (RED UNVERIFIED-IN-LIVE-DB)\n                { \"M48 Chaparral\", \"Strela-10M3\"  },  -- :448/:449  M48A1_CHAPARRAL / SA13_GOPHER (both UNVERIFIED-IN-LIVE-DB)\n                { \"M-113\",         \"BTR-80\"       },  -- :450/:451  M113A2 / BTR80 (BLUE UNVERIFIED-IN-LIVE-DB)\n                { \"M-1 Abrams\",    \"T-80UD\"       },  -- :452/:453  M1A2_ABRAMS / T80U\n                { \"M-1 Abrams\",    \"T-80UD\"       },  -- :454/:455  M1A2_ABRAMS / T80U\n                { \"M2A2 Bradley\",  \"BMP-2\"        },  -- :456/:457  M2A2_BRADLEY / BMP2\n                { \"M-1 Abrams\",    \"T-80UD\"       },  -- :458/:459  M1A2_ABRAMS / T80U\n                { \"M-1 Abrams\",    \"T-80UD\"       },  -- :460/:461  M1A2_ABRAMS / T80U\n                { \"M-113\",         \"BTR-80\"       },  -- :462/:463  M113A2 / BTR80\n                { \"M-1 Abrams\",    \"T-80UD\"       },  -- :464/:465  M1A2_ABRAMS / T80U\n                { \"M-113\",         \"BTR-80\"       },  -- :466/:467  M113A2 / BTR80\n                { \"M-1 Abrams\",    \"T-80UD\"       },  -- :468/:469  M1A2_ABRAMS / T80U\n            },\n            -- SECONDARY_FRONTLINE_GROUP ordered slots (ground_forces.lua; FORMCOMP.DAT:475-511, :COUNT 16\n            -- at :477). Placed at FRONTLINE_FORCE_SECONDARY road nodes BEHIND the primary line\n            -- (faction.c:1565-1600); group type GROUP_SECONDARY_FRONTLINE, frontline_flag SECONDARY\n            -- (gp_dbase.c:764). Consumed slot-by-slot in file order (faction.c:661/666); a size-N group\n            -- fields the FIRST N slots. Each row = { BLUE DCS type, RED DCS type }; FORMCOMP line pair per\n            -- row. ARRAY \226\128\148 replaced wholesale on override. All types LIVE-DB-VERIFIED (Unit.getDescByName\n            -- desc check, 2026-07-10); the three NEW types (M978 HEMTT Tanker / ATZ-10 / BRDM-2) pass the\n            -- same DB query the boot validator uses \226\128\148 spawn-test still the only 100% proof.\n            secondary_slots = {\n                { \"M-1 Abrams\",          \"T-80UD\"     },  -- :479/:480  M1A2_ABRAMS / T80U            (verified)\n                { \"M48 Chaparral\",       \"Strela-10M3\"},  -- :481/:482  M48A1_CHAPARRAL / SA13_GOPHER (organic SHORAD)\n                { \"M2A2 Bradley\",        \"BMP-3\"      },  -- :483/:484  M2A2_BRADLEY / BMP3\n                { \"M 818\",               \"Ural-375\"   },  -- :485/:486  M923A1_BIG_FOOT_COVERED / URAL_4320 (cargo truck)\n                { \"M-1 Abrams\",          \"T-80UD\"     },  -- :487/:488  M1A2_ABRAMS / T80U\n                { \"M978 HEMTT Tanker\",   \"ATZ-10\"     },  -- :489/:490  M978_HEMTT / URAL_FUEL_TANKER (NEW fuel truck)\n                { \"M1043 HMMWV Armament\",\"BRDM-2\"     },  -- :491/:492  M1025_HUMVEE / BRDM2 (scout; RED BRDM-2 NEW)\n                { \"M-113\",               \"BTR-80\"     },  -- :493/:494  M113A2 / BTR80\n                { \"M-1 Abrams\",          \"T-80UD\"     },  -- :495/:496  M1A2_ABRAMS / T80U\n                { \"M 818\",               \"Ural-375\"   },  -- :497/:498  M923A1_BIG_FOOT_COVERED / URAL_4320\n                { \"M-113\",               \"BTR-80\"     },  -- :499/:500  M113A2 / BTR80\n                { \"M48 Chaparral\",       \"Strela-10M3\"},  -- :501/:502  M48A1_CHAPARRAL / SA13_GOPHER\n                { \"M-1 Abrams\",          \"T-80UD\"     },  -- :503/:504  M1A2_ABRAMS / T80U\n                { \"M978 HEMTT Tanker\",   \"ATZ-10\"     },  -- :505/:506  M978_HEMTT / URAL_FUEL_TANKER\n                { \"M48 Chaparral\",       \"Strela-10M3\"},  -- :507/:508  M48A1_CHAPARRAL / SA13_GOPHER\n                { \"M-1 Abrams\",          \"T-80UD\"     },  -- :509/:510  M1A2_ABRAMS / T80U\n            },\n            -- ARTILLERY_GROUP slots (ground_forces.lua; FORMCOMP.DAT:549-562, :COUNT 4 at :552).\n            arty_slots = {\n                { \"M-109\",                \"SAU Msta\" },  -- :554/:555  M109A2 / 2S19 (both UNVERIFIED-IN-LIVE-DB)\n                { \"M-109\",                \"SAU Msta\" },  -- :556/:557  M109A2 / 2S19\n                { \"M 818\",                \"Ural-375\" },  -- :558/:559  M923A1_BIG_FOOT / URAL_4320 (both UNVERIFIED; Ural-4320 \226\134\146 \"Ural-375\")\n                { \"M1043 HMMWV Armament\", \"UAZ-469\"  },  -- :560/:561  M998_HUMVEE / UAZ469B (BLUE armed-variant sub; RED UNVERIFIED)\n            },\n            -- MLRS_GROUP slots (ground_forces.lua; FORMCOMP.DAT:566-579, :COUNT 4 at :569).\n            mlrs_slots = {\n                { \"MLRS\",                 \"Grad-URAL\" },  -- :571/:572  M270_MLRS / BM21_GRAD (both UNVERIFIED)\n                { \"MLRS\",                 \"Grad-URAL\" },  -- :573/:574  M270_MLRS / BM21_GRAD\n                { \"M 818\",                \"Ural-375\"  },  -- :575/:576  M923A1_BIG_FOOT / URAL_4320\n                { \"M1043 HMMWV Armament\", \"UAZ-469\"   },  -- :577/:578  M998_HUMVEE / UAZ469B\n            },\n            -- Keysite infantry patrol type (troop.lua INFANTRY_TYPE \226\128\148 proxy for FORMATION_COMPONENT_INFANTRY).\n            infantry = { blue = \"Soldier M4\", red = \"Infantry AK\" },\n            -- Installation empty-zone GARRISON (installations.lua GARRISON_UNITS \226\128\148 DESIGNER data, a mixed\n            -- defensive company for an auto-zone; ARRAY replaced wholesale).\n            garrison = {\n                blue = { \"M-1 Abrams\", \"M2A2 Bradley\", \"M2A2 Bradley\", \"M1043 HMMWV Armament\" },\n                red  = { \"T-80UD\", \"BMP-2\", \"BMP-2\", \"BTR-80\" },\n            },\n            -- Installation defence element types (installations.lua). ewr also feeds statics.kinds.radar.unit.\n            ewr = { blue = \"Hawk sr\", red = \"55G6 EWR\" },        -- radar/EWR unit per side\n            aaa = { blue = \"Vulcan\",  red = \"ZSU-23-4 Shilka\" }, -- short-range AAA\n            sam = { blue = { \"Roland ADS\" }, red = { \"Kub 1S91 str\", \"Kub 2P25 ln\" } },  -- point SAM battery (ARRAY)\n        },\n    },\n\n    -- \226\148\128\226\148\128 Static objects (STRUCTURE-only validated: a DB type query is not spawn proof \226\128\148 see the\n    -- 2026-07-06 journal crash saga where a \"valid\" type still failed to spawn; only a live spawn\n    -- confirms a triple. Author-supplied statics are trusted structurally and verified at spawn time).\n    statics = {\n        -- installations.lua KINDS: zone kind \226\134\146 physical object. \"static\" kinds carry a type/shape/cat\n        -- triple; the \"radar\" kind spawns a per-side EWR UNIT instead.\n        kinds = {\n            depot    = { spawn = \"static\", type = \"M92_10Ft_Container\", shape = \"M92_Container_10ft\", cat = \"Cargos\",         label = \"Supply Depot\" },\n            fuel     = { spawn = \"static\", type = \"FARP Fuel Depot\",    shape = \"GSM Rus\",            cat = \"Fortifications\", label = \"Fuel Depot\" },\n            command  = { spawn = \"static\", type = \".Command Center\",    shape = \"ComCenter\",          cat = \"Fortifications\", label = \"Command Post\" },\n            factory  = { spawn = \"static\", type = \"Boiler-house A\",     shape = \"kotelnaya_a\",        cat = \"Fortifications\", label = \"Munitions Factory\" },\n            refinery = { spawn = \"static\", type = \"FARP Fuel Depot\",    shape = \"GSM Rus\",            cat = \"Fortifications\", label = \"Oil Refinery\" },\n            radar    = { spawn = \"unit\",   unit = { blue = \"Hawk sr\", red = \"55G6 EWR\" },             label = \"Radar/EWR\" },\n        },\n        -- installations.lua PALETTE: verified spawn building blocks (type | shape_name | category).\n        palette = {\n            factory   = { \"Boiler-house A\",         \"kotelnaya_a\",        \"Fortifications\" },  -- production hall\n            warehouse = { \"Warehouse\",              \"sklad\",              \"Warehouses\"     },  -- storage shed\n            fueltank  = { \"Tank\",                   \"bak\",                \"Warehouses\"     },  -- fuel/oil tank\n            ammo      = { \".Ammunition depot\",      \"SkladC\",             \"Warehouses\"     },  -- ammo store\n            fuel      = { \"FARP Fuel Depot\",        \"GSM Rus\",            \"Fortifications\" },  -- fuel dump\n            command   = { \".Command Center\",        \"ComCenter\",          \"Fortifications\" },  -- HQ building\n            bunker    = { \"FARP CP Blindage\",       \"kp_ug\",              \"Fortifications\" },  -- command bunker\n            container = { \"M92_10Ft_Container\",     \"M92_Container_10ft\", \"Cargos\"         },  -- cargo container\n        },\n        -- farps.lua forward-FARP static (auto-theatre only; zone-authored theatres place their own).\n        farp = { type = \"FARP\", shape_name = \"FARP\", category = \"Heliports\" },\n    },\n\n    -- \226\148\128\226\148\128 Weapon pylon tables (payloads.lua). STRUCTURE-only validated (no mission-env API enumerates\n    -- CLSIDs); the CLSIDs are spawn-time-verified. Keyed side\226\134\146role\226\134\146pylon list.\n    payloads = {\n        blue = { striker = payloads.F16_STRIKER,  escort = payloads.F15_ESCORT, attack_heli = payloads.AH64D_CAP },\n        red  = { striker = payloads.SU25T_STRIKER, escort = payloads.SU27_ESCORT, attack_heli = payloads.MI24V_CAP },\n    },\n\n    -- \226\148\128\226\148\128 Reserve allotments (supply.lua). NOT the EECH-cited regen reseed counts (+6/+4 at\n    -- keysite.c:1490/1494 are engine constants and stay in regen.lua).\n    reserves = {\n        -- Per owned AIRBASE idle-aircraft ledger seed (supply.lua RESERVE_PER_BASE).\n        per_base = { striker = 4, escort = 2, heli = 6, recon = 1, transport = 3, vehicle = 2 },\n        -- FOB/FARP (helicopters-only) ledger seed (supply.lua:143): rotary + insertion transport only.\n        farp_heli      = 4,\n        farp_transport = 2,\n    },\n\n    -- \226\148\128\226\148\128 Theatre knobs \226\128\148 documented DESIGNER/proxy data only (no EECH C citation). Everything with a\n    -- C citation stays in its module.\n    theatre = {\n        -- Dormant-FARP activation gate (farps.lua; EECH keysite.c:507-568 initialise_keysite_farp_enable):\n        -- when TRUE (default, EECH-faithful) a forward FARP is created DORMANT (in_use=FALSE, ks_creat.c:157)\n        -- and only participates once its sector's side matches its own \226\128\148 i.e. as the front reaches it. When\n        -- FALSE, every FARP is active from boot (authored theatres that want all-active). Default TRUE for\n        -- fidelity (EECH FARPs are never all-active at boot; they enable when the sector is friendly).\n        farp_activation     = true,\n        fixed_wing_per_side = 2,        -- farps.lua FIXED_WING_PER_SIDE (a couple of FW airbases per side)\n        front_dist          = 140000,   -- m; ground_forces.lua:38 + installations.lua FRONT_DIST \226\128\148 both were\n                                        -- 140000 pre-hoist (unification VERIFIED, not a merge of two values)\n        farp_front_dist     = 260000,   -- m; farps.lua FRONT_DIST (forward-FARP frontline distance). The\n                                        -- RECORDED value is 260 km (goals/03 2026-07-06 close-spec-gaps\n                                        -- journal:523 \"FRONT_DIST 260km \226\134\146 19 FARPs\"); the 200000 found in\n                                        -- farps.lua at hoist time was unjournaled drift (07-09 journal:345)\n                                        -- \226\128\148 realigned to the journaled value here.\n    },\n\n    -- \226\148\128\226\148\128 Persistence (persist.lua \226\128\148 WAVE 2, goals/03 P1) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- Campaign save/restore through the DCS Studio SQLite bridge so the campaign survives a\n    -- DCS_server.exe restart (EECH pack_session analog). DISABLED BY DEFAULT so every current dev\n    -- workflow (hot re-inject) is byte-for-byte unchanged \226\128\148 enable it only for a dedicated-server\n    -- deployment. autosave_period is seconds between background autosaves (saves also fire on capture\n    -- and on the win declaration). slot names the save row; db_path is under lfs.writedir() (bridge-guarded).\n    persistence = {\n        enabled         = false,               -- master switch (restore in game_loop + autosave)\n        autosave_period = 300,                 -- s between autosaves (proxy for periodic session repack)\n        slot            = \"default\",           -- save-slot key (one campaign per slot)\n        db_path         = \"dmt_campaign.sqlite\", -- SQLite file under the guarded write root\n    },\n\n    -- \226\148\128\226\148\128 Keysite AIR-DEFENCE RINGS (base_defenses.lua) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- EECH popread.c:2148-2212 read_population_sam_placements spawns an ENTITY_SUB_TYPE_GROUP_ANTI_\n    -- AIRCRAFT group (formation FORMATION_COMPONENT_LIGHT_SAM_AAA_GROUP, popread.c:2204) at EVERY\n    -- population AAA/SAM point; the points come from map population templates (TEMPLATE_TYPE_AIRFIELD /\n    -- TEMPLATE_TYPE_AAASAM, popread.c:100-101) that seed several around every airfield/town. That per-\n    -- keysite DENSITY is MAP DATA, not in the C tree, so `groups_per` is a DOCUMENTED DESIGNER PROXY for\n    -- it (author sets 0 to opt a keysite class out). `ring_radius` is metres from the keysite centre the\n    -- ring is spaced at. `group` is the per-group composition = FORMCOMP.DAT:535-545 LIGHT_SAM_AAA_GROUP\n    -- FIRST TWO slots (member count = component_count-1 = 2, popread.c:2208): slot1 M48A1_CHAPARRAL /\n    -- SA19_GRISON, slot2 M163_VULCAN / SA13_GOPHER \226\134\146 DCS BLUE {M48 Chaparral, Vulcan}, RED {2S6 Tunguska\n    -- (SA-19), Strela-10M3 (SA-13)}. (FORMCOMP HEAVY_SAM_AAA_GROUP:516-530 has no code consumer in the\n    -- shipped tree \226\128\148 popread.c:2204 uses LIGHT only \226\128\148 so it is deliberately NOT ported.) These are FREE\n    -- OOB placement (no force-reserve consume \226\128\148 population AA is engine-placed, not force hardware).\n    defenses = {\n        groups_per  = { airbase = 3, farp = 1, installation = 1 },  -- DESIGNER proxy for popread density\n        ring_radius = 1500,                                         -- m; ring spacing from keysite centre\n        group = {   -- FORMCOMP.DAT:535-545 first 2 slots (ARRAY \226\128\148 replaced wholesale on override)\n            blue = { \"M48 Chaparral\", \"Vulcan\" },        -- M48A1_CHAPARRAL + M163_VULCAN\n            red  = { \"2S6 Tunguska\", \"Strela-10M3\" },    -- SA19_GRISON (SA-19) + SA13_GOPHER (SA-13)\n        },\n        -- \226\148\128\226\148\128 POPULATION FIRING POINTS (base_defenses.lua) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n        -- EECH popread.c:1389-1439: population building scene-links spawn SINGLE-UNIT\n        -- GROUP_STATIC_INFANTRY groups \226\128\148 FORMATION_COMPONENT_LIGHT/MEDIUM/HEAVY_FIRING_POINT (MG posts,\n        -- FORMCOMP.DAT:693-717, :COUNT 1) and INFANTRY_SAM_STANDING/KNEELING (MANPAD soldier,\n        -- FORMCOMP.DAT:617-631, :COUNT 1), linked to the closest keysite, owned by the sector side.\n        -- GROUP_STATIC_INFANTRY frontline_flag = NONE (gp_dbase.c:887) \226\134\146 target of NEITHER CAS(==1) nor\n        -- BAI(>1); air_attack_strength = 6 (gp_dbase.c:896, NOT the ==10 the generator SEAD wants at\n        -- highlevl.c:1981) \226\134\146 not a generator-SEAD target. Per-keysite point DENSITY is MAP population\n        -- DATA (not in the C tree), so `firing_points` counts are a DOCUMENTED DESIGNER PROXY (0 opts a\n        -- class out). FREE OOB placement (population-placed, never force-reserve hardware). MG types are a\n        -- proxy for the building-mounted VEHICLE_*_FIRING_POINT posts (no DCS equivalent) \226\128\148 reuse the\n        -- verified infantry patrol soldiers; MANPAD = INFANTRY_SAM soldier (FORMCOMP.DAT:621/:622).\n        firing_points = { airbase = 4, farp = 2, installation = 2 },  -- DESIGNER proxy for popread FP density\n        mg     = { blue = \"Soldier M4\",     red = \"Infantry AK\" },        -- MG post proxy (verified soldiers)\n        manpad = { blue = \"Soldier stinger\", red = \"SA-18 Igla manpad\" }, -- INFANTRY_SAM (LIVE-DB-VERIFIED)\n    },\n}\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Merge + re-key machinery\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n\n-- A \"sequence\" (array) = a table whose keys are exactly 1..n. Arrays REPLACE wholesale on merge.\nlocal function is_seq(t)\n    local n = 0\n    for k in pairs(t) do\n        if type(k) ~= \"number\" then return false end\n        n = n + 1\n    end\n    return n > 0 and #t == n\nend\n\n-- Deep-merge `over` onto `base`: maps merge per key, arrays replace wholesale, scalars replace.\nlocal function deep_merge(base, over)\n    if type(base) ~= \"table\" or type(over) ~= \"table\" then return over end\n    if is_seq(over) then return over end\n    local out = {}\n    for k, v in pairs(base) do out[k] = v end\n    for k, v in pairs(over) do\n        if type(v) == \"table\" and type(out[k]) == \"table\" and not is_seq(v) then\n            out[k] = deep_merge(out[k], v)\n        else\n            out[k] = v\n        end\n    end\n    return out\nend\n\n-- Deep-copy while re-keying the string side keys \"blue\"/\"red\" \226\134\146 coalition.side numbers. No other key\n-- in the schema is ever the string \"blue\"/\"red\", so a generic remap is safe.\n-- SIDE-KEY TYPO GUARD: only lowercase \"blue\"/\"red\" re-key. A leftover key that merely LOOKS like a\n-- side (\"BLUE\", \"Red\", \"neutral\") would otherwise be silently carried through and never read \226\128\148 the\n-- author's override would be a silent no-op. Warn loudly instead (accepted forms named).\nlocal SIDE_OF = { blue = BLUE, red = RED }\nlocal function build(v, path)\n    if type(v) ~= \"table\" then return v end\n    local out = {}\n    for k, val in pairs(v) do\n        if type(k) == \"string\" and not SIDE_OF[k] then\n            local lk = string.lower(k)\n            if lk == \"blue\" or lk == \"red\" or lk == \"neutral\" or lk == \"neutrals\" then\n                cs.dbg(\"config\", \"INVALID: side key %q at %s ignored (accepted side keys are \"\n                    .. \"\\\"blue\\\"/\\\"red\\\", lowercase) \226\128\148 that override is a NO-OP\", k, path or \"<root>\")\n            end\n        end\n        out[SIDE_OF[k] or k] = build(val, (path and (path .. \".\") or \"\") .. tostring(k))\n    end\n    return out\nend\n\n-- Count leaf values in a table (for the \"K user overrides applied\" summary).\nlocal function count_leaves(t)\n    if type(t) ~= \"table\" then return 1 end\n    local n = 0\n    for _, v in pairs(t) do n = n + count_leaves(v) end\n    return n\nend\n\n-- Merge the author override (if any) and expose both the ACTIVE config (C) and a pristine DEFAULT\n-- view (used as the fallback source during validation).\nlocal user_cfg = (type(_G.DMT_CONFIG) == \"table\") and _G.DMT_CONFIG or nil\n-- deep_merge on string-keyed DEFAULTS + string-keyed user, THEN re-key to coalition.side.\nlocal merged = deep_merge(DEFAULTS, user_cfg or {})\nM.C   = build(merged)         -- ACTIVE config, coalition.side-keyed\nM.DEF = build(DEFAULTS)       -- pristine defaults, coalition.side-keyed (fallback source)\n_G.DMT_ACTIVE_CONFIG = M.C\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Validation (config.load_and_validate) \226\128\148 DB-checks types, structure-checks the rest, falls bad\n-- user overrides back to defaults, and warns loudly if a DEFAULT type itself is missing.\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n\nlocal KNOWN_ROLES = { striker = true, escort = true, heli = true, recon = true, transport = true, vehicle = true }\nlocal KNOWN_CATS  = { Fortifications = true, Warehouses = true, Cargos = true, Heliports = true, Fortification = true, GroundVehicles = true }\n\nlocal function db_exists(name)\n    if type(name) ~= \"string\" then return false end\n    local ok, desc = pcall(Unit.getDescByName, name)\n    if not ok or type(desc) ~= \"table\" then return false end\n    -- This DCS build returns a STUB table for UNKNOWN types (echoes typeName back, ~5 keys,\n    -- EMPTY displayName, no attributes) instead of nil \226\128\148 live-caught when \"F-99 Bogus\" passed\n    -- validation and became BLUE's active striker. A REAL desc always carries a non-empty\n    -- displayName and a populated attributes table; require either signal to count as existing.\n    local dn = desc.displayName\n    if type(dn) == \"string\" and #dn > 0 then return true end\n    local at = desc.attributes\n    if type(at) == \"table\" and next(at) ~= nil then return true end\n    return false\nend\n\nlocal function deep_copy(v)\n    if type(v) ~= \"table\" then return v end\n    local out = {}\n    for k, val in pairs(v) do out[k] = deep_copy(val) end\n    return out\nend\n\nlocal function deep_equal(a, b)\n    if type(a) ~= \"table\" or type(b) ~= \"table\" then return a == b end\n    for k, v in pairs(a) do if not deep_equal(v, b[k]) then return false end end\n    for k, v in pairs(b) do if a[k] == nil then return false end end\n    return true\nend\n\n-- Set of valid country ids (values of country.id).\nlocal function valid_country_ids()\n    local set = {}\n    if type(country) == \"table\" and type(country.id) == \"table\" then\n        for _, id in pairs(country.id) do set[id] = true end\n    end\n    return set\nend\n\nfunction M.load_and_validate(log_fn)\n    log_fn = log_fn or function() end\n    local C, DEF = M.C, M.DEF\n\n    -- \226\148\128\226\148\128 Branch type-guards (resilient boot) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- A scalar where a TABLE is expected (e.g. DMT_CONFIG.types.aircraft.blue = \"F-16\", or\n    -- countries = \"USA\") survives deep_merge and would crash the section loops / write-back paths\n    -- below (\"attempt to index a string\"), aborting the whole boot. Guard every branch first: a\n    -- wrong-typed branch is logged INVALID and replaced by a deep copy of its DEFAULT subtree, then\n    -- leaf validation proceeds normally.\n    local function ensure_table(container, key, defval, path)\n        if type(container[key]) ~= \"table\" then\n            cs.dbg(\"config\", \"INVALID: %s = %s (expected table) \226\128\148 using default subtree\",\n                path, tostring(container[key]))\n            container[key] = deep_copy(defval)\n        end\n        return container[key]\n    end\n    ensure_table(C, \"types\", DEF.types, \"types\")\n    ensure_table(C.types, \"aircraft\", DEF.types.aircraft, \"types.aircraft\")\n    ensure_table(C.types, \"ground\",   DEF.types.ground,   \"types.ground\")\n    for _, side in ipairs({ BLUE, RED }) do\n        local sname = cs.SIDE_NAME[side]\n        ensure_table(C.types.aircraft, side, DEF.types.aircraft[side], \"types.aircraft.\" .. sname)\n    end\n    for _, k in ipairs({ \"primary_slots\", \"secondary_slots\", \"arty_slots\", \"mlrs_slots\",\n                         \"infantry\", \"garrison\", \"ewr\", \"aaa\", \"sam\" }) do\n        ensure_table(C.types.ground, k, DEF.types.ground[k], \"types.ground.\" .. k)\n    end\n    ensure_table(C, \"statics\", DEF.statics, \"statics\")\n    ensure_table(C.statics, \"kinds\",   DEF.statics.kinds,   \"statics.kinds\")\n    ensure_table(C.statics, \"palette\", DEF.statics.palette, \"statics.palette\")\n    -- (statics.farp has its own structural check below; palette/kind ENTRIES are guarded in their loops)\n    ensure_table(C, \"payloads\", DEF.payloads, \"payloads\")\n    for _, side in ipairs({ BLUE, RED }) do\n        ensure_table(C.payloads, side, DEF.payloads[side], \"payloads.\" .. cs.SIDE_NAME[side])\n    end\n    ensure_table(C, \"reserves\", DEF.reserves, \"reserves\")\n    ensure_table(C.reserves, \"per_base\", DEF.reserves.per_base, \"reserves.per_base\")\n    ensure_table(C, \"countries\", DEF.countries, \"countries\")\n    ensure_table(C, \"theatre\",   DEF.theatre,   \"theatre\")\n    ensure_table(C, \"defenses\",  DEF.defenses,  \"defenses\")\n    ensure_table(C.defenses, \"groups_per\",    DEF.defenses.groups_per,    \"defenses.groups_per\")\n    ensure_table(C.defenses, \"firing_points\", DEF.defenses.firing_points, \"defenses.firing_points\")\n    ensure_table(C.defenses, \"group\",         DEF.defenses.group,         \"defenses.group\")\n    ensure_table(C.defenses, \"mg\",            DEF.defenses.mg,            \"defenses.mg\")\n    ensure_table(C.defenses, \"manpad\",        DEF.defenses.manpad,        \"defenses.manpad\")\n    for _, side in ipairs({ BLUE, RED }) do\n        ensure_table(C.defenses.group,  side, DEF.defenses.group[side],  \"defenses.group.\"  .. cs.SIDE_NAME[side])\n    end\n\n    local ok_names, missing = {}, {}   -- sets of type-name \226\134\146 true\n    local function note(names)         -- DB-check a list of names into ok/missing sets\n        for _, n in ipairs(names) do\n            if db_exists(n) then ok_names[n] = true else missing[n] = true end\n        end\n    end\n    local function names_scalar(v) return (type(v) == \"string\") and { v } or {} end\n    local function names_strlist(v)\n        local o = {}\n        if type(v) == \"table\" then for _, n in ipairs(v) do if type(n) == \"string\" then o[#o + 1] = n end end end\n        return o\n    end\n    local function names_rows(v)   -- array of {BLUE, RED} slot rows\n        local o = {}\n        if type(v) == \"table\" then for _, row in ipairs(v) do\n            if type(row) == \"table\" then o[#o + 1] = row[1]; o[#o + 1] = row[2] end\n        end end\n        return o\n    end\n    -- Validate one leaf: DB-check its type names; if a USER override is bad, log INVALID and fall the\n    -- whole leaf back to its default, then account the default's names into ok/missing.\n    local function validate_leaf(container, key, defval, path, extract)\n        local cur = container[key]\n        local bad = {}\n        for _, n in ipairs(extract(cur)) do if not db_exists(n) then bad[#bad + 1] = n end end\n        if #bad == 0 then note(extract(cur)); return end\n        if not deep_equal(cur, defval) then\n            cs.dbg(\"config\", \"INVALID: %s = %s (unknown unit type: %s) \226\128\148 using default\",\n                path, (type(cur) == \"table\" and \"[array]\" or tostring(cur)), table.concat(bad, \", \"))\n            container[key] = defval\n            note(extract(defval))\n        else\n            for _, n in ipairs(bad) do missing[n] = true end\n            for _, n in ipairs(extract(cur)) do if db_exists(n) then ok_names[n] = true end end\n        end\n    end\n\n    -- \226\148\128\226\148\128 Aircraft roster (per side, per role) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    for _, side in ipairs({ BLUE, RED }) do\n        local sname = cs.SIDE_NAME[side]\n        local ac, dac = C.types.aircraft[side], DEF.types.aircraft[side]\n        for _, role in ipairs({ \"striker\", \"escort\", \"recon\", \"attack_heli\", \"transport_heli\", \"transport_fw\", \"transport_fw_heavy\", \"bda_heli\" }) do\n            validate_leaf(ac, role, dac[role], string.format(\"types.aircraft.%s.%s\", sname, role), names_scalar)\n        end\n    end\n\n    -- \226\148\128\226\148\128 Ground: slot rows (shared arrays), per-side infantry/garrison/ewr/aaa/sam \226\148\128\226\148\128\n    validate_leaf(C.types.ground, \"primary_slots\",   DEF.types.ground.primary_slots,   \"types.ground.primary_slots\",   names_rows)\n    validate_leaf(C.types.ground, \"secondary_slots\", DEF.types.ground.secondary_slots, \"types.ground.secondary_slots\", names_rows)\n    validate_leaf(C.types.ground, \"arty_slots\",    DEF.types.ground.arty_slots,    \"types.ground.arty_slots\",    names_rows)\n    validate_leaf(C.types.ground, \"mlrs_slots\",    DEF.types.ground.mlrs_slots,    \"types.ground.mlrs_slots\",    names_rows)\n    for _, side in ipairs({ BLUE, RED }) do\n        local sname = cs.SIDE_NAME[side]\n        local g, dg = C.types.ground, DEF.types.ground\n        validate_leaf(g.infantry,     side, dg.infantry[side],     \"types.ground.infantry.\"     .. sname, names_scalar)\n        validate_leaf(g.garrison,     side, dg.garrison[side],     \"types.ground.garrison.\"     .. sname, names_strlist)\n        validate_leaf(g.ewr,          side, dg.ewr[side],          \"types.ground.ewr.\"          .. sname, names_scalar)\n        validate_leaf(g.aaa,          side, dg.aaa[side],          \"types.ground.aaa.\"          .. sname, names_scalar)\n        validate_leaf(g.sam,          side, dg.sam[side],          \"types.ground.sam.\"          .. sname, names_strlist)\n    end\n\n    -- \226\148\128\226\148\128 Statics: STRUCTURE only (a DB type query is NOT spawn proof \226\128\148 2026-07-06 crash saga) \226\148\128\226\148\128\n    for kind, spec in pairs(C.statics.kinds) do\n        if type(spec) ~= \"table\" then\n            cs.dbg(\"config\", \"INVALID: statics.kinds.%s = %s (expected table) \226\128\148 using default\",\n                tostring(kind), tostring(spec))\n            C.statics.kinds[kind] = deep_copy(DEF.statics.kinds[kind])   -- nil default drops the entry\n            spec = C.statics.kinds[kind]\n        end\n        if spec and spec.spawn == \"static\" then\n            if type(spec.type) ~= \"string\" or type(spec.shape) ~= \"string\" or type(spec.cat) ~= \"string\" then\n                cs.dbg(\"config\", \"INVALID: statics.kinds.%s (missing type/shape/cat triple) \226\128\148 using default\", tostring(kind))\n                C.statics.kinds[kind] = DEF.statics.kinds[kind]\n            elseif not KNOWN_CATS[spec.cat] then\n                cs.dbg(\"config\", \"INVALID: statics.kinds.%s.cat = %s (unknown category) \226\128\148 using default\", tostring(kind), tostring(spec.cat))\n                C.statics.kinds[kind].cat = DEF.statics.kinds[kind] and DEF.statics.kinds[kind].cat or spec.cat\n            end\n        end\n    end\n    for token, tri in pairs(C.statics.palette) do\n        if type(tri) ~= \"table\" or type(tri[1]) ~= \"string\" or type(tri[2]) ~= \"string\" or not KNOWN_CATS[tri[3]] then\n            cs.dbg(\"config\", \"INVALID: statics.palette.%s (bad type|shape|category triple) \226\128\148 using default\", tostring(token))\n            C.statics.palette[token] = DEF.statics.palette[token]\n        end\n    end\n    if type(C.statics.farp) ~= \"table\" or type(C.statics.farp.type) ~= \"string\"\n       or type(C.statics.farp.shape_name) ~= \"string\" or not KNOWN_CATS[C.statics.farp.category] then\n        cs.dbg(\"config\", \"INVALID: statics.farp (bad type/shape_name/category) \226\128\148 using default\")\n        C.statics.farp = DEF.statics.farp\n    end\n    cs.dbg(\"config\", \"statics/payloads are STRUCTURE-validated only (type triples + CLSIDs are spawn-time-verified, \"\n        .. \"not queryable from the mission env)\")\n\n    -- \226\148\128\226\148\128 Payloads: STRUCTURE only (no CLSID enumeration API) \226\148\128\226\148\128\n    for _, side in ipairs({ BLUE, RED }) do\n        local sname = cs.SIDE_NAME[side]\n        for _, role in ipairs({ \"striker\", \"escort\", \"attack_heli\" }) do\n            local pl = C.payloads[side] and C.payloads[side][role]\n            local structurally_ok = type(pl) == \"table\"\n            if structurally_ok then\n                for _, p in ipairs(pl) do\n                    if type(p) ~= \"table\" or type(p.CLSID) ~= \"string\" then structurally_ok = false; break end\n                end\n            end\n            if not structurally_ok then\n                cs.dbg(\"config\", \"INVALID: payloads.%s.%s (not a pylon list of {CLSID=string}) \226\128\148 using default\", sname, role)\n                if C.payloads[side] then C.payloads[side][role] = DEF.payloads[side][role] end\n            end\n        end\n    end\n\n    -- \226\148\128\226\148\128 Reserves: known role names, numbers >= 0 \226\148\128\226\148\128\n    for role, n in pairs(C.reserves.per_base) do\n        if not KNOWN_ROLES[role] then\n            cs.dbg(\"config\", \"INVALID: reserves.per_base.%s (unknown role) \226\128\148 dropping\", tostring(role))\n            C.reserves.per_base[role] = nil\n        elseif type(n) ~= \"number\" or n < 0 then\n            cs.dbg(\"config\", \"INVALID: reserves.per_base.%s = %s (must be number >= 0) \226\128\148 using default\", tostring(role), tostring(n))\n            C.reserves.per_base[role] = DEF.reserves.per_base[role]\n        end\n    end\n    for _, key in ipairs({ \"farp_heli\", \"farp_transport\" }) do\n        if type(C.reserves[key]) ~= \"number\" or C.reserves[key] < 0 then\n            cs.dbg(\"config\", \"INVALID: reserves.%s = %s (must be number >= 0) \226\128\148 using default\", key, tostring(C.reserves[key]))\n            C.reserves[key] = DEF.reserves[key]\n        end\n    end\n\n    -- \226\148\128\226\148\128 Countries: valid country.id values \226\148\128\226\148\128\n    local valid_cid = valid_country_ids()\n    for _, side in ipairs({ BLUE, RED }) do\n        local sname = cs.SIDE_NAME[side]\n        if not valid_cid[C.countries[side]] then\n            cs.dbg(\"config\", \"INVALID: countries.%s = %s (not a country.id value) \226\128\148 using default\", sname, tostring(C.countries[side]))\n            C.countries[side] = DEF.countries[side]\n        end\n    end\n\n    -- \226\148\128\226\148\128 Mode selector: \"campaign\" | \"skirmish\" (else default). campaign_mode.lua already falls back\n    --    defensively, but sanitise + log here so a typo is visible and C.mode is a clean value. \226\148\128\226\148\128\n    if C.mode ~= \"campaign\" and C.mode ~= \"skirmish\" then\n        cs.dbg(\"config\", \"INVALID: mode = %s (must be \\\"campaign\\\" or \\\"skirmish\\\") \226\128\148 using default\",\n            tostring(C.mode))\n        C.mode = DEF.mode\n    end\n\n    -- \226\148\128\226\148\128 Theatre knobs: numeric >= 0 (fixed_wing_per_side additionally an integer) \226\148\128\226\148\128\n    -- Without this a string front_dist would only crash much later, at ground_forces frontline-scan\n    -- time \226\128\148 far from the author's mistake. Mirror the reserves loop: INVALID log + default fallback.\n    for _, key in ipairs({ \"fixed_wing_per_side\", \"front_dist\", \"farp_front_dist\" }) do\n        local v = C.theatre[key]\n        if type(v) ~= \"number\" or v < 0 then\n            cs.dbg(\"config\", \"INVALID: theatre.%s = %s (must be number >= 0) \226\128\148 using default\", key, tostring(v))\n            C.theatre[key] = DEF.theatre[key]\n        end\n    end\n    if C.theatre.fixed_wing_per_side ~= math.floor(C.theatre.fixed_wing_per_side) then\n        cs.dbg(\"config\", \"INVALID: theatre.fixed_wing_per_side = %s (must be an integer) \226\128\148 using default\",\n            tostring(C.theatre.fixed_wing_per_side))\n        C.theatre.fixed_wing_per_side = DEF.theatre.fixed_wing_per_side\n    end\n    if type(C.theatre.farp_activation) ~= \"boolean\" then\n        cs.dbg(\"config\", \"INVALID: theatre.farp_activation = %s (must be boolean) \226\128\148 using default\",\n            tostring(C.theatre.farp_activation))\n        C.theatre.farp_activation = DEF.theatre.farp_activation\n    end\n\n    -- \226\148\128\226\148\128 Persistence: bool enabled, numeric autosave_period > 0, string slot/db_path \226\148\128\226\148\128\n    ensure_table(C, \"persistence\", DEF.persistence, \"persistence\")\n    if type(C.persistence.enabled) ~= \"boolean\" then\n        cs.dbg(\"config\", \"INVALID: persistence.enabled = %s (must be boolean) \226\128\148 using default\",\n            tostring(C.persistence.enabled))\n        C.persistence.enabled = DEF.persistence.enabled\n    end\n    if type(C.persistence.autosave_period) ~= \"number\" or C.persistence.autosave_period <= 0 then\n        cs.dbg(\"config\", \"INVALID: persistence.autosave_period = %s (must be number > 0) \226\128\148 using default\",\n            tostring(C.persistence.autosave_period))\n        C.persistence.autosave_period = DEF.persistence.autosave_period\n    end\n    for _, key in ipairs({ \"slot\", \"db_path\" }) do\n        if type(C.persistence[key]) ~= \"string\" or #C.persistence[key] == 0 then\n            cs.dbg(\"config\", \"INVALID: persistence.%s = %s (must be non-empty string) \226\128\148 using default\",\n                key, tostring(C.persistence[key]))\n            C.persistence[key] = DEF.persistence[key]\n        end\n    end\n\n    -- \226\148\128\226\148\128 Defenses: per-side ring composition (DB-checked types), counts + radius (numbers >= 0) \226\148\128\226\148\128\n    for _, side in ipairs({ BLUE, RED }) do\n        validate_leaf(C.defenses.group,  side, DEF.defenses.group[side],\n            \"defenses.group.\"  .. cs.SIDE_NAME[side], names_strlist)\n        -- Firing-point unit types: single DCS type per side each (MG post + MANPAD soldier).\n        validate_leaf(C.defenses.mg,     side, DEF.defenses.mg[side],\n            \"defenses.mg.\"     .. cs.SIDE_NAME[side], names_scalar)\n        validate_leaf(C.defenses.manpad, side, DEF.defenses.manpad[side],\n            \"defenses.manpad.\" .. cs.SIDE_NAME[side], names_scalar)\n    end\n    for _, key in ipairs({ \"airbase\", \"farp\", \"installation\" }) do\n        local v = C.defenses.groups_per[key]\n        if type(v) ~= \"number\" or v < 0 then\n            cs.dbg(\"config\", \"INVALID: defenses.groups_per.%s = %s (must be number >= 0) \226\128\148 using default\", key, tostring(v))\n            C.defenses.groups_per[key] = DEF.defenses.groups_per[key]\n        end\n        local fv = C.defenses.firing_points[key]\n        if type(fv) ~= \"number\" or fv < 0 then\n            cs.dbg(\"config\", \"INVALID: defenses.firing_points.%s = %s (must be number >= 0) \226\128\148 using default\", key, tostring(fv))\n            C.defenses.firing_points[key] = DEF.defenses.firing_points[key]\n        end\n    end\n    if type(C.defenses.ring_radius) ~= \"number\" or C.defenses.ring_radius < 0 then\n        cs.dbg(\"config\", \"INVALID: defenses.ring_radius = %s (must be number >= 0) \226\128\148 using default\", tostring(C.defenses.ring_radius))\n        C.defenses.ring_radius = DEF.defenses.ring_radius\n    end\n\n    -- \226\148\128\226\148\128 Cross-checks: every side has the required aircraft roles; slot tables non-empty w/ both columns \226\148\128\226\148\128\n    for _, side in ipairs({ BLUE, RED }) do\n        local sname = cs.SIDE_NAME[side]\n        for _, role in ipairs({ \"striker\", \"escort\", \"recon\", \"attack_heli\", \"transport_heli\", \"transport_fw\" }) do\n            if type(C.types.aircraft[side][role]) ~= \"string\" then\n                cs.dbg(\"config\", \"INVALID: types.aircraft.%s.%s missing (required role) \226\128\148 using default\", sname, role)\n                C.types.aircraft[side][role] = DEF.types.aircraft[side][role]\n            end\n        end\n    end\n    for _, sk in ipairs({ \"primary_slots\", \"secondary_slots\", \"arty_slots\", \"mlrs_slots\" }) do\n        local rows = C.types.ground[sk]\n        local ok = type(rows) == \"table\" and #rows > 0\n        if ok then\n            for _, row in ipairs(rows) do\n                if type(row) ~= \"table\" or type(row[1]) ~= \"string\" or type(row[2]) ~= \"string\" then ok = false; break end\n            end\n        end\n        if not ok then\n            cs.dbg(\"config\", \"INVALID: types.ground.%s (empty or missing a side column) \226\128\148 using default\", sk)\n            C.types.ground[sk] = DEF.types.ground[sk]\n        end\n    end\n\n    -- \226\148\128\226\148\128 Tally + report \226\148\128\226\148\128\n    local n_ok, n_missing = 0, 0\n    for _ in pairs(ok_names)  do n_ok = n_ok + 1 end\n    local missing_list = {}\n    for name in pairs(missing) do if not ok_names[name] then n_missing = n_missing + 1; missing_list[#missing_list + 1] = name end end\n    local n_over = user_cfg and count_leaves(user_cfg) or 0\n\n    -- A DEFAULT type that fails the DB check = a module/mod not installed (e.g. the AH-64D incident):\n    -- LOUD warning + on-screen outText, because those spawns will silently fail until the module loads.\n    if n_missing > 0 then\n        table.sort(missing_list)\n        local list = table.concat(missing_list, \", \")\n        local warn = string.format(\"[dmt:config] WARNING: %d unit type(s) NOT in this DCS install's DB: %s. \"\n            .. \"Their spawns will FAIL. Fix: install the module OR place ONE such unit in the .miz to \"\n            .. \"preload it. Boot continues (spawn refunds keep the economy safe).\", n_missing, list)\n        env.info(warn)\n        log_fn(warn)\n        pcall(function() trigger.action.outText(warn, 30) end)\n    end\n\n    local summary = string.format(\"[dmt:config] validated: %d unit types OK, %d unknown, %d user overrides applied\",\n        n_ok, n_missing, n_over)\n    env.info(summary)\n    log_fn(summary)\n    if n_missing > 0 then\n        pcall(function() trigger.action.outText(summary, 20) end)\n    end\n    cs.dbg(\"config\", \"load_and_validate complete: ok=%d missing=%d overrides=%d (user_cfg=%s)\",\n        n_ok, n_missing, n_over, tostring(user_cfg ~= nil))\n\n    return M.C\nend\n\nreturn M\n"
__modules["croute"] = "-- croute.lua\n-- Inspired by:\n--   aphavoc/source/ai/taskgen/croute.c   BIASED ROUTE GENERATOR \226\128\148 the whole file.\n--     route_biasing_database[MOVEMENT_TYPE_AIR]  (croute.c:126-135)  the AIR profile constants\n--     create_route / generate_best_mid_point     (croute.c:1242-1309) recursive perpendicular search\n--     get_best_point                             (croute.c:1315-1458) sample the perpendicular sweep\n--     get_route_point_rating                     (croute.c:1502-1553) elevation + range + side cost\n--     second_past_route                          (croute.c:1464-1496) one smoothing re-optimise pass\n--     optimise_route                             (croute.c:1559-1669) prune near-colinear nodes\n--     generate_biased_vec3d_route                (croute.c:1132-1236) per-leg driver + stitch\n--\n-- WHY: EECH does NOT fly straight lines between keysites. Every AI air/heli group's route is run\n-- through this biased generator, which recursively drops nav nodes onto the LOWEST terrain, nearest\n-- OWN territory, near the leg centreline \226\128\148 i.e. valley-following, enemy-sector-avoiding, dispersed\n-- routes. The port previously flew depart->target->RTB as three points (a straight \"kill corridor\");\n-- this module reproduces the EECH algorithm so every builder's legs bend through cover.\n--\n-- SCOPE: this module is PURE route geometry (no spawning, no DCS group calls). `M.biased_route`\n-- ports create_route+second_past_route+optimise_route for ONE leg; `M.expand` walks a DCS `points`\n-- list and stitches biased nav points between consecutive waypoints (the generate_biased_vec3d_route\n-- multi-leg loop). All airborne movement is MOVEMENT_TYPE_AIR in EECH (group_database movement_type\n-- for aircraft/helicopters), so there is a single profile \226\128\148 no config, no scenario data: these are\n-- EECH C constants, cited above.\n--\n-- PORT DEVIATIONS (documented, not invented):\n--  * sector_side proxy: EECH reads get_local_sector_entity(test_point)->SECTOR_SIDE (croute.c:1534-1536)\n--    off its fine authored sector grid. The port has no sector grid \226\128\148 bases ARE the sectors (the same\n--    convention campaign_state.route_difficulty uses, task.c:876). So sector_side(test_point) = owner of\n--    the NEAREST base. nil owner (no base / unowned) -> treated as NOT own side (biased against), per spec.\n--  * elevation: EECH get_3d_terrain_elevation (croute.c:1389) -> DCS pcall(land.getHeight,{x,y=z}); a\n--    failed/out-of-map probe defaults to 0 (then max(avg,0), matching croute.c:1526). Memoised per\n--    biased_route call (quantised key) to bound land.getHeight to ~one probe per distinct sample point.\n--  * hard recursion depth cap (DEPTH_CAP): min_route_range (5000 m, croute.c:1347) is the REAL\n--    terminator \226\128\148 a leg subdivides until each half is <= 5 km. The depth cap is only a safety bound so a\n--    pathological/degenerate leg can never recurse unboundedly; at 5 km termination a 100 km leg reaches\n--    depth ~5, so DEPTH_CAP=6 is never the binding limit on real routes.\n--  * nav points are NOT land-snapped: they are flown at cruise altitude (nav waypoints), so they may sit\n--    over water/steep ground exactly as EECH's do (EECH never snaps nav nodes either; only the elevation\n--    RATING cares about terrain height).\n--  * per-leg nav cap (MAX_NAV_PER_LEG): a DCS route table safety cap (DCS is fine to ~20 points/route;\n--    we keep <=8 inserted nav points per leg after the optimise prune). Not an EECH constant; on real\n--    legs the colinear prune already yields ~3-8, so this only guards degenerate long legs.\n\nlocal cs = require(\"campaign_state\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- \226\148\128\226\148\128 AIR movement profile (croute.c:126-135, route_biasing_database[MOVEMENT_TYPE_AIR]) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal ELEVATION_BIAS   = 5.0      -- elevation bias   (croute.c:128)\nlocal RANGE_BIAS       = 0.5      -- range bias       (croute.c:129)\nlocal SIDE_BIAS        = 1.0      -- side bias        (croute.c:130)\nlocal MIN_ROUTE_RANGE  = 5000.0   -- min route range  (croute.c:131) \226\128\148 legs at/under this are not split\nlocal DEVIATION_SIZE   = 3.0      -- route deviation size (croute.c:132)\nlocal NUM_SAMPLES      = 8        -- num route samples   (croute.c:133)\nlocal OPT_TOLERANCE    = 0.94     -- optimise tolerance  (croute.c:134) \226\128\148 |cos angle| above this = colinear\n\nlocal DEPTH_CAP        = 6        -- safety bound (see header); min_route_range is the real terminator\nlocal MAX_NAV_PER_LEG  = 8        -- DCS route-table safety cap on inserted nav points per leg (see header)\n\n-- \226\148\128\226\148\128 sector_side proxy: owner of the nearest base to a test point \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors get_local_sector_entity(test_point)->INT_TYPE_SECTOR_SIDE (croute.c:1534-1536) onto the\n-- port's bases-as-sectors grid (same nearest-base scan as campaign_state.route_difficulty). Returns the\n-- coalition side owning the nearest base, or nil when none is found / it is unowned.\nlocal function sector_side(x, z)\n    local best, best_d2 = nil, math.huge\n    for name, bpos in pairs(S.base_pos) do\n        local dx, dz = x - bpos.x, z - bpos.z\n        local d2 = dx * dx + dz * dz\n        if d2 < best_d2 then best_d2 = d2; best = name end\n    end\n    if not best then return nil end\n    return S.base_owner[best]   -- may be nil (unowned) -> caller treats nil as NOT own side\nend\n\n-- \226\148\128\226\148\128 biased_route(start_pos, end_pos, side) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Ports create_route -> generate_best_mid_point (recursive), then second_past_route, then\n-- optimise_route for ONE leg. start_pos/end_pos are world { x = north, z = east }. Returns an array of\n-- intermediate nav points { {x=,z=}, ... } in world coords (EXCLUDING the two endpoints, which the\n-- caller already has as real waypoints). Possibly empty for legs at/under MIN_ROUTE_RANGE.\nfunction M.biased_route(start_pos, end_pos, side)\n    -- per-call terrain memo: quantise to 1 m so identical sample points reuse one land.getHeight probe\n    local elev_cache = {}\n    local function terrain_h(x, z)\n        local kx, kz = math.floor(x + 0.5), math.floor(z + 0.5)\n        local key = kx * 100000 + kz\n        local h = elev_cache[key]\n        if h == nil then\n            local ok, v = pcall(land.getHeight, { x = x, y = z })\n            h = (ok and type(v) == \"number\") and v or 0.0\n            elev_cache[key] = h\n        end\n        return h\n    end\n\n    -- get_route_point_rating (croute.c:1502-1553). `elev` is the 1..NUM_SAMPLES perpendicular elevation\n    -- window; sample_number is 1-based. LOWER rating wins (low terrain + own side + near centreline).\n    local function point_rating(sample_number, x, z, elev)\n        -- 3-sample averaging window, clamped to [1, NUM_SAMPLES] (croute.c:1520-1524)\n        local lo = math.max(sample_number - 1, 1)\n        local hi = math.min(sample_number + 1, NUM_SAMPLES)\n        local avg = (elev[sample_number] + elev[lo] + elev[hi]) / 3.0\n        if avg < 0.0 then avg = 0.0 end                          -- max(avg,0) (croute.c:1526)\n        local elevation = ELEVATION_BIAS * avg                   -- croute.c:1528\n        -- range bias: |2s - N| / (2N) \226\128\148 minimised near the centre sample (croute.c:1530-1532)\n        local range_bias = RANGE_BIAS * math.abs((2.0 * sample_number) - NUM_SAMPLES) / (NUM_SAMPLES * 2.0)\n        local ss = sector_side(x, z)                             -- croute.c:1534-1536\n        local side_bias = (ss ~= side) and SIDE_BIAS or 0.0      -- (sector_side != side) (croute.c:1538)\n        local w = (avg > 1.0) and avg or 1.0                     -- max(avg,1.0) (croute.c:1541-1542)\n        return elevation + (range_bias * w) + (side_bias * w)    -- croute.c:1540-1542\n    end\n\n    -- get_best_point (croute.c:1315-1458). Returns {x=,z=} of the lowest-rated perpendicular sample, or\n    -- nil when the leg is at/under MIN_ROUTE_RANGE (no midpoint \226\128\148 the recursion terminator).\n    local function get_best_point(ax, az, bx, bz)\n        local dx, dz = bx - ax, bz - az\n        local sqr = dx * dx + dz * dz\n        if sqr <= (MIN_ROUTE_RANGE * MIN_ROUTE_RANGE) then return nil end   -- croute.c:1347\n\n        -- perpendicular to the leg (croute.c:1350-1356)\n        local test_x = dz\n        local test_z = -dx\n        -- per-sample increment along the perpendicular (croute.c:1359-1360)\n        local inc_x = test_x / (NUM_SAMPLES * DEVIATION_SIZE)\n        local inc_z = test_z / (NUM_SAMPLES * DEVIATION_SIZE)\n        -- leg mid point (croute.c:1363-1365)\n        local mid_x = ax + dx * 0.5\n        local mid_z = az + dz * 0.5\n        -- first sample position: mid - inc*(NUM_SAMPLES*0.5) (croute.c:1368-1369) => offsets -4..+3 inc\n        local sx = mid_x - inc_x * (NUM_SAMPLES * 0.5)\n        local sz = mid_z - inc_z * (NUM_SAMPLES * 0.5)\n\n        -- gather terrain elevations across the sweep, index 1..NUM_SAMPLES (croute.c:1376-1398)\n        local elev = {}\n        local tx, tz = sx, sz\n        for i = 1, NUM_SAMPLES do\n            elev[i] = terrain_h(tx, tz)\n            tx = tx + inc_x\n            tz = tz + inc_z\n        end\n\n        -- rate each sample, keep the lowest (croute.c:1400-1439)\n        tx, tz = sx, sz\n        local best_rating = point_rating(1, tx, tz, elev)\n        local best_x, best_z = tx, tz\n        for i = 1, NUM_SAMPLES - 1 do            -- loop 1..N-1, rating sample_number i+1 (2..N)\n            tx = tx + inc_x\n            tz = tz + inc_z\n            local r = point_rating(i + 1, tx, tz, elev)\n            if r < best_rating then\n                best_rating = r\n                best_x, best_z = tx, tz\n            end\n        end\n        return { x = best_x, z = best_z }\n    end\n\n    -- build the node list: {start, interior..., end}. generate_best_mid_point recursion (croute.c:1275).\n    local nodes = { { x = start_pos.x, z = start_pos.z } }\n    local generated = 0\n\n    local function subdivide(ax, az, bx, bz, depth)\n        if depth >= DEPTH_CAP then return end            -- safety bound (min_route_range is the real stop)\n        local mid = get_best_point(ax, az, bx, bz)\n        if not mid then return end                       -- leg <= MIN_ROUTE_RANGE: no midpoint\n        subdivide(ax, az, mid.x, mid.z, depth + 1)       -- recurse first half (croute.c:1301)\n        nodes[#nodes + 1] = mid\n        generated = generated + 1\n        subdivide(mid.x, mid.z, bx, bz, depth + 1)        -- recurse second half (croute.c:1303)\n    end\n\n    subdivide(start_pos.x, start_pos.z, end_pos.x, end_pos.z, 0)\n    nodes[#nodes + 1] = { x = end_pos.x, z = end_pos.z }\n\n    -- second_past_route (croute.c:1464-1496): one forward smoothing pass \226\128\148 re-solve each interior node\n    -- against its (already-updated) neighbours. C ignores get_best_point's return; if it fails (a short\n    -- prev->next span) C would read an uninitialised best_point \226\128\148 the port instead leaves the node put\n    -- (the only sane reading of that latent C bug).\n    for i = 2, #nodes - 1 do\n        local prev, nxt = nodes[i - 1], nodes[i + 1]\n        local mid = get_best_point(prev.x, prev.z, nxt.x, nxt.z)\n        if mid then nodes[i] = mid end\n    end\n\n    -- optimise_route (croute.c:1559-1669): drop interior nodes that are (near-)colinear with their\n    -- neighbours \226\128\148 |cos(angle between the two normalised leg vectors)| > OPT_TOLERANCE, or a zero leg.\n    local i = 2\n    while i <= #nodes - 1 do\n        local prev, node, nxt = nodes[i - 1], nodes[i], nodes[i + 1]\n        local v1x, v1z = node.x - prev.x, node.z - prev.z\n        local v2x, v2z = nxt.x - node.x, nxt.z - node.z\n        local remove = false\n        local l1 = v1x * v1x + v1z * v1z\n        local l2 = v2x * v2x + v2z * v2z\n        if l1 == 0.0 or l2 == 0.0 then\n            remove = true                                 -- zero leg (croute.c:1589-1605)\n        else\n            local n1 = 1.0 / math.sqrt(l1)\n            local n2 = 1.0 / math.sqrt(l2)\n            local cos = (v1x * n1) * (v2x * n2) + (v1z * n1) * (v2z * n2)   -- dot of normalised (croute.c:1624)\n            if math.abs(cos) > OPT_TOLERANCE then remove = true end          -- croute.c:1626\n        end\n        if remove then\n            table.remove(nodes, i)                        -- delete node; re-test at same index\n        else\n            i = i + 1\n        end\n    end\n\n    -- collect interior nodes (exclude the two endpoints) as the biased nav points\n    local nav = {}\n    for k = 2, #nodes - 1 do\n        nav[#nav + 1] = { x = nodes[k].x, z = nodes[k].z }\n    end\n\n    -- DCS route-table safety cap: keep <= MAX_NAV_PER_LEG (even subsample to preserve spread). See header.\n    if #nav > MAX_NAV_PER_LEG then\n        local trimmed = {}\n        local step = #nav / MAX_NAV_PER_LEG\n        for k = 1, MAX_NAV_PER_LEG do\n            trimmed[k] = nav[math.min(#nav, math.floor((k - 0.5) * step) + 1)]\n        end\n        nav = trimmed\n    end\n\n    local leg_km = math.sqrt((end_pos.x - start_pos.x) ^ 2 + (end_pos.z - start_pos.z) ^ 2) / 1000.0\n    cs.dbg(\"croute\", \"leg %.1fkm: %d node(s) generated, %d after prune/cap\", leg_km, generated, #nav)\n    return nav\nend\n\n-- \226\148\128\226\148\128 expand(points, side, opts) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Ports the generate_biased_vec3d_route multi-leg loop (croute.c:1153-1229) onto a DCS `route.points`\n-- list: for every consecutive pair of waypoints, insert the biased nav points between them as\n-- \"Turning Point\" waypoints. `points` waypoints carry DCS coords (x=north, y=east); world pos of a\n-- waypoint is { x = wp.x, z = wp.y }. Inserted nav points fly at opts.alt / opts.speed / opts.alt_type\n-- (the group's cruise leg altitude/speed \226\128\148 EECH gives every generated nav node the member cruise\n-- altitude, croute.c:690). Returns a NEW points array (endpoints preserved, nav spliced between).\n--   opts = { alt=<m>, alt_type=\"BARO\"|\"RADIO\", speed=<m/s>, name=<prefix> }\nfunction M.expand(points, side, opts)\n    if type(points) ~= \"table\" or #points < 2 then return points end\n    opts = opts or {}\n    local alt      = opts.alt or 3000\n    local alt_type = opts.alt_type or \"BARO\"\n    local speed    = opts.speed or 200\n    local prefix   = opts.name or \"Nav\"\n\n    local out = {}\n    local seq = 0\n    for i = 1, #points - 1 do\n        out[#out + 1] = points[i]\n        local a = { x = points[i].x,     z = points[i].y }\n        local b = { x = points[i + 1].x, z = points[i + 1].y }\n        local nav = M.biased_route(a, b, side)\n        for j = 1, #nav do\n            seq = seq + 1\n            out[#out + 1] = {\n                type = \"Turning Point\", action = \"Turning Point\",\n                alt = alt, alt_type = alt_type, speed = speed,\n                ETA = 0, ETA_locked = false,\n                x = nav[j].x, y = nav[j].z,\n                name = prefix .. seq, formation_template = \"\",\n            }\n        end\n    end\n    out[#out + 1] = points[#points]\n    return out\nend\n\nreturn M\n"
__modules["farps"] = "-- farps.lua \226\128\148 base-role classification + forward FARP network\n-- EECH source:\n--   ks_dbase.c: AIRBASE (air_force_capacity LARGE, fixed-wing + heli, requires_cap TRUE, requires_\n--     barcap FALSE); FARP (air_force_capacity SMALL, HELICOPTERS ONLY).\n--   popread.c:1601-1664,1981-2019: airfields with fixed-wing runway routes are AIRBASEs, the rest are\n--     helicopter sites; FARP keysites are placed at forward FARP objects. EECH warzones field only a\n--     handful of fixed-wing airbases plus a dense field of heli-only bases and forward FARPs.\n--\n-- Two layers, both EECH-faithful:\n--  1) CLASSIFY the DCS airfields (PREDICTABLE structure): a fixed number per side (the REAR fields)\n--     run as fixed-wing AIRBASEs; the rest run as heli-only FOBs (\"FARP only behaviour\").\n--  2) Place a FORWARD FARP network (RANDOMNESS/variety): extra heli-only forward bases ahead of the\n--     line, jittered in position and count so each campaign's rotary staging differs.\n-- Enforcement is via the supply ledger: airbase = fixed-wing + heli; FOB/FARP = helicopters only. So\n-- fixed-wing (OCA / keysite strike / SEAD) launches ONLY from the few airbases, while the rotary war\n-- (CAS/BAI/insertion) flies from the whole FOB + FARP network \226\128\148 an EECH helicopter-primary front.\n\nlocal cs     = require(\"campaign_state\")\nlocal config = require(\"config\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- EECH warzones field only \"a couple\" of fixed-wing airbases per side. Cap (config theatre\n-- fixed_wing_per_side), and never more than a third of a side's fields, so the majority stay heli-only\n-- FOBs even on a small scoped theatre.\nlocal FIXED_WING_PER_SIDE = config.C.theatre.fixed_wing_per_side\nlocal function fixed_wing_count(side_field_count)\n    return math.max(1, math.min(FIXED_WING_PER_SIDE, math.floor(side_field_count / 3)))\nend\nlocal FRONT_DIST          = config.C.theatre.farp_front_dist   -- m; a base with an enemy within this is \"frontline\" (config theatre)\nlocal FARP_FWD_MIN        = 18000    -- m: forward-FARP distance ahead of the parent field (min)\nlocal FARP_FWD_MAX        = 40000    -- m: ... (max) \226\128\148 randomised per FARP\nlocal FARP_LATERAL        = 22000    -- m: max random lateral jitter along the front\nlocal FARP_CHANCE         = 70       -- % chance a given frontline field gets a forward FARP (variety)\n\nlocal COUNTRY = config.C.countries\n\n-- Nearest enemy base to `base` \226\134\146 (name, distance). math.huge if the enemy has none.\nlocal function nearest_enemy(base, side)\n    local bp = S.base_pos[base]\n    local enemy = cs.ENEMY[side]\n    if not bp or not enemy then return nil, math.huge end\n    local best, bestd = nil, math.huge\n    for name, owner in pairs(S.base_owner) do\n        if owner == enemy and S.base_pos[name] then\n            local ep = S.base_pos[name]\n            local d = cs.dist2d(bp.x, bp.z, ep.x, ep.z)\n            if d < bestd then bestd = d; best = name end\n        end\n    end\n    return best, bestd\nend\n\n-- \226\148\128\226\148\128 Dormant-FARP activation (Item 1 \226\128\148 eech keysite.c:507-568 initialise_keysite_farp_enable) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH FARP keysites are created in_use=FALSE (ks_creat.c:157) and only ACTIVATE when their SECTOR's\n-- side matches their own force side (keysite.c:541-547) \226\128\148 i.e. as the friendly front reaches them.\n-- Port proxy on bases-as-sectors: the FARP's \"sector side\" is the owner of the nearest NON-FARP base\n-- to it; the FARP is friendly-sector iff that owner == the FARP's own side. Activation LATCHES (EECH\n-- only clears in_use on destroy, ks_dstry.c:325). While dormant a FARP is excluded from launch\n-- candidacy (task_board.owned_bases \226\137\136 nearest-keysite search keysite.c:369) and the win usable-airbase\n-- census (win_condition \226\137\136 fc_msgs.c:234 ALIVE && IN_USE) via cs.base_is_active.\n--\n-- WATCH ITEM (F5, documented proxy limit): an AUTHOR-PLACED friendly FARP whose nearest NON-FARP base\n-- happens to be enemy-owned reads as \"sector not friendly\" and starts DORMANT under this proxy \226\128\148 even\n-- though the author clearly intends it live (EECH's real sector grid is far finer than\n-- bases-as-sectors, so its FARP could still sit in a friendly sector there). It self-heals as the\n-- front advances past it; an author who wants such deep-forward FARPs active from boot sets\n-- theatre.farp_activation = false (all FARPs active \226\128\148 the documented override).\nlocal function sector_side_friendly(fname)\n    local fpos  = S.base_pos[fname]\n    local fside = S.base_owner[fname]\n    if not fpos or not fside then return false end\n    local best_owner, best_d = nil, math.huge\n    for name, owner in pairs(S.base_owner) do\n        if name ~= fname and (S.base_kind or {})[name] ~= \"farp\" and S.base_pos[name] then\n            local bp = S.base_pos[name]\n            local d = cs.dist2d(fpos.x, fpos.z, bp.x, bp.z)\n            if d < best_d then best_d = d; best_owner = owner end\n        end\n    end\n    return best_owner == fside\nend\n\n-- Seed S.farp_active for every FARP at boot. Gate OFF \226\134\146 all FARPs active (authored convenience).\n-- Gate ON (default, EECH-faithful) \226\134\146 active only if the FARP's sector is already friendly; the rest\n-- stay dormant until M.update latches them.\nfunction M.seed_activation(log_fn)\n    log_fn = log_fn or function() end\n    S.farp_active = S.farp_active or {}\n    local gate = config.C.theatre.farp_activation\n    local n_active, n_dormant = 0, 0\n    for name, kind in pairs(S.base_kind or {}) do\n        if kind == \"farp\" then\n            local active = (not gate) or sector_side_friendly(name)\n            S.farp_active[name] = active or nil\n            if active then n_active = n_active + 1 else n_dormant = n_dormant + 1 end\n        end\n    end\n    log_fn(string.format(\"FARP activation (gate=%s): %d active, %d dormant (dormant activate as the front nears)\",\n        tostring(gate), n_active, n_dormant))\n    cs.dbg(\"farps\", \"seed_activation gate=%s: %d active, %d dormant\", tostring(gate), n_active, n_dormant)\nend\n\n-- Periodic latch: activate any dormant FARP whose sector has become friendly (front advanced). This is\n-- the \"dormant-FARP activation as the front moves\" \226\128\148 EECH re-runs initialise_keysite_farp_enable at\n-- campaign setup; the port re-evaluates the same sector-side predicate as ownership shifts.\nfunction M.update(log_fn)\n    log_fn = log_fn or function() end\n    S.farp_active = S.farp_active or {}\n    if not config.C.theatre.farp_activation then return end   -- gate off \226\134\146 all already active\n    for name, kind in pairs(S.base_kind or {}) do\n        if kind == \"farp\" and not S.farp_active[name] and sector_side_friendly(name) then\n            S.farp_active[name] = true\n            log_fn(string.format(\"FARP %s ACTIVATED \226\128\148 sector now friendly (front reached)\", name))\n            cs.dbg(\"farps\", \"FARP %s ACTIVATED (sector friendly, keysite.c:541 proxy)\", name)\n        end\n    end\nend\n\n-- Scheduler (registered once from game_loop.start): re-evaluate FARP activation every 120 s.\nfunction M.schedule(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    local PERIOD = 120\n    cs.dbg(\"farps\", \"activation scheduler REGISTERED period=%ds\", PERIOD)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end\n        pcall(M.update, log_fn)\n        return t + PERIOD\n    end, nil, timer.getTime() + PERIOD)\nend\n\n-- Called from game_loop init AFTER base discovery, BEFORE supply.init (the ledger reads base_kind).\nfunction M.init(log_fn)\n    log_fn = log_fn or function() end\n    S.base_kind = S.base_kind or {}\n    pcall(function() math.randomseed(math.floor((timer.getTime() or 0) * 1000) + cs.GENERATION * 7919) end)\n\n    -- \226\148\128\226\148\128 AUTHORED theatre (zone-based) \226\128\148 REGISTER, do not spawn \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- When the bases were authored by ME keysite zones, keysite.lua already set base_kind\n    -- (\"airbase\"/\"farp\") from the zones. The author PLACES the FARP static in the Mission Editor\n    -- (it auto-registers as a HELIPAD airbase); the campaign SPAWNS NOTHING here. We only confirm the\n    -- farp roles. The supply-ledger contract (base_kind \"airbase\" = fixed-wing+heli; \"farp\" =\n    -- heli-only) is already set by keysite.lua and preserved.\n    if require(\"zones\").has_keysite_zones() then\n        local nfarp = 0\n        for _, kind in pairs(S.base_kind) do\n            if kind == \"farp\" then nfarp = nfarp + 1 end\n        end\n        log_fn(string.format(\"base roles from zones: %d farp bases confirmed (author-placed FARP \"\n            .. \"statics; NO spawning) \226\128\148 airbase/farp roles set by keysite zones\", nfarp))\n        cs.dbg(\"farps\", \"init (zone-authored): %d farp bases confirmed, no spawning\", nfarp)\n        M.seed_activation(log_fn)   -- Item 1: dormant-FARP activation seeding (zone-authored FARPs)\n        return\n    end\n\n    -- \226\148\128\226\148\128 Layer 1: classify airfields (predictable) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    local nfw, nfob = 0, 0\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        local fields = {}\n        for name, owner in pairs(S.base_owner) do\n            if owner == side then\n                local _, d = nearest_enemy(name, side)\n                fields[#fields + 1] = { name = name, d = d }\n            end\n        end\n        -- Rear-most fields (largest distance to the enemy) are the fixed-wing AIRBASEs; the forward\n        -- fields become heli-only FOBs. The airbase count scales down on a small theatre so the\n        -- majority always stay heli (never more than a third of a side's fields, capped at 2).\n        table.sort(fields, function(a, b) return a.d > b.d end)\n        local nfw_side = fixed_wing_count(#fields)\n        for i, f in ipairs(fields) do\n            if i <= nfw_side then S.base_kind[f.name] = \"airbase\"; nfw = nfw + 1\n            else S.base_kind[f.name] = \"fob\"; nfob = nfob + 1 end\n        end\n    end\n\n    -- \226\148\128\226\148\128 Layer 2: forward FARP network (randomised) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    local airfields = {}\n    for name, owner in pairs(S.base_owner) do\n        if S.base_kind[name] == \"airbase\" or S.base_kind[name] == \"fob\" then\n            airfields[#airfields + 1] = { name = name, owner = owner }\n        end\n    end\n    local nfarp = 0\n    for _, ab in ipairs(airfields) do\n        local enemy_base, d = nearest_enemy(ab.name, ab.owner)\n        if enemy_base and d < FRONT_DIST and math.random(100) <= FARP_CHANCE then\n            local bp, ep = S.base_pos[ab.name], S.base_pos[enemy_base]\n            local dx, dz = ep.x - bp.x, ep.z - bp.z\n            local len = math.max(math.sqrt(dx * dx + dz * dz), 1)\n            local ux, uz = dx / len, dz / len          -- unit vector toward the enemy\n            local px, pz = -uz, ux                       -- perpendicular (lateral) unit vector\n            local fwd = FARP_FWD_MIN + math.random() * (FARP_FWD_MAX - FARP_FWD_MIN)\n            local lat = (math.random() * 2 - 1) * FARP_LATERAL\n            -- Snap the forward-FARP placement off water (a jittered point 18-40 km ahead of a coastal\n            -- field can land in the sea); fallback = the parent field centre `bp` (always land).\n            local fp = cs.snap_land(bp.x + ux * fwd + px * lat, bp.z + uz * fwd + pz * lat, bp.x, bp.z)\n            local fx = fp.x\n            local fz = fp.z\n            local fname = \"FARP-\" .. ab.name:sub(1, 12)\n\n            S.base_owner[fname]  = ab.owner\n            S.base_pos[fname]    = { x = fx, z = fz }\n            S.base_health[fname] = 1.0\n            S.base_kind[fname]   = \"farp\"\n\n            -- Idempotent: FARP statics survive reset.nuke (it destroys groups, not statics).\n            if not Airbase.getByName(fname) then\n                local fs = config.C.statics.farp   -- config statics.farp = {type, shape_name, category}\n                coalition.addStaticObject(COUNTRY[ab.owner], {\n                    heading = 0, type = fs.type, shape_name = fs.shape_name, category = fs.category,\n                    name = fname, x = fx, y = fz, dead = false,\n                })\n            end\n            nfarp = nfarp + 1\n        end\n    end\n\n    log_fn(string.format(\"base roles: %d fixed-wing AIRBASEs (rear) + %d heli-only FOBs + %d forward \"\n        .. \"FARPs \226\128\148 fixed-wing flies only from airbases; the rotary front war flies from FOBs + FARPs\",\n        nfw, nfob, nfarp))\n    cs.dbg(\"farps\", \"init (auto): %d airbases, %d heli-only FOBs, %d forward FARPs placed\", nfw, nfob, nfarp)\n    M.seed_activation(log_fn)   -- Item 1: dormant-FARP activation seeding (auto-theatre forward FARPs)\nend\n\n-- NOTE: M.is_heli_only was DELETED in Cluster H (zero callers) \226\128\148 heli-only enforcement lives in the\n-- ledger seeding (supply.lua: FOB/FARP bases get no fixed-wing striker/escort/recon roles), which is\n-- what actually confines fixed-wing to the airbases.\n\nreturn M\n"
__modules["fog_of_war"] = "-- fog_of_war.lua\n-- EECH source: aphavoc/source/entity/special/sector/sector.c\n--   update_client_server_sector_fog_of_war() line 562\n--   update_sector_fog_of_war() line 533  \226\128\148 subtracts FOG_OF_WAR_DECAY_RATE every period\n--   set_sector_fog_of_war_value() line 374 \226\128\148 units grant fog proportional to (1-r/recon_radius)*maximum\n-- EECH source: aphavoc/source/ai/highlevl/highlevl.h\n--   FOG_OF_WAR_DECAY_RATE    = 30.0\n--   DEFAULT_FOG_OF_WAR_MAXIMUM_VALUE = 4.0 * ONE_HOUR = 4.0 * 3600 = 14400\n-- EECH source: aphavoc/source/ai/highlevl/highlevl.c line 280\n--   add_high_level_ai_function(update_client_server_sector_fog_of_war, FOG_OF_WAR_DECAY_RATE, 8.0)\n--   \226\134\146 period = 30 s, initial offset = 8 s\n-- EECH source: highlevl.c FOW threshold usage:\n--   line 1433, 1620, 2072, 2653, 3062: fow >= 0.25 * maximum  \226\134\146 proceed with task\n--   line 1179: fow < 0.25 * maximum  \226\134\146 create recon instead\n--   line 1819: fow < 0.20 * maximum  \226\134\146 create recon instead (troop insertion, stricter)\n--\n-- DCS proxy: EECH stores per-sector fog values.  DCS has no sector grid, so we track\n-- per-base fog-of-war for each side.  Units within RECON_RADIUS of a base grant fog.\n-- Normalised value returned by get() is raw / FOW_MAX (0.0\226\128\1471.0).\n\nlocal cs = require(\"campaign_state\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- \226\148\128\226\148\128 EECH constants (exact mirror) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal FOW_DECAY_RATE = 30.0           -- subtract per period (highlevl.h)\nlocal FOW_MAX        = 4.0 * 3600    -- 14400; DEFAULT_FOG_OF_WAR_MAXIMUM_VALUE (highlevl.h)\nlocal FOW_PERIOD     = FOW_DECAY_RATE -- 30 s; period used as update period (highlevl.c:280)\nlocal FOW_OFFSET     = 8.0            -- initial offset seconds (highlevl.c:280)\n\n-- EECH: FLOAT_TYPE_RECON_RADIUS is a single per-unit-type database float\n-- (aircraft ac_dbase.c, vehicles/ships vh_dbase.c). The FOW code doubles it\n-- (recon_radius = db_value * 2.0, eech sector.c:434) to get the effective scan\n-- radius, then linearly falls off to 0 at that radius.\n--\n-- The port's old flat \"airplane 20 km / heli 10 km / ground 3 km\" values do NOT\n-- exist anywhere in EECH (spec 06 \194\167SECTOR-F8 \226\128\148 REFUTED). Replaced here with the\n-- real per-unit-type recon_radius, keyed off DCS unit attributes (getDesc) which\n-- map cleanly onto EECH's per-type database rows. Values below are the raw\n-- database recon_radius (metres); the *2.0 doubling is applied in the grant loop.\nlocal RECON = {\n    -- Aircraft (eech entity/mobile/aircraft/ac_dbase.c)\n    FIGHTER        = 10000, -- fighters/strike fighters (F-16C, MiG-29, F/A-18C, Su-33/34) eech ac_dbase.c:1226,1303,1534,1611,1689\n    ATTACK_JET     = 6000,  -- attack jets (A-10A, Su-25, AV-8B, Yak-41)                    eech ac_dbase.c:1072,1149,1380,1457\n    HELI_ATTACK    = 5000,  -- attack/scout/utility helis (AH-64D, Ka-52, Mi-28, Mi-24...)  eech ac_dbase.c:144,221,298,375,454,533\n    HELI_TRANSPORT = 3000,  -- transport helis + fixed-wing transports (CH-47, Mi-6, C-130) eech ac_dbase.c:610,764,918,995,2007\n    -- Vehicles / ships (eech entity/mobile/vehicle/vh_dbase.c)\n    INFANTRY       = 500,   -- infantry / small units                                       eech vh_dbase.c:2104,2290,2538\n    VEHICLE        = 1000,  -- tanks, trucks, most AFVs, artillery (most common tier)        eech vh_dbase.c:554,616,740\n    APC_IFV        = 2000,  -- APC / IFV class                                               eech vh_dbase.c:120,182,368\n    SCOUT          = 3000,  -- scout / recon vehicles                                        eech vh_dbase.c:244,306,1174\n    AD_RADAR       = 4000,  -- short-range AD radar vehicles (Avenger/Tor tier)              eech vh_dbase.c:1050,1112\n    RADAR_SAM      = 6000,  -- radar SAM / frigates (SA-19, O.H. Perry, Krivak II)           eech vh_dbase.c:988,1794,1856\n    CAPITAL_SHIP   = 8000,  -- capital ships (Tarawa, Kiev)                                  eech vh_dbase.c:1670,1732\n}\nlocal RECON_DEFAULT = RECON.VEHICLE  -- unknown ground \226\134\146 tanks/trucks tier (19\195\1511000, the modal value)\n\n-- Resolve a unit's database recon_radius from its DCS attributes/category, mapping\n-- onto the closest EECH per-type value. Attribute-driven (not type-name-hardcoded)\n-- so it stays valid across the whole DCS unit set. Mirrors FLOAT_TYPE_RECON_RADIUS.\nlocal function recon_radius_for(u, cat)\n    local desc = u.getDesc and u:getDesc() or nil\n    local a = (desc and desc.attributes) or {}\n\n    if cat == Group.Category.AIRPLANE then\n        if a[\"Transports\"] then return RECON.HELI_TRANSPORT end     -- fixed-wing transports \226\134\146 3000\n        if a[\"Attack planes\"] then return RECON.ATTACK_JET end      -- A-10/Su-25 class \226\134\146 6000\n        return RECON.FIGHTER                                        -- fighters/multirole/bombers \226\134\146 10000\n    elseif cat == Group.Category.HELICOPTER then\n        if a[\"Transport helicopters\"] then return RECON.HELI_TRANSPORT end\n        return RECON.HELI_ATTACK\n    elseif cat == Group.Category.SHIP then\n        if a[\"Aircraft Carriers\"] then return RECON.CAPITAL_SHIP end\n        return RECON.RADAR_SAM                                      -- frigates/other combatants \226\134\146 6000\n    else -- GROUND\n        if a[\"Infantry\"] then return RECON.INFANTRY end\n        if a[\"SAM TR\"] or a[\"SAM LR\"] then return RECON.RADAR_SAM end  -- long-range radar SAM \226\134\146 6000\n        if a[\"SAM SR\"] then return RECON.AD_RADAR end                 -- short-range AD \226\134\146 4000\n        if a[\"IFV\"] or a[\"APC\"] then return RECON.APC_IFV end          -- IFV/APC \226\134\146 2000\n        return RECON_DEFAULT                                           -- tanks/trucks/artillery \226\134\146 1000\n    end\nend\n\n-- FOW thresholds (normalised 0.0\226\128\1471.0), derived from highlevl.c fractional comparisons:\nM.THRESHOLD_TASK   = 0.25  -- most task generators require fow >= 0.25 * maximum\nM.THRESHOLD_TROOP  = 0.20  -- troop insertion requires fow >= 0.20 * maximum (stricter)\n\n-- \226\148\128\226\148\128 State: S.fow[base_name][side] = raw float 0\226\128\147FOW_MAX \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Initialised to 0 (fog of war fully engaged \226\128\148 EECH starts missions with zero fog)\n\nfunction M.init()\n    S.fow = S.fow or {}\n    for name in pairs(S.base_owner) do\n        S.fow[name] = S.fow[name] or {}\n        for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n            S.fow[name][side] = S.fow[name][side] or 0.0\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 get() \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Returns normalised 0.0\226\128\1471.0 for the named base from the given attacker's perspective.\n-- \"side\" here is the ATTACKER \226\128\148 returns FOW the attacker has on the base (enemy info).\n-- mirrors get_sector_fog_of_war_value() semantics.\nfunction M.get(base_name, side)\n    if not S.fow or not S.fow[base_name] then return 0.0 end\n    -- EECH: get_sector_fog_of_war_value() returns FOW_MAX when sector owned by queried side\n    -- (sector.c line 521: \"if sector_side == side return maximum_value\")\n    if S.base_owner[base_name] == side then return 1.0 end\n    local raw = S.fow[base_name][side] or 0.0\n    return raw / FOW_MAX\nend\n\n-- NOTE: M.grant (a manual FOW-grant export) was DELETED in Cluster H \226\128\148 it had zero callers (the\n-- per-unit proximity scan in tick_fow does its grants inline via the local grant logic below).\n\n-- \226\148\128\226\148\128 Decay + recon scan \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors update_sector_fog_of_war():\n--   raw = max(0, raw - FOG_OF_WAR_DECAY_RATE)  for every sector, every period.\n-- Plus: scan all friendly units (via coalition.getGroups) for proximity to each base;\n--   mirrors the per-entity set_sector_fog_of_war_value() calls that happen during\n--   entity movement updates.\n\nlocal function tick_fow()\n    if not S.fow then return end\n    local sides = { coalition.side.BLUE, coalition.side.RED }\n    local n_grants = 0\n\n    for name in pairs(S.base_owner) do\n        local bpos = S.base_pos[name]\n        S.fow[name] = S.fow[name] or {}\n        for _, side in ipairs(sides) do\n            -- Decay (mirrors update_sector_fog_of_war: max(0, val - DECAY_RATE))\n            local raw = (S.fow[name][side] or 0.0) - FOW_DECAY_RATE\n            if raw < 0.0 then raw = 0.0 end\n            S.fow[name][side] = raw\n        end\n\n        -- Recon grant from friendly units near this base\n        -- Mirrors the continuous per-entity set_sector_fog_of_war_value() calls.\n        -- Per-unit FLOAT_TYPE_RECON_RADIUS now resolved per unit-type via getDesc\n        -- attributes (closes the invented 20/10/3 km proxy; mirrors EECH's per-type\n        -- database recon_radius lookup, doubled with linear falloff).\n        if bpos then\n            for _, side in ipairs(sides) do\n                local grps = coalition.getGroups(side)\n                if grps then\n                    for _, grp in ipairs(grps) do\n                        if grp and grp:isExist() then\n                            local u = grp:getUnit(1)\n                            if u and u:isExist() then\n                                -- Resolve per-unit-type database recon_radius (mirrors FLOAT_TYPE_RECON_RADIUS)\n                                local cat = grp:getCategory()\n                                local recon_r = recon_radius_for(u, cat)\n\n                                local upos = u:getPosition().p\n                                local dx = upos.x - bpos.x\n                                local dz = upos.z - bpos.z\n                                local r  = math.sqrt(dx*dx + dz*dz)\n                                -- set_sector_fog_of_war_value uses recon_radius * 2.0 for sector scan\n                                local scan_r = recon_r * 2.0\n                                if r <= scan_r then\n                                    -- new_fog_value = max(current, (1 - r/scan_r) * maximum)\n                                    local grant = (1.0 - r / scan_r) * FOW_MAX\n                                    local current = S.fow[name][side] or 0.0\n                                    if grant > current then\n                                        S.fow[name][side] = math.min(FOW_MAX, grant)\n                                        n_grants = n_grants + 1\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    cs.dbg(\"fow\", \"decay+recon tick: %d (base,side) FOW grants raised this pass\", n_grants)\nend\n\n-- \226\148\128\226\148\128 Scheduler \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors add_high_level_ai_function(update_client_server_sector_fog_of_war,\n--                                    FOG_OF_WAR_DECAY_RATE, 8.0)\n-- period = 30 s, initial offset = 8 s\nfunction M.schedule_decay(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"fow\", \"decay scheduler REGISTERED offset=%.0fs period=%.0fs\", FOW_OFFSET, FOW_PERIOD)\n    timer.scheduleFunction(function(_, t)\n        -- INFRASTRUCTURE: FOW decay/grant keeps running post-victory (EECH fc_msgs.c:163). Cluster E.\n        if _DMT_GEN ~= my_gen then return nil end\n        local ok, err = pcall(tick_fow)\n        if not ok then log_fn(\"fog_of_war tick error: \" .. tostring(err)) end\n        return t + FOW_PERIOD\n    end, nil, timer.getTime() + FOW_OFFSET)\nend\n\nreturn M\n"
__modules["frontline"] = "-- frontline.lua\n-- EECH source: aphavoc/source/ai/frontl/ai_fline.c\n--   create_frontline(force) line 125  \226\128\148 iterates all sectors, marks PRIMARY if check passes\n--   check_sector_frontline(side, x, z) line 177 \226\128\148 returns PRIMARY if sector owned by side\n--     AND any of its 8 adjacent (3\195\1513 neighbourhood) sectors is owned by a different side\n--   recreate_frontline / recreate_side_frontline line 383 \226\128\148 event-driven on capture\n-- EECH source: aphavoc/source/ai/highlevl/highlevl.c\n--   add_high_level_ai_function(create_frontline, ...) \226\128\148 periodic rebuild\n--\n-- DCS proxy: EECH operates on a 2D sector grid (SECTOR_SIDE_LENGTH \226\137\136 4096 m).\n-- check_sector_frontline (ai_fline.c:177) marks a sector PRIMARY when it is owned\n-- by side X and any of its up-to-8 grid neighbours (3\195\1513 box) is owned by a\n-- different side. DCS has no sector grid and no static painted ownership; bases\n-- (keysites) are our sector proxies. The faithful analogue of \"the next sector\n-- over is enemy-owned\" is a *topological* adjacency between bases, not a fixed\n-- metric radius. We use Gabriel-graph adjacency: base B (side X) is frontline iff\n-- it is Gabriel-adjacent to at least one enemy base E, i.e. no third base lies\n-- inside the circle whose diameter is the segment B\226\128\147E. This is parameter-free and\n-- mirrors \"immediate neighbour of a different side\" far better than the old\n-- invented 200 km radius (spec 06 \194\167SECTOR-F16 \226\128\148 the port's fixed-km threshold is\n-- REFUTED as an EECH constant).\n--\n-- Recompute cadence (spec 06 \194\167SECTOR-F16): EECH's create_frontline runs ONCE per\n-- force at campaign load (parser.c:1369) over STATIC painted ownership and is never\n-- recomputed during play (recreate_frontline, ai_fline.c:383, has no callers). The\n-- port's ownership is DYNAMIC (bases change hands), so the faithful analogue is:\n-- build at load + recompute on each capture event. There is NO periodic (120 s)\n-- rebuild in EECH \226\128\148 that was an invention. M.recompute() is the capture hook.\n--\n-- Also provides:\n--   M.get_frontline(side)       \226\128\148 sorted list of frontline base names for side\n--   M.nearest_enemy(name)       \226\128\148 {name, distance} of nearest enemy base\n--   M.echelon_of(pos)           \226\128\148 \"frontline\" | \"second\" CAS/BAI/SEAD echelon of a position\n--   M.rebuild() / M.recompute() \226\128\148 recompute all flags (load + on capture)\n\nlocal cs = require(\"campaign_state\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- \226\148\128\226\148\128 Internal cache \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- frontline_flag[side][base_name] = true/false\nlocal frontline_flag = {\n    [coalition.side.BLUE] = {},\n    [coalition.side.RED]  = {},\n}\n\n-- Gabriel-graph adjacency test: are bases a,b adjacent with no other base strictly\n-- inside the disk whose diameter is a\226\128\147b? r is inside that disk iff the angle a-r-b\n-- is obtuse, i.e. |a-r|\194\178 + |b-r|\194\178 < |a-b|\194\178. Faithful proxy for \"immediate neighbour\".\nlocal function gabriel_adjacent(apos, bpos, aname, bname)\n    local dx = apos.x - bpos.x\n    local dz = apos.z - bpos.z\n    local d2 = dx*dx + dz*dz\n    if d2 <= 0 then return false end\n    for rname, rpos in pairs(S.base_pos) do\n        if rname ~= aname and rname ~= bname and S.base_owner[rname] then\n            local ax, az = apos.x - rpos.x, apos.z - rpos.z\n            local bx, bz = bpos.x - rpos.x, bpos.z - rpos.z\n            if (ax*ax + az*az) + (bx*bx + bz*bz) < d2 then\n                return false  -- a third base sits between a and b \226\134\146 not immediate neighbours\n            end\n        end\n    end\n    return true\nend\n\n-- \226\148\128\226\148\128 rebuild() \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors create_frontline() + check_sector_frontline() (ai_fline.c:125,177):\n--   For each base owned by side X, it is frontline iff it is Gabriel-adjacent to\n--   at least one enemy-owned base (the topological \"adjacent enemy sector\" rule).\nfunction M.rebuild()\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        frontline_flag[side] = {}\n        local enemy = cs.ENEMY[side]\n\n        for name, owner in pairs(S.base_owner) do\n            if owner == side then\n                local bpos = S.base_pos[name]\n                if bpos then\n                    local is_front = false\n                    for ename, eowner in pairs(S.base_owner) do\n                        if eowner == enemy then\n                            local epos = S.base_pos[ename]\n                            if epos and gabriel_adjacent(bpos, epos, name, ename) then\n                                is_front = true\n                                break\n                            end\n                        end\n                    end\n                    frontline_flag[side][name] = is_front\n                end\n            end\n        end\n    end\n    local n_blue, n_red = 0, 0\n    for _, f in pairs(frontline_flag[coalition.side.BLUE]) do if f then n_blue = n_blue + 1 end end\n    for _, f in pairs(frontline_flag[coalition.side.RED])  do if f then n_red  = n_red  + 1 end end\n    cs.dbg(\"frontline\", \"rebuild: BLUE frontline=%d bases, RED frontline=%d bases\", n_blue, n_red)\nend\n\n-- Capture-event hook (spec 06 \194\167SECTOR-F16): recompute the whole frontline after a\n-- base changes hands. Coordinator must wire this into the base-capture path (in\n-- keysite/win modules \226\128\148 out of this cluster's file scope). Alias of rebuild().\nfunction M.recompute()\n    cs.dbg(\"frontline\", \"recompute triggered (capture event)\")\n    M.rebuild()\nend\n\n-- \226\148\128\226\148\128 is_frontline(name, side) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Returns true if the base is on the frontline for the given side.\nfunction M.is_frontline(name, side)\n    return frontline_flag[side] and frontline_flag[side][name] == true\nend\n\n-- \226\148\128\226\148\128 echelon_of(pos) \226\128\148 CAS / BAI / SEAD echelon classifier \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH splits enemy ground targets between the generators by the STATIC\n-- per-group-TYPE flag group_database[sub_type].frontline_flag, surfaced as\n-- INT_TYPE_FRONTLINE (gp_int.c:389-392 \226\128\148 it returns the database flag verbatim,\n-- it is NOT a sector-distance value). The enum (group.h:199-202) is\n-- NONE=0, PRIMARY=1, SECONDARY=2, ARTILLERY=3, so:\n--   \226\128\162 create_cas_tasks   keeps groups with FRONTLINE == 1  (highlevl.c:877) \226\134\146 PRIMARY frontline armour\n--   \226\128\162 create_bai_tasks   keeps groups with FRONTLINE >  1  (highlevl.c:637) \226\134\146 SECONDARY/support + artillery\n--   \226\128\162 create_sead_tasks  keeps AA with !frontline_flag     (highlevl.c:1981) \226\134\146 NONE (rear/site AA, not frontline-attached)\n--\n-- The port's ground groups are undifferentiated (there is no per-type\n-- frontline_flag database \226\128\148 every standing-frontline / garrison group is the same\n-- DCS composition), so the only available echelon signal is POSITIONAL: a target\n-- in the contact zone stands in for a PRIMARY-frontline group; one deeper in the\n-- rear stands in for a SECONDARY/second-line group. A target's echelon is decided\n-- by whether its NEAREST owned base (either side) is a Gabriel-frontline base\n-- (is_frontline for that base's owner \226\128\148 a base owned by side X and Gabriel-adjacent\n-- to an enemy base is by construction frontline for X and its neighbour frontline\n-- for the enemy). Returns \"frontline\" (CAS-eligible) or \"second\" (BAI/SEAD-eligible).\n--\n-- CURRENCY: the Gabriel flags are rebuilt at load (init_and_build, game_loop.lua)\n-- and on every capture (recompute, keysite.lua). Base ownership is the flags' ONLY\n-- input and it changes ONLY on capture, so the flags are always current when read\n-- here \226\128\148 no periodic rebuild is needed (matches EECH: create_frontline is not on a\n-- timer, ai_fline.c:383 recreate_frontline has no callers).\nlocal function base_is_frontline(name)\n    local owner = S.base_owner[name]\n    return owner ~= nil and M.is_frontline(name, owner)\nend\n\nfunction M.echelon_of(pos)\n    if not pos then return \"second\" end\n    local best, best_d2 = nil, math.huge\n    for name, bpos in pairs(S.base_pos) do\n        if S.base_owner[name] then\n            local dx = pos.x - bpos.x\n            local dz = pos.z - bpos.z\n            local d2 = dx*dx + dz*dz\n            if d2 < best_d2 then best_d2 = d2; best = name end\n        end\n    end\n    if best and base_is_frontline(best) then return \"frontline\" end\n    return \"second\"\nend\n\n-- \226\148\128\226\148\128 get_frontline(side) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Returns a list of base names owned by side that are frontline,\n-- sorted ascending by distance to the nearest enemy base (most forward first).\n-- Mirrors EECH's frontline sector ordering by proximity.\nfunction M.get_frontline(side)\n    local list = {}\n    for name, flag in pairs(frontline_flag[side] or {}) do\n        if flag then\n            local ne = M.nearest_enemy(name)\n            list[#list + 1] = { name = name, dist = ne and ne.distance or math.huge }\n        end\n    end\n    table.sort(list, function(a, b) return a.dist < b.dist end)\n    local names = {}\n    for _, entry in ipairs(list) do names[#names + 1] = entry.name end\n    return names\nend\n\n-- \226\148\128\226\148\128 nearest_enemy(name) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Returns {name=string, distance=metres} for the nearest enemy-owned base.\n-- Returns nil if no enemy bases exist.\nfunction M.nearest_enemy(name)\n    local bpos  = S.base_pos[name]\n    local owner = S.base_owner[name]\n    if not bpos or not owner then return nil end\n\n    local enemy   = cs.ENEMY[owner]\n    local best_d2 = math.huge\n    local best_nm = nil\n\n    for ename, eowner in pairs(S.base_owner) do\n        if eowner == enemy then\n            local epos = S.base_pos[ename]\n            if epos then\n                local dx = bpos.x - epos.x\n                local dz = bpos.z - epos.z\n                local d2 = dx*dx + dz*dz\n                if d2 < best_d2 then\n                    best_d2 = d2\n                    best_nm = ename\n                end\n            end\n        end\n    end\n\n    if best_nm then\n        return { name = best_nm, distance = math.sqrt(best_d2) }\n    end\n    return nil\nend\n\n-- \226\148\128\226\148\128 init_and_build() \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.init_and_build()\n    M.rebuild()\nend\n\n-- \226\148\128\226\148\128 Scheduler \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH computes the frontline ONCE at campaign load and never on a timer\n-- (spec 06 \194\167SECTOR-F16; recreate_frontline has no callers). The port's dynamic\n-- ownership instead recomputes on capture via M.recompute(). This scheduler is\n-- therefore intentionally a no-op \226\128\148 retained only so game_loop.lua's call site\n-- (frontl.schedule_update) stays valid. The frontline is fresh from init_and_build\n-- at load and from recompute() on each capture.\nfunction M.schedule_update(log_fn)\n    -- no periodic rebuild (faithful to EECH); frontline is event-driven now.\n    cs.dbg(\"frontline\", \"schedule_update called: intentional no-op (EECH computes frontline once at \" ..\n        \"load + on capture, not on a timer \226\128\148 see module header)\")\nend\n\nreturn M\n"
__modules["game_loop"] = "-- game_loop.lua\n-- Inspired by:\n--   aphavoc/source/ai/highlevl/highlevl.c   start_high_level_ai(): registers ALL campaign\n--                                            AI functions into the update list with period + offset\n--   aphavoc/source/update.c                 add_update_function: staggered periodic scheduler\n--   aphavoc/source/update.h                 update_function_data_type: callback, sleep, offset\n--   aphavoc/source/entity/special/session/ss_updt.c  session update: elapsed_time tick\n--   aphavoc/source/entity/special/force/fc_updt.c    update_server: criteria evaluation every 5s\n--\n-- Orchestrator only \226\128\148 thin wiring layer, no campaign logic lives here.\n-- Mirrors start_high_level_ai() which does nothing but register every task-generation\n-- function into the update list; the logic is in each sub-system module.\n--\n-- Module dependency graph (mirrors EECH entity/AI split):\n--   campaign_state  \226\134\144 SESSION + FORCE data (no dependencies)\n--   keysite         \226\134\144 KEYSITE entity ops (requires campaign_state)\n--   imap            \226\134\144 influence maps (requires campaign_state)\n--   fog_of_war      \226\134\144 FOW decay (requires campaign_state)\n--   frontline       \226\134\144 frontline detection (requires campaign_state)\n--   win_condition   \226\134\144 fc_updt criteria + kill handler (requires campaign_state, keysite)\n--   attack_waves    \226\134\144 highlevl OCA/strike tasks (requires campaign_state, keysite)\n--   ground_forces   \226\134\144 highlevl advance/retreat tasks (requires campaign_state, keysite)\n--   regen           \226\134\144 dead-group regen FIFO (requires campaign_state, supply)\n--   keysite_repair  \226\134\144 ks_updt supply/repair tick (requires campaign_state)\n--   cas_bai_sead    \226\134\144 highlevl CAS/BAI/SEAD/OCA Sweep/Artillery (requires imap, fog_of_war, frontline)\n--   troop           \226\134\144 highlevl T.I. + patrol (requires campaign_state, imap, fog_of_war)\n--   transfer        \226\134\144 highlevl FW/HC transfer (requires campaign_state, imap, supply)\n--   reaction        \226\134\144 reactive AI on task-assign (requires campaign_state, supply)\n--   game_loop       \226\134\144 start_high_level_ai orchestrator (requires all above)\n\nlocal cs       = require(\"campaign_state\")\nlocal ks       = require(\"keysite\")\nlocal sup      = require(\"supply\")\nlocal wc       = require(\"win_condition\")\nlocal atk      = require(\"attack_waves\")\nlocal gnd      = require(\"ground_forces\")\nlocal ov       = require(\"map_overlay\")\nlocal imap_m   = require(\"imap\")\nlocal fow_m    = require(\"fog_of_war\")\nlocal frontl   = require(\"frontline\")\nlocal regen_m  = require(\"regen\")\nlocal kr_m     = require(\"keysite_repair\")\nlocal cas_m    = require(\"cas_bai_sead\")\nlocal troop_m  = require(\"troop\")\nlocal xfer_m   = require(\"transfer\")\nlocal react_m  = require(\"reaction\")\nlocal inst_m   = require(\"installations\")\n-- heli_war is NOT required here: its schedulers were deleted in Cluster H and its remaining exports\n-- (build_attack_heli, spawn_escort) are required directly by cas_bai_sead / troop.\nlocal board_m  = require(\"task_board\")\nlocal sf_m     = require(\"supply_flight\")\nlocal pilots_m = require(\"pilots\")\nlocal persist  = require(\"persist\")\nlocal sched    = require(\"campaign_mode\")   -- Item 5: mode-selected scheduler cadence (period + per-side offsets)\n\nlocal game_loop = {}\ngame_loop.name    = \"game_loop\"\ngame_loop.version = \"0.2.0\"\n\nlocal S = cs.S\n\n-- Status and capture-check periods\n-- mirrors update_campaign_triggers (every 1s in EECH); we log at human granularity\nlocal STATUS_PERIOD = 2 * 60\nlocal CAPTURE_CHK   = 60\n\nlocal function info(msg)\n    env.info(string.format(\"[dynamic-mission-test] [game_loop] %s\", tostring(msg)))\nend\n\n-- \226\148\128\226\148\128 Admin scheduler \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors update_client_server_sector_side_count (1 min) +\n--         update_campaign_triggers (1 s) + fc_updt criteria check (5 s)\n-- Combined here at coarser granularity since DCS log is the readout.\n\nlocal function schedule_admin()\n    local my_gen = _DMT_GEN\n    cs.dbg(\"loop\", \"admin scheduler REGISTERED: capture/win offset=90s period=%ds, status offset=%ds period=%ds\",\n        CAPTURE_CHK, STATUS_PERIOD, STATUS_PERIOD)\n    -- Capture poll + win condition (mirrors fc_updt every-5s criteria scan).\n    -- INFRASTRUCTURE: keeps running post-victory \226\128\148 captures still happen and wc.check_win is idempotent\n    -- (win_condition.lua:118 early-returns once S.game_over is set, mirroring EECH fc_msgs.c:163 which\n    -- returns TRUE early on an already-complete session rather than re-awarding). Cluster E.\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end\n        ks.try_capture(info)\n        wc.check_win(info)\n        return t + CAPTURE_CHK\n    end, nil, timer.getTime() + 90)\n\n    -- Periodic status log (mirrors EECH campaign map HUD + update_campaign_triggers)\n    -- INFRASTRUCTURE: status/strength readout keeps running post-victory (EECH fc_msgs.c:163). Cluster E.\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end\n        cs.recalc_strength()\n        local elapsed = math.floor((timer.getTime() - S.start_time) / 60)\n        local ph      = cs.current_phase()\n\n        -- Phase transition announcement \226\128\148 logged AND shown to players in-game.\n        if ph ~= S.phase then\n            local prev = S.phase\n            S.phase = ph\n            info(string.format(\"Phase \226\134\146 %s | BLUE str=%d RED str=%d\",\n                ph, S.strength[coalition.side.BLUE], S.strength[coalition.side.RED]))\n            trigger.action.outText(string.format(\n                \"\226\148\128\226\148\128 Campaign phase: %s \226\148\128\226\148\128\\nBLUE %d%%   RED %d%%\",\n                string.upper(ph), S.strength[coalition.side.BLUE], S.strength[coalition.side.RED]), 20)\n            cs.dbg(\"loop\", \"phase transition %s -> %s at T+%dm\", tostring(prev), ph, elapsed)\n        end\n\n        local parts = {}\n        for n, o in pairs(S.base_owner) do\n            local h = math.floor((S.base_health[n] or 1) * 100)\n            parts[#parts + 1] = n .. \"=\" .. (cs.SIDE_NAME[o] or \"?\") .. \"(\" .. h .. \"%)\"\n        end\n        table.sort(parts)\n\n        info(string.format(\"STATUS T+%dm [%s] BLUE=%d RED=%d | %s\",\n            elapsed, ph,\n            S.strength[coalition.side.BLUE],\n            S.strength[coalition.side.RED],\n            table.concat(parts, \"  \")))\n\n        -- Item 2: per-side kill/loss/task/sortie tally line alongside the strength/ownership readout.\n        info(cs.stats_summary_line())\n\n        return t + STATUS_PERIOD\n    end, nil, timer.getTime() + STATUS_PERIOD)\nend\n\n-- \226\148\128\226\148\128 Entry point \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors start_high_level_ai(): called once, registers all campaign AI timers.\n-- Each sub-system's schedule_* function mirrors add_high_level_ai_function(fn, period, offset).\n\nfunction game_loop.start()\n    info(\"EECH-inspired campaign game loop v\" .. game_loop.version .. \" starting\")\n\n    S.start_time = timer.getTime()\n    S.phase      = \"early\"\n\n    -- \226\148\128\226\148\128 Phase 1: State initialisation \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- Mirrors initialise_order_of_battle + session entity setup.\n\n    -- Keysite registry (keysite entity list \226\134\146 S.base_owner, S.base_pos, S.base_health)\n    ks.init_base_state(info)\n\n    -- FARP layer (EECH popread.c FARP keysites): forward heli-only bases ahead of each frontline\n    -- airbase. Marks airfields base_kind=\"airbase\" and adds base_kind=\"farp\" forward bases. MUST run\n    -- after base discovery and BEFORE supply.init so FARPs get a (heli-only) ledger.\n    require(\"farps\").init(info)\n\n    cs.recalc_strength()\n\n    -- Hardware inventory (force_info_reserve_hardware \226\134\146 supply counts)\n    sup.init(info)\n\n    -- Influence maps (4 layers, start empty \226\128\148 first update at T+30s)\n    imap_m.init()\n\n    -- Fog of war (per-base per-side fog tables, all zero at mission start)\n    fow_m.init()\n\n    -- Frontline detection (per-base is_frontline flag)\n    frontl.init_and_build()\n\n    -- Regen queues (FIFO per side per type, all empty)\n    regen_m.init(info)\n\n    -- Keysite supply/repair state (ammo/fuel 100% at mission start)\n    kr_m.init(info)\n\n    -- \226\148\128\226\148\128 PERSISTENCE RESTORE \226\128\148 DATA phase (WAVE 2, goals/03 P1) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- After world discovery + all data-seeding init() (so keys exist to overlay) but BEFORE the ground\n    -- OOB spawn and before installations/AD read ownership. Overlays the saved base_*/ledger/production/\n    -- regen/fow/pilots/objectives/strength onto the fresh state so the rest of boot sees the restored\n    -- campaign. No-op (returns false) unless config.persistence.enabled AND a save exists for the slot.\n    -- On a same-process hot re-inject this stays a no-op (default disabled) \226\128\148 current workflows unchanged.\n    local restored = persist.restore_data(info)\n    if restored then\n        -- ownership changed under us \226\134\146 rebuild the frontline now (the 120 s scheduler would otherwise\n        -- catch up later); pcall-guarded, purely a freshness optimisation.\n        pcall(function() if frontl.recompute then frontl.recompute(info) end end)\n        -- F1: re-derive FARP activation against the RESTORED ownership. farps.init ran seed_activation\n        -- BEFORE this overlay (against fresh ownership), and the latch only ever sets true \226\128\148 a stale\n        -- pre-restore activation would never heal (over-active FARPs polluting the win census after\n        -- every server restart). EECH's own boot behaviour is a RECOMPUTE, not a persisted flag:\n        -- initialise_keysite_farp_enable re-evaluates every FARP's sector side at campaign setup\n        -- (keysite.c:507-568). Reset the latch and re-seed; S.farp_active is deliberately NOT persisted.\n        S.farp_active = {}\n        pcall(function() require(\"farps\").seed_activation(info) end)\n    end\n\n    -- Standing frontline: seed N ground groups per side (mirrors order.c ground registry).\n    -- Runs after supply.init (draws from the \"vehicle\" reserve) and keysite state.\n    -- On RESTORE the mobile OOB is respawned from saved summaries (persist.restore_world, below) instead\n    -- of a fresh seed \226\128\148 so skip the OOB spawn to avoid a doubled frontline / double reserve consume.\n    if not restored then\n        gnd.init_oob(info)\n    else\n        cs.dbg(\"loop\", \"restore active: skipping fresh ground OOB seed (mobile OOB respawns from save)\")\n    end\n\n    -- Non-airbase keysites: depots/radar/fuel installations behind each base (Cluster G).\n    inst_m.init(info)\n\n    -- Flesh out keysites with an air-defence garrison (radar SAM + AAA per base): gives SEAD real\n    -- targets, contests strikes, feeds the AIR_DEFENCE imap, and drives organic keysite attrition.\n    require(\"base_defenses\").init(info)\n\n    -- Pilot/player career substrate (Cluster 6, spec 10). Restore-safe (never clobbers S.pilots).\n    -- Kill/birth/death wiring lives inside the EXISTING win_condition + reaction handlers; here we\n    -- only init the record store and build the F-10 menu. Fully dormant until player slots exist.\n    pilots_m.init(info)\n\n    -- \226\148\128\226\148\128 PERSISTENCE RESTORE \226\128\148 WORLD phase (WAVE 2) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- After installations + AD rings + pilots are freshly seeded: overlay saved keysite health/dead\n    -- (re-killing saved-dead author statics so the world matches), and respawn the mobile OOB (primary/\n    -- artillery/secondary ground groups) from summaries \226\128\148 reserve-neutral (restored ledger already\n    -- reflects them). No-op unless restore_data applied a save above.\n    if restored then\n        persist.restore_world(info)\n    end\n\n    info(string.format(\"Campaign live \226\128\148 BLUE str=%d RED str=%d phase=early\",\n        S.strength[coalition.side.BLUE], S.strength[coalition.side.RED]))\n    local n_bases = 0\n    for _ in pairs(S.base_owner) do n_bases = n_bases + 1 end\n    cs.dbg(\"loop\", \"Phase 1 init complete: %d bases known, generation=%d\", n_bases, cs.GENERATION)\n\n    -- \226\148\128\226\148\128 Phase 2: Event handlers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- Mirrors entity destroy hooks + task-assign notification hooks in EECH.\n\n    -- Register handlers through a global tracker so reset.lua can remove them on the next\n    -- injection (world.addEventHandler has no auto-cleanup; untracked handlers would stack).\n    _G.__dmt_handlers = _G.__dmt_handlers or {}\n    local function add_handler(h)\n        world.addEventHandler(h)\n        _G.__dmt_handlers[#_G.__dmt_handlers + 1] = h\n    end\n\n    add_handler(wc.make_kill_handler(info))        -- Kill \226\134\146 win condition decrement\n    add_handler(regen_m.make_dead_handler(info))   -- Dead aircraft \226\134\146 regen queue insert\n    add_handler(sup.make_land_handler(info))       -- RTB landing \226\134\146 recycle hardware to reserve\n    add_handler(react_m.make_event_handler(info))  -- Offensive spawn \226\134\146 CAP/BARCAP reaction\n    cs.dbg(\"loop\", \"Phase 2 complete: %d event handlers registered (kill/dead/land/reaction)\", #_G.__dmt_handlers)\n\n    -- \226\148\128\226\148\128 Phase 3: Periodic schedulers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- Mirrors start_high_level_ai() registering each function with period + offset.\n    -- Order matches EECH highlevl.c lines 246-280 (campaign mode) where applicable.\n\n    -- STARTUP SCHEDULER ROSTER (loop tag): every registration below appends {label, offset} here so\n    -- the full set \226\128\148 and any offset<=0 that DCS would silently drop \226\128\148 is visible in ONE grep, rather\n    -- than scattered across each subsystem's own dbg tag. This is exactly the blind spot that hid the\n    -- BLUE-attack-heli-war bug (schedule_cas offset=0) for so long.\n    local sched_roster = {}\n    local function roster(label, offset) sched_roster[#sched_roster + 1] = { label, offset } end\n\n    -- Task-board assignment engine (Cluster 4): drains the UNASSIGNED task queue every 3 min\n    -- (KEYSITE_TASK_ASSIGN_TIMER, keysite.h:69), matching idle base inventory to queued tasks and\n    -- expiring the unassignable (assign.c / ts_updt.c). Registered before the generators so the\n    -- board is live when the first tasks are created.\n    board_m.schedule(info)\n\n    -- Supply consumption + resupply (sup.schedule_supply mirrors ks_updt supply loop)\n    sup.schedule_supply(info)\n\n    -- Keysite repair (mirrors overload_keysite_update_functions, 60 s). This tick also raises the\n    -- PHYSICAL supply-flight requests (supply_flight.request) when a keysite drops below threshold.\n    kr_m.schedule_repair(info)\n\n    -- Supply-flight delivery detection (supply_flight.check_arrivals): the transport's DROP_OFF\n    -- fly-over of a consumer keysite restocks it to 100 (ks_msgs.c:230,238). Short cadence so a fast\n    -- transport's pass is never missed. Producer\226\134\146consumer transport is the EECH create_supply_task path.\n    sf_m.schedule_arrivals(info)\n\n    -- Regen dequeue (rg_updt.c update_server, 60 s \195\151 REGEN_UPDATE_MEDIUM)\n    regen_m.schedule_regen(info)\n\n    -- FOW decay + recon scan (mirrors add_high_level_ai_function(..., 30s, 8s))\n    fow_m.schedule_decay(info)\n\n    -- Influence maps (4 staggered layers, 120 s each; mirrors separate imap update registrations)\n    imap_m.schedule_update(info)\n\n    -- Frontline rebuild (120 s; mirrors per-tick sector neighbour scan)\n    frontl.schedule_update(info)\n\n    -- Dormant-FARP activation (Item 1; 120 s): latch a forward FARP active once its sector turns\n    -- friendly \226\128\148 the port's \"activation as the front moves\" (eech keysite.c:507-568). No-op when\n    -- config.C.theatre.farp_activation is false (all FARPs already active).\n    require(\"farps\").schedule(info)\n\n    -- Item 5: all per-side offsets now come from campaign_mode.SCHED (mode-selected). The CAMPAIGN\n    -- column is byte-identical to the prior inline literals + staggers (verified value-by-value); the\n    -- SKIRMISH column is highlevl.c:218-242. `.blue`/`.red` carry the port's per-side stagger.\n\n    -- Keysite (ground) strikes: EECH create_keysite_strike_tasks (highlevl.c:252 campaign / :228 skirmish)\n    atk.schedule_keysite_strikes(coalition.side.BLUE, sched.SCHED.keysite_strike.blue, info)\n    atk.schedule_keysite_strikes(coalition.side.RED,  sched.SCHED.keysite_strike.red,  info)\n    roster(\"keysite_strike/BLUE\", sched.SCHED.keysite_strike.blue); roster(\"keysite_strike/RED\", sched.SCHED.keysite_strike.red)\n\n    -- OCA strikes: EECH create_oca_strike_tasks (highlevl.c:268 campaign / :242 skirmish)\n    atk.schedule_oca_strikes(coalition.side.BLUE, sched.SCHED.oca_strike.blue, info)\n    atk.schedule_oca_strikes(coalition.side.RED,  sched.SCHED.oca_strike.red,  info)\n    roster(\"oca_strike/BLUE\", sched.SCHED.oca_strike.blue); roster(\"oca_strike/RED\", sched.SCHED.oca_strike.red)\n\n    -- Ground advance/retreat: EECH create_advance_and_retreat_tasks (highlevl.c:250 campaign / :224 skirmish)\n    gnd.schedule_ground(coalition.side.BLUE, sched.SCHED.ground.blue, info)\n    gnd.schedule_ground(coalition.side.RED,  sched.SCHED.ground.red,  info)\n    roster(\"ground/BLUE\", sched.SCHED.ground.blue); roster(\"ground/RED\", sched.SCHED.ground.red)\n\n    -- Infantry patrol: EECH create_troop_patrol_tasks (highlevl.c:248 campaign / :230 skirmish)\n    troop_m.schedule_patrol(coalition.side.BLUE, sched.SCHED.patrol.blue, info)\n    troop_m.schedule_patrol(coalition.side.RED,  sched.SCHED.patrol.red,  info)\n    roster(\"patrol/BLUE\", sched.SCHED.patrol.blue); roster(\"patrol/RED\", sched.SCHED.patrol.red)\n\n    -- \226\148\128\226\148\128 Rotary-wing war (EECH's primary offensive arm) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- heli_war.schedule_anti_armour / schedule_hunter_killer were a PORT INVENTION \226\128\148 EECH has no\n    -- anti_armour / hunter_killer task (grep of the C source finds only a formation component,\n    -- en_forms.c:177). In EECH the attack-helicopter frontline fight IS CAS + BAI, which are\n    -- heli-eligible (ts_dbase.c :511/:329) and launch attack helis from the forward FARPs (task_board\n    -- SUIT cas/bai = \"heli\"; cas_bai_sead builds heli sections). Those two schedulers + their private\n    -- helpers were DELETED in Cluster H (2026-07-09); heli_war.lua remains only as the shared\n    -- attack-heli / escort BUILDER (build_attack_heli, spawn_escort). No rotary scheduler is registered here.\n\n    -- CAS: EECH create_cas_tasks (highlevl.c:246 campaign / :220 skirmish) \226\128\148 the rotary frontline fight\n    -- from FARPs. EECH start_time 0.0 is bumped to blue=5 in campaign_mode (DCS silently drops a timer\n    -- scheduled at getTime()+0 \226\128\148 this once suppressed BLUE's whole attack-heli war); red staggered 30.\n    cas_m.schedule_cas(coalition.side.BLUE, sched.SCHED.cas.blue, info)\n    cas_m.schedule_cas(coalition.side.RED,  sched.SCHED.cas.red,  info)\n    roster(\"cas/BLUE\", sched.SCHED.cas.blue); roster(\"cas/RED\", sched.SCHED.cas.red)\n\n    -- Artillery: EECH create_artillery_strike_tasks (highlevl.c:254 campaign / :226 skirmish)\n    cas_m.schedule_artillery(coalition.side.BLUE, sched.SCHED.artillery.blue, info)\n    cas_m.schedule_artillery(coalition.side.RED,  sched.SCHED.artillery.red,  info)\n    roster(\"artillery/BLUE\", sched.SCHED.artillery.blue); roster(\"artillery/RED\", sched.SCHED.artillery.red)\n\n    -- Troop insertion: EECH create_troop_insertion_tasks (highlevl.c:256 campaign / :234 skirmish)\n    troop_m.schedule_troop_insertion(coalition.side.BLUE, sched.SCHED.troop_insertion.blue, info)\n    troop_m.schedule_troop_insertion(coalition.side.RED,  sched.SCHED.troop_insertion.red,  info)\n    roster(\"troop_insertion/BLUE\", sched.SCHED.troop_insertion.blue); roster(\"troop_insertion/RED\", sched.SCHED.troop_insertion.red)\n\n    -- SEAD: EECH create_sead_tasks (highlevl.c:264 campaign / :222 skirmish)\n    cas_m.schedule_sead(coalition.side.BLUE, sched.SCHED.sead.blue, info)\n    cas_m.schedule_sead(coalition.side.RED,  sched.SCHED.sead.red,  info)\n    roster(\"sead/BLUE\", sched.SCHED.sead.blue); roster(\"sead/RED\", sched.SCHED.sead.red)\n\n    -- BAI: EECH create_bai_tasks (highlevl.c:266 campaign / :236 skirmish)\n    cas_m.schedule_bai(coalition.side.BLUE, sched.SCHED.bai.blue, info)\n    cas_m.schedule_bai(coalition.side.RED,  sched.SCHED.bai.red,  info)\n    roster(\"bai/BLUE\", sched.SCHED.bai.blue); roster(\"bai/RED\", sched.SCHED.bai.red)\n\n    -- OCA Sweep: EECH create_oca_sweep_tasks (highlevl.c:258 campaign / :240 skirmish)\n    cas_m.schedule_oca_sweep(coalition.side.BLUE, sched.SCHED.oca_sweep.blue, info)\n    cas_m.schedule_oca_sweep(coalition.side.RED,  sched.SCHED.oca_sweep.red,  info)\n    roster(\"oca_sweep/BLUE\", sched.SCHED.oca_sweep.blue); roster(\"oca_sweep/RED\", sched.SCHED.oca_sweep.red)\n\n    -- Helicopter transfer: EECH create_helicopter_transfer_tasks (highlevl.c:260 campaign / :238 skirmish)\n    xfer_m.schedule_hc_transfer(coalition.side.BLUE, sched.SCHED.hc_transfer.blue, info)\n    xfer_m.schedule_hc_transfer(coalition.side.RED,  sched.SCHED.hc_transfer.red,  info)\n    roster(\"hc_transfer/BLUE\", sched.SCHED.hc_transfer.blue); roster(\"hc_transfer/RED\", sched.SCHED.hc_transfer.red)\n\n    -- Fixed-wing transfer: EECH create_fixed_wing_transfer_tasks (highlevl.c:262 campaign / :232 skirmish)\n    xfer_m.schedule_fw_transfer(coalition.side.BLUE, sched.SCHED.fw_transfer.blue, info)\n    xfer_m.schedule_fw_transfer(coalition.side.RED,  sched.SCHED.fw_transfer.red,  info)\n    roster(\"fw_transfer/BLUE\", sched.SCHED.fw_transfer.blue); roster(\"fw_transfer/RED\", sched.SCHED.fw_transfer.red)\n\n    -- Resource-scenery drain poll: the airfields' built-in fuel/barrel/warehouse scenery has no\n    -- S_EVENT_DEAD and can't be re-acquired by name, so its attrition is detected by polling the held\n    -- handles' getLife() (register-not-spawn scenery layer, installations.lua). ~25 s cadence.\n    inst_m.schedule_scenery_poll(info)\n\n    -- Admin: capture poll + status log (mirrors fc_updt criteria scan + campaign HUD)\n    schedule_admin()\n\n    -- Persistence autosave (WAVE 2): periodic background save (mirrors EECH's periodic session repack).\n    -- No-op unless config.persistence.enabled; saves also fire on capture (keysite.do_capture) and on\n    -- the win declaration (win_condition finish).\n    persist.schedule(info)\n\n    -- F-10 map overlay (base ownership, task arrows, frontline)\n    ov.schedule_overlay(info)\n\n    -- F-10 radio menu: Campaign > Request Mission / My Record (display-only, spec 10 Cluster 6).\n    -- pcall-guarded so a missing missionCommands API degrades silently.\n    pilots_m.build_menus(info)\n\n    -- Startup roster dump: one line per scheduler with its offset \226\128\148 an offset<=0 is instantly visible\n    -- by grepping \"[dmt:loop] scheduler\" (this is the fix for the historical silent-drop class of bug).\n    for _, entry in ipairs(sched_roster) do\n        local label, offset = entry[1], entry[2]\n        cs.dbg(\"loop\", \"scheduler %-24s offset=%.1fs%s\", label, offset, offset <= 0 and \" <-- WARNING: DCS drops offset<=0!\" or \"\")\n    end\n    cs.dbg(\"loop\", \"startup roster: %d schedulers registered (see individual subsystem tags for their own period/offset logs too)\",\n        #sched_roster)\n    cs.dbg(\"loop\", \"scheduler cadence MODE = %s (highlevl.c %s branch)\", sched.mode,\n        sched.mode == \"skirmish\" and \":218-242\" or \":246-268\")\n\n    info(\"All campaign schedulers registered \226\128\148 EECH game loop active\")\nend\n\nreturn game_loop\n"
__modules["ground_forces"] = "-- ground_forces.lua\n-- EECH source:\n--   aphavoc/source/ai/highlevl/highlevl.c   create_advance_and_retreat_tasks (12 min campaign,\n--                                            highlevl.c:250): advances the best frontline group ONE\n--                                            road-node toward the warmest reachable node; retreat\n--                                            emerges when forward nodes are hostile (:505-543).\n--   aphavoc/source/ai/highlevl/order.c       initialise_armoured_divisions: the frontline is a\n--                                            STANDING set of ground groups (ground registry), grouped\n--                                            into divisions (ceil(count/12)) \226\128\148 NOT one column.\n--   aphavoc/source/ai/faction/faction.c      initialise_frontline_forces (:1500-1662): places PRIMARY\n--                                            (:1520-1562), SECONDARY (:1565-1600) and ARTILLERY\n--                                            (:1602-1661) groups at road nodes. This module ports all\n--                                            three: primary tank column (spawn_group), SP artillery\n--                                            (spawn_arty_group), and the second-echelon SECONDARY group\n--                                            (spawn_sec_group) behind each frontline base.\n--   aphavoc/source/entity/special/group/group.h  GROUP.route_node, frontline_flag.\n--\n-- Port model: a STANDING FRONTLINE of N ground groups per side (one per frontline base), created at\n-- OOB and drawn from the side's \"vehicle\" reserve. This replaces the old single-column-per-side.\n-- Keysites are the movement \"nodes\": each group drives base-to-base toward the nearest enemy base,\n-- retargets when its objective is captured, and retreats to the nearest friendly base when cut off.\n--\n-- STRUCTURAL LIMIT (documented, not a proxy we can close): DCS exposes no road-node adjacency graph,\n-- so EECH's true node-by-node road pathfinding and \"move one group one node per tick\" discretisation\n-- cannot be reproduced. Continuous vehicle movement between keysite nodes is the closest achievable;\n-- the front paces itself through vehicle speed rather than a per-tick node step.\n\nlocal cs      = require(\"campaign_state\")\nlocal keysite = require(\"keysite\")\nlocal supply  = require(\"supply\")\nlocal config  = require(\"config\")\nlocal S       = cs.S\nlocal M       = {}\n\nlocal mode       = require(\"campaign_mode\")   -- Item 5: mode-selected cadence\nlocal GND_PERIOD = mode.SCHED.ground.period    -- highlevl.c:250 campaign 12min / :224 skirmish 15min\nlocal COL_SPEED  = 8         -- m/s \226\137\136 29 km/h\n\n-- Artillery advance halt distance: batteries advance with the front (highlevl.c:433 \226\128\148 the\n-- advance/retreat candidate filter is `if (group_database[sub_type].frontline_flag)`, NON-zero,\n-- so ARTILLERY(3) advances exactly like PRIMARY(1) tank groups) but hold INSIDE firing range of\n-- the contact line rather than driving into it: create_artillery_strike_tasks engages targets\n-- within weapon range (highlevl.c:2939-3081). 15 km = 0.75 \195\151 the 20 km ARTY_DEFAULT_RANGE\n-- envelope in cas_bai_sead (margin so the whole battery is in range of the base point).\nlocal ARTY_STANDOFF = 15000\nlocal FRONT_DIST = config.C.theatre.front_dist    -- m; a friendly base this close to an enemy base is \"frontline\" (config theatre)\nlocal CUTOFF_HP  = 0.5       -- retreat when group strength (alive fraction) drops below this\n\n-- \226\148\128\226\148\128 COMPOSITIONS: EECH formation-component DATA, not the gp_dbase labels \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- The real member composition of every EECH ground group is DATA: setup/common/data/FORMCOMP.DAT\n-- (the default formation-component database). create_faction_members consumes it slot-by-slot in\n-- FILE ORDER \226\128\148 components[loop*2] = BLUE vehicle, components[loop*2+1] = RED vehicle, for\n-- loop = 0..number-1 (faction.c:661/666) \226\128\148 so a group of size N fields the FIRST N slots. The\n-- gp_dbase.c default_blue/red_force_sub_type (M1A2/T80U) is only the fallback single type; the\n-- placed PRIMARY_FRONTLINE_GROUP is COMBINED ARMS with ORGANIC AD (the earlier \"all-tank\" reading\n-- of the gp_dbase labels was a misalignment \226\128\148 corrected against FORMCOMP.DAT:434-469).\n-- COUNTRY_OF + the FORMCOMP.DAT ordered slot rows are hoisted to config.lua (types.ground.*), with the\n-- per-row FORMCOMP citations kept ON THE DEFAULTS there. SIDE_COL maps a side to its column (1=BLUE,\n-- 2=RED) into those {BLUE, RED} rows.\nlocal COUNTRY_OF = config.C.countries\nlocal SIDE_COL = { [coalition.side.BLUE] = 1, [coalition.side.RED] = 2 }   -- {BLUE, RED} column\nlocal PRIMARY_SLOTS = config.C.types.ground.primary_slots     -- FORMCOMP.DAT:434-469 (:COUNT 16)\nlocal SECONDARY_SLOTS = config.C.types.ground.secondary_slots -- FORMCOMP.DAT:475-511 (:COUNT 16)\nlocal ARTY_SLOTS    = config.C.types.ground.arty_slots        -- FORMCOMP.DAT:549-562 (:COUNT 4)\nlocal MLRS_SLOTS    = config.C.types.ground.mlrs_slots        -- FORMCOMP.DAT:566-579 (:COUNT 4)\n\n-- Primary frontline group size: faction.c:1540-1542 places\n--   number = (int)((safe_radius / 4.0) + sfrand1() * 2.0), bound to [1, force_size].\n-- With EECH's default road-node safe_radius ~28 this is int(28/4) \194\177 2 = 7 \194\177 2. Proxy: 7 + rand(-2,2).\nlocal function primary_group_size()\n    return math.max(1, 7 + math.random(-2, 2))\nend\n\n-- Artillery group size: faction.c:1640-1644 places number = (int)(safe_radius/5.0) then bounds it by\n-- size = min(force_size, formation_component_data->count) \226\128\148 the ARTILLERY/MLRS component :COUNT is 4\n-- (FORMCOMP.DAT:552/:569; gp_dbase.c:810 maximum_member_count agrees). 4 IS the component count, and\n-- the group fields all 4 ordered slots (2 guns + truck + scout), not 4 guns.\nlocal ARTY_GROUP_SIZE = 4   -- FORMCOMP.DAT:552/:569 :COUNT 4 (= faction.c:1642-1644 bound)\n\n-- Combined-arms PRIMARY-frontline group: the first N ordered FORMCOMP slots for this side\n-- (create_faction_members consumes slots in file order, faction.c:661/666). A 7-group is therefore\n-- 2 tanks + IFV + SHORAD + IFV + SAM + APC \226\128\148 combined arms with organic AD, per FORMCOMP.DAT:438-450.\nlocal function group_comp(side)\n    local col = SIDE_COL[side]\n    local n   = math.min(primary_group_size(), #PRIMARY_SLOTS)\n    local out = {}\n    for i = 1, n do out[i] = PRIMARY_SLOTS[i][col] end\n    return out\nend\n\n-- \226\148\128\226\148\128 SECONDARY (second-echelon) frontline group \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH faction.c:1565-1600 places FORMATION_COMPONENT_SECONDARY_FRONTLINE_GROUP at\n-- FRONTLINE_FORCE_SECONDARY road nodes \226\128\148 nodes marked BEHIND the primary line \226\128\148 group type\n-- GROUP_SECONDARY_FRONTLINE (frontline_flag SECONDARY, gp_dbase.c:764). Same 7\194\1772 size formula as the\n-- primary line (faction.c:1579-1581 = the primary :1540-1542 form). Composition is FORMCOMP.DAT:475-511\n-- (:COUNT 16), consumed slot-by-slot in file order (faction.c:661/666), so a size-N group fields the\n-- FIRST N ordered slots: 2 tanks + SHORAD + IFV + cargo truck + tank + fuel truck + scout for N=7 \226\128\148\n-- combined arms with organic AD (Chaparral/SA-13 at slot 2), a fuel truck at slot 6, a BRDM/HMMWV scout\n-- at slot 7.\n--\n-- SECOND-ECHELON MOVEMENT PROXY (documented divergence): DCS has no road-node adjacency graph, so\n-- EECH's \"warm node behind the primary line\" placement + advance can't be reproduced node-by-node. The\n-- port models it as: the group holds SEC_STANDOFF behind its side's NEAREST FRIENDLY FRONTLINE base,\n-- toward the side's own rear, and re-routes to follow when the front moves (the nearest friendly\n-- frontline base changes) \226\128\148 see advance_retreat step 2c. It never drives at enemy bases (that is\n-- PRIMARY's job, spawn_group); following the moving front is the faithful proxy for EECH's warm-node\n-- advance eventually pulling the secondaries forward.\nlocal SEC_STANDOFF = 10000   -- m; designer proxy: second echelon sits ~10 km behind the front (no EECH\n                             -- metric constant \226\128\148 EECH uses road-node topology the port cannot mirror)\nlocal SEC_REAR_OFFSET = 4000 -- m; OOB spawn offset toward the side's rear (behind the arty's ~1.5 km)\n\n-- Combined-arms SECONDARY-frontline group: the first N ordered FORMCOMP-secondary slots for this side.\nlocal function sec_group_comp(side)\n    local col = SIDE_COL[side]\n    local n   = math.min(primary_group_size(), #SECONDARY_SLOTS)   -- same 7\194\1772 size (faction.c:1579-1581)\n    local out = {}\n    for i = 1, n do out[i] = SECONDARY_SLOTS[i][col] end\n    return out\nend\n\n-- \226\148\128\226\148\128 Node helpers (keysites = nodes) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function nearest_base_of(owner_side, pos)\n    local best, best_d = nil, math.huge\n    for name, owner in pairs(S.base_owner) do\n        if owner == owner_side then\n            local bp = S.base_pos[name]\n            if bp then\n                local d = cs.dist2d(pos.x, pos.z, bp.x, bp.z)\n                if d < best_d then best_d = d; best = name end\n            end\n        end\n    end\n    return best, best_d\nend\n\n-- Frontline bases for `side`: friendly bases within FRONT_DIST of any enemy base.\nlocal function frontline_bases(side)\n    local enemy, out = cs.ENEMY[side], {}\n    for name, owner in pairs(S.base_owner) do\n        if owner == side then\n            local bp = S.base_pos[name]\n            if bp then\n                for ename, eowner in pairs(S.base_owner) do\n                    if eowner == enemy then\n                        local ep = S.base_pos[ename]\n                        if ep and cs.dist2d(bp.x, bp.z, ep.x, ep.z) <= FRONT_DIST then\n                            out[#out + 1] = name; break\n                        end\n                    end\n                end\n            end\n        end\n    end\n    return out\nend\n\nlocal function lead_pos(grp)\n    local u = grp:getUnit(1)\n    if u and u:isExist() then return u:getPosition().p end\n    return nil\nend\n\nlocal function alive_fraction(grp, want)\n    local units = grp:getUnits()\n    local n = units and #units or 0\n    return (want > 0) and (n / want) or 0\nend\n\n-- Re-task an existing ground group to drive to a new objective (On Road).\nlocal function reroute(grp, to_pos)\n    if not to_pos then return end\n    local from = lead_pos(grp)\n    if not from then return end\n    local mx, mz = (from.x + to_pos.x) * 0.5, (from.z + to_pos.z) * 0.5\n    local ctrl = grp:getController()\n    if not ctrl then return end\n    ctrl:setTask({\n        id = \"Mission\",\n        params = { route = { points = {\n            { type=\"Turning Point\", action=\"On Road\", speed=COL_SPEED, ETA=0, ETA_locked=false,\n              alt=land.getHeight({x=mx, y=mz}), alt_type=\"BARO\", x=mx, y=mz, name=\"Via\", formation_template=\"\" },\n            { type=\"Turning Point\", action=\"On Road\", speed=COL_SPEED, ETA=0, ETA_locked=false,\n              alt=land.getHeight({x=to_pos.x, y=to_pos.z}), alt_type=\"BARO\",\n              x=to_pos.x, y=to_pos.z, name=\"Objective\", formation_template=\"\" },\n        } } },\n    })\nend\n\n-- Artillery variant: approach On Road (march like any column) but DEPLOY the final leg Off Road\n-- at the exact dispersed slot \226\128\148 reroute()'s On-Road terminal snaps every battery back onto the\n-- road network, which collapsed the standoff-ring dispersion and piled batteries on one road\n-- (live-observed). EECH batteries occupy their node position, not the road line (faction.c:1602).\nlocal function arty_reroute(grp, to_pos)\n    if not to_pos then return end\n    local from = lead_pos(grp)\n    if not from then return end\n    local mx, mz = (from.x + to_pos.x) * 0.5, (from.z + to_pos.z) * 0.5\n    local ctrl = grp:getController()\n    if not ctrl then return end\n    ctrl:setTask({\n        id = \"Mission\",\n        params = { route = { points = {\n            { type=\"Turning Point\", action=\"On Road\", speed=COL_SPEED, ETA=0, ETA_locked=false,\n              alt=land.getHeight({x=mx, y=mz}), alt_type=\"BARO\", x=mx, y=mz, name=\"Via\", formation_template=\"\" },\n            { type=\"Turning Point\", action=\"Off Road\", speed=COL_SPEED, ETA=0, ETA_locked=false,\n              alt=land.getHeight({x=to_pos.x, y=to_pos.z}), alt_type=\"BARO\",\n              x=to_pos.x, y=to_pos.z, name=\"Deploy\", formation_template=\"\" },\n        } } },\n    })\nend\n\n-- \226\148\128\226\148\128 Spawn one frontline group at home_base, driving toward target_base \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function spawn_group(side, home_base, target_base, log_fn)\n    if not supply.consume_side(side, \"vehicle\", 1) then\n        log_fn(cs.SIDE_NAME[side] .. \" ground: vehicle reserve exhausted\")\n        cs.dbg(\"ground\", \"%s spawn_group ABORT: vehicle reserve exhausted\", cs.SIDE_NAME[side])\n        return false\n    end\n    local home = S.base_pos[home_base]\n    local tpos = S.base_pos[target_base]\n    if not home or not tpos then\n        supply.recycle_side(side, \"vehicle\", 1)\n        cs.dbg(\"ground\", \"%s spawn_group ABORT: missing position for %s or %s -> refunded\",\n            cs.SIDE_NAME[side], tostring(home_base), tostring(target_base))\n        return false\n    end\n\n    local comp = group_comp(side)   -- ordered FORMCOMP slot types (first N, faction.c:661/666)\n    local id   = cs.next_id()\n    local name = string.format(\"GndCol-%d-%d\", side, id)\n    -- Snap the jittered spawn origin off water (coastal base); fallback = the base centre `home`.\n    local sp = cs.snap_land(home.x + math.random(-800, 800), home.z + math.random(-800, 800), home.x, home.z)\n    local sx, sz = sp.x, sp.z\n\n    local units = {}\n    for ui, utype in ipairs(comp) do\n        local ux, uz = sx + (ui-1)*30, sz + (ui-1)*15\n        units[ui] = { name=name..\"-\"..ui, type=utype, skill=\"Average\",\n            x=ux, y=uz, alt=land.getHeight({x=ux, y=uz}), alt_type=\"BARO\",\n            heading=cs.heading_to(sx, sz, tpos.x, tpos.z) }\n    end\n    local want = #units\n\n    local mx, mz = (sx + tpos.x) * 0.5, (sz + tpos.z) * 0.5\n    -- pcall the addGroup: a THROW here would leak the consumed vehicle (same class as the escort\n    -- builders' MED-2 fix) \226\128\148 contained throw/nil both refund below.\n    local ok_g, grp = pcall(coalition.addGroup, COUNTRY_OF[side], Group.Category.GROUND, {\n        name = name, hidden = false, units = units,\n        route = { points = {\n            { type=\"Turning Point\", action=\"On Road\", speed=COL_SPEED, ETA=0, ETA_locked=false,\n              alt=land.getHeight({x=sx, y=sz}), alt_type=\"BARO\", x=sx, y=sz, name=\"Start\", formation_template=\"\" },\n            { type=\"Turning Point\", action=\"On Road\", speed=COL_SPEED, ETA=0, ETA_locked=false,\n              alt=land.getHeight({x=mx, y=mz}), alt_type=\"BARO\", x=mx, y=mz, name=\"Via\", formation_template=\"\" },\n            { type=\"Turning Point\", action=\"On Road\", speed=COL_SPEED, ETA=0, ETA_locked=false,\n              alt=land.getHeight({x=tpos.x, y=tpos.z}), alt_type=\"BARO\",\n              x=tpos.x, y=tpos.z, name=\"Objective\", formation_template=\"\" },\n        } },\n    })\n    if ok_g and grp then\n        S.ground_groups[side][name] = { grp=grp, target_base=target_base, home_base=home_base, want=want }\n        log_fn(string.format(\"GndCol %s: %d units %s \226\134\146 %s\", name, want, home_base, target_base))\n        cs.dbg(\"ground\", \"%s spawned: %d units %s -> %s\", name, want, home_base, target_base)\n        return true\n    end\n    supply.recycle_side(side, \"vehicle\", 1)  -- refund: spawn failed/threw\n    cs.dbg(\"ground\", \"%s SPAWN FAILED %s -> %s (pcall_ok=%s) -> refunded\", name, home_base, target_base, tostring(ok_g))\n    return false\nend\n\n-- \226\148\128\226\148\128 Spawn one SP-artillery/MLRS group behind home_base \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH FRONTLINE_FORCE_ARTILLERY (faction.c:1602-1661): artillery groups start at artillery\n-- nodes supporting the frontline. They then ADVANCE with the front like every frontline_flag\n-- group (highlevl.c:433) \226\128\148 see the 2b arty-advance step in advance_retreat, which walks them to\n-- ARTY_STANDOFF of the nearest enemy base so run_artillery has targets in its fire envelope.\n-- Tagged \"Arty-\" (cas_bai_sead.run_artillery keys on it) and tracked in the SEPARATE\n-- S.arty_groups registry (advance_retreat moves them with arty semantics, not column semantics).\n-- Alternates tube / MLRS per the mlrs_flag toggle (faction.c:1624-1633). Consumes 1 \"vehicle\"\n-- from reserve, exactly like spawn_group.\nlocal function spawn_arty_group(side, home_base, use_mlrs, log_fn)\n    if not supply.consume_side(side, \"vehicle\", 1) then\n        cs.dbg(\"ground\", \"%s artillery ABORT: vehicle reserve exhausted\", cs.SIDE_NAME[side])\n        return false\n    end\n    local home = S.base_pos[home_base]\n    if not home then\n        supply.recycle_side(side, \"vehicle\", 1)\n        return false\n    end\n    -- Ordered slot list (FORMCOMP.DAT ARTILLERY_GROUP :549-562 / MLRS_GROUP :566-579): the battery\n    -- fields 2 guns + supply truck + scout, consumed slot-by-slot (faction.c:661/666) \226\128\148 NOT 4 guns.\n    local slots = use_mlrs and MLRS_SLOTS or ARTY_SLOTS\n    local col   = SIDE_COL[side]\n    local id    = cs.next_id()\n    local name  = string.format(\"Arty-%d-%d\", side, id)\n    -- Place a little behind the base (into its own rear = away from the nearest enemy base).\n    local ex, ez = home.x, home.z + 1\n    local eb = nearest_base_of(cs.ENEMY[side], home)\n    if eb and S.base_pos[eb] then ex, ez = S.base_pos[eb].x, S.base_pos[eb].z end\n    local dx, dz = home.x - ex, home.z - ez\n    local len = math.max(math.sqrt(dx*dx + dz*dz), 1)\n    -- ~1.5 km into the rear; snap off water (a rear offset at a coastal base can be wet), fallback = home.\n    local sp = cs.snap_land(home.x + dx/len * 1500 + math.random(-200, 200),\n                            home.z + dz/len * 1500 + math.random(-200, 200), home.x, home.z)\n    local sx, sz = sp.x, sp.z\n\n    local units = {}\n    for i = 1, math.min(ARTY_GROUP_SIZE, #slots) do\n        local ux, uz = sx + (i-1)*35, sz\n        units[i] = { name = name..\"-\"..i, type = slots[i][col], skill = \"Average\",\n            x = ux, y = uz, alt = land.getHeight({x=ux, y=uz}), alt_type = \"BARO\", heading = 0 }\n    end\n    -- pcall the addGroup: a THROW (e.g. an unverified artillery type name rejected by the DB) must\n    -- refund the consumed vehicle, not leak it (escort builders' MED-2 pattern).\n    local ok_g, grp = pcall(coalition.addGroup, COUNTRY_OF[side], Group.Category.GROUND, {\n        name = name, hidden = false, units = units,\n        route = { points = {\n            { type=\"Turning Point\", action=\"Off Road\", speed=0, ETA=0, ETA_locked=true,\n              alt=land.getHeight({x=sx, y=sz}), alt_type=\"BARO\", x=sx, y=sz, name=\"Hold\", formation_template=\"\" },\n        } },\n    })\n    if ok_g and grp then\n        S.arty_groups[side][name] = { grp = grp, home_base = home_base }\n        log_fn(string.format(\"Artillery %s: %d units (2\195\151%s + truck + scout) at %s\",\n            name, #units, slots[1][col], home_base))\n        cs.dbg(\"ground\", \"%s artillery spawned: %d units lead=%s at %s (mlrs=%s)\",\n            name, #units, slots[1][col], home_base, tostring(use_mlrs))\n        return true\n    end\n    supply.recycle_side(side, \"vehicle\", 1)   -- refund: spawn failed/threw\n    cs.dbg(\"ground\", \"%s artillery SPAWN FAILED at %s (pcall_ok=%s) -> refunded\", name, home_base, tostring(ok_g))\n    return false\nend\n\n-- \226\148\128\226\148\128 Spawn one SECONDARY (second-echelon) frontline group behind home_base \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH FRONTLINE_FORCE_SECONDARY (faction.c:1565-1600): a second-echelon combined-arms group placed at\n-- a road node BEHIND the primary line. Port: spawn it SEC_REAR_OFFSET into home_base's own rear (away\n-- from the nearest enemy base \226\128\148 same away-from-enemy vector the arty uses, but a larger offset so the\n-- secondary sits behind both the primary line and the artillery). Consumes 1 \"vehicle\" from reserve,\n-- refund-on-fail/throw exactly like spawn_group / spawn_arty_group. Tagged \"GndSec-\" so\n-- cas_bai_sead.group_frontline_flag classes it SECONDARY(2) \226\134\146 a BAI target (never CAS, never SEAD).\nlocal function spawn_sec_group(side, home_base, log_fn)\n    if not supply.consume_side(side, \"vehicle\", 1) then\n        log_fn(cs.SIDE_NAME[side] .. \" secondary: vehicle reserve exhausted\")\n        cs.dbg(\"ground\", \"%s spawn_sec_group ABORT: vehicle reserve exhausted\", cs.SIDE_NAME[side])\n        return false\n    end\n    local home = S.base_pos[home_base]\n    if not home then\n        supply.recycle_side(side, \"vehicle\", 1)\n        cs.dbg(\"ground\", \"%s spawn_sec_group ABORT: missing position for %s -> refunded\",\n            cs.SIDE_NAME[side], tostring(home_base))\n        return false\n    end\n    -- Rear vector: away from the nearest enemy base (into this side's own rear).\n    local ex, ez = home.x, home.z + 1\n    local eb = nearest_base_of(cs.ENEMY[side], home)\n    if eb and S.base_pos[eb] then ex, ez = S.base_pos[eb].x, S.base_pos[eb].z end\n    local dx, dz = home.x - ex, home.z - ez\n    local len = math.max(math.sqrt(dx*dx + dz*dz), 1)\n    -- Second-echelon rear offset; snap off water at a coastal base, fallback = the base centre `home`.\n    local sp = cs.snap_land(home.x + dx/len * SEC_REAR_OFFSET + math.random(-200, 200),\n                            home.z + dz/len * SEC_REAR_OFFSET + math.random(-200, 200), home.x, home.z)\n    local sx, sz = sp.x, sp.z\n\n    local comp = sec_group_comp(side)   -- ordered FORMCOMP-secondary slot types (first N)\n    local id   = cs.next_id()\n    local name = string.format(\"GndSec-%d-%d\", side, id)\n    local units = {}\n    for ui, utype in ipairs(comp) do\n        local ux, uz = sx + (ui-1)*30, sz + (ui-1)*15\n        units[ui] = { name=name..\"-\"..ui, type=utype, skill=\"Average\",\n            x=ux, y=uz, alt=land.getHeight({x=ux, y=uz}), alt_type=\"BARO\", heading=0 }\n    end\n    local want = #units\n    -- pcall the addGroup: a THROW (e.g. an unverified secondary type rejected by the DB) must refund\n    -- the consumed vehicle, not leak it (spawn_group / spawn_arty_group MED-2 pattern).\n    local ok_g, grp = pcall(coalition.addGroup, COUNTRY_OF[side], Group.Category.GROUND, {\n        name = name, hidden = false, units = units,\n        route = { points = {\n            { type=\"Turning Point\", action=\"Off Road\", speed=0, ETA=0, ETA_locked=true,\n              alt=land.getHeight({x=sx, y=sz}), alt_type=\"BARO\", x=sx, y=sz, name=\"Hold\", formation_template=\"\" },\n        } },\n    })\n    if ok_g and grp then\n        S.sec_groups[side][name] = { grp = grp, home_base = home_base, want = want }\n        log_fn(string.format(\"GndSec %s: %d units (2nd echelon) behind %s\", name, want, home_base))\n        cs.dbg(\"ground\", \"%s secondary spawned: %d units lead=%s behind %s\", name, want, comp[1], home_base)\n        return true\n    end\n    supply.recycle_side(side, \"vehicle\", 1)   -- refund: spawn failed/threw\n    cs.dbg(\"ground\", \"%s secondary SPAWN FAILED behind %s (pcall_ok=%s) -> refunded\", name, home_base, tostring(ok_g))\n    return false\nend\n\n-- \226\148\128\226\148\128 OOB init: seed the standing frontline + supporting artillery \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.init_oob(log_fn)\n    log_fn = log_fn or function() end\n    S.ground_groups = { [coalition.side.BLUE] = {}, [coalition.side.RED] = {} }\n    S.arty_groups   = { [coalition.side.BLUE] = {}, [coalition.side.RED] = {} }\n    S.sec_groups    = { [coalition.side.BLUE] = {}, [coalition.side.RED] = {} }\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        local fbases = frontline_bases(side)\n        -- WARZONE RESERVE-SEED ANALOG (parser.c:1397-1435): EECH seeds each force's reserve hardware\n        -- from warzone DATA sized to cover the actual OOB placement \226\128\148 the reserve is never smaller\n        -- than what initialise_order_of_battle places. The port's RESERVE_PER_BASE.vehicle (=2) is\n        -- airbase-only scenario data predating the per-frontline-base OOB (tank company + artillery\n        -- battery + SECONDARY second-echelon group \226\128\148 three vehicle groups per frontline base), so\n        -- supplement the vehicle pool up to the real placement demand BEFORE placement, rather than\n        -- hand-tuning the per-base constant.\n        local demand = 3 * #fbases   -- 1 tank + 1 artillery + 1 secondary group per frontline base\n        local have   = supply.reserve_side(side, \"vehicle\")\n        if have < demand then\n            supply.recycle_side(side, \"vehicle\", demand - have)\n            cs.dbg(\"ground\", \"%s OOB vehicle reserve topped up %d -> %d (3 x %d frontline bases; \"\n                .. \"parser.c:1397-1435 warzone reserve-seed analog)\", cs.SIDE_NAME[side], have, demand, #fbases)\n        end\n        local mlrs = false\n        for _, base in ipairs(fbases) do\n            local tgt = nearest_base_of(cs.ENEMY[side], S.base_pos[base])\n            if tgt then spawn_group(side, base, tgt, log_fn) end\n            -- One SP-artillery group supporting each frontline base (faction.c artillery node ~=\n            -- adjacent to a frontline node); alternate tube/MLRS (faction.c:1624-1633 mlrs_flag).\n            spawn_arty_group(side, base, mlrs, log_fn)\n            mlrs = not mlrs\n            -- One SECONDARY (second-echelon) group behind each frontline base (faction.c:1565-1600\n            -- FRONTLINE_FORCE_SECONDARY node behind the primary line). Holds/follows the front (2c).\n            spawn_sec_group(side, base, log_fn)\n        end\n        local n_grp, n_arty, n_sec = 0, 0, 0\n        for _ in pairs(S.ground_groups[side]) do n_grp = n_grp + 1 end\n        for _ in pairs(S.arty_groups[side]) do n_arty = n_arty + 1 end\n        for _ in pairs(S.sec_groups[side]) do n_sec = n_sec + 1 end\n        log_fn(string.format(\"ground OOB: %s frontline = %d group(s) + %d artillery + %d secondary group(s)\",\n            cs.SIDE_NAME[side], n_grp, n_arty, n_sec))\n        cs.dbg(\"ground\", \"init_oob: %s frontline bases=%d, tank groups=%d, artillery groups=%d, secondary groups=%d\",\n            cs.SIDE_NAME[side], #fbases, n_grp, n_arty, n_sec)\n    end\nend\n\n-- Nearest enemy base to pos NOT already targeted by another friendly group (occupancy\n-- deconfliction, highlevl.c:514 side_occupying check), excluding `self_base`.\nlocal function nearest_unoccupied_enemy(side, pos, occupied)\n    local enemy = cs.ENEMY[side]\n    local best, best_d = nil, math.huge\n    for name, owner in pairs(S.base_owner) do\n        if owner == enemy and not occupied[name] then\n            local bp = S.base_pos[name]\n            if bp then\n                local d = cs.dist2d(pos.x, pos.z, bp.x, bp.z)\n                if d < best_d then best_d = d; best = name end\n            end\n        end\n    end\n    return best\nend\n\n-- \226\148\128\226\148\128 Advance / retreat / reinforce tick \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function advance_retreat(side, log_fn)\n    local groups = S.ground_groups[side]\n    if not groups then return end\n    local enemy = cs.ENEMY[side]\n\n    -- 1. Prune dead; note which bases already have a live group (home + objective occupancy).\n    local alive_count, homes_covered, occupied = 0, {}, {}\n    for gname, rec in pairs(groups) do\n        if not cs.group_is_alive(rec.grp) then\n            groups[gname] = nil  -- dead \226\134\146 replaced by reinforcement below (ground regen, #14)\n        else\n            alive_count = alive_count + 1\n            if rec.home_base then homes_covered[rec.home_base] = true end\n            if rec.target_base and S.base_owner[rec.target_base] == enemy then\n                occupied[rec.target_base] = true\n            end\n        end\n    end\n\n    -- 2. Retarget / retreat survivors.\n    local n_retreated, n_advanced = 0, 0\n    for gname, rec in pairs(groups) do\n        if cs.group_is_alive(rec.grp) then\n            local gpos = lead_pos(rec.grp)\n            if gpos then\n                local frac   = alive_fraction(rec.grp, rec.want or 4)\n                local fb, fd = nearest_base_of(side, gpos)\n                if frac < CUTOFF_HP then\n                    -- Retreat: weakened group falls back to the nearest friendly base and HOLDS\n                    -- there (advance is gated on strength below, so no flip-flop).\n                    if fb and fd and fd > 20000 and rec.target_base ~= fb then\n                        rec.target_base = fb\n                        reroute(rec.grp, S.base_pos[fb])\n                        log_fn(string.format(\"GndCol %s retreating \226\134\146 %s (str %.0f%%)\", gname, fb, frac*100))\n                        cs.dbg(\"ground\", \"%s retreating -> %s (str=%.0f%%)\", gname, fb, frac * 100)\n                        n_retreated = n_retreated + 1\n                    end\n                else\n                    -- Advance: only healthy groups advance, to the nearest UNOCCUPIED enemy base,\n                    -- if the current objective is no longer enemy-owned or a closer node opened up.\n                    if S.base_owner[rec.target_base] ~= enemy then\n                        occupied[rec.target_base] = nil\n                        local eb = nearest_unoccupied_enemy(side, gpos, occupied)\n                        if eb and rec.target_base ~= eb then\n                            rec.target_base = eb\n                            occupied[eb] = true\n                            reroute(rec.grp, S.base_pos[eb])\n                            log_fn(string.format(\"GndCol %s advancing \226\134\146 %s\", gname, eb))\n                            cs.dbg(\"ground\", \"%s advancing -> %s\", gname, eb)\n                            n_advanced = n_advanced + 1\n                        end\n                    end\n                end\n            end\n        end\n    end\n\n    -- 2b. ARTILLERY ADVANCE (live-validation fix): EECH's advance candidate filter is\n    -- `if (group_database[sub_type].frontline_flag)` \226\128\148 NON-zero \226\128\148 so ARTILLERY(3) groups advance\n    -- with the front exactly like PRIMARY tank groups (highlevl.c:433; the earlier \"artillery\n    -- never advances\" note on spawn_arty_group was a misreading \226\128\148 faction.c artillery nodes are\n    -- only the INITIAL placement). Without this, batteries parked at their home base sat\n    -- permanently outside the 20 km fire envelope and run_artillery assigned 0 missions all\n    -- campaign. A battery moves toward the nearest enemy base and HALTS at ARTY_STANDOFF, inside\n    -- firing range; it re-routes when the front (nearest enemy base) changes.\n    local n_arty_adv = 0\n    for aname, arec in pairs((S.arty_groups and S.arty_groups[side]) or {}) do\n        if cs.group_is_alive(arec.grp) then\n            local apos = lead_pos(arec.grp)\n            if apos then\n                local eb, ed = nearest_base_of(enemy, apos)\n                local bp = eb and S.base_pos[eb]\n                if eb and bp and ed and ed > ARTY_STANDOFF and arec.moving_to ~= eb then\n                    local dx, dz = bp.x - apos.x, bp.z - apos.z\n                    local len = math.max(math.sqrt(dx*dx + dz*dz), 1)\n                    -- DISPERSED firing positions: every battery heading for the same enemy base\n                    -- must NOT share one halt coordinate \226\128\148 that live-piled all 5 batteries onto a\n                    -- single road point (converging columns jam the DCS ground AI). EECH spreads\n                    -- artillery across DISTINCT artillery nodes along the front (faction.c:\n                    -- 1602-1661, one node per group), so each battery takes its own slot on the\n                    -- standoff ring: a deterministic lateral offset (perpendicular to the\n                    -- approach), slot index from the battery's spawn id, ~2 km apart.\n                    local id   = tonumber(aname:match(\"(%d+)$\")) or 0\n                    local slot = (id % 5) - 2                       -- -2..2 \226\134\146 5 spread positions\n                    local px, pz = -dz / len, dx / len              -- unit perpendicular\n                    -- Snap the deploy point off water so a battery isn't ordered into the sea and\n                    -- stranded on the shoreline; fallback = the battery's CURRENT position (don't move\n                    -- if no land found near the standoff slot \226\128\148 hold rather than march into water).\n                    local dp = cs.snap_land(bp.x - dx/len * ARTY_STANDOFF + px * slot * 2000,\n                                            bp.z - dz/len * ARTY_STANDOFF + pz * slot * 2000,\n                                            apos.x, apos.z)\n                    arty_reroute(arec.grp, { x = dp.x, z = dp.z })\n                    arec.moving_to = eb\n                    n_arty_adv = n_arty_adv + 1\n                    cs.dbg(\"ground\", \"%s artillery advancing toward %s (halt at %.0f km standoff, slot %+d)\",\n                        aname, eb, ARTY_STANDOFF / 1000, slot)\n                end\n            end\n        else\n            S.arty_groups[side][aname] = nil   -- prune dead batteries (no auto-replacement; reserve-bound)\n        end\n    end\n\n    -- 2c. SECONDARY (second-echelon) MOVEMENT: EECH secondaries sit at road nodes BEHIND the primary\n    -- line and are pulled forward as the warm-node front advances (faction.c:1565-1600 place; the\n    -- advance candidate filter `if (group_database[sub_type].frontline_flag)` at highlevl.c:433 is\n    -- NON-zero so SECONDARY(2) advances too). DCS has no node graph, so the port proxies \"behind the\n    -- moving front\" by tracking each secondary to its side's NEAREST FRIENDLY FRONTLINE base and holding\n    -- SEC_STANDOFF into that base's rear; when the front moves (the nearest friendly frontline base\n    -- changes) the group re-routes to follow. It never drives at enemy bases (PRIMARY's job).\n    local fbases = frontline_bases(side)\n    local n_sec_moved = 0\n    for sname, srec in pairs((S.sec_groups and S.sec_groups[side]) or {}) do\n        if cs.group_is_alive(srec.grp) then\n            local spos = lead_pos(srec.grp)\n            if spos and #fbases > 0 then\n                -- nearest friendly frontline base to this group\n                local fb, fd = nil, math.huge\n                for _, b in ipairs(fbases) do\n                    local bp = S.base_pos[b]\n                    if bp then\n                        local d = cs.dist2d(spos.x, spos.z, bp.x, bp.z)\n                        if d < fd then fd = d; fb = b end\n                    end\n                end\n                if fb and srec.behind_base ~= fb then\n                    local bp = S.base_pos[fb]\n                    -- Rear vector for that frontline base = away from ITS nearest enemy base.\n                    local eb = nearest_base_of(enemy, bp)\n                    local ep = eb and S.base_pos[eb] or { x = bp.x, z = bp.z - 1 }\n                    local dx, dz = bp.x - ep.x, bp.z - ep.z\n                    local len = math.max(math.sqrt(dx*dx + dz*dz), 1)\n                    -- Deterministic lateral slot (from spawn id) so co-located secondaries don't pile on\n                    -- one hold coordinate (mirrors the arty standoff-ring dispersion).\n                    local id   = tonumber(sname:match(\"(%d+)$\")) or 0\n                    local slot = (id % 5) - 2\n                    local px, pz = -dz / len, dx / len\n                    -- Snap the follow-the-front hold point off water; fallback = the group's CURRENT\n                    -- position (hold rather than route the second echelon into the sea).\n                    local dp = cs.snap_land(bp.x + dx/len * SEC_STANDOFF + px * slot * 1500,\n                                            bp.z + dz/len * SEC_STANDOFF + pz * slot * 1500,\n                                            spos.x, spos.z)\n                    arty_reroute(srec.grp, { x = dp.x, z = dp.z })\n                    srec.behind_base = fb\n                    n_sec_moved = n_sec_moved + 1\n                    cs.dbg(\"ground\", \"%s secondary following front: holding %.0f km behind %s (slot %+d)\",\n                        sname, SEC_STANDOFF / 1000, fb, slot)\n                end\n            end\n        else\n            S.sec_groups[side][sname] = nil   -- prune dead secondaries (no auto-replacement; reserve-bound)\n        end\n    end\n\n    -- 3. Reinforce: one group per frontline base that has lost its company (draws from the\n    --    depleting \"vehicle\" reserve \226\128\148 the pool exhaustion is what ends the ground war).\n    -- No survival gate: EECH create_advance_and_retreat_tasks (highlevl.c) reinforces/advances the\n    -- ground front regardless of force strength \226\128\148 the pool exhaustion is the only brake. The former\n    -- STRENGTH_SURVIVAL skip was invented (Cluster E).\n    local n_reinforced = 0\n    for _, base in ipairs(frontline_bases(side)) do\n        if not homes_covered[base] then\n            local tgt = nearest_unoccupied_enemy(side, S.base_pos[base], occupied)\n                      or nearest_base_of(enemy, S.base_pos[base])\n            if tgt and spawn_group(side, base, tgt, log_fn) then\n                homes_covered[base] = true\n                if S.base_owner[tgt] == enemy then occupied[tgt] = true end\n                n_reinforced = n_reinforced + 1\n            else\n                break  -- reserve dry\n            end\n        end\n    end\n    cs.dbg(\"ground\", \"%s advance/retreat tick: %d alive, %d retreated, %d advanced, %d reinforced, %d arty advancing, %d secondary moved\",\n        cs.SIDE_NAME[side], alive_count, n_retreated, n_advanced, n_reinforced, n_arty_adv, n_sec_moved)\nend\n\n-- \226\148\128\226\148\128 Persistence respawn (WAVE 2) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Re-create a saved ground/arty/sec group from a persist.lua SUMMARY on campaign restore. RESERVE-\n-- NEUTRAL by design: the restored S.base_ledger already reflects the \"vehicle\" these groups consumed\n-- when first spawned, so respawning must NOT consume (or refund) reserve again \226\128\148 it only re-materialises\n-- the DCS group at its saved position with its saved surviving unit count and re-registers it. The unit\n-- composition is the FIRST n ordered FORMCOMP slots for the kind (exactly as the original spawn built\n-- it, faction.c:661/666); the mobile-OOB movement re-derives on the next advance/retreat tick.\n-- summ = { name, side, kind \226\136\136 {\"primary\",\"arty\",\"sec\"}, home_base, target_base, n_alive, want, lead={x,z} }\nlocal KIND_SLOTS = { primary = PRIMARY_SLOTS, arty = ARTY_SLOTS, sec = SECONDARY_SLOTS }\nlocal KIND_REG   = { primary = \"ground_groups\", arty = \"arty_groups\", sec = \"sec_groups\" }\n\nfunction M.respawn_saved(summ, log_fn)\n    log_fn = log_fn or function() end\n    if type(summ) ~= \"table\" then return false end\n    local side  = summ.side\n    local kind  = summ.kind\n    local slots = KIND_SLOTS[kind]\n    local regk  = KIND_REG[kind]\n    local lead  = summ.lead\n    if not slots or not regk or not lead or (side ~= coalition.side.BLUE and side ~= coalition.side.RED) then\n        cs.dbg(\"ground\", \"respawn_saved SKIP: bad summary (kind=%s side=%s)\", tostring(kind), tostring(side))\n        return false\n    end\n    local col = SIDE_COL[side]\n    local n   = math.max(1, math.min(tonumber(summ.n_alive) or 1, #slots))\n    -- Snap the saved lead point off water (a coastal front can drift wet); fallback = the point itself.\n    local sp = cs.snap_land(lead.x, lead.z, lead.x, lead.z)\n    local sx, sz = sp.x, sp.z\n    local name = summ.name or string.format(\"Gnd-%s-%d-%d\", tostring(kind), side, cs.next_id())\n\n    local units = {}\n    for i = 1, n do\n        local ux, uz = sx + (i - 1) * 30, sz + (i - 1) * 15\n        units[i] = { name = name .. \"-\" .. i, type = slots[i][col], skill = \"Average\",\n            x = ux, y = uz, alt = land.getHeight({ x = ux, y = uz }), alt_type = \"BARO\", heading = 0 }\n    end\n\n    -- Route: a primary column drives toward its saved objective (so it keeps advancing/capturing);\n    -- arty/sec spawn on a hold point and re-route themselves on the next tick (moving_to/behind_base\n    -- start nil \226\134\146 2b/2c re-issue their standoff route).\n    local points\n    local tpos = summ.target_base and S.base_pos[summ.target_base]\n    if kind == \"primary\" and tpos then\n        local mx, mz = (sx + tpos.x) * 0.5, (sz + tpos.z) * 0.5\n        points = {\n            { type = \"Turning Point\", action = \"On Road\", speed = COL_SPEED, ETA = 0, ETA_locked = false,\n              alt = land.getHeight({ x = sx, y = sz }), alt_type = \"BARO\", x = sx, y = sz, name = \"Start\", formation_template = \"\" },\n            { type = \"Turning Point\", action = \"On Road\", speed = COL_SPEED, ETA = 0, ETA_locked = false,\n              alt = land.getHeight({ x = mx, y = mz }), alt_type = \"BARO\", x = mx, y = mz, name = \"Via\", formation_template = \"\" },\n            { type = \"Turning Point\", action = \"On Road\", speed = COL_SPEED, ETA = 0, ETA_locked = false,\n              alt = land.getHeight({ x = tpos.x, y = tpos.z }), alt_type = \"BARO\", x = tpos.x, y = tpos.z, name = \"Objective\", formation_template = \"\" },\n        }\n    else\n        points = {\n            { type = \"Turning Point\", action = \"Off Road\", speed = 0, ETA = 0, ETA_locked = true,\n              alt = land.getHeight({ x = sx, y = sz }), alt_type = \"BARO\", x = sx, y = sz, name = \"Hold\", formation_template = \"\" },\n        }\n    end\n\n    local ok_g, grp = pcall(coalition.addGroup, COUNTRY_OF[side], Group.Category.GROUND, {\n        name = name, hidden = false, units = units, route = { points = points },\n    })\n    if ok_g and grp then\n        S[regk] = S[regk] or { [coalition.side.BLUE] = {}, [coalition.side.RED] = {} }\n        S[regk][side] = S[regk][side] or {}\n        if kind == \"primary\" then\n            S[regk][side][name] = { grp = grp, target_base = summ.target_base, home_base = summ.home_base, want = summ.want or n }\n        elseif kind == \"sec\" then\n            S[regk][side][name] = { grp = grp, home_base = summ.home_base, want = summ.want or n }\n        else -- arty\n            S[regk][side][name] = { grp = grp, home_base = summ.home_base }\n        end\n        cs.dbg(\"ground\", \"respawn_saved: %s (%s) %d units at (%.0f,%.0f) home=%s target=%s\",\n            name, tostring(kind), n, sx, sz, tostring(summ.home_base), tostring(summ.target_base))\n        return true\n    end\n    cs.dbg(\"ground\", \"respawn_saved SPAWN FAILED: %s (%s) pcall_ok=%s\", name, tostring(kind), tostring(ok_g))\n    return false\nend\n\nfunction M.schedule_ground(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"ground\", \"%s scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], initial_offset, GND_PERIOD)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        -- Item 6 (LITERAL post-victory semantics): the ground war continues after the win is declared \226\128\148\n        -- EECH fc_msgs.c:163 gates ONLY the win-check re-award, never the highlevl.c generators. The\n        -- prior Cluster-E ground-advance suppression is removed (it was a proxy, not the literal C).\n        local ok, err = pcall(advance_retreat, side, log_fn)\n        if not ok then log_fn(\"ground error: \" .. tostring(err)) end\n        return t + GND_PERIOD\n    end, nil, timer.getTime() + initial_offset)\nend\n\nreturn M\n"
__modules["heli_war"] = "-- heli_war.lua\n-- EECH source: aphavoc/source/ai/highlevl/highlevl.c (create_cas_tasks / anti-armour tasks),\n--   aphavoc/source/ai/highlevl/suitable.c (suitability matrix \226\128\148 ATTACK_HELICOPTER is the primary\n--   suitable type for anti-armour / CAS / armed-recon / escort in campaign),\n--   aphavoc/source/entity/helicopter/* (attack helicopter behaviour).\n--\n-- EECH (\"Enemy Engaged\": Comanche vs Hokum / Apache vs Havoc) is FUNDAMENTALLY a helicopter combat\n-- sim \226\128\148 attack helicopters are the main offensive arm and the bulk of the campaign's sorties. The\n-- fixed-wing strike/CAS/BAI/SEAD tasks (attack_waves / cas_bai_sead) model the air-force layer; THIS\n-- module models the rotary-wing war that is the heart of the game:\n--   1. Anti-armour sorties  \226\128\148 attack-heli sections hunt enemy frontline ground groups (core mission)\n--   2. Hunter-killer recon  \226\128\148 armed recon along the front, engaging ground AND air (incl. enemy helis)\n--   3. Attack-heli escort   \226\128\148 escorts transport/BDA/troop-insertion helis into hostile airspace\n-- All draw from the per-side \"heli\" reserve (finite; recycled on RTB by supply.make_land_handler).\n\nlocal cs      = require(\"campaign_state\")\nlocal croute  = require(\"croute\")\nlocal ov      = require(\"map_overlay\")\nlocal config  = require(\"config\")\nlocal board   = require(\"task_board\")\nlocal S       = cs.S\nlocal M       = {}\n\n-- \226\148\128\226\148\128 Attack helicopter roster (hoisted to config: attack_heli type + payloads.attack_heli pylons) \226\148\128\226\148\128\n-- fuel is a spawn-kinematics amount (not warzone type/economy data) \226\134\146 kept module-local per side.\nlocal HELI_FUEL = { [coalition.side.BLUE] = 1600, [coalition.side.RED] = 1500 }\nlocal ATTACK = {}\nfor _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n    ATTACK[side] = {\n        country = config.C.countries[side],\n        type    = config.C.types.aircraft[side].attack_heli,\n        pylons  = config.C.payloads[side].attack_heli,\n        fuel    = HELI_FUEL[side],\n    }\nend\n\n-- A section = 2 attack helis (draws 2 from the \"heli\" reserve). Used by build_attack_heli.\n-- (The retired anti_armour / hunter_killer scheduler PERIODS were deleted in Cluster H \226\128\148 the rotary\n-- frontline fight is now CAS + BAI, launched by cas_bai_sead via this module's build_attack_heli.)\nlocal SECTION_SIZE = 2\n\n-- Attack profile: low and slow, nap-of-the-earth-ish.\nlocal HELI_ALT   = 60      -- m AGL cruise\nlocal HELI_SPEED = 55      -- m/s \226\137\136 107 kt\nlocal ENGAGE_DIST = 12000  -- m; attack helis engage targets within this range\n\n-- NOTE: frontline_point, heli_sorties and front_targets were DELETED in Cluster H \226\128\148 they only fed the\n-- retired schedule_anti_armour / schedule_hunter_killer schedulers (a PORT INVENTION; EECH has no\n-- anti_armour/hunter_killer task \226\128\148 the rotary frontline fight IS CAS + BAI). heli_sorties' strength-\n-- ratio sortie scaler was itself an invented posture mechanic (Cluster E territory). This module now\n-- keeps only the shared attack-heli / escort BUILDERS (build_attack_heli, spawn_escort).\n\n-- \226\148\128\226\148\128 build_attack_heli(side, base_name, target_pos, role, log_fn) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- BUILDER (task-board contract): spawns an attack-heli section FROM base_name. The board has\n-- already consumed SECTION_SIZE \"heli\" from base_name's ledger (refunds on nil). Returns the\n-- group on success, nil on failure. role \"anti_armour\" (attack ground) or \"hunter_killer\"\n-- (armed recon: ground + air).\nlocal function build_attack_heli(side, base_name, target_pos, role, log_fn)\n    log_fn = log_fn or function() end\n    -- Launch position: a real Airbase (AIRDROME or HELIPAD) if the base has one \226\128\148 helis launch from\n    -- fixed-wing airbases too \226\128\148 otherwise the logical base's own coordinates (a zone-authored FARP has\n    -- no Airbase object). Helis start from a real airbase via TakeOff-from-parking, or from a bare\n    -- position via a GROUND start. Only truly-unknown bases (no Airbase AND no S.base_pos) fail.\n    local home_ab = Airbase.getByName(base_name)\n    local cfg    = ATTACK[side]\n    local ab_pos, ab_id\n    if home_ab then\n        ab_pos, ab_id = home_ab:getPosition().p, home_ab:getID()\n    else\n        local bp = S.base_pos and S.base_pos[base_name]\n        if not bp then\n            cs.dbg(\"heli\", \"%s heli ABORT: base %s has no Airbase and no base_pos\",\n                cs.SIDE_NAME[side], tostring(base_name))\n            return nil\n        end\n        local gy = 0\n        pcall(function() gy = land.getHeight({ x = bp.x, y = bp.z }) or 0 end)\n        ab_pos = { x = bp.x, y = gy, z = bp.z }   -- ground start at the FARP coordinates\n    end\n    local bx, by = cs.wp_xy(ab_pos)\n    local tx, ty = cs.wp_xy(target_pos)\n    local sid    = cs.next_id()\n    local ROLE_LABEL = { anti_armour = \"AA\", hunter_killer = \"HK\", cas = \"CAS\", bai = \"BAI\" }\n    local gname  = string.format(\"Heli-%s-%d-%d\", ROLE_LABEL[role] or \"AA\", side, sid)\n\n    -- Hunter-killer engages air too (Comanche-vs-Hokum heli combat); anti-armour focuses ground.\n    local target_types = (role == \"hunter_killer\")\n        and { \"Ground Units\", \"Helicopters\", \"Air\" }\n        or  { \"Ground Units\", \"Helicopters\" }\n\n    local units = {}\n    for i = 1, SECTION_SIZE do\n        units[i] = {\n            name = gname .. \"-\" .. i, type = cfg.type, skill = \"High\",\n            x = ab_pos.x + (i-1)*40, y = ab_pos.z, alt = ab_pos.y, alt_type = \"BARO\",\n            speed = 0, heading = cs.heading_to(ab_pos.x, ab_pos.z, target_pos.x, target_pos.z),\n            payload = { fuel = cfg.fuel, flare = 60, chaff = 60, gun = 100, pylons = cfg.pylons },\n        }\n    end\n\n    -- Depart/RTB points: a real airbase uses TakeOff-from-parking + Landing; a bare-coordinate FARP\n    -- uses a ground start (From Ground Area) and returns to a hover point over its own position.\n    local depart, rtb\n    if ab_id then\n        depart = { type=\"TakeOff\", action=\"From Parking Area\", airdromeId=ab_id,\n                   alt=ab_pos.y, alt_type=\"BARO\", speed=0, ETA=0, ETA_locked=true,\n                   x=bx, y=by, name=\"Depart\", formation_template=\"\" }\n        rtb    = { type=\"Land\", action=\"Landing\", airdromeId=ab_id, alt=ab_pos.y, alt_type=\"BARO\",\n                   speed=HELI_SPEED, ETA=0, ETA_locked=false, x=bx, y=by, name=\"RTB\", formation_template=\"\" }\n    else\n        depart = { type=\"TakeOffGroundHot\", action=\"From Ground Area Hot\", alt=ab_pos.y, alt_type=\"BARO\",\n                   speed=0, ETA=0, ETA_locked=true, x=bx, y=by, name=\"Depart\", formation_template=\"\" }\n        rtb    = { type=\"Turning Point\", action=\"Turning Point\", alt=HELI_ALT, alt_type=\"RADIO\",\n                   speed=HELI_SPEED, ETA=0, ETA_locked=false, x=bx, y=by, name=\"RTB\", formation_template=\"\" }\n    end\n    local gspec = { name = gname, task = \"CAS\", hidden = false, units = units, route = { points = croute.expand({\n        depart,\n        { type=\"Turning Point\", action=\"Turning Point\", alt=HELI_ALT, alt_type=\"RADIO\",\n          speed=HELI_SPEED, ETA=0, ETA_locked=false, x=tx, y=ty, name=\"Engage\", formation_template=\"\",\n          task = { id=\"ComboTask\", params={ tasks={ [1]={ number=1, auto=true, id=\"EngageTargets\",\n            enabled=true, params={ maxDist=ENGAGE_DIST, priority=0, targetTypes=target_types } } }}}},\n        rtb,\n    }, side, { alt=HELI_ALT, alt_type=\"RADIO\", speed=HELI_SPEED, name=\"Nav\" }) }}\n    if ab_id then gspec.airdromeId = ab_id end\n    local _ok, grp = pcall(coalition.addGroup, cfg.country, Group.Category.HELICOPTER, gspec)\n    if _ok and grp then\n        ov.add_task_arrow(gname, ab_pos, target_pos, side)   -- Item 4: key by group name (GC backstop reaps it)\n        log_fn(string.format(\"%s %s heli section (%dx%s) from %s \226\134\146 (%.0f,%.0f)\",\n            cs.SIDE_NAME[side], role, SECTION_SIZE, cfg.type, base_name, target_pos.x, target_pos.z))\n        cs.dbg(\"heli\", \"%s %s heli section #%d spawned from %s (ground_start=%s)\",\n            cs.SIDE_NAME[side], role, sid, base_name, tostring(ab_id == nil))\n        return grp\n    end\n    cs.dbg(\"heli\", \"%s heli spawn FAILED at %s (type=%s ground_start=%s): pcall_ok=%s err=%s\",\n        cs.SIDE_NAME[side], tostring(base_name), tostring(cfg.type), tostring(ab_id == nil),\n        tostring(_ok), tostring(grp))\n    return nil\nend\n\n-- NOTE: create_heli_task, schedule_anti_armour and schedule_hunter_killer were DELETED in Cluster H.\n-- They were a PORT INVENTION (EECH has no anti_armour/hunter_killer task) already retired from\n-- game_loop; the rotary frontline fight is CAS + BAI, launched by cas_bai_sead through the shared\n-- build_attack_heli builder below.\n\n-- \226\148\128\226\148\128 Attack-heli escort (called when a transport/BDA/troop-insertion heli launches) \226\148\128\226\148\128\n-- BUILDER: spawns a single attack heli FROM base_name to shepherd a transport toward target_pos.\nlocal function build_escort(side, base_name, target_pos, log_fn)\n    log_fn = log_fn or function() end\n    local home_ab = Airbase.getByName(base_name)\n    if not home_ab then\n        cs.dbg(\"heli\", \"%s build_escort ABORT: base %s not found\", cs.SIDE_NAME[side], tostring(base_name))\n        return nil\n    end\n    local cfg    = ATTACK[side]\n    local ab_pos = home_ab:getPosition().p\n    local bx, by = cs.wp_xy(ab_pos)\n    local tx, ty = cs.wp_xy(target_pos)\n    local sid    = cs.next_id()\n    local gname  = string.format(\"Heli-ESC-%d-%d\", side, sid)\n\n    local _ok, grp = pcall(coalition.addGroup, cfg.country, Group.Category.HELICOPTER, {\n        name = gname, task = \"Escort\", hidden = false, airdromeId = home_ab:getID(),\n        units = {{ name=gname..\"-1\", type=cfg.type, skill=\"High\",\n            x=ab_pos.x, y=ab_pos.z, alt=ab_pos.y, alt_type=\"BARO\", speed=0,\n            heading=cs.heading_to(ab_pos.x, ab_pos.z, target_pos.x, target_pos.z),\n            payload={ fuel=cfg.fuel, flare=60, chaff=60, gun=100, pylons=cfg.pylons } }},\n        route = { points = croute.expand({\n            { type=\"TakeOff\", action=\"From Parking Area\", airdromeId=home_ab:getID(),\n              alt=ab_pos.y, alt_type=\"BARO\", speed=0, ETA=0, ETA_locked=true,\n              x=bx, y=by, name=\"Depart\", formation_template=\"\" },\n            { type=\"Turning Point\", action=\"Turning Point\", alt=HELI_ALT, alt_type=\"RADIO\",\n              speed=HELI_SPEED, ETA=0, ETA_locked=false, x=tx, y=ty, name=\"Escort\", formation_template=\"\",\n              task = { id=\"ComboTask\", params={ tasks={ [1]={ number=1, auto=true, id=\"EngageTargets\",\n                enabled=true, params={ maxDist=ENGAGE_DIST, priority=0,\n                targetTypes={ \"Ground Units\", \"Helicopters\", \"Air\" } } } }}}},\n            { type=\"Land\", action=\"Landing\", airdromeId=home_ab:getID(), alt=ab_pos.y, alt_type=\"BARO\",\n              speed=HELI_SPEED, ETA=0, ETA_locked=false, x=bx, y=by, name=\"RTB\", formation_template=\"\" },\n        }, side, { alt=HELI_ALT, alt_type=\"RADIO\", speed=HELI_SPEED, name=\"Nav\" })},\n    })\n    if _ok and grp then\n        log_fn(string.format(\"%s attack-heli escort #%d \226\134\146 (%.0f,%.0f)\", cs.SIDE_NAME[side], sid, target_pos.x, target_pos.z))\n        cs.dbg(\"heli\", \"%s escort #%d spawned from %s\", cs.SIDE_NAME[side], sid, base_name)\n        return grp\n    end\n    cs.dbg(\"heli\", \"%s escort #%d SPAWN FAILED from %s: pcall_ok=%s err=%s\",\n        cs.SIDE_NAME[side], sid, base_name, tostring(_ok), tostring(grp))\n    return nil\nend\n\n-- \226\148\128\226\148\128 spawn_escort(side, target_pos, log_fn) \226\128\148 SINGLE-SHOT EXPORT (never-replace list) \226\148\128\226\148\128\n-- Reimplemented as an immediate create_task wrapper (create_escort_task at assignment, assign.c:598):\n-- the board picks the launch base from the \"heli\" ledger and calls build_escort. Same signature.\nfunction M.spawn_escort(side, target_pos, log_fn)\n    log_fn = log_fn or function() end\n    if not target_pos then\n        cs.dbg(\"heli\", \"%s spawn_escort ABORT: no target_pos\", cs.SIDE_NAME[side])\n        return false\n    end\n    cs.dbg(\"heli\", \"%s spawn_escort: queueing immediate escort task\", cs.SIDE_NAME[side])\n    board.create_task({\n        type = \"heli_escort\", side = side, count = 1, immediate = true, log_fn = log_fn,\n        target = { pos = target_pos },\n        builder = function(base_name) return build_escort(side, base_name, target_pos, log_fn) end,\n    })\n    return true\nend\n\n-- Exposed so cas_bai_sead can launch the CAS/BAI frontline fight as ATTACK-HELICOPTER sections from\n-- FARPs (EECH: CAS/BAI are helicopter-eligible, ts_dbase.c landing_types :511/:329, and the rotary\n-- frontline fight IS CAS/BAI \226\128\148 this replaces the invented anti_armour/hunter_killer schedulers).\nM.build_attack_heli = build_attack_heli\n\nreturn M\n"
__modules["imap"] = "-- imap.lua\n-- EECH source: aphavoc/source/ai/highlevl/imaps.c\n--   initialise_imaps(), normalise_importance_imaps(), normalise_base_distance_imaps(),\n--   normalise_air_defence_imaps(), normalise_surface_defence_imaps(),\n--   normalise_inlfuence_map() (min-max normalise to 0\226\128\147255 then / 255.0),\n--   update_keysite_distance_to_friendly_base() \226\128\148 inverse-square falloff within air_coverage_radius,\n--   update_imap_surface_to_air_defence_level()  \226\128\148 AIR_SCAN_RANGE * 10 exaggeration,\n--   update_imap_surface_to_surface_defence_level() \226\128\148 SURFACE_SCAN_RANGE * 10 exaggeration.\n--\n-- DCS proxy: EECH stores values in a 2D sector grid.  DCS has no sector grid, so we\n-- compute per-base proxy values using the same falloff formulas; imap.get() interpolates\n-- for any world position via inverse-distance weighting from the known base positions.\n--\n-- Layers (string keys, mirrors imap_types enum):\n--   M.BASE_DISTANCE  \226\128\148 proximity to friendly bases (inverse-square within air_coverage_radius)\n--   M.AIR_DEFENCE    \226\128\148 enemy AA threat coverage (AIR_SCAN_RANGE \195\151 10 exaggeration)\n--   M.SURFACE_DEFENCE\226\128\148 enemy surface-to-surface threat (SURFACE_SCAN_RANGE \195\151 10)\n--   M.IMPORTANCE     \226\128\148 keysite strategic importance (health \195\151 ownership)\n--\n-- Period: each layer refreshes every 120 s, staggered 20 s apart (mirrors EECH's\n--         separate update_imap_* calls registered at different offsets).\n\nlocal cs = require(\"campaign_state\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- \226\148\128\226\148\128 Layer name constants (mirrors imap_types enum) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nM.BASE_DISTANCE   = \"BASE_DISTANCE\"\nM.AIR_DEFENCE     = \"AIR_DEFENCE\"\nM.SURFACE_DEFENCE = \"SURFACE_DEFENCE\"\nM.IMPORTANCE      = \"IMPORTANCE\"\n\n-- \226\148\128\226\148\128 EECH constants \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- air_coverage_radius: keysite_database[sub_type].air_coverage_radius.\n-- All Caucasus airbases use the same default (not per-keysite in our approximation).\nlocal AIR_COVERAGE_RADIUS    = 150000  -- metres; proxy for keysite air_coverage_radius\nlocal IMPORTANCE_RADIUS      = 100000  -- metres; proxy for keysite importance_radius\nlocal AIR_SCAN_EXAGGERATION  = 10.0   -- EECH: radius = AIR_SCAN_RANGE * 10 / SECTOR_SIDE_LENGTH\nlocal SURF_SCAN_EXAGGERATION = 10.0   -- EECH: radius = SURFACE_SCAN_RANGE * 10 / SECTOR_SIDE_LENGTH\nlocal DEFAULT_AIR_SCAN_RANGE  = 25000 -- metres; proxy for FLOAT_TYPE_AIR_SCAN_RANGE on AA units\nlocal DEFAULT_SURF_SCAN_RANGE = 15000 -- metres; proxy for FLOAT_TYPE_SURFACE_SCAN_RANGE\nlocal AA_THREAT_VALUE         = 1.0   -- FLOAT_TYPE_POTENTIAL_SURFACE_TO_AIR_THREAT proxy\nlocal SURF_THREAT_VALUE       = 1.0   -- FLOAT_TYPE_POTENTIAL_SURFACE_TO_SURFACE_THREAT proxy\n\nlocal UPDATE_PERIOD  = 120  -- seconds per layer; four layers = one full cycle per 480 s\nlocal LAYER_STAGGER  = 20   -- seconds between successive layer updates\n\n-- \226\148\128\226\148\128 Raw storage: imap_raw[layer][side][base_name] = float (unnormalised) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- \226\148\128\226\148\128 Normalised: imap_nrm[layer][side][base_name] = 0.0\226\128\1471.0 \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Wave 1: the layer store now lives on S (S.imap.raw / S.imap.nrm) so the influence-map state is part\n-- of the persistence surface (GOAL P2). These module-local names are REFERENCES into S.imap \226\128\148 the\n-- get()/update API and every consumer are unchanged; S (and thus S.imap) is rebuilt fresh per inject,\n-- and M.init() zeroes the sub-tables exactly as before. The `or` guard is belt-and-suspenders: the\n-- S literal already defines S.imap, so this only ever reuses the existing tables.\nS.imap = S.imap or { raw = {}, nrm = {} }\nlocal imap_raw = S.imap.raw\nlocal imap_nrm = S.imap.nrm\n\nlocal LAYERS = { M.BASE_DISTANCE, M.AIR_DEFENCE, M.SURFACE_DEFENCE, M.IMPORTANCE }\nlocal SIDES  = { coalition.side.BLUE, coalition.side.RED }\n\n-- Table entry count (debug summaries only \226\128\148 never used in a hot per-cell path).\nlocal function count_entries(t)\n    local n = 0\n    if t then for _ in pairs(t) do n = n + 1 end end\n    return n\nend\n\nlocal function ensure_tables()\n    for _, layer in ipairs(LAYERS) do\n        imap_raw[layer] = imap_raw[layer] or {}\n        imap_nrm[layer] = imap_nrm[layer] or {}\n        for _, side in ipairs(SIDES) do\n            imap_raw[layer][side] = imap_raw[layer][side] or {}\n            imap_nrm[layer][side] = imap_nrm[layer][side] or {}\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 normalise_inlfuence_map equivalent \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors EECH: find min/max across all entries, map to 0\226\128\147255, divide by 255.\n-- Returns early (no-op) if max == min (all entries identical).\nlocal function normalise_layer(layer, side)\n    local raw = imap_raw[layer][side]\n    local min_val, max_val = math.huge, -math.huge\n    for _, v in pairs(raw) do\n        if v < min_val then min_val = v end\n        if v > max_val then max_val = v end\n    end\n    if max_val == min_val then return end  -- mirrors EECH early-return\n    local range = max_val - min_val\n    local nrm   = imap_nrm[layer][side]\n    for name, v in pairs(raw) do\n        -- (v - min) / range \226\134\146 0..1; matches EECH's 255 * ((v - min)/(max - min)) / 255\n        nrm[name] = (v - min_val) / range\n    end\nend\n\n-- \226\148\128\226\148\128 IMAP_BASE_DISTANCE \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors update_keysite_distance_to_friendly_base():\n--   for each friendly keysite: scale = 1 - (dist^2 / radius^2), clamped 0\226\128\1471.\n--   Accumulate max(existing, scale) per sector (we use per-base proxy).\n-- Then normalise_base_distance_imaps() min-max normalises across all sectors.\nlocal function update_base_distance(side)\n    local layer = M.BASE_DISTANCE\n    local raw   = imap_raw[layer][side]\n    -- Zero all entries first (mirrors zero loop in update_imap_distance_to_friendly_base)\n    for name in pairs(S.base_owner) do raw[name] = 0.0 end\n\n    local r2 = AIR_COVERAGE_RADIUS * AIR_COVERAGE_RADIUS\n\n    -- For each friendly keysite: spread inverse-square influence to all base-proxies\n    for fname, fowner in pairs(S.base_owner) do\n        if fowner == side then\n            local fpos = S.base_pos[fname]\n            if fpos then\n                for tname in pairs(S.base_owner) do\n                    local tpos = S.base_pos[tname]\n                    if tpos then\n                        local dx = fpos.x - tpos.x\n                        local dz = fpos.z - tpos.z\n                        local d2 = dx*dx + dz*dz\n                        if d2 < r2 then\n                            local scale = 1.0 - d2 / r2  -- inverse-square within radius\n                            -- mirrors max() accumulation in EECH\n                            if scale > (raw[tname] or 0) then\n                                raw[tname] = scale\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    normalise_layer(layer, side)\nend\n\n-- \226\148\128\226\148\128 IMAP_AIR_DEFENCE \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors update_imap_surface_to_air_defence_level():\n--   value = FLOAT_TYPE_POTENTIAL_SURFACE_TO_AIR_THREAT (proxy: AA_THREAT_VALUE)\n--   radius = AIR_SCAN_RANGE * 10.0 / SECTOR_SIDE_LENGTH (proxy: DEFAULT_AIR_SCAN_RANGE * 10)\n--   scale = (1 - dist^2/r^2) * value, accumulated (+=) per sector.\nlocal function update_air_defence(side)\n    local layer   = M.AIR_DEFENCE\n    local raw     = imap_raw[layer][side]\n    for name in pairs(S.base_owner) do raw[name] = 0.0 end\n\n    local enemy = cs.ENEMY[side]\n    local radius = DEFAULT_AIR_SCAN_RANGE * AIR_SCAN_EXAGGERATION\n    local r2     = radius * radius\n\n    -- Scan all enemy groups for AA units\n    local enemy_groups = coalition.getGroups(enemy)\n    if not enemy_groups then return end\n\n    for _, grp in ipairs(enemy_groups) do\n        if grp and grp:isExist() then\n            local desc = grp:getUnit(1) and grp:getUnit(1):getDesc()\n            local is_aa = desc and (\n                (desc.attributes and (desc.attributes[\"SAM\"] or\n                                      desc.attributes[\"AAA\"] or\n                                      desc.attributes[\"SR SAM\"] or\n                                      desc.attributes[\"IR Guided SAM\"] or\n                                      desc.attributes[\"LR SAM\"] or\n                                      desc.attributes[\"MR SAM\"]))\n            )\n            if is_aa then\n                local gunit = grp:getUnit(1)\n                if gunit and gunit:isExist() then\n                    local gpos = gunit:getPosition().p\n                    -- accumulate threat contribution into each base proxy\n                    for bname in pairs(S.base_owner) do\n                        local bpos = S.base_pos[bname]\n                        if bpos then\n                            local dx = gpos.x - bpos.x\n                            local dz = gpos.z - bpos.z\n                            local d2 = dx*dx + dz*dz\n                            if d2 < r2 then\n                                local scale = (1.0 - d2 / r2) * AA_THREAT_VALUE\n                                raw[bname] = (raw[bname] or 0) + scale\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    normalise_layer(layer, side)\nend\n\n-- \226\148\128\226\148\128 IMAP_SURFACE_DEFENCE \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors update_imap_surface_to_surface_defence_level():\n--   value = FLOAT_TYPE_POTENTIAL_SURFACE_TO_SURFACE_THREAT (proxy: SURF_THREAT_VALUE)\n--   radius = SURFACE_SCAN_RANGE * 10 / SECTOR_SIDE_LENGTH\n--   Same accumulation pattern as air_defence but for ground-attack units.\nlocal function update_surface_defence(side)\n    local layer  = M.SURFACE_DEFENCE\n    local raw    = imap_raw[layer][side]\n    for name in pairs(S.base_owner) do raw[name] = 0.0 end\n\n    local enemy  = cs.ENEMY[side]\n    local radius = DEFAULT_SURF_SCAN_RANGE * SURF_SCAN_EXAGGERATION\n    local r2     = radius * radius\n\n    local enemy_groups = coalition.getGroups(enemy)\n    if not enemy_groups then return end\n\n    for _, grp in ipairs(enemy_groups) do\n        if grp and grp:isExist() then\n            local desc = grp:getUnit(1) and grp:getUnit(1):getDesc()\n            local is_surf = desc and (\n                (desc.attributes and (desc.attributes[\"Armor\"] or\n                                      desc.attributes[\"Artillery\"] or\n                                      desc.attributes[\"Infantry\"] or\n                                      desc.attributes[\"Ground vehicles\"]))\n            )\n            if is_surf then\n                local gunit = grp:getUnit(1)\n                if gunit and gunit:isExist() then\n                    local gpos = gunit:getPosition().p\n                    for bname in pairs(S.base_owner) do\n                        local bpos = S.base_pos[bname]\n                        if bpos then\n                            local dx = gpos.x - bpos.x\n                            local dz = gpos.z - bpos.z\n                            local d2 = dx*dx + dz*dz\n                            if d2 < r2 then\n                                local scale = (1.0 - d2 / r2) * SURF_THREAT_VALUE\n                                raw[bname] = (raw[bname] or 0) + scale\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    normalise_layer(layer, side)\nend\n\n-- \226\148\128\226\148\128 IMAP_IMPORTANCE \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors normalise_importance_imaps() which reads sector->importance_level[side].\n-- In EECH importance_level is propagated from keysite importance_radius spread.\n-- DCS proxy: importance = health \195\151 0.5 + ownership_contribution \195\151 0.5,\n--            spread with inverse-linear falloff within IMPORTANCE_RADIUS.\nlocal function update_importance(side)\n    local layer = M.IMPORTANCE\n    local raw   = imap_raw[layer][side]\n    for name in pairs(S.base_owner) do raw[name] = 0.0 end\n\n    local r2 = IMPORTANCE_RADIUS * IMPORTANCE_RADIUS\n\n    for fname, fowner in pairs(S.base_owner) do\n        if fowner == side then\n            local fpos = S.base_pos[fname]\n            if fpos then\n                local health = S.base_health[fname] or 1.0\n                local importance = health * 0.5 + 0.5  -- owned by us = always non-zero\n                -- spread to neighbours\n                for tname in pairs(S.base_owner) do\n                    local tpos = S.base_pos[tname]\n                    if tpos then\n                        local dx = fpos.x - tpos.x\n                        local dz = fpos.z - tpos.z\n                        local d2 = dx*dx + dz*dz\n                        if d2 < r2 then\n                            -- additive accumulation (mirrors update_sector_importance_level += scale)\n                            local scale = (1.0 - d2 / r2) * importance\n                            raw[tname] = (raw[tname] or 0) + scale\n                        end\n                    end\n                end\n            end\n        end\n    end\n    normalise_layer(layer, side)\nend\n\n-- \226\148\128\226\148\128 imap.get() \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Returns 0.0\226\128\1471.0 for the given layer/side at world position wp.\n-- Interpolates using inverse-distance weighting from known base positions.\n-- When wp is exactly a base position: returns that base's normalised value.\nfunction M.get(side, layer, wp)\n    if not wp then return 0.0 end\n    local nrm = imap_nrm[layer] and imap_nrm[layer][side]\n    if not nrm then return 0.0 end\n\n    -- Inverse-distance weighted interpolation across all bases\n    local num, den = 0.0, 0.0\n    for name, val in pairs(nrm) do\n        local bpos = S.base_pos[name]\n        if bpos then\n            local dx = wp.x - bpos.x\n            local dz = wp.z - bpos.z\n            local d2 = dx*dx + dz*dz\n            if d2 < 1.0 then\n                -- Exact hit: return this base's value immediately\n                return val\n            end\n            local w = 1.0 / d2\n            num = num + w * val\n            den = den + w\n        end\n    end\n    if den == 0.0 then return 0.0 end\n    return num / den\nend\n\n-- \226\148\128\226\148\128 init \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.init()\n    ensure_tables()\n    -- Zero all normalised tables\n    for _, layer in ipairs(LAYERS) do\n        for _, side in ipairs(SIDES) do\n            imap_nrm[layer][side] = {}\n            imap_raw[layer][side] = {}\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 Scheduler \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Four staggered timers, one per layer (mirrors EECH registering each\n-- update_imap_* function separately with a different offset).\n-- All respect the generation guard.\nfunction M.schedule_update(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n\n    local updaters = {\n        { M.BASE_DISTANCE,   \"base_distance\",   update_base_distance   },\n        { M.AIR_DEFENCE,     \"air_defence\",     update_air_defence     },\n        { M.SURFACE_DEFENCE, \"surface_defence\", update_surface_defence },\n        { M.IMPORTANCE,      \"importance\",      update_importance      },\n    }\n\n    for i, entry in ipairs(updaters) do\n        local layer_name, label, fn = entry[1], entry[2], entry[3]\n        local offset = (i - 1) * LAYER_STAGGER\n        timer.scheduleFunction(function(_, t)\n            -- INFRASTRUCTURE: imap layers keep refreshing after campaign-over \226\128\148 the world runs on\n            -- (EECH fc_msgs.c:163 halts only the win-check, not the sim). Only the re-injection guard cancels.\n            if _DMT_GEN ~= my_gen then return nil end\n            local ok, err = pcall(function()\n                for _, side in ipairs(SIDES) do\n                    fn(side)\n                end\n            end)\n            if not ok then log_fn(\"imap \" .. label .. \" error: \" .. tostring(err)) end\n            -- LIGHT refresh summary: one line per layer per pass, entry counts only (never per cell).\n            cs.dbg(\"imap\", \"layer %s refreshed: BLUE=%d entries, RED=%d entries\", label,\n                count_entries(imap_nrm[layer_name][coalition.side.BLUE]),\n                count_entries(imap_nrm[layer_name][coalition.side.RED]))\n            return t + UPDATE_PERIOD\n        -- EECH highlevl.c lines 272\226\128\147278: layers fire at 20, 40, 60, 80 s (base=20, stagger=20)\n        end, nil, timer.getTime() + 20 + offset)\n    end\n    log_fn(\"imap: scheduled 4 layer updaters (stagger=\" .. LAYER_STAGGER .. \"s, period=\" .. UPDATE_PERIOD .. \"s)\")\n    cs.dbg(\"imap\", \"scheduler REGISTERED: 4 layers, base_offset=20s stagger=%.0fs period=%.0fs\", LAYER_STAGGER, UPDATE_PERIOD)\nend\n\nreturn M\n"
__modules["installations"] = "-- installations.lua\n-- EECH source: aphavoc/source/entity/special/keysite/keysite.h + keysite_database\n--   Non-airbase keysites \226\128\148 bridges / depots / factories / radar / command \226\128\148 each with per-type\n--   flags: oca_target, ground_strike_target, ship_strike_target, troop_insertion_target,\n--   recon_target, requires_cap, requires_barcap, minimum_efficiency.\n--\n-- WHY THIS MODULE EXISTS: airbase-only keysites made create_keysite_strike_tasks (ground_strike_\n-- target) and create_oca_strike_tasks (oca_target) hit the SAME set. EECH's keysite database has\n-- many ground_strike-only keysites (depots, radars, bridges) that OCA never touches. These\n-- installations restore that distinction: they are ground_strike_target + recon_target but NOT\n-- oca_target / troop_insertion_target \226\128\148 so the ground-strike tasker and artillery hit them while\n-- OCA-strike stays airfield-only.\n--\n-- TWO MODES:\n--   \226\128\162 ZONE-AUTHORED (preferred, register_static_death spec): when the author placed keysite trigger\n--     zones, the campaign REGISTERS the STATIC OBJECTS the author dropped inside each circle \226\128\148 it\n--     SPAWNS NOTHING. Keysite health = alive registered assets / total registered assets; a struck\n--     keysite destroys that fraction of its still-alive statics and drains toward 0 (neutralised /\n--     capturable at < MINIMUM_EFFICIENCY, never removed). Terrain-safe: the author controls placement.\n--   \226\128\162 AUTO (fallback, no zones): installations are placed PROCEDURALLY around each airbase (legacy).\n--     Kept intact so an empty Caucasus mission still boots a scenario; this path still spawns.\n\nlocal cs     = require(\"campaign_state\")\nlocal config = require(\"config\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- Physical small keysites are now SPAWNED (verified live: statics need a valid type/shape_name/\n-- category triple AND a running sim \226\128\148 addStaticObject throws \"Can't update mission database\" while\n-- the sim is paused at t=0, which caused the earlier crash confusion; on a live sim the verified\n-- triples below spawn and persist cleanly). All triples were extracted from an ME-authored .miz so\n-- they are guaranteed-good shapes. Radar sites are REAL EWR ground units so SEAD has a live emitter\n-- to hunt. Everything spawns through the coalition.* stagger queue (spawn_queue) so the whole\n-- infrastructure network drains in over time rather than popping in at once.\nlocal SPAWN_PHYSICAL = true\n\n-- \226\148\128\226\148\128 Installation kinds (hoisted to config.statics.kinds; ME-VERIFIED static triples + EWR units) \226\148\128\226\148\128\n-- spawn = \"static\": {type, shape, cat} verified from a mission-editor .miz (spawn+persist confirmed).\n-- spawn = \"unit\":   an EWR radar GROUND unit per side \226\128\148 a SEAD target with a real emitter.\nlocal COUNTRY = config.C.countries\nlocal KINDS   = config.C.statics.kinds\n\n-- \226\148\128\226\148\128 Production keysites (KEYSITE-F1/F5) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- eech ks_dbase.c factory/refinery/port rows; default_supply_usage (spec 03 \194\1672.3, %/min):\n--   FACTORY   ammo +1.0, fuel  0.0   (eech ks_dbase.c:185-224 factory row)\n--   REFINERY  ammo  0.0, fuel +1.0   (eech ks_dbase.c:420-459 oil-refinery row)\n-- Positive default_supply_usage = PRODUCER (accumulates stock as cargo crates, eech ks_updt.c:\n-- 136-146). While alive AND owned, a producer feeds its side's economy: crate deliveries restock\n-- consumer keysites (KEYSITE-F6/F7/F8) and surplus crates replace hardware losses (supply.lua).\n-- Rates are percentage-points-per-minute (= 0.1 CARGO crate/min at +1.0; CARGO_*_SIZE=10, cargo.h:89).\nlocal PRODUCER = {\n    factory  = { ammo = 1.0, fuel = 0.0 },   -- eech ks_dbase.c factory default_supply_usage\n    refinery = { ammo = 0.0, fuel = 1.0 },   -- eech ks_dbase.c oil-refinery default_supply_usage\n    port     = { ammo = 0.0, fuel = 1.0 },   -- port keysite: fuel logistics (proxy = refinery row)\n}\n\n-- Flags per kind = the FULL keysite_database row (ks_dbase.c) each zone kind maps to. NO installation\n-- requires CAP or BARCAP and NONE is an oca_target \226\128\148 that is the whole point (distinct from airbases,\n-- which OCA hits). Producers are ground_strike_target too so the ground-strike / CAS / artillery\n-- taskers hit them: destroying an enemy factory genuinely starves that side (production_rates drops\n-- \226\134\146 no crate deliveries, no reserve replacement).\n-- The port zone kind \226\134\146 EECH keysite_database row (ks_dbase.c), with the six task-relevant flags read\n-- by the reaction chain (Cluster I made keysite_flags kind-aware, so these are now consumed):\n--   factory  \226\134\146 FACTORY          (cap F:214, oca F:218, recon F:219, gs T:220, ti T:222)\n--   refinery \226\134\146 OIL_REFINERY     (cap F:449, oca F:453, recon T:454, gs T:455, ti F:457)\n--   fuel     \226\134\146 OIL_REFINERY (analog: fuel dump \226\137\136 refinery/fuel logistics \226\128\148 same row)\n--   port     \226\134\146 PORT             (cap F:355, oca F:359, recon F:360, gs T:361, ti F:363)\n--   power    \226\134\146 POWER_STATION    (cap F:402, oca F:406, recon T:407, gs T:408, ti F:410)\n--   radar    \226\134\146 RADIO_TRANSMITTER(cap F:496, oca F:500, recon T:501, gs T:502, ti F:504)\n--   depot    \226\134\146 MILITARY_BASE    (cap F:308, oca F:312, recon T:313, gs T:314, ti T:316)\n--   command  \226\134\146 MILITARY_BASE    (same row as depot)\nlocal FLAGS = {\n    factory  = { requires_cap = false, requires_barcap = false, oca_target = false, ground_strike_target = true,  troop_insertion_target = true,  recon_target = false },\n    refinery = { requires_cap = false, requires_barcap = false, oca_target = false, ground_strike_target = true,  troop_insertion_target = false, recon_target = true  },\n    fuel     = { requires_cap = false, requires_barcap = false, oca_target = false, ground_strike_target = true,  troop_insertion_target = false, recon_target = true  },\n    port     = { requires_cap = false, requires_barcap = false, oca_target = false, ground_strike_target = true,  troop_insertion_target = false, recon_target = false },\n    power    = { requires_cap = false, requires_barcap = false, oca_target = false, ground_strike_target = true,  troop_insertion_target = false, recon_target = true  },\n    radar    = { requires_cap = false, requires_barcap = false, oca_target = false, ground_strike_target = true,  troop_insertion_target = false, recon_target = true  },\n    depot    = { requires_cap = false, requires_barcap = false, oca_target = false, ground_strike_target = true,  troop_insertion_target = true,  recon_target = true  },\n    command  = { requires_cap = false, requires_barcap = false, oca_target = false, ground_strike_target = true,  troop_insertion_target = true,  recon_target = true  },\n}\n\n-- Kind-aware keysite_database row lookup (consumed by reaction.keysite_flags for installation\n-- objectives). Returns the FULL flag row for a zone kind, or nil for an unknown kind.\nfunction M.flags_for_kind(kind)\n    return FLAGS[kind]\nend\n\n-- Human-readable label per keysite ZONE type (kind = zone.type verbatim; see init_from_zones).\nlocal ZONE_LABELS = {\n    factory  = \"Munitions Factory\", refinery = \"Oil Refinery\", port = \"Port\",\n    power    = \"Power Station\",      radar   = \"Radar/EWR\",    depot = \"Supply Depot\",\n    fuel     = \"Fuel Depot\",         command = \"Command Post\",\n}\n\n-- Which installations each base fields, and how far into its rear (metres) they sit.\nlocal BASE_LOADOUT = { \"depot\", \"fuel\", \"radar\" }   -- every owned base: consumer/target installations\nlocal REAR_LOADOUT = { \"factory\", \"refinery\" }       -- producers: rear bases only (safe from the front)\nlocal REAR_OFFSET  = 3200    -- m behind the base \226\128\148 close enough to read as THIS base's support\n                             -- complex (was 10 km, which scattered them far from their airfield)\nlocal KILL_DMG     = 0.15    -- default per-hit health fraction for M.damage (deterministic strike channel)\nlocal FRONT_DIST   = config.C.theatre.front_dist  -- m; a base within this of an enemy base is \"frontline\" (config theatre; matches ground_forces)\nlocal LOW_TARGET_THRESHOLD = 2  -- a keysite with 1..this registered assets is flagged \"low targets\" (a\n                                -- warning to the author: place more statics/resource objects in the circle)\n\n-- Distance from `base` to its nearest enemy base (math.huge if the enemy has no base).\nlocal function nearest_enemy_dist(base, side)\n    local bp = S.base_pos[base]\n    local enemy = cs.ENEMY[side]\n    if not bp or not enemy then return math.huge end\n    local best = math.huge\n    for name, owner in pairs(S.base_owner) do\n        if owner == enemy then\n            local ep = S.base_pos[name]\n            if ep then\n                local d = cs.dist2d(bp.x, bp.z, ep.x, ep.z)\n                if d < best then best = d end\n            end\n        end\n    end\n    return best\nend\n\n-- A base is \"rear\" if no enemy base is within FRONT_DIST \226\128\148 the safe interior where EECH sites its\n-- factories/refineries. Producers only spawn at rear bases so they are a strategic depth objective.\nlocal function is_rear(base, side)\n    return nearest_enemy_dist(base, side) > FRONT_DIST\nend\n\n-- Direction from a base into its own rear = away from the nearest enemy base.\nlocal function rear_offset_pos(base, side)\n    local bp = S.base_pos[base]\n    if not bp then return nil end\n    local enemy = cs.ENEMY[side]\n    -- Default rear direction = due-north offset; overridden by the nearest enemy base if any.\n    local ex, ez, best, found = bp.x, bp.z + 1, math.huge, false\n    for name, owner in pairs(S.base_owner) do\n        if owner == enemy then\n            local ep = S.base_pos[name]\n            if ep then\n                local d = cs.dist2d(bp.x, bp.z, ep.x, ep.z)\n                if d < best then best = d; ex, ez = ep.x, ep.z; found = true end\n            end\n        end\n    end\n    if not found then return { x = bp.x + REAR_OFFSET, z = bp.z } end\n    local dx, dz = bp.x - ex, bp.z - ez           -- points into the rear (away from enemy)\n    local len = math.max(math.sqrt(dx*dx + dz*dz), 1)\n    return { x = bp.x + dx/len * REAR_OFFSET, z = bp.z + dz/len * REAR_OFFSET }\nend\n\n-- Spawn the installation's physical object: a building STATIC (verified triple) or an EWR UNIT\n-- (radar sites). Both go through the coalition.* stagger queue (spawn_queue) so they drain in over\n-- time. Returns \"static\" | \"unit\" so damage() knows which registry to destroy from.\nlocal function spawn_installation(kname, kind, side, pos)\n    local spec = KINDS[kind]\n    local cid  = COUNTRY[side]\n    if not spec or not cid or not SPAWN_PHYSICAL then return spec and spec.spawn or nil end\n    if spec.spawn == \"static\" then\n        pcall(coalition.addStaticObject, cid, {\n            heading = 0, type = spec.type, shape_name = spec.shape, category = spec.cat,\n            name = kname, x = pos.x, y = pos.z, dead = false,\n        })\n    elseif spec.spawn == \"unit\" then\n        local utype = spec.unit[side]\n        if utype then\n            pcall(coalition.addGroup, cid, Group.Category.GROUND, {\n                name = kname, task = \"Ground Nothing\",\n                units = { { name = kname .. \"-1\", type = utype, x = pos.x, y = pos.z, heading = 0, skill = \"Average\" } },\n                route = { points = { { x = pos.x, y = pos.z, type = \"Turning Point\", action = \"Off Road\",\n                                       speed = 0, ETA = 0, ETA_locked = true } } },\n            })\n        end\n    end\n    return spec.spawn\nend\n\n-- Decide which owned bases host the production keysites: every rear base, but guarantee at least\n-- one producer per side (the base farthest from the enemy) so a side always has an economy even on\n-- a tiny/all-frontline map.\nlocal function pick_producer_bases()\n    local producer = {}   -- [base] = true\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        local owned, any_rear = {}, false\n        for base, owner in pairs(S.base_owner) do\n            if owner == side then owned[#owned + 1] = base end\n        end\n        for _, base in ipairs(owned) do\n            if is_rear(base, side) then producer[base] = true; any_rear = true end\n        end\n        if not any_rear and #owned > 0 then\n            local best, best_d = nil, -1\n            for _, base in ipairs(owned) do\n                local d = nearest_enemy_dist(base, side)\n                if d ~= math.huge and d > best_d then best_d = d; best = base end\n            end\n            best = best or owned[1]\n            if best then producer[best] = true end\n        end\n    end\n    return producer\nend\n\n-- \226\148\128\226\148\128 Zone-authored keysites (register author-placed statics; spawn nothing) \226\148\128\226\148\128\226\148\128\226\148\128\n\n-- Recompute alive-asset count and health from the destroyed-asset set. health = alive/total; a\n-- keysite with 0 registered assets reads 0 (neutralised/capturable). Idempotent \226\128\148 the S_EVENT_DEAD\n-- handler and M.damage both mark rec.dead[name] and call this, so double reports are harmless.\n-- Assets are TWO registries folded into one total: author-placed STATICS (rec.assets, drained by name\n-- via rec.dead[name]) and destroyable resource SCENERY (rec.scenery rows, drained by rec.scenery[i].dead\n-- from the getLife poll / a direct destroy). total = #statics + #scenery; a scenery entry counts as dead\n-- when its .dead flag is set. Keeps the statics accounting identical to before.\nlocal function recompute_health(rec)\n    if not rec.assets and not rec.scenery then return end\n    local total = rec.total or 0\n    local dead = 0\n    if rec.assets then\n        for _, nm in ipairs(rec.assets) do\n            if rec.dead[nm] then dead = dead + 1 end\n        end\n    end\n    if rec.scenery then\n        for _, s in ipairs(rec.scenery) do\n            if s.dead then dead = dead + 1 end\n        end\n    end\n    rec.alive  = math.max(0, total - dead)\n    rec.health = (total > 0) and (rec.alive / total) or 0\nend\n\n-- Nearest side-owned base to a point \226\134\146 name (for the damage log + capture affinity), or nil.\nlocal function nearest_owned_base(pos, side)\n    local best, bestd = nil, math.huge\n    for name, owner in pairs(S.base_owner) do\n        if owner == side then\n            local bp = S.base_pos[name]\n            if bp then\n                local d = cs.dist2d(pos.x, pos.z, bp.x, bp.z)\n                if d < bestd then bestd = d; best = name end\n            end\n        end\n    end\n    return best\nend\n\n-- \226\148\128\226\148\128 Empty-site default TEMPLATE (DESIGNER DATA \226\128\148 not EECH-sourced) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- When a keysite zone has NO author-placed assets, spawn a well-crafted default instead of leaving it\n-- pending: the type's building static PLUS a defensive garrison company. The spawned statics register\n-- as the keysite's drainable assets; the garrison gives an empty auto-zone some ground presence.\n-- FIDELITY NOTE: this garrison composition is DESIGNER DATA, NOT an EECH constant. EECH's actual\n-- per-keysite ground presence is (a) INFANTRY PATROLS \226\128\148 create_troop_patrol_tasks, highlevl.c:2735,\n-- 4-man infantry, already ported in troop.lua \226\128\148 and (b) population-data firing points (popread.c).\n-- The former \"order.c:361\" citation was WRONG: that line is armoured-company ORGANISATION (3 groups\n-- per company), not a keysite garrison. Placed statics always override this EMPTY-zone fallback.\n-- \226\148\128\226\148\128 Verified spawn PALETTE (type|shape_name|category \226\128\148 all extracted from ME-placed statics) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- These are the building blocks the templates draw on. Every triple is confirmed to spawn+persist.\n-- Verified spawn PALETTE + defence element types are hoisted to config.lua (statics.palette,\n-- types.ground.{garrison,aaa,sam,ewr}). GARRISON_UNITS is DESIGNER DATA \226\128\148 a mixed defensive company\n-- for an empty auto-zone, not an EECH composition (EECH keysite ground = the infantry patrol of\n-- troop.lua + population firing points; see the TEMPLATE header). Author-placed statics override.\nlocal PALETTE        = config.C.statics.palette\nlocal GARRISON_UNITS = config.C.types.ground.garrison\nlocal AAA_UNIT       = config.C.types.ground.aaa\nlocal SAM_UNITS      = config.C.types.ground.sam\nlocal EWR_UNIT       = config.C.types.ground.ewr\n\n-- \226\148\128\226\148\128 Site TEMPLATES \226\128\148 organic shorthand, reasoned per keysite type \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- `b` = the buildings that make up the installation {palette token = count}; `d` = its defence force\n-- {garrison / aaa / sam / ewr}. The transpiler below lays the buildings on a grid and rings them with\n-- the defenders. This is the EMPTY-zone fallback (a designer-authored complex + defensive garrison;\n-- author-placed statics override it entirely. Reasoning per type:\n--   factory  \226\128\148 a production line (3 halls) + finished-goods warehouses + an ammo store + fuel, armour+AAA\n--   refinery \226\128\148 tank farm (fuel dumps + oil tanks) + a warehouse, armour+AAA\n--   port     \226\128\148 quayside warehouses + fuel tanks + an ammo store, armour+AAA\n--   depot    \226\128\148 the supply hub: warehouses + containers + ammo + fuel, armour+AAA\n--   fuel     \226\128\148 a fuel/tank farm, armour+AAA\n--   command  \226\128\148 HQ building + hardened bunker + a store, armour + AAA + a point SAM (HQs are defended)\n--   power    \226\128\148 the plant (2 halls) + transformer yard (containers) + fuel, armour+AAA\n--   radar    \226\128\148 an EWR\231\171\153 + a SAM battery + a bunker + AAA (the radar site IS its air-defence node)\nlocal TEMPLATES = {\n    factory  = { b = { factory = 3, warehouse = 2, fueltank = 1, ammo = 1 }, d = { garrison = 1, aaa = 2 } },\n    refinery = { b = { fuel = 2, fueltank = 3, warehouse = 1 },              d = { garrison = 1, aaa = 2 } },\n    port     = { b = { warehouse = 3, fueltank = 2, ammo = 1 },              d = { garrison = 1, aaa = 2 } },\n    depot    = { b = { warehouse = 2, container = 3, ammo = 2, fueltank = 1 }, d = { garrison = 1, aaa = 1 } },\n    fuel     = { b = { fuel = 2, fueltank = 3 },                             d = { garrison = 1, aaa = 1 } },\n    command  = { b = { command = 1, bunker = 1, warehouse = 1 },             d = { garrison = 1, aaa = 1, sam = 1 } },\n    power    = { b = { factory = 2, container = 2, fueltank = 1 },           d = { garrison = 1, aaa = 1 } },\n    radar    = { b = { bunker = 1 },                                         d = { ewr = 1, sam = 1, aaa = 1 } },\n}\n\n-- Spawn one palette static; returns its name (for asset registration) or nil.\nlocal function spawn_palette_static(name, token, side, x, z)\n    local p, cid = PALETTE[token], COUNTRY[side]\n    if not p or not cid then return nil end\n    pcall(coalition.addStaticObject, cid, {\n        heading = 0, type = p[1], shape_name = p[2], category = p[3], name = name, x = x, y = z, dead = false,\n    })\n    return name\nend\n\n-- Spawn a ground group from a flat unit-type list around `pos` (pcall-guarded).\nlocal function spawn_ground(name, side, types, pos)\n    local cid = COUNTRY[side]\n    if not cid or #types == 0 then return end\n    local units = {}\n    for i, t in ipairs(types) do\n        local ux = pos.x + ((i - 1) % 3) * 30\n        local uz = pos.z + math.floor((i - 1) / 3) * 30\n        units[i] = { name = name .. \"-\" .. i, type = t, skill = \"Average\",\n            x = ux, y = uz, heading = 0, alt = land.getHeight({ x = ux, y = uz }), alt_type = \"BARO\" }\n    end\n    pcall(coalition.addGroup, cid, Group.Category.GROUND, {\n        name = name, task = \"Ground Nothing\", hidden = false, units = units,\n        route = { points = { { type = \"Turning Point\", action = \"Off Road\", speed = 0, ETA = 0,\n            ETA_locked = true, x = pos.x, y = pos.z,\n            alt = land.getHeight({ x = pos.x, y = pos.z }), alt_type = \"BARO\", name = \"Hold\" } } },\n    })\nend\n\n-- Transpile a site TEMPLATE into DCS spawns: a grid of buildings + a ringing defence force. Returns\n-- the spawned STATIC names (the keysite's drainable assets).\nlocal function spawn_keysite_template(kname, kind, side, pos)\n    local tmpl = TEMPLATES[kind]\n    if not tmpl then return {} end\n    local cx, cz = pos.x, pos.z\n    local names = {}\n    -- Buildings: flatten {token=count} into a list, lay out on a centred ~45 m grid.\n    local blds = {}\n    for token, n in pairs(tmpl.b) do for _ = 1, n do blds[#blds + 1] = token end end\n    local cols = math.max(1, math.ceil(math.sqrt(#blds)))\n    for i, token in ipairs(blds) do\n        local col, row = (i - 1) % cols, math.floor((i - 1) / cols)\n        -- Snap EACH grid cell off water (fixes \"factory 5/7 at Batumi\": coastal grid cells landed in\n        -- the sea); each building is its own STATIC \226\134\146 snap each, fallback = the keysite centre (cx,cz).\n        local cell = cs.snap_land(cx + (col - (cols - 1) / 2) * 45, cz + (row - (cols - 1) / 2) * 45, cx, cz)\n        local sn = spawn_palette_static(string.format(\"%s-b%d\", kname, i), token, side, cell.x, cell.z)\n        if sn then names[#names + 1] = sn end\n    end\n    -- Defence: each element is its OWN group so a bad unit type only loses that element (a mixed group\n    -- fails entirely on one bad type). Each element's origin is snapped off water (fixes \"def groups\n    -- only ~4 survived\" at coastal Batumi); fallback = the keysite centre (cx,cz). snap_land returns a\n    -- {x=,z=} table, exactly the `pos` shape spawn_ground consumes; per-unit offsets stay relative to it.\n    local d = tmpl.d or {}\n    if d.garrison then spawn_ground(kname .. \"-def\", side, GARRISON_UNITS[side] or {}, cs.snap_land(cx + 30, cz + 30, cx, cz)) end\n    if (d.aaa or 0) > 0 and AAA_UNIT[side] then\n        local aaa = {}\n        for _ = 1, d.aaa do aaa[#aaa + 1] = AAA_UNIT[side] end\n        spawn_ground(kname .. \"-aaa\", side, aaa, cs.snap_land(cx - 50, cz + 50, cx, cz))\n    end\n    if d.sam then spawn_ground(kname .. \"-sam\", side, SAM_UNITS[side] or {}, cs.snap_land(cx - 40, cz - 40, cx, cz)) end\n    if d.ewr and EWR_UNIT[side] then spawn_ground(kname .. \"-ewr\", side, { EWR_UNIT[side] }, cs.snap_land(cx + 50, cz - 30, cx, cz)) end\n    return names\nend\n\n-- REGISTER S.keysites from the author's non-basing keysite zones (factory/refinery/port/radar/depot/\n-- fuel/power/command). For each zone, the STATIC OBJECTS the author placed inside the circle become\n-- that keysite's assets. NOTHING is spawned. kind = zone.type verbatim; side = zone colour; health =\n-- 1.0 while any asset is alive, else 0. Preserves S.keysites entries already added by keysite.lua\n-- (airbase-zone assets) \226\128\148 keysite.init_base_state runs before this.\nlocal function init_from_zones(log_fn)\n    S.keysites = S.keysites or {}\n    local zones = require(\"zones\")\n    local n, np, nassets, npending = 0, 0, 0, 0\n    local warnings = {}   -- keysites with no/low targets (author feedback)\n    for _, kz in ipairs(zones.keysites()) do\n        local kind = kz.type\n        -- airbase/farp zones are basing keysites (keysite.lua / farps.lua); skip here.\n        if kind ~= \"airbase\" and kind ~= \"farp\" and kz.side then\n            local pos    = { x = kz.x, z = kz.z }\n            local kname  = string.format(\"KS-%s-%s\", kind, tostring(kz.label))\n            local uniq, k = kname, 1\n            while S.keysites[uniq] do k = k + 1; uniq = kname .. \"-\" .. k end\n            kname = uniq\n            local assets  = zones.statics_in_zone(kz.label)  -- author-placed statics inside the circle\n            -- Destroyable resource SCENERY inside the circle (fuel/warehouse \226\128\148 TOPLIVO-BAK/SKLADIK/etc.),\n            -- registered exactly like statics and folded into the same totals. The author's zone bounds\n            -- which objects count, so a zone drawn over a real depot/warehouse cluster registers them.\n            local scenery = {}\n            for _, srow in ipairs(zones.scenery_in_zone(kz.label, zones.RESOURCE_SCENERY)) do\n                scenery[#scenery + 1] = { id = srow.id, type = srow.type, handle = srow.handle, dead = false }\n            end\n            local nstatics, nscen = #assets, #scenery\n            local ntotal = nstatics + nscen\n            -- NO AUTHOR-PLACED STATICS \226\134\146 spawn a well-crafted default TEMPLATE (building complex +\n            -- defensive garrison) rather than leaving it thin. Gated on placed STATICS only (not scenery):\n            -- a zone that merely overlaps some found civilian scenery should still get its full complex +\n            -- garrison (the scenery just adds to the asset pool). Placed statics always win. (User\n            -- directive; garrison is DESIGNER DATA \226\128\148 EECH keysite ground presence is the infantry patrol\n            -- of troop.lua + population firing points, NOT the mis-cited order.c:361 company org.)\n            local templated = false\n            if nstatics == 0 then\n                for _, sn in ipairs(spawn_keysite_template(kname, kind, kz.side, pos)) do\n                    assets[#assets + 1] = sn\n                end\n                nstatics, ntotal, templated = #assets, #assets + nscen, true\n            end\n            -- PENDING only if the template spawned nothing at all (should not happen for known kinds).\n            local pending     = (ntotal == 0) and not templated\n            local low_targets = (not pending) and (not templated) and (ntotal <= LOW_TARGET_THRESHOLD)\n            S.keysites[kname] = {\n                kind      = kind,                             -- zone.type verbatim\n                side      = kz.side,                          -- authoritative side from zone colour\n                pos       = pos,\n                home_base = nearest_owned_base(pos, kz.side) or kz.label,\n                assets    = assets,                           -- list of registered static NAMES\n                dead      = {},                               -- destroyed-static set (name \226\134\146 true)\n                scenery   = scenery,                          -- registered resource-scenery rows (held handles)\n                total     = ntotal,                           -- statics + scenery\n                alive     = ntotal,\n                health    = (ntotal > 0) and 1.0 or 0,\n                pending   = pending,                          -- empty circle: excluded until filled\n                templated = templated,                        -- empty-zone TEMPLATE spawned its own -aaa/\n                                                              -- -sam defence \226\134\146 base_defenses skips it (no\n                                                              -- double AD ring). Author-placed keysites\n                                                              -- (templated=false) get the ring.\n                low_targets = low_targets,                    -- 1..threshold assets \226\134\146 author warning\n                flags     = FLAGS[kind] or { ground_strike_target = true, recon_target = true },\n                label     = ZONE_LABELS[kind] or kind,\n                producer  = PRODUCER[kind],                   -- {ammo,fuel} %/min, or nil\n            }\n            n = n + 1\n            nassets = nassets + ntotal\n            if pending then npending = npending + 1\n            elseif PRODUCER[kind] then np = np + 1 end\n            if pending or low_targets then\n                warnings[#warnings + 1] = string.format(\"%s(%d)\", tostring(kz.label), ntotal)\n            end\n            log_fn(string.format(\"  keysite %s [%s] registered %d placed statics + %d resource scenery%s\",\n                kname, cs.SIDE_NAME[kz.side] or \"?\", nstatics, nscen,\n                pending and \" (PENDING \226\128\148 empty)\" or (low_targets and \" (LOW TARGETS)\" or \"\")))\n        end\n    end\n    log_fn(string.format(\"installations from zones: %d keysites (%d producers, %d pending/empty), \"\n        .. \"%d registered statics (author-placed \226\128\148 NO spawning)\", n, np, npending, nassets))\n    cs.dbg(\"installs\", \"init_from_zones: %d keysites (%d producers, %d pending/empty), %d assets registered\",\n        n, np, npending, nassets)\n    if #warnings > 0 then\n        local list = table.concat(warnings, \", \")\n        log_fn(string.format(\"WARNING: %d keysite(s) have no/low targets (<= %d assets) \226\128\148 place more \"\n            .. \"statics/resource objects in these circles: %s\", #warnings, LOW_TARGET_THRESHOLD, list))\n        -- Surface the same warning in-game so the author sees it on-screen, not just in the log.\n        pcall(trigger.action.outText, string.format(\n            \"\\226\\154\\160 CAMPAIGN: %d keysite(s) need targets (<= %d assets each).\\n\"\n            .. \"Place static objects / resource scenery inside these zone circles:\\n%s\",\n            #warnings, LOW_TARGET_THRESHOLD, list), 30, false)\n    end\nend\n\n-- \226\148\128\226\148\128 Static-death \226\134\146 keysite drain (world event handler) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- A registered asset dying (bomb, artillery, capture) decrements its keysite's alive count and\n-- recomputes health. Re-injection safe: stored in _G.__dmt_static_death_handler, old one removed\n-- first (world.addEventHandler has no auto-cleanup).\nfunction M.register_static_death(static_name, log_fn)\n    if not static_name then return nil end\n    for kname, rec in pairs(S.keysites or {}) do\n        if rec.assets and rec.dead and not rec.dead[static_name] then\n            for _, nm in ipairs(rec.assets) do\n                if nm == static_name then\n                    rec.dead[static_name] = true\n                    recompute_health(rec)\n                    -- Under-attack defensive CAP (keysite.c:854 notify_keysite_structure_under_attack):\n                    -- a keysite BUILDING dying IS the EECH under-attack trigger. For an AIRFIELD-asset\n                    -- record the keysite is the airbase (rec.home_base, requires_cap \226\134\146 scrambles CAP \226\128\148\n                    -- covers a HUMAN bombing airfield structures, MP-critical). Installation records\n                    -- (requires_cap FALSE) no-op inside on_keysite_under_attack, so gate to airbase kind.\n                    if rec.kind == \"airbase\" and rec.home_base then\n                        local ok_r, react = pcall(require, \"reaction\")\n                        if ok_r and react and react.on_keysite_under_attack then\n                            pcall(react.on_keysite_under_attack, rec.home_base, log_fn)\n                        end\n                    end\n                    if log_fn then\n                        log_fn(string.format(\"keysite %s asset lost: %s (%d/%d alive, %.0f%%)\",\n                            rec.label or kname, static_name, rec.alive, rec.total, rec.health * 100))\n                    end\n                    cs.dbg(\"installs\", \"%s asset lost: %s (%d/%d alive, %.0f%%)%s\",\n                        kname, static_name, rec.alive, rec.total, rec.health * 100,\n                        (rec.health <= 0.1) and \" -> NEUTRALISED\" or \"\")\n                    return kname\n                end\n            end\n        end\n    end\n    return nil\nend\n\nfunction M.init_static_death_handler(log_fn)\n    log_fn = log_fn or function() end\n    if _G.__dmt_static_death_handler then\n        pcall(world.removeEventHandler, _G.__dmt_static_death_handler)\n        _G.__dmt_static_death_handler = nil\n    end\n    local h = {}\n    function h:onEvent(event)\n        if not event then return end\n        if event.id ~= world.event.S_EVENT_DEAD and event.id ~= world.event.S_EVENT_KILL then return end\n        local obj = (event.id == world.event.S_EVENT_KILL) and event.target or event.initiator\n        if not obj then return end\n        local ok, nm = pcall(function() return obj:getName() end)\n        -- register_static_death no-ops unless the name is a registered keysite asset, so this is safe\n        -- to call for every dead object regardless of its category.\n        if ok and nm then M.register_static_death(nm, log_fn) end\n    end\n    world.addEventHandler(h)\n    _G.__dmt_static_death_handler = h\nend\n\n-- \226\148\128\226\148\128 Scenery drain via polling (held-handle getLife) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Resource scenery emits NO S_EVENT_DEAD the death handler can key off (and can't be re-acquired by\n-- name), so its attrition is detected by POLLING the held handle. For every keysite with registered\n-- scenery, read each still-alive handle's getLife(); when life is nil (handle gone) or <= 1 (burned\n-- out) the entry is marked dead, health recomputed, and the drop logged. Idempotent and re-injection\n-- safe (operates on S.keysites, which persists across re-injects).\nfunction M.poll_scenery(log_fn)\n    log_fn = log_fn or function() end\n    for kname, rec in pairs(S.keysites or {}) do\n        if rec.scenery and #rec.scenery > 0 then\n            local dropped = 0\n            for _, s in ipairs(rec.scenery) do\n                if not s.dead then\n                    local ok, life = pcall(function() return s.handle:getLife() end)\n                    if (not ok) or life == nil or life <= 1 then\n                        s.dead = true\n                        dropped = dropped + 1\n                    end\n                end\n            end\n            if dropped > 0 then\n                recompute_health(rec)\n                log_fn(string.format(\"keysite %s scenery lost: %d destroyed (%d/%d alive, %.0f%%)\",\n                    rec.label or kname, dropped, rec.alive or 0, rec.total or 0, (rec.health or 0) * 100))\n                cs.dbg(\"installs\", \"%s scenery poll: %d dropped this pass (%d/%d alive, %.0f%%)\",\n                    kname, dropped, rec.alive or 0, rec.total or 0, (rec.health or 0) * 100)\n            end\n        end\n    end\nend\n\n-- Register the periodic scenery-drain poll. Generation-guarded like every other scheduler (self-cancels\n-- on re-inject). Runs on after the win declaration \226\128\148 post-victory the whole sim keeps running (Item 6\n-- LITERAL semantics: EECH fc_msgs.c:163 gates only the win re-award; nothing is game_over-gated).\n-- Period mirrors the light cadence of the other keysite-attrition scanners; scenery death is\n-- coarse-grained so ~25 s is ample.\nlocal SCENERY_POLL_PERIOD = 25\nfunction M.schedule_scenery_poll(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"installs\", \"scenery-poll scheduler REGISTERED offset=%.0fs period=%.0fs\", SCENERY_POLL_PERIOD, SCENERY_POLL_PERIOD)\n    timer.scheduleFunction(function(_, t)\n        -- INFRASTRUCTURE: installation scenery-drain poll keeps running post-victory (EECH fc_msgs.c:163). Cluster E.\n        if _DMT_GEN ~= my_gen then return nil end\n        M.poll_scenery(log_fn)\n        return t + SCENERY_POLL_PERIOD\n    end, nil, timer.getTime() + SCENERY_POLL_PERIOD)\nend\n\n-- \226\148\128\226\148\128 init: procedurally place installations behind each base \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.init(log_fn)\n    log_fn = log_fn or function() end\n    -- Static-death \226\134\146 keysite drain handler (harmless no-op when there are no registered assets).\n    M.init_static_death_handler(log_fn)\n    -- Zone-authored theatre: REGISTER keysites from the ME zones (spawn nothing).\n    if require(\"zones\").has_keysite_zones() then return init_from_zones(log_fn) end\n    S.keysites = {}\n    local producer = pick_producer_bases()\n    local n, np = 0, 0\n    for base, owner in pairs(S.base_owner) do\n        if owner == coalition.side.BLUE or owner == coalition.side.RED then\n            local rear = rear_offset_pos(base, owner)\n            if rear then\n                -- consumer/target installations at every base; producers only at rear/depth bases\n                local loadout = { BASE_LOADOUT[1], BASE_LOADOUT[2], BASE_LOADOUT[3] }\n                if producer[base] then\n                    for _, k in ipairs(REAR_LOADOUT) do loadout[#loadout + 1] = k end\n                end\n                local bc = S.base_pos[base]\n                for i, kind in ipairs(loadout) do\n                    -- fan them in a TIGHT ring so each base's sites cluster into one readable complex;\n                    -- snap each ring slot off water (coastal base), fallback = the base centre.\n                    local ang = (i - 1) * (2 * math.pi / #loadout)\n                    local pos = cs.snap_land(rear.x + math.cos(ang) * 550, rear.z + math.sin(ang) * 550,\n                                             bc and bc.x or rear.x, bc and bc.z or rear.z)\n                    local kname = string.format(\"Inst-%s-%s\", kind, base)\n                    local spawn_kind = spawn_installation(kname, kind, owner, pos)\n                    S.keysites[kname] = {\n                        home_base = base, kind = kind, pos = pos,\n                        health = 1.0, flags = FLAGS[kind], label = KINDS[kind].label,\n                        producer = PRODUCER[kind],   -- {ammo,fuel} %/min, or nil for consumers/targets\n                        spawn_kind = spawn_kind,     -- \"static\" | \"unit\" \226\128\148 how to destroy its object\n                    }\n                    n = n + 1\n                    if PRODUCER[kind] then np = np + 1 end\n                end\n            end\n        end\n    end\n    log_fn(string.format(\"installations: %d non-airbase keysites placed (%d producers) [%s]\",\n        n, np, SPAWN_PHYSICAL and \"physical statics + EWR radar units\" or \"abstract points\"))\n    cs.dbg(\"installs\", \"init (auto/procedural path): %d keysites placed (%d producers)\", n, np)\nend\n\n-- \226\148\128\226\148\128 Per-side production capacity (KEYSITE-F5) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Sum of default_supply_usage over all ALIVE, side-owned producer keysites. Returns ammo,fuel in\n-- percentage-points-per-minute. Zero once a side's factories/refineries are all destroyed/captured\n-- \226\134\146 its consumer keysites stop being restocked and its reserve replacement halts (supply.lua).\nfunction M.production_rates(side)\n    local ammo, fuel = 0, 0\n    for _, rec in pairs(S.keysites or {}) do\n        local p = rec.producer\n        -- gate: producing only while healthy AND (for registered keysites) some assets still alive.\n        if p and not rec.pending and rec.health > 0.1 and (rec.alive == nil or rec.alive > 0) and M.side_of(rec) == side then\n            ammo = ammo + (p.ammo or 0)\n            fuel = fuel + (p.fuel or 0)\n        end\n    end\n    return ammo, fuel\nend\n\n-- Installation side. Zone-authored keysites carry their own side (rec.side, set by the zone colour);\n-- auto-placed installations follow their home base's current owner (captures propagate).\nfunction M.side_of(rec)\n    if rec.side then return rec.side end\n    return S.base_owner[rec.home_base]\nend\n\n-- \226\148\128\226\148\128 nearest_producer(side, commodity, pos) \226\128\148 supplier selection for a physical supply flight \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors fc_msgs.c:759-800 response_to_force_low_on_supplies supplier lookup: for AMMO pick the\n-- closest FACTORY (fall back to any producer); for FUEL the closest OIL_REFINERY/PORT (fall back to\n-- any producer). This is the PICK_UP keysite (taskgen.c:1638) \226\128\148 the transport routes here first.\n-- Only ALIVE + owned producers qualify (same gate as production_rates: the crate physically exists\n-- only while its factory stands, so killing the factory kills the resupply too). Returns\n-- {name=, pos=} of the nearest qualifying producer, or nil if the side has none alive.\nfunction M.nearest_producer(side, commodity, pos)\n    local primary, primary_d2 = nil, math.huge   -- producer that makes THIS commodity (factory/refinery)\n    local any, any_d2         = nil, math.huge    -- any live producer (fc_msgs fallback path)\n    for kname, rec in pairs(S.keysites or {}) do\n        local p = rec.producer\n        if p and not rec.pending and rec.health > 0.1 and (rec.alive == nil or rec.alive > 0)\n           and M.side_of(rec) == side and rec.pos then\n            local d2 = 0\n            if pos then local dx, dz = pos.x - rec.pos.x, pos.z - rec.pos.z; d2 = dx*dx + dz*dz end\n            if d2 < any_d2 then any_d2 = d2; any = { name = kname, pos = rec.pos } end\n            if (p[commodity] or 0) > 0 and d2 < primary_d2 then\n                primary_d2 = d2; primary = { name = kname, pos = rec.pos }\n            end\n        end\n    end\n    return primary or any\nend\n\n-- \226\148\128\226\148\128 ground_strike targets for `attacker` = enemy installations still standing \226\148\128\n-- Enumerator (NOT a scorer): returns every enemy ground_strike_target installation still standing.\n-- keysite.strike_candidates rates these with the ONE create_keysite_strike_tasks formula\n-- (highlevl.c:1093-1127) alongside airbases \226\128\148 the port no longer scores installations with a\n-- separate invented table. `recon_target` is surfaced so the funnel's recon-fork can honour the\n-- keysite_database row (ks_dbase.c) per site.\nfunction M.strike_targets(attacker)\n    local enemy, out = cs.ENEMY[attacker], {}\n    for kname, rec in pairs(S.keysites or {}) do\n        if rec.flags.ground_strike_target and not rec.pending and rec.health > 0.1 and M.side_of(rec) == enemy then\n            out[#out + 1] = { name = kname, pos = rec.pos, health = rec.health, kind = rec.kind,\n                              recon_target = rec.flags.recon_target == true }\n        end\n    end\n    return out\nend\n\n-- \226\148\128\226\148\128 Core damage application \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Reduce an installation's health; at \226\137\164 0.1 it is destroyed (dropped from strike_targets and its\n-- visual static removed). This is the single source of truth for installation attrition.\nfunction M.damage(kname, amount, log_fn)\n    log_fn = log_fn or function() end\n    local rec = S.keysites and S.keysites[kname]\n    if not rec then return end\n\n    -- Under-attack notification (keysite.c:854-939 notify_keysite_structure_under_attack): wired for\n    -- parity with the airbase strike path. Installation keysites are requires_cap=FALSE (ks_dbase.c)\n    -- and carry no base owner, so reaction.on_keysite_under_attack no-ops here (no defensive CAP for a\n    -- factory/depot/radar) \226\128\148 faithful: EECH scrambles CAP only for keysites whose row requires it.\n    local ok_r, react = pcall(require, \"reaction\")\n    if ok_r and react and react.on_keysite_under_attack then\n        pcall(react.on_keysite_under_attack, kname, log_fn)\n    end\n\n    -- REGISTERED-ASSET keysite (zone-authored): a strike destroying `amount` of its strength destroys\n    -- ceil(amount * total) of the still-alive placed statics; health drains to alive/total. At <=0.1 it\n    -- is neutralised/capturable but the record is KEPT (feeds the capture + economy loop).\n    if rec.assets then\n        if (rec.alive or 0) <= 0 then return end\n        local before   = rec.health or 0\n        local want      = math.min(math.ceil((amount or KILL_DMG) * rec.total), rec.alive)\n        local destroyed = 0\n        for _, nm in ipairs(rec.assets) do\n            if destroyed >= want then break end\n            if not rec.dead[nm] then\n                local so = StaticObject.getByName(nm)\n                if so then pcall(function() so:destroy() end) end\n                rec.dead[nm] = true   -- idempotent with the S_EVENT_DEAD handler\n                destroyed = destroyed + 1\n            end\n        end\n        -- Statics exhausted but more destruction still owed \226\134\146 burn registered SCENERY too. Try the\n        -- object's destroy() (SceneryObject may not expose one \226\128\148 pcall-guarded); either way mark the\n        -- entry dead so health drains, and the getLife poll confirms/backstops it.\n        if destroyed < want and rec.scenery then\n            for _, s in ipairs(rec.scenery) do\n                if destroyed >= want then break end\n                if not s.dead then\n                    pcall(function() s.handle:destroy() end)\n                    s.dead = true\n                    destroyed = destroyed + 1\n                end\n            end\n        end\n        recompute_health(rec)\n        if rec.health > 0.1 then\n            log_fn(string.format(\"keysite %s struck: %.0f%%->%.0f%% (%d/%d statics left)\",\n                rec.label or kname, before * 100, rec.health * 100, rec.alive, rec.total))\n            cs.dbg(\"installs\", \"%s damaged: %.0f%%->%.0f%% (%d assets destroyed this hit, %d/%d left)\",\n                kname, before * 100, rec.health * 100, destroyed, rec.alive, rec.total)\n        else\n            log_fn(string.format(\"keysite %s DESTROYED%s (%s) \226\128\148 %d/%d statics, capturable\",\n                rec.label or kname, rec.producer and \" \226\128\148 PRODUCER LOST, supply cut\" or \"\",\n                cs.SIDE_NAME[M.side_of(rec)] or \"?\", rec.alive, rec.total))\n            cs.dbg(\"installs\", \"%s NEUTRALISED (%.0f%%->%.0f%%)%s owner=%s\", kname, before * 100, rec.health * 100,\n                rec.producer and \" PRODUCER LOST\" or \"\", cs.SIDE_NAME[M.side_of(rec)] or \"?\")\n        end\n        return rec.health\n    end\n\n    -- AUTO-path keysite (no zones): legacy abstract-health model + single-object destroy.\n    if rec.health <= 0.1 then return end\n    local before = rec.health\n    rec.health = math.max(0, rec.health - (amount or KILL_DMG))\n    if rec.health > 0.1 then\n        log_fn(string.format(\"installation struck: %s %.0f%%->%.0f%% (%s)\",\n            rec.label, before * 100, rec.health * 100, kname))\n        cs.dbg(\"installs\", \"%s (auto) damaged: %.0f%%->%.0f%%\", kname, before * 100, rec.health * 100)\n    end\n    if rec.health <= 0.1 then\n        local owner = M.side_of(rec)\n        log_fn(string.format(\"installation DESTROYED: %s at %s%s (%s)\", rec.label, rec.home_base,\n            rec.producer and \" \226\128\148 PRODUCER LOST, supply cut\" or \"\",\n            cs.SIDE_NAME[owner] or \"?\"))\n        cs.dbg(\"installs\", \"%s (auto) NEUTRALISED at %s%s owner=%s\", kname, rec.home_base,\n            rec.producer and \" PRODUCER LOST\" or \"\", cs.SIDE_NAME[owner] or \"?\")\n        -- Remove the physical object \226\128\148 a static (via StaticObject) or an EWR unit group (via Group).\n        pcall(function()\n            if rec.spawn_kind == \"unit\" then\n                local g = Group.getByName(kname)\n                if g then g:destroy() end\n            else\n                local so = StaticObject.getByName(kname)\n                if so then so:destroy() end\n            end\n        end)\n    end\n    return rec.health\nend\n\n-- NOTE: the generic kill-proximity bleed (apply_kill_damage: any kill within KILL_RADIUS of an\n-- installation chipped its health) was REMOVED in Cluster G. EECH keysite strength changes only when\n-- the keysite's own registered structures die \226\128\148 that path already exists (register_static_death, the\n-- S_EVENT_DEAD handler) \226\128\148 so the extra proximity channel double-counted every registered-asset death.\n-- Installation attrition is now driven exclusively by (a) the deterministic strike channel (M.damage,\n-- called by the strike scheduler at time-on-target) and (b) register_static_death (real structure death).\n\nreturn M\n"
__modules["keysite"] = "-- keysite.lua\n-- Inspired by:\n--   aphavoc/source/entity/special/keysite/keysite.h     KEYSITE entity: side, strength, position\n--   aphavoc/source/entity/special/keysite/ks_funcs.c    capture_keysite, destroy_keysite\n--   aphavoc/source/entity/special/keysite/ks_updt.c     supply tracking, assign_timer (3 min)\n--   aphavoc/source/entity/special/sector/sc_secfuncs.c  sector ownership, influence map updates\n--   aphavoc/source/ai/highlevl/imaps.c                  IMAP_BASE_DISTANCE, IMAP_IMPORTANCE scoring\n--\n-- Manages airbase (keysite) ownership, structural health, damage, and capture.\n-- Provides target-scoring used by attack_waves.lua.\n-- Mirrors KEYSITE entity: sub_type=AIRBASE, side, keysite_strength, keysite_usable_state.\n\nlocal cs   = require(\"campaign_state\")\nlocal imap = require(\"imap\")\nlocal S    = cs.S\nlocal M    = {}\n\n-- MIN_TASK_CREATION_RATIO \226\128\148 a candidate whose rating is < 75% of the top target's rating is not\n-- worth tasking this cycle (highlevl.c:88). FOW recon threshold = 0.25 * FOW maximum (highlevl.c:1179).\nlocal MIN_TASK_CREATION_RATIO = 0.75   -- highlevl.c:88\nlocal FOW_RECON_THRESHOLD     = 0.25   -- highlevl.c:1179 (0.25 * FLOAT_TYPE_FOG_OF_WAR_MAXIMUM_VALUE)\n\n-- \226\148\128\226\148\128 Airdrome discovery \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors keysite sub_type filter: ENTITY_SUB_TYPE_KEYSITE_AIRBASE\n\nlocal function all_airdromes()\n    local out, seen = {}, {}\n    for _, side in ipairs({ coalition.side.NEUTRAL, coalition.side.BLUE, coalition.side.RED }) do\n        for _, ab in ipairs(coalition.getAirbases(side)) do\n            local n = ab:getName()\n            -- ab:getDesc().category == Airbase.Category.AIRDROME (0) is the correct check;\n            -- ab:getCategory() returns Object.Category.BASE (4) which is WRONG.\n            -- Guard nil desc: runtime-spawned FARPs register as HELIPAD airbases and, once destroyed,\n            -- can linger in getAirbases() with a nil getDesc(); filtering to AIRDROME here also keeps\n            -- FARP (HELIPAD) keysites out of the fixed-wing airbase registry (they are their own layer).\n            local d = ab:getDesc()\n            if d and d.category == Airbase.Category.AIRDROME and not seen[n] then\n                seen[n] = true\n                out[#out + 1] = ab\n            end\n        end\n    end\n    return out\nend\n\n-- \226\148\128\226\148\128 Initialisation \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors initialise_order_of_battle (order.c): assigns all keysites to a force,\n-- builds initial keysite registry with side, position, and full health.\n\nfunction M.init_base_state(log_fn)\n    log_fn = log_fn or function() end\n\n    -- Prefer coalition-assigned bases from the mission editor\n    local assigned = {}\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        for _, ab in ipairs(coalition.getAirbases(side)) do\n            local d = ab:getDesc()   -- guard nil desc (lingering destroyed HELIPAD/FARP airbases)\n            if d and d.category == Airbase.Category.AIRDROME then\n                assigned[ab:getName()] = side\n            end\n        end\n    end\n\n    local all = all_airdromes()\n\n    -- \226\148\128\226\148\128 AUTHORED THEATRE via ME trigger zones (preferred) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- If the mission author placed zones, they define the theatre and ownership:\n    --   \226\128\162 BLUE + RED boxes  \226\134\146 airfields inside each become that side; the theatre is their union;\n    --                          anything outside both is excluded. The gap between them is the front.\n    --   \226\128\162 THEATRE box only  \226\134\146 scope to it, then auto-split sides (below).\n    -- Falls back to the automatic densest-cluster scoping when no zones are placed.\n    local zones = require(\"zones\")\n    zones.load()\n\n    -- \226\148\128\226\148\128 FULLY-AUTHORED zone-based theatre (preferred) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- If the author placed one zone per keysite (colour = side, first word of name = type, centre =\n    -- location \226\128\148 see README \"Authoring a mission\"), the WHOLE order of battle is read from them and\n    -- the auto-generation below is skipped entirely. Only airfields covered by an `airbase` zone are\n    -- in play; `farp` zones become forward heli bases; other keysite zones are handled by\n    -- installations.lua. Ownership is the zone colour, so there is NO x-median side split here.\n    if zones.has_keysite_zones() then\n        S.base_kind = S.base_kind or {}\n        local ksz = zones.keysites()\n        local n_ab, n_farp, n_ks, farp_seen = 0, 0, 0, {}\n\n        for _, kz in ipairs(ksz) do\n            if kz.type == \"airbase\" and kz.side then\n                -- Bind the zone to the DCS AIRDROME nearest its centre; that airfield's real position\n                -- is the keysite location. Airfields no airbase zone covers are excluded (never added).\n                local best, bestd = nil, math.huge\n                for _, ab in ipairs(all) do\n                    local p = ab:getPosition().p\n                    local d = cs.dist2d(p.x, p.z, kz.x, kz.z)\n                    if d < bestd then bestd = d; best = ab end\n                end\n                if best then\n                    local nm = best:getName()\n                    local p  = best:getPosition().p\n                    S.base_pos[nm]    = { x = p.x, z = p.z }\n                    S.base_health[nm] = 1.0\n                    S.base_owner[nm]  = kz.side\n                    S.base_kind[nm]   = \"airbase\"\n                    n_ab = n_ab + 1\n\n                    -- REGISTER the DCS airbase warehouse inventory (aircraft type\226\134\146count). This is\n                    -- read/registered but DOES NOT drive sortie generation: per the user's explicit\n                    -- 2026-07-07 decision the port uses the EECH economy (per-base reserve ledger +\n                    -- production crates), NOT a warehouse-driven OOB. The registration is retained as\n                    -- authored data for future use (a possible F10 inventory display / restore surface) \226\128\148\n                    -- documented-intentional, NOT accidentally-dead. Do NOT wire it into the ledger.\n                    -- pcall-guarded (getWarehouse/getInventory can throw on some bases).\n                    S.base_warehouse = S.base_warehouse or {}\n                    local ok_w, inv = pcall(function() return best:getWarehouse():getInventory() end)\n                    if ok_w and inv and inv.aircraft then\n                        local summ = {}\n                        for atype, cnt in pairs(inv.aircraft) do summ[atype] = cnt end\n                        S.base_warehouse[nm] = summ\n                    end\n\n                    -- REGISTER placed statics AND destroyable resource scenery (the airfield's built-in\n                    -- fuel-barrel dumps / GSM / warehouses \226\128\148 TOPLIVO-BAK/SKLADIK/etc.) inside the airbase\n                    -- zone as this airbase's assets (same structure as installations.lua). Spawns nothing.\n                    -- Count scales with airfield size: Batumi ~5, Kutaisi ~80 \226\128\148 the author's zone bounds it.\n                    local ab_assets = zones.statics_in_zone(kz.label)\n                    local ab_scenery = {}\n                    for _, srow in ipairs(zones.scenery_in_zone(kz.label, zones.RESOURCE_SCENERY)) do\n                        ab_scenery[#ab_scenery + 1] =\n                            { id = srow.id, type = srow.type, handle = srow.handle, dead = false }\n                    end\n                    local ab_total = #ab_assets + #ab_scenery\n                    if ab_total > 0 then\n                        S.keysites = S.keysites or {}\n                        S.keysites[\"AB-\" .. nm] = {\n                            kind = \"airbase\", side = kz.side, pos = { x = p.x, z = p.z },\n                            home_base = nm, assets = ab_assets, dead = {}, scenery = ab_scenery,\n                            total = ab_total, alive = ab_total, health = 1.0,\n                            flags = { ground_strike_target = true, recon_target = true },\n                            label = \"Airfield assets \" .. nm, producer = nil,\n                        }\n                    end\n\n                    log_fn(string.format(\n                        \"  airbase keysite %s \226\134\146 %s (%s) \226\128\148 warehouse %s, %d placed statics + %d scenery\",\n                        nm, cs.SIDE_NAME[kz.side] or \"?\", kz.label,\n                        (S.base_warehouse and S.base_warehouse[nm]) and \"read\" or \"unavailable\",\n                        #ab_assets, #ab_scenery))\n                end\n            end\n        end\n\n        for _, kz in ipairs(ksz) do\n            if kz.type == \"farp\" and kz.side then\n                -- Forward heli base created AT the zone centre; base_kind \"farp\" (heli-only ledger).\n                local base = \"FARP-\" .. tostring(kz.label or \"farp\")\n                local uniq, k = base, 1\n                while S.base_owner[uniq] or farp_seen[uniq] do\n                    k = k + 1; uniq = base .. \"-\" .. k\n                end\n                farp_seen[uniq]    = true\n                S.base_pos[uniq]   = { x = kz.x, z = kz.z }\n                S.base_health[uniq]= 1.0\n                S.base_owner[uniq] = kz.side\n                S.base_kind[uniq]  = \"farp\"\n                n_farp = n_farp + 1\n                log_fn(string.format(\"  farp keysite %s \226\134\146 %s\", uniq, cs.SIDE_NAME[kz.side] or \"?\"))\n            elseif kz.type ~= \"airbase\" and kz.type ~= \"farp\" then\n                n_ks = n_ks + 1   -- non-basing keysite (factory/refinery/radar/... \226\134\146 installations.lua)\n            end\n        end\n\n        log_fn(string.format(\"theatre from zones: %d airbases, %d FARPs, %d keysites\",\n            n_ab, n_farp, n_ks))\n        cs.dbg(\"keysite\", \"init_base_state (zone-authored theatre): %d airbases, %d FARPs, %d installations\",\n            n_ab, n_farp, n_ks)\n        M.designate_objectives(log_fn)\n        return\n    end\n\n    local zone_owner = {}   -- base name \226\134\146 side, when BLUE/RED zones assign ownership explicitly\n    local zone_scoped = false\n\n    if zones.exists(\"BLUE\") and zones.exists(\"RED\") then\n        local scoped, total = {}, #all\n        for _, ab in ipairs(all) do\n            local p = ab:getPosition().p\n            local side\n            if zones.contains(\"BLUE\", p.x, p.z) then side = coalition.side.BLUE\n            elseif zones.contains(\"RED\", p.x, p.z) then side = coalition.side.RED end\n            if side then scoped[#scoped + 1] = ab; zone_owner[ab:getName()] = side end\n        end\n        if #scoped >= 2 then all = scoped end\n        zone_scoped = true\n        log_fn(string.format(\"theatre from ME zones (BLUE/RED): %d of %d airfields in play\", #all, total))\n    elseif zones.exists(\"THEATRE\") then\n        local scoped, total = {}, #all\n        for _, ab in ipairs(all) do\n            local p = ab:getPosition().p\n            if zones.contains(\"THEATRE\", p.x, p.z) then scoped[#scoped + 1] = ab end\n        end\n        if #scoped >= 4 then all = scoped end\n        zone_scoped = true\n        log_fn(string.format(\"theatre from ME zone (THEATRE): %d of %d airfields in play\", #all, total))\n    end\n\n    -- THEATRE SCOPING (fallback, no zones): an EECH warzone is ~260 km across (128 sectors x 2048 m \226\128\148\n    -- parser.c:347 / en_world.c set_entity_world_map_size), far smaller than DCS Caucasus (~500+ km).\n    -- Scope to the densest EECH-sized cluster so distances/gameplay match.\n    if not zone_scoped then\n        local THEATRE_RADIUS = 130000   -- m; ~260 km theatre \226\137\136 EECH Georgia map extent\n        local total = #all\n        -- Centre the theatre on the DENSEST cluster (the airfield with the most neighbours within the\n        -- radius) rather than the centroid \226\128\148 the Caucasus fields span ~370x660 km, so the centroid can\n        -- land in an empty gap. This picks the busiest EECH-sized pocket of airfields.\n        local best_center, best_count = nil, -1\n        for _, c in ipairs(all) do\n            local cp, cnt = c:getPosition().p, 0\n            for _, ab in ipairs(all) do\n                local p = ab:getPosition().p\n                if cs.dist2d(p.x, p.z, cp.x, cp.z) <= THEATRE_RADIUS then cnt = cnt + 1 end\n            end\n            if cnt > best_count then best_count = cnt; best_center = cp end\n        end\n        if best_center then\n            local scoped = {}\n            for _, ab in ipairs(all) do\n                local p = ab:getPosition().p\n                if cs.dist2d(p.x, p.z, best_center.x, best_center.z) <= THEATRE_RADIUS then\n                    scoped[#scoped + 1] = ab\n                end\n            end\n            if #scoped >= 6 then all = scoped end   -- guard: keep a playable count\n        end\n        log_fn(string.format(\"theatre scoped to ~%.0f km (densest cluster): %d of %d airfields in play\",\n            THEATRE_RADIUS * 2 / 1000, #all, total))\n    end\n\n    -- COHERENT territory split (used only when ownership is NOT authored by BLUE/RED zones): project\n    -- each base onto the x axis and cut at the median so each side owns a contiguous block with the\n    -- frontline between them. On DCS Caucasus low-x = Georgia (BLUE), high-x = Russia (RED).\n    table.sort(all, function(a, b) return a:getPosition().p.x < b:getPosition().p.x end)\n    local half = math.floor(#all / 2)\n\n    local counts = { [coalition.side.BLUE] = 0, [coalition.side.RED] = 0 }\n    for i, ab in ipairs(all) do\n        local n   = ab:getName()\n        local pos = ab:getPosition().p\n        S.base_health[n] = 1.0   -- mirrors keysite.keysite_strength = keysite_maximum_strength\n        S.base_pos[n]    = { x = pos.x, z = pos.z }\n\n        -- Zone-authored ownership wins; else editor coalition; else the contiguous median split.\n        local side = zone_owner[n] or assigned[n] or ((i <= half) and coalition.side.BLUE or coalition.side.RED)\n        S.base_owner[n] = side\n        counts[side]    = (counts[side] or 0) + 1\n        log_fn(string.format(\"  keysite %s \226\134\146 %s\", n, cs.SIDE_NAME[side] or \"?\"))\n    end\n    log_fn(string.format(\"keysites initialised: BLUE=%d RED=%d total=%d\",\n        counts[coalition.side.BLUE], counts[coalition.side.RED], #all))\n    cs.dbg(\"keysite\", \"init_base_state (auto theatre): BLUE=%d RED=%d total=%d\",\n        counts[coalition.side.BLUE], counts[coalition.side.RED], #all)\n\n    M.designate_objectives(log_fn)\nend\n\n-- \226\148\128\226\148\128 Campaign objective selection \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors create_force_campaign_objectives (eech ai/highlevl/setup.c:126-289): for each force,\n-- choose NUMBER_OF_CAMPAIGN_OBJECTIVES_PER_SIDE (5, setup.c:79) ENEMY keysites, rated by\n-- isolation = distance to the closest OTHER enemy keysite (setup.c:224-253) plus frand1()\n-- (\"obligatory random factor\", setup.c:255-262); take the top 5.\n-- PROXY: all port keysites are airbases (equal keysite_database importance 1.0), so importance\n-- gives no ordering \226\128\148 the EECH isolation+random rating IS the selection rule and is reproduced\n-- exactly. The result is the per-side objective set the win check tests (KEYSITE-F26/F31).\nfunction M.designate_objectives(log_fn)\n    log_fn = log_fn or function() end\n    S.objectives = { [coalition.side.BLUE] = {}, [coalition.side.RED] = {} }\n\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        local enemy = cs.ENEMY[side]\n        -- Candidate set: every enemy-owned keysite at OOB (eech: enemy keysites that are\n        -- POTENTIAL_CAMPAIGN_OBJECTIVE and IN_USE \226\128\148 all port airbases qualify).\n        local cands = {}\n        for name, owner in pairs(S.base_owner) do\n            if owner == enemy then\n                local bp = S.base_pos[name]\n                if bp then\n                    -- isolation: distance to the closest OTHER enemy keysite (setup.c:224)\n                    local iso = math.huge\n                    for other, oowner in pairs(S.base_owner) do\n                        if oowner == enemy and other ~= name then\n                            local op = S.base_pos[other]\n                            if op then\n                                local d = cs.dist2d(bp.x, bp.z, op.x, op.z)\n                                if d < iso then iso = d end\n                            end\n                        end\n                    end\n                    if iso == math.huge then iso = 0 end\n                    cands[#cands + 1] = { name = name, iso = iso }\n                end\n            end\n        end\n\n        -- Normalise isolation by the maximum (setup.c:244-253), add frand1() (setup.c:255-262).\n        local max_iso = 0\n        for _, c in ipairs(cands) do if c.iso > max_iso then max_iso = c.iso end end\n        for _, c in ipairs(cands) do\n            local norm = (max_iso > 0) and (c.iso / max_iso) or 0\n            c.rating = norm + math.random()   -- math.random() \226\136\136 [0,1) proxies frand1()\n        end\n        table.sort(cands, function(a, b) return a.rating > b.rating end)\n\n        local n = math.min(#cands, cs.OBJECTIVES_PER_SIDE)\n        for i = 1, n do S.objectives[side][i] = cands[i].name end\n        log_fn(string.format(\"objectives %s (must capture %d enemy keysites): %s\",\n            cs.SIDE_NAME[side] or \"?\", n, table.concat(S.objectives[side], \", \")))\n        cs.dbg(\"keysite\", \"objectives designated for %s: %d of %d enemy candidates -> %s\",\n            cs.SIDE_NAME[side] or \"?\", n, #cands, table.concat(S.objectives[side], \",\"))\n    end\nend\n\n-- \226\148\128\226\148\128 Queries \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- NOTE: best_friendly_base, best_friendly_airbase and behind_base were DELETED in Cluster H \226\128\148 all\n-- three had zero callers (pre-task-board / pre-ground-spawn-era leftovers: launch-base selection now\n-- lives in the task board's per-base ledger + slot gate, and spawns start on the ground at the chosen\n-- base with real TakeOff waypoints \226\128\148 no \"behind the base\" in-air offset).\n\n-- \226\148\128\226\148\128 Landing-slot / basing-capacity arbitration (Cluster 5) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH throttles sortie tempo per keysite via LANDING entities holding slot counts. A keysite's\n-- available landing sites = free_landing_sites - reserved_landing_sites (eech keysite.c:313-331,\n-- :324 get_keysite_landing_sites_available; spec 07 TASK-F23). Order generation / assignment gate\n-- on that availability (assign.c:879/:906); a sortie RESERVES a site at assignment\n-- (RESERVE_LANDING_SITE, ld_msgs.c:950) and frees it on landing/loss (UN/LOCK_LANDING_SITE,\n-- ld_msgs.c:1567). The port reproduces this as an in-flight-sortie counter per launch base.\n--\n-- CAPACITY: total_landing_sites is PER-KEYSITE scenario/route data (eech ai/faction/parser.c:2667,\n-- FILE_TAG_COUNT) with NO compiled-in default, so the port tiers a proxy default by the keysite's\n-- air_force_capacity enum (NONE/SMALL/LARGE, eech keysite.h:77-84; airbase = LARGE, ks_dbase.c /\n-- spec 03:88). LARGE = 4 is a labeled PROXY anchored to the airbase per-pass assignment budget\n-- (assign_task_count = 3, eech assign.c:218 / spec 03:91) + 1 headroom so one lingering prior-pass\n-- sortie cannot zero out the current pass's launch budget.\n--\n-- GRANULARITY PROXY: EECH locks per-AIRFRAME landing sites (formation_position bitmask, landing.c);\n-- the port tracks per-SORTIE (group) \226\128\148 matching its group-level ledger/spawn model and the per-group\n-- land/dead release handlers. One occupied slot = one in-flight sortie launched from the base.\nM.SLOT_CAPACITY = { NONE = 0, SMALL = 4, LARGE = 8 }  -- airbase can run more concurrent sorties;\n                                                       -- 4 starved insertions at busy frontline bases\n\n-- All port keysites are airbases (all_airdromes filters to AIRDROME) \226\134\146 air_force_capacity LARGE.\nfunction M.base_slot_capacity(name)\n    -- Size-aware: a forward FARP/FOB is a small landing site (fewer concurrent sorties) than a full\n    -- airbase (eech keysite landing-site capacity is per keysite type). base_kind mirrors EECH's\n    -- air_force_capacity SMALL vs LARGE \226\128\148 same split do_capture uses for the repair bump.\n    local kind = name and S.base_kind and S.base_kind[name]\n    return (kind == \"farp\" or kind == \"fob\") and M.SLOT_CAPACITY.SMALL or M.SLOT_CAPACITY.LARGE\nend\n\n-- Available launch/landing slots at a base = capacity - in-flight sorties (>= 0). Mirrors\n-- get_keysite_landing_sites_available = free - reserved (eech keysite.c:324).\nfunction M.slot_available(name)\n    if not name then return 0 end\n    local used = (S.base_inflight and S.base_inflight[name]) or 0\n    return M.base_slot_capacity(name) - used\nend\n\n-- Reserve one slot at `base` for sortie `gname` (RESERVE/LOCK_LANDING_SITE, ld_msgs.c:950/:599).\n-- Records the launch base so the slot can be released on RTB-land / death. Idempotent per group.\nfunction M.reserve_slot(base, gname)\n    if not base or not gname then return end\n    S.base_inflight     = S.base_inflight or {}\n    S.group_launch_base = S.group_launch_base or {}\n    if S.group_launch_base[gname] then return end   -- already holds a slot for this sortie\n    S.group_launch_base[gname] = base\n    S.base_inflight[base] = (S.base_inflight[base] or 0) + 1\nend\n\n-- Release the slot held by sortie `gname` (UNLOCK_LANDING_SITE, ld_msgs.c:1567). Idempotent: a\n-- second call (e.g. death then despawn-timer, or first-unit-death then RTB) is a no-op. Clamps \226\137\165 0.\nfunction M.release_slot(gname)\n    if not gname then return end\n    local base = S.group_launch_base and S.group_launch_base[gname]\n    if not base then return end\n    S.group_launch_base[gname] = nil\n    if S.base_inflight then\n        S.base_inflight[base] = math.max(0, (S.base_inflight[base] or 0) - 1)\n    end\nend\n\n-- \226\148\128\226\148\128 Unified keysite accessor (Wave 1 \226\128\148 one enumeration surface over both namespaces) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- The port keeps keysite state in TWO parallel namespaces: BASING keysites (airbases/FARPs in\n-- S.base_owner / S.base_pos / S.base_health / S.base_kind) and non-basing INSTALLATIONS (S.keysites\n-- records). get()/all() give consumers ONE uniform read-only view so they stop branching per-namespace,\n-- and give persistence a single enumeration point. This is a lookup FACADE only \226\128\148 it does NOT migrate\n-- the underlying storage (deliberately: a mid-campaign storage move is too invasive; GOAL P2).\n--\n-- get(name) \226\134\146 view, or nil if `name` is neither a base nor an installation. The resolution reproduces\n-- reaction.lua's keysite_owner / keysite_pos / keysite_health EXACTLY (those helpers now delegate here):\n--   view = { name, kind, side, owner (== side), pos, health, is_basing, rec }\n-- owner : basing \226\134\146 S.base_owner[name]; installation \226\134\146 rec.side or S.base_owner[rec.home_base] (may be nil)\n-- pos   : basing \226\134\146 S.base_pos[name];   installation \226\134\146 rec.pos\n-- health: basing \226\134\146 S.base_health[name]; installation \226\134\146 rec.health (nil \226\134\146 1.0; a caller resolves the\n--         \"unknown base \226\134\146 1.0\" case via the nil return, matching keysite_health's tail).\nfunction M.get(name)\n    if not name then return nil end\n    local basing_owner = S.base_owner[name]\n    if basing_owner ~= nil then\n        return {\n            name      = name,\n            kind      = S.base_kind and S.base_kind[name] or nil,\n            side      = basing_owner,\n            owner     = basing_owner,\n            pos       = S.base_pos[name],\n            health    = S.base_health[name],\n            is_basing = true,\n            rec       = nil,\n        }\n    end\n    local rec = S.keysites and S.keysites[name]\n    if rec then\n        local owner = rec.side or S.base_owner[rec.home_base]\n        return {\n            name      = name,\n            kind      = rec.kind,\n            side      = owner,\n            owner     = owner,\n            pos       = rec.pos,\n            health    = (rec.health ~= nil) and rec.health or 1.0,\n            is_basing = false,\n            rec       = rec,\n        }\n    end\n    return nil\nend\n\n-- all(side) \226\134\146 iterator over EVERY keysite (basing + installation) as get()-shaped views; pass a side to\n-- filter to that owner. The single enumeration surface for persistence and cross-namespace scans.\n-- Snapshots the current keysites into a list, then returns a closure: `for v in ks.all(side) do ... end`.\nfunction M.all(side)\n    local views = {}\n    for name in pairs(S.base_owner) do\n        local v = M.get(name)\n        if v and (side == nil or v.owner == side) then views[#views + 1] = v end\n    end\n    for name in pairs(S.keysites or {}) do\n        local v = M.get(name)\n        if v and (side == nil or v.owner == side) then views[#views + 1] = v end\n    end\n    local i = 0\n    return function()\n        i = i + 1\n        return views[i]\n    end\nend\n\n-- \226\148\128\226\148\128 Target scoring \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH create_keysite_strike_tasks (highlevl.c:1109-1127) and create_oca_strike_tasks\n-- (highlevl.c:1370-1381) rate every ground_strike / oca keysite with ONE weighted sum over the\n-- influence-map layers. Both share this core; only the per-term weights + max differ:\n--   ground strike : 1*(1-AIR_DEFENCE) + 4*BASE_DISTANCE + 2*(1-efficiency) + 2*side_ratio  max 9.0\n--   oca strike    : 1*(1-AIR_DEFENCE) + 4*BASE_DISTANCE +      (no eff)    + 2*side_ratio  max 7.0\n-- The IMAP_IMPORTANCE term is COMMENTED OUT in the C (highlevl.c:1113) \226\128\148 not ported. There is NO\n-- target damage/health term (the port's old 2*damage / 4*proximity \"obj_boost\" were invented, REMOVED).\nM.RATE_GROUND_STRIKE = { air_def = 1.0, base_dist = 4.0, eff = 2.0, side_ratio = 2.0, max = 9.0 } -- highlevl.c:1116-1127\nM.RATE_OCA_STRIKE    = { air_def = 1.0, base_dist = 4.0, eff = 0.0, side_ratio = 2.0, max = 7.0 } -- highlevl.c:1373-1381\n\n-- get_local_sector_side_ratio(x,z,side) proxy (highlevl.c:1125): fraction of nearby keysites owned\n-- by `side`. Uses the SAME 200 km radius the CAS/BAI/OCA-sweep generator uses for the same EECH call\n-- (cas_bai_sead.lua SECTOR_RATIO_RADIUS) so every rating formula reads one sector model.\nlocal SECTOR_RATIO_RADIUS = 200000   -- m; get_local_sector_side_ratio proxy radius\nlocal function sector_ratio(pos, side)\n    if not pos then return 0.0 end\n    local r2 = SECTOR_RATIO_RADIUS * SECTOR_RATIO_RADIUS\n    local friendly, total = 0, 0\n    for name, owner in pairs(S.base_owner) do\n        local bp = S.base_pos[name]\n        if bp then\n            local dx, dz = pos.x - bp.x, pos.z - bp.z\n            if dx * dx + dz * dz <= r2 then\n                total = total + 1\n                if owner == side then friendly = friendly + 1 end\n            end\n        end\n    end\n    if total == 0 then return 0.0 end\n    return friendly / total\nend\n\n-- Nearest owned/known base to a world position \226\128\148 the position's \"sector\" (there is no sector grid),\n-- used to read the FOW value that gates the recon fork (mirrors get_local_sector_entity(pos)).\nlocal function nearest_base_to(pos)\n    local best, best_d2 = nil, math.huge\n    for name, bp in pairs(S.base_pos) do\n        local dx, dz = pos.x - bp.x, pos.z - bp.z\n        local d2 = dx * dx + dz * dz\n        if d2 < best_d2 then best_d2 = d2; best = name end\n    end\n    return best\nend\n\n-- Weighted imap rating for an arbitrary keysite position + efficiency (shared by airbases and\n-- non-airbase installations so create_keysite_strike_tasks scores the whole ground_strike set with\n-- ONE formula). Reads the EXISTING imap layers (imap.get, normalised 0..1, refreshed every 120 s):\n--   IMAP_AIR_DEFENCE : highlevl.c:1116 reads it for the ENEMY side; the port builds this layer for\n--       `attacker` by scanning the ENEMY's AA (imap.lua:update_air_defence), so\n--       imap.get(attacker, AIR_DEFENCE, \194\183) IS the enemy-AA field. LOW enemy AA is preferred \226\134\146 (1-v).\n--   IMAP_BASE_DISTANCE : highlevl.c:1119 reads it for this_side (attacker) \226\128\148 closeness to the\n--       attacker's own bases (reachability). imap.get(attacker, BASE_DISTANCE, \194\183).\n--   efficiency + side_ratio read directly, exactly as EECH (FLOAT_TYPE_EFFICIENCY / sector_side_ratio).\nfunction M.rate_pos(attacker, tpos, eff, weights)\n    if not tpos then return 0 end\n    weights = weights or M.RATE_GROUND_STRIKE\n    eff = eff or 1.0\n    local air_def   = imap.get(attacker, imap.AIR_DEFENCE,   tpos)   -- highlevl.c:1116\n    local base_dist = imap.get(attacker, imap.BASE_DISTANCE, tpos)   -- highlevl.c:1119\n    local sr        = sector_ratio(tpos, attacker)                   -- highlevl.c:1125\n    return weights.air_def    * (1.0 - air_def)\n         + weights.base_dist  * base_dist\n         + weights.eff        * (1.0 - eff)\n         + weights.side_ratio * sr\nend\n\n-- Rating for a named airbase keysite. weights defaults to ground-strike; pass RATE_OCA_STRIKE for\n-- the OCA generator (which scans oca_target keysites = airbases only, ks_dbase.c:124/218).\nfunction M.rate_target(attacker, tname, weights)\n    local tpos = S.base_pos[tname]\n    if not tpos then return 0 end\n    if (S.base_health[tname] or 1) <= cs.HEALTH_DESTROYED then return 0 end   -- fully destroyed, skip\n    if S.base_owner[tname] == attacker then return 0 end                      -- own base, skip\n    return M.rate_pos(attacker, tpos, M.efficiency(tname), weights)\nend\n\n-- Returns (name, rating) of the best enemy airbase target; nil if none. Used by the OCA generator +\n-- reaction single-shots. Mirrors the top-of-list pick of create_oca_strike_tasks.\nfunction M.pick_target(attacker, log_fn, weights)\n    log_fn = log_fn or function() end\n    local best_name, best_r = nil, -1\n    local enemy = cs.ENEMY[attacker]\n\n    for name, owner in pairs(S.base_owner) do\n        -- Attack enemy-owned OR partly-damaged neutral bases\n        if owner == enemy or (owner ~= attacker and (S.base_health[name] or 1) < 1) then\n            local r = M.rate_target(attacker, name, weights)\n            if r > best_r then best_r = r; best_name = name end\n        end\n    end\n\n    if best_name then\n        log_fn(string.format(\"target: %s \226\134\146 %s (rating=%.2f health=%.0f%%)\",\n            cs.SIDE_NAME[attacker], best_name, best_r,\n            (S.base_health[best_name] or 1) * 100))\n        cs.dbg(\"keysite\", \"%s pick_target: %s rating=%.2f health=%.0f%%\",\n            cs.SIDE_NAME[attacker], best_name, best_r, (S.base_health[best_name] or 1) * 100)\n    else\n        cs.dbg(\"keysite\", \"%s pick_target: no candidate found\", cs.SIDE_NAME[attacker])\n    end\n    return best_name, best_r\nend\n\n-- Merged, rating-sorted candidate list across the WHOLE ground_strike_target keysite set (airbases\n-- AND non-airbase installations) scored by the ONE create_keysite_strike_tasks formula\n-- (highlevl.c:1093-1127 iterates every keysite whose keysite_database row is ground_strike_target).\n-- Each entry: { name, pos, eff, rating, recon_target, is_inst }. Replaces the old airbase/installation\n-- interleave with a single ranked scan (invented STRIKE_VALUE table + finish-off bonus removed).\nfunction M.strike_candidates(attacker, weights)\n    weights = weights or M.RATE_GROUND_STRIKE\n    local enemy = cs.ENEMY[attacker]\n    local out = {}\n    -- Airbases (ks_dbase.c AIRBASE row: ground_strike_target=TRUE, recon_target=TRUE, min_eff 0.3 \226\128\148\n    -- ks_dbase.c:103,125-126).\n    for name, owner in pairs(S.base_owner) do\n        if owner == enemy or (owner ~= attacker and (S.base_health[name] or 1) < 1) then\n            local pos = S.base_pos[name]\n            if pos and (S.base_health[name] or 1) > cs.HEALTH_DESTROYED then\n                local eff = M.efficiency(name)\n                out[#out + 1] = { name = name, pos = pos, eff = eff,\n                    rating = M.rate_pos(attacker, pos, eff, weights),\n                    recon_target = true, is_inst = false }\n            end\n        end\n    end\n    -- Non-airbase installations (ground_strike_target keysites \226\128\148 installations.strike_targets).\n    local ok_i, inst = pcall(require, \"installations\")\n    if ok_i and inst and inst.strike_targets then\n        for _, t in ipairs(inst.strike_targets(attacker)) do\n            out[#out + 1] = { name = t.name, pos = t.pos, eff = t.health,\n                rating = M.rate_pos(attacker, t.pos, t.health, weights),\n                recon_target = (t.recon_target == true), is_inst = true }\n        end\n    end\n    table.sort(out, function(a, b) return a.rating > b.rating end)\n    return out\nend\n\n-- create_keysite_strike_tasks funnel (highlevl.c:1155-1270). Scores the whole ground_strike set\n-- (strike_candidates), takes the top CREATE_KEYSITE_STRIKE_TASK_COUNT (n), and for each applies:\n--   \226\128\162 MIN_TASK_CREATION_RATIO gate \226\128\148 rating < 0.75*top \226\134\146 skip (highlevl.c:1167-1169).\n--   \226\128\162 recon-first fork (highlevl.c:1179): recon_target OR FOW(sector) < 0.25*max \226\134\146 dispatch RECON\n--       (the STRIKE is created later by the recon-complete reaction, reaction.c:482 / the port's\n--       react_recon_complete_keysite), with the recon-branch dedup on recon/bda/ground_strike/\n--       troop_insertion (highlevl.c:1185-1191).\n--   \226\128\162 else (recon not required) \226\134\146 direct strike iff efficiency >= minimum_efficiency (highlevl.c:1224;\n--       below-min keysites are left for troop insertion), with the strike-branch dedup on\n--       ground_strike/troop_insertion (highlevl.c:1227-1230).\n-- AIRBASES are recon_target=TRUE (ks_dbase.c:125) so they ALWAYS take the recon fork \226\128\148 the generator\n-- reconnoitres and the ground strike arrives via the reaction chain, exactly as EECH.\n-- INSTALLATIONS now take the SAME fork keyed on their TRUE recon_target row (Cluster I made\n-- react_recon_complete_keysite + reaction.keysite_flags installation-aware, so the all-installations\n-- direct-strike carve-out is removed): factory (recon_target=FALSE, ks_dbase.c:219) and port (:360)\n-- are direct-struck when visible; refinery/power/radar/military_base (recon_target=TRUE, :454/:407/\n-- :501/:313) recon-fork and the ground strike arrives via the reaction chain \226\128\148 exact EECH behaviour.\n-- (Installations have no port capture mechanic, so an installation that reaches eff < minimum is left\n-- by the strike branch \226\128\148 highlevl.c:1224 \226\128\148 and finished by the deterministic 0.5-per-sortie\n-- installations.damage / artillery, since EECH's below-min\226\134\146troop-insertion path needs a capturable\n-- keysite the port only models for airbases/FARPs.)\n-- Returns a list of decisions { action=\"strike\"|\"recon\", name, pos, is_inst } for attack_waves.\nfunction M.pick_targets(attacker, n, log_fn)\n    log_fn = log_fn or function() end\n    n = n or 3\n    local cands = M.strike_candidates(attacker, M.RATE_GROUND_STRIKE)\n    local decisions = {}\n    if #cands == 0 or cands[1].rating <= 0 then\n        cs.dbg(\"keysite\", \"%s strike funnel: 0 candidates\", cs.SIDE_NAME[attacker])\n        return decisions\n    end\n\n    local ok_f, fow = pcall(require, \"fog_of_war\")\n    local top_r = cands[1].rating\n    local count = math.min(#cands, n)\n    local n_strike, n_recon, n_ratio, n_dedup, n_eff = 0, 0, 0, 0, 0\n\n    for i = 1, count do\n        local e = cands[i]\n        if e.rating / top_r < MIN_TASK_CREATION_RATIO then\n            n_ratio = n_ratio + 1                               -- highlevl.c:1167-1169\n        else\n            -- Full EECH fork for BOTH airbases and installations, driven by each keysite's TRUE\n            -- recon_target row (no all-installations carve-out). FOW of the target's sector: the\n            -- keysite's own base key for airbases; the nearest base for installations.\n            local fow_val = 1.0\n            if ok_f and fow then\n                local fow_base = (S.base_pos[e.name] and e.name) or nearest_base_to(e.pos)\n                fow_val = (fow_base and fow.get(fow_base, attacker)) or 0.0\n            end\n            if e.recon_target or fow_val < FOW_RECON_THRESHOLD then   -- highlevl.c:1179\n                -- Dedup set highlevl.c:1185-1191 = RECON/BDA/GROUND_STRIKE/ANTI_SHIP/TROOP_INSERTION/\n                -- TROOP_MOVEMENT_INSERT_CAPTURE. ANTI_SHIP is n/a (no ship keysites); the port's single\n                -- \"troop_insertion\" type covers BOTH EECH troop task types (one insertion pipeline).\n                if cs.has_task_against(\"recon\", e.name, attacker)\n                   or cs.has_task_against(\"bda\", e.name, attacker)\n                   or cs.has_task_against(\"ground_strike\", e.name, attacker)\n                   or cs.has_task_against(\"troop_insertion\", e.name, attacker) then\n                    n_dedup = n_dedup + 1                        -- highlevl.c:1185-1191\n                else\n                    decisions[#decisions + 1] = { action = \"recon\", name = e.name, pos = e.pos, is_inst = e.is_inst }\n                    n_recon = n_recon + 1\n                end\n            elseif e.eff < cs.MINIMUM_EFFICIENCY then\n                n_eff = n_eff + 1                                -- highlevl.c:1224 (below-min \226\134\146 TI, not strike)\n            elseif cs.has_task_against(\"ground_strike\", e.name, attacker)\n                or cs.has_task_against(\"troop_insertion\", e.name, attacker) then\n                n_dedup = n_dedup + 1                            -- highlevl.c:1227-1230\n            else\n                decisions[#decisions + 1] = { action = \"strike\", name = e.name, pos = e.pos, is_inst = e.is_inst }\n                n_strike = n_strike + 1\n            end\n        end\n    end\n\n    cs.dbg(\"keysite\",\n        \"%s strike funnel: %d cands -> top %d checked: %d strike, %d recon(fogged/recon_target), %d below-ratio, %d deduped, %d eff-gated\",\n        cs.SIDE_NAME[attacker], #cands, count, n_strike, n_recon, n_ratio, n_dedup, n_eff)\n    return decisions\nend\n\n-- \226\148\128\226\148\128 Damage \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- NOTE: the generic kill-proximity bleed (apply_kill_damage: any kill within KILL_RADIUS of a base\n-- reduced its structural health) was REMOVED in Cluster G. EECH keysite_strength changes ONLY when\n-- the keysite's own buildings die (keysite.c:854), not from nearby air-to-air kills \226\128\148 the old channel\n-- double-dipped with strike_damage. Airbase attrition is now strike_damage (below) + registered-asset\n-- death (installations.register_static_death); the under-attack CAP notification lives in both paths.\n\n-- \226\148\128\226\148\128 Direct keysite-strike attrition \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- A strike package that reaches an airbase keysite reduces its building strength directly (mirrors\n-- EECH create_keysite_strike_tasks: keysites are degraded by strikes ON them, not only by incidental\n-- unit kills \226\128\148 an empty airfield takes no unit-kills, so without this the base can never fall). Also\n-- stamps the strike time so keysite_repair suppresses recovery while the keysite is under attack\n-- (EECH: a suppressed keysite does not run its repair loop).\nfunction M.strike_damage(bname, dmg, log_fn)\n    log_fn = log_fn or function() end\n    if not S.base_health[bname] then return end\n    local old_h = S.base_health[bname]\n    local new_h = math.max(0, old_h - dmg)\n    S.base_health[bname]     = new_h\n    S.base_efficiency        = S.base_efficiency or {}\n    S.base_efficiency[bname] = new_h\n    S.base_last_strike       = S.base_last_strike or {}\n    S.base_last_strike[bname] = timer.getTime()\n    -- Strict < min: UNUSABLE/capturable iff eff < minimum (keysite.c:827-830); matches the TI\n    -- generators' strict test so the \"capturable\" banner never fires for a base resting at exactly min.\n    local newly_neutralised = old_h >= cs.HEALTH_NEUTRALISED and new_h < cs.HEALTH_NEUTRALISED\n    log_fn(string.format(\"keysite strike: %s (%s) %.0f%%\226\134\146%.0f%%%s\",\n        bname, cs.SIDE_NAME[S.base_owner[bname]] or \"?\", old_h * 100, new_h * 100,\n        newly_neutralised\n            and string.format(\" \226\128\148 NEUTRALISED, capturable (<%.0f%%)\", cs.MINIMUM_EFFICIENCY * 100) or \"\"))\n    cs.dbg(\"keysite\", \"strike_damage: %s %.0f%%->%.0f%% (dmg=%.2f)%s\", bname, old_h * 100, new_h * 100,\n        dmg, newly_neutralised and \" -> NEUTRALISED\" or \"\")\n    -- Under-attack defensive CAP (keysite.c:854-939 notify_keysite_structure_under_attack): a struck\n    -- keysite scrambles CAP even when NO attacker task was registered (covers a HUMAN player's strike \226\128\148\n    -- MP-critical). Lazy pcall require avoids a load cycle (reaction requires keysite at the top).\n    local ok_r, react = pcall(require, \"reaction\")\n    if ok_r and react and react.on_keysite_under_attack then\n        pcall(react.on_keysite_under_attack, bname, log_fn)\n    end\n    return new_h\nend\n\n-- \226\148\128\226\148\128 Efficiency \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- FLOAT_TYPE_EFFICIENCY (eech ks_float.c:260-275) = keysite_strength / keysite_maximum_strength.\n-- In the port that is base_efficiency (kept == base_health by keysite_repair; see KEYSITE-F3).\nfunction M.efficiency(bname)\n    return (S.base_efficiency and S.base_efficiency[bname])\n        or (S.base_health and S.base_health[bname]) or 1.0\nend\n\n-- \226\148\128\226\148\128 Capture \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors capture_keysite(en, new_side) (eech keysite.c:1289-1518): probabilistic roll on the\n-- troop-insertion-capture waypoint, then flip side + instant repair + regen queue reseed +\n-- campaign-objective re-check. Capture is OFFERED only when efficiency < minimum (0.3).\n\nlocal CAPTURE_RANGE = 5000   -- m; ground column \"at\" the keysite (port proxy for insert waypoint)\n\n-- On-capture repair \226\128\148 eech keysite.c:1451-1462 repairs UP TO 5 buildings (for loop<5 call\n-- repair_client_server_entity_keysite), then USABLE if that reached full strength else REPAIRING (the\n-- slow 1-building/10-min heal continues). KEY nuance: \"5 buildings\" is SIZE-DEPENDENT \226\128\148 a SMALL keysite\n-- (FARP/FOB, air_force_capacity SMALL \226\128\148 only a handful of buildings) is effectively FULLY repaired by 5\n-- (\226\134\146 full strength \226\134\146 USABLE, and HELD), while a LARGE airbase (air_force_capacity LARGE \226\128\148 many\n-- buildings) gets only a partial bump (\226\134\146 REPAIRING, stays contestable). The port proxies this via\n-- base_kind. Without the size split, small FARPs came back at a flat ~0.65 and instantly flip-flopped,\n-- so the front oscillated on one base and never advanced \226\134\146 no decisive win.\nlocal CAPTURE_REPAIR_LARGE = 0.4   -- airbase: ~5 of ~12 buildings restored \226\134\146 partial, contestable\nlocal CAPTURE_REPAIR_SMALL = 1.0   -- FARP/FOB: 5 buildings \226\137\136 all \226\134\146 full (held); lets the front advance\n\n-- Regen queue reseed on capture \226\128\148 eech keysite.c:1483-1517 (AIRBASE): the new owner gains\n-- +6 helicopter and +4 fixed-wing regen slots; the destroy path (eech keysite.c:1266-1282,\n-- KEYSITE-F14) removes the same from the old owner. Port maps \"regen slots\" onto the per-side\n-- reserve pool (+ queued groups at the base) \226\128\148 see supply.lua / regen.lua.\nlocal CAPTURE_REGEN_HELI = 6   -- eech keysite.c:1490 (helicopter slots)\nlocal CAPTURE_REGEN_FW   = 4   -- eech keysite.c:1494 (fixed-wing slots)\n\n-- Defence score + probabilistic capture test \226\128\148 eech mb_msgs.c:2287-2308:\n--   d = (efficiency - minimum) / (1 - minimum)          [d is the DEFENCE score]\n--   d = d * member_count / (member_count + losses)\n--   capture iff d < frand1()\n-- efficiency \226\137\164 minimum \226\135\146 d \226\137\164 0 \226\135\146 guaranteed capture; full efficiency + intact troops \226\135\146 d\226\137\1361 \226\135\146\n-- capture chance \226\137\136 0. Uses the keysite's CURRENT efficiency, so a base that repairs above the\n-- minimum while troops are inbound can resist the capture.\nfunction M.capture_roll(bname, member_count, losses)\n    local eff = M.efficiency(bname)\n    local mn  = cs.MINIMUM_EFFICIENCY\n    local d   = (eff - mn) / (1.0 - mn)\n    member_count = member_count or 1\n    losses       = losses or 0\n    d = d * (member_count / (member_count + losses))\n    local roll = math.random()   -- math.random() \226\136\136 [0,1) proxies EECH frand1()\n    local won  = d < roll\n    cs.dbg(\"capture\", \"capture_roll %s: eff=%.2f defence_score=%.2f roll=%.2f -> %s\",\n        bname, eff, d, roll, won and \"CAPTURED\" or \"REPELLED\")\n    return won\nend\n\n-- Regen reseed side-effect (eech keysite.c:1483-1517 + 1266-1282).\nlocal function reseed_regen_on_capture(old_side, new_side, bname, log_fn)\n    local ok_s, supply = pcall(require, \"supply\")\n    if ok_s and supply then\n        -- new owner gains the base's air slots\n        supply.recycle_side(new_side, \"heli\",    CAPTURE_REGEN_HELI)\n        supply.recycle_side(new_side, \"striker\", CAPTURE_REGEN_FW)\n        -- old owner loses them (clamped at 0 \226\128\148 reserves never go negative on this path).\n        -- Drain ONE at a time: consume_side needs a single base to hold the whole count, so a\n        -- fragmented reserve (e.g. 3+3 heli across two bases, nreq 6) would otherwise remove\n        -- nothing. One-at-a-time drains across bases (each hit takes from the richest remaining).\n        local function shrink(side, role, nreq)\n            local have = supply.reserve_side(side, role)\n            for _ = 1, math.min(have, nreq) do\n                if not supply.consume_side(side, role, 1) then break end\n            end\n        end\n        shrink(old_side, \"heli\",    CAPTURE_REGEN_HELI)\n        shrink(old_side, \"striker\", CAPTURE_REGEN_FW)\n    end\n    -- queue the fresh default groups at the captured base so they actually regenerate.\n    -- F3: the FIXED-WING portion only at an AIRBASE \226\128\148 EECH reseeds a captured keysite with the group\n    -- types the keysite supports (keysite.c:1483 reseeds the AIRBASE default set; a FARP fields\n    -- helicopters only, ks_dbase.c FARP air_force_capacity SMALL/heli). The port's base_kind convention\n    -- (farps.lua: \"farp\"/\"fob\" = heli-only ledger, no striker stock) means FW regen entries at a\n    -- captured FARP could never be satisfied by spawn_regen \226\128\148 they'd sit as dead ring-buffer slots.\n    local ok_r, regen = pcall(require, \"regen\")\n    if ok_r and regen and regen.queue_reseed then\n        local kind = (S.base_kind and S.base_kind[bname]) or \"airbase\"\n        local fw_n = (kind == \"airbase\") and CAPTURE_REGEN_FW or 0\n        regen.queue_reseed(new_side, bname, CAPTURE_REGEN_HELI, fw_n, log_fn)\n    end\nend\n\n-- Apply the ownership flip and all capture side-effects (assumes the roll already succeeded).\nfunction M.do_capture(bname, new_side, log_fn)\n    log_fn = log_fn or function() end\n    local old_side = S.base_owner[bname]\n    if old_side == new_side then\n        cs.dbg(\"capture\", \"do_capture NO-OP: %s already owned by %s\", bname, cs.SIDE_NAME[new_side])\n        return false\n    end\n\n    S.base_owner[bname] = new_side\n    -- Repair UP TO 5 buildings on capture (eech keysite.c loop < 5), SIZE-aware: a small FARP/FOB is\n    -- fully covered by 5 buildings (\226\134\146 held); a large airbase gets a partial bump (\226\134\146 contestable).\n    local bump = ((S.base_kind and S.base_kind[bname]) == \"airbase\") and CAPTURE_REPAIR_LARGE or CAPTURE_REPAIR_SMALL\n    S.base_health[bname] = math.min(1.0, (S.base_health[bname] or 0) + bump)\n    S.base_efficiency = S.base_efficiency or {}\n    S.base_efficiency[bname] = S.base_health[bname]\n\n    -- Captured-aircraft disposition on keysite loss (WAVE 3 \226\128\148 realign to the C). This fork ships\n    -- command_line_capture_aircraft = TRUE by default (cmndline.c:151, \"Moje 040304\"), so on capture EECH\n    -- does NOT destroy or evacuate the RESIDENT IDLE aircraft parked at the seized keysite \226\128\148 it CHANGES\n    -- THEIR SIDE to the captor and leaves them parked there (capture_keysite: for each GROUP_MODE_IDLE\n    -- aircraft group, set INT_TYPE_SIDE = new_side, keysite.c:1375-1393). destroy_keysite's capture branch\n    -- then spares them because they are no longer the old side (keysite.c:1025-1090 only touches SIDE==old).\n    -- The port's per-base ledger IS exactly those idle parked groups (supply.lua header), and S.base_owner\n    -- has ALREADY flipped above, so we KEEP the ledger untouched: it now counts toward the new owner's\n    -- reserve (reserve_side sums owned-base ledgers). This realigns the previous \"zero the ledger\" proxy,\n    -- which modelled the command_line_capture_aircraft = FALSE branch (keysite.c:1130-1133 kills parked\n    -- aircraft) \226\128\148 the WRONG default for this fork. The regen-queue reseed below (keysite.c:1483-1517) adds\n    -- fresh production slots ON TOP, exactly as EECH does both (captured hardware + regen reseed).\n    -- (True EMERGENCY TRANSFER \226\128\148 create_group_emergency_transfer_task, keysite.c:1087/1213 \226\128\148 moves only\n    -- AIRBORNE, still-old-side aircraft in their landing phase OUT to a friendly keysite; the port already\n    -- models that as in-flight sorties RTB'ing and recycling to the nearest friendly base via\n    -- supply.make_land_handler, so no ledger action is owed for it here.)\n    do\n        local led = S.base_ledger and S.base_ledger[bname]\n        local n_captured = 0\n        if led then for _, c in pairs(led) do n_captured = n_captured + (c or 0) end end\n        cs.dbg(\"capture\", \"%s captures %d parked aircraft with %s (ledger kept under new owner; keysite.c:1375-1393, command_line_capture_aircraft=TRUE)\",\n            cs.SIDE_NAME[new_side], n_captured, bname)\n    end\n\n    -- Keysite-loss task termination (EECH destroy_keysite, keysite.c:1229-1260, invoked from\n    -- capture_keysite:1423). On capture EECH terminates ALL tasks whose objective is this keysite,\n    -- REGARDLESS of side: LIST_TYPE_UNASSIGNED_TASK children \226\134\146 TASK_TERMINATED_ABORTED (:1233-1242)\n    -- and LIST_TYPE_TASK_DEPENDENT children \226\134\146 TASK_COMPLETED/TASK_INCOMPLETE (:1248-1260). That kills\n    -- BOTH the new owner's (former attacker's) offensive strikes/OCA/TI/recon AND the old owner's\n    -- defensive CAP against a base it no longer holds \226\128\148 neither makes sense after the flip.\n    -- PROXY: in-flight DCS groups are NOT despawned (too aggressive for the port's event model). We\n    -- clear the registry entry so NO follow-on reaction fires (LAND/DEAD read cs.get_task \226\134\146 nil \226\134\146 no\n    -- completion chain) and let the group RTB naturally; UNASSIGNED board records are FAILED (they\n    -- consumed no ledger yet, so no refund is owed).\n    do\n        local n_term = 0\n        local doomed = {}\n        for gname, t in pairs(S.active_tasks or {}) do\n            if t.target_base == bname then doomed[#doomed + 1] = gname end\n        end\n        for _, gname in ipairs(doomed) do cs.clear_task(gname); n_term = n_term + 1 end\n        if S.board_tasks then\n            for _, t in ipairs(S.board_tasks) do\n                if t.state == \"UNASSIGNED\" and t.target and t.target.base == bname then\n                    t.state = \"FAILED\"; n_term = n_term + 1\n                end\n            end\n        end\n        if n_term > 0 then\n            cs.dbg(\"capture\", \"%s task-termination on capture of %s: %d task(s) cleared (keysite.c:1229-1260)\",\n                cs.SIDE_NAME[new_side], bname, n_term)\n        end\n    end\n\n    reseed_regen_on_capture(old_side, new_side, bname, log_fn)\n    cs.recalc_strength()\n\n    log_fn(string.format(\"CAPTURE: %s seizes %s from %s (health\226\134\146%.0f%%, +%d heli/+%d fw reseed)\",\n        cs.SIDE_NAME[new_side] or \"?\", bname, cs.SIDE_NAME[old_side] or \"NEUTRAL\",\n        (S.base_health[bname] or 0) * 100, CAPTURE_REGEN_HELI, CAPTURE_REGEN_FW))\n    cs.dbg(\"capture\", \"OWNER TRANSITION: %s %s -> %s (health->%.0f%%, kind=%s)\",\n        bname, cs.SIDE_NAME[old_side] or \"NEUTRAL\", cs.SIDE_NAME[new_side] or \"?\",\n        (S.base_health[bname] or 0) * 100, tostring(S.base_kind and S.base_kind[bname]))\n    trigger.action.outText(string.format(\"%s captured by %s!\", bname, cs.SIDE_NAME[new_side]), 20)\n\n    -- Frontline recomputes on ownership change (EECH computes it at load only because its\n    -- ownership map is static; capture is the port's equivalent trigger \226\128\148 see frontline.lua).\n    local ok_f, frontl = pcall(require, \"frontline\")\n    if ok_f and frontl and frontl.recompute then pcall(frontl.recompute, log_fn) end\n\n    -- The captor garrisons the seized keysite with its own air defence (the old defenders were\n    -- ground down by the strikes that neutralised it).\n    local ok_d, bd = pcall(require, \"base_defenses\")\n    if ok_d and bd and bd.regarrison then pcall(bd.regarrison, bname, new_side, log_fn) end\n\n    -- eech F29: keysite capture re-checks campaign objectives on BOTH forces (event-driven).\n    local ok_w, wc = pcall(require, \"win_condition\")\n    if ok_w and wc and wc.check_win then pcall(wc.check_win, log_fn) end\n\n    -- Persistence (WAVE 2): a capture is a durable campaign event \226\128\148 checkpoint immediately so a restart\n    -- right after a base flips restores the new ownership (EECH pack_session is repacked on such events).\n    -- No-op unless persistence enabled; pcall-guarded so a save failure can never abort the capture.\n    local ok_p, persist = pcall(require, \"persist\")\n    if ok_p and persist and persist.save then pcall(persist.save, log_fn) end\n    return true\nend\n\n-- Ground-column capture poll: an enemy ground group parked at a keysite whose efficiency has\n-- fallen below the minimum attempts a probabilistic capture (eech mb_msgs.c:2260-2325 analogue\n-- for the port's advancing armour; the airmobile troop-insertion path lives in troop.lua).\nfunction M.try_capture(log_fn)\n    log_fn = log_fn or function() end\n    local n_below_min, n_attempts = 0, 0\n    for bname, owner in pairs(S.base_owner) do\n        -- Offer gate: capture only offered when efficiency < minimum (eech highlevl.c:1732).\n        if M.efficiency(bname) < cs.MINIMUM_EFFICIENCY then\n            n_below_min = n_below_min + 1\n            local bpos = S.base_pos[bname]\n            if bpos then\n                -- Any enemy ground group within CAPTURE_RANGE of the keysite may capture it.\n                -- Scans the whole standing frontline registry (not a single column).\n                for side, groups in pairs(S.ground_groups or {}) do\n                    if side ~= owner then\n                        for _, rec in pairs(groups) do\n                            local col = rec.grp\n                            if cs.group_is_alive(col) then\n                                local units = col:getUnits()\n                                if units and units[1] and units[1]:isExist() then\n                                    local upos = units[1]:getPosition().p\n                                    if cs.dist2d(upos.x, upos.z, bpos.x, bpos.z) < CAPTURE_RANGE then\n                                        -- member_count = column strength; losses proxied 0\n                                        -- (port does not track per-column casualties en route).\n                                        n_attempts = n_attempts + 1\n                                        if M.capture_roll(bname, #units, 0) then\n                                            M.do_capture(bname, side, log_fn)\n                                        else\n                                            log_fn(string.format(\n                                                \"capture repelled at %s (defence held)\", bname))\n                                        end\n                                        break\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    if n_below_min > 0 then\n        cs.dbg(\"capture\", \"try_capture tick: %d bases below min-efficiency, %d ground-column capture attempts\",\n            n_below_min, n_attempts)\n    end\nend\n\nreturn M\n"
__modules["keysite_repair"] = "-- keysite_repair.lua\n-- EECH source: aphavoc/source/entity/special/keysite/ks_updt.c\n--   update_server() \226\128\148 two sub-loops at different periods:\n--     Loop A (every KEYSITE_UPDATE_SLEEP_TIMER = 60 s):\n--       ammo_supply_level += AMMO_USAGE_ACCELERATOR(1.0) \195\151 default_supply_usage.ammo_supply_level\n--       fuel_supply_level += FUEL_USAGE_ACCELERATOR(1.0) \195\151 default_supply_usage.fuel_supply_level\n--       bound both to [KEYSITE_MINIMUM_AMMO_SUPPLY_LEVEL=10.0, 100.0]\n--     Loop B (every 1.0 * ONE_MINUTE = 60 s, offset by task_timer):\n--       if keysite_strength < keysite_maximum_strength AND repairable:\n--         create_repair_task(side, pos, en, priority=10.0) if not already tasked\n--   KEYSITE_STATE_REPAIRING loop (continuous, delta-time driven):\n--     repair_timer -= delta_time; if <= 0: repair_client_server_entity_keysite()\n--     (repairs one building per timer expiry; when all repaired \226\134\146 KEYSITE_STATE_USABLE)\n--\n-- EECH source: aphavoc/source/entity/system/en_types/en_suply.h\n--   KEYSITE_MINIMUM_AMMO_SUPPLY_LEVEL = 10.0  (percentage, 0\226\128\147100 scale)\n--   KEYSITE_MINIMUM_FUEL_SUPPLY_LEVEL = 10.0\n--   AMMO_USAGE_ACCELERATOR            = 1.0\n--   FUEL_USAGE_ACCELERATOR            = 1.0\n--\n-- EECH source: aphavoc/source/entity/special/keysite/keysite.h\n--   KEYSITE_UPDATE_SLEEP_TIMER = 1.0 * ONE_MINUTE = 60 s\n--\n-- DCS proxy notes:\n-- \226\128\162 Repair in EECH requires a dedicated repair unit task.  We proxy this as automatic\n--   health increment when base is damaged but not neutralised.  Rate is set to match a\n--   typical EECH repair task completing in ~20 minutes (REPAIR_RATE = 0.05/min).\n-- \226\128\162 Supply consumption: default_supply_usage is keysite-type-specific in EECH data.\n--   We use a single proxy rate (AMMO_USAGE_PER_MIN = -0.2 \226\134\146 0.2% per 60 s), giving\n--   full drain from 100% to 10% in 450 minutes \226\128\148 close to EECH airbase drain rates.\n-- \226\128\162 S.base_ammo[name] uses 0\226\128\147100 scale to match EECH's ammo_supply_level.\n\nlocal cs     = require(\"campaign_state\")\nlocal supply = require(\"supply\")\nlocal inst   = require(\"installations\")\nlocal sf     = require(\"supply_flight\")\nlocal S      = cs.S\nlocal M      = {}\n\n-- \226\148\128\226\148\128 EECH constants (exact mirror) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal KEYSITE_UPDATE_SLEEP_TIMER      = 60        -- s; keysite.h: 1.0 * ONE_MINUTE\nlocal KEYSITE_MINIMUM_AMMO_SUPPLY     = 10.0      -- %; en_suply.h: KEYSITE_MINIMUM_AMMO_SUPPLY_LEVEL\nlocal KEYSITE_MINIMUM_FUEL_SUPPLY     = 10.0      -- %; en_suply.h: KEYSITE_MINIMUM_FUEL_SUPPLY_LEVEL\nlocal AMMO_USAGE_ACCELERATOR          = 1.0       -- en_suply.h\nlocal FUEL_USAGE_ACCELERATOR          = 1.0       -- en_suply.h\nlocal KEYSITE_SUPPLY_REQUEST_THRESHOLD = 75.0     -- %; en_suply.h:87 / keysite.c:469 \226\128\148 below \226\134\146 request crate\n\n-- \226\148\128\226\148\128 Consumer keysite drain (per-keysite-type default_supply_usage, ks_dbase.c) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- default_supply_usage is keysite-TYPE-specific in the EECH keysite_database, NOT one flat rate:\n--   AIRBASE : ammo -0.2 %/min, fuel -0.4 %/min   (eech ks_dbase.c:98-99, airbase row)\n--   FARP    : ammo -0.05 %/min, fuel -0.03 %/min (eech ks_dbase.c:239-240, FARP row)\n-- A FARP is a SMALL forward base with a far lighter supply appetite than a full airbase, so it drains\n-- ~4-13\195\151 slower. The port branches on S.base_kind so FARPs/FOBs drain at the FARP rate and full\n-- airbases at the airbase rate (03-F5). Every base drains every 60 s tick; restock no longer comes\n-- from being \"rear\" but from the LOGISTICS CHAIN (KEYSITE-F6/F7/F8): when a base falls below\n-- KEYSITE_SUPPLY_REQUEST_THRESHOLD it requests a crate, and a PHYSICAL supply flight (supply_flight.lua\n-- \226\128\148 a transport that flies the crate from the nearest producer to the consumer) restocks it to 100 on\n-- arrival \226\128\148 but ONLY if the owner has a live producer (factory/refinery) with a crate available, AND\n-- the transport survives the trip. Kill the enemy's factories (or shoot down its transports) and its\n-- bases drain to the floor (10) and can no longer rearm/refuel/repair.\nlocal AIRBASE_AMMO_USAGE_PER_TICK = -0.2    -- eech ks_dbase.c:98  airbase ammo default_supply_usage\nlocal AIRBASE_FUEL_USAGE_PER_TICK = -0.4    -- eech ks_dbase.c:99  airbase fuel default_supply_usage\nlocal FARP_AMMO_USAGE_PER_TICK    = -0.05   -- eech ks_dbase.c:239 FARP ammo default_supply_usage\nlocal FARP_FUEL_USAGE_PER_TICK    = -0.03   -- eech ks_dbase.c:240 FARP fuel default_supply_usage\n\n-- Proxy repair rate \226\128\148 realigned to EECH's ACTUAL cadence (keysite.c:1581 repair_client_server_entity_\n-- keysite + ks_updt.c update_server): a repairing keysite restores exactly ONE building every 10 min\n-- (repair_timer = 10.0 * ONE_MINUTE; regen buildings 20 min), building-by-building until usable. So a\n-- multi-building AIRBASE takes ~10 min \195\151 building-count (50-100+ min) for a FULL repair \226\128\148 NOT the 20 min\n-- the old proxy assumed. At the old 0.05/min (1/20), bases recovered from strikes faster than the\n-- spread-out strike tasker could re-neutralise them \226\134\146 they never dropped below MINIMUM_EFFICIENCY (0.3)\n-- \226\134\146 NO base captures \226\134\146 permanent stalemate. Modelling ~10 building-equivalents at 10 min each:\nlocal REPAIR_RATE_PER_TICK = 1.0 / 100.0  -- \226\137\1361 building (0.1 strength) per 10 min \226\134\146 full in ~100 min\n\n-- STRIKE_SUPPRESS_TIME \226\128\148 PROXY for EECH's repair-TASK creation + delivery delay, NOT a standalone\n-- EECH timer. EECH repair has NO supply gate and NO suppression timer: when keysite_strength < max\n-- the update loop CREATES a repair task (ks_updt.c:200-217, create_repair_task priority 10) which\n-- must be ASSIGNED and physically DELIVERED before the keysite enters KEYSITE_STATE_REPAIRING and the\n-- 1-building/10-min heal begins (ks_updt.c:169-222; keysite.c:1581). That create\226\134\146assign\226\134\146deliver\n-- latency is the real brake on recovery under sustained attack. The port has no repair-flight entity,\n-- so it proxies that latency as a fixed post-strike hold: a keysite struck within the last\n-- STRIKE_SUPPRESS_TIME does not run its repair increment. 480 s > the 7.5-min (450 s) keysite-strike\n-- period, so a base under SUSTAINED strike pressure stays suppressed (matching EECH, where a keysite\n-- that keeps taking hits never gets its repair task delivered).\nlocal STRIKE_SUPPRESS_TIME = 480.0        -- s: repair-task creation/delivery-delay proxy (ks_updt.c:169-222)\n\n-- \226\148\128\226\148\128 S.base_ammo and S.base_fuel \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- 0\226\128\147100 percentage, mirroring EECH ammo_supply_level / fuel_supply_level.\n\nfunction M.init(log_fn)\n    log_fn = log_fn or function() end\n    S.base_ammo       = S.base_ammo or {}\n    S.base_fuel       = S.base_fuel or {}\n    S.base_efficiency = S.base_efficiency or {}\n    for name in pairs(S.base_owner) do\n        S.base_ammo[name]       = S.base_ammo[name] or 100.0\n        S.base_fuel[name]       = S.base_fuel[name] or 100.0\n        S.base_efficiency[name] = 1.0   -- full efficiency at mission start\n    end\n    log_fn(string.format(\n        \"keysite_repair: ammo/fuel tables initialised (min_ammo=%.0f%%, min_fuel=%.0f%%)\",\n        KEYSITE_MINIMUM_AMMO_SUPPLY, KEYSITE_MINIMUM_FUEL_SUPPLY))\n    cs.dbg(\"repair\", \"init: ammo/fuel tables seeded at 100%% for all owned bases\")\nend\n\nlocal SIDES = { coalition.side.BLUE, coalition.side.RED }\n\nlocal function bound(v, lo)\n    if v < lo then return lo elseif v > 100.0 then return 100.0 else return v end\nend\n\n-- \226\148\128\226\148\128 update_server proxy \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors EECH ks_updt.c update_server()/supply tick, running every KEYSITE_UPDATE_SLEEP_TIMER.\n-- One tick = 60 s = 1 minute, so per-minute rates apply directly.\nlocal function tick(log_fn)\n    S.base_ammo = S.base_ammo or {}\n    S.base_fuel = S.base_fuel or {}\n    S.base_efficiency = S.base_efficiency or {}\n\n    -- \226\148\128\226\148\128 1. Production tick (KEYSITE-F5): credit each side's crate accumulator \226\148\128\226\148\128\n    -- from its ALIVE producer keysites (installations.production_rates). Zero once its factories\n    -- are gone \226\134\146 no deliveries, no reserve replacement.\n    for _, side in ipairs(SIDES) do\n        local ok, a, f = pcall(inst.production_rates, side)\n        if ok then supply.credit_production(side, a or 0, f or 0, 1) end\n    end\n\n    -- \226\148\128\226\148\128 2. Consumer drain + collect restock requests (KEYSITE-F5/F6) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    local need = {\n        [coalition.side.BLUE] = { ammo = {}, fuel = {} },\n        [coalition.side.RED]  = { ammo = {}, fuel = {} },\n    }\n    for name, owner in pairs(S.base_owner) do\n        if owner == coalition.side.BLUE or owner == coalition.side.RED then\n            -- Branch the drain rate on keysite TYPE (ks_dbase.c per-row default_supply_usage): FARP/FOB\n            -- forward bases drain at the light FARP rate (:239-240), full airbases at the airbase rate\n            -- (:98-99). base_kind mirrors EECH's keysite sub_type (air_force_capacity SMALL vs LARGE).\n            local kind = S.base_kind and S.base_kind[name]\n            local is_farp = (kind == \"farp\" or kind == \"fob\")\n            local ammo_rate = is_farp and FARP_AMMO_USAGE_PER_TICK or AIRBASE_AMMO_USAGE_PER_TICK\n            local fuel_rate = is_farp and FARP_FUEL_USAGE_PER_TICK or AIRBASE_FUEL_USAGE_PER_TICK\n            S.base_ammo[name] = bound((S.base_ammo[name] or 100.0)\n                + AMMO_USAGE_ACCELERATOR * ammo_rate, KEYSITE_MINIMUM_AMMO_SUPPLY)\n            S.base_fuel[name] = bound((S.base_fuel[name] or 100.0)\n                + FUEL_USAGE_ACCELERATOR * fuel_rate, KEYSITE_MINIMUM_FUEL_SUPPLY)\n            -- request a crate when at/below threshold (KEYSITE-F6: cargo_level <= 75 AND consumer)\n            if S.base_ammo[name] <= KEYSITE_SUPPLY_REQUEST_THRESHOLD then\n                need[owner].ammo[#need[owner].ammo + 1] = name\n            end\n            if S.base_fuel[name] <= KEYSITE_SUPPLY_REQUEST_THRESHOLD then\n                need[owner].fuel[#need[owner].fuel + 1] = name\n            end\n        end\n    end\n\n    -- \226\148\128\226\148\128 3. Supply requests (KEYSITE-F6/F7): neediest base first \226\134\146 PHYSICAL supply flight \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- Below-threshold keysites no longer teleport a crate: each raises a FORCE_LOW_ON_SUPPLIES request\n    -- (keysite.c:469-494) that supply_flight.request turns into a board TASK_SUPPLY \226\128\148 a transport that\n    -- must physically fly the crate from the nearest producer and reach the consumer before it counts\n    -- (fc_msgs.c:672-870 \226\134\146 taskgen.c:1638 create_supply_task). request() dedups per consumer per\n    -- commodity, aborts with no live producer / no banked crate, and EARMARKS the crate so the reserve\n    -- conversion below can't repurpose it while the flight is queued. The actual restock-to-100 happens\n    -- on the flight's DROP_OFF fly-over (supply_flight.check_arrivals), not here.\n    for _, side in ipairs(SIDES) do\n        for _, commodity in ipairs({ \"ammo\", \"fuel\" }) do\n            local tbl  = (commodity == \"ammo\") and S.base_ammo or S.base_fuel\n            local list = need[side][commodity]\n            table.sort(list, function(x, y) return (tbl[x] or 0) < (tbl[y] or 0) end)   -- neediest first\n            for _, bname in ipairs(list) do\n                sf.request(side, bname, commodity, log_fn)\n            end\n        end\n    end\n\n    -- \226\148\128\226\148\128 3b. Reconcile crate earmarks to the live queued supply tasks \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    -- set_earmark = number of still-QUEUED supply board tasks per side/commodity (spawned/expired ones\n    -- drop out), so convert_reserves below protects exactly the crates committed to pending flights and\n    -- never leaks an earmark for a task that vanished.\n    for _, side in ipairs(SIDES) do\n        for _, commodity in ipairs({ \"ammo\", \"fuel\" }) do\n            supply.set_earmark(side, commodity, sf.count_queued(side, commodity))\n        end\n    end\n\n    -- \226\148\128\226\148\128 4. Reserve replacement (force.c replace_into_force_info): SURPLUS crates \226\134\146 reserve hardware\n    -- (only crates beyond the earmarks set above \226\128\148 delivery has priority over stockpiling reserves).\n    for _, side in ipairs(SIDES) do\n        supply.convert_reserves(side, log_fn)\n    end\n\n    -- \226\148\128\226\148\128 5. Repair + efficiency, per keysite \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n    local n_repaired, n_suppressed, n_full_or_dead = 0, 0, 0\n    for name, owner in pairs(S.base_owner) do\n        if owner == coalition.side.BLUE or owner == coalition.side.RED then\n            -- Loop B repair trigger (ks_updt.c:169-222): DCS proxy directly increments health when the\n            -- keysite is USABLE (health > neutralised) and not currently suppressed. EECH repair has NO\n            -- supply gate \226\128\148 repair is purely the repair-TASK delivery + the 1-building/10-min timer; the\n            -- 50%-supply gate the port used to apply was an INVENTION (uncited \226\134\146 latent bug) and is\n            -- removed (03-F10). The only brake is STRIKE_SUPPRESS_TIME (the repair-task-delivery-delay\n            -- proxy above): a keysite struck within that window does not run its repair increment.\n            local h = S.base_health[name] or 1.0\n            local last = S.base_last_strike and S.base_last_strike[name]\n            local suppressed = last and (timer.getTime() - last) < STRIKE_SUPPRESS_TIME\n            if h < 1.0 and h >= cs.HEALTH_NEUTRALISED and not suppressed then   -- USABLE inclusive (keysite.c:827-830)\n                S.base_health[name] = math.min(1.0, h + REPAIR_RATE_PER_TICK)\n                n_repaired = n_repaired + 1\n            elseif h < 1.0 and h >= cs.HEALTH_NEUTRALISED and suppressed then\n                n_suppressed = n_suppressed + 1\n            else\n                n_full_or_dead = n_full_or_dead + 1\n            end\n\n            -- FLOAT_TYPE_EFFICIENCY (ks_float.c:260-275) = keysite_strength / keysite_maximum_strength;\n            -- supply is NOT part of efficiency (KEYSITE-F3). base_health IS strength/max, so eff==health.\n            S.base_efficiency[name] = S.base_health[name] or 1.0\n        end\n    end\n    cs.dbg(\"repair\", \"repair tick: %d repaired, %d suppressed (recent strike / repair-task-delay proxy), %d full/neutralised-or-dead\",\n        n_repaired, n_suppressed, n_full_or_dead)\nend\n\n-- \226\148\128\226\148\128 Scheduler \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- mirrors overload_keysite_update_functions \226\134\146 update_server, called every\n-- KEYSITE_UPDATE_SLEEP_TIMER (60 s).\nfunction M.schedule_repair(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"repair\", \"scheduler REGISTERED offset=%.0fs period=%.0fs\", KEYSITE_UPDATE_SLEEP_TIMER, KEYSITE_UPDATE_SLEEP_TIMER)\n    timer.scheduleFunction(function(_, t)\n        -- INFRASTRUCTURE: keysite supply/repair tick keeps running post-victory (EECH fc_msgs.c:163). Cluster E.\n        if _DMT_GEN ~= my_gen then return nil end\n        local ok, err = pcall(tick, log_fn)\n        if not ok then log_fn(\"keysite_repair tick error: \" .. tostring(err)) end\n        return t + KEYSITE_UPDATE_SLEEP_TIMER\n    end, nil, timer.getTime() + KEYSITE_UPDATE_SLEEP_TIMER)\nend\n\nreturn M\n"
__modules["map_overlay"] = "-- map_overlay.lua\n-- F-10 map mission tasking overlay.\n-- Mirrors EECH's campaign map briefing screen (briefing.c / campaign_map.c):\n--   - Base ownership labels with health bars\n--   - Active strike task arrows (attacker \226\134\146 target)\n--   - Ground column position markers\n--   - Frontline indicator (midpoint between nearest opposing bases)\n--\n-- DCS API used:\n--   trigger.action.markToAll(id, text, pos, readonly, message)\n--   trigger.action.markToCoalition(id, text, pos, coal, readonly, message)\n--   trigger.action.removeMark(id)\n--   trigger.action.lineToAll(coal, id, startPos, endPos, r, g, b, a, lineType)\n--   trigger.action.textToAll(coal, id, pos, r, g, b, a, fillR, fillG, fillB, fillA,\n--                            fontSize, readonly, text)\n--   trigger.action.circleToAll(coal, id, pos, radius, r, g, b, a, fillR, fillG, fillB, fillA, lineType)\n\nlocal cs = require(\"campaign_state\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- \226\148\128\226\148\128 Mark ID allocation \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Base labels: 10000 + sequential index\n-- Task arrows: 20000 + task_id\n-- Column marks: 30000 + side\n-- Frontline:    40000\n\nlocal BASE_MARK_START = 60000   -- moved out of the 10000 range: stale overlay schedulers from earlier\n                                -- re-injects removeMark the old 10000 base range every tick and clobber\n                                -- new base labels. 60000+ dodges them. (A fresh mission start also\n                                -- clears the stale timers \226\128\148 the definitive fix.)\nlocal TASK_MARK_START = 20000\nlocal COL_MARK_BLUE   = 30001\nlocal COL_MARK_RED    = 30002\nlocal FRONT_MARK      = 40000\n\nlocal UPDATE_PERIOD   = 30  -- seconds between overlay refreshes\n\n-- Map from base name \226\134\146 mark ID (assigned on first draw)\nlocal base_mark_ids   = {}\nlocal base_last_label = {}   -- base name \226\134\146 last label issued (STABLE marks: update only on change)\nlocal next_base_id    = BASE_MARK_START\n\n-- Active task arrows: task_id \226\134\146 mark_id pair\nlocal task_mark_ids = {}\nlocal next_task_mark = TASK_MARK_START\n\n-- \226\148\128\226\148\128 Helpers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nlocal function world_to_mark_pos(wx, wz)\n    -- trigger.action marks use {x=north, y=altitude, z=east}\n    return { x = wx, y = 0, z = wz }\nend\n\nlocal function health_bar(h)\n    -- 5-segment ASCII bar like EECH's keysite strength display\n    local filled = math.floor(h * 5 + 0.5)\n    return string.rep(\"|\", filled) .. string.rep(\".\", 5 - filled)\nend\n\n-- \226\148\128\226\148\128 Base ownership labels \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- One mark per airbase; updated in-place (remove + re-add).\n-- EECH analogue: draw_keysite_icon() in campaign_map.c\n\nlocal function update_base_marks()\n    for name, owner in pairs(S.base_owner) do\n        local pos = S.base_pos[name]\n        if pos then\n            local mid = world_to_mark_pos(pos.x, pos.z)\n            local h   = S.base_health[name] or 1.0\n            -- Idle inventory is a PER-BASE ledger now (Cluster 4); show THIS base's parked aircraft.\n            local pool = S.base_ledger and S.base_ledger[name]\n\n            local side_tag = (owner == coalition.side.BLUE) and \"BLUE\" or \"RED\"\n            local kind  = (S.base_kind and S.base_kind[name]) or \"airbase\"\n            local ktag  = (kind == \"airbase\" and \"AIRBASE (fixed-wing)\")\n                       or (kind == \"fob\" and \"FOB (heli)\")\n                       or (kind == \"farp\" and \"FARP (heli)\") or \"BASE\"\n            -- Item 1: a dormant FARP (sector not yet friendly) is flagged so the player sees it is not\n            -- yet participating (it activates as the front reaches it).\n            if kind == \"farp\" and not cs.base_is_active(name) then ktag = ktag .. \" \226\128\148 DORMANT\" end\n            -- FOB/FARP are heli-only \226\134\146 show only the heli count; airbases show the fixed-wing pools too.\n            local str_txt = \"?\"\n            if pool then\n                if kind == \"airbase\" then\n                    str_txt = string.format(\"idle F%d E%d H%d\", pool.striker or 0, pool.escort or 0, pool.heli or 0)\n                else\n                    str_txt = string.format(\"idle H%d T%d\", pool.heli or 0, pool.transport or 0)\n                end\n            end\n            local label = string.format(\"%s  [%s]\\n%s\\n%s %.0f%%\\n%s\",\n                name, side_tag, ktag, health_bar(h), h * 100, str_txt)\n\n            -- Allocate a stable ID for this base\n            if not base_mark_ids[name] then\n                base_mark_ids[name] = next_base_id\n                next_base_id = next_base_id + 1\n            end\n            local mid_id = base_mark_ids[name]\n\n            -- STABLE marks: only re-issue when the label actually changes. The previous code did\n            -- removeMark+markToAll EVERY tick for every base, which made the labels flicker/vanish on\n            -- the client (the remove and add race). Updating on change keeps them rendered.\n            if base_last_label[name] ~= label then\n                trigger.action.removeMark(mid_id)\n                trigger.action.markToAll(mid_id, label, mid, true, \"\")  -- shown to all (shared campaign map)\n                base_last_label[name] = label\n            end\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 Active task arrows (Item 4 \226\128\148 RE-ENABLED with a reliable lifecycle) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH analogue: draw_task_arrow() highlighting active offensive sorties on the campaign map.\n--\n-- The previous re-enable LEAKED (~170 orphaned line-marks) because remove_task_arrow was not reliably\n-- called. This version keys the arrow by the sortie's DCS GROUP NAME (the same key the task registry\n-- uses) and reaps it through TWO redundant paths so an arrow can never outlive its group:\n--   (1) PRIMARY \226\128\148 cs.clear_task(gname) is the SINGLE chokepoint every registered task-end funnels\n--       through (reaction LAND/DEAD, troop capture, keysite capture-termination, supply RTB). It\n--       fires cs.task_end_hook = M.remove_task_arrow (wired in schedule_overlay), so a registered\n--       sortie's arrow is removed the instant its task clears.\n--   (2) BACKSTOP \226\128\148 gc_task_arrows() (run every refresh) removes any arrow whose group no longer\n--       exists. This covers the non-registered arrow sources (CAS/BAI/SEAD run, heli sections) that\n--       never enter the task registry, so EVERY arrow is bounded regardless of the clear_task path.\n-- Mark ids are allocated in a bounded band [TASK_MARK_START, TASK_MARK_END] with wrap; reset.lua\n-- clears 20000..20400 (covers the band) on every re-inject.\nlocal TASK_MARK_END = 20399   -- inclusive band top (reset.lua clears 20000..20400)\n\nlocal function alloc_task_mark()\n    local id = next_task_mark\n    next_task_mark = next_task_mark + 1\n    if next_task_mark > TASK_MARK_END then next_task_mark = TASK_MARK_START end\n    return id\nend\n\n-- add_task_arrow(gname, from_pos, to_pos, side): draw a side-coloured line from launch \226\134\146 target.\n-- `gname` MUST be the sortie's DCS group name (so the GC backstop can test its existence). Idempotent\n-- per key (a re-registered name replaces its old arrow).\nfunction M.add_task_arrow(gname, from_pos, to_pos, side)\n    if not gname or not from_pos or not to_pos then return end\n    M.remove_task_arrow(gname)\n    local id = alloc_task_mark()\n    task_mark_ids[gname] = id\n    local sp = world_to_mark_pos(from_pos.x, from_pos.z)\n    local ep = world_to_mark_pos(to_pos.x, to_pos.z)\n    -- BLUE arrow blue, RED arrow red; lineType 1 = solid.\n    local r = (side == coalition.side.BLUE) and 0.2 or 0.9\n    local g = 0.3\n    local b = (side == coalition.side.BLUE) and 0.9 or 0.2\n    pcall(trigger.action.lineToAll, -1, id, sp, ep, r, g, b, 0.6, 1)\n    return id\nend\n\nfunction M.remove_task_arrow(gname)\n    local mid = task_mark_ids[gname]\n    if mid then\n        pcall(trigger.action.removeMark, mid)\n        task_mark_ids[gname] = nil\n    end\nend\n\n-- GC backstop: reap any arrow whose group is gone (covers arrows never routed through clear_task).\nlocal function gc_task_arrows()\n    for gname, mid in pairs(task_mark_ids) do\n        local ok, grp = pcall(Group.getByName, gname)\n        local alive = ok and grp ~= nil and grp:isExist()\n        if not alive then\n            pcall(trigger.action.removeMark, mid)\n            task_mark_ids[gname] = nil\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 Ground column markers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nlocal col_mark_prev = {}  -- [side] = highest mark index used last refresh (to clear the tail)\n\nlocal function update_column_marks()\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        local base_id = (side == coalition.side.BLUE) and COL_MARK_BLUE or COL_MARK_RED\n        -- Clear the full band drawn last time, then redraw current groups (prevents orphaned marks\n        -- when a side loses groups; pairs() order is nondeterministic so we clear rather than diff).\n        for k = 0, (col_mark_prev[side] or 0) do trigger.action.removeMark(base_id * 100 + k) end\n        local i = 0\n        for _, rec in pairs((S.ground_groups and S.ground_groups[side]) or {}) do\n            if cs.group_is_alive(rec.grp) then\n                local u = rec.grp:getUnit(1)\n                if u and u:isExist() then\n                    local p = u:getPosition().p\n                    trigger.action.markToAll(base_id * 100 + i,\n                        string.format(\"[%s] Ground group \226\134\146 %s\", cs.SIDE_NAME[side] or \"?\",\n                            rec.target_base or \"?\"),\n                        { x = p.x, y = 0, z = p.z }, true, \"\")\n                    i = i + 1\n                end\n            end\n        end\n        col_mark_prev[side] = math.max(i - 1, col_mark_prev[side] or 0)\n    end\nend\n\n-- \226\148\128\226\148\128 Frontline indicator \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Draws a line connecting the midpoints of nearest BLUE\226\128\147RED base pairs.\n-- EECH analogue: draw_frontline() in ai_fline.c visual output.\n\nlocal function update_frontline()\n    trigger.action.removeMark(FRONT_MARK)\n\n    -- Find the single closest BLUE\226\128\147RED base pair to approximate the front\n    local min_d, bx, bz, rx, rz = math.huge, 0, 0, 0, 0\n    local found = false\n    for bname, bowner in pairs(S.base_owner) do\n        if bowner == coalition.side.BLUE then\n            local bp = S.base_pos[bname]\n            if bp then\n                for rname, rowner in pairs(S.base_owner) do\n                    if rowner == coalition.side.RED then\n                        local rp = S.base_pos[rname]\n                        if rp then\n                            local d = cs.dist2d(bp.x, bp.z, rp.x, rp.z)\n                            if d < min_d then\n                                min_d = d\n                                bx, bz = bp.x, bp.z\n                                rx, rz = rp.x, rp.z\n                                found = true\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n\n    if found then\n        local mx = (bx + rx) * 0.5\n        local mz = (bz + rz) * 0.5\n        trigger.action.markToAll(FRONT_MARK,\n            string.format(\"--- FRONTLINE ---\\nBLUE str=%d RED str=%d\",\n                S.strength[coalition.side.BLUE] or 0,\n                S.strength[coalition.side.RED]  or 0),\n            { x = mx, y = 0, z = mz }, true, \"\")\n    end\nend\n\n-- \226\148\128\226\148\128 One-time cleanup of leaked task-arrow marks (arrows are now disabled) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal cleaned_leaks = false\nlocal function cleanup_leaked_marks()\n    if cleaned_leaks then return end\n    cleaned_leaks = true\n    local ok, panels = pcall(world.getMarkPanels)\n    if ok and panels then\n        for _, p in ipairs(panels) do\n            local id = p.idx or -1\n            if id >= TASK_MARK_START and id < COL_MARK_BLUE then  -- 20000..30000 (old task arrows)\n                pcall(trigger.action.removeMark, id)\n            end\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 Installation markers: strategic infrastructure (producers = factories/refineries) \226\148\128\226\148\128\nlocal INST_MARK_START = 50000\nlocal inst_mark_ids   = {}\nlocal inst_last_label = {}\nlocal next_inst_id    = INST_MARK_START\nlocal function update_installation_marks()\n    for kname, rec in pairs(S.keysites or {}) do\n        -- Mark EVERY non-airbase keysite (factory/refinery/depot/fuel/radar/command) with its type,\n        -- owner and health \226\128\148 the full infrastructure picture (producers flagged in the label).\n        if rec.pos then\n            -- Zone-registered keysites carry their own side (rec.side); auto keysites follow home base.\n            local owner    = rec.side or (rec.home_base and S.base_owner[rec.home_base])\n            local side_tag = (owner == coalition.side.BLUE) and \"BLUE\" or \"RED\"\n            local h        = rec.health or 1.0\n            if not inst_mark_ids[kname] then inst_mark_ids[kname] = next_inst_id; next_inst_id = next_inst_id + 1 end\n            local id    = inst_mark_ids[kname]\n            -- PENDING (empty circle: author hasn't placed statics) shows a distinct placeholder, NOT a\n            -- \"0%\" neutralised reading \226\128\148 it's excluded from the campaign until filled.\n            local label\n            if rec.pending then\n                label = string.format(\"%s [%s] \226\128\148 empty (place statics)\", rec.label or rec.kind, side_tag)\n            elseif (h > 0.1) or (rec.assets ~= nil) then\n                -- Registered asset count (alive/total) surfaces what the author placed, e.g. \"(3/5)\".\n                local count_txt = rec.total and string.format(\" (%d/%d)\", rec.alive or 0, rec.total) or \"\"\n                -- Under-populated keysite \226\134\146 warn the author to place more targets in the circle.\n                local warn = rec.low_targets and \"\226\154\160 LOW TARGETS \" or \"\"\n                label = string.format(\"%s%s [%s] %.0f%%%s\", warn, rec.label or rec.kind, side_tag, h * 100, count_txt)\n            end\n            if inst_last_label[kname] ~= label then\n                trigger.action.removeMark(id)\n                if label then trigger.action.markToAll(id, label, world_to_mark_pos(rec.pos.x, rec.pos.z), true, \"\") end\n                inst_last_label[kname] = label\n            end\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 Per-destructible asset indicators \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- A small map marker on EACH registered destructible (every placed static + every resource-scenery\n-- object) so the author can see the individual targets, not just the aggregate keysite label. Placed\n-- once and left in place (statics/scenery don't move); removed when that asset is destroyed, so the\n-- indicators visibly thin out as a keysite is bombed down.\nlocal ASSET_MARK_START = 70000\nlocal asset_mark_ids   = {}   -- asset key (\"S:\"..staticName / \"C:\"..sceneryId) \226\134\146 mark id\nlocal next_asset_id    = ASSET_MARK_START\n\nlocal function draw_asset_mark(key, p, text)   -- p is a getPoint() table {x,y,z}\n    if asset_mark_ids[key] then return end\n    local id = next_asset_id; next_asset_id = next_asset_id + 1\n    asset_mark_ids[key] = id\n    -- Descriptive text (which keysite this destructible belongs to) \226\128\148 DCS stamps the mark's AUTHOR as\n    -- \"mission data\" (unchangeable for scripted marks), so the text is where the useful info goes.\n    trigger.action.markToAll(id, text or \"\\226\\150\\170\", world_to_mark_pos(p.x, p.z), true, \"\")\nend\n\nlocal function remove_asset_mark(key)\n    if asset_mark_ids[key] then\n        trigger.action.removeMark(asset_mark_ids[key])\n        asset_mark_ids[key] = nil\n    end\nend\n\nlocal function update_asset_indicators()\n    for _, rec in pairs(S.keysites or {}) do\n        -- placed statics: mark each alive one; remove when it enters rec.dead\n        if rec.assets then\n            for _, nm in ipairs(rec.assets) do\n                local key = \"S:\" .. tostring(nm)\n                if rec.dead and rec.dead[nm] then\n                    remove_asset_mark(key)\n                elseif not asset_mark_ids[key] then\n                    local so = StaticObject.getByName(nm)\n                    if so and so:isExist() then\n                        local p = so:getPoint()\n                        if p then draw_asset_mark(key, p, \"\\226\\150\\170 \" .. (rec.label or rec.kind or \"target\") .. \" (target)\") end\n                    end\n                end\n            end\n        end\n        -- resource scenery: mark each alive handle; remove when the row is marked dead\n        if rec.scenery then\n            for _, row in ipairs(rec.scenery) do\n                local key = \"C:\" .. tostring(row.id)\n                if row.dead then\n                    remove_asset_mark(key)\n                elseif not asset_mark_ids[key] and row.handle then\n                    local ok, p = pcall(row.handle.getPoint, row.handle)\n                    if ok and p then\n                        draw_asset_mark(key, { x = p.x, y = 0, z = p.z },\n                            \"\\226\\150\\170 \" .. (rec.label or \"airfield\") .. \" (\" .. tostring(row.type) .. \")\")\n                    end\n                end\n            end\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 Full refresh \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nlocal function refresh(log_fn)\n    local ok, err = pcall(function()\n        cleanup_leaked_marks()\n        update_base_marks()\n        update_installation_marks()\n        update_asset_indicators()\n        update_column_marks()\n        update_frontline()\n        gc_task_arrows()   -- Item 4 backstop: reap arrows whose sortie group is gone\n    end)\n    if not ok and log_fn then\n        log_fn(\"map_overlay error: \" .. tostring(err))\n        cs.dbg(\"mapov\", \"refresh FAILED: %s\", tostring(err))\n    end\nend\n\n-- \226\148\128\226\148\128 Scheduler \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunction M.schedule_overlay(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    -- Item 4: wire the task-end chokepoint so cs.clear_task reaps this task's arrow the instant it ends.\n    cs.task_end_hook = M.remove_task_arrow\n    cs.dbg(\"mapov\", \"overlay scheduler REGISTERED offset=5s period=%.0fs (task-arrow clear_task hook wired)\", UPDATE_PERIOD)\n    -- Initial draw after a short delay so all bases are registered\n    timer.scheduleFunction(function(_, t)\n        -- INFRASTRUCTURE: map overlay keeps refreshing post-victory (shows the final/continuing state).\n        -- EECH fc_msgs.c:163 halts only the win-check, not the sim. Cluster E.\n        if _DMT_GEN ~= my_gen then return nil end\n        refresh(log_fn)\n        return t + UPDATE_PERIOD\n    end, nil, timer.getTime() + 5)\nend\n\nreturn M\n"
__modules["payloads"] = "-- payloads.lua\n-- Weapon pylon tables for all spawned aircraft.\n-- Mirrors: aphavoc/source/entity/helicopter/he_funcs.c (load_helicopter_payload),\n--          aphavoc/source/entity/fixedwing/fw_funcs.c (load_fixedwing_payload)\n--\n-- All CLSIDs verified against live DCS install:\n--   CoreMods/aircraft/F-16C/UnitPayloads/F-16C_50.lua\n--   CoreMods/aircraft/AH-64D/UnitPayloads/AH-64D_BLK_II.lua\n--   MissionEditor/data/scripts/UnitPayloads/{F-15C,Su-25T,Su-27,Mi-24V}.lua\n\nlocal M = {}\n\n-- \226\148\128\226\148\128 BLUE FIXED-WING \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n-- F-16C bl.52d striker: AIM-120C*2, AIM-9X*2, GBU-12*2, 370gal*2, TGP\n-- Pylon layout: 1=L wingtip, 2=L outer, 3=L mid, 4=L inner,\n--               5=centerline, 6=R inner, 7=R mid, 8=R outer, 9=R wingtip\nM.F16_STRIKER = {\n    {CLSID=\"{40EF17B7-F508-45de-8566-6FFECC0C1AB8}\", num=1},  -- AIM-120C\n    {CLSID=\"{5CE2FF2A-645A-4197-B48D-8720AC69394F}\", num=2},  -- AIM-9X\n    {CLSID=\"{DB769D48-67D7-42ED-A2BE-108D566C8B1E}\", num=3},  -- GBU-12\n    {CLSID=\"{F376DBEE-4CAE-41BA-ADD9-B2910AC95DEC}\", num=4},  -- 370gal tank\n    {CLSID=\"{A111396E-D3E8-4b9c-8AC9-2432489304D5}\", num=5},  -- LITENING TGP\n    {CLSID=\"{F376DBEE-4CAE-41BA-ADD9-B2910AC95DEC}\", num=6},  -- 370gal tank\n    {CLSID=\"{DB769D48-67D7-42ED-A2BE-108D566C8B1E}\", num=7},  -- GBU-12\n    {CLSID=\"{5CE2FF2A-645A-4197-B48D-8720AC69394F}\", num=8},  -- AIM-9X\n    {CLSID=\"{40EF17B7-F508-45de-8566-6FFECC0C1AB8}\", num=9},  -- AIM-120C\n}\n\n-- F-15C escort: AIM-120C*2 wingtip, AIM-120B*4 fuselage, AIM-9M*2, fuel*3\n-- Pylon layout: 1=L wingtip, 2=L outer, 3=L inner, 4-5=L fuse,\n--               6=centerline, 7-8=R fuse, 9=R inner, 10=R outer, 11=R wingtip\nM.F15_ESCORT = {\n    {CLSID=\"{40EF17B7-F508-45de-8566-6FFECC0C1AB8}\", num=1},  -- AIM-120C\n    {CLSID=\"{E1F29B21-F291-4589-9FD8-3272EEC69506}\", num=2},  -- 600gal tank\n    {CLSID=\"{6CEB49FC-DED8-4DED-B053-E1F033FF72D3}\", num=3},  -- AIM-9M\n    {CLSID=\"{C8E06185-7CD6-4C90-959F-044679E90751}\", num=4},  -- AIM-120B\n    {CLSID=\"{C8E06185-7CD6-4C90-959F-044679E90751}\", num=5},  -- AIM-120B\n    {CLSID=\"{E1F29B21-F291-4589-9FD8-3272EEC69506}\", num=6},  -- 600gal tank\n    {CLSID=\"{C8E06185-7CD6-4C90-959F-044679E90751}\", num=7},  -- AIM-120B\n    {CLSID=\"{C8E06185-7CD6-4C90-959F-044679E90751}\", num=8},  -- AIM-120B\n    {CLSID=\"{6CEB49FC-DED8-4DED-B053-E1F033FF72D3}\", num=9},  -- AIM-9M\n    {CLSID=\"{E1F29B21-F291-4589-9FD8-3272EEC69506}\", num=10}, -- 600gal tank\n    {CLSID=\"{40EF17B7-F508-45de-8566-6FFECC0C1AB8}\", num=11}, -- AIM-120C\n}\n\n-- \226\148\128\226\148\128 RED FIXED-WING \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n-- Su-25T striker: Kh-29T*2 (TV-guided AGM), R-73*2 (IR self-defence), fuel*2, MPS-410 ECM\n-- Verified from payload \"Kh-29T*2,R-73*2,Fuel*2,MPS-410\" in Su-25T.lua\n-- Pylon: 1=L wingtip ECM, 2=L outer AAM, 3=L inner fuel, 5=L AGM,\n--        7=R AGM, 9=R inner fuel, 10=R outer AAM, 11=R wingtip ECM\nM.SU25T_STRIKER = {\n    {CLSID=\"{44EE8698-89F9-48EE-AF36-5FD31896A82D}\", num=1},  -- MPS-410 ECM (left)\n    {CLSID=\"{CBC29BFE-3D24-4C64-B81D-941239D12249}\", num=2},  -- R-73\n    {CLSID=\"{E8D4652F-FD48-45B7-BA5B-2AE05BB5A9CF}\", num=3},  -- fuel tank\n    {CLSID=\"{601C99F7-9AF3-4ed7-A565-F8B8EC0D7AAC}\", num=5},  -- Kh-29T\n    {CLSID=\"{601C99F7-9AF3-4ed7-A565-F8B8EC0D7AAC}\", num=7},  -- Kh-29T\n    {CLSID=\"{E8D4652F-FD48-45B7-BA5B-2AE05BB5A9CF}\", num=9},  -- fuel tank\n    {CLSID=\"{CBC29BFE-3D24-4C64-B81D-941239D12249}\", num=10}, -- R-73\n    {CLSID=\"{44EE8698-89F9-48EE-AF36-5FD31896A82C}\", num=11}, -- MPS-410 ECM (right)\n}\n\n-- Su-27 escort: R-73*4 (IR), R-27ER*4 (SARH BVR), R-27ET*2 (IR BVR), ECM\n-- Verified from payload \"R-73*4,R-27ER*4,R-27ET*2\" in Su-27.lua\n-- Pylon: 1,10=wingtip R-73; 2,9=outer R-73; 3,8=R-27ET; 4-7=R-27ER belly\nM.SU27_ESCORT = {\n    {CLSID=\"{FBC29BFE-3D24-4C64-B81D-941239D12249}\", num=1},  -- R-73\n    {CLSID=\"{FBC29BFE-3D24-4C64-B81D-941239D12249}\", num=2},  -- R-73\n    {CLSID=\"{B79C379A-9E87-4E50-A1EE-7F7E29C2E87A}\", num=3},  -- R-27ET\n    {CLSID=\"{E8069896-8435-4B90-95C0-01A03AE6E400}\", num=4},  -- R-27ER\n    {CLSID=\"{E8069896-8435-4B90-95C0-01A03AE6E400}\", num=5},  -- R-27ER\n    {CLSID=\"{E8069896-8435-4B90-95C0-01A03AE6E400}\", num=6},  -- R-27ER\n    {CLSID=\"{E8069896-8435-4B90-95C0-01A03AE6E400}\", num=7},  -- R-27ER\n    {CLSID=\"{B79C379A-9E87-4E50-A1EE-7F7E29C2E87A}\", num=8},  -- R-27ET\n    {CLSID=\"{FBC29BFE-3D24-4C64-B81D-941239D12249}\", num=9},  -- R-73\n    {CLSID=\"{FBC29BFE-3D24-4C64-B81D-941239D12249}\", num=10}, -- R-73\n}\n\n-- \226\148\128\226\148\128 BLUE ROTARY-WING \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n-- AH-64D: 4x AGM-114K Hellfire (inboard), 2x M261 Hydra-70 (outboard), FCR\n-- Verified from AH-64D_BLK_II.lua constants:\n--   HellfireLauncherID_AGM114K_4 = {88D18A5E-99C8-4B04-B40B-1C02F2018B6E}\n--   NURSLauncherID_MK151 = M261_MK151\n--   InternalFuelTank100 = {IAFS_ComboPak_100}\n--   FCR = {AN_APG_78}\nM.AH64D_CAP = {\n    {CLSID=\"M261_MK151\",                              num=1}, -- Hydra M261 (left outer)\n    {CLSID=\"{88D18A5E-99C8-4B04-B40B-1C02F2018B6E}\", num=2}, -- 4x AGM-114K\n    {CLSID=\"{88D18A5E-99C8-4B04-B40B-1C02F2018B6E}\", num=3}, -- 4x AGM-114K\n    {CLSID=\"M261_MK151\",                              num=4}, -- Hydra M261 (right outer)\n    {CLSID=\"{IAFS_ComboPak_100}\",                    num=5}, -- internal fuel (required)\n    {CLSID=\"{AN_APG_78}\",                             num=6}, -- FCR\n}\n\n-- \226\148\128\226\148\128 RED ROTARY-WING \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n-- Mi-24V: 4x 9M114 Shturm ATGM (outer), 4x S-8 rocket pods (inner)\n-- Verified from payload \"4x9M114, 80xS-8\" in Mi-24V.lua:\n--   9M114 = {B919B0F4-7C25-455E-9A02-CEA51DB895E3} on pylon 1, 6\n--   S-8 pod = {6A4B9E69-64FE-439a-9163-3A87FB6A4D81} on pylons 2-5\nM.MI24V_CAP = {\n    {CLSID=\"{B919B0F4-7C25-455E-9A02-CEA51DB895E3}\", num=1}, -- 9M114 x4 (left outer)\n    {CLSID=\"{6A4B9E69-64FE-439a-9163-3A87FB6A4D81}\", num=2}, -- S-8 20-round\n    {CLSID=\"{6A4B9E69-64FE-439a-9163-3A87FB6A4D81}\", num=3}, -- S-8 20-round\n    {CLSID=\"{6A4B9E69-64FE-439a-9163-3A87FB6A4D81}\", num=4}, -- S-8 20-round\n    {CLSID=\"{6A4B9E69-64FE-439a-9163-3A87FB6A4D81}\", num=5}, -- S-8 20-round\n    {CLSID=\"{B919B0F4-7C25-455E-9A02-CEA51DB895E3}\", num=6}, -- 9M114 x4 (right outer)\n}\n\n-- \226\148\128\226\148\128 HELPERS \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n-- Build DCS payload block from a pylon table.\n-- Returns { fuel=100, gun=100, pylons={...}, unlimited={fuel=false, guns=false, flares=false, chaff=false} }\nfunction M.build(pylon_list)\n    local pylons = {}\n    for i, p in ipairs(pylon_list) do\n        pylons[i] = {CLSID=p.CLSID, num=p.num}\n    end\n    return {\n        fuel     = 100,\n        gun      = 100,\n        pylons   = pylons,\n        unlimited = {fuel=false, guns=false, flares=false, chaff=false},\n    }\nend\n\nreturn M\n"
__modules["persist"] = "-- persist.lua\n-- EECH source:\n--   aphavoc/source/session/session.c   pack_session / unpack_session \226\128\148 the campaign save/restore\n--                                       root: elapsed_time, per-FORCE data, keysite ownership/strength,\n--                                       reserve hardware, regen queues, and the mobile OOB are packed to\n--                                       a save block and restored on load (SESSION-F15/F16/F17).\n--   aphavoc/source/entity/special/force/force.c    force reserve hardware (restored, not respawned).\n--   aphavoc/source/entity/special/keysite/keysite.c keysite side/strength/supply (restored).\n--\n-- WHAT THIS IS: the port's pack_session analog. EECH's process is a single monolithic entity-tree\n-- serialize; the DCS port cannot serialize live DCS object handles (Group/StaticObject/scenery are\n-- engine userdata that do not survive a process restart), so it saves a PROJECTION of the campaign\n-- state singleton S \226\128\148 the subset that is either pure data or reconstructible \226\128\148 and RESPAWNS the mobile\n-- OOB from position/count SUMMARIES on restore. Air-defence rings, firing points, patrols, installations\n-- and the airbase-asset scenery are re-seeded FRESH by their own init() at boot (exactly as at-boot),\n-- then overlaid with saved health; in-flight sorties are NOT restored (they RTB into the void of the old\n-- process \226\128\148 EECH likewise does not resurrect airborne missions verbatim, it repacks the task tree which\n-- the port drops; unassigned demand regenerates within one generator cycle).\n--\n-- TRANSPORT: the DCS Studio native bridge (dcs_studio.*), which the mission scripting env can reach and\n-- which survives sanitizeModule (CLAUDE.md guardrail: NO os/io/lfs). dcs_studio.file is WRITE-ONLY\n-- (write_text/write_json/write_csv/dump \226\128\148 no read fn), so the round-trippable store is dcs_studio.sqlite:\n-- one row per slot holding a versioned, self-contained Lua-literal blob produced by the pure-Lua\n-- serializer below (chosen over the bridge's JSON so integer coalition.side keys and mixed key types\n-- round-trip exactly \226\128\148 JSON would stringify [2]=BLUE).\n--\n-- RE-INJECTION vs RESTART: a same-process hot re-inject is UNAFFECTED \226\128\148 restore only fires when\n-- config.persistence.enabled is true (default FALSE), so all current dev workflows keep working exactly\n-- as before. Enable it (DMT_CONFIG.persistence.enabled=true) for a dedicated-server deployment where the\n-- campaign must survive a DCS_server.exe restart. See README \"Persistence\".\n\nlocal cs     = require(\"campaign_state\")\nlocal config = require(\"config\")\nlocal S      = cs.S\nlocal M      = {}\n\nlocal SAVE_VERSION = 1\n\n-- \226\148\128\226\148\128 Bridge access (mission-env reachable dcs_studio native runtime) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- rawget avoids an undeclared-global finding and a nil-index if the bridge is not present. If it is\n-- genuinely absent, EVERY persist entry point no-ops with a single loud warning \226\128\148 the campaign runs\n-- unaffected (persistence is best-effort infrastructure, never a spawn-path dependency). We do NOT fall\n-- back to io/lfs (CLAUDE.md guardrail \226\128\148 the sanitized mission env has none).\nlocal function bridge()\n    return rawget(_G, \"dcs_studio\")\nend\n\nlocal _warned_no_bridge = false\nlocal function no_bridge()\n    local b = bridge()\n    if b and b.sqlite then return false end\n    if not _warned_no_bridge then\n        _warned_no_bridge = true\n        env.info(\"[dmt:persist] dcs_studio bridge (sqlite) NOT reachable from the mission env \226\128\148 \"\n            .. \"persistence DISABLED for this run (no save/restore). Campaign continues normally.\")\n    end\n    return true\nend\n\n-- \226\148\128\226\148\128 Config \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function pcfg()\n    return (config.C and config.C.persistence) or {}\nend\nfunction M.enabled()\n    return pcfg().enabled == true\nend\nlocal function slot()\n    local s = pcfg().slot\n    return (type(s) == \"string\" and #s > 0) and s or \"default\"\nend\nlocal function db_path()\n    local p = pcfg().db_path\n    return (type(p) == \"string\" and #p > 0) and p or \"dmt_campaign.sqlite\"\nend\nlocal function autosave_period()\n    local n = pcfg().autosave_period\n    return (type(n) == \"number\" and n > 0) and n or 300\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- PURE-LUA SERIALIZER (proven round-trip in Lua 5.1: integer/string keys, floats, nested tables;\n-- functions/userdata/threads are assert-skipped so a stray live handle can never abort a save). The\n-- output is a self-contained Lua table literal; deserialize is loadstring in an EMPTY sandbox (the blob\n-- is our own output \226\128\148 only data literals, no calls \226\128\148 so an empty environment is safe and total).\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\nlocal function ser_num(v)\n    if v ~= v or v == math.huge or v == -math.huge then return \"0\" end   -- nan/inf \226\134\146 0 (never in the subset)\n    if v == math.floor(v) and math.abs(v) < 2 ^ 53 then\n        return string.format(\"%d\", v)\n    end\n    return string.format(\"%.17g\", v)   -- full float precision \226\134\146 exact round-trip\nend\n\nlocal function ser_key(k)\n    local tk = type(k)\n    if tk == \"number\" then return \"[\" .. ser_num(k) .. \"]\" end\n    if tk == \"string\" then return \"[\" .. string.format(\"%q\", k) .. \"]\" end\n    return nil   -- non-scalar key \226\134\146 skip the pair\nend\n\nlocal function ser(v)\n    local t = type(v)\n    if t == \"number\"  then return ser_num(v) end\n    if t == \"boolean\" then return v and \"true\" or \"false\" end\n    if t == \"string\"  then return string.format(\"%q\", v) end\n    if t == \"table\" then\n        local parts = {}\n        for k, val in pairs(v) do\n            local tv = type(val)\n            if tv == \"number\" or tv == \"boolean\" or tv == \"string\" or tv == \"table\" then\n                local ks = ser_key(k)\n                if ks then parts[#parts + 1] = ks .. \"=\" .. ser(val) end\n            end\n            -- function/userdata/thread values are assert-skipped (never emitted)\n        end\n        return \"{\" .. table.concat(parts, \",\") .. \"}\"\n    end\n    return \"nil\"\nend\nM._ser = ser   -- exposed for the standalone round-trip probe\n\nlocal function deser(str)\n    local ld = loadstring or load\n    if type(ld) ~= \"function\" then return nil, \"no loadstring/load in this env\" end\n    local chunk = ld(\"return \" .. str)\n    if not chunk then return nil, \"parse error\" end\n    if type(setfenv) == \"function\" then pcall(setfenv, chunk, {}) end   -- empty sandbox\n    local ok, val = pcall(chunk)\n    if not ok then return nil, tostring(val) end\n    return val\nend\nM._deser = deser\n\n-- Count leaf fields in a table (save/restore size telemetry).\nlocal function leaf_count(t)\n    if type(t) ~= \"table\" then return 1 end\n    local n = 0\n    for _, v in pairs(t) do n = n + leaf_count(v) end\n    return n\nend\nlocal function key_count(t)\n    local n = 0\n    if type(t) == \"table\" then for _ in pairs(t) do n = n + 1 end end\n    return n\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- SNAPSHOT \226\128\148 build the persistable projection of S. Every field decision is documented in the\n-- REPORT/README; timer-relative values are stored as AGES (seconds before `now`) and rebased on restore\n-- because timer.getTime() resets to 0 on a server restart.\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\nlocal BLUE, RED = coalition.side.BLUE, coalition.side.RED\n\nlocal function group_summary(rec, side, kind)\n    local grp = rec.grp\n    if not cs.group_is_alive(grp) then return nil end\n    local units = grp:getUnits()\n    local n = units and #units or 0\n    if n <= 0 then return nil end\n    local lead\n    local u = grp:getUnit(1)\n    if u and u:isExist() then\n        local p = u:getPosition().p\n        lead = { x = p.x, z = p.z }\n    end\n    if not lead then return nil end\n    local ok_name, gname = pcall(function() return grp:getName() end)\n    return {\n        name        = ok_name and gname or nil,\n        side        = side,\n        kind        = kind,                 -- \"primary\" | \"arty\" | \"sec\"\n        home_base   = rec.home_base,\n        target_base = rec.target_base,      -- primary only (nil for arty/sec)\n        n_alive     = n,\n        want        = rec.want,\n        lead        = lead,\n    }\nend\n\n-- keysite record \226\134\146 handle-stripped snapshot (scenery rows keep {id,type,dead}; NO live handle).\nlocal function keysite_snapshot(rec)\n    local scen = {}\n    for _, srow in ipairs(rec.scenery or {}) do\n        scen[#scen + 1] = { id = srow.id, type = srow.type, dead = srow.dead == true }\n    end\n    local dead = {}\n    for _, dn in ipairs(rec.dead or {}) do dead[#dead + 1] = dn end\n    local assets = {}\n    for _, an in ipairs(rec.assets or {}) do assets[#assets + 1] = an end\n    return {\n        kind = rec.kind, side = rec.side, pos = rec.pos, home_base = rec.home_base,\n        health = rec.health, total = rec.total, alive = rec.alive,\n        label = rec.label, producer = rec.producer, flags = rec.flags,\n        assets = assets, dead = dead, scenery = scen,\n    }\nend\n\nfunction M.snapshot()\n    local now = timer.getTime()\n    local d = {}\n\n    -- Session (SESSION.elapsed_time, pack_session): store elapsed so phase continuity survives the\n    -- timer reset; game_over/winner so a decided campaign stays decided.\n    d.start_elapsed = now - (S.start_time or now)\n    d.phase         = S.phase\n    d.game_over     = S.game_over == true\n    d.winner        = S.winner\n\n    -- Keysite ownership / strength / supply (keysite.c side/strength/ammo/fuel). base_last_strike is\n    -- timer-relative \226\134\146 stored as AGE (rebased on restore) so post-restart repair suppression is correct.\n    d.base_owner      = S.base_owner\n    d.base_health     = S.base_health\n    d.base_pos        = S.base_pos\n    d.base_kind       = S.base_kind\n    d.base_efficiency = S.base_efficiency\n    d.base_ammo       = S.base_ammo\n    d.base_fuel       = S.base_fuel\n    d.base_last_strike_age = {}\n    for name, t in pairs(S.base_last_strike or {}) do\n        if type(t) == \"number\" then d.base_last_strike_age[name] = now - t end\n    end\n\n    -- Campaign objectives + per-side strength (setup.c objective set; fc_updt.c force_percentage).\n    d.objectives = S.objectives\n    d.strength   = S.strength\n\n    -- Per-base idle ledger + production accumulator incl. earmarks (force reserve hardware).\n    d.base_ledger = S.base_ledger\n    d.production  = S.production\n\n    -- Regen queues (rg_updt.c). enqueued is timer-relative \226\134\146 store AGE, rebase on restore.\n    d.regen_queue = {}\n    for side, byt in pairs(S.regen_queue or {}) do\n        d.regen_queue[side] = {}\n        for atype, q in pairs(byt) do\n            local out = {}\n            for _, e in ipairs(q) do\n                out[#out + 1] = { base_name = e.base_name, aircraft_type = e.aircraft_type,\n                                  age = now - (e.enqueued or now) }\n            end\n            d.regen_queue[side][atype] = out\n        end\n    end\n\n    -- Fog of war (sector.c fog values) + pilot career records (player.h).\n    d.fow    = S.fow\n    d.pilots = S.pilots\n\n    -- Per-side campaign stats (F2 \226\128\148 force.h:98-99 kills[]/losses[] live in the packed FORCE entity, so\n    -- they survive an EECH session repack; plain counters, saved alongside pilots).\n    d.stats = S.stats\n\n    -- Keysites (installations + airbase-asset clusters), handles stripped.\n    d.keysites = {}\n    for name, rec in pairs(S.keysites or {}) do\n        d.keysites[name] = keysite_snapshot(rec)\n    end\n\n    -- Mobile OOB \226\134\146 position/count summaries for respawn (the DCS analog of pack_session's mobile tree).\n    d.ground = {}\n    local function add_reg(reg, kind)\n        for side, groups in pairs(reg or {}) do\n            for _, rec in pairs(groups) do\n                local s = group_summary(rec, side, kind)\n                if s then d.ground[#d.ground + 1] = s end\n            end\n        end\n    end\n    add_reg(S.ground_groups, \"primary\")\n    add_reg(S.arty_groups,   \"arty\")\n    add_reg(S.sec_groups,    \"sec\")\n\n    -- DELIBERATELY DROPPED (documented): board_tasks/active_tasks (reference live builders/groups \226\128\148\n    -- unassigned demand regenerates within one generator cycle), base_inflight/group_launch_base\n    -- (in-flight not restored), counter_battery (TTL'd), supply_delivered (per-flight), pending_captures\n    -- (keyed by group names that don't survive respawn), base_warehouse (re-read at boot),\n    -- base_ad_groups/base_fp_groups/patrol_groups (live handles, re-seeded fresh by their init),\n    -- farp_active (F1: RECOMPUTED at boot against the restored ownership \226\128\148 game_loop re-runs\n    -- farps.seed_activation after restore_data, exactly as EECH re-runs initialise_keysite_farp_enable\n    -- at campaign setup, keysite.c:507-568; persisting the latch would freeze stale over-activation).\n\n    return { version = SAVE_VERSION, saved_t = now, data = d }\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- SAVE\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\nfunction M.save(log_fn)\n    log_fn = log_fn or function() end\n    if not M.enabled() then return false end\n    if no_bridge() then return false end\n\n    local ok_snap, envelope = pcall(M.snapshot)\n    if not ok_snap then\n        log_fn(\"[persist] snapshot FAILED: \" .. tostring(envelope))\n        cs.dbg(\"persist\", \"snapshot error: %s\", tostring(envelope))\n        return false\n    end\n    local ok_ser, blob_raw = pcall(ser, envelope)\n    if not ok_ser or type(blob_raw) ~= \"string\" then\n        log_fn(\"[persist] serialize FAILED: \" .. tostring(blob_raw))\n        cs.dbg(\"persist\", \"serialize error: %s\", tostring(blob_raw))\n        return false\n    end\n    local blob = tostring(blob_raw)   -- definite string (analyzer does not narrow a pcall union)\n    local blob_len = #blob\n\n    local b = bridge()\n    local db, oerr = b.sqlite.open(db_path())\n    if not db then\n        log_fn(\"[persist] sqlite.open FAILED: \" .. tostring(oerr))\n        cs.dbg(\"persist\", \"sqlite.open error: %s\", tostring(oerr))\n        return false\n    end\n\n    local ok_w = pcall(function()\n        db:exec(\"CREATE TABLE IF NOT EXISTS campaign_save \"\n            .. \"(slot TEXT PRIMARY KEY, version INTEGER, saved_t REAL, blob TEXT)\")\n        db:exec(\"INSERT OR REPLACE INTO campaign_save (slot, version, saved_t, blob) VALUES (?, ?, ?, ?)\",\n            { slot(), SAVE_VERSION, envelope.saved_t, blob })\n    end)\n    pcall(function() db:close() end)\n\n    if not ok_w then\n        log_fn(\"[persist] sqlite write FAILED\")\n        cs.dbg(\"persist\", \"sqlite write error\")\n        return false\n    end\n\n    local d = envelope.data\n    local n_ground = (type(d.ground) == \"table\") and #d.ground or 0\n    log_fn(string.format(\"[persist] saved slot=%q (%d bytes, %d fields)\", slot(), blob_len, leaf_count(d)))\n    cs.dbg(\"persist\", \"SAVE slot=%s bytes=%d fields=%d | bases=%d keysites=%d ground=%d pilots=%d regen_q=%d\",\n        slot(), blob_len, leaf_count(d), key_count(d.base_owner), key_count(d.keysites),\n        n_ground, key_count(d.pilots), key_count(d.regen_queue))\n    return true\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- LOAD (raw) \226\128\148 read + deserialize the slot's blob; returns the envelope table or nil.\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\nlocal function load_envelope(log_fn)\n    if no_bridge() then return nil end\n    local b = bridge()\n    local db, oerr = b.sqlite.open(db_path())\n    if not db then\n        cs.dbg(\"persist\", \"restore sqlite.open error: %s\", tostring(oerr))\n        return nil\n    end\n    local rows\n    pcall(function()\n        db:exec(\"CREATE TABLE IF NOT EXISTS campaign_save \"\n            .. \"(slot TEXT PRIMARY KEY, version INTEGER, saved_t REAL, blob TEXT)\")\n        rows = db:query(\"SELECT blob, version, saved_t FROM campaign_save WHERE slot = ?\", { slot() })\n    end)\n    pcall(function() db:close() end)\n\n    if type(rows) ~= \"table\" or not rows[1] or type(rows[1].blob) ~= \"string\" then\n        cs.dbg(\"persist\", \"restore: no save row for slot=%s\", slot())\n        return nil\n    end\n    local env_tbl, derr = deser(rows[1].blob)\n    if type(env_tbl) ~= \"table\" or type(env_tbl.data) ~= \"table\" then\n        (log_fn or env.info)(\"[persist] restore: deserialize FAILED: \" .. tostring(derr))\n        cs.dbg(\"persist\", \"restore deserialize error: %s\", tostring(derr))\n        return nil\n    end\n    if env_tbl.version ~= SAVE_VERSION then\n        cs.dbg(\"persist\", \"restore: version mismatch (save=%s expected=%d) \226\128\148 ignoring\",\n            tostring(env_tbl.version), SAVE_VERSION)\n        return nil\n    end\n    return env_tbl\nend\n\n-- Module-local carry between the two restore phases (data overlay early, world overlay late).\nlocal _restored = false\nlocal _data = nil\n\nfunction M.was_restored() return _restored end\n\n-- \226\148\128\226\148\128 PHASE A: data overlay (call AFTER world discovery + all *.init that seed data tables, BEFORE\n-- ground OOB spawn). Overlays the pure-data subset onto the freshly-initialised S so later init that\n-- READS ownership (installations, AD rings) sees the restored map. Returns true if a save was applied.\nfunction M.restore_data(log_fn)\n    log_fn = log_fn or function() end\n    _restored = false\n    _data = nil\n    if not M.enabled() then\n        cs.dbg(\"persist\", \"restore_data: persistence disabled (config) \226\128\148 fresh OOB\")\n        return false\n    end\n    local envelope = load_envelope(log_fn)\n    if not envelope then return false end\n    local d = envelope.data\n    local now = timer.getTime()\n\n    -- Session\n    S.start_time = now - (tonumber(d.start_elapsed) or 0)\n    if type(d.phase) == \"string\" then S.phase = d.phase end\n    S.game_over = d.game_over == true\n    S.winner    = d.winner\n\n    -- Keysite ownership / strength / supply (whole-table overlay \226\128\148 base names are stable DCS airbase\n    -- names, so keys line up with the freshly-discovered registry).\n    local function overlay(dst_name, src)\n        if type(src) == \"table\" then S[dst_name] = src end\n    end\n    overlay(\"base_owner\", d.base_owner)\n    overlay(\"base_health\", d.base_health)\n    overlay(\"base_pos\", d.base_pos)\n    overlay(\"base_kind\", d.base_kind)\n    overlay(\"base_efficiency\", d.base_efficiency)\n    overlay(\"base_ammo\", d.base_ammo)\n    overlay(\"base_fuel\", d.base_fuel)\n    overlay(\"objectives\", d.objectives)\n    overlay(\"strength\", d.strength)\n    overlay(\"base_ledger\", d.base_ledger)\n    overlay(\"production\", d.production)\n    overlay(\"fow\", d.fow)\n    overlay(\"pilots\", d.pilots)\n    overlay(\"stats\", d.stats)   -- F2: per-side kill/loss/task/sortie stats (absent in older saves \226\134\146 fresh zeros kept)\n\n    -- base_last_strike: rebase AGE \226\134\146 absolute in the new timeline (now - age).\n    S.base_last_strike = {}\n    for name, age in pairs(d.base_last_strike_age or {}) do\n        if type(age) == \"number\" then S.base_last_strike[name] = now - age end\n    end\n\n    -- Regen queues: rebase each entry's enqueued time (now - age).\n    if type(d.regen_queue) == \"table\" then\n        local rq = {}\n        for side, byt in pairs(d.regen_queue) do\n            rq[side] = {}\n            for atype, q in pairs(byt) do\n                local out = {}\n                for _, e in ipairs(q) do\n                    out[#out + 1] = { base_name = e.base_name, aircraft_type = e.aircraft_type,\n                                      enqueued = now - (tonumber(e.age) or 0) }\n                end\n                rq[side][atype] = out\n            end\n        end\n        S.regen_queue = rq\n    end\n\n    -- In-flight sorties are NOT restored (their DCS groups died with the old process): zero the slot\n    -- ledger so no base is falsely at capacity, and clear the launch-base map.\n    S.base_inflight     = {}\n    S.group_launch_base = {}\n\n    _restored = true\n    _data = d\n    log_fn(string.format(\"[persist] restore: applied slot=%q (saved %.0fs of campaign elapsed)\",\n        slot(), tonumber(d.start_elapsed) or 0))\n    cs.dbg(\"persist\", \"RESTORE(data) slot=%s: bases=%d ledger-bases=%d regen_q=%d pilots=%d fow=%d strength B/R=%d/%d game_over=%s\",\n        slot(), key_count(d.base_owner), key_count(d.base_ledger), key_count(d.regen_queue),\n        key_count(d.pilots), key_count(d.fow), S.strength[BLUE] or 0, S.strength[RED] or 0,\n        tostring(S.game_over))\n    return true\nend\n\n-- \226\148\128\226\148\128 PHASE B: world overlay (call AFTER installations.init + base_defenses.init + pilots.init, BEFORE\n-- schedulers). Overlays saved keysite health/dead onto the freshly-seeded keysite records, re-kills\n-- saved-dead author statics by name, and respawns the mobile OOB from summaries.\nfunction M.restore_world(log_fn)\n    log_fn = log_fn or function() end\n    if not _restored or type(_data) ~= \"table\" then return end\n    local d = _data\n\n    -- Keysite records (installations + airbase-asset clusters): overlay health/alive/dead so a keysite\n    -- damaged last session is still damaged. Scenery handles cannot be re-acquired by name (journal:\n    -- not re-acquirable) \226\128\148 the keysite's health is count-derived, so restoring alive/health + the\n    -- per-row dead flags is sufficient; register_static_death arithmetic reads the counts, not handles.\n    local n_ks, n_rekill = 0, 0\n    for name, snap in pairs(d.keysites or {}) do\n        local rec = S.keysites and S.keysites[name]\n        if rec then\n            rec.health = snap.health\n            rec.alive  = snap.alive\n            rec.total  = snap.total or rec.total\n            rec.side   = snap.side or rec.side\n            -- dead author-static NAME list: re-kill each (StaticObject.getByName \226\134\146 destroy) so the\n            -- physical world matches the saved keysite health. pcall-guarded; a missing static is a no-op.\n            -- BEST-EFFORT: author-placed statics (loaded with the .miz) are present now and ARE re-killed;\n            -- campaign-spawned template statics (Inst-*) are still in the spawn_queue at this point (drains\n            -- after game_loop.start), so their re-kill is a no-op here. Keysite health is already restored\n            -- numerically above and is event-incremental (register_static_death), so correctness holds\n            -- regardless \226\128\148 this loop only reconciles the VISIBLE static set, not the health value.\n            rec.dead = {}\n            for _, dn in ipairs(snap.dead or {}) do\n                rec.dead[#rec.dead + 1] = dn\n                local ok_s, so = pcall(StaticObject.getByName, dn)\n                if ok_s and so then\n                    if pcall(function() so:destroy() end) then n_rekill = n_rekill + 1 end\n                end\n            end\n            -- Scenery dead flags (handles stay whatever init re-acquired; only the dead marker matters\n            -- for the count-based health that installations.lua already restored above).\n            if type(rec.scenery) == \"table\" and type(snap.scenery) == \"table\" then\n                local by_id = {}\n                for _, srow in ipairs(snap.scenery) do by_id[tostring(srow.id)] = srow.dead == true end\n                for _, srow in ipairs(rec.scenery) do\n                    local sd = by_id[tostring(srow.id)]\n                    if sd ~= nil then srow.dead = sd end\n                end\n            end\n            n_ks = n_ks + 1\n        else\n            cs.dbg(\"persist\", \"restore_world: saved keysite %s has no fresh record (placement drift) \226\128\148 skipped\", name)\n        end\n    end\n\n    -- Respawn the mobile OOB (primary/arty/sec) from summaries \226\128\148 reserve-neutral (the restored\n    -- base_ledger already reflects these groups' original consumption).\n    local ground = (type(d.ground) == \"table\") and d.ground or {}\n    local n_ground = #ground\n    local ok_g, gnd = pcall(require, \"ground_forces\")\n    local n_resp = 0\n    if ok_g and gnd and gnd.respawn_saved then\n        for _, summ in ipairs(ground) do\n            if pcall(gnd.respawn_saved, summ, log_fn) then n_resp = n_resp + 1 end\n        end\n    else\n        cs.dbg(\"persist\", \"restore_world: ground_forces.respawn_saved unavailable \226\128\148 mobile OOB NOT restored\")\n    end\n\n    log_fn(string.format(\"[persist] restore(world): %d keysite(s) overlaid, %d dead static(s) re-killed, %d ground group(s) respawned\",\n        n_ks, n_rekill, n_resp))\n    cs.dbg(\"persist\", \"RESTORE(world): keysites=%d rekilled=%d ground_respawned=%d/%d\",\n        n_ks, n_rekill, n_resp, n_ground)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- AUTOSAVE SCHEDULER (mirrors EECH's periodic session repack). Registered from game_loop only when\n-- persistence is enabled; gen-guarded like every other campaign timer.\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\nfunction M.schedule(log_fn)\n    log_fn = log_fn or function() end\n    if not M.enabled() then\n        cs.dbg(\"persist\", \"autosave NOT scheduled (persistence disabled)\")\n        return\n    end\n    if no_bridge() then return end\n    local period = autosave_period()\n    local my_gen = _DMT_GEN\n    cs.dbg(\"persist\", \"autosave scheduler REGISTERED period=%.0fs slot=%s db=%s\", period, slot(), db_path())\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end   -- re-injection guard\n        local ok, err = pcall(M.save, log_fn)\n        if not ok then\n            log_fn(\"[persist] autosave error: \" .. tostring(err))\n            cs.dbg(\"persist\", \"autosave tick error: %s\", tostring(err))\n        end\n        return t + period\n    end, nil, timer.getTime() + period)\nend\n\nreturn M\n"
__modules["pilots"] = "-- pilots.lua\n-- EECH source:\n--   aphavoc/source/entity/special/pilot/pi_funcs.c    pilot entity accessors (kills/rank/side)\n--   aphavoc/source/entity/special/pilot/pilot.c        get_player_rank_from_points, high-score,\n--                                                      join-announce, session pilot count\n--   aphavoc/source/entity/system/en_types/en_plyr.h    entity_players (AI/LOCAL/REMOTE, :67-73)\n--   aphavoc/source/ui_menu/player/player.c             promotion thresholds (:73-77),\n--                                                      inc_player_log_kills classification (:912-977)\n--   aphavoc/source/ui_menu/player/play_md.c            valour-medal criteria table (:218-260)\n--   aphavoc/source/entity/mobile/mobile.c              credit_client_server_mobile_kill /\n--                                                      calculate_task_points_for_kill (:281-484)\n--   aphavoc/source/entity/mobile/aircraft/helicop/helicop.c  suitable_for_player (:1825-1966),\n--                                                      notify_gunship_entity_mission_terminated\n--\n-- THE PILOT / PLAYER CAREER SUBSTRATE (Cluster 6, spec 10). EECH's PILOT entity + player_log are\n-- NOT PORTED (DCS owns player slots, join/leave, side selection, occupancy \226\128\148 spec 10 \194\1675). This\n-- module is the port-side career record the campaign keeps ABOUT each human: per-player kills by\n-- category, cumulative score (experience proxy), rank, valour medals, sorties and deaths, keyed by\n-- getPlayerName. It is scaffolding: it activates fully only once flyable player slots exist (goals/03\n-- P0 \226\128\148 coalition.addGroup cannot create human slots). With zero players every entry point is inert.\n--\n-- State lives in the campaign_state singleton (S.pilots) so a future persistence layer (goals/03 P1)\n-- serializes it with the rest of the campaign. init() never clobbers an existing S.pilots (restore-safe).\n--\n-- PORTED IN WAVE 4 (this file):\n--   * Player mission assignment (F19): a human binds an open player-flyable board task via the F-10\n--     group menu (M._grp_request \226\134\146 task_board.assign_to_player); it leaves the AI pool and is registered\n--     as the player's sortie so reaction/dedup/debrief treat it like an AI task.\n--   * Per-sortie debrief loop (F9): M.on_debrief, fired from reaction's S_EVENT_LAND when a human lands\n--     completing their task \226\128\148 mirrors notify_gunship_entity_mission_terminated (helicop.c:693-836).\n--   * Air Medal (F11, 3 consecutive successes, play_md.c:1304-1359); Purple Heart (F13, damaged-but-\n--     survived, play_md.c:1245-1296, tracked via S_EVENT_HIT \226\134\146 M.on_hit); Campaign medal at the win\n--     declaration (F14, play_md.c:1062, M.award_campaign_medals from win_condition.finish).\n--\n-- DELIBERATELY NOT PORTED (noted, not reproduced):\n--   * Flying-hours career track + aviator-wings flight-time medals (F12): the port keeps `sorties`\n--     (mission count) but no flying-hours accrual, so the documented EECH \195\1511000 unit bug\n--     (get_player_log_flying_hours uses TIME_1_HOUR = 3_600_000 ms, player.c:740, while\n--     award_aviator_wings uses ONE_HOUR = 3600 s, play_md.c:1018 \226\128\148 spec 10 Open-Q1) is NOT\n--     reproduced. If flying hours are ever added, divide seconds by 3600 (ONE_HOUR) everywhere.\n--   * MP pilot entity replication, high-score table, planner locks (F1-F6,F18,F20-F22):\n--     DCS-native or out of scope for this scaffolding.\n\nlocal cs      = require(\"campaign_state\")\nlocal supply  = require(\"supply\")\nlocal board   = require(\"task_board\")\nlocal frontl  = require(\"frontline\")\nlocal S       = cs.S\nlocal M       = {}\n\nlocal function info(msg)\n    env.info(string.format(\"[dynamic-mission-test] [pilots] %s\", tostring(msg)))\nend\n\n-- \226\148\128\226\148\128 Rank / promotion thresholds (PILOT-F8) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Rank is a pure function of accumulated per-side experience points (award_player_rank,\n-- get_player_rank_from_points; eech player.c:408-431). Base constants eech player.c:73-77.\n-- NO demotion guard in EECH \226\128\148 rank is whatever the points imply; points only shrink via explicit\n-- clamping at 0 (player.c:540-546), never from death. Names: eech player.c:172-177.\nM.RANK = {\n    { name = \"Lieutenant\",  points = 0 },       -- LIEUTENANT_POINTS_BASE   eech player.c:73\n    { name = \"Captain\",     points = 7500 },    -- CAPTAIN_POINTS_BASE      eech player.c:74\n    { name = \"Major\",       points = 32000 },   -- MAJOR_POINTS_BASE        eech player.c:75\n    { name = \"Lt. Colonel\", points = 120000 },  -- LT_COLONEL_POINTS_BASE   eech player.c:76\n    { name = \"Colonel\",     points = 250000 },  -- COLONEL_POINTS_BASE      eech player.c:77\n}\n\n-- \226\148\128\226\148\128 Valour medals (PILOT-F10) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Points thresholds of the valour-medal criteria table (eech play_md.c:218-260); the points test\n-- is strictly `points >` the threshold (eech play_md.c:1212).\n-- PORT PROXY: EECH awards these on PER-MISSION points with rank / prerequisite-medal / campaign-medal\n-- gating (query_award_medal, play_md.c:1109-1173), inside the mission-termination debrief (F9). The\n-- port has no per-mission debrief loop for players yet, so each valour medal is awarded ONCE when\n-- CUMULATIVE career score first exceeds its threshold \226\128\148 a documented reward-spine stand-in until\n-- player mission assignment (F19) exists. The rank/prerequisite gates are intentionally omitted.\nM.VALOUR = {\n    { name = \"Flying Cross\",          points = 2600 },  -- eech play_md.c:218-260\n    { name = \"Silver Star\",           points = 3200 },\n    { name = \"Distinguished Service\", points = 4000 },\n    { name = \"Medal of Honour\",       points = 5000 },\n}\n\n-- \226\148\128\226\148\128 Per-category kill points \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- PORT PROXY for INT_TYPE_POINTS_VALUE (the per-entity data value that EECH's\n-- calculate_task_points_for_kill uses as its base; eech mobile.c:281-359). The port has no\n-- per-entity points-value data, so kills are scored by CATEGORY. Same-side (friendly) kills score 0\n-- (eech mobile.c:306-311). The EECH threat-target bonuses (+10% own group / +50% other friendly\n-- group; mobile.c:338/346) are omitted \226\128\148 the port has no per-kill \"was the victim targeting a\n-- friendly\" context. Values are relative-worth proxies, not eech literals.\nM.KILL_POINTS = {\n    fixed_wing = 100, helicopter = 100, air_defence = 80,\n    armour = 60, artillery = 60, ground = 40, sea = 120, fixed = 50,\n}\n\n-- \226\148\128\226\148\128 Player-flyable task types (PILOT-F17) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- suitable_for_player gates the campaign to player-controllable COMBAT HELICOPTERS (gunships;\n-- eech helicop.c:1825-1966). In the port the gunship missions are the LIVE heli-role board tasks:\n-- CAS and BAI (the rotary frontline fight, ts_dbase.c heli-eligible landing types) plus troop\n-- insertion (critical \226\134\146 shown in the menu but never held back by the reservation) and BDA.\n-- The retired anti_armour/hunter_killer/heli_escort types were removed with their generators\n-- (Cluster H) \226\128\148 listing them here made the player reservation + Request Mission list INERT\n-- (adversarial-review Finding 1). Fixed-wing striker/escort/recon tasks are AI-only here.\n-- Consumed by get_player_missions (F-10 \"Request Mission\") and task_board's player reservation.\nM.PLAYER_FLYABLE = {\n    cas = true, bai = true, troop_insertion = true, bda = true,\n}\n\n-- \226\148\128\226\148\128 Air Medal streak (PILOT-F11, eech play_md.c:89) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- NUM_NEEDED_TO_AWARD_AIR_MEDAL = 3 (play_md.c:89): the Air Medal is awarded on a hat-trick of\n-- CONSECUTIVE successful missions (award_air_medal_medal, play_md.c:1304-1359 \226\128\148 counter++ on success,\n-- award+reset at 3, reset to 0 on any failure).\nM.AIR_MEDAL_STREAK = 3\n\n-- \226\148\128\226\148\128 Per-task briefing templates (WARZONE-F20/21, eech ai/faction/briefing.c) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH generates mission briefing text from a briefing database: briefing.dat holds a template string\n-- per task type and build_substitution_info (briefing.c) walks %-tokens substituting the live objective\n-- \226\128\148 briefing_add_keysite / briefing_add_position / briefing_add_sector / briefing_add_target_type\n-- (briefing.c:107-117) splice in the target keysite name, its map position, and the target kind. The\n-- port keeps that SHAPE data-light: one template per port task type, with a single %s target-name\n-- substitution, and brief_for() appends the live bearing/range from the assigning base (the\n-- briefing_add_position analog). Kept intentionally as flavour+geometry text, not a data-file loader.\nM.TEMPLATES = {\n    cas             = \"CLOSE AIR SUPPORT: friendly ground forces are in contact near %s. Find and destroy the enemy armour and infantry in the engagement zone, then RTB.\",\n    bai             = \"BATTLEFIELD INTERDICTION: enemy ground forces are moving to reinforce %s. Interdict and destroy the column before it reaches the front line.\",\n    bda             = \"BATTLE DAMAGE ASSESSMENT: overfly %s and confirm the results of the preceding strike. Stay high, observe, and return to base.\",\n    troop_insertion = \"AIR ASSAULT: %s has been suppressed below holding strength. Insert the assault troops onto the objective to capture it.\",\n    ground_strike   = \"GROUND STRIKE: destroy the high-value structures at %s to degrade its operational output.\",\n    oca_strike      = \"OCA STRIKE: hit the airbase at %s to suppress enemy air operations \226\128\148 crater the ramp and kill parked aircraft.\",\n    oca_sweep       = \"OCA SWEEP: sweep the airspace over %s ahead of the strike package and clear enemy fighters.\",\n    sead            = \"SEAD: suppress the enemy air-defence network protecting %s. Kill the radars and launchers screening the objective.\",\n    recon           = \"RECONNAISSANCE: overfly %s and reveal enemy dispositions to cue follow-on tasking.\",\n    heli_escort     = \"ESCORT: shepherd the friendly rotary package operating near %s and keep threats off it.\",\n    supply          = \"LOGISTICS: fly the resupply run into %s.\",\n}\n\n-- \226\148\128\226\148\128 Rank helper \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function rank_from_points(pts)\n    local r = 1\n    for i = #M.RANK, 1, -1 do\n        if pts >= M.RANK[i].points then r = i; break end\n    end\n    return r\nend\n\n-- \226\148\128\226\148\128 Record lifecycle (created on first sight, PILOT-F1 analogue) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function get_or_create(name, side)\n    S.pilots = S.pilots or {}\n    local rec = S.pilots[name]\n    if not rec then\n        rec = {\n            name = name, side = side,\n            score = 0, rank = 1,\n            -- category counters mirror player_kills_type (eech player.h:154-169)\n            kills = { air = 0, ground = 0, sea = 0, fixed = 0,\n                      fixed_wing = 0, helicopter = 0, air_defence = 0,\n                      armour = 0, artillery = 0, friendly = 0, total = 0 },\n            medals   = {},   -- [medal_name] = count\n            sorties  = 0,    -- slot-entries (S_EVENT_BIRTH count)\n            deaths   = 0,\n            -- Debrief-loop fields (PILOT-F9/F11/F13, eech play_md.c). missions_flown mirrors\n            -- inc_player_log_missions_flown (helicop.c:729 \226\128\148 COMPLETED missions, distinct from `sorties`\n            -- which is births); air_medal_counter is player_log side_log.air_medal_counter (play_md.c:1320);\n            -- sortie_score_start snapshots career score at task assignment so mission_points = the per-\n            -- sortie delta (the INT_TYPE_TASK_SCORE proxy, mobile.c:416-424); sortie_damaged is the\n            -- S_EVENT_HIT-tracked \"took damage this sortie\" flag for the Purple Heart (play_md.c:1245).\n            missions_flown   = 0,\n            air_medal_counter = 0,\n            sortie_score_start = 0,\n            sortie_damaged   = false,\n            first_seen = timer.getTime(),\n        }\n        S.pilots[name] = rec\n        info(string.format(\"pilot record created: %s (%s)\", name, cs.SIDE_NAME[side] or \"?\"))\n        cs.dbg(\"pilots\", \"record created: %s (%s)\", name, cs.SIDE_NAME[side] or \"?\")\n    end\n    return rec\nend\n\n-- \226\148\128\226\148\128 Victim classification (PILOT-F15, eech player.c:912-977) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Returns (category, sub) where category \226\136\136 {air,ground,sea,fixed} and sub is the finer bucket\n-- (fixed_wing/helicopter/air_defence/armour/artillery) or nil. nil category \226\134\146 not a scorable kill.\nlocal function classify_victim(victim)\n    local ok, desc = pcall(function() return victim:getDesc() end)\n    local a = (ok and desc and desc.attributes) or {}\n    if a[\"Planes\"]      then return \"air\", \"fixed_wing\" end\n    if a[\"Helicopters\"] then return \"air\", \"helicopter\" end\n    if a[\"Air Defence\"] or a[\"SAM\"] or a[\"AAA\"] or a[\"SR SAM\"] or a[\"MR SAM\"] or a[\"LR SAM\"]\n                        then return \"ground\", \"air_defence\" end\n    if a[\"Ships\"]       then return \"sea\", nil end\n    if a[\"Buildings\"] or a[\"Structures\"] or a[\"Immobile\"] then return \"fixed\", nil end\n    if a[\"Tanks\"] or a[\"Armored vehicles\"] or a[\"IFV\"] or a[\"APC\"] or a[\"MBT\"]\n                        then return \"ground\", \"armour\" end\n    if a[\"Artillery\"]   then return \"ground\", \"artillery\" end\n    if a[\"Ground Units\"] or a[\"Infantry\"] then return \"ground\", nil end\n    return nil, nil\nend\n\n-- \226\148\128\226\148\128 Promotion / medal awarding (announced via outText, PILOT-F8/F10) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function award_after_score(rec)\n    -- Promotion (no demotion: score only grows, so rank_from_points >= current).\n    local newr = rank_from_points(rec.score)\n    if newr > rec.rank then\n        rec.rank = newr\n        local msg = string.format(\"%s promoted to %s (score %d)\", rec.name, M.RANK[newr].name, rec.score)\n        info(msg)\n        pcall(trigger.action.outText, msg, 15)\n    end\n    -- Valour medals: award each once when cumulative score strictly exceeds its threshold.\n    for _, m in ipairs(M.VALOUR) do\n        if rec.score > m.points and not rec.medals[m.name] then\n            rec.medals[m.name] = 1\n            local msg = string.format(\"%s awarded the %s\", rec.name, m.name)\n            info(msg)\n            pcall(trigger.action.outText, msg, 15)\n        end\n    end\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Event entry points (called from EXISTING world handlers \226\128\148 no new world hooks)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n\n-- on_kill: called from win_condition's S_EVENT_KILL handler. Credits the killer's career record\n-- when the killer is a human (PILOT-F16 player-career branch, mobile.c:449-459). Inert for AI kills.\nfunction M.on_kill(event)\n    if not event or event.id ~= world.event.S_EVENT_KILL then return end\n    local killer = event.initiator\n    if not killer or not killer.getPlayerName then return end\n    local pname\n    local ok = pcall(function() pname = killer:getPlayerName() end)\n    if not ok or not pname then return end   -- AI killer \226\134\146 not a player career event\n\n    local kside\n    pcall(function() kside = killer:getCoalition() end)\n    local rec = get_or_create(pname, kside)\n\n    local victim = event.target\n    if not victim then return end\n\n    local vside\n    pcall(function() vside = victim:getCoalition() end)\n    local cat, sub = classify_victim(victim)\n    if not cat then return end\n\n    if vside ~= nil and vside == kside then\n        rec.kills.friendly = rec.kills.friendly + 1   -- same-side kill: 0 points (mobile.c:306-311)\n        info(string.format(\"%s FRIENDLY kill (no score)\", pname))\n        return\n    end\n\n    rec.kills[cat] = (rec.kills[cat] or 0) + 1\n    if sub then rec.kills[sub] = (rec.kills[sub] or 0) + 1 end\n    rec.kills.total = rec.kills.total + 1\n    local pts = M.KILL_POINTS[sub or cat] or 0\n    rec.score = rec.score + pts\n    info(string.format(\"%s kill: %s (+%d \226\134\146 score %d, %d total)\",\n        pname, sub or cat, pts, rec.score, rec.kills.total))\n    cs.dbg(\"pilots\", \"%s kill: %s +%d -> score %d rank=%s\", pname, sub or cat, pts, rec.score,\n        M.RANK[rec.rank] and M.RANK[rec.rank].name or \"?\")\n    award_after_score(rec)\nend\n\n-- on_death: called from reaction's S_EVENT_DEAD handler. Records a player's loss (PILOT-F15/F23).\n-- Death does NOT destroy the career (spec 10 F23) and carries NO score penalty in EECH (experience\n-- only shrinks via explicit clamping, player.c:540-546) \226\128\148 so there is no demotion (F8). We record the\n-- death and re-affirm rank (unchanged). No respawn mechanics (DCS owns slot re-entry).\nfunction M.on_death(event)\n    local u = event and event.initiator\n    if not u or not u.getPlayerName then return end\n    local pname\n    local ok = pcall(function() pname = u:getPlayerName() end)\n    if not ok or not pname then return end\n    local rec = S.pilots and S.pilots[pname]\n    if not rec then return end   -- never seen alive \226\134\146 nothing to record\n    rec.deaths = (rec.deaths or 0) + 1\n    rec.kills.deaths = rec.deaths   -- mirror into the player_kills_type deaths field\n    -- A death is a FAILED mission (the sortie never debriefs): reset the Air Medal consecutive-success\n    -- streak (eech play_md.c:820 award_air_medal_medal(side, FALSE) on TASK_COMPLETED_FAILURE) and clear\n    -- the per-sortie debrief baselines so the next sortie starts clean. No score penalty (rank held).\n    rec.air_medal_counter  = 0\n    rec.sortie_damaged     = false\n    rec.sortie_score_start = rec.score\n    info(string.format(\"%s DEATH recorded (deaths=%d, rank held at %s, no score penalty)\",\n        pname, rec.deaths, M.RANK[rec.rank].name))\n    cs.dbg(\"pilots\", \"%s DEATH recorded: deaths=%d, air-medal streak reset, no score penalty\", pname, rec.deaths)\nend\n\n-- on_birth: called from reaction's S_EVENT_BIRTH handler. Ensures a career record for a human unit\n-- and, once per entry (debounced), sends the situational JOIN BRIEF (goals/03 P1): phase, own-side\n-- strength, reserves, nearest frontline, own objectives, open gunship missions. Inert for AI births.\nfunction M.on_birth(event)\n    local u = event and event.initiator\n    if not u or not u.getPlayerName then return end\n    local pname\n    local ok = pcall(function() pname = u:getPlayerName() end)\n    if not ok or not pname then return end\n\n    local side\n    pcall(function() side = u:getCoalition() end)\n    local rec = get_or_create(pname, side)\n    rec.sorties = (rec.sorties or 0) + 1\n\n    -- Resolve this human's group id/name once (used for the group-scoped menu AND the join brief).\n    local gid, gname\n    pcall(function() local g = u:getGroup(); gid = g:getID(); gname = g:getName() end)\n\n    -- Build/refresh this human's group-scoped F-10 assignment menu (PILOT-F19). Group-scoped so the\n    -- command can identify WHICH player is requesting (a coalition-scoped command cannot). Rebuilt on\n    -- each birth (remove+add) so it stays correct across slot changes and re-injection.\n    if gid and gname then pcall(M.build_group_menu, gid, gname, side) end\n\n    -- Debounce: S_EVENT_BIRTH can fire more than once per slot entry; one brief per ~10 s.\n    local now = timer.getTime()\n    if rec.last_brief_t and (now - rec.last_brief_t) < 10 then return end\n    rec.last_brief_t = now\n\n    local text = M.build_brief(rec, side)\n    if gid and trigger.action.outTextForGroup then\n        local sent = pcall(trigger.action.outTextForGroup, gid, text, 30)\n        if sent then info(string.format(\"join brief sent to %s (group %s)\", pname, tostring(gid)))\n                     return end\n    end\n    pcall(trigger.action.outText, text, 30)   -- fallback: whole-server text\n    info(string.format(\"join brief (fallback outText) for %s\", pname))\nend\n\n-- \226\148\128\226\148\128 Situational brief text (goals/03 P1 \"entering an ongoing war\") \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.build_brief(rec, side)\n    local enemy = cs.ENEMY[side]\n    local phase = cs.current_phase()\n    local lines = {}\n    lines[#lines + 1] = string.format(\"=== SITUATION BRIEF \226\128\148 %s (%s) ===\",\n        rec.name, M.RANK[rec.rank] and M.RANK[rec.rank].name or \"?\")\n    lines[#lines + 1] = string.format(\"Phase: %s   |   %s %d%%   %s %d%%\",\n        string.upper(phase),\n        cs.SIDE_NAME[side]  or \"?\", S.strength[side]  or 0,\n        cs.SIDE_NAME[enemy] or \"?\", S.strength[enemy] or 0)\n\n    -- Own-side reserve summary (supply.reserve_side = \206\163 base ledgers).\n    local ok_h, heli    = pcall(supply.reserve_side, side, \"heli\")\n    local ok_s, striker = pcall(supply.reserve_side, side, \"striker\")\n    local ok_e, escort  = pcall(supply.reserve_side, side, \"escort\")\n    lines[#lines + 1] = string.format(\"Your reserves: %d gunship, %d strike, %d escort\",\n        (ok_h and heli) or 0, (ok_s and striker) or 0, (ok_e and escort) or 0)\n\n    -- Nearest / most-forward frontline base for the side.\n    local ok_f, fl = pcall(frontl.get_frontline, side)\n    local front = (ok_f and fl and fl[1]) or \"none\"\n    lines[#lines + 1] = \"Frontline (most forward): \" .. front\n\n    -- Own campaign objectives (enemy keysites this side must capture).\n    local objs = S.objectives and S.objectives[side]\n    if objs and #objs > 0 then\n        lines[#lines + 1] = \"Objectives (capture): \" .. table.concat(objs, \", \")\n    else\n        lines[#lines + 1] = \"Objectives: (pending assignment)\"\n    end\n\n    -- Open gunship missions available to request.\n    local ok_m, miss = pcall(M.get_player_missions, side)\n    local msn = (ok_m and miss) or {}   -- or {} \226\134\146 provably a table for the length op\n    lines[#lines + 1] = string.format(\n        \"Open gunship missions: %d  (F10 > Campaign > Request Mission)\", #msn)\n\n    return table.concat(lines, \"\\n\")\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Per-task briefing text (WARZONE-F20/21, eech ai/faction/briefing.c)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n\n-- nearest_own_base_pos(side, pos): position of `side`'s nearest owned base to `pos` (the launch base\n-- the briefing geometry is measured FROM when no explicit origin is supplied \226\128\148 the F-10 list case).\nlocal function nearest_own_base_pos(side, pos)\n    if not pos then return nil end\n    local best, best_d2 = nil, math.huge\n    for name, owner in pairs(S.base_owner or {}) do\n        if owner == side then\n            local bpos = S.base_pos and S.base_pos[name]\n            if bpos then\n                local d2 = cs.dist2d(pos.x, pos.z, bpos.x, bpos.z) ^ 2\n                if d2 < best_d2 then best_d2 = d2; best = bpos end\n            end\n        end\n    end\n    return best\nend\n\n-- brief_for(task, origin_pos): one-paragraph mission briefing \226\128\148 per-type template (M.TEMPLATES) with\n-- the target name substituted (briefing_add_keysite, briefing.c:111) plus the live bearing/range from\n-- `origin_pos` to the objective (briefing_add_position, briefing.c:107). `task` is a board-task record\n-- ({type, target={base,pos}, critical}). origin_pos nil \226\134\146 geometry omitted (template only).\n-- (task/origin_pos are normalised to provable tables with `or {}` \226\128\148 the static analyzer does not narrow\n-- and/or guards on parameters, and this keeps the geometry safe when either is nil, e.g. a task with no\n-- target position or a caller with no launch base.)\nfunction M.brief_for(task, origin_pos)\n    task = task or {}\n    local ttype  = task.type or task.task_type or \"recon\"\n    local tgt    = (task.target and task.target.base) or task.target_base or \"the target area\"\n    local tpos   = (task.target and task.target.pos) or task.target_pos\n    local tmpl   = M.TEMPLATES[ttype] or \"Mission vs %s.\"\n    local body   = string.format(tmpl, tgt)\n    local geo    = \"\"\n    local origin = origin_pos or {}\n    local ox, oz = origin.x, origin.z\n    local tx     = tpos and tpos.x\n    local tz     = tpos and tpos.z\n    if ox and oz and tx and tz then\n        local rng = cs.dist2d(ox, oz, tx, tz) / 1000.0\n        local brg = math.deg(cs.heading_to(ox, oz, tx, tz))\n        if brg < 0 then brg = brg + 360 end\n        geo = string.format(\"  [Bearing %03.0f, %.0f km]\", brg, rng)\n    end\n    return body .. geo .. (task.critical and \"  *PRIORITY*\" or \"\")\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Mission request scaffolding (PILOT-F19)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n\n-- get_player_missions(side): the top open UNASSIGNED player-flyable board tasks, formatted for a\n-- future F-10 menu. Display-only \226\128\148 NO assignment happens (player\226\134\148task link, F19, is not ported yet).\n-- Sorted by the board's own priority ordering (critical \195\1512, assign.c:201-204).\nfunction M.get_player_missions(side)\n    local out = {}\n    for _, t in ipairs(S.board_tasks or {}) do\n        if t.state == \"UNASSIGNED\" and t.side == side and M.PLAYER_FLYABLE[t.type] then\n            out[#out + 1] = t\n        end\n    end\n    table.sort(out, function(a, b)\n        local pa = (a.priority or 1) * (a.critical and 2.0 or 1.0)\n        local pb = (b.priority or 1) * (b.critical and 2.0 or 1.0)\n        return pa > pb\n    end)\n    local top = {}\n    for i = 1, math.min(3, #out) do\n        local t = out[i]\n        local base = (t.target and t.target.base) or \"field\"\n        -- Briefing text (item 3) measured from the side's nearest owned base to the objective (the\n        -- likely launch field), replacing the bare \"type -> target\" line.\n        local origin = nearest_own_base_pos(side, t.target and t.target.pos)\n        top[i] = {\n            id = t.id, type = t.type, target = base,\n            priority = t.priority, critical = t.critical or false,\n            text = string.format(\"%d. %s\", i, M.brief_for(t, origin)),\n        }\n    end\n    return top\nend\n\n-- \226\148\128\226\148\128 Record summary text (for the F-10 \"My Record\" display) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function record_text(rec)\n    local medals = {}\n    for name, _ in pairs(rec.medals or {}) do medals[#medals + 1] = name end\n    return string.format(\"%s  %s | score %d | kills %d (air %d, gnd %d, sea %d, fixed %d) | sorties %d | deaths %d%s\",\n        rec.name, M.RANK[rec.rank] and M.RANK[rec.rank].name or \"?\",\n        rec.score, rec.kills.total, rec.kills.air, rec.kills.ground, rec.kills.sea, rec.kills.fixed,\n        rec.sorties, rec.deaths,\n        (#medals > 0) and (\" | medals: \" .. table.concat(medals, \", \")) or \"\")\nend\n\n-- \226\148\128\226\148\128 Coalition-scoped text output (falls back to whole-server outText) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function out_side(side, text, time)\n    if trigger.action.outTextForCoalition then\n        local ok = pcall(trigger.action.outTextForCoalition, side, text, time)\n        if ok then return end\n    end\n    pcall(trigger.action.outText, text, time)\nend\n\n-- \226\148\128\226\148\128 F-10 menu command handlers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M._menu_request(side)\n    local ok, miss = pcall(M.get_player_missions, side)\n    local ms = (ok and miss) or {}   -- or {} \226\134\146 provably a table\n    if #ms == 0 then\n        out_side(side, \"Campaign: no open gunship missions right now.\", 20)\n        return\n    end\n    local lines = { \"-- Open gunship missions --\" }\n    for _, m in ipairs(ms) do lines[#lines + 1] = m.text end\n    lines[#lines + 1] = \"(To ACCEPT: from inside your aircraft use F10 > Campaign > Request Mission.)\"\n    out_side(side, table.concat(lines, \"\\n\"), 25)\nend\n\n-- NOTE: a DCS coalition-scoped F-10 command cannot identify WHICH player triggered it, so \"My Record\"\n-- shows the whole side roster. Per-player menus require group-scoped commands, which need player\n-- slots/groups to exist first (goals/03 P0). Documented display-only limitation.\nfunction M._menu_record(side)\n    local roster = {}\n    for _, rec in pairs(S.pilots or {}) do\n        if rec.side == side then roster[#roster + 1] = record_text(rec) end\n    end\n    if #roster == 0 then\n        out_side(side, \"Campaign: no pilot records yet on this side.\", 20)\n        return\n    end\n    table.sort(roster)\n    table.insert(roster, 1, \"\226\148\128\226\148\128 Pilot records (this side) \226\148\128\226\148\128\")\n    out_side(side, table.concat(roster, \"\\n\"), 25)\nend\n\n-- \226\148\128\226\148\128 Campaign Stats (Item 2): per-side kill/loss/task/sortie tally to the coalition (display-only) \226\148\128\226\148\128\nfunction M._menu_stats(side)\n    out_side(side, cs.stats_text(), 30)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Player mission assignment + debrief (PILOT-F19, F9/F11/F13)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- `board` (task_board) is hard-required at module load (top of file); the reverse edge is deferred in\n-- task_board (player_flyable_set), so there is no load cycle.\n\n-- Group-scoped text output (falls back to whole-server outText).\nlocal function _out_group(gid, text, time)\n    time = time or 20\n    if gid and trigger.action.outTextForGroup then\n        local ok = pcall(trigger.action.outTextForGroup, gid, text, time)\n        if ok then return end\n    end\n    pcall(trigger.action.outText, text, time)\nend\n\n-- Resolve a group's first unit + its player name (read-only; nil for AI / gone groups).\nlocal function group_player(gname)\n    if not gname or not Group or not Group.getByName then return nil, nil end\n    local g = Group.getByName(gname)\n    if not g then return nil, nil end\n    local u\n    local oku = pcall(function() u = g:getUnit(1) end)\n    if not oku or not u then return nil, nil end\n    local pn\n    pcall(function() pn = u:getPlayerName() end)\n    return u, pn\nend\n\n-- \226\148\128\226\148\128 build_group_menu: this human's own F-10 assignment menu (rebuild-safe) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Group-scoped so the command can identify WHICH player requested (a coalition command cannot \226\128\148\n-- documented limitation on _menu_record). Removes any prior \"Campaign\" submenu for the group first so\n-- re-injection / re-slot never stacks duplicates. pcall-guarded end to end.\nfunction M.build_group_menu(gid, gname, side)\n    if not missionCommands or not gid then return end\n    local arg = { gid = gid, gname = gname, side = side }\n    pcall(function()\n        if missionCommands.removeItemForGroup then\n            pcall(missionCommands.removeItemForGroup, gid, { \"Campaign\" })\n        end\n        local root = missionCommands.addSubMenuForGroup(gid, \"Campaign\")\n        missionCommands.addCommandForGroup(gid, \"Request Mission\", root, M._grp_request,   arg)\n        missionCommands.addCommandForGroup(gid, \"My Mission\",      root, M._grp_mymission, arg)\n        missionCommands.addCommandForGroup(gid, \"My Record\",       root, M._grp_record,    arg)\n    end)\n    cs.dbg(\"pilots\", \"group F-10 menu built for %s (gid=%s, %s)\",\n        tostring(gname), tostring(gid), cs.SIDE_NAME[side] or \"?\")\nend\n\n-- \226\148\128\226\148\128 _grp_request: the player TAKES the top open gunship mission (PILOT-F19) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- The human binds an UNASSIGNED player-flyable board task exactly as an EECH gunship binds its primary\n-- task: the task leaves the AI unassigned pool (board.assign_to_player marks it ASSIGNED with the\n-- player's group as object; EECH reserves such tasks for humans in the assign pass, assign.c:220-255).\n-- NO ledger consume and NO landing-slot reserve (the human airframe is not reserve hardware and occupies\n-- a real DCS slot). A situational brief (target, bearing/range, task purpose) is sent on assignment.\nfunction M._grp_request(arg)\n    local gid, gname, side = arg.gid, arg.gname, arg.side\n    local cur = cs.get_task(gname)\n    if cur and cur.player then\n        _out_group(gid, \"Campaign: you already have an active mission. RTB to complete it first.\")\n        return\n    end\n    -- Top player-flyable UNASSIGNED board task for the side (critical x2 priority, assign.c:201-204).\n    local best, best_p\n    for _, t in ipairs(S.board_tasks or {}) do\n        if t.state == \"UNASSIGNED\" and t.side == side and M.PLAYER_FLYABLE[t.type] then\n            local p = (t.priority or 1) * (t.critical and 2.0 or 1.0)\n            if not best or p > best_p then best, best_p = t, p end\n        end\n    end\n    if not best then\n        _out_group(gid, \"Campaign: no gunship missions available right now - check back shortly.\")\n        cs.dbg(\"pilots\", \"player %s Request Mission: none available (side=%s)\",\n            tostring(gname), cs.SIDE_NAME[side] or \"?\")\n        return\n    end\n    if not board.assign_to_player(best, gname, gid) then\n        _out_group(gid, \"Campaign: that mission was just taken - try again.\")\n        return\n    end\n    -- Snapshot the sortie score/damage baseline so the LAND debrief can score THIS mission.\n    local u, pname = group_player(gname)\n    if pname then\n        local rec = get_or_create(pname, side)\n        rec.sortie_score_start = rec.score\n        rec.sortie_damaged     = false\n    end\n    local origin\n    if u then pcall(function() origin = u:getPosition().p end) end\n    origin = origin or nearest_own_base_pos(side, best.target and best.target.pos)\n    _out_group(gid, \"=== MISSION ASSIGNED ===\\n\" .. M.brief_for(best, origin) ..\n        \"\\nReturn to base after completing the mission to log it.\", 30)\n    cs.dbg(\"pilots\", \"player %s ASSIGNED task #%d %s vs %s (left AI pool, no ledger/slot)\",\n        tostring(gname), best.id, best.type, (best.target and best.target.base) or \"field\")\nend\n\n-- \226\148\128\226\148\128 _grp_mymission: re-show the player's current mission brief \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M._grp_mymission(arg)\n    local gid, gname, side = arg.gid, arg.gname, arg.side\n    local cur = cs.get_task(gname)\n    if not cur or not cur.player then\n        _out_group(gid, \"Campaign: you have no active mission. Use Request Mission to accept one.\")\n        return\n    end\n    local origin\n    local u = group_player(gname)\n    if u then pcall(function() origin = u:getPosition().p end) end\n    origin = origin or nearest_own_base_pos(side, cur.target_pos)\n    _out_group(gid, \"=== CURRENT MISSION ===\\n\" .. M.brief_for(cur, origin), 25)\nend\n\n-- \226\148\128\226\148\128 _grp_record: per-PLAYER record (group scope identifies the pilot) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M._grp_record(arg)\n    local gid, gname = arg.gid, arg.gname\n    local _, pname = group_player(gname)\n    local rec = pname and S.pilots and S.pilots[pname]\n    if not rec then\n        _out_group(gid, \"Campaign: no record yet - fly a mission first.\")\n        return\n    end\n    _out_group(gid, record_text(rec), 25)\nend\n\n-- \226\148\128\226\148\128 on_hit: Purple-Heart damage tracking (PILOT-F13, play_md.c:1245) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Called from reaction's S_EVENT_HIT branch. Marks the target player's record as damaged-this-sortie;\n-- if the pilot survives to the LAND debrief the Purple Heart is awarded. Read-only on the player unit,\n-- inert for AI targets (no getPlayerName).\nfunction M.on_hit(event)\n    if not event or event.id ~= world.event.S_EVENT_HIT then return end\n    local tgt = event.target\n    if not tgt or not tgt.getPlayerName then return end\n    local pname\n    local ok = pcall(function() pname = tgt:getPlayerName() end)\n    if not ok or not pname then return end\n    local rec = S.pilots and S.pilots[pname]\n    if not rec then\n        local side; pcall(function() side = tgt:getCoalition() end)\n        rec = get_or_create(pname, side)\n    end\n    if not rec.sortie_damaged then\n        rec.sortie_damaged = true\n        cs.dbg(\"pilots\", \"%s took damage this sortie (S_EVENT_HIT) -> Purple Heart eligible at debrief\", pname)\n    end\nend\n\n-- \226\148\128\226\148\128 on_debrief: per-sortie mission termination for a PLAYER (PILOT-F9) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Called from reaction's S_EVENT_LAND branch when a human lands completing their registered task.\n-- Mirrors notify_gunship_entity_mission_terminated (helicop.c:693-836) TASK_COMPLETED_SUCCESS path:\n--   points = task score (port proxy: career-score delta earned since assignment, kills accrue via\n--            on_kill, mobile.c:416-424); inc experience (already added live) + inc missions_flown;\n--   award promotion + valour (award_after_score, the cumulative reward spine, F8/F10, helicop.c:750-756);\n--   AIR MEDAL on a 3-success streak (play_md.c:1304-1359); PURPLE HEART if damaged-but-survived\n--   (play_md.c:1245-1296). Read-only on the player unit throughout (guardrail).\nfunction M.on_debrief(u, task, assessment)\n    if not u or not u.getPlayerName or not task then return end\n    local pname\n    local ok = pcall(function() pname = u:getPlayerName() end)\n    if not ok or not pname then return end\n    local side\n    pcall(function() side = u:getCoalition() end)\n    local rec = get_or_create(pname, side)\n\n    local mission_points = rec.score - (rec.sortie_score_start or rec.score)\n    if mission_points < 0 then mission_points = 0 end\n    -- Item 3: EECH award_points_for_task_completion (task.c:508-543) scales task points by the\n    -- completion outcome \226\128\148 FAILURE 0, PARTIAL points>>2 (quarter), SUCCESS full. The port's career\n    -- score accrues from kills (on_kill), so we apply the multiplier to THIS sortie's displayed points\n    -- (documented proxy: there is no separate task-points award to scale). Defaults to success.\n    local task_result = (assessment and assessment.result) or \"success\"\n    if     task_result == \"failure\" then mission_points = 0\n    elseif task_result == \"partial\" then mission_points = math.floor(mission_points / 4) end\n    rec.missions_flown = (rec.missions_flown or 0) + 1   -- inc_player_log_missions_flown (helicop.c:729)\n\n    award_after_score(rec)   -- promotion + valour on cumulative score (announces itself)\n\n    local awarded = {}\n    -- AIR MEDAL: success \226\134\146 streak++, award + reset at AIR_MEDAL_STREAK (play_md.c:1320-1326). Item 3:\n    -- a PARTIAL/FAILURE outcome does not extend the success streak (only a SUCCESS advances it).\n    if task_result == \"success\" then\n        rec.air_medal_counter = (rec.air_medal_counter or 0) + 1\n    end\n    if rec.air_medal_counter >= M.AIR_MEDAL_STREAK then\n        rec.medals[\"Air Medal\"] = (rec.medals[\"Air Medal\"] or 0) + 1\n        rec.air_medal_counter = 0\n        awarded[#awarded + 1] = \"Air Medal\"\n    end\n    -- PURPLE HEART: damaged this sortie AND survived to land (play_md.c:1273-1287).\n    local alive = false\n    pcall(function() alive = u:isExist() end)\n    if rec.sortie_damaged and alive then\n        rec.medals[\"Purple Heart\"] = (rec.medals[\"Purple Heart\"] or 0) + 1\n        awarded[#awarded + 1] = \"Purple Heart\"\n    end\n\n    rec.sortie_damaged     = false\n    rec.sortie_score_start = rec.score   -- baseline for the next sortie\n\n    local msg = string.format(\"MISSION COMPLETE - %s: %s | +%d pts (score %d) | missions %d\",\n        pname, task.task_type or task.type or \"sortie\", mission_points, rec.score, rec.missions_flown)\n    if #awarded > 0 then msg = msg .. \" | AWARDED: \" .. table.concat(awarded, \", \") end\n    info(msg)\n    cs.dbg(\"pilots\", \"DEBRIEF %s: task=%s +%d pts score=%d missions=%d awards=[%s]\",\n        pname, tostring(task.task_type or task.type), mission_points, rec.score, rec.missions_flown,\n        table.concat(awarded, \",\"))\n    local gid\n    pcall(function() gid = u:getGroup():getID() end)\n    _out_group(gid, msg, 20)\nend\n\n-- \226\148\128\226\148\128 award_campaign_medals: campaign medal at win declaration (PILOT-F14) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Called from win_condition.finish(). EECH awards the campaign/theatre medal to the player log at\n-- session complete (award_campaign_medal, play_md.c:1062; campaign.c:1128). Port: one \"Campaign\" medal\n-- per pilot who flew at least one sortie (both sides took part in the campaign).\nfunction M.award_campaign_medals(winner, log_fn)\n    log_fn = log_fn or function() end\n    local n = 0\n    for _, rec in pairs(S.pilots or {}) do\n        if (rec.sorties or 0) > 0 then\n            rec.medals = rec.medals or {}\n            rec.medals[\"Campaign\"] = (rec.medals[\"Campaign\"] or 0) + 1\n            n = n + 1\n        end\n    end\n    if n > 0 then\n        log_fn(string.format(\"pilots: campaign medal awarded to %d participating pilot(s)\", n))\n        cs.dbg(\"pilots\", \"campaign medal awarded to %d participating pilot(s) (winner=%s)\",\n            n, cs.SIDE_NAME[winner] or \"?\")\n    end\nend\n\n-- \226\148\128\226\148\128 F-10 menu build (once, pcall-guarded so a missing API degrades silently) \226\148\128\226\148\128\226\148\128\nfunction M.build_menus(log_fn)\n    log_fn = log_fn or function() end\n    if not missionCommands then log_fn(\"pilots: missionCommands unavailable \226\128\148 F-10 menu skipped\"); return end\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        local ok = pcall(function()\n            local root = missionCommands.addSubMenuForCoalition(side, \"Campaign\")\n            missionCommands.addCommandForCoalition(side, \"Request Mission\", root, M._menu_request, side)\n            missionCommands.addCommandForCoalition(side, \"My Record\",       root, M._menu_record,  side)\n            missionCommands.addCommandForCoalition(side, \"Campaign Stats\",  root, M._menu_stats,   side)  -- Item 2\n        end)\n        if not ok then\n            log_fn(\"pilots: F-10 menu build failed for side \" .. tostring(side))\n            cs.dbg(\"pilots\", \"F-10 menu build FAILED for side %s\", cs.SIDE_NAME[side] or tostring(side))\n        end\n    end\n    log_fn(\"pilots: F-10 'Campaign' menu registered (Request Mission / My Record)\")\n    cs.dbg(\"pilots\", \"F-10 'Campaign' menu registered\")\nend\n\n-- \226\148\128\226\148\128 init (restore-safe: never clobbers an existing S.pilots) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.init(log_fn)\n    log_fn = log_fn or function() end\n    S.pilots = S.pilots or {}\n    local n = 0\n    for _ in pairs(S.pilots) do n = n + 1 end\n    log_fn(string.format(\"pilots init \226\128\148 career substrate ready (%d existing record(s)); dormant until player slots exist\", n))\n    cs.dbg(\"pilots\", \"init: career substrate ready, %d existing record(s)\", n)\nend\n\nreturn M\n"
__modules["reaction"] = "-- reaction.lua\n-- EECH source: aphavoc/source/ai/highlevl/reaction.c\n--\n-- create_task_assigned_reactionary_tasks (line 97): on an OFFENSIVE keysite task being assigned\n--   (GROUND_STRIKE / OCA_STRIKE / OCA_SWEEP / RECON), the OBJECTIVE side scrambles defensive air:\n--   create_reaction_to_offensive_keysite_task_assigned (line 217):\n--     if keysite requires_cap  and not already CAP-tasked  \226\134\146 create_cap_task   (CAP_DURATION)\n--     if keysite requires_barcap and not already BARCAP-tasked \226\134\146 create_barcap_task at\n--        objective + normalise(attacker - objective) * BARCAP_OFFSET (CAP_DURATION)\n--\n-- create_task_completed_reactionary_tasks (line 152): on RECON/BDA/STRIKE completing with SUCCESS:\n--   create_reaction_to_recon_task_completed (line 314):\n--     KEYSITE objective:\n--       if create_sead_tasks_around_keysite() > 1 \226\134\146 BREAK (suppress: strike into SAMs aborted)\n--       if ALIVE:\n--         if troop_insertion_target and eff < min and not tasked \226\134\146 T.I. (+ backup defender T.I.)\n--         if oca_target      \226\134\146 OCA_STRIKE (dedup) + OCA_SWEEP (dedup)\n--         if ground_strike_target and eff >= min \226\134\146 GROUND_STRIKE\n--     GROUP objective:\n--       ANTI_AIRCRAFT group \226\134\146 create_sead_task\n--       frontline group     \226\134\146 create_bai_task\n--   create_reaction_to_strike_task_completed (line 609):\n--     if ground_strike_target and eff >= min \226\134\146 another GROUND_STRIKE ; else if recon_target \226\134\146 BDA\n--\n-- Constants (reaction.c): BARCAP_OFFSET = 6.0*KILOMETRE = 6000 m (line 293);\n--   CAP_DURATION = 30.0*ONE_MINUTE = 1800 s (lines 248/298).\n--\n-- DCS mapping. \"task assigned\" = S_EVENT_BIRTH of the mission group; \"task completed SUCCESS\" =\n-- the mission group RTBs (S_EVENT_LAND) \226\128\148 a shot-down mission never lands, so it is a FAILURE and\n-- triggers NO follow-on (this is the H1 fix: the old port fired follow-ons on group WIPEOUT, which\n-- is EECH's failure case, not success). Every mission registers its exact objective in\n-- campaign_state.active_tasks at spawn, so reactions target the RIGHT keysite (H5 fix), not the\n-- base nearest the attacker's launch field.\n\nlocal cs     = require(\"campaign_state\")\nlocal supply = require(\"supply\")\nlocal ks     = require(\"keysite\")\nlocal imap_m = require(\"imap\")\nlocal fow_m  = require(\"fog_of_war\")\nlocal inst_m = require(\"installations\")\nlocal config = require(\"config\")\nlocal S      = cs.S\nlocal M      = {}\n\n-- \226\148\128\226\148\128 EECH constants \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal BARCAP_OFFSET      = 6000   -- m; reaction.c:293 (6.0 * KILOMETRE)\nlocal CAP_DURATION       = 1800   -- s; reaction.c:248/298 (30.0 * ONE_MINUTE)\nlocal MINIMUM_EFFICIENCY = cs.MINIMUM_EFFICIENCY   -- 0.3; eech ks_dbase.c minimum_efficiency (all types)\nlocal KEYSITE_SEAD_RANGE = 4000   -- m; MAX_KEYSITE_SEAD_RANGE (create_sead_tasks_around_keysite)\nlocal MAX_KEYSITE_SEAD   = 3      -- MAX_KEYSITE_SEAD_COUNT\n\n-- \226\148\128\226\148\128 Per-keysite flags \226\128\148 kind-aware keysite_database rows (ks_dbase.c) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH keys every reaction decision off keysite_database[sub_type].<flag>. The port resolves the\n-- keysite kind from campaign state and returns the matching ks_dbase row:\n--   basing keysites   \226\134\146 AIRBASE (ks_dbase.c:114-129) or FARP (:255-270), both requires_cap TRUE;\n--   installation keysites \226\134\146 the ks_dbase row per zone kind (installations.flags_for_kind).\n-- AIRBASE row: requires_cap T:120, requires_barcap F:121, oca T:124, recon T:125, gs T:126, ti T:128.\n-- FARP    row: requires_cap T:261, requires_barcap F:262, oca F:265, recon T:266, gs T:267, ti T:269.\n-- BARCAP is a CARRIER/ANCHORAGE behaviour (ks_dbase.c ANCHORAGE:168), never airbases/FARPs.\n-- The OLD proxy returned the AIRBASE row for EVERYTHING \226\128\148 wrong for FARPs (would OCA a FARP whose\n-- oca_target is FALSE) and for installation objectives (whole reaction chain assumed airbase rows).\n-- Now every objective's true flags drive react_recon_complete_keysite.\nlocal AIRBASE_FLAGS = {\n    requires_cap = true,  requires_barcap = false, oca_target = true,  ground_strike_target = true,\n    troop_insertion_target = true, recon_target = true,   -- ks_dbase.c:120-128 AIRBASE row\n}\nlocal FARP_FLAGS = {\n    requires_cap = true,  requires_barcap = false, oca_target = false, ground_strike_target = true,\n    troop_insertion_target = true, recon_target = true,   -- ks_dbase.c:261-269 FARP row\n}\nlocal function keysite_flags(base)\n    local bk = S.base_kind and S.base_kind[base]\n    if bk == \"farp\"    then return FARP_FLAGS end\n    if bk == \"airbase\" then return AIRBASE_FLAGS end\n    -- installation keysite: read its zone kind \226\134\146 ks_dbase row (installations.flags_for_kind).\n    local rec = S.keysites and S.keysites[base]\n    if rec then\n        if rec.kind == \"airbase\" then return AIRBASE_FLAGS end   -- \"AB-<name>\" airfield-assets keysite\n        local f = inst_m.flags_for_kind(rec.kind)\n        if f then return f end\n    end\n    -- real DCS airbase not tagged in base_kind (auto/no-zones theatre) \226\134\146 AIRBASE row.\n    return AIRBASE_FLAGS\nend\n\n-- \226\148\128\226\148\128 Aircraft configuration (hoisted to config.lua) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- escort = the CAP/BARCAP fighter; heli = the BDA overflight airframe (config bda_heli).\nlocal AC = {}\nfor _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n    AC[side] = {\n        country = config.C.countries[side],\n        escort  = config.C.types.aircraft[side].escort,\n        heli    = config.C.types.aircraft[side].bda_heli,\n    }\nend\n\n-- Offensive task types that make the objective side scramble CAP/BARCAP (reaction.c:97 switch).\nlocal OFFENSIVE = {\n    ground_strike = true, oca_strike = true, oca_sweep = true, recon = true,\n}\n\n-- \226\148\128\226\148\128 Group-name \226\134\146 task_type classifier \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Aligns with the names set by the spawner modules (Cluster A/B renames).\nlocal function classify(gname)\n    if gname:match(\"^KStrike%-\")    then return \"ground_strike\" end\n    if gname:match(\"^OCAStrike%-\")  then return \"oca_strike\"    end\n    if gname:match(\"^OCA%-Sweep%-\") then return \"oca_sweep\"     end\n    if gname:match(\"^Recon%-\")      then return \"recon\"         end\n    if gname:match(\"^BDA%-\")        then return \"bda\"           end\n    if gname:match(\"^CAP%-\")        then return \"cap\"           end\n    if gname:match(\"^BARCAP%-\")     then return \"barcap\"        end\n    return nil\nend\n\n-- \226\148\128\226\148\128 Helpers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function nearest_base(owner_side, pos)\n    local best, best_d2 = nil, math.huge\n    for name, owner in pairs(S.base_owner) do\n        if owner == owner_side then\n            local bpos = S.base_pos[name]\n            if bpos then\n                local dx = pos.x - bpos.x; local dz = pos.z - bpos.z\n                local d2 = dx*dx + dz*dz\n                if d2 < best_d2 then best_d2 = d2; best = name end\n            end\n        end\n    end\n    return best\nend\n\n-- Nearest owned base of ANY side to a position = its FOW sector (get_local_sector_entity). Used by\n-- the SEAD-ring per-group FOW gate and the counter-battery reaction.\nlocal function nearest_any_base(pos)\n    local best, best_d2 = nil, math.huge\n    for name, bpos in pairs(S.base_pos) do\n        if S.base_owner[name] then\n            local dx = pos.x - bpos.x; local dz = pos.z - bpos.z\n            local d2 = dx*dx + dz*dz\n            if d2 < best_d2 then best_d2 = d2; best = name end\n        end\n    end\n    return best\nend\n\nlocal function efficiency_of(base)\n    return (S.base_efficiency and S.base_efficiency[base])\n        or (S.base_health and S.base_health[base])\n        -- installation keysites: eff = strength/max applies to EVERY keysite type (ks_float.c:260-275);\n        -- without this, strike-complete follow-ons read a destroyed installation as eff=1.0 and\n        -- re-strike it forever.\n        or (S.keysites and S.keysites[base] and S.keysites[base].health)\n        or 1.0\nend\n\n-- Recycle-on-expiry guard shared with supply.make_land_handler (S._recycled). Credits back ONLY the\n-- LIVE survivors of the group at expiry \226\128\148 a flight shot down before its expiry/loiter timer is\n-- already in the regen queue (regen.make_dead_handler), so crediting reserve for it too would\n-- double-count and soften attrition on exactly the flights that die most (MED-1 fix). A group that\n-- RTB'd already had its survivors credited by the land handler (which sets S._recycled), so this\n-- no-ops for it. Airborne-at-expiry (despawned below) \226\134\146 credit its live units.\nlocal function recycle_once(gname, side, role, grp)\n    S._recycled = S._recycled or {}\n    if S._recycled[gname] then return end\n    S._recycled[gname] = true\n    local n = 0\n    if grp and grp.isExist and grp:isExist() then\n        local ok, units = pcall(function() return grp:getUnits() end)\n        if ok and units then\n            for _, u in ipairs(units) do if u and u:isExist() then n = n + 1 end end\n        end\n    end\n    if n > 0 then supply.recycle_side(side, role, n) end\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Defensive spawns: CAP / BARCAP\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- The CAP waypoint carries a ComboTask: EngageTargets (intercept) + Orbit (loiter on-station).\n-- The Orbit keeps the flight on station for the whole CAP_DURATION (EECH's on-station time) rather\n-- than flying through and RTB'ing in minutes. The expiry timer despawns + recycles it (no Land wp).\nlocal function cap_route(ab, ab_pos, bx, by, orbit_x, orbit_z)\n    return { points = {\n        {type=\"TakeOff\",action=\"From Parking Area\",airdromeId=ab:getID(),\n         alt=ab_pos.y,alt_type=\"BARO\",speed=0,ETA=0,ETA_locked=true,x=bx,y=by,name=\"Depart\",formation_template=\"\"},\n        {type=\"Turning Point\",action=\"Turning Point\",alt=7000,alt_type=\"BARO\",speed=250,\n         ETA=0,ETA_locked=false,x=orbit_x,y=orbit_z,name=\"CAP\",formation_template=\"\",\n         task={id=\"ComboTask\",params={tasks={\n           [1]={number=1,auto=true,id=\"EngageTargets\",enabled=true,\n             params={maxDist=60000,priority=0,targetTypes={\"Air\"}}},\n           [2]={number=2,auto=false,id=\"Orbit\",enabled=true,\n             params={pattern=\"Race-Track\", speed=250, altitude=7000,\n                     point={x=orbit_x,y=orbit_z}, point2={x=orbit_x+18000,y=orbit_z}}},\n         }}}},\n    }}\nend\n\n-- Schedule CAP_DURATION expiry: recycle the escort back to reserve (EECH replace_into_force_info\n-- at task expiry) and despawn if still airborne. If it already RTB'd, the land handler recycled it\n-- and the shared once-guard makes this a no-op.\nlocal function schedule_cap_expiry(grp, gname, side, duration)\n    duration = duration or CAP_DURATION\n    local my_gen = _DMT_GEN\n    timer.scheduleFunction(function()\n        if _DMT_GEN ~= my_gen then return nil end   -- stale generation: reset.nuke already cleaned up\n        recycle_once(gname, side, \"escort\", grp)   -- credits only live survivors (dead \226\134\146 regen owns it)\n        ks.release_slot(gname)                     -- Cluster 5: free the base landing slot on despawn\n        if grp and grp:isExist() then grp:destroy() end\n        cs.clear_task(gname)   -- clear registry so the dedup guard frees up for the next reaction\n        return nil\n    end, nil, timer.getTime() + duration)\nend\n\n-- spawn_cap(defending_side, base_name, log_fn [, duration]): duration defaults to CAP_DURATION\n-- (reaction.c:248, 30 min) for the offensive-task-assigned CAP; the under-attack CAP passes its own\n-- 15-min duration (keysite.c:915). Priority/force-assign semantics (keysite.c:915/921) are moot in the\n-- port (defensive CAP is a DIRECT spawn, not a board-priority task).\nlocal function spawn_cap(defending_side, base_name, log_fn, duration)\n    duration = duration or CAP_DURATION\n    -- Consume from the DEFENDED base's own ledger (Cluster 4): the CAP is flown by fighters resident\n    -- at that keysite (assign.c). No resident escort \226\134\146 no CAP (force conservation with location).\n    if not supply.consume_base(base_name, \"escort\", 1) then\n        cs.dbg(\"reaction\", \"%s spawn_cap ABORT at %s: no escort stock\", cs.SIDE_NAME[defending_side], base_name)\n        return false\n    end\n    local cfg = AC[defending_side]\n    local ab  = Airbase.getByName(base_name)\n    if not ab then\n        supply.recycle_base(base_name, \"escort\", 1)\n        cs.dbg(\"reaction\", \"%s spawn_cap ABORT at %s: no Airbase -> refunded\", cs.SIDE_NAME[defending_side], base_name)\n        return false\n    end\n    local ab_pos = ab:getPosition().p\n    local bx, by = cs.wp_xy(ab_pos)\n    local sid    = cs.next_id()\n    local gname  = string.format(\"CAP-%d-%d\", defending_side, sid)\n\n    local grp = coalition.addGroup(cfg.country, Group.Category.AIRPLANE, {\n        name = gname, task = \"CAP\", hidden = false, airdromeId = ab:getID(),\n        units = {{ name=gname..\"-1\", type=cfg.escort, skill=\"High\",\n            x=ab_pos.x, y=ab_pos.z, alt=ab_pos.y, alt_type=\"BARO\", speed=0, heading=0,\n            payload={fuel=5200,flare=120,chaff=120,gun=100} }},\n        route = cap_route(ab, ab_pos, bx, by, bx, by),\n    })\n    if grp then\n        -- Cluster 5: a scrambled CAP occupies a landing slot at the defended base so it counts\n        -- against basing capacity (visible to the board's assignment gate). PROXY: defensive\n        -- scrambles are NOT hard-gated \226\128\148 the base must always be defended, so reaction stays\n        -- responsive even at capacity (EECH's landing arbitration would queue/hold; spec 07 TASK-F23).\n        ks.reserve_slot(base_name, gname)\n        cs.register_task(gname, { task_type=\"cap\", side=defending_side, target_base=base_name,\n                                  target_pos=S.base_pos[base_name], born_time=timer.getTime() })\n        schedule_cap_expiry(grp, gname, defending_side, duration)\n        log_fn(string.format(\"reaction CAP #%d defending %s (dur=%ds)\", sid, base_name, duration))\n        cs.dbg(\"reaction\", \"%s CAP #%d spawned defending %s (dur=%ds)\", cs.SIDE_NAME[defending_side], sid, base_name, duration)\n        return true\n    end\n    supply.recycle_base(base_name, \"escort\", 1)  -- refund: CAP spawn failed\n    cs.dbg(\"reaction\", \"%s CAP #%d SPAWN FAILED at %s -> refunded\", cs.SIDE_NAME[defending_side], sid, base_name)\n    return false\nend\n\nlocal function spawn_barcap(defending_side, obj_pos, attacker_pos, base_name, log_fn)\n    local dx = attacker_pos.x - obj_pos.x\n    local dz = attacker_pos.z - obj_pos.z\n    local len = math.sqrt(dx*dx + dz*dz)\n    if len < 1.0 then return false end\n    dx, dz = dx/len, dz/len\n    local bp_x = obj_pos.x + dx * BARCAP_OFFSET\n    local bp_z = obj_pos.z + dz * BARCAP_OFFSET\n\n    if not supply.consume_base(base_name, \"escort\", 1) then\n        cs.dbg(\"reaction\", \"%s spawn_barcap ABORT at %s: no escort stock\", cs.SIDE_NAME[defending_side], base_name)\n        return false\n    end\n    local cfg = AC[defending_side]\n    local ab  = Airbase.getByName(base_name)\n    if not ab then\n        supply.recycle_base(base_name, \"escort\", 1)\n        cs.dbg(\"reaction\", \"%s spawn_barcap ABORT at %s: no Airbase -> refunded\", cs.SIDE_NAME[defending_side], base_name)\n        return false\n    end\n    local ab_pos = ab:getPosition().p\n    local bx, by = cs.wp_xy(ab_pos)\n    local sid    = cs.next_id()\n    local gname  = string.format(\"BARCAP-%d-%d\", defending_side, sid)\n\n    local grp = coalition.addGroup(cfg.country, Group.Category.AIRPLANE, {\n        name = gname, task = \"CAP\", hidden = false, airdromeId = ab:getID(),\n        units = {{ name=gname..\"-1\", type=cfg.escort, skill=\"High\",\n            x=ab_pos.x, y=ab_pos.z, alt=ab_pos.y, alt_type=\"BARO\", speed=0, heading=0,\n            payload={fuel=5200,flare=120,chaff=120,gun=100} }},\n        route = cap_route(ab, ab_pos, bx, by, bp_x, bp_z),\n    })\n    if grp then\n        ks.reserve_slot(base_name, gname)   -- Cluster 5: occupy a landing slot (responsive proxy, see spawn_cap)\n        cs.register_task(gname, { task_type=\"barcap\", side=defending_side, target_base=base_name,\n                                  target_pos=S.base_pos[base_name], born_time=timer.getTime() })\n        schedule_cap_expiry(grp, gname, defending_side)\n        log_fn(string.format(\"reaction BARCAP #%d at (%.0f,%.0f) dur=%ds\", sid, bp_x, bp_z, CAP_DURATION))\n        cs.dbg(\"reaction\", \"%s BARCAP #%d spawned at (%.0f,%.0f) from %s\", cs.SIDE_NAME[defending_side], sid, bp_x, bp_z, base_name)\n        return true\n    end\n    supply.recycle_base(base_name, \"escort\", 1)  -- refund: BARCAP spawn failed\n    cs.dbg(\"reaction\", \"%s BARCAP #%d SPAWN FAILED from %s -> refunded\", cs.SIDE_NAME[defending_side], sid, base_name)\n    return false\nend\n\n-- \226\148\128\226\148\128 Dedup guard: existing CAP/BARCAP over an objective base for the defender \226\148\128\226\148\128\n-- Mirrors entity_is_object_of_task(objective, TASK_*, objective_side). Independent per type.\nlocal function has_defensive(base_name, defending_side, task_type)\n    return cs.has_task_against(task_type, base_name, defending_side)\nend\n\n-- \226\148\128\226\148\128 react_to_offense: create_reaction_to_offensive_keysite_task_assigned (reaction.c:217) \226\148\128\226\148\128\n-- objective = the target keysite (owned by the defending side). CAP/BARCAP scramble THERE.\nlocal function react_to_offense(objective_base, objective_pos, attacker_pos, log_fn)\n    local defending_side = S.base_owner[objective_base]\n    if defending_side ~= coalition.side.BLUE and defending_side ~= coalition.side.RED then return end\n    local flags = keysite_flags(objective_base)\n\n    local cap_dup, barcap_dup = has_defensive(objective_base, defending_side, \"cap\"),\n                                 has_defensive(objective_base, defending_side, \"barcap\")\n    cs.dbg(\"reaction\", \"%s react_to_offense at %s: requires_cap=%s(dup=%s) requires_barcap=%s(dup=%s)\",\n        cs.SIDE_NAME[defending_side], objective_base, tostring(flags.requires_cap), tostring(cap_dup),\n        tostring(flags.requires_barcap), tostring(barcap_dup))\n    if flags.requires_cap and not cap_dup then\n        spawn_cap(defending_side, objective_base, log_fn)\n    end\n    if flags.requires_barcap and not barcap_dup then\n        spawn_barcap(defending_side, objective_pos, attacker_pos, objective_base, log_fn)\n    end\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Under-attack defensive CAP: notify_keysite_structure_under_attack (keysite.c:854-939)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- EECH's SECOND defensive-CAP path (distinct from the task-assigned reaction above): when a keysite's\n-- STRUCTURE actually takes damage, the owning side scrambles a defensive CAP even if NO task was ever\n-- registered against it. This is the path that covers a HUMAN PLAYER's strike (MP-critical) \226\128\148 a\n-- player's bombs register no AI task, so only the structure-damage notification defends the base.\n-- EECH behaviour (keysite.c:854-939):\n--   \226\128\162 friendly-fire ignored (aggressor side == keysite side, :883-901);\n--   \226\128\162 gated by the ASSIST_TIMER (:903): only if no assistance request is pending \226\128\148 this dedups\n--     sustained bombardment so CAPs don't stack. On firing, ASSIST_TIMER is set to\n--     DEFAULT_KEYSITE_ASSISTANCE_REQUEST_TIMER = ONE_MINUTE + sfrand1()*20 (keysite.h:67) = 60\194\17720 s;\n--   \226\128\162 only if the aggressor is an aircraft (:907) and the keysite is not already CAP-tasked (:909);\n--   \226\128\162 create_cap_task(side, keysite, aggressor, TRUE, 10.0, 15.0*ONE_MINUTE, ...) \226\128\148 priority 10.0,\n--     duration 15 min (keysite.c:915). NB: this is the CAP's OWN duration, NOT the 30-min CAP_DURATION\n--     of the offensive-reaction path (reaction.c:248) \226\128\148 we use the keysite.c value.\n-- Port mapping onto the existing CAP machinery: the 60\194\17720 s assist timer is BOTH the dedup window and,\n-- in the port's event model, the scramble delay (assistance arrives after that time). The CAP is\n-- spawned with UNDER_ATTACK_CAP_DURATION and blocks re-CAP via has_task_against(\"cap\") for its life\n-- (matching EECH's not-already-CAP-tasked gate). Wired from keysite.strike_damage (deterministic\n-- strike on a base) and installations.register_static_death (an airfield-asset building dying \226\128\148 covers\n-- a HUMAN bombing airfield structures, MP-critical); inert from installations.damage (installation\n-- keysites have requires_cap FALSE / no base owner). The old apply_kill_damage caller was removed in\n-- Cluster G (generic kill-proximity bleed deleted \226\128\148 buildings dying IS the EECH under-attack trigger).\nlocal UNDER_ATTACK_CAP_DURATION = 15 * 60   -- s; keysite.c:915 (15.0 * ONE_MINUTE)\n\n-- DEFAULT_KEYSITE_ASSISTANCE_REQUEST_TIMER = ONE_MINUTE + sfrand1()*20 (keysite.h:67). sfrand1 \226\136\136 [-1,1].\nlocal function assist_timer_delay()\n    return 60.0 + (math.random() * 2.0 - 1.0) * 20.0\nend\n\nfunction M.on_keysite_under_attack(base_name, log_fn)\n    log_fn = log_fn or function() end\n    if not base_name then return end\n    local defending_side = S.base_owner[base_name]\n    -- Non-basing keysites (installation names not in base_owner) and neutral sites: no CAP owner.\n    if defending_side ~= coalition.side.BLUE and defending_side ~= coalition.side.RED then return end\n    -- Only keysites that require CAP defend this way (keysite.c:909 \226\134\146 keysite_database.requires_cap).\n    if not keysite_flags(base_name).requires_cap then return end\n\n    -- Assist-timer dedup (keysite.c:903): while a request is pending, no new scramble.\n    S.keysite_assist_timer = S.keysite_assist_timer or {}\n    local now = timer.getTime()\n    if (S.keysite_assist_timer[base_name] or 0) > now then\n        cs.dbg(\"reaction\", \"under-attack CAP SKIP at %s: assist timer pending (%.0fs left)\",\n            base_name, S.keysite_assist_timer[base_name] - now)\n        return\n    end\n    local delay = assist_timer_delay()\n    S.keysite_assist_timer[base_name] = now + delay\n    cs.dbg(\"reaction\", \"%s keysite %s STRUCTURE UNDER ATTACK: assist timer %.0fs \226\134\146 scramble CAP (keysite.c:854-939)\",\n        cs.SIDE_NAME[defending_side], base_name, delay)\n\n    -- Scramble after the assist-timer delay (keysite.c:915 create_cap_task, 15-min duration).\n    local my_gen = _DMT_GEN\n    timer.scheduleFunction(function()\n        if _DMT_GEN ~= my_gen then return nil end            -- stale generation: reset.nuke cleaned up\n        if S.base_owner[base_name] ~= defending_side then return nil end   -- base flipped in the interim\n        if has_defensive(base_name, defending_side, \"cap\") then            -- keysite.c:909 not-already-CAP\n            cs.dbg(\"reaction\", \"under-attack CAP at %s: already CAP-tasked, no scramble\", base_name)\n            return nil\n        end\n        if spawn_cap(defending_side, base_name, log_fn, UNDER_ATTACK_CAP_DURATION) then\n            log_fn(string.format(\"reaction: %s under attack \226\134\146 defensive CAP scrambled (dur=%ds)\",\n                base_name, UNDER_ATTACK_CAP_DURATION))\n        end\n        return nil\n    end, nil, now + delay)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- SEAD suppression gate: create_sead_tasks_around_keysite (reaction.c:386, highlevl.c:2576)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Count enemy AA groups within KEYSITE_SEAD_RANGE of the objective; spawn SEAD against up to\n-- MAX_KEYSITE_SEAD of them. Returns the count. Caller aborts the strike follow-ons if it is > 1\n-- (strike into intact SAM coverage is suppressed until SEAD clears the way).\nlocal function is_aa_unit(u)\n    local desc = u:getDesc()\n    local a = desc and desc.attributes\n    return a and (a[\"SAM\"] or a[\"AAA\"] or a[\"SR SAM\"] or a[\"MR SAM\"] or a[\"LR SAM\"] or a[\"IR Guided SAM\"])\nend\n\nlocal function create_sead_around_keysite(attacking_side, objective_pos, log_fn)\n    -- SEAD is flown by the ATTACKER against the objective's (enemy) air defences.\n    local aa_side = cs.ENEMY[attacking_side]\n    local grps = coalition.getGroups(aa_side)\n    if not grps then return 0 end\n    local r2 = KEYSITE_SEAD_RANGE * KEYSITE_SEAD_RANGE\n    local cas_m = require(\"cas_bai_sead\")\n    local count, n_fogged = 0, 0\n    for _, grp in ipairs(grps) do\n        if count >= MAX_KEYSITE_SEAD then break end\n        if grp and grp:isExist() then\n            local u = grp:getUnit(1)\n            if u and u:isExist() and is_aa_unit(u) then\n                local gp = u:getPosition().p\n                local dx = gp.x - objective_pos.x\n                local dz = gp.z - objective_pos.z\n                if dx*dx + dz*dz <= r2 then\n                    -- Per-group FOW gate (highlevl.c:2653): only SEAD an AA group whose OWN sector is\n                    -- revealed to the attacker (FOW > 0.25*max) \226\128\148 do not SEAD SAMs we cannot yet see.\n                    -- fow_m.get returns raw/FOW_MAX (normalised 0..1), so the gate is a bare > 0.25.\n                    local sect = nearest_any_base(gp)\n                    local fv   = (sect and fow_m.get(sect, attacking_side)) or 0.0\n                    if fv > 0.25 then\n                        if cas_m.spawn_sead_against(attacking_side, grp, log_fn, true) then   -- highlevl.c:2659 critical=TRUE\n                            count = count + 1\n                        end\n                    else\n                        n_fogged = n_fogged + 1\n                    end\n                end\n            end\n        end\n    end\n    if n_fogged > 0 then\n        cs.dbg(\"reaction\", \"%s SEAD gate: %d in-range AA skipped (sector fogged, FOW<=0.25, highlevl.c:2653)\",\n            cs.SIDE_NAME[attacking_side], n_fogged)\n    end\n    if count > 0 then\n        log_fn(string.format(\"reaction SEAD gate: %d AA within %dm of objective \226\134\146 SEAD\", count, KEYSITE_SEAD_RANGE))\n    end\n    cs.dbg(\"reaction\", \"%s SEAD gate: %d SEAD tasks created within %dm of objective (cap=%d, suppress follow-ons if >1)\",\n        cs.SIDE_NAME[attacking_side], count, KEYSITE_SEAD_RANGE, MAX_KEYSITE_SEAD)\n    return count\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Completion reactions\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n\n-- Keysite owner + position resolvers that also cover non-airbase INSTALLATION objectives (which live\n-- in S.keysites, not S.base_owner/S.base_pos). Installations reach here once Cluster I removed the\n-- pick_targets carve-out: a recon_target=TRUE installation (refinery/power/radar/military_base) takes\n-- the recon fork, so its recon completion drives this same reaction with the installation's true flags.\n-- Wave 1: these three now delegate to the unified keysite accessor (keysite.get), which resolves the\n-- basing (S.base_owner/pos/health) and installation (S.keysites) namespaces with the SAME precedence\n-- these helpers used to hand-roll. Behaviour is identical, including the \"unknown base \226\134\146 nil owner/pos,\n-- 1.0 health\" tails (ks.get returns nil for an unknown name; the `or 1.0` reproduces keysite_health's).\nlocal function keysite_owner(base)\n    local v = ks.get(base)\n    return v and v.owner\nend\nlocal function keysite_pos(base)\n    local v = ks.get(base)\n    return v and v.pos\nend\nlocal function keysite_health(base)\n    local v = ks.get(base)\n    return v and v.health or 1.0\nend\n\n-- create_reaction_to_recon_task_completed \226\128\148 KEYSITE objective branch (reaction.c:375-520)\nlocal function react_recon_complete_keysite(attacking_side, target_base, log_fn)\n    if not target_base then return end\n    if keysite_owner(target_base) == attacking_side then return end   -- objective must be enemy (line 353)\n\n    local objective_pos = keysite_pos(target_base)\n    local is_basing     = S.base_owner[target_base] ~= nil            -- real airbase/FARP (capturable)\n    local flags = keysite_flags(target_base)                          -- kind-aware ks_dbase row\n    local eff   = efficiency_of(target_base)\n\n    -- SEAD gate (reaction.c:386): if surrounding AA > 1 \226\134\146 abort follow-ons, create SEAD instead.\n    if objective_pos and create_sead_around_keysite(attacking_side, objective_pos, log_fn) > 1 then\n        log_fn(string.format(\"reaction: %s defended by SAMs \226\134\146 strike suppressed, SEAD only\", target_base))\n        cs.dbg(\"reaction\", \"%s recon-complete(keysite) at %s SUPPRESSED: SAM gate\", cs.SIDE_NAME[attacking_side], target_base)\n        return\n    end\n\n    -- INT_TYPE_ALIVE gate (reaction.c:391): a destroyed keysite gets no new strikes.\n    if keysite_health(target_base) <= cs.HEALTH_DESTROYED then\n        log_fn(string.format(\"reaction: %s already destroyed \226\134\146 no follow-on\", target_base))\n        cs.dbg(\"reaction\", \"%s recon-complete(keysite) at %s ABORT: destroyed\", cs.SIDE_NAME[attacking_side], target_base)\n        return\n    end\n\n    cs.dbg(\"reaction\", \"%s recon-complete(keysite) at %s: eff=%.2f basing=%s ti_target=%s oca_target=%s ground_target=%s\",\n        cs.SIDE_NAME[attacking_side], target_base, eff, tostring(is_basing), tostring(flags.troop_insertion_target),\n        tostring(flags.oca_target), tostring(flags.ground_strike_target))\n\n    local atk_m   = require(\"attack_waves\")\n    local cas_m   = require(\"cas_bai_sead\")\n    local troop_m = require(\"troop\")\n\n    -- Troop insertion (reaction.c:402) \226\128\148 efficiency below minimum, deduped, TARGETED at this\n    -- keysite (reaction.c:413 passes the objective), + backup defender T.I. (reaction.c:429).\n    -- PROXY: the port's capture mechanic exists only for BASING keysites (do_capture flips\n    -- S.base_owner). An installation may be troop_insertion_target=TRUE in ks_dbase (factory :222,\n    -- military_base :316) but the port has no installation-capture path, so T.I. follow-ons are\n    -- gated to basing keysites; installations are neutralised by strike/artillery attrition instead.\n    if flags.troop_insertion_target and eff < MINIMUM_EFFICIENCY and is_basing\n       and not cs.has_task_against(\"troop_insertion\", target_base, attacking_side) then\n        pcall(troop_m.run_troop_insertion, attacking_side, log_fn, target_base)\n        log_fn(string.format(\"reaction: %s eff=%.2f<min \226\134\146 T.I.\", target_base, eff))\n        -- Backup DEFENDER troop insertion: if the objective side has < 2 patrols there.\n        local defender = S.base_owner[target_base]\n        if defender ~= attacking_side\n           and not cs.has_task_against(\"troop_insertion\", target_base, defender) then\n            pcall(troop_m.run_troop_insertion, defender, log_fn, target_base)\n            log_fn(string.format(\"reaction: backup defender T.I. at %s\", target_base))\n        end\n    end\n\n    -- OCA (reaction.c:455): OCA strike (targeted) + OCA sweep, each deduped. The sweep is created ON\n    -- the recon'd objective (reaction.c:469-471 passes `objective`), NOT a fresh generator scan that\n    -- could hit a different base and double-charge the generator's 2-task budget. oca_target is FALSE\n    -- for FARPs and every installation, so this whole block is airbase-only in practice.\n    if flags.oca_target then\n        if not cs.has_task_against(\"oca_strike\", target_base, attacking_side) then\n            pcall(atk_m.run_oca_strike, attacking_side, log_fn, target_base, true)   -- reaction.c:459 critical=TRUE\n        end\n        if not cs.has_task_against(\"oca_sweep\", target_base, attacking_side) then\n            -- reaction.c:471 create_oca_sweep_task critical=TRUE \226\128\148 oca_sweep is already in board.M.CRITICAL,\n            -- so the follow-on is critical without threading an override through run_oca_sweep.\n            pcall(cas_m.run_oca_sweep, attacking_side, log_fn, target_base, objective_pos)\n        end\n    end\n\n    -- Ground strike (reaction.c:482): only if efficiency >= minimum. EECH does NOT dedup this\n    -- follow-on (creates unconditionally), so we don't either.\n    if flags.ground_strike_target and eff >= MINIMUM_EFFICIENCY then\n        pcall(atk_m.run_strike, attacking_side, log_fn, target_base, true)   -- reaction.c:486 critical=TRUE\n    end\nend\n\n-- create_reaction_to_recon_task_completed \226\128\148 GROUP objective branch (reaction.c:523-590)\n--   AA group \226\134\146 SEAD ; frontline group \226\134\146 BAI. (#8: the whole group-recon chain was absent before.)\nlocal function react_recon_complete_group(attacking_side, objective, log_fn)\n    local cas_m = require(\"cas_bai_sead\")\n    if objective.kind == \"aa_group\" then\n        if objective.group and objective.group:isExist() then\n            cas_m.spawn_sead_against(attacking_side, objective.group, log_fn, true)   -- reaction.c:540 critical=TRUE\n            log_fn(cs.SIDE_NAME[attacking_side] .. \" reaction: recon of AA group \226\134\146 SEAD\")\n            cs.dbg(\"reaction\", \"%s recon-complete(group aa_group) -> SEAD\", cs.SIDE_NAME[attacking_side])\n        else\n            cs.dbg(\"reaction\", \"%s recon-complete(group aa_group) SKIP: group gone\", cs.SIDE_NAME[attacking_side])\n        end\n    elseif objective.kind == \"frontline_group\" then\n        if objective.pos then\n            cas_m.spawn_bai_against(attacking_side, objective.pos, log_fn, true)   -- reaction.c:583 critical=TRUE\n            log_fn(cs.SIDE_NAME[attacking_side] .. \" reaction: recon of frontline group \226\134\146 BAI\")\n            cs.dbg(\"reaction\", \"%s recon-complete(group frontline_group) -> BAI\", cs.SIDE_NAME[attacking_side])\n        end\n    end\nend\n\n-- create_reaction_to_strike_task_completed (reaction.c:609): repeat strike or send BDA.\nlocal function react_strike_complete(attacking_side, target_base, target_pos, log_fn)\n    if not target_base or S.base_owner[target_base] == attacking_side then return end\n    local eff = efficiency_of(target_base)\n    local atk_m = require(\"attack_waves\")\n    if eff >= MINIMUM_EFFICIENCY then\n        -- EECH creates the follow-on ground strike UNCONDITIONALLY (reaction.c:659-674 \226\128\148 there is NO\n        -- entity_is_object_of_task dedup on this branch, deliberately, spec 05 open-Q5 confirmed). The\n        -- port previously added a has_task_against(\"ground_strike\") guard that throttled EECH's\n        -- strike-pressure loop; removed. (The eff >= minimum_efficiency gate at reaction.c:661 is kept.)\n        log_fn(string.format(\"reaction: strike at %s complete eff=%.2f \226\134\146 follow-on strike\", target_base, eff))\n        cs.dbg(\"reaction\", \"%s strike-complete at %s: eff=%.2f -> follow-on strike (no dedup, reaction.c:659-674)\",\n            cs.SIDE_NAME[attacking_side], target_base, eff)\n        pcall(atk_m.run_strike, attacking_side, log_fn, target_base, true)   -- reaction.c:663 critical=TRUE\n    else\n        -- BDA only if the keysite is a recon_target (reaction.c:676 gates the whole BDA branch on\n        -- keysite_database[sub_type].recon_target), deduped (reaction.c:678-681: not already object of\n        -- RECON or BDA). Cluster I: installations now reach here, and factory/port are recon_target=FALSE\n        -- (ks_dbase.c:219/:360) \226\134\146 no BDA, matching EECH (kind-aware keysite_flags).\n        if keysite_flags(target_base).recon_target\n           and target_pos\n           and not cs.has_task_against(\"bda\", target_base, attacking_side)\n           and not cs.has_task_against(\"recon\", target_base, attacking_side) then\n            log_fn(string.format(\"reaction: strike at %s complete eff=%.2f \226\134\146 BDA\", target_base, eff))\n            cs.dbg(\"reaction\", \"%s strike-complete at %s: eff=%.2f -> BDA\", cs.SIDE_NAME[attacking_side], target_base, eff)\n            M.spawn_bda(attacking_side, target_base, target_pos, log_fn)\n        else\n            cs.dbg(\"reaction\", \"%s strike-complete at %s: eff=%.2f, BDA skip (recon_target=%s / no target_pos / already tasked)\",\n                cs.SIDE_NAME[attacking_side], target_base, eff, tostring(keysite_flags(target_base).recon_target))\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 BDA helicopter (create_bda_task) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal BDA_LOITER_TIME = 3 * 60\n\nfunction M.spawn_bda(attacking_side, target_base, target_pos, log_fn)\n    log_fn = log_fn or function() end\n    local home = nearest_base(attacking_side, target_pos)\n    if not home then\n        cs.dbg(\"reaction\", \"%s spawn_bda ABORT vs %s: no owned base found\", cs.SIDE_NAME[attacking_side], tostring(target_base))\n        return\n    end\n    if not supply.consume_base(home, \"heli\", 1) then\n        cs.dbg(\"reaction\", \"%s spawn_bda ABORT vs %s: no heli stock at %s\", cs.SIDE_NAME[attacking_side], target_base, home)\n        return\n    end   -- BDA heli resident at `home`\n    local cfg = AC[attacking_side]\n    local ab  = Airbase.getByName(home)\n    if not ab then\n        supply.recycle_base(home, \"heli\", 1)\n        cs.dbg(\"reaction\", \"%s spawn_bda ABORT vs %s: %s has no Airbase -> refunded\", cs.SIDE_NAME[attacking_side], target_base, home)\n        return\n    end\n    local ab_pos = ab:getPosition().p\n    local bx, by = cs.wp_xy(ab_pos)\n    local tx, ty = cs.wp_xy(target_pos)\n    local sid    = cs.next_id()\n    local gname  = string.format(\"BDA-%d-%d\", attacking_side, sid)\n\n    local grp = coalition.addGroup(cfg.country, Group.Category.HELICOPTER, {\n        name = gname, task = \"Reconnaissance\", hidden = false, airdromeId = ab:getID(),\n        units = {{ name=gname..\"-1\", type=cfg.heli, skill=\"Good\",\n            x=ab_pos.x, y=ab_pos.z, alt=ab_pos.y, alt_type=\"BARO\", speed=0, heading=0,\n            payload={fuel=2200,flare=60,chaff=60,gun=100} }},\n        route = { points = {\n            {type=\"TakeOff\",action=\"From Parking Area\",airdromeId=ab:getID(),\n             alt=ab_pos.y,alt_type=\"BARO\",speed=0,ETA=0,ETA_locked=true,x=bx,y=by,name=\"Depart\",formation_template=\"\"},\n            {type=\"Turning Point\",action=\"Fly Over Point\",alt=300,alt_type=\"BARO\",speed=60,\n             ETA=0,ETA_locked=false,x=tx,y=ty,name=\"BDA\",formation_template=\"\"},\n        }},\n    })\n    if grp then\n        ks.reserve_slot(home, gname)   -- Cluster 5: occupy a landing slot at the launch base (responsive proxy)\n        cs.register_task(gname, { task_type=\"bda\", side=attacking_side, target_base=target_base,\n            target_pos=target_pos, objective={kind=\"keysite\", base=target_base}, born_time=timer.getTime() })\n        -- BDA \"completes\" after loitering over the target (reveal) \226\134\146 recon-completed reaction.\n        local bda_gen = _DMT_GEN\n        timer.scheduleFunction(function()\n            if _DMT_GEN ~= bda_gen then return nil end   -- stale generation: reset.nuke cleaned up\n            react_recon_complete_keysite(attacking_side, target_base, log_fn)\n            recycle_once(gname, attacking_side, \"heli\", grp)   -- live survivors only (dead \226\134\146 regen)\n            ks.release_slot(gname)                             -- Cluster 5: free the landing slot on despawn\n            if grp and grp:isExist() then grp:destroy() end\n            cs.clear_task(gname)\n            return nil\n        end, nil, timer.getTime() + BDA_LOITER_TIME)\n        log_fn(string.format(\"reaction BDA #%d \226\134\146 %s (loiter %ds)\", sid, target_base, BDA_LOITER_TIME))\n        cs.dbg(\"reaction\", \"%s BDA #%d spawned from %s -> %s\", cs.SIDE_NAME[attacking_side], sid, home, target_base)\n    else\n        supply.recycle_base(home, \"heli\", 1)  -- refund: BDA spawn failed\n        cs.dbg(\"reaction\", \"%s BDA #%d SPAWN FAILED from %s -> refunded\", cs.SIDE_NAME[attacking_side], sid, home)\n    end\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Counter-battery reaction: create_reaction_to_artillery_fire (reaction.c:703-810) \226\128\148 REACT-F13\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- When an artillery group FIRES, the VICTIM side raises a counter-battery task against that battery:\n--   rating = (1 - IMAP_AIR_DEFENCE) + IMAP_SURFACE_DEFENCE + 2*IMAP_BASE_DISTANCE,  max 4.0\n--            (reaction.c:770-778 \226\128\148 all three imaps read for the VICTIM side at the battery's sector)\n--   FOW(battery sector, victim) > 0.5*max \226\134\146 create BAI ; else \226\134\146 create RECON  (reaction.c:780-809)\n-- Dedup: skip if the battery is already object of a counter-battery BAI/RECON (reaction.c:740-744).\n-- This is the SOLE consumer of IMAP_SURFACE_DEFENCE (06-F13) \226\128\148 porting it re-connects that layer.\n-- The port's artillery fires on a timer (cas_bai_sead.run_artillery); each committed shot calls this\n-- with (victim_side, battery_group, battery_pos).\nlocal COUNTER_BATTERY_TTL = 20 * 60   -- s; proxy for \"object of BAI/RECON\" duration (BAI task life)\n-- (nearest_any_base = the battery's FOW sector, get_local_sector_entity reaction.c:750 \226\128\148 hoisted to\n-- the shared helpers section above; also used by the SEAD-ring FOW gate.)\n\nfunction M.on_artillery_fire(victim_side, battery_group, battery_pos, log_fn)\n    log_fn = log_fn or function() end\n    if victim_side ~= coalition.side.BLUE and victim_side ~= coalition.side.RED then return end\n    if not battery_group or not battery_pos then return end\n    local gname = (battery_group.getName and battery_group:getName()) or tostring(battery_group)\n\n    -- Dedup (reaction.c:740-744): battery already object of a counter-battery BAI/RECON.\n    S.counter_battery = S.counter_battery or {}\n    local now = timer.getTime()\n    -- Prune EXPIRED entries on read: fresh Arty-<id> names accumulate over a long campaign (batteries\n    -- die and are re-seeded), so the table would otherwise grow without bound.\n    for k, exp in pairs(S.counter_battery) do\n        if exp <= now then S.counter_battery[k] = nil end\n    end\n    if S.counter_battery[gname] and S.counter_battery[gname] > now then\n        cs.dbg(\"reaction\", \"%s counter-battery SKIP vs %s: already object of BAI/RECON\",\n            cs.SIDE_NAME[victim_side], gname)\n        return\n    end\n\n    -- Sector rating (reaction.c:761-778), read for the VICTIM side at the battery's position.\n    local airdef  = imap_m.get(victim_side, imap_m.AIR_DEFENCE,     battery_pos)\n    local surface = imap_m.get(victim_side, imap_m.SURFACE_DEFENCE, battery_pos)   -- re-connects the layer\n    local bdist   = imap_m.get(victim_side, imap_m.BASE_DISTANCE,   battery_pos)\n    local rating  = (1.0 - airdef) + surface + 2.0 * bdist   -- max_rating = 4.0\n\n    -- FOW of the battery's sector for the victim (reaction.c:780): > 0.5 \226\134\146 BAI, else RECON.\n    local sect = nearest_any_base(battery_pos)\n    local fow  = (sect and fow_m.get(sect, victim_side)) or 0.0\n    S.counter_battery[gname] = now + COUNTER_BATTERY_TTL\n\n    local cas_m = require(\"cas_bai_sead\")\n    if fow > 0.5 then\n        -- Counter-battery BAI is critical=FALSE in EECH (reaction.c:788) \226\128\148 the ONE reaction create_* call\n        -- that is NOT critical. Pass false explicitly (board would otherwise use the M.CRITICAL default,\n        -- which is already false for bai, but this pins it to the C).\n        cas_m.spawn_bai_against(victim_side, battery_pos, log_fn, false)\n        log_fn(string.format(\"%s counter-battery BAI vs artillery (fow=%.2f rating=%.2f/4.0)\",\n            cs.SIDE_NAME[victim_side], fow, rating))\n        cs.dbg(\"reaction\", \"%s counter-battery: FOW %.2f>0.5 -> BAI vs %s (rating=%.2f/4.0)\",\n            cs.SIDE_NAME[victim_side], fow, gname, rating)\n    else\n        local ok_r, recon = pcall(require, \"recon\")\n        if ok_r and recon and recon.spawn_recon then\n            recon.spawn_recon(victim_side, battery_pos, \"CounterBty\", log_fn,\n                { kind = \"frontline_group\", pos = battery_pos, group = battery_group }, true)   -- reaction.c:803 critical=TRUE\n        end\n        log_fn(string.format(\"%s counter-battery RECON vs artillery (fow=%.2f rating=%.2f/4.0)\",\n            cs.SIDE_NAME[victim_side], fow, rating))\n        cs.dbg(\"reaction\", \"%s counter-battery: FOW %.2f<=0.5 -> RECON vs %s (rating=%.2f/4.0)\",\n            cs.SIDE_NAME[victim_side], fow, gname, rating)\n    end\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Event handler\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- BIRTH  = task assigned  \226\134\146 defender scrambles CAP/BARCAP at the objective (from the registered task).\n-- LAND   = task SUCCESS    \226\134\146 completion reaction (strike follow-on / recon-completed chain).\n--          A shot-down mission never lands \226\134\146 no follow-on (EECH fires only on SUCCESS).\nfunction M.make_event_handler(log_fn)\n    log_fn = log_fn or function() end\n    return {\n        onEvent = function(_, event)\n            if event.id == world.event.S_EVENT_BIRTH then\n                -- Pilot career (spec 10 Cluster 6): ensure a record + send the join brief for a human\n                -- unit. pcall-guarded and inert for AI births (returns immediately on no getPlayerName).\n                local ok_pb, pilots = pcall(require, \"pilots\")\n                if ok_pb and pilots then pcall(pilots.on_birth, event) end\n\n                local u = event.initiator\n                if not u or not u.getGroup then return end\n                local ok, grp = pcall(function() return u:getGroup() end)\n                if not ok or not grp or not grp:isExist() then return end\n                local gname = grp:getName()\n                local task  = cs.get_task(gname)\n                -- Only registered offensive tasks trigger a defender reaction.\n                if task and OFFENSIVE[task.task_type] and task.target_base then\n                    local obj_pos   = S.base_pos[task.target_base]\n                    local spawn_pos = u:getPosition().p\n                    if obj_pos then\n                        log_fn(string.format(\"reaction: offensive '%s' vs %s \226\134\146 CAP/BARCAP\", gname, task.target_base))\n                        local okr, err = pcall(react_to_offense, task.target_base, obj_pos, spawn_pos, log_fn)\n                        if not okr then log_fn(\"reaction assign error: \" .. tostring(err)) end\n                    end\n                end\n\n            elseif event.id == world.event.S_EVENT_LAND then\n                local u = event.initiator\n                if not u or not u.getGroup then return end\n                -- A human landing that completes THEIR registered campaign task runs the same completion\n                -- chain as an AI sortie (reactions key off the TASK, not the crew \226\128\148 a player-flown strike\n                -- fires the same defender/BDA follow-ons) AND a per-sortie pilot debrief (PILOT-F9). A\n                -- human WITHOUT a registered task falls through `if not task then return end` unchanged, so\n                -- taskless players are still ignored. The player airframe is NEVER despawned/recycled here\n                -- (that is supply.make_land_handler, which skips players) \226\128\148 read-only on the player unit.\n                local is_player = false\n                if u.getPlayerName then\n                    local okp, pn = pcall(function() return u:getPlayerName() end)\n                    is_player = okp and pn ~= nil and pn ~= false\n                end\n                local ok, grp = pcall(function() return u:getGroup() end)\n                if not ok or not grp then return end\n                local gname = grp:getName()\n                local task  = cs.get_task(gname)\n                if not task then return end\n                S._completed = S._completed or {}\n                if S._completed[gname] then return end     -- fire completion once per mission\n                S._completed[gname] = true\n\n                cs.dbg(\"reaction\", \"LAND event: %s (task=%s side=%s target=%s player=%s) -> completion dispatch\",\n                    gname, task.task_type, cs.SIDE_NAME[task.side], tostring(task.target_base), tostring(is_player))\n                if task.task_type == \"ground_strike\" or task.task_type == \"oca_strike\" then\n                    react_strike_complete(task.side, task.target_base, task.target_pos, log_fn)\n                elseif task.task_type == \"recon\" then\n                    if task.objective and task.objective.kind ~= \"keysite\" then\n                        react_recon_complete_group(task.side, task.objective, log_fn)\n                    else\n                        react_recon_complete_keysite(task.side, task.target_base, log_fn)\n                    end\n                end\n                -- Item 3: assess completion (RTB == EECH TASK_TERMINATED_WAYPOINT_ROUTE_COMPLETE) and\n                -- record the success/partial outcome into the per-side task stats (Item 2).\n                local result, rating = cs.assess_task(task, \"route_complete\")\n                cs.stat_task_result(task.side, result)\n                cs.dbg(\"reaction\", \"assess %s (%s) LAND -> %s (rating=%.2f)\", gname, task.task_type, result, rating)\n                -- Player mission debrief (spec 10 Cluster 6): score + medals for the human who completed\n                -- this task. The assessment feeds the EECH points multiplier (task.c:508-555 \226\128\148\n                -- FAILURE 0 / PARTIAL \194\188 / SUCCESS full). pcall-guarded, read-only on the player unit.\n                if is_player then\n                    local ok_dbf, pilots = pcall(require, \"pilots\")\n                    if ok_dbf and pilots then pcall(pilots.on_debrief, u, task, { result = result, rating = rating }) end\n                end\n                cs.clear_task(gname)\n\n            elseif event.id == world.event.S_EVENT_DEAD then\n                -- Pilot career (spec 10 Cluster 6): record a player's loss (F15/F23). pcall-guarded\n                -- and inert for AI deaths (returns immediately if the dead unit has no getPlayerName).\n                local ok_pd, pilots = pcall(require, \"pilots\")\n                if ok_pd and pilots then pcall(pilots.on_death, event) end\n\n                -- A mission that dies before RTB is a FAILURE: no follow-on (EECH fires only on\n                -- SUCCESS). Just clear the registry entry once the whole group is gone, so it does\n                -- not leak or keep a stale dedup guard that would block future tasks on that target.\n                local u = event.initiator\n                if not u or not u.getGroup then return end\n                local ok, grp = pcall(function() return u:getGroup() end)\n                if not ok or not grp then return end\n                local gname = grp:getName()\n                local task  = cs.get_task(gname)\n                if not task then return end\n                local alive = false\n                local ok2, units = pcall(function() return grp:getUnits() end)\n                if ok2 and units then\n                    for _, uu in ipairs(units) do\n                        if uu and uu:isExist() then alive = true; break end\n                    end\n                end\n                if not alive then\n                    -- Item 3/2: a mission destroyed before RTB is a FAILURE (eech task.c terminated-early\n                    -- path) \226\128\148 record the failed outcome before clearing the registry entry + arrow.\n                    local result = cs.assess_task(task, \"terminated\")\n                    cs.stat_task_result(task.side, result)\n                    cs.dbg(\"reaction\", \"assess %s (%s) DEAD -> %s\", gname, task.task_type, result)\n                    cs.clear_task(gname)\n                end\n\n            elseif event.id == world.event.S_EVENT_HIT then\n                -- Purple-Heart tracking (spec 10 Cluster 6, PILOT-F13): mark a hit player as damaged-\n                -- this-sortie; awarded at the LAND debrief if the pilot survives. pcall-guarded, inert\n                -- for AI targets (no getPlayerName), read-only on the player unit.\n                local ok_ph, pilots = pcall(require, \"pilots\")\n                if ok_ph and pilots then pcall(pilots.on_hit, event) end\n            end\n        end\n    }\nend\n\nreturn M\n"
__modules["recon"] = "-- recon.lua\n-- EECH source: aphavoc/source/ai/highlevl/highlevl.c  create_recon_task (called from the\n--   strike-vs-recon fork in create_bai_tasks:785, create_sead_tasks:2093, create_oca_*_tasks,\n--   create_keysite_strike_tasks:1051) and aphavoc/source/ai/highlevl/reaction.c (recon of AA\n--   groups / frontline groups \226\134\146 SEAD/BAI chain).\n--\n-- THE RECON FORK (the single most important behavioural fix): in EECH the fog-of-war gate on a\n-- strike task is not a filter that drops fogged targets \226\128\148 it is a FORK. When the highest-value\n-- candidate's sector is under-reconned, the task generator creates a RECON task INSTEAD of the\n-- strike. The recon flight overflies the target, which raises that sector's fog-of-war value, so\n-- next cycle the target is revealed and becomes strikeable. Without this, a fogged sector never\n-- generates recon \226\134\146 its FOW never rises \226\134\146 the target is invisible to the tasker forever (a dead\n-- loop). EECH self-heals; the previous port self-stalled.\n--\n-- A recon flight is a fast, high-altitude overflight of the target. Its presence near the target\n-- keysite grants fog-of-war to the recon side via fog_of_war.lua's per-unit recon scan. It draws\n-- from the side's \"recon\" reserve pool, RTBs, and is recycled on landing (supply.make_land_handler).\n\nlocal cs      = require(\"campaign_state\")\nlocal croute  = require(\"croute\")\nlocal ov      = require(\"map_overlay\")\nlocal board   = require(\"task_board\")\nlocal config  = require(\"config\")\nlocal M       = {}\n\n-- \226\148\128\226\148\128 Recon airframe per side (hoisted to config.lua) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Fast, high-flying types for a survivable overflight. Consumes the \"recon\" reserve\n-- pool (distinct from striker/escort), so recon sorties never starve strike packages.\nlocal AC = {}\nfor _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n    AC[side] = { country = config.C.countries[side], recon = config.C.types.aircraft[side].recon }\nend\n\nlocal RECON_ALT   = 8000   -- m AMSL \226\128\148 high overflight\nlocal RECON_SPEED = 300    -- m/s \226\137\136 580 kt \226\128\148 fast dash in/out\n\n-- \226\148\128\226\148\128 build_recon(side, base_name, target_pos, label, log_fn, objective) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- BUILDER (task-board contract): physically spawns one recon overflight FROM base_name toward\n-- target_pos. The board has already consumed 1 \"recon\" from base_name's ledger and refunds on nil.\n-- Returns the DCS group on success, nil on failure. No reserve accounting here (the board owns it).\nlocal function build_recon(side, base_name, target_pos, label, log_fn, objective)\n    log_fn = log_fn or function() end\n    label  = label or \"RECON\"\n    local home_ab = Airbase.getByName(base_name)\n    if not home_ab then\n        cs.dbg(\"recon\", \"%s build_recon ABORT: base %s not found\", cs.SIDE_NAME[side], tostring(base_name))\n        return nil\n    end\n\n    local cfg    = AC[side]\n    local ab_pos = home_ab:getPosition().p\n    local bx, by = cs.wp_xy(ab_pos)\n    local tx, ty = cs.wp_xy(target_pos)\n    local sid    = cs.next_id()\n    local gname  = string.format(\"Recon-%d-%d\", side, sid)\n\n    local grp = coalition.addGroup(cfg.country, Group.Category.AIRPLANE, {\n        name       = gname,\n        task       = \"Reconnaissance\",\n        hidden     = false,\n        airdromeId = home_ab:getID(),\n        units = {{\n            name = gname .. \"-1\", type = cfg.recon, skill = \"High\",\n            x = ab_pos.x, y = ab_pos.z, alt = ab_pos.y, alt_type = \"BARO\",\n            speed = 0, heading = cs.heading_to(ab_pos.x, ab_pos.z, target_pos.x, target_pos.z),\n            payload = { fuel = 5200, flare = 120, chaff = 120, gun = 100 },\n        }},\n        route = { points = croute.expand({\n            { type=\"TakeOff\", action=\"From Parking Area\", airdromeId=home_ab:getID(),\n              alt=ab_pos.y, alt_type=\"BARO\", speed=0, ETA=0, ETA_locked=true,\n              x=bx, y=by, name=\"Depart\", formation_template=\"\" },\n            -- Overfly the target at high speed/altitude \226\128\148 grants fog-of-war on arrival.\n            { type=\"Turning Point\", action=\"Fly Over Point\",\n              alt=RECON_ALT, alt_type=\"BARO\", speed=RECON_SPEED,\n              ETA=0, ETA_locked=false, x=tx, y=ty, name=\"Recon\", formation_template=\"\",\n              -- No EngageTargets task: recon observes, it does not fight.\n            },\n            { type=\"Land\", action=\"Landing\", airdromeId=home_ab:getID(),\n              alt=ab_pos.y, alt_type=\"BARO\", speed=RECON_SPEED, ETA=0, ETA_locked=false,\n              x=bx, y=by, name=\"RTB\", formation_template=\"\" },\n        }, side, { alt=RECON_ALT, alt_type=\"BARO\", speed=RECON_SPEED, name=\"Nav\" })},\n    })\n\n    if grp then\n        cs.register_task(gname, {\n            task_type   = \"recon\",\n            side        = side,\n            target_base = objective and objective.base or nil,\n            target_pos  = target_pos,\n            objective   = objective or { kind = \"keysite\" },\n            born_time   = timer.getTime(),\n        })\n        ov.add_task_arrow(gname, ab_pos, target_pos, side)   -- Item 4: key by group name (clear_task reaps it)\n        log_fn(string.format(\"%s %s RECON #%d from %s \226\134\146 (%.0f,%.0f)\",\n            cs.SIDE_NAME[side], label, sid, home_ab:getName(), target_pos.x, target_pos.z))\n        cs.dbg(\"recon\", \"%s RECON #%d spawned from %s -> obj=%s\", cs.SIDE_NAME[side], sid,\n            home_ab:getName(), objective and (objective.base or objective.kind) or \"pos\")\n        return grp\n    end\n    cs.dbg(\"recon\", \"%s RECON spawn FAILED from %s (addGroup returned nil)\", cs.SIDE_NAME[side], base_name)\n    return nil\nend\n\n-- \226\148\128\226\148\128 spawn_recon(side, target_pos, label, log_fn, objective) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- SINGLE-SHOT EXPORT (unchanged signature; called by apply_fork's recon fork and reaction chains).\n-- Reimplemented as a create_task wrapper with immediate assignment: the board picks the suitable\n-- launch base from the \"recon\" ledger (nearest, in range) and calls build_recon. If no recon\n-- inventory is reachable the task sits UNASSIGNED and retries until its 10-min expiry (then FAILED).\n-- objective (optional) = { kind=\"keysite\"|\"aa_group\"|\"frontline_group\", base=name, group=, pos= }.\n-- Returns true when a task was created (queued or assigned) \226\128\148 the caller uses it as a per-sector\n-- \"task placed\" signal, which holds whether assignment is immediate or deferred.\n-- `critical` (optional, WAVE 3 Item 4): the counter-battery RECON reaction is critical=TRUE\n-- (reaction.c:803 create_recon_task) \226\128\148 reaction.lua passes true there. Generator/apply-fork recon callers\n-- omit it \226\134\146 M.create_task falls back to the M.CRITICAL default (recon is not critical there), unchanged.\nfunction M.spawn_recon(side, target_pos, label, log_fn, objective, critical)\n    log_fn = log_fn or function() end\n    label  = label or \"RECON\"\n    if not target_pos then\n        cs.dbg(\"recon\", \"%s spawn_recon ABORT: no target_pos (label=%s)\", cs.SIDE_NAME[side], label)\n        return false\n    end\n    cs.dbg(\"recon\", \"%s spawn_recon: queueing task (label=%s obj=%s)\", cs.SIDE_NAME[side], label,\n        objective and (objective.base or objective.kind) or \"pos\")\n    board.create_task({\n        type = \"recon\", side = side, count = 1, immediate = true, log_fn = log_fn,\n        critical = critical,   -- nil for generators (M.CRITICAL default); true from counter-battery recon\n        target = { base = objective and objective.base or nil, pos = target_pos,\n                   group = objective and objective.group, objective = objective },\n        builder = function(base_name)\n            return build_recon(side, base_name, target_pos, label, log_fn, objective)\n        end,\n    })\n    return true\nend\n\nreturn M\n"
__modules["regen"] = "-- regen.lua\n-- EECH source: aphavoc/source/entity/special/regen/rg_updt.c\n--   update_server() line 160  \226\128\148 sleep-based tick, period = regen_frequency * modifier\n--   regen_update()  line 199  \226\128\148 dequeue front entry if queue non-empty + keysite usable + reserve > 0\n--   regen_queue_insert() line 763 \226\128\148 ring buffer; when full, oldest is overwritten (front advances)\n--   regen_queue_use()    line 820 \226\128\148 pop front, consume reserve_hardware, spawn via\n--                                   create_landing_faction_members()\n-- EECH source: aphavoc/source/entity/special/regen/regen.h\n--   REGEN_QUEUE_DEFAULT_SIZE = 5\n--   REGEN_QUEUE_MINIMUM_SIZE = 5\n--   REGEN_UPDATE_SLOW   = 1.5\n--   REGEN_UPDATE_MEDIUM = 1.0   \226\134\144 used by get_regen_frequency_difficulty_modifier()\n--   REGEN_UPDATE_FAST   = 0.5\n-- EECH source: aphavoc/source/entity/special/regen/regen.c line 335\n--   get_regen_frequency_difficulty_modifier() returns REGEN_UPDATE_MEDIUM (1.0) always (medium only)\n-- regen_frequency[side] is mission-data driven (parsgen.c:1519); proxy value: 60 s\n-- regen_update blocked when: building not alive OR keysite NOT KEYSITE_STATE_USABLE\n--   \226\134\146 DCS proxy: S.base_health[base] <= cs.HEALTH_NEUTRALISED\n-- regen_update blocked when: reserve_count <= 0\n--   \226\134\146 DCS proxy: supply.available(base, type) <= 0\n-- CLUSTER 4: supply.available/consume are now the PER-BASE ledger (S.base_ledger), so a regenerated\n-- airframe draws from \226\128\148 and is fielded at \226\128\148 its OWN home base's idle inventory (the exact base the\n-- dead group is homed to via nearest_friendly), not a shared side pool. Force conservation with\n-- location: regen at a base with no reserve of that role is blocked even if another base has some.\n--\n-- Types tracked (mirrors ENTITY_SUB_TYPE_REGEN_* enum used to classify dead entities):\n--   REGEN_FIXED_WING  \226\134\146 \"striker\" (group name prefix \"Strike-\")\n--   REGEN_FIXED_WING  \226\134\146 \"escort\"  (group name prefix \"Escort-\")\n--   REGEN_HELICOPTER  \226\134\146 \"heli\"    (group name prefix \"Heli-\", \"Insert-\")\n\nlocal cs     = require(\"campaign_state\")\nlocal supply = require(\"supply\")\nlocal ks     = require(\"keysite\")\nlocal config = require(\"config\")\nlocal S      = cs.S\nlocal M      = {}\n\n-- \226\148\128\226\148\128 EECH constants (exact mirror) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal REGEN_QUEUE_DEFAULT_SIZE       = 5     -- regen.h\nlocal REGEN_UPDATE_MEDIUM            = 1.0   -- regen.h; difficulty modifier\n-- regen_frequency[side] is DATA-DRIVEN per side in EECH (parsgen.c:1519); the campaign-file values\n-- are not in the C tree (spec 08 Open-Q1), so we keep the single 60 s proxy per side with citation.\nlocal REGEN_FREQUENCY_BASE           = 60    -- proxy for regen_frequency[side] (seconds)\nlocal REGEN_PERIOD = REGEN_FREQUENCY_BASE * REGEN_UPDATE_MEDIUM  -- 60 s\n\n-- \226\148\128\226\148\128 Supply-scaled rearm/turnaround (KEYSITE-F9, en_suply.c:95-148) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- rearming_sleep = base_time * ( -(MAX-1)/100 * ammo_supply_level + MAX ), MAX=5 (en_suply.h:67):\n-- 1x turnaround at supply 100, up to ~5x at the 10-point floor. The port's closest surface is the\n-- regen dequeue: a starved base (few crate deliveries \226\128\148 see keysite_repair) rearms its replacements\n-- far more slowly, so an economy under pressure loses operational tempo. base_time = REGEN_PERIOD.\nlocal MAX_REARMING_TIME_SCALING_FACTOR = 5   -- en_suply.h:67\nlocal function rearm_scale(level)\n    level = level or 100\n    return -(MAX_REARMING_TIME_SCALING_FACTOR - 1) / 100 * level + MAX_REARMING_TIME_SCALING_FACTOR\nend\n\n-- \226\148\128\226\148\128 Aircraft type tables (hoisted to config.lua; mirrors force faction data for spawning) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- The \"heli\" reserve is dominated by attack helicopters (EECH's main arm), so regenerated rotary\n-- reinforcements are attack helis (config attack_heli: AH-64D / Mi-24V), not unarmed transports.\n-- regen's local \"heli\" atype = config attack_heli.\nlocal AC = {}\nfor _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n    AC[side] = {\n        country = config.C.countries[side],\n        striker = config.C.types.aircraft[side].striker,\n        escort  = config.C.types.aircraft[side].escort,\n        heli    = config.C.types.aircraft[side].attack_heli,\n    }\nend\n\nlocal REGEN_ALT   = 300   -- m; parking area height proxy\nlocal REGEN_SPEED = 0     -- 0 at TakeOff waypoint\n\n-- \226\148\128\226\148\128 Queue structure \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- S.regen_queue[side][atype] = FIFO list of {base_name, aircraft_type, side}\n-- \"atype\" \226\136\136 {\"striker\", \"escort\", \"heli\"}\n\nlocal TYPES = { \"striker\", \"escort\", \"heli\" }\nlocal SIDES = { coalition.side.BLUE, coalition.side.RED }\n\n-- \226\148\128\226\148\128 Pattern \226\134\146 type mapping (mirrors get_regen_sub_type() switch in rg_updt.c:598) \226\148\128\226\148\128\n-- SINGLE SOURCE (Wave 1): the prefix\226\134\146role table now lives ONCE in supply.lua (supply.PREFIX_ROLES).\n-- classify_group delegates to supply.classify_group, which returns a role only for REGENERATED types\n-- (regen=true) and nil for one-shots \226\128\148 Recon, Ferry, Insert (troop-transport) and Supply (physical\n-- resupply) flights are NOT regenerated; they respawn on demand (recon via the FOW fork, insertions via\n-- the next T.I. task, supply flights via the next keysite_repair supply request). Guaranteed to AGREE\n-- with supply.classify_role for regen types (same table, same order). Kept as a local wrapper so the\n-- caller (make_dead_handler) is untouched.\nlocal function classify_group(name)\n    return supply.classify_group(name)\nend\n\n-- \226\148\128\226\148\128 Nearest friendly base (home base for regen spawn) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function nearest_friendly(side, pos)\n    local best, best_d2 = nil, math.huge\n    for name, owner in pairs(S.base_owner) do\n        if owner == side then\n            local h = S.base_health[name] or 1.0\n            if h >= cs.HEALTH_NEUTRALISED then   -- USABLE iff eff >= min (keysite.c:827-830, inclusive)\n                local bpos = S.base_pos[name]\n                if bpos then\n                    local dx = pos.x - bpos.x\n                    local dz = pos.z - bpos.z\n                    local d2 = dx*dx + dz*dz\n                    if d2 < best_d2 then best_d2 = d2; best = name end\n                end\n            end\n        end\n    end\n    return best\nend\n\n-- \226\148\128\226\148\128 Player-landed veto (rg_updt.c:307-339) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- \"Don't regen if PLAYER landed there\" (rg_updt.c:308). EECH walks the keysite's own groups/members\n-- and returns NULL from regen_update if ANY non-AI (human) member has INT_TYPE_LANDED set\n-- (rg_updt.c:311-339). This is the regen expression of \"players are first-class\": no AI reinforcement\n-- appears at a base a human is currently sitting on the ground at.\n--\n-- Port proxy: the port has no keysite-group membership list, so \"landed among the keysite's groups\" is\n-- proxied by \"a player unit on the ground within PLAYER_LANDED_RADIUS of the base\". The keysite is\n-- owned by `side` (spawn_regen's usable gate runs first), and EECH's keysite-group members are the\n-- keysite owner's, so we scan coalition.getPlayers(side) \226\128\148 own-side players only. 2 km is the\n-- base-vicinity proxy for keysite-group membership (spec 08-F14). Read-only: the player unit is NEVER\n-- touched or destroyed (guardrail). Every DCS call pcall-guarded. Returns true \226\134\146 caller VETOES (delays,\n-- not drops) this regen; the entry stays queued and is retried next tick.\nlocal PLAYER_LANDED_RADIUS = 2000  -- m\n\nlocal function player_landed_at(base_name, side)\n    local bp = S.base_pos and S.base_pos[base_name]\n    if not bp then return false end\n    local ok, players = pcall(coalition.getPlayers, side)\n    if not ok or type(players) ~= \"table\" then return false end\n    for _, u in ipairs(players) do\n        local alive = false\n        pcall(function() alive = u and u.isExist and u:isExist() or false end)\n        if alive then\n            local in_air = true   -- default true \226\134\146 only a CONFIRMED on-ground reading vetoes\n            local oka = pcall(function() in_air = u:inAir() end)\n            if oka and in_air == false then\n                local okp, p = pcall(function() return u:getPosition().p end)\n                if okp and p then\n                    if cs.dist2d(p.x, p.z, bp.x, bp.z) <= PLAYER_LANDED_RADIUS then\n                        return true\n                    end\n                end\n            end\n        end\n    end\n    return false\nend\n\n-- \226\148\128\226\148\128 init() \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.init(log_fn)\n    log_fn = log_fn or function() end\n    S.regen_queue = {}\n    for _, side in ipairs(SIDES) do\n        S.regen_queue[side] = {}\n        for _, atype in ipairs(TYPES) do\n            S.regen_queue[side][atype] = {}\n        end\n    end\n    log_fn(string.format(\"regen: queues initialised (REGEN_QUEUE_DEFAULT_SIZE=%d, period=%ds)\",\n        REGEN_QUEUE_DEFAULT_SIZE, REGEN_PERIOD))\n    cs.dbg(\"regen\", \"queues initialised: size=%d period=%ds\", REGEN_QUEUE_DEFAULT_SIZE, REGEN_PERIOD)\nend\n\n-- \226\148\128\226\148\128 regen_queue_insert (rg_updt.c:763) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Ring buffer: when full, drop OLDEST entry (advance front) and insert newest.\n-- Mirrors EECH: at capacity, rear==front, new entry overwrites oldest slot,\n-- then m1->front = (m1->front + 1) % size.  Count stays at REGEN_QUEUE_DEFAULT_SIZE.\n-- Returns (inserted, evicted_oldest). `evicted_oldest` is true when the ring buffer was full and the\n-- oldest pending regen was overwritten to make room \226\128\148 so the caller can surface the (silent) tempo loss.\nlocal function queue_insert(side, atype, base_name, aircraft_type)\n    local q = S.regen_queue[side][atype]\n    local evicted = false\n    if #q >= REGEN_QUEUE_DEFAULT_SIZE then\n        table.remove(q, 1)  -- drop OLDEST (mirrors ring buffer advancing front past overwritten slot,\n                            -- rg_updt.c:791-794 \226\128\148 overflow overwrites the oldest pending regen, NOT the newest)\n        evicted = true\n    end\n    -- enqueued time drives the supply-scaled turnaround gate in process_queue (KEYSITE-F9).\n    q[#q + 1] = { base_name = base_name, aircraft_type = aircraft_type, enqueued = timer.getTime() }\n    return true, evicted\nend\n\n-- \226\148\128\226\148\128 queue_reseed (capture side-effect, eech keysite.c:1483-1517) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- On keysite capture the new owner's regen queue is reseeded with default groups at the\n-- captured base (EECH AIRBASE: 2\195\151 attack-helo, 2\195\151 recon-attack-helo, 2\195\151 assault-helo,\n-- 2\195\151 CAS, 2\195\151 multi-role \226\128\148 6 rotary + 4 fixed-wing groups). Port proxy: insert heli_n\n-- helicopter + fw_n striker entries for `base_name`. The queue is a fixed-size ring\n-- (REGEN_QUEUE_DEFAULT_SIZE) so it retains the newest 5 per type; the matching reserve\n-- boost (supply.recycle_side in keysite.reseed_regen_on_capture) carries the full +6/+4.\nfunction M.queue_reseed(side, base_name, heli_n, fw_n, log_fn)\n    log_fn = log_fn or function() end\n    if not S.regen_queue or not S.regen_queue[side] then return end\n    local cfg = AC[side]\n    for _ = 1, (heli_n or 0) do\n        queue_insert(side, \"heli\", base_name, cfg and cfg.heli or \"AH-64D\")\n    end\n    for _ = 1, (fw_n or 0) do\n        queue_insert(side, \"striker\", base_name, cfg and cfg.striker or \"F-16C bl.52d\")\n    end\n    log_fn(string.format(\"regen: capture reseed at %s (%s) +%d heli +%d fw queued\",\n        base_name, cs.SIDE_NAME[side] or \"?\", heli_n or 0, fw_n or 0))\n    cs.dbg(\"regen\", \"capture reseed at %s (%s): +%d heli +%d fw queued\",\n        base_name, cs.SIDE_NAME[side] or \"?\", heli_n or 0, fw_n or 0)\nend\n\n-- \226\148\128\226\148\128 make_dead_handler() \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Returns an event handler table for world.addEventHandler().\n-- On S_EVENT_DEAD: classify dead group \226\134\146 add to regen queue.\n-- Mirrors add_entity_to_regen_queue() called from destroy hooks.\nfunction M.make_dead_handler(log_fn)\n    log_fn = log_fn or function() end\n    return {\n        onEvent = function(_, event)\n            if event.id ~= world.event.S_EVENT_DEAD then return end\n            local obj = event.initiator\n            if not obj or not obj.getGroup then return end\n            local ok, grp = pcall(function() return obj:getGroup() end)\n            if not ok or not grp then return end\n\n            -- Players are first-class: a human-piloted airframe is NEVER regen hardware (guardrail). The\n            -- prefix classifier below already rejects player group names, but this explicit getPlayerName\n            -- check makes the invariant unbreakable if a player group is ever named with a tracked prefix\n            -- (goal-03 P1 \"regen dead handler prefix-fragile\"). A player death never queues an AI\n            -- replacement; the fc census still counts the human alive while flying (campaign_state).\n            if obj.getPlayerName then\n                local okp, pn = pcall(function() return obj:getPlayerName() end)\n                if okp and pn then\n                    cs.dbg(\"regen\", \"dead unit is a player (%s) - no regen queue (players first-class)\", tostring(pn))\n                    return\n                end\n            end\n\n            -- Resolve the group name WITHOUT requiring grp:isExist() \226\128\148 on the final unit's death the\n            -- group can already report non-existent, and the slot release must still fire.\n            local okn, gname = pcall(function() return grp:getName() end)\n            if not okn then gname = nil end\n\n            -- Cluster 5: release the base landing slot once the WHOLE sortie is dead (S_EVENT_DEAD\n            -- fires per unit, so release only when no OTHER unit survives). This is the sole release\n            -- path for a board sortie killed before RTB (it has no despawn/loiter timer), so it must\n            -- NOT sit behind the grp:isExist() guard below. The dying unit (event.initiator) is\n            -- excluded from the survivor scan to defeat DCS unit-removal lag (it may still list as\n            -- alive on its own death event). Idempotent + clamped in release_slot.\n            if gname then\n                local dying\n                local okd, dn = pcall(function() return obj.getName and obj:getName() or nil end)\n                if okd then dying = dn end\n                local any_alive = false\n                local oku, us = pcall(function() return grp:getUnits() end)\n                if oku and us then\n                    for _, uu in ipairs(us) do\n                        if uu and uu:isExist() and (not dying or uu:getName() ~= dying) then\n                            any_alive = true; break\n                        end\n                    end\n                end\n                if not any_alive then ks.release_slot(gname) end\n            end\n\n            -- Regen-queue insertion needs a still-valid group (original guard preserved).\n            if not grp:isExist() then return end\n            local gname_s = gname or \"\"   -- provably string for classify_group's :match\n            if gname_s == \"\" then return end\n\n            local atype = classify_group(gname_s)\n            if not atype then return end\n\n            -- Determine side from the dead unit\n            local u = grp:getUnit(1)\n            if not u or not u:isExist() then return end\n            local coal = u:getCoalition()\n            -- DCS coalition: 2=BLUE, 1=RED\n            local side = (coal == 2) and coalition.side.BLUE or coalition.side.RED\n\n            -- Find nearest surviving friendly base as home for regen\n            local upos = u:getPosition().p\n            local home = nearest_friendly(side, upos)\n            if not home then\n                log_fn(string.format(\"regen: dead %s \226\128\148 no friendly base found, skipped\", gname))\n                cs.dbg(\"regen\", \"%s dead, NO friendly base found for regen -> dropped (type=%s)\",\n                    tostring(gname), atype)\n                return\n            end\n\n            -- Determine aircraft type from AC table\n            local ac_type = AC[side] and AC[side][atype] or \"F-16C bl.52d\"\n\n            if not S.regen_queue or not S.regen_queue[side] then return end\n            local _, evicted = queue_insert(side, atype, home, ac_type)\n            log_fn(string.format(\"regen: queued %s (%s) at %s [q=%d/%d]\",\n                gname, atype, home, #S.regen_queue[side][atype], REGEN_QUEUE_DEFAULT_SIZE))\n            cs.dbg(\"regen\", \"queue INSERT: %s (%s/%s) at %s [q=%d/%d]\",\n                gname, cs.SIDE_NAME[side], atype, home, #S.regen_queue[side][atype], REGEN_QUEUE_DEFAULT_SIZE)\n            if evicted then\n                -- The ring buffer was full: EECH overwrites the OLDEST pending regen (rg_updt.c:791-794).\n                -- Now VISIBLE \226\128\148 a saturated regen queue means the oldest queued replacement is lost (tempo hit).\n                log_fn(string.format(\"regen: queue was full for %s/%s \226\128\148 oldest pending regen evicted\",\n                    cs.SIDE_NAME[side], atype))\n                cs.dbg(\"regen\", \"queue OVERFLOW %s/%s: oldest pending regen evicted (tempo loss)\",\n                    cs.SIDE_NAME[side], atype)\n            end\n        end\n    }\nend\n\n-- \226\148\128\226\148\128 Spawn replacement (mirrors create_landing_faction_members at keysite) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function spawn_regen(side, atype, entry, log_fn)\n    local base_name   = entry.base_name\n    local aircraft_type = entry.aircraft_type\n    local cfg         = AC[side]\n    if not cfg then return false end\n\n    -- Blocked: keysite must be usable (mirrors regen_update check)\n    local h = S.base_health[base_name] or 0.0\n    if h < cs.HEALTH_NEUTRALISED then   -- UNUSABLE iff eff < min, strict (keysite.c:827-830)\n        log_fn(string.format(\"regen: %s too damaged (%.0f%%) \226\128\148 regen blocked\", base_name, h*100))\n        cs.dbg(\"regen\", \"spawn BLOCKED: %s too damaged (%.0f%% < neutralised threshold %.0f%%)\",\n            base_name, h * 100, cs.HEALTH_NEUTRALISED * 100)\n        return false\n    end\n\n    -- Blocked: no reserve hardware (mirrors reserve_count <= 0)\n    if supply.available(base_name, atype) <= 0 then\n        log_fn(string.format(\"regen: no %s reserve at %s \226\128\148 regen blocked\", atype, base_name))\n        cs.dbg(\"regen\", \"spawn BLOCKED: no %s reserve at %s\", atype, base_name)\n        return false\n    end\n\n    -- Vetoed: a human player is landed at this base (rg_updt.c:307-339). EECH checks this AFTER the\n    -- reserve gate (rg_updt.c:294 then :311) and returns NULL \226\128\148 a DELAY, not a drop: process_queue\n    -- leaves the entry queued (no pop on false) and retries next tick, exactly as EECH re-attempts the\n    -- pending regen. No reserve is consumed here (consume happens below), so nothing leaks on veto.\n    if player_landed_at(base_name, side) then\n        log_fn(string.format(\"regen: human player landed at %s \226\128\148 regen delayed\", base_name))\n        cs.dbg(\"regen\", \"spawn VETOED: human player landed within %.0fm of %s \226\128\148 regen delayed (retry next tick)\",\n            PLAYER_LANDED_RADIUS, base_name)\n        return false\n    end\n\n    -- Spawn from a real airbase if the base has one, else GROUND-START from its coordinates \226\128\148 a\n    -- synthetic zone-FARP has no Airbase object (same fix as heli_war.build_attack_heli / troop\n    -- insertion). Without this, regen was silently blocked at EVERY padless FARP (the old\n    -- `if not ab then return false end`), so FARP losses never replenished \226\128\148 only Batumi/Kutaisi\n    -- regenerated. FARP reserves are heli-only, so the ground start only ever fields rotary here.\n    local ab = Airbase.getByName(base_name)\n    local ab_pos, ab_id\n    if ab then\n        ab_pos, ab_id = ab:getPosition().p, ab:getID()\n    else\n        local bp = cs.S.base_pos and cs.S.base_pos[base_name]\n        if not bp then\n            cs.dbg(\"regen\", \"spawn BLOCKED: %s has no Airbase and no base_pos\", tostring(base_name))\n            return false\n        end\n        local gy = 0\n        pcall(function() gy = land.getHeight({ x = bp.x, y = bp.z }) or 0 end)\n        ab_pos = { x = bp.x, y = gy, z = bp.z }\n    end\n\n    supply.consume(base_name, atype, 1)\n\n    local bx, by = cs.wp_xy(ab_pos)\n    local id      = cs.next_id()\n    local prefix  = (atype == \"striker\") and \"Regen-Strike\" or\n                    (atype == \"escort\")  and \"Regen-Escort\" or \"Regen-Heli\"\n    local gname   = string.format(\"%s-%d\", prefix, id)\n\n    local cat = (atype == \"heli\") and Group.Category.HELICOPTER or Group.Category.AIRPLANE\n\n    local u = {\n        name     = gname .. \"-1\",\n        type     = aircraft_type,\n        skill    = \"Good\",\n        x        = ab_pos.x,\n        y        = ab_pos.z,\n        alt      = ab_pos.y,\n        alt_type = \"BARO\",\n        speed    = REGEN_SPEED,\n        heading  = 0,\n        payload  = { fuel = 4000, flare = 60, chaff = 60, gun = 100 },\n    }\n\n    local depart\n    if ab_id then\n        depart = { type = \"TakeOff\", action = \"From Parking Area\", airdromeId = ab_id,\n                   alt = ab_pos.y, alt_type = \"BARO\", speed = 0, ETA = 0, ETA_locked = true,\n                   x = bx, y = by, name = \"Depart\", formation_template = \"\" }\n    else\n        depart = { type = \"TakeOffGroundHot\", action = \"From Ground Area Hot\",\n                   alt = ab_pos.y, alt_type = \"BARO\", speed = 0, ETA = 0, ETA_locked = true,\n                   x = bx, y = by, name = \"Depart\", formation_template = \"\" }\n    end\n    local gspec = {\n        name   = gname,\n        task   = (atype == \"heli\") and \"Transport\" or \"Ground Attack\",\n        hidden = false,\n        units  = { u },\n        route  = { points = { depart } },\n    }\n    if ab_id then gspec.airdromeId = ab_id end\n    local grp = coalition.addGroup(cfg.country, cat, gspec)\n\n    if grp then\n        log_fn(string.format(\"regen: spawned %s %s at %s\", gname, aircraft_type, base_name))\n        cs.dbg(\"regen\", \"spawn SUCCESS: %s (%s) at %s\", gname, aircraft_type, base_name)\n        return true\n    end\n    cs.dbg(\"regen\", \"spawn FAILED: %s (%s) at %s (addGroup returned nil)\", gname, aircraft_type, base_name)\n    return false\nend\n\n-- \226\148\128\226\148\128 regen_queue_use (rg_updt.c:820) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Pop front of FIFO, attempt spawn.  If blocked: leave in queue (don't pop).\nlocal function process_queue(side, atype, log_fn)\n    local q = S.regen_queue[side][atype]\n    if not q or #q == 0 then return end\n\n    local entry = q[1]  -- peek front (mirrors m1->front)\n\n    -- Supply-scaled turnaround gate (KEYSITE-F9): the home base's ammo supply level scales the\n    -- required rearm time. A well-supplied base (100) turns a replacement around in REGEN_PERIOD;\n    -- a starved base (floor 10) takes up to ~4.6x as long. Not-yet-ready \226\134\146 leave queued, retry next tick.\n    local level    = (S.base_ammo and S.base_ammo[entry.base_name]) or 100\n    local required = REGEN_PERIOD * rearm_scale(level)\n    local waited   = timer.getTime() - (entry.enqueued or 0)\n    if waited < required then\n        return\n    end\n\n    cs.dbg(\"regen\", \"dequeue attempt: %s/%s front=%s@%s (waited=%.0fs >= required=%.0fs, ammo=%.0f%%)\",\n        cs.SIDE_NAME[side], atype, entry.aircraft_type, entry.base_name, waited, required, level)\n    if spawn_regen(side, atype, entry, log_fn) then\n        table.remove(q, 1)  -- pop (mirrors regen_queue_use advancing front)\n    end\n    -- If blocked: leave in queue (EECH behaviour: regen retries next tick)\nend\n\n-- \226\148\128\226\148\128 schedule_regen() \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors update_server() sleep loop: period = regen_frequency * REGEN_UPDATE_MEDIUM\nfunction M.schedule_regen(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"regen\", \"scheduler REGISTERED offset=%.0fs period=%.0fs\", REGEN_PERIOD, REGEN_PERIOD)\n    timer.scheduleFunction(function(_, t)\n        -- INFRASTRUCTURE: regen keeps running post-victory. EECH's rg_updt.c regen tick is not gated on\n        -- SESSION_COMPLETE (only on the usable/reserve/player-landed gates it already applies), and the\n        -- world runs on after the win banner (fc_msgs.c:163). Cluster E \226\128\148 keep alive; only the\n        -- re-injection guard cancels.\n        if _DMT_GEN ~= my_gen then return nil end\n        if not S.regen_queue then return t + REGEN_PERIOD end\n\n        local ok, err = pcall(function()\n            for _, side in ipairs(SIDES) do\n                for _, atype in ipairs(TYPES) do\n                    process_queue(side, atype, log_fn)\n                end\n            end\n        end)\n        if not ok then log_fn(\"regen tick error: \" .. tostring(err)) end\n\n        return t + REGEN_PERIOD  -- mirrors raw->sleep = regen_frequency * modifier\n    end, nil, timer.getTime() + REGEN_PERIOD)\nend\n\nreturn M\n"
__modules["reset"] = "-- reset.lua\n-- Dev-iteration reset: on EACH injection, nuke the previous campaign so a fresh order-of-battle\n-- starts in the SAME running mission \226\128\148 no DCS restart needed to iterate (edit \226\134\146 build \226\134\146 inject).\n--\n-- What survives a re-inject and must be cleared here:\n--   1. Units/groups placed in the DCS world by the previous campaign (Lua state resets on the\n--      fresh bundle run + the _DMT_GEN generation guard cancels the old run's timers, but the\n--      spawned OBJECTS live in the sim, not in Lua).\n--   2. Event handlers registered via world.addEventHandler (never auto-removed \226\134\146 would stack).\n--   3. F-10 overlay marks (map_overlay ID ranges).\n-- Human players are never touched.\n\nlocal cs = require(\"campaign_state\")\nlocal M  = {}\n\nlocal function group_has_player(g)\n    local ok, units = pcall(function() return g:getUnits() end)\n    if not ok or not units then return false end\n    for _, u in ipairs(units) do\n        local okp, name = pcall(function() return u.getPlayerName and u:getPlayerName() end)\n        if okp and name and name ~= \"\" then return true end\n    end\n    return false\nend\n\nfunction M.nuke(log_fn)\n    log_fn = log_fn or env.info\n    cs.dbg(\"reset\", \"nuke() starting: current generation=%d (old timers with a stale generation self-cancel)\", cs.GENERATION)\n\n    -- 1. Remove the previous injection's event handlers (game_loop tracks them here).\n    local removed_h = 0\n    if type(_G.__dmt_handlers) == \"table\" then\n        for _, h in ipairs(_G.__dmt_handlers) do\n            if pcall(world.removeEventHandler, h) then removed_h = removed_h + 1 end\n        end\n    end\n    _G.__dmt_handlers = {}\n\n    -- 2. Destroy every campaign-spawned group (skip any group holding a human player).\n    local destroyed, skipped = 0, 0\n    for _, side in ipairs({ coalition.side.NEUTRAL, coalition.side.RED, coalition.side.BLUE }) do\n        local ok, groups = pcall(coalition.getGroups, side)\n        if ok and type(groups) == \"table\" then\n            for _, g in ipairs(groups) do\n                if group_has_player(g) then\n                    skipped = skipped + 1\n                else\n                    pcall(function() g:destroy() end)\n                    destroyed = destroyed + 1\n                end\n            end\n        end\n    end\n\n    -- 2b. Destroy CAMPAIGN-SPAWNED statics (template buildings / FARP pads / auto installations) so a\n    -- re-inject re-templates cleanly. Statics survive re-injection (only groups auto-clear), so stale\n    -- template buildings make an empty keysite look populated \226\134\146 the template + its garrison get skipped.\n    -- Match campaign name prefixes ONLY (KS-/FARP-/Inst-); author-placed statics keep their own names.\n    local ds = 0\n    for _, side in ipairs({ coalition.side.NEUTRAL, coalition.side.RED, coalition.side.BLUE }) do\n        local ok, objs = pcall(coalition.getStaticObjects, side)\n        if ok and type(objs) == \"table\" then\n            for _, so in ipairs(objs) do\n                local okn, nm = pcall(function() return so:getName() end)\n                if okn and type(nm) == \"string\" and\n                   (nm:match(\"^KS%-\") or nm:match(\"^FARP%-\") or nm:match(\"^Inst%-\")) then\n                    pcall(function() so:destroy() end)\n                    ds = ds + 1\n                end\n            end\n        end\n    end\n\n    -- 3. Clear F-10 overlay marks. Base/column/front marks reuse STABLE ids (map_overlay overwrites\n    --    them each draw), so only the task-arrow band accumulates. Keep the sweep small \226\128\148 a few\n    --    thousand synchronous removeMark calls in one frame can trip the ANTIFREEZE watchdog.\n    local function clear(a, b) for id = a, b do pcall(trigger.action.removeMark, id) end end\n    clear(10000, 10050)   -- base labels (legacy range; still cleared for stale marks)\n    clear(20000, 20400)   -- task arrows (disabled now, but clear any stale ones)\n    clear(30000, 30010)   -- ground column bands\n    clear(40000, 40010)   -- frontline\n    clear(50000, 50200)   -- installation labels (producers etc.)\n    clear(60000, 60060)   -- base labels (current range \226\128\148 moved off 10000 to dodge stale schedulers)\n    clear(70000, 70400)   -- per-destructible asset indicators (one small \226\150\170 mark per static/scenery)\n\n    log_fn(string.format(\n        \"[reset] fresh start \226\128\148 destroyed %d group(s), %d campaign static(s), skipped %d player group(s), \"\n        .. \"removed %d handler(s), cleared overlay\", destroyed, ds, skipped, removed_h))\n    cs.dbg(\"reset\", \"nuke() done: %d groups destroyed, %d statics destroyed, %d player groups skipped, %d handlers removed\",\n        destroyed, ds, skipped, removed_h)\nend\n\nreturn M\n"
__modules["spawn_queue"] = "-- spawn_queue.lua\n-- Diagnostic + robustness layer: intercept every coalition.addGroup / addStaticObject and DEFER it\n-- into a queue that drains a few spawns per timer tick, instead of spawning ~150-200 groups\n-- synchronously in a single frame at mission start.\n--\n-- WHY: injecting the campaign hard-crashes DCS (~0.07s after init) with C0000005 ACCESS_VIOLATION\n-- in edObjects viLight::QueryEditor, via wSimCalendar::DoActionsUntil \226\134\146 wSimTrace (track recorder).\n-- No Lua error \226\128\148 a DCS-engine null-deref triggered when the sim first advances and processes the\n-- burst of freshly-added groups. Draining one spawn per tick lets the sim advance a frame BETWEEN\n-- each spawn, so (a) if the crash is a volume/burst problem it is avoided entirely, and (b) if it is\n-- one specific unit, the log pinpoints it: the last \">>> SPAWNING #N\" / \"<<< OK #N\" pair with no\n-- following \"#N+1\" is the group whose render/track step crashed the sim.\n--\n-- Callers keep working: addGroup returns a lazy PROXY that delegates to the real DCS group (by name)\n-- once the queued spawn drains. getController() before the real spawn captures setTask/pushTask and\n-- replays them on drain (ground_forces / cas artillery set a task immediately after spawning).\n\nlocal cs = require(\"campaign_state\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- Tuning. 1/tick with a 1s gap = maximal isolation for crash bisection. Raise DRAIN_PER_TICK once\n-- the crash trigger is understood (burst-size threshold vs a single bad unit).\nlocal DRAIN_PER_TICK = 4     -- crash root cause was launch lights=0 (not spawn volume), so the burst\n                             -- guard can drain faster; keeps stagger but clears the larger OOB\n                             -- (airbases + AD garrisons + the infrastructure network) in reasonable time\nlocal DRAIN_INTERVAL = 1.0   -- sim seconds between drains\n\nS.spawn_queue = S.spawn_queue or {}\nS._spawn_seq  = S._spawn_seq  or 0\n\n-- Preserve the REAL engine originals across re-injection \226\128\148 never wrap an already-wrapped function.\n_G.__dmt_real_addGroup  = _G.__dmt_real_addGroup  or coalition.addGroup\n_G.__dmt_real_addStatic = _G.__dmt_real_addStatic or coalition.addStaticObject\nlocal real_addGroup  = _G.__dmt_real_addGroup\nlocal real_addStatic = _G.__dmt_real_addStatic\n\n-- \226\148\128\226\148\128 Lazy proxy \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Stands in for the group between enqueue and drain; delegates to the live group by name.\nlocal function make_proxy(name, item)\n    local function live() return Group.getByName(name) end\n    local p = { __queued = true }\n    function p:getName()      return name end\n    function p:isExist()      local g = live(); return g ~= nil and g:isExist() end\n    function p:getUnits()     local g = live(); return g and g:getUnits() or {} end\n    function p:getUnit(i)     local g = live(); return g and g:getUnit(i) or nil end\n    function p:getSize()      local g = live(); return g and g:getSize() or 0 end\n    function p:getID()        local g = live(); return g and g:getID() or -1 end\n    function p:getCategory()  local g = live(); return g and g:getCategory() or nil end\n    function p:getCoalition() local g = live(); return g and g:getCoalition() or nil end\n    function p:destroy()      local g = live(); if g then g:destroy() end end\n    function p:getController()\n        local g = live()\n        if g then return g:getController() end\n        -- Real group not spawned yet: capture tasking to replay on drain.\n        return {\n            setTask    = function(_, t) item.deferred_setTask  = t end,\n            pushTask   = function(_, t) item.deferred_pushTask = t end,\n            resetTask  = function() end,\n            setCommand = function() end,\n            setOption  = function() end,\n        }\n    end\n    return p\nend\n\n-- \226\148\128\226\148\128 Interception \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\ncoalition.addGroup = function(country_id, category, data)\n    S._spawn_seq = S._spawn_seq + 1\n    local name = (data and data.name) or (\"SpawnQ-\" .. S._spawn_seq)\n    local item = { kind = \"group\", country = country_id, category = category, data = data,\n                   name = name, seq = S._spawn_seq }\n    S.spawn_queue[#S.spawn_queue + 1] = item\n    return make_proxy(name, item)\nend\n\ncoalition.addStaticObject = function(country_id, data)\n    S._spawn_seq = S._spawn_seq + 1\n    local name = (data and data.name) or (\"SpawnQ-static-\" .. S._spawn_seq)\n    local item = { kind = \"static\", country = country_id, data = data, name = name, seq = S._spawn_seq }\n    S.spawn_queue[#S.spawn_queue + 1] = item\n    return make_proxy(name, item)\nend\n\n-- \226\148\128\226\148\128 Drain \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Reaching drain tick T proves every spawn done in tick T-1 survived the sim advancing a frame.\nfunction M.drain(log_fn)\n    log_fn = log_fn or env.info\n    local q = S.spawn_queue\n    local n = 0\n    while #q > 0 and n < DRAIN_PER_TICK do\n        local item  = table.remove(q, 1)\n        local utype = (item.data and item.data.units and item.data.units[1] and item.data.units[1].type) or \"?\"\n        log_fn(string.format(\"[spawn_queue] >>> SPAWNING #%d name=%s type=%s kind=%s (%d left)\",\n            item.seq, tostring(item.name), tostring(utype), item.kind, #q))\n        local g\n        if item.kind == \"group\" then\n            local ok, res = pcall(real_addGroup, item.country, item.category, item.data)\n            if ok then g = res else\n                log_fn(string.format(\"[spawn_queue] !!! addGroup THREW #%d: %s\", item.seq, tostring(res)))\n            end\n        else\n            local ok, res = pcall(real_addStatic, item.country, item.data)\n            if ok then g = res end\n        end\n        if g and item.deferred_setTask  then pcall(function() g:getController():setTask(item.deferred_setTask)   end) end\n        if g and item.deferred_pushTask then pcall(function() g:getController():pushTask(item.deferred_pushTask) end) end\n        log_fn(string.format(\"[spawn_queue] <<< OK #%d name=%s spawned=%s\", item.seq, tostring(item.name), tostring(g ~= nil)))\n        n = n + 1\n    end\n    if #q == 0 and not S._spawn_drain_reported and S._spawn_seq > 0 then\n        S._spawn_drain_reported = true\n        log_fn(string.format(\"[spawn_queue] DRAIN COMPLETE \226\128\148 all %d queued spawns executed and survived the loop\",\n            S._spawn_seq))\n        cs.dbg(\"spawn\", \"DRAIN COMPLETE: all %d queued spawns executed\", S._spawn_seq)\n    end\n    return n\nend\n\nfunction M.schedule_drain(log_fn)\n    log_fn = log_fn or env.info\n    local my_gen = _DMT_GEN\n    local function tick(_, t)\n        if _DMT_GEN ~= my_gen then return nil end   -- self-cancel on re-injection\n        M.drain(log_fn)\n        return t + DRAIN_INTERVAL\n    end\n    timer.scheduleFunction(tick, nil, timer.getTime() + DRAIN_INTERVAL)\n    log_fn(string.format(\"[spawn_queue] drain scheduled: %d spawn/tick every %.1fs (%d queued now)\",\n        DRAIN_PER_TICK, DRAIN_INTERVAL, #S.spawn_queue))\n    cs.dbg(\"spawn\", \"drain scheduler REGISTERED offset=%.1fs period=%.1fs rate=%d/tick (%d queued now)\",\n        DRAIN_INTERVAL, DRAIN_INTERVAL, DRAIN_PER_TICK, #S.spawn_queue)\nend\n\nreturn M\n"
__modules["supply"] = "-- supply.lua\n-- Mirrors EECH's per-FORCE hardware reserve system:\n--   aphavoc/source/entity/special/force/force.h   force_info_reserve_hardware[NUM_CATAGORIES]\n--   aphavoc/source/entity/special/force/force.c    add_to_force_info  (spawn \226\134\146 reserve--, force.c:236-241)\n--                                                   remove_from_force_info (death \226\134\146 current--, :270)\n--                                                   replace_into_force_info (RTB recycle \226\134\146 reserve++, :297)\n--   aphavoc/source/ai/faction/parser.c:1303         reserve_hardware seeded once at OOB\n--   aphavoc/source/entity/special/regen/rg_updt.c:287  regen gated on reserve > 0\n--\n-- CLUSTER 4 \226\128\148 PER-BASE IDLE LEDGER: idle hardware now lives in a PER-BASE ledger (S.base_ledger,\n-- counts by role at each owned base), NOT a single per-side pool. This localises EECH's reserve\n-- hardware to keysites \226\128\148 the task engine's resident-group source (assign.c LIST_TYPE_KEYSITE_GROUP).\n-- The per-side pool is the SUM of base ledgers (reserve_side); consume_side/recycle_side stay as\n-- thin wrappers that pick a base internally (the richest owned base) when the caller has no base in\n-- hand. The task board (task_board.lua) consumes from the CHOSEN launch base at assignment time.\n-- Why a proxy: DCS cannot keep hundreds of parked AI aircraft alive (parking/perf), so parked\n-- aircraft are counts, spawned physically only at assignment and despawned on RTB.\n--\n-- PORT PROXY \226\128\148 recycle-on-RTB: shipped EECH has ZERO callers of replace_into_force_info (force.c:\n-- 278-300; verified full-tree grep, spec 02 FORCE-F6) \226\128\148 hardware that lands/withdraws is never\n-- returned. The port credits reserve on RTB (make_land_handler \226\134\146 the LANDING base's ledger) and on\n-- task expiry (reaction.lua) as a reconstruction of the DESIGN intent (force conservation with\n-- location: survivors become idle inventory at the base they landed at, transferable thereafter).\n--\n-- PRODUCTION (this cluster) \226\128\148 the OTHER caller of the replacement mechanism: production keysites\n-- (factory/refinery/port, KEYSITE-F1/F5) accumulate ammo/fuel as cargo crates while alive+owned;\n-- crates restock consumer keysites (KEYSITE-F6/F7/F8, in keysite_repair.lua) and SURPLUS crates\n-- convert to reserve replacement here (convert_reserves \226\134\146 recycle_side). This is a deliberate port\n-- synthesis: shipped EECH keeps aircraft-reserve and keysite-supply on separate ledgers, but the\n-- port has no crate-logistics entities, so production is wired to BOTH surfaces so that destroying\n-- an enemy factory genuinely starves it (the economic-vulnerability gap). Rates: eech ks_dbase.c\n-- factory ammo +1.0/min, refinery fuel +1.0/min; crate size 10 (cargo.h:89,91).\n--\n-- The public API is still keyed by base NAME (so existing call sites are unchanged); a base\n-- name resolves to its owner side via S.base_owner, and all accounting hits that side's pool.\n-- Side-keyed variants (*_side) exist for code that already has the side in hand.\n--\n-- VEHICLE/TROOP reserve discipline: ground reinforcement (ground_forces.lua) draws the \"vehicle\"\n-- pool through the SAME consume_side/recycle_side path (with refund on failure) as aircraft \226\128\148 the\n-- reserve gate is identical (EECH gates vehicle regen on reserves too, rg_updt.c:291). Production's\n-- convert_reserves also replenishes the vehicle/troop pools, so factory loss starves the ground war.\n\nlocal cs = require(\"campaign_state\")\nlocal ks = require(\"keysite\")\nlocal config = require(\"config\")\nlocal S  = cs.S\nlocal M  = {}\n\n-- \226\148\128\226\148\128 Roles \226\134\146 EECH force_info_catagory \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Roles are finer-grained than EECH's 8 categories (striker+escort are both ARMED_FIXED_WING);\n-- the mapping is used only for category-level logging / future per-category reporting. Strength\n-- itself is a live census (campaign_state.count_current_hardware), so this map is informational.\n-- NOTE: the \"troop\" role was REMOVED in Cluster H \226\128\148 it was seeded + credited by fuel-crate conversion\n-- but NO spawner ever drew it (troop insertions consume the \"transport\" role, classify_role Insert\226\134\146\n-- transport), so 1 of the 4 fuel round-robin slots vanished into a dead pool. Insertion troops ride\n-- the transport ledger; ground reinforcement rides \"vehicle\".\nM.ROLES = { \"striker\", \"escort\", \"heli\", \"recon\", \"transport\", \"vehicle\" }\n\nM.ROLE_CATEGORY = {\n    striker   = \"ARMED_FIXED_WING\",\n    escort    = \"ARMED_FIXED_WING\",\n    recon     = \"ARMED_FIXED_WING\",\n    transport = \"UNARMED_FIXED_WING\",\n    heli      = \"ARMED_HELICOPTER\",\n    vehicle   = \"ARMED_ROUTED_VEHICLE\",\n}\n\n-- \226\148\128\226\148\128 Baked scenario: per-owned-base reserve allotment \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- The whole OOB is injected at server start (empty DCS mission). Each base a side owns at\n-- campaign start contributes this allotment to that side's strategic reserve pool. Scaling\n-- the pool with base count keeps the scenario map-agnostic (works on any Caucasus layout).\n-- Mission designers tune the campaign length here: bigger pools = longer war before attrition.\n-- EECH is a helicopter-centric campaign \226\128\148 attack helis fly the bulk of the sorties (anti-armour,\n-- hunter-killer, escort, BDA, troop insertion), so the rotary reserve is the deepest pool.\n-- striker=4 so a SINGLE base can source a full late-phase strike wave; the task board assigns one task\n-- to one base, so a base must be able to field the largest package. Hoisted to config.reserves.per_base.\nlocal RESERVE_PER_BASE = config.C.reserves.per_base\n\n-- \226\148\128\226\148\128 Production \226\134\146 reserve replacement (KEYSITE-F5/F8, force.c replace_into_force_info) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Crate size: eech cargo.h:89,91 CARGO_AMMO_SIZE / CARGO_FUEL_SIZE = 10 supply points per crate.\n-- A production keysite's %/min stock (installations.production_rates) accumulates in S.production;\n-- keysite_repair debits whole crates for consumer restock (deliver_crate), then surplus crates\n-- convert to reserve hardware (convert_reserves). One crate \226\134\146 one reserve unit, round-robin across\n-- the roles that logically consume that commodity:\n--   ammo (factory/port) \226\134\146 the armed shooters that expend ordnance (heli, striker, vehicle)\n--   fuel (refinery/port) \226\134\146 the fuel-hungry mobility/support airframes (escort, recon, transport)\nlocal CRATE_SIZE = 10\nlocal AMMO_RESERVE_ROLES = { \"heli\", \"striker\", \"vehicle\" }\nlocal FUEL_RESERVE_ROLES = { \"escort\", \"recon\", \"transport\" }\n\n-- \226\148\128\226\148\128 Group-name \226\134\146 role classifier: SINGLE SOURCE (RTB recycle + regen) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors get_regen_sub_type()'s entity classification (rg_updt.c:598). ONE ordered prefix\226\134\146role table\n-- feeds BOTH consumers (Wave 1 merge \226\128\148 was two hand-synced tables, here + regen.classify_group):\n--   \226\128\162 classify_role  (RTB recycle) \226\134\146 role for ANY match. Every spawned combat/support group whose lead\n--     unit RTBs is recycled back to its side's reserve (replace_into_force_info), so it MUST recycle the\n--     SAME pool it consumed at spawn. Escort-consuming flights (OCA-Sweep, CAP, BARCAP use cfg.escort) \226\134\146\n--     \"escort\"; heli-consuming flights (BDA, troop Insert, Heli CAP) \226\134\146 \"heli\".\n--   \226\128\162 classify_group (regen queue, called by regen.lua) \226\134\146 role only for REGENERATED types (regen=true);\n--     nil for one-shots (Recon/Ferry/Insert/Supply, regen=false) which respawn on demand, not via the\n--     regen queue. A one-shot SURVIVOR that lands is still recycled to its \"transport\"/\"recon\" pool by\n--     classify_role; one shot down is simply LOST (no regen entry, its picked-up crate lost with it).\n-- Order is LOAD-BEARING: matched top-to-bottom, first hit wins \226\128\148 preserves the original if/elseif order\n-- of both functions exactly (no prefix matches across a regen boundary, so first-hit is unambiguous).\nlocal PREFIX_ROLES = {\n    { pattern = \"^Escort%-\",      role = \"escort\",    regen = true  },\n    { pattern = \"^Regen%-Escort\", role = \"escort\",    regen = true  },\n    { pattern = \"^OCA%-Sweep\",    role = \"escort\",    regen = true  },\n    { pattern = \"^CAP%-\",         role = \"escort\",    regen = true  },\n    { pattern = \"^BARCAP%-\",      role = \"escort\",    regen = true  },\n    { pattern = \"^Strike%-\",      role = \"striker\",   regen = true  },\n    { pattern = \"^Regen%-Strike\", role = \"striker\",   regen = true  },\n    { pattern = \"^KStrike%-\",     role = \"striker\",   regen = true  },\n    { pattern = \"^OCAStrike%-\",   role = \"striker\",   regen = true  },\n    { pattern = \"^CAS%-\",         role = \"striker\",   regen = true  },\n    { pattern = \"^BAI%-\",         role = \"striker\",   regen = true  },\n    { pattern = \"^SEAD%-\",        role = \"striker\",   regen = true  },\n    { pattern = \"^Recon%-\",       role = \"recon\",     regen = false },  -- one-shot: recycled on RTB, not regenerated\n    { pattern = \"^Ferry%-\",       role = \"transport\", regen = false },  -- one-shot\n    { pattern = \"^Insert%-\",      role = \"transport\", regen = false },  -- troop-insert helis \226\134\146 transport pool, one-shot\n    { pattern = \"^Supply%-\",      role = \"transport\", regen = false },  -- physical supply flights \226\134\146 transport pool, one-shot\n    { pattern = \"^Heli\",          role = \"heli\",      regen = true  },\n    { pattern = \"^Regen%-Heli\",   role = \"heli\",      regen = true  },\n    { pattern = \"^BDA%-\",         role = \"heli\",      regen = true  },\n}\nM.PREFIX_ROLES = PREFIX_ROLES   -- exposed as the single source (regen.classify_group delegates here)\n\n-- classify_role(name) \226\134\146 role of the first matching prefix, or nil. RTB recycle: every tracked flight.\nlocal function classify_role(name)\n    for _, e in ipairs(PREFIX_ROLES) do\n        if name:match(e.pattern) then return e.role end\n    end\n    return nil\nend\nM.classify_role = classify_role\n\n-- classify_group(name) \226\134\146 role only when the matched prefix is a REGENERATED type (regen=true); nil for\n-- one-shots and non-matches. Used by regen.lua (single source; agrees with classify_role for regen\n-- types by construction \226\128\148 same table, same order).\nfunction M.classify_group(name)\n    for _, e in ipairs(PREFIX_ROLES) do\n        if name:match(e.pattern) then\n            return e.regen and e.role or nil\n        end\n    end\n    return nil\nend\n\n-- \226\148\128\226\148\128 Init: seed per-side reserve pool from OOB \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Called once from game_loop.start() after keysite.init_base_state().\n-- Mirrors order.c initialise_order_of_battle assigning reserve hardware to each force.\nfunction M.init(log_fn)\n    log_fn = log_fn or function() end\n\n    -- Seed the PER-BASE ledger: each owned base gets RESERVE_PER_BASE idle aircraft by role.\n    -- The per-side pool is now the SUM of these ledgers (reserve_side). This localises EECH's\n    -- reserve hardware to keysites (the assignment engine's resident-group source, assign.c).\n    S.base_ledger = {}\n    for name, owner in pairs(S.base_owner) do\n        if owner == coalition.side.BLUE or owner == coalition.side.RED then\n            local led = {}\n            local k = S.base_kind and S.base_kind[name]\n            local heli_only = (k == \"fob\" or k == \"farp\")\n            for _, role in ipairs(M.ROLES) do\n                if heli_only then\n                    -- FOB/FARP = HELICOPTERS ONLY (ks_dbase.c FARP air_force_capacity SMALL, and the\n                    -- \"FARP only behaviour\" fields): rotary roles resident (heli attack + transport for\n                    -- insertion), NO fixed-wing striker/escort/recon. This is what confines fixed-wing\n                    -- to the few AIRBASEs and makes the FRONT a helicopter war.\n                    led[role] = (role == \"heli\" and config.C.reserves.farp_heli)\n                             or (role == \"transport\" and config.C.reserves.farp_transport) or 0\n                else\n                    led[role] = RESERVE_PER_BASE[role] or 0\n                end\n            end\n            S.base_ledger[name] = led\n        end\n    end\n\n    -- per-side production crate accumulator (KEYSITE-F5). ammo/fuel are supply-points; *_rr are\n    -- round-robin cursors for reserve conversion. Fed by keysite_repair from production_rates.\n    -- *_earmark = whole crates COMMITTED to a pending physical supply flight (supply_flight.lua): a\n    -- crate a consumer keysite has requested but not yet picked up. convert_reserves must NOT convert\n    -- an earmarked crate to reserve hardware (the cargo is claimed by a TASK_SUPPLY \226\128\148 EECH's cargo\n    -- entity is a child of the factory referenced by the supply task, never repurposed; fc_msgs.c:848).\n    -- The count is RECONCILED to live queued supply tasks each keysite_repair tick (supply.set_earmark),\n    -- so an expired/vanished supply task can never leak an earmark.\n    S.production = {\n        [coalition.side.BLUE] = { ammo = 0, fuel = 0, ammo_rr = 0, fuel_rr = 0, ammo_earmark = 0, fuel_earmark = 0 },\n        [coalition.side.RED]  = { ammo = 0, fuel = 0, ammo_rr = 0, fuel_rr = 0, ammo_earmark = 0, fuel_earmark = 0 },\n    }\n\n    -- recycle once-guard: group names already credited back to reserve on landing\n    S._recycled = {}\n\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        log_fn(string.format(\"supply: %s reserve seeded \226\128\148 striker=%d escort=%d heli=%d recon=%d veh=%d\",\n            cs.SIDE_NAME[side],\n            M.reserve_side(side, \"striker\"), M.reserve_side(side, \"escort\"), M.reserve_side(side, \"heli\"),\n            M.reserve_side(side, \"recon\"), M.reserve_side(side, \"vehicle\")))\n        cs.dbg(\"supply\", \"%s reserve seeded: striker=%d escort=%d heli=%d recon=%d veh=%d\",\n            cs.SIDE_NAME[side],\n            M.reserve_side(side, \"striker\"), M.reserve_side(side, \"escort\"), M.reserve_side(side, \"heli\"),\n            M.reserve_side(side, \"recon\"), M.reserve_side(side, \"vehicle\"))\n    end\nend\n\n-- \226\148\128\226\148\128 Side resolution \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function side_of(name)\n    return S.base_owner and S.base_owner[name]\nend\n\n-- \226\148\128\226\148\128 Per-base ledger core (the assignment source) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- ledger(base, role) \226\128\148 idle count of `role` currently parked at `base` (0 if none/unowned).\nfunction M.ledger(base, role)\n    local led = base and S.base_ledger and S.base_ledger[base]\n    return led and (led[role] or 0) or 0\nend\n\n-- consume_base: decrement `count` of `role` from ONE base's ledger. Mirrors add_to_force_info\n-- reserve-- (force.c:241) localised to the launch keysite. false if the base lacks the stock.\nfunction M.consume_base(base, role, count)\n    count = count or 1\n    local led = base and S.base_ledger and S.base_ledger[base]\n    if not led then\n        cs.dbg(\"supply\", \"consume_base FAIL: %s has no ledger (unowned/unknown base)\", tostring(base))\n        return false\n    end\n    local before = led[role] or 0\n    if before < count then\n        cs.dbg(\"supply\", \"consume_base FAIL: %s %s stock=%d < requested=%d\", base, role, before, count)\n        return false\n    end\n    led[role] = before - count\n    cs.dbg(\"supply\", \"consume_base: %s %s %d -> %d (-%d)\", base, role, before, led[role], count)\n    return true\nend\n\n-- Fixed-wing roles can never be resident at a heli-only keysite: the EECH FARP row's air\n-- capacity is rotary (ks_dbase.c:255 KEYSITE_AIR_FORCE_CAPACITY_SMALL + \"FARP only behaviour\");\n-- FARPs get no fixed-wing runway routes (popread.c:1981-2019).\nlocal FIXED_WING_ROLES = { striker = true, escort = true, recon = true }\n\nlocal function heli_only_base(name)\n    local k = S.base_kind and S.base_kind[name]\n    return k == \"farp\" or k == \"fob\"\nend\n\n-- recycle_base: credit `count` of `role` back to ONE base's ledger. Mirrors\n-- replace_into_force_info reserve++ (force.c:297) localised to the recipient keysite.\n-- A FIXED-WING credit aimed at a heli-only FARP/FOB is REDIRECTED to the side's richest\n-- fixed-wing-capable base: convert_reserves' round-robin and refund paths could otherwise stock\n-- striker/escort/recon at a FARP, which the board then assigns but the builder can never launch\n-- (live-observed assign\226\134\146builder-fail\226\134\146refund-to-same-FARP loop that starved the recon-first\n-- strike spine \226\128\148 36 failed recons in 30 min).\nfunction M.recycle_base(base, role, count)\n    count = count or 1\n    if base and FIXED_WING_ROLES[role] and heli_only_base(base) then\n        local owner, redirect, best_n = S.base_owner[base], nil, -1\n        for name, own in pairs(S.base_owner) do\n            if own == owner and not heli_only_base(name) then\n                local n = (S.base_ledger and S.base_ledger[name] and S.base_ledger[name][role]) or 0\n                if n > best_n then best_n = n; redirect = name end\n            end\n        end\n        if redirect then\n            cs.dbg(\"supply\", \"recycle_base: %s is heli-only, %s credit redirected -> %s\", base, role, redirect)\n            base = redirect\n        end\n    end\n    local led = base and S.base_ledger and S.base_ledger[base]\n    if not led then\n        -- base not in ledger (e.g. just captured / neutral) \226\128\148 lazily create it so the credit is not lost.\n        if base and S.base_ledger then\n            led = {}; for _, r in ipairs(M.ROLES) do led[r] = 0 end\n            S.base_ledger[base] = led\n            cs.dbg(\"supply\", \"recycle_base: %s had no ledger, lazily created\", base)\n        else\n            cs.dbg(\"supply\", \"recycle_base FAIL: no base name / no S.base_ledger, credit of %d %s LOST\", count, role)\n            return\n        end\n    end\n    local before = led[role] or 0\n    led[role] = before + count\n    cs.dbg(\"supply\", \"recycle_base: %s %s %d -> %d (+%d)\", base, role, before, led[role], count)\nend\n\n-- Pick the owned base with the MOST of `role` (so we don't fragment stock); nil if none has any.\nlocal function richest_base(side, role)\n    local best, best_n = nil, 0\n    for name, owner in pairs(S.base_owner) do\n        if owner == side then\n            local n = M.ledger(name, role)\n            if n > best_n then best_n = n; best = name end\n        end\n    end\n    return best\nend\n\n-- Pick any owned base to CREDIT (prefer the one with the most of `role`, else the first owned base).\nlocal function any_owned_base(side, role)\n    return richest_base(side, role) or (function()\n        for name, owner in pairs(S.base_owner) do\n            if owner == side and S.base_ledger and S.base_ledger[name] then return name end\n        end\n        return nil\n    end)()\nend\n\n-- \226\148\128\226\148\128 Side-keyed core (EECH force_info operations) \226\128\148 thin wrappers over the ledger \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- reserve_side = SUM of the side's base ledgers (the per-side pool is derived, not stored).\nfunction M.reserve_side(side, role)\n    local total = 0\n    for name, owner in pairs(S.base_owner) do\n        if owner == side then total = total + M.ledger(name, role) end\n    end\n    return total\nend\n\n-- consume_side: caller does not name a base, so pick the richest owned base with >= count and\n-- consume THERE. Mirrors add_to_force_info reserve-- (force.c:241).\nfunction M.consume_side(side, role, count)\n    count = count or 1\n    local base = richest_base(side, role)\n    if not base or M.ledger(base, role) < count then\n        cs.dbg(\"supply\", \"consume_side FAIL: %s has no base with >= %d %s in stock\", cs.SIDE_NAME[side], count, role)\n        return false\n    end\n    return M.consume_base(base, role, count)\nend\n\n-- recycle_side: caller does not name a base, so credit the richest owned base's ledger.\n-- Mirrors replace_into_force_info reserve++ (force.c:297).\nfunction M.recycle_side(side, role, count)\n    count = count or 1\n    local base = any_owned_base(side, role)\n    if not base then\n        cs.dbg(\"supply\", \"recycle_side FAIL: %s owns no base, credit of %d %s LOST\", cs.SIDE_NAME[side], count, role)\n        return\n    end\n    M.recycle_base(base, role, count)\nend\n\n-- \226\148\128\226\148\128 Production economy (KEYSITE-F5/F8) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Credit a side's crate accumulator from its alive producers. rate is %/min (supply-points/min),\n-- minutes = length of the tick (keysite supply tick = 1 min, ks_updt.c KEYSITE_UPDATE_SLEEP_TIMER).\nfunction M.credit_production(side, ammo_rate, fuel_rate, minutes)\n    local acc = S.production and S.production[side]\n    if not acc then return end\n    minutes = minutes or 1\n    acc.ammo = acc.ammo + (ammo_rate or 0) * minutes\n    acc.fuel = acc.fuel + (fuel_rate or 0) * minutes\nend\n\n-- Debit ONE crate of `commodity` (\"ammo\"|\"fuel\") for a keysite delivery; true if a crate was\n-- available (KEYSITE-F8: one crate delivery restocks a consumer keysite to 100). In the PHYSICAL\n-- supply-flight model this is the PICK_UP debit (taskgen.c:1638 WAYPOINT_PICK_UP): the crate leaves\n-- the producer the moment the transport is spawned. A flight shot down after pick-up = crate LOST\n-- (already debited, never refunded) \226\128\148 the interceptable-economy point of the feature.\nfunction M.deliver_crate(side, commodity)\n    local acc = S.production and S.production[side]\n    if not acc or (acc[commodity] or 0) < CRATE_SIZE then return false end\n    acc[commodity] = acc[commodity] - CRATE_SIZE\n    cs.dbg(\"supply\", \"%s deliver_crate: %s crate picked up (%.1f remaining)\", cs.SIDE_NAME[side], commodity, acc[commodity])\n    return true\nend\n\n-- Refund ONE crate (re-credit the accumulator) \226\128\148 used when a supply flight FAILS to spawn AFTER the\n-- pick-up debit (coalition.addGroup returned nil), so the committed crate is not silently lost.\nfunction M.refund_crate(side, commodity)\n    local acc = S.production and S.production[side]\n    if not acc then return end\n    acc[commodity] = (acc[commodity] or 0) + CRATE_SIZE\n    cs.dbg(\"supply\", \"%s refund_crate: %s crate returned (%.1f banked)\", cs.SIDE_NAME[side], commodity, acc[commodity])\nend\n\n-- \226\148\128\226\148\128 Crate earmark (protect delivery-committed crates from reserve conversion) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- free_crate: is there at least one WHOLE crate of `commodity` beyond those already earmarked for\n-- pending supply flights? (gate for creating a new supply flight \226\128\148 \"if no crate banked \226\134\146 no flight\").\nfunction M.free_crate(side, commodity)\n    local acc = S.production and S.production[side]\n    if not acc then return false end\n    local earmark = acc[commodity .. \"_earmark\"] or 0\n    return (acc[commodity] or 0) - earmark * CRATE_SIZE >= CRATE_SIZE\nend\n\n-- earmark_crate: reserve one free crate (increment the earmark) so convert_reserves leaves it alone\n-- until a supply flight picks it up. Returns false if no free crate exists (caller creates no flight).\nfunction M.earmark_crate(side, commodity)\n    if not M.free_crate(side, commodity) then return false end\n    local acc = S.production[side]\n    local key = commodity .. \"_earmark\"\n    acc[key] = (acc[key] or 0) + 1\n    cs.dbg(\"supply\", \"%s earmark_crate: %s earmark -> %d (%.1f banked)\", cs.SIDE_NAME[side], commodity, acc[key], acc[commodity])\n    return true\nend\n\n-- release_earmark: drop one earmark (a supply flight was picked up, aborted, or expired). Clamped >= 0.\nfunction M.release_earmark(side, commodity)\n    local acc = S.production and S.production[side]\n    if not acc then return end\n    local key = commodity .. \"_earmark\"\n    acc[key] = math.max(0, (acc[key] or 0) - 1)\nend\n\n-- set_earmark: RECONCILE the earmark count to `n` (number of live queued supply tasks for this\n-- commodity), clamped to the crates actually banked. Called each keysite_repair tick from the count of\n-- UNASSIGNED board supply tasks, so a supply task that expired/spawned/vanished can never leak an\n-- earmark (fully derived \226\128\148 no per-task release bookkeeping). Spawned flights drop out of the board\n-- task list, so their earmark is released here the tick after pick-up (the crate was already debited).\nfunction M.set_earmark(side, commodity, n)\n    local acc = S.production and S.production[side]\n    if not acc then return end\n    local key = commodity .. \"_earmark\"\n    local max_crates = math.floor((acc[commodity] or 0) / CRATE_SIZE)\n    acc[key] = math.max(0, math.min(n or 0, max_crates))\nend\n\n-- Convert SURPLUS whole crates (those not spent on deliveries this tick) into reserve replacement,\n-- mirroring replace_into_force_info (force.c:297) \226\128\148 production is what replaces hardware losses.\nfunction M.convert_reserves(side, log_fn)\n    log_fn = log_fn or function() end\n    local acc = S.production and S.production[side]\n    if not acc then return end\n    local function drain(commodity, roles, rr_key)\n        local n = 0\n        -- Convert only SURPLUS crates: those beyond crates earmarked for pending physical supply\n        -- flights (KEYSITE-F6/F7 delivery has priority over stockpiling reserves; the earmarked cargo\n        -- is claimed by a TASK_SUPPLY and must reach the requester keysite, not become a jet).\n        local earmark = acc[commodity .. \"_earmark\"] or 0\n        while (acc[commodity] or 0) - earmark * CRATE_SIZE >= CRATE_SIZE do\n            acc[commodity] = acc[commodity] - CRATE_SIZE\n            local rr = (acc[rr_key] % #roles) + 1\n            acc[rr_key] = rr\n            M.recycle_side(side, roles[rr], 1)\n            n = n + 1\n        end\n        if n > 0 then\n            cs.dbg(\"supply\", \"%s convert_reserves: %d surplus %s crate(s) -> reserve hardware\", cs.SIDE_NAME[side], n, commodity)\n        end\n    end\n    drain(\"ammo\", AMMO_RESERVE_ROLES, \"ammo_rr\")\n    drain(\"fuel\", FUEL_RESERVE_ROLES, \"fuel_rr\")\nend\n\n-- \226\148\128\226\148\128 Base-name-keyed public API (unchanged signatures for existing call sites) \226\148\128\226\148\128\n-- Now TRULY per-base (hits that base's ledger), so regen/troop/transfer operate on the exact\n-- base's idle inventory. transfer's consume(donor)+produce(target) becomes a real ledger move.\nfunction M.available(name, role)\n    return M.ledger(name, role)\nend\n\nfunction M.consume(name, role, count)\n    return M.consume_base(name, role, count)\nend\n\n-- Back-compat alias: some call sites \"produce\" to undo a failed consume \226\128\148 that is a recycle.\nfunction M.produce(name, role, count)\n    M.recycle_base(name, role, count)\nend\n\n-- \226\148\128\226\148\128 RTB recycle handler \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- On S_EVENT_LAND, an AI combat/support flight that RTBs is recycled back into its side's\n-- reserve (EECH replace_into_force_info) and despawned to free the DCS slot \226\128\148 important for a\n-- long-running MP session. Player-slot units are ignored (they are not reserve hardware).\nfunction M.make_land_handler(log_fn)\n    log_fn = log_fn or function() end\n    return {\n        onEvent = function(_, event)\n            if event.id ~= world.event.S_EVENT_LAND then return end\n            local u = event.initiator\n            if not u or not u.getGroup then return end\n            local ok, grp = pcall(function() return u:getGroup() end)\n            if not ok or not grp or not grp:isExist() then return end\n            local gname = grp:getName()\n\n            -- Cluster 5: an RTB frees the base landing slot this sortie reserved at launch\n            -- (UNLOCK_LANDING_SITE, ld_msgs.c:1567). Idempotent; runs before the classify gate so\n            -- the slot is released even for a group we do not recycle into the reserve pool.\n            ks.release_slot(gname)\n\n            local role = classify_role(gname)\n            if not role then return end                        -- not one of our tracked flights\n            if u.getPlayerName and u:getPlayerName() then return end  -- human slot, not reserve\n            S._recycled = S._recycled or {}\n            if S._recycled[gname] then return end              -- already recycled this group\n            S._recycled[gname] = true\n\n            local coal = u:getCoalition()\n            local side = (coal == coalition.side.BLUE) and coalition.side.BLUE or coalition.side.RED\n\n            -- Recycle EVERY surviving airframe in the group (EECH replace_into_force_info returns\n            -- each one). Spawn consumed N units; crediting only 1 would leak N-1 on every healthy\n            -- multi-ship sortie. Count live units now (dead ones are already gone from the group).\n            local survivors = grp:getUnits()\n            local n = survivors and #survivors or 1\n\n            -- Credit the LANDING base's ledger (force conservation with LOCATION): the flight lands\n            -- at a specific keysite and its survivors become idle inventory THERE, transferable by\n            -- transfer.lua thereafter. Landing base = nearest owned base to the landing position.\n            local lpos = u:getPosition().p\n            local land_base, best_d2 = nil, math.huge\n            for bname, bowner in pairs(S.base_owner) do\n                if bowner == side then\n                    local bpos = S.base_pos[bname]\n                    if bpos then\n                        local dx = lpos.x - bpos.x; local dz = lpos.z - bpos.z\n                        local d2 = dx*dx + dz*dz\n                        if d2 < best_d2 then best_d2 = d2; land_base = bname end\n                    end\n                end\n            end\n            if land_base then M.recycle_base(land_base, role, n) else M.recycle_side(side, role, n) end\n            log_fn(string.format(\"supply: %s (%s) RTB @ %s \226\134\146 +%d %s (base now %d / side %d)\",\n                gname, cs.SIDE_NAME[side], land_base or \"?\", n, role,\n                M.ledger(land_base, role), M.reserve_side(side, role)))\n\n            -- Despawn shortly after landing to free the slot (aircraft is now \"in reserve\").\n            -- Group:destroy() fires NO S_EVENT_DEAD, so this does not re-enter the regen queue \226\128\148\n            -- load-bearing: if that DCS behaviour ever changed, a recycled airframe would also be\n            -- regenerated (double-count). Any stragglers still airborne are folded into reserve too.\n            timer.scheduleFunction(function()\n                if grp and grp:isExist() then grp:destroy() end\n                return nil\n            end, nil, timer.getTime() + 30)\n        end\n    }\nend\n\n-- \226\148\128\226\148\128 Reserve status logger \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Kept for observability only; periodically logs remaining reserves + crate accumulators so the\n-- attrition arc AND the production economy are visible in the DCS log. The reserve pool is fed by\n-- production (convert_reserves) and RTB recycle, and drained by spawns \226\128\148 killing enemy producers\n-- flattens the reserve line, which is the whole point of the economic gap.\nlocal SUPPLY_PERIOD = 10 * 60\n\nfunction M.schedule_supply(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"supply\", \"reserve-status scheduler REGISTERED offset=%.0fs period=%.0fs\", SUPPLY_PERIOD, SUPPLY_PERIOD)\n    timer.scheduleFunction(function(_, t)\n        -- INFRASTRUCTURE: reserve-status logging keeps running post-victory (EECH fc_msgs.c:163). Cluster E.\n        if _DMT_GEN ~= my_gen then return nil end\n        for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n            local prod = S.production and S.production[side]\n            log_fn(string.format(\"reserve %s: striker=%d escort=%d heli=%d recon=%d veh=%d | crates ammo=%.1f fuel=%.1f | tasks failed=%d\",\n                cs.SIDE_NAME[side],\n                M.reserve_side(side, \"striker\"), M.reserve_side(side, \"escort\"), M.reserve_side(side, \"heli\"),\n                M.reserve_side(side, \"recon\"), M.reserve_side(side, \"vehicle\"),\n                prod and prod.ammo or 0, prod and prod.fuel or 0, S.board_failed or 0))\n        end\n        return t + SUPPLY_PERIOD\n    end, nil, timer.getTime() + SUPPLY_PERIOD)\nend\n\nreturn M\n"
__modules["supply_flight"] = "-- supply_flight.lua\n-- PHYSICAL supply flights \226\128\148 the transport that actually flies a resupply crate from a producer\n-- keysite to a low consumer keysite, replacing the old instant-crate teleport in keysite_repair.\n--\n-- EECH source:\n--   aphavoc/source/entity/special/force/fc_msgs.c:672-870  response_to_force_low_on_supplies:\n--     a keysite whose ammo/fuel supply level fell to KEYSITE_SUPPLY_REQUEST_THRESHOLD (75.0,\n--     en_suply.h:87) raises ENTITY_MESSAGE_FORCE_LOW_ON_SUPPLIES (keysite.c:469-494). The FORCE\n--     picks the CLOSEST supplier \226\128\148 AMMO: nearest FACTORY (fall back OIL_REFINERY), FUEL: nearest\n--     OIL_REFINERY (fall back FACTORY); an AIRBASE within range may substitute if closer\n--     (fc_msgs.c:759-800) \226\128\148 then finds the matching cargo crate and calls create_supply_task with\n--     movement_type = MOVEMENT_TYPE_AIR (fc_msgs.c:846 \226\128\148 the land-convoy branch is commented out in\n--     the shipped source, fc_msgs.c:834-845). Dedup: one supply task per keysite PER CARGO SUB_TYPE\n--     (entity_is_object_of_task + FLOAT_TYPE_TASK_USER_DATA==sub_type, fc_msgs.c:721-742).\n--   aphavoc/source/ai/taskgen/taskgen.c:1638-1727  create_supply_task: TASK_SUPPLY with waypoints\n--     PICK_UP (at the cargo/producer, :1707), PREPARE_FOR_DROP_OFF (stop - dir*4km, :1688-1690),\n--     DROP_OFF (requester supply position, :1709), FINISH_DROP_OFF (stop + dir*2km, :1692-1694);\n--     expire_time = 20*ONE_MINUTE (:1696). Start keysite = get_task_start_keysite (a friendly\n--     keysite with idle transports) \226\128\148 the task board's launch-base selection is the port analog.\n--   aphavoc/source/entity/special/task/ts_dbase.c:1386-1440  TASK_SUPPLY row: task_priority 4,\n--     Escort Required Threshold 6, Movement Type MOVEMENT_TYPE_AIR, landing types\n--     LANDING_FIXED_WING_TRANSPORT + LANDING_HELICOPTER, Cargo Space 5, Engage Enemy FALSE.\n--   aphavoc/source/entity/special/keysite/keysite.c:337-467  update_keysite_cargo / ks_msgs.c:230,238\n--     one crate delivery restocks the consumer keysite to 100.\n--\n-- PORT MODEL (documented divergences from the C):\n--   * MOVEMENT_TYPE_AIR only. EECH's create_supply_task also serves land convoys when the caller\n--     picks MOVEMENT_TYPE_LAND, but fc_msgs.c:846 hardcodes AIR for keysite resupply (the land branch\n--     is commented out), and DCS exposes no road-node adjacency graph for a node-by-node convoy (the\n--     documented structural road-graph limit shared with ground movement) \226\128\148 so AIR is both faithful to\n--     the live caller and the only reproducible option.\n--   * The \"cargo crate\" is the side-level production accumulator (supply.lua S.production), not a\n--     per-factory cargo entity. The producer keysite (installations.nearest_producer) is used as the\n--     PICK_UP position; the crate is debited from the accumulator at pick-up (flight spawn). A crate\n--     requested but not yet picked up is EARMARKED (supply.earmark_crate) so convert_reserves cannot\n--     turn it into a jet while the flight is queued \226\128\148 EECH's cargo, once claimed by a supply task, is\n--     never repurposed.\n--   * DROP_OFF is a fly-over of the consumer detected by proximity (check_arrivals); the transport\n--     then RTBs and LANDS BACK AT ITS LAUNCH BASE (where the land handler recycles it to the transport\n--     ledger). EECH lands at the requester; the port has no consumer-landing model, so restock is\n--     triggered by the fly-over and the airframe returns home for recycle.\n--   * Airframe: fixed-wing transport (config transport_fw: C-130 / An-26B) for airbase\226\134\148airbase legs;\n--     transport heli (config transport_heli: UH-1H / Mi-8MT) whenever EITHER endpoint is a padless\n--     FARP/FOB (no runway). Movement stays AIR either way (the ts_dbase landing types allow both).\n--   * Shot down en route = crate LOST (debited at pick-up, never refunded) \226\128\148 the interceptable\n--     economy this whole feature exists to create.\n\nlocal cs      = require(\"campaign_state\")\nlocal croute  = require(\"croute\")\nlocal config  = require(\"config\")\nlocal supply  = require(\"supply\")\nlocal inst    = require(\"installations\")\nlocal board   = require(\"task_board\")\nlocal ks      = require(\"keysite\")\nlocal S       = cs.S\nlocal M       = {}\n\n-- Route cruise speed (m/s) \226\128\148 matches the task-board ETA gate's transport CRUISE_SPEED (task_board.lua:113).\nlocal SUPPLY_SPEED = 100\n\n-- Proximity a supply flight must reach at the consumer keysite for the DROP_OFF fly-over to count as\n-- delivered. 4 km comfortably brackets the ~2 km a 100 m/s transport covers between 20 s arrival scans.\nlocal DELIVERY_RADIUS = 4000\n\n-- Arrival scan cadence \226\128\148 short so a fast transport's fly-over is never missed between ticks.\nlocal ARRIVAL_SCAN_PERIOD = 20\n\nlocal SUPPLY_PREFIX = \"Supply\"\n\n-- \226\148\128\226\148\128 Dedup: one live supply flight per consumer PER COMMODITY (fc_msgs.c:721-742) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Derived from live state (no per-task bookkeeping): a supply demand is \"pending\" if a board supply\n-- task is still QUEUED for it, OR a spawned \"Supply-\" flight is registered against it. Both sources are\n-- rebuilt from S.board_tasks / S.active_tasks, so an expired/spawned/dead flight self-clears here.\nfunction M.has_pending(side, consumer, commodity)\n    for _, t in ipairs(S.board_tasks or {}) do\n        if t.state == \"UNASSIGNED\" and t.type == \"supply\" and t.side == side\n           and t.target and t.target.base == consumer and t.target.commodity == commodity then\n            return true\n        end\n    end\n    for _, at in pairs(S.active_tasks or {}) do\n        if at.task_type == \"supply\" and at.side == side and at.target_base == consumer\n           and at.commodity == commodity then\n            return true\n        end\n    end\n    return false\nend\n\n-- Number of QUEUED (not-yet-spawned) supply board tasks for a side+commodity \226\128\148 the earmark target\n-- (keysite_repair reconciles supply.set_earmark to this each tick).\nfunction M.count_queued(side, commodity)\n    local n = 0\n    for _, t in ipairs(S.board_tasks or {}) do\n        if t.state == \"UNASSIGNED\" and t.type == \"supply\" and t.side == side\n           and t.target and t.target.commodity == commodity then\n            n = n + 1\n        end\n    end\n    return n\nend\n\n-- \226\148\128\226\148\128 RTB / backstop recycle (transport ledger) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- A supply flight that lands at its launch base is recycled by supply.make_land_handler (classify_role\n-- \"Supply-\" \226\134\146 transport). But a heli launched from a PADLESS FARP fires no S_EVENT_LAND on its RTB\n-- turning point, so this backstop guarantees the transport ledger + landing slot are freed. Once-guarded\n-- via the SHARED S._recycled set (so if the land handler already recycled, this no-ops). A flight shot\n-- down en route reaches here with no survivors \226\134\146 nothing credited (the airframe is a real loss), and the\n-- DEAD handlers already freed its slot + task.\nlocal function recycle_supply_once(gname, launch_base, grp)\n    S._recycled = S._recycled or {}\n    if S._recycled[gname] then return end\n    S._recycled[gname] = true\n    local n = 0\n    if grp and grp.isExist and grp:isExist() then\n        local ok, units = pcall(function() return grp:getUnits() end)\n        if ok and units then\n            for _, u in ipairs(units) do if u and u:isExist() then n = n + 1 end end\n        end\n    end\n    if n > 0 then supply.recycle_base(launch_base, \"transport\", n) end\nend\n\nlocal function schedule_backstop(gname, launch, grp, ab_pos, ppos, cpos)\n    local function d(a, b) local x = a.x - b.x; local z = a.z - b.z; return math.sqrt(x*x + z*z) end\n    local dist = d(ab_pos, ppos) + d(ppos, cpos) + d(cpos, ab_pos)\n    local ttl  = dist / 40 + 600   -- conservative (40 m/s floor << the 100 m/s cruise) + 10 min margin,\n                                    -- so the backstop only fires well AFTER a normal round trip would land.\n    local my_gen = _DMT_GEN\n    timer.scheduleFunction(function()\n        if _DMT_GEN ~= my_gen then return nil end   -- stale generation: reset.nuke already cleaned up\n        recycle_supply_once(gname, launch, grp)\n        ks.release_slot(gname)\n        if grp and grp:isExist() then grp:destroy() end\n        cs.clear_task(gname)\n        return nil\n    end, nil, timer.getTime() + ttl)\nend\n\n-- \226\148\128\226\148\128 Builder (task-board contract) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- The board has consumed 1 \"transport\" from `launch`'s ledger (refunds on nil/throw). We debit the\n-- crate (pick-up), spawn the transport routed launch \226\134\146 producer(PICK_UP) \226\134\146 consumer(DROP_OFF) \226\134\146 launch,\n-- and register the task. Returns the group on success, nil on failure.\nlocal function build_supply_flight(side, launch, consumer, cpos, commodity, prod, log_fn)\n    log_fn = log_fn or function() end\n    local ac = config.C.types.aircraft[side]\n    local lk = S.base_kind and S.base_kind[launch]\n    local ck = S.base_kind and S.base_kind[consumer]\n    -- Heli when either endpoint is a padless FARP/FOB (no runway); fixed-wing transport otherwise.\n    local use_heli = (lk == \"farp\" or lk == \"fob\" or ck == \"farp\" or ck == \"fob\")\n    -- TWO-TIER fixed-wing fleet (gp_dbase.c:590-591 MEDIUM_LIFT = C-130J/An-12B, :631-632\n    -- HEAVY_LIFT = C-17/IL-76MD): EECH's SUPPLY task accepts BOTH transport group types\n    -- (suitable.c landing-type gate \226\128\148 FIXED_WING_TRANSPORT), and the assign flies whichever idle\n    -- transport group is nearest, so C-17s hauled crates alongside C-130s. The port has no\n    -- per-group airframe pool, so it ALTERNATES medium/heavy per fixed-wing flight \226\128\148 the same\n    -- deterministic-toggle proxy the artillery uses for the tube/MLRS mix (faction.c:1633\n    -- mlrs_flag pattern).\n    local actype\n    if use_heli then\n        actype = ac.transport_heli\n    else\n        S.supply_heavy_flag = not S.supply_heavy_flag\n        actype = (S.supply_heavy_flag and ac.transport_fw_heavy) or ac.transport_fw\n        actype = actype or ac.transport_fw\n    end\n    local cat      = use_heli and Group.Category.HELICOPTER or Group.Category.AIRPLANE\n    local country  = config.C.countries[side]\n\n    -- LAUNCH != CONSUMER (taskgen.c:1676: `if (!get_task_start_keysite(...) || start_ks == requester)\n    -- return NULL` \226\128\148 EECH refuses a supply task whose start keysite IS the requester). Without this a\n    -- transport assigned to launch from the requesting base spawned already inside the delivery radius\n    -- and \"delivered\" in ~20s while parked (live-caught: Supply-Kutaisi-fuel-2-2204). The board also\n    -- excludes this base at assignment (exclude_target_base); this is the belt-and-braces guard.\n    if launch == consumer then\n        cs.dbg(\"supply\", \"%s supply build ABORT: launch == consumer %s (taskgen.c:1676) -> refund transport, retry\",\n            cs.SIDE_NAME[side], consumer)\n        return nil\n    end\n\n    -- Re-resolve the producer at SPAWN time (board assignment lags the request by up to a pass): if the\n    -- factory/refinery was destroyed or captured in the interim, EECH cancels the supply task (its cargo\n    -- entity died with the keysite). Abort BEFORE any crate debit so the board just refunds the transport\n    -- ledger and the task retries/expires. Otherwise route PICK_UP to the CURRENT nearest producer.\n    prod = inst.nearest_producer(side, commodity, cpos)\n    if not prod then\n        cs.dbg(\"supply\", \"%s supply build ABORT at %s: producer died before spawn -> refund transport, retry\",\n            cs.SIDE_NAME[side], tostring(launch))\n        return nil\n    end\n\n    -- PICK_UP debit (taskgen.c:1638 WAYPOINT_PICK_UP): the crate leaves the producer as the transport\n    -- launches. No crate available \226\134\146 abort so the board refunds the transport ledger and retries.\n    if not supply.deliver_crate(side, commodity) then\n        cs.dbg(\"supply\", \"%s supply build ABORT at %s: %s crate gone before pick-up -> refund transport, retry\",\n            cs.SIDE_NAME[side], tostring(launch), commodity)\n        return nil\n    end\n\n    -- Launch geometry: real airbase pad (TakeOff/Land) or padless FARP (ground start / RTB turning\n    -- point). A fixed-wing transport only ever launches from a real airbase (use_heli forces heli at a\n    -- FARP endpoint), so the padless branch is heli-only.\n    local ab = Airbase.getByName(launch)\n    local ab_pos, ab_id\n    if ab then\n        ab_pos, ab_id = ab:getPosition().p, ab:getID()\n    else\n        -- No runway at the launch base. A fixed-wing transport cannot ground-start off-field, so this\n        -- branch is heli-only (use_heli is forced true whenever an endpoint is a FARP/FOB). Guard the\n        -- latent case where a non-FARP base has no resolvable Airbase object \226\134\146 refund + abort.\n        if not use_heli then\n            supply.refund_crate(side, commodity)\n            cs.dbg(\"supply\", \"%s supply build ABORT: fixed-wing launch %s has no Airbase (no runway) -> crate refunded\",\n                cs.SIDE_NAME[side], tostring(launch))\n            return nil\n        end\n        local bp = S.base_pos and S.base_pos[launch]\n        if not bp then\n            supply.refund_crate(side, commodity)\n            cs.dbg(\"supply\", \"%s supply build ABORT: launch %s unknown (no Airbase, no base_pos) -> crate refunded\",\n                cs.SIDE_NAME[side], tostring(launch))\n            return nil\n        end\n        local gy = 0\n        pcall(function() gy = land.getHeight({ x = bp.x, y = bp.z }) or 0 end)\n        ab_pos = { x = bp.x, y = gy, z = bp.z }\n    end\n\n    local bx, by = cs.wp_xy(ab_pos)\n    local px, py = cs.wp_xy(prod.pos)\n    local dx, dy = cs.wp_xy(cpos)\n    local sid    = cs.next_id()\n    local gname  = string.format(\"Supply-%s-%s-%d-%d\", consumer:sub(1, 8), commodity, side, sid)\n    local alt      = use_heli and 150 or 3000\n    local alt_type = use_heli and \"RADIO\" or \"BARO\"\n\n    local depart, rtb\n    if ab_id then\n        depart = { type=\"TakeOff\", action=\"From Parking Area\", airdromeId=ab_id, alt=ab_pos.y,\n                   alt_type=\"BARO\", speed=0, ETA=0, ETA_locked=true, x=bx, y=by, name=\"Depart\", formation_template=\"\" }\n        rtb    = { type=\"Land\", action=\"Landing\", airdromeId=ab_id, alt=ab_pos.y, alt_type=\"BARO\",\n                   speed=SUPPLY_SPEED, ETA=0, ETA_locked=false, x=bx, y=by, name=\"RTB\", formation_template=\"\" }\n    else\n        depart = { type=\"TakeOffGroundHot\", action=\"From Ground Area Hot\", alt=ab_pos.y, alt_type=\"BARO\",\n                   speed=0, ETA=0, ETA_locked=true, x=bx, y=by, name=\"Depart\", formation_template=\"\" }\n        rtb    = { type=\"Turning Point\", action=\"Turning Point\", alt=alt, alt_type=alt_type,\n                   speed=SUPPLY_SPEED, ETA=0, ETA_locked=false, x=bx, y=by, name=\"RTB\", formation_template=\"\" }\n    end\n\n    local gspec = {\n        name = gname, task = \"Transport\", hidden = false,\n        units = {{ name=gname..\"-1\", type=actype, skill=\"High\",\n            x=ab_pos.x, y=ab_pos.z, alt=ab_pos.y, alt_type=\"BARO\", speed=0, heading=0,\n            payload={ fuel = use_heli and 2200 or 12000 } }},\n        route = { points = croute.expand({\n            depart,\n            { type=\"Turning Point\", action=\"Turning Point\", alt=alt, alt_type=alt_type,\n              speed=SUPPLY_SPEED, ETA=0, ETA_locked=false, x=px, y=py, name=\"PickUp\", formation_template=\"\" },\n            { type=\"Turning Point\", action=\"Fly Over Point\", alt=alt, alt_type=alt_type,\n              speed=SUPPLY_SPEED, ETA=0, ETA_locked=false, x=dx, y=dy, name=\"DropOff\", formation_template=\"\" },\n            rtb,\n        }, side, { alt=alt, alt_type=alt_type, speed=SUPPLY_SPEED, name=\"Nav\" }) },\n    }\n    if ab_id then gspec.airdromeId = ab_id end\n\n    local ok_s, grp = pcall(coalition.addGroup, country, cat, gspec)\n    if ok_s and grp then\n        -- Crate physically picked up \226\134\146 drop its earmark (reconcile would too next tick; immediate for clarity).\n        supply.release_earmark(side, commodity)\n        cs.register_task(gname, { task_type=\"supply\", side=side, target_base=consumer, target_pos=cpos,\n            commodity=commodity, launch_base=launch, born_time=timer.getTime(),\n            -- PICK_UP-before-DROP_OFF sequencing (taskgen.c:1709-1711 waypoint order): the arrival\n            -- scan must see the transport AT the producer before a consumer flyover counts as a\n            -- delivery \226\128\148 otherwise a route that skims the consumer early \"delivers\" without cargo.\n            producer_pos = { x = prod.pos.x, z = prod.pos.z }, picked_up = false })\n        -- Escort assessment (assign.c:598; TASK_SUPPLY threshold 6). Rear resupply legs run over own\n        -- territory, so route_difficulty \226\137\136 0 and this is effectively inert \226\128\148 wired for fidelity.\n        if cs.escort_count(\"supply\", side, ab_pos, cpos, log_fn) > 0 then\n            pcall(function() require(\"heli_war\").spawn_escort(side, cpos, log_fn) end)\n        end\n        schedule_backstop(gname, launch, grp, ab_pos, prod.pos, cpos)\n        log_fn(string.format(\"%s SUPPLY flight #%d: %s crate %s \226\134\146 %s (via producer %s, %s)\",\n            cs.SIDE_NAME[side], sid, commodity, launch, consumer, prod.name, use_heli and \"heli\" or \"fixed-wing\"))\n        cs.dbg(\"supply\", \"%s supply flight %s DISPATCHED: %s pick-up @ %s -> drop @ %s, RTB %s (%s)\",\n            cs.SIDE_NAME[side], gname, commodity, prod.name, consumer, launch, actype)\n        return grp\n    end\n\n    -- Spawn failed AFTER the pick-up debit \226\134\146 return the crate; board refunds the transport ledger.\n    supply.refund_crate(side, commodity)\n    cs.dbg(\"supply\", \"%s supply flight SPAWN FAILED from %s -> %s (%s): crate refunded, pcall_ok=%s err=%s\",\n        cs.SIDE_NAME[side], tostring(launch), consumer, tostring(actype), tostring(ok_s), tostring(grp))\n    return nil\nend\n\n-- \226\148\128\226\148\128 Request path (called from keysite_repair for each low consumer keysite) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Picks the nearest ALIVE producer (PICK_UP), earmarks a crate, and queues a board supply task\n-- targeting the consumer. Gates (all mirror the EECH request path):\n--   * dedup one live task per consumer per commodity                       (fc_msgs.c:721-742)\n--   * no live producer alive \226\134\146 no flight (economy strangulation preserved) (fc_msgs.c:802 `if factory`)\n--   * no free crate banked \226\134\146 no flight                                     (fc_msgs.c:820 `if cargo`)\nfunction M.request(side, consumer, commodity, log_fn)\n    log_fn = log_fn or function() end\n    local cpos = S.base_pos and S.base_pos[consumer]\n    if not cpos then return false end\n    if M.has_pending(side, consumer, commodity) then return false end\n    local prod = inst.nearest_producer(side, commodity, cpos)\n    if not prod then\n        cs.dbg(\"supply\", \"%s supply request for %s %s: NO live producer -> no flight (strangled)\",\n            cs.SIDE_NAME[side], consumer, commodity)\n        return false\n    end\n    if not supply.free_crate(side, commodity) then\n        cs.dbg(\"supply\", \"%s supply request for %s %s: no crate banked -> no flight\",\n            cs.SIDE_NAME[side], consumer, commodity)\n        return false\n    end\n    -- Earmark the crate so convert_reserves leaves it for this flight (released at pick-up / reconcile).\n    supply.earmark_crate(side, commodity)\n    board.create_task({\n        type = \"supply\", side = side, count = 1, log_fn = log_fn,\n        -- taskgen.c:1676: the start keysite must not be the requester \226\128\148 the board skips the\n        -- consumer itself when picking the launch base (else the transport \"delivers\" while parked).\n        exclude_target_base = true,\n        target = { base = consumer, pos = cpos, commodity = commodity,\n                   producer_name = prod.name, producer_pos = prod.pos,\n                   objective = { kind = \"keysite\", base = consumer } },\n        builder = function(launch)\n            return build_supply_flight(side, launch, consumer, cpos, commodity, prod, log_fn)\n        end,\n    })\n    cs.dbg(\"supply\", \"%s supply task QUEUED: %s %s (producer %s)\", cs.SIDE_NAME[side], consumer, commodity, prod.name)\n    return true\nend\n\n-- \226\148\128\226\148\128 Delivery detection: DROP_OFF fly-over of the consumer keysite \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors troop.check_landing_helis: scan own-side \"Supply-\" groups; the first that reaches within\n-- DELIVERY_RADIUS of ITS OWN registered consumer keysite restocks that keysite to 100 for its commodity\n-- (ks_msgs.c:230,238), once. The transport then RTBs on its own (recycled by the land handler / backstop).\nlocal function scan_side(side, log_fn)\n    local grps = coalition.getGroups(side)\n    if not grps then return end\n    S.supply_delivered = S.supply_delivered or {}\n    local done = S.supply_delivered\n    for _, grp in ipairs(grps) do\n        if grp and grp:isExist() then\n            local gname = grp:getName()\n            if gname:match(\"^\" .. SUPPLY_PREFIX .. \"%-\") and not done[gname] then\n                local task = cs.get_task(gname)\n                if task and task.task_type == \"supply\" then\n                    local consumer, commodity = task.target_base, task.commodity\n                    local cpos = consumer and S.base_pos[consumer]\n                    local u = grp:getUnit(1)\n                    if cpos and u and u:isExist() then\n                        local hp = u:getPosition().p\n                        -- Phase 1 \226\128\148 PICK_UP: the transport must first reach the producer (waypoint\n                        -- order taskgen.c:1709-1711). Until then, consumer proximity does NOT count\n                        -- (a transport spawning near \226\128\148 or overflying \226\128\148 the consumer has no cargo yet).\n                        if not task.picked_up and task.producer_pos then\n                            local px, pz = hp.x - task.producer_pos.x, hp.z - task.producer_pos.z\n                            if px*px + pz*pz <= DELIVERY_RADIUS * DELIVERY_RADIUS then\n                                task.picked_up = true\n                                cs.dbg(\"supply\", \"%s supply flight %s PICK-UP confirmed at producer (%.0fm)\",\n                                    cs.SIDE_NAME[side], gname, math.sqrt(px*px + pz*pz))\n                            end\n                        end\n                        local dx, dz = hp.x - cpos.x, hp.z - cpos.z\n                        if task.picked_up and dx*dx + dz*dz <= DELIVERY_RADIUS * DELIVERY_RADIUS then\n                            done[gname] = true   -- once per flight either way (spent even if it can't restock)\n                            -- Only restock if the consumer is STILL friendly: a base captured by the enemy\n                            -- while the transport was en route gets no free refill (EECH's supply task\n                            -- cancels when the requester keysite flips). The crate is spent regardless\n                            -- (picked up at the producer) \226\128\148 an interdicted/overrun delivery is a loss.\n                            if S.base_owner[consumer] == side then\n                                -- One crate delivery fully restocks the consumer (keysite.c:438-467 / ks_msgs.c:230,238).\n                                if commodity == \"ammo\" then\n                                    S.base_ammo = S.base_ammo or {}; S.base_ammo[consumer] = 100.0\n                                else\n                                    S.base_fuel = S.base_fuel or {}; S.base_fuel[consumer] = 100.0\n                                end\n                                log_fn(string.format(\"supply: %s %s delivered to %s \226\134\146 restocked to 100 (%s)\",\n                                    cs.SIDE_NAME[side], commodity, consumer, gname))\n                                cs.dbg(\"supply\", \"%s supply flight %s reached %s (%.0fm): %s restocked to 100%% \226\128\148 RTB\",\n                                    cs.SIDE_NAME[side], gname, consumer, math.sqrt(dx*dx + dz*dz), commodity)\n                            else\n                                cs.dbg(\"supply\", \"%s supply flight %s reached %s but it flipped enemy \226\128\148 crate lost, no restock\",\n                                    cs.SIDE_NAME[side], gname, consumer)\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\nend\n\nfunction M.check_arrivals(log_fn)\n    log_fn = log_fn or function() end\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        scan_side(side, log_fn)\n    end\nend\n\nfunction M.schedule_arrivals(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"supply\", \"supply-flight arrival scanner REGISTERED period=%.0fs\", ARRIVAL_SCAN_PERIOD)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end   -- re-injection guard\n        local ok, err = pcall(M.check_arrivals, log_fn)\n        if not ok then log_fn(\"supply_flight arrival scan error: \" .. tostring(err)) end\n        return t + ARRIVAL_SCAN_PERIOD\n    end, nil, timer.getTime() + ARRIVAL_SCAN_PERIOD)\nend\n\nreturn M\n"
__modules["task_board"] = "-- task_board.lua\n-- EECH source:\n--   aphavoc/source/entity/system/en_types/en_task.h   TASK_STATE_TYPES (UNASSIGNED/ASSIGNED/\n--                                                      COMPLETED, :83-90), TASK_TERMINATED_TYPES\n--                                                      (EXPIRE_TIME_REACHED, :115-127)\n--   aphavoc/source/entity/special/task/task.c          task list membership / state machine\n--                                                      (get_local_task_list_type :561-589)\n--   aphavoc/source/entity/special/task/ts_updt.c        update_server: UNASSIGNED expire_timer\n--                                                      countdown \226\134\146 TASK_TERMINATED (:99-124)\n--   aphavoc/source/entity/special/task/ts_dbase.c       per-type task_priority / expiry defaults\n--   aphavoc/source/ai/taskgen/assign.c                 assign_keysite_tasks (sort by priority,\n--                                                      critical \195\1512, :201-212); get_suitable_\n--                                                      registered_group (LOWEST-positive-suitability\n--                                                      winner, best_result=FLT_MAX / result<best,\n--                                                      :433-501, the quirk at :497); locality gate\n--   aphavoc/source/ai/highlevl/suitable.c              group\195\151task suitability matrix\n--   aphavoc/source/entity/special/keysite/keysite.h    KEYSITE_TASK_ASSIGN_TIMER = 3 min (:69)\n--\n-- THE ASSIGNMENT ENGINE (Cluster 4). Shipped EECH does NOT spawn fresh aircraft per task: order\n-- generation creates TASK entities and this engine matches them to EXISTING idle groups resident\n-- at keysites. The port previously fresh-spawned per task (no unassigned pool, no suitability, no\n-- failure path). This module restores the shipped model with a DCS-shaped ledger:\n--\n--   * Idle aircraft = a PER-BASE ledger (supply.lua S.base_ledger) \226\128\148 counts by role at each owned\n--     base, a documented proxy for EECH's live aircraft parked at keysites (DCS cannot keep\n--     hundreds of parked AI aircraft alive).\n--   * Generators create_task(...) an UNASSIGNED record instead of spawning.\n--   * tick() drains the board: sort by priority (critical \195\1512, assign.c:201-204); for each task pick\n--     the suitable base inventory (SUIT matrix \226\134\146 role; assign.c:497 LOWEST-positive-suitability\n--     winner reproduced exactly; distance a pass/fail gate, TASK-F14); consume that base's ledger;\n--     physically spawn via the generator's builder; mark ASSIGNED. On spawn failure \226\134\146 refund the\n--     ledger, task STAYS UNASSIGNED for retry until expiry (refund discipline).\n--   * UNASSIGNED past its unassigned-expiry (ts_updt.c:99-124) \226\134\146 FAILED, removed \226\128\148 the real\n--     task-failure path that the fresh-spawn port never had.\n--\n-- Dedup: while a task is UNASSIGNED the board keeps a synthetic marker in S.active_tasks (keyed\n-- \"board:<id>\", shaped {task_type,target_base,side}) so the existing cs.has_task_against() /\n-- reaction dedup guards transparently see QUEUED-but-not-yet-spawned tasks. On assignment the\n-- marker is dropped and the freshly spawned group registers under its real name (reaction's BIRTH\n-- path). So a target is never double-tasked whether the prior task is queued or already flying.\n--\n-- Reaction unchanged: the ASSIGNED transition IS the DCS S_EVENT_BIRTH (the group is physically\n-- created at assignment), and completion is RTB (S_EVENT_LAND) \226\128\148 exactly what reaction.lua already\n-- keys off (ENTITY_MESSAGE_TASK_ASSIGNED / TASK_COMPLETED). The board owns create\226\134\146assign\226\134\146expire.\n\nlocal cs     = require(\"campaign_state\")\nlocal supply = require(\"supply\")\nlocal ks     = require(\"keysite\")\nlocal S      = cs.S\nlocal M      = {}\n\n-- \226\148\128\226\148\128 Assignment cadence \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- KEYSITE_TASK_ASSIGN_TIMER = 3.0 * ONE_MINUTE (eech keysite.h:69; spec 07 TASK-F9). EECH runs a\n-- per-keysite pass every 3 min (staggered by frand1()*3min at ks_creat.c:166); the port has no\n-- per-keysite timers, so one global board pass every 3 min stands in.\nlocal ASSIGN_CADENCE = 3 * 60\n\n-- \226\148\128\226\148\128 Per-type task_priority (eech ts_dbase.c; spec 07 Table A / spec 04 \194\1672) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- heli_escort is the port's escort-at-assignment task (spawn_escort, immediate); priced at the\n-- escort band. (anti_armour/hunter_killer rows removed with their retired generators, Cluster H.)\nM.PRIORITY = {\n    ground_strike = 9, oca_strike = 6, oca_sweep = 7, cas = 6, bai = 4, sead = 9,\n    recon = 7, bda = 9, troop_insertion = 10, heli_escort = 7,\n    supply = 4,   -- ts_dbase.c:1391 TASK_SUPPLY task_priority = 4 (TASK_CATEGORY_SUPPORT)\n}\n\n-- \226\148\128\226\148\128 Critical flag (eech generator `critical=` argument; spec 04 F6/F7/F8) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Critical tasks sort at \195\1512 priority (assign.c:201-204).\nM.CRITICAL = { oca_strike = true, oca_sweep = true, troop_insertion = true }\n\n-- \226\148\128\226\148\128 Per-creator UNASSIGNED expiry (eech taskgen.c; spec 07 TASK-F8), seconds \226\148\128\226\148\128\226\148\128\n-- Zero expire timer = never expires in EECH; every port task type has a finite window here so the\n-- failure path always exists. recon = 10 min is the shortest (taskgen.c:1477) and the generic\n-- unassigned-expiry the design emphasises; the rotary composite reuses it.\nM.EXPIRY = {\n    ground_strike = 40 * 60, oca_strike = 30 * 60, oca_sweep = 30 * 60,\n    cas = 20 * 60, bai = 20 * 60, sead = 30 * 60, recon = 10 * 60,\n    bda = 30 * 60, troop_insertion = 45 * 60, heli_escort = 10 * 60,\n    supply = 20 * 60,   -- taskgen.c:1696 create_supply_task expire_time = 20 * ONE_MINUTE\n}\nlocal UNASSIGNED_EXPIRY_DEFAULT = 10 * 60\n\n-- \226\148\128\226\148\128 Suitability matrix: task type \226\134\146 acceptable {role, suitability} (eech suitable.c) \226\148\128\226\148\128\n-- Each entry is a group\195\151task suitability value (>0). The assignment keeps the LOWEST-positive\n-- suitability candidate (assign.c:497 quirk \226\128\148 \"least over-qualified\", best_result=FLT_MAX,\n-- result<best). Port roles are effectively 1:1 with task types (as EECH's data is effectively 1.0\n-- for every capable group \226\128\148 spec 07 \194\1676.1), so the matrix is single-role per task; the lowest-\n-- positive comparison is reproduced across candidate BASES (each owned base = a candidate \"group\").\nM.SUIT = {\n    ground_strike = { { role = \"striker\", s = 1.0 } },\n    oca_strike    = { { role = \"striker\", s = 1.0 } },\n    cas           = { { role = \"heli\",    s = 1.0 } },  -- CAS/BAI are the rotary frontline fight in\n    bai           = { { role = \"heli\",    s = 1.0 } },  -- EECH \226\134\146 attack helis from the nearest FARP\n    sead          = { { role = \"striker\", s = 1.0 } },  -- SEAD stays fixed-wing (Wild Weasel)\n    oca_sweep     = { { role = \"escort\",  s = 1.0 } },\n    recon         = { { role = \"recon\",   s = 1.0 } },\n    bda           = { { role = \"heli\",    s = 1.0 } },\n    troop_insertion = { { role = \"transport\", s = 1.0 } },  -- transport heli (UH-1H/Mi-8MT), its OWN\n                                                             -- pool \226\128\148 not the attack-heli pool that\n                                                             -- heli_war drains dry at the frontline\n    heli_escort   = { { role = \"heli\",    s = 1.0 } },\n    supply        = { { role = \"transport\", s = 1.0 } },  -- physical resupply flight (supply_flight.lua):\n                                                          -- fixed-wing transport (C-130/An-26B) airbase\226\134\148\n                                                          -- airbase, or transport heli when an endpoint is\n                                                          -- a padless FARP. Shares the transport ledger.\n}\n\n-- \226\148\128\226\148\128 ESCORT speed-class suitability check (eech assign.c:318-363) \226\128\148 DOCUMENTED AS IMPOSSIBLE HERE \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- WAVE 3 Item 3a: EECH's suitable_group_task_specific_checks gates a TASK_ESCORT group by movement class\n-- (assign.c:318-363): \"Jets escort Jets, Helis escort anything but jets\" \226\128\148 a fast objective (movement\n-- speed >= 5) requires a fast escort and vice-versa, and an escort must not be slower than its objective.\n-- The port has NO analogous runtime check, and deliberately so: its role model makes a class mismatch\n-- structurally impossible, so coding the check would be dead code. The port has exactly two escort task\n-- surfaces, each bound by this SUIT matrix to a single airframe class:\n--   \226\128\162 heli_escort \226\134\146 role \"heli\" ONLY (attack helis). It only ever escorts other HELICOPTERS\n--     (transport / BDA / troop-insertion helis, heli_war.spawn_escort), so escort and objective are both\n--     rotary \226\128\148 a heli-escorts-jet / jet-escorts-heli pairing can never arise.\n--   \226\128\162 oca_sweep   \226\134\146 role \"escort\" ONLY (fixed-wing fighters), sweeping ahead of fixed-wing strike.\n-- Because the board can only ever match each escort task to its one correct class, the assign.c:318-363\n-- gate is satisfied by construction; there is nothing to test at assignment time.\n\n-- \226\148\128\226\148\128 Per-role cruise speed (m/s) \226\128\148 the port's ACTUAL route velocities \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH's locality gate reads each group's live FLOAT_TYPE_CRUISE_VELOCITY (group.c:296). The port has\n-- no per-group velocity model, so the ETA gate uses the fixed cruise speed each role's spawner\n-- actually flies its route at \226\128\148 the faithful stand-in for \"the group's own cruise velocity\". Each\n-- value is cited to the port module that flies it (source of truth) and to group.c for the model:\n--   striker   220  \226\128\148 attack_waves.lua:68 / cas_bai_sead.lua:133 STRIKE_SPEED (ground/OCA strike, SEAD)\n--   escort    220  \226\128\148 cas_bai_sead.lua:293 / attack_waves.lua:289 escort leg flies at STRIKE_SPEED\n--   recon     300  \226\128\148 recon.lua:33 RECON_SPEED (fast recon dash in/out)\n--   heli       55  \226\128\148 heli_war.lua:40 HELI_SPEED (attack-heli CAS/BAI/BDA/anti-armour/HK/escort cruise)\n--   transport 100  \226\128\148 troop.lua:267 troop-insertion ingress leg speed\nlocal CRUISE_SPEED = {\n    striker = 220, escort = 220, recon = 300, heli = 55, transport = 100,\n}\nlocal CRUISE_SPEED_DEFAULT = 100   -- conservative fallback for any un-tabled role\n\n-- \226\148\128\226\148\128 Locality gate \226\128\148 EECH ETA test (assess_group_task_locality_factor, group.c:245-336) \226\148\128\226\148\128\n-- EECH accepts a group for a task iff its ETA to the task keysite is within the task's expire timer:\n--   eta = distance / cruise_speed;  reject iff eta > FLOAT_TYPE_EXPIRE_TIMER   (group.c:298,314)\n-- i.e. accept iff  distance <= cruise_speed(role) \195\151 expire_timer(task).  The port reuses its per-type\n-- unassigned-expiry (M.EXPIRY \226\128\148 the taskgen expire_timer values, ts_updt.c) as that timer and each\n-- role's actual route cruise speed (CRUISE_SPEED) as the group velocity. This replaces the old flat\n-- MAX_ASSIGN_RANGE 400 km hack (which sat arbitrarily between the real per-type reaches): the ETA gate\n-- legitimises long FIXED-WING reach (ground strike 220 m/s \195\151 40 min \226\137\136 528 km \226\128\148 the anti-stalemate reach\n-- the flat cap was hand-tuned to allow) while correctly CAPPING helicopters (CAS 55 m/s \195\151 20 min \226\137\136 66 km\n-- \226\128\148 the flat 400 km wrongly let FARP helis accept tasks they could never reach in time; EECH rejects\n-- them). TASK-F14 realigned. `t` carries its own expire window (t.expiry_t - t.created_t == M.EXPIRY\n-- value, honouring any per-task spec.expiry override).\nlocal function eta_range(role, t)\n    -- REMAINING window, not the total: EECH's expire_timer counts DOWN (ts_updt.c:107\n    -- `raw->expire_timer -= get_delta_time()`) and group.c:314 compares eta against that live\n    -- value \226\128\148 the acceptance radius SHRINKS as a task ages. Using the total window over-ranged\n    -- stale tasks (a 35-min-old ground strike kept its full 528 km reach with 5 min left).\n    local window = t.expiry_t - timer.getTime()\n    if window <= 0 then return 0 end\n    return (CRUISE_SPEED[role] or CRUISE_SPEED_DEFAULT) * window\nend\n\n-- \226\148\128\226\148\128 Per-keysite assign budget (eech assign_task_count, assign.c:218; ks_dbase.c:118 airbase=3) \226\148\128\226\148\128\n-- EECH assigns at most `assign_task_count` (airbase = 3) tasks FROM a keysite per assignment pass\n-- (assign.c:218 `assign_count = max(assign_task_count,1u)`; loop breaks at :224 when it hits 0). The\n-- port's board is one global pass, so this caps how many tasks a single base may launch per tick \226\128\148\n-- once a base has been chosen 3 times this pass it is skipped, and the task falls through to the next\n-- base (or stays UNASSIGNED for retry). Reset at the top of each M.tick.\nlocal ASSIGN_BUDGET_PER_BASE = 3\nlocal _assign_count = {}   -- base_name -> assignments made THIS board pass (reset in M.tick)\n\n-- \226\148\128\226\148\128 Minimum idle reserve per role (eech get_suitable_registered_group, assign.c:465-474) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH will not assign an idle group unless the keysite's idle count OF THAT GROUP SUB_TYPE strictly\n-- exceeds group_database[sub_type].minimum_idle_count (assign.c:474 `idle_count > minimum_idle_count`) \226\128\148\n-- a per-group-type DEFENSIVE RESERVE the assignment engine never spends offensively. It is a compiled-in\n-- group_database constant (gp_dbase.c), NOT warzone data. Per-role values, mapped to the EECH group\n-- sub_type each port role represents (assigning one group consumes one group, so the port keeps MIN_IDLE\n-- aircraft of the role idle after the task: ledger >= t.count + MIN_IDLE):\n--   heli      = 2  \226\128\148 ENTITY_SUB_TYPE_GROUP_ATTACK_HELICOPTER minimum_idle_count (gp_dbase.c:114); the\n--                    RECON_ATTACK_HELICOPTER row is 3 (gp_dbase.c:319) but the port's single \"heli\" role\n--                    is the plain attack helicopter, so its reserve (2) is used.\n--   striker   = 1  \226\128\148 ENTITY_SUB_TYPE_GROUP_CLOSE_AIR_SUPPORT_AIRCRAFT (gp_dbase.c:565): CAS/OCA/SEAD jets.\n--   escort    = 1  \226\128\148 ENTITY_SUB_TYPE_GROUP_MULTI_ROLE_FIGHTER (gp_dbase.c:442): CAP/BARCAP/sweep fighters.\n--   recon     = 0  \226\128\148 ENTITY_SUB_TYPE_GROUP_RECON_HELICOPTER (gp_dbase.c:278): no reserve.\n--   transport = 0  \226\128\148 MEDIUM/HEAVY_LIFT_TRANSPORT_HELICOPTER (gp_dbase.c:360/401): no reserve.\n--   vehicle   = 0  \226\128\148 frontline ground groups (gp_dbase.c:729/770): no reserve.\nlocal MIN_IDLE = { heli = 2, striker = 1, escort = 1, recon = 0, transport = 0, vehicle = 0 }\n\n-- \226\148\128\226\148\128 Non-USABLE keysite \195\1512 assign interval (eech ks_updt.c:118-123) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH doubles a keysite's assign_timer when its keysite_usable_state != KEYSITE_STATE_USABLE\n-- (ks_updt.c:120-123), so a not-fully-repaired keysite runs its assignment pass HALF as often. USABLE is\n-- set only when keysite_strength == keysite_maximum_strength; a captured/struck keysite below full\n-- strength is KEYSITE_STATE_REPAIRING (keysite.c:1468-1474). The port's board is ONE global 3-min pass,\n-- so the faithful proxy is: a non-usable (below-full-strength) base participates as a launch candidate\n-- every OTHER pass \226\128\148 a per-base skip flag toggles each tick (S.base_assign_toggle) and, while set, this\n-- table excludes the base from owned_bases for the current pass. Recomputed at the top of M.tick.\nlocal _skip_pass = {}   -- base_name -> true when skipped THIS board pass (Item 5)\n\n-- \226\148\128\226\148\128 Player task reservation count (eech ks_dbase.c:119 airbase reserve_task_count = 2) \226\148\128\226\148\128\n-- Per assign pass EECH holds back up to `reserve_task_count` FRESH, NON-CRITICAL tasks so a human\n-- gunship pilot can take them before the AI does (assign.c:220,244-255). Airbase row = 2\n-- (ks_dbase.c:119). Applied in M.tick's assignment loop (see the block there for the full semantics).\nlocal RESERVE_TASK_COUNT = 2\n\n-- \226\148\128\226\148\128 Player-flyable task set (single source of truth: pilots.PLAYER_FLYABLE) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- The reservation narrows to task types a human can actually fly here (the port's gunship-mission\n-- set). pilots.lua owns that list (PLAYER_FLYABLE); we read it rather than duplicate it. A deferred\n-- require avoids the pilots<->task_board load cycle (pilots requires task_board at load, so a\n-- top-level require back would be circular); by the time M.tick first fires, pilots is fully loaded\n-- and require() returns the cached module. Cached on first successful resolve.\nlocal _player_flyable\nlocal function player_flyable_set()\n    if not _player_flyable then\n        local ok, pilots = pcall(require, \"pilots\")\n        if ok and pilots then _player_flyable = pilots.PLAYER_FLYABLE end\n    end\n    return _player_flyable\nend\n\nlocal _tid = 0\nlocal function next_tid() _tid = _tid + 1; return _tid end\n\n-- Owned, usable bases sorted nearest-first to `pos` (nil pos \226\134\146 health order).\nlocal function owned_bases(side, pos)\n    local out = {}\n    for name, owner in pairs(S.base_owner) do\n        -- Item 1: a dormant FARP (not yet in_use \226\128\148 sector not friendly) is not a launch candidate\n        -- (eech nearest-keysite search skips !in_use keysites, keysite.c:369).\n        if owner == side and not _skip_pass[name] and cs.base_is_active(name) then   -- Item 5: non-USABLE base skips alternate passes\n            local h = S.base_health[name] or 1.0\n            if h >= cs.HEALTH_NEUTRALISED then   -- USABLE iff eff >= min (keysite.c:827-830, inclusive)\n                local bpos = S.base_pos[name]\n                if bpos then\n                    local d = pos and cs.dist2d(pos.x, pos.z, bpos.x, bpos.z) or 0\n                    out[#out + 1] = { name = name, pos = bpos, d = d, h = h }\n                end\n            end\n        end\n    end\n    if pos then\n        table.sort(out, function(a, b) return a.d < b.d end)\n    else\n        table.sort(out, function(a, b) return a.h > b.h end)\n    end\n    return out\nend\n\n-- \226\148\128\226\148\128 create_task \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- spec = { type, side, target = {base=, pos=, group=, objective=}, count, builder,\n--          priority?, critical?, expiry?, immediate?, log_fn? }\n-- builder(base_name) -> group|truthy on spawn success, nil/false on spawn failure.\n-- The board consumes `count` of the matched role from the CHOSEN base BEFORE calling builder;\n-- builder only builds the DCS group at that base (no reserve accounting of its own for the primary\n-- role). Returns the task record.\nfunction M.create_task(spec)\n    S.board_tasks = S.board_tasks or {}\n    local id  = next_tid()\n    local now = timer.getTime()\n    -- Explicit if (not `a and b or c`) so an explicit critical=false is honored over the type default.\n    local critical\n    if spec.critical ~= nil then critical = spec.critical else critical = M.CRITICAL[spec.type] or false end\n    local t = {\n        id       = id,\n        type     = spec.type,\n        side     = spec.side,\n        target   = spec.target or {},\n        count    = spec.count or 1,\n        builder  = spec.builder,\n        log_fn   = spec.log_fn or function() end,\n        origin   = spec.origin or spec.type,\n        priority = spec.priority or M.PRIORITY[spec.type] or 1,\n        critical = critical,\n        created_t = now,\n        expiry_t  = now + (spec.expiry or M.EXPIRY[spec.type] or UNASSIGNED_EXPIRY_DEFAULT),\n        state     = \"UNASSIGNED\",\n        assigned_group = nil,\n        dedup_key = \"board:\" .. id,\n        -- Supply tasks: the start keysite must not BE the requester (taskgen.c:1676) \226\128\148 try_assign\n        -- skips the target base itself as a launch candidate when this is set.\n        exclude_target_base = spec.exclude_target_base or false,\n    }\n    S.board_tasks[#S.board_tasks + 1] = t\n\n    -- Item 2 stats: a queued board task == a task created for its side (eech task-generation count).\n    cs.stat_task_created(spec.side)\n\n    -- Synthetic dedup marker so cs.has_task_against() sees this QUEUED task (dropped on assign/fail).\n    S.active_tasks = S.active_tasks or {}\n    S.active_tasks[t.dedup_key] = { task_type = t.type, target_base = t.target.base, side = t.side }\n\n    cs.dbg(\"board\", \"created #%d %s side=%s target=%s prio=%.1f critical=%s expiry=%.0fmin immediate=%s\",\n        id, t.type, cs.SIDE_NAME[t.side], t.target.base or \"field\", t.priority, tostring(t.critical),\n        (t.expiry_t - now) / 60, tostring(spec.immediate))\n\n    if spec.immediate then M.try_assign(t) end\n    return t\nend\n\n-- \226\148\128\226\148\128 try_assign: match one UNASSIGNED task to a base ledger and spawn \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.try_assign(t)\n    if t.state ~= \"UNASSIGNED\" then return false end\n    local suit = M.SUIT[t.type]\n    if not suit then return false end\n    local tpos  = t.target.pos\n    local bases = owned_bases(t.side, tpos)\n\n    -- Roles in ascending suitability (lowest positive first = assign.c:497 winner order).\n    for _, entry in ipairs(suit) do\n        local role, s = entry.role, entry.s\n        if s > 0 then\n            -- Among candidate bases (nearest-first), keep the LOWEST-positive suitability with\n            -- best_result=FLT_MAX / result<best (assign.c:433-501). Suitability is uniform, so the\n            -- strict `<` makes the FIRST qualifying (nearest, within range, stocked) base win \226\128\148\n            -- faithful to the spec's own note that the current data reduces the quirk to first-match.\n            local best_base, best_s = nil, math.huge\n            local range = eta_range(role, t)   -- cruise_speed(role) \195\151 expire_timer(task), group.c:298,314\n            for _, b in ipairs(bases) do\n                local within = (not tpos) or (b.d <= range)   -- ETA locality gate (group.c:314; TASK-F14)\n                -- start_ks != requester gate (taskgen.c:1676; supply tasks): never launch from the\n                -- base being resupplied \226\128\148 the transport would spawn inside its own delivery radius.\n                if t.exclude_target_base and b.name == t.target.base then within = false end\n                -- Per-base assign budget: a base that has already launched ASSIGN_BUDGET_PER_BASE tasks\n                -- this pass is skipped so the task falls through to the next base (assign.c:218,224).\n                local under_budget = (_assign_count[b.name] or 0) < ASSIGN_BUDGET_PER_BASE\n                -- Basing-capacity gate (Cluster 5): skip a base with no free landing slot, so it\n                -- falls through to the NEXT-best base; if no base has a free slot the task stays\n                -- UNASSIGNED and is retried until expiry (the starvation/throttle path). Mirrors the\n                -- landing-site availability check at assignment (eech assign.c:879, keysite.c:324).\n                local has_slot = ks.slot_available(b.name) >= 1\n                -- Minimum idle reserve (assign.c:474): keep MIN_IDLE[role] of the role idle at the base\n                -- (never spent on offensive board tasks), so require ledger >= t.count + MIN_IDLE[role].\n                local need = t.count + (MIN_IDLE[role] or 0)\n                if within and under_budget and has_slot and supply.ledger(b.name, role) >= need and s < best_s then\n                    best_s   = s\n                    best_base = b.name\n                end\n            end\n            if not best_base and not t._dbg_logged then\n                -- One-shot funnel diagnostic: why did no base qualify? (range / stock / slot / budget)\n                local nb, nr, nstock, nslot, nbudget = #bases, 0, 0, 0, 0\n                local need = t.count + (MIN_IDLE[role] or 0)   -- incl. minimum idle reserve (assign.c:474)\n                for _, b in ipairs(bases) do\n                    if (not tpos) or (b.d <= range) then nr = nr + 1 end\n                    if supply.ledger(b.name, role) >= need then nstock = nstock + 1 end\n                    if ks.slot_available(b.name) >= 1 then nslot = nslot + 1 end\n                    if (_assign_count[b.name] or 0) < ASSIGN_BUDGET_PER_BASE then nbudget = nbudget + 1 end\n                end\n                t._dbg_logged = true\n                cs.dbg(\"board\", \"%s %s vs %s UNASSIGNED (role=%s): owned_bases=%d in_range=%d(<=%.0fkm) stocked=%d free_slot=%d w/budget=%d\",\n                    cs.SIDE_NAME[t.side], t.type, (t.target and t.target.base) or \"field\",\n                    role, nb, nr, range / 1000, nstock, nslot, nbudget)\n            end\n            if best_base then\n                if supply.consume_base(best_base, role, t.count) then\n                    -- pcall the builder so a THROW (e.g. coalition.addGroup raising) still refunds the\n                    -- ledger \226\128\148 a missed refund silently drains a base forever (dev-loop guardrail).\n                    local ok_b, grp = pcall(t.builder, best_base)\n                    if ok_b and grp then\n                        t.state = \"ASSIGNED\"\n                        t.role  = role\n                        t.base  = best_base\n                        local ok_n, nm = pcall(function()\n                            return (type(grp) == \"table\" and grp.getName) and grp:getName() or nil\n                        end)\n                        t.assigned_group = ok_n and nm or nil\n                        -- Occupy a landing slot at the launch base (Cluster 5). Reserve keyed by the\n                        -- spawned group's name so the slot releases on its RTB-land / death. If the\n                        -- name could not be resolved we skip (cannot track release \226\134\146 do not leak a slot).\n                        if t.assigned_group then ks.reserve_slot(best_base, t.assigned_group) end\n                        _assign_count[best_base] = (_assign_count[best_base] or 0) + 1   -- per-base budget (assign.c:218)\n                        S.active_tasks[t.dedup_key] = nil   -- hand off to the spawned group's registration\n                        cs.dbg(\"board\", \"#%d %s vs %s ASSIGNED base=%s role=%s group=%s (waited %.0fs)\",\n                            t.id, t.type, (t.target and t.target.base) or \"field\", best_base, role,\n                            tostring(t.assigned_group), timer.getTime() - t.created_t)\n                        return true\n                    else\n                        -- Refund discipline: spawn failed OR threw \226\134\146 credit the ledger back; task stays\n                        -- UNASSIGNED and is retried next tick until it expires.\n                        supply.recycle_base(best_base, role, t.count)\n                        if not ok_b then t.log_fn(\"task_board builder error: \" .. tostring(grp)) end\n                        cs.dbg(\"board\", \"#%d %s vs %s builder FAILED at base=%s role=%s ok=%s -> refunded, retry\",\n                            t.id, t.type, (t.target and t.target.base) or \"field\", best_base, role, tostring(ok_b))\n                        return false\n                    end\n                end\n            end\n        end\n    end\n    -- Diagnostic: a CRITICAL task (troop_insertion / OCA) that can't assign is a stalled payoff \226\128\148\n    -- log WHY (in-range / has-slot / has-stock counts), throttled per type, so starvation is visible.\n    if M.CRITICAL[t.type] and suit[1] then\n        local role = suit[1].role\n        local range = eta_range(role, t)   -- group.c:298,314 (TASK-F14)\n        local inrange, slotted, stocked = 0, 0, 0\n        for _, b in ipairs(bases) do\n            if (not tpos) or b.d <= range then\n                inrange = inrange + 1\n                if ks.slot_available(b.name) >= 1 then\n                    slotted = slotted + 1\n                    if supply.ledger(b.name, role) >= t.count + (MIN_IDLE[role] or 0) then stocked = stocked + 1 end\n                end\n            end\n        end\n        S._board_diag = S._board_diag or {}\n        if (timer.getTime() - (S._board_diag[t.type] or 0)) > 30 then\n            S._board_diag[t.type] = timer.getTime()\n            t.log_fn(string.format(\n                \"board: %s vs %s UNASSIGNED \226\128\148 %d owned, %d in-range, %d w/slot, %d w/%s-stock\",\n                t.type, (t.target and t.target.base) or \"?\", #bases, inrange, slotted, stocked, role))\n            cs.dbg(\"board\", \"CRITICAL STALL %s vs %s: %d owned, %d in-range, %d w/slot, %d w/%s-stock\",\n                t.type, (t.target and t.target.base) or \"?\", #bases, inrange, slotted, stocked, role)\n        end\n    end\n    return false   -- no suitable base with stock in range \226\134\146 remains UNASSIGNED (retry until expiry)\nend\n\n-- \226\148\128\226\148\128 assign_to_player: a human binds an UNASSIGNED task (PILOT-F19) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH reserves player-flyable tasks in the assign pass (reserve_task_count, assign.c:220-255) so a\n-- human gunship can take one before the AI; on binding, the task becomes ASSIGNED with the player's\n-- gunship as its object (get_local_entity_primary_task, helicop.c:314). This is that binding for the\n-- port: the task LEAVES the AI unassigned pool (state \226\134\146 ASSIGNED, compacted out of board_tasks next\n-- tick) and is registered under the player's group name so reaction/dedup treat the human sortie\n-- exactly like an AI one \226\128\148 the defender's under-attack CAP scrambles against it, completion fires on\n-- the player's LAND, and death clears it. Deliberately DIFFERENT from try_assign: NO ledger consume\n-- (the human airframe is not reserve hardware) and NO landing-slot reserve (the player occupies a real\n-- DCS slot). Returns true on success.\nfunction M.assign_to_player(t, gname, gid)\n    if not t or t.state ~= \"UNASSIGNED\" then return false end\n    if not gname then return false end\n    t.state          = \"ASSIGNED\"\n    t.assigned_group = gname\n    t.role           = \"player\"\n    t.player         = true\n    S.active_tasks = S.active_tasks or {}\n    S.active_tasks[t.dedup_key] = nil   -- drop the queued-task dedup marker (hand off to the group name)\n    cs.register_task(gname, {\n        task_type   = t.type,\n        side        = t.side,\n        target_base = t.target and t.target.base,\n        target_pos  = t.target and t.target.pos,\n        objective   = (t.target and t.target.objective) or\n                      { kind = \"keysite\", base = t.target and t.target.base },\n        born_time   = timer.getTime(),\n        player      = true,\n    })\n    -- F4b: draw the player sortie's F-10 task arrow (AI assignments get theirs in the spawners; the\n    -- player path spawns nothing, so draw here). From = the player's current position; if the group\n    -- can't be resolved, skip (a zero-length arrow at the target is useless). Lifecycle already reaped:\n    -- cs.clear_task fires the map_overlay task_end_hook, and the GC backstop covers a vanished group.\n    pcall(function()\n        local tpos = t.target and t.target.pos\n        if not tpos then return end\n        local grp = Group.getByName(gname)\n        local u = grp and grp:getUnit(1)\n        if u and u:isExist() then\n            local p = u:getPosition().p\n            require(\"map_overlay\").add_task_arrow(gname, { x = p.x, z = p.z }, tpos, t.side)\n        end\n    end)\n    cs.dbg(\"board\", \"#%d %s vs %s ASSIGNED to PLAYER group=%s (left AI pool, no ledger/slot)\",\n        t.id, t.type, (t.target and t.target.base) or \"field\", tostring(gname))\n    return true\nend\n\n-- \226\148\128\226\148\128 tick: expire, sort by priority, assign; then compact \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.tick(log_fn)\n    log_fn = log_fn or function() end\n    if not S.board_tasks then return end\n    local now = timer.getTime()\n    _assign_count = {}   -- reset the per-base assign budget for this pass (assign.c:218)\n\n    -- Item 5: recompute the non-USABLE per-base skip set for this pass (ks_updt.c:118-123). A base below\n    -- full strength (KEYSITE_STATE_REPAIRING/UNUSABLE \226\128\148 USABLE \226\159\186 strength==max, keysite.c:1468-1474) has\n    -- its assign interval doubled, i.e. it participates as a launch candidate every OTHER pass. Toggle a\n    -- per-base flag each tick: while set, owned_bases excludes the base. Fully-usable bases never skip.\n    S.base_assign_toggle = S.base_assign_toggle or {}\n    _skip_pass = {}\n    local n_skip = 0\n    for name, owner in pairs(S.base_owner) do\n        if owner == coalition.side.BLUE or owner == coalition.side.RED then\n            if (S.base_health[name] or 1.0) >= 1.0 then\n                S.base_assign_toggle[name] = nil          -- USABLE (full strength): every pass\n            else\n                local skip = not S.base_assign_toggle[name]   -- non-USABLE: flip skip/serve each tick\n                S.base_assign_toggle[name] = skip\n                if skip then _skip_pass[name] = true; n_skip = n_skip + 1 end\n            end\n        end\n    end\n    if n_skip > 0 then\n        cs.dbg(\"board\", \"assign-interval \195\1512: %d non-USABLE base(s) skipped this pass (ks_updt.c:118-123)\", n_skip)\n    end\n\n    -- 1) Expire UNASSIGNED tasks past their window \226\134\146 FAILED (ts_updt.c:99-124 / TASK-F10.7).\n    local live = {}\n    for _, t in ipairs(S.board_tasks) do\n        if t.state == \"UNASSIGNED\" then\n            if now > t.expiry_t then\n                t.state = \"FAILED\"\n                S.active_tasks[t.dedup_key] = nil\n                S.board_failed = (S.board_failed or 0) + 1\n                log_fn(string.format(\"task_board: %s vs %s EXPIRED after %.0fmin unassigned \226\134\146 FAILED (no suitable idle group)\",\n                    t.type, (t.target and t.target.base) or \"field\", (now - t.created_t) / 60))\n                cs.dbg(\"board\", \"#%d %s vs %s EXPIRED after %.0fmin -> FAILED (total board_failed=%d)\",\n                    t.id, t.type, (t.target and t.target.base) or \"field\", (now - t.created_t) / 60, S.board_failed)\n            else\n                live[#live + 1] = t\n            end\n        end\n    end\n\n    -- 2) Sort by priority, critical \195\1512 (assign.c:201-204).\n    table.sort(live, function(a, b)\n        local pa = a.priority * (a.critical and 2.0 or 1.0)\n        local pb = b.priority * (b.critical and 2.0 or 1.0)\n        return pa > pb\n    end)\n\n    -- 3) Assign in priority order \226\128\148 with PLAYER TASK RESERVATION (assign.c:220-255).\n    -- EECH holds back up to reserve_task_count (=2 airbase, ks_dbase.c:119) FRESH, NON-CRITICAL tasks\n    -- per keysite per assign pass so a human gunship pilot can take them (assign.c:220,244-253). The\n    -- exact EECH predicate for a reservable task, per pass, while the counter is > 0:\n    --     !INT_TYPE_CRITICAL_TASK                                    (assign.c:244 \226\128\148 never reserve critical)\n    --   &&  FLOAT_TYPE_EXPIRE_TIMER > KEYSITE_TASK_ASSIGN_TIMER      (assign.c:246 \226\128\148 only while \"fresh\")\n    -- When matched it does non_critical_task_count-- and `continue` (skips AI assignment, leaves the task\n    -- UNASSIGNED). KEYSITE_TASK_ASSIGN_TIMER = 3 min (keysite.h:69) == our ASSIGN_CADENCE, so \"fresh\"\n    -- means remaining time-to-expiry > one assign cadence. Reservation LAPSES BY AGING: once a reserved\n    -- task's remaining window falls to <= ASSIGN_CADENCE it is no longer reservable and falls through to\n    -- AI assignment on a later pass \226\128\148 it ages into AI use BEFORE expiry (EECH never holds it to expiry).\n    --\n    -- Port adaptations (cited divergences):\n    --   * The board runs ONE global pass (no per-keysite passes, spec 07-F9), so the reserve budget is a\n    --     single global counter per pass \226\128\148 the faithful proxy for EECH's per-keysite reserve_task_count.\n    --   * Reservable set is narrowed to PLAYER-FLYABLE types (pilots.PLAYER_FLYABLE, single source of\n    --     truth) \226\128\148 only those can ever be flown by a human here; EECH reserves any non-critical task for\n    --     player gunships, but the port's fixed-wing striker/SEAD/recon tasks are AI-only (PILOT-F17).\n    --   * SCALE proxy (adversarial-review Finding 1b): EECH reserves 2 PER KEYSITE across many keysites,\n    --     so its reservation is a small fraction of the task flow; the port's single global pass makes a\n    --     flat global-2 hold ~half of each rotary CAS/BAI cycle hostage for ~the full window. Reserving\n    --     only while a human pilot is actually CONNECTED keeps the intent (missions left for humans,\n    --     assign.c:244-255) without the scale distortion on an empty server. Reserved tasks are only\n    --     DELAYED (they age into AI assignment), never dropped.\n    -- Critical-path safety: immediate=true reaction tasks call try_assign directly from create_task and\n    -- never enter this loop, so the reaction chain is never throttled by reservation (EECH likewise\n    -- reserves only in the periodic assign pass, not on the immediate assign path).\n    local humans_present = false\n    for _, ps in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        local okp, plist = pcall(coalition.getPlayers, ps)\n        local players = (okp and plist) or {}   -- provable table for the analyzer (no and/or narrowing)\n        if #players > 0 then humans_present = true; break end\n    end\n    local reserve_left = humans_present and RESERVE_TASK_COUNT or 0\n    local flyable = player_flyable_set()\n    for _, t in ipairs(live) do\n        local reservable = reserve_left > 0 and flyable and flyable[t.type]\n            and not t.critical                             -- assign.c:244\n            and (t.expiry_t - now) > ASSIGN_CADENCE        -- assign.c:246 (\"fresh\")\n        if reservable then\n            reserve_left = reserve_left - 1\n            cs.dbg(\"board\", \"reserved #%d %s vs %s for players (%d/%d reserve left, %.0fs to expiry)\",\n                t.id, t.type, (t.target and t.target.base) or \"field\",\n                reserve_left, RESERVE_TASK_COUNT, t.expiry_t - now)\n        else\n            local ok, err = pcall(M.try_assign, t)\n            if not ok then log_fn(\"task_board assign error: \" .. tostring(err)) end\n        end\n    end\n\n    -- 4) Compact: keep only still-UNASSIGNED records (ASSIGNED handed to the group lifecycle;\n    --    FAILED are terminal). Bounds S.board_tasks growth.\n    local kept = {}\n    for _, t in ipairs(S.board_tasks) do\n        if t.state == \"UNASSIGNED\" then kept[#kept + 1] = t end\n    end\n    S.board_tasks = kept\nend\n\n-- NOTE: M.has_live_task_of_type_against was DELETED in Cluster H (zero callers) \226\128\148 it was a spec-facing\n-- alias of cs.has_task_against, which every dedup site calls directly. The board's synthetic markers\n-- put UNASSIGNED tasks INTO active_tasks, so cs.has_task_against already covers both queued + flying.\n\n-- \226\148\128\226\148\128 Scheduler registration (called once from game_loop.start) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nfunction M.schedule(log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    cs.dbg(\"board\", \"scheduler REGISTERED cadence=%.0fs offset=%.0fs\", ASSIGN_CADENCE, ASSIGN_CADENCE)\n    timer.scheduleFunction(function(_, t)\n        -- POST-VICTORY (Item 6 LITERAL semantics): the whole task pipeline keeps running after the win \226\128\148\n        -- generators keep QUEUEING and this pass keeps ASSIGNING, exactly as EECH (fc_msgs.c:163 gates\n        -- only the win-check re-award; nothing else is session-gated). The former Cluster-E generator\n        -- game_over gates were removed in WAVE 5 Item 6.\n        if _DMT_GEN ~= my_gen then return nil end\n        local n_unassigned = S.board_tasks and #S.board_tasks or 0\n        cs.dbg(\"board\", \"tick FIRE: %d unassigned queued before pass\", n_unassigned)\n        local ok, err = pcall(M.tick, log_fn)\n        if not ok then log_fn(\"task_board tick error: \" .. tostring(err)) end\n        return t + ASSIGN_CADENCE\n    end, nil, timer.getTime() + ASSIGN_CADENCE)\nend\n\nreturn M\n"
__modules["transfer"] = "-- transfer.lua\n-- EECH source: aphavoc/source/ai/highlevl/highlevl.c\n--\n-- create_fixed_wing_transfer_tasks()  line 2132\n--   Period:  15.0*ONE_MINUTE (skirmish line 232 / campaign line 262)\n--   Offsets: 34.0 s (skirmish) / 2.5*ONE_MINUTE=150 s (campaign)\n--   Score: base_dist*4 + (1 - min(idle_count,4)*0.25)*4;  max=8.0\n--   Commented-out terms (importance, airdef, surfdef) are NOT included.\n--   Pairing: sort descending; top CREATE_TRANSFER_TASK_COUNT=3 receive from bottom donors.\n--     keysite_count = min(count/2, CREATE_TRANSFER_TASK_COUNT)  (line 2294)\n--     donar = target_list[loop2]  (highest index = lowest rating = most idle aircraft)\n--     target = target_list[loop]  (lowest index = highest rating = most needed reinforcement)\n--     Condition: donor != target; target has landing sites available.\n--\n-- create_helicopter_transfer_tasks() line 2352\n--   Period:  10.0*ONE_MINUTE (skirmish line 238) / 7.5*ONE_MINUTE (campaign line 260)\n--   Offsets: 3.0*ONE_MINUTE=180 s (skirmish) / 2.0*ONE_MINUTE=120 s (campaign)\n--   Score: IDENTICAL formula and max to fixed-wing (same source block, same coefficients).\n--\n-- EECH constants:\n--   CREATE_TRANSFER_TASK_COUNT = 3 (line 102)\n--   MAX_HIGHLEVEL_TARGET_CHECKS = 160 (line 84)\n--\n-- DCS proxy notes:\n--   EECH transfers fly real aircraft from donor keysite to target keysite via task.\n--   DCS proxy: immediately adjust supply.available() counts \226\128\148 consume from donor,\n--   produce at target.  No flight is spawned; the aircraft materialises at the new base.\n--   idle_group_count proxy: supply.available(base, type) \226\128\148 more reserve = more idle.\n--   Clamped to [0, 4] then \195\1510.25, matching EECH: min(idle, 4.0f) \195\151 0.25.\n\nlocal cs     = require(\"campaign_state\")\nlocal imap_m = require(\"imap\")\nlocal supply = require(\"supply\")\nlocal S      = cs.S\nlocal M      = {}\n\n-- \226\148\128\226\148\128 EECH constants \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal CREATE_TRANSFER_TASK_COUNT = 3    -- highlevl.c line 102\nlocal MAX_HIGHLEVEL_TARGET_CHECKS = 160 -- highlevl.c line 84\nlocal TRANSFER_MAX_RATING         = 8.0 -- highlevl.c lines 2264, 2474\n\n-- \226\148\128\226\148\128 Periods (from add_high_level_ai_function; Item 5: mode-selected via campaign_mode.lua) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal mode        = require(\"campaign_mode\")\nlocal PERIOD_FW   = mode.SCHED.fw_transfer.period  -- :262 15min campaign / :232 15min skirmish\nlocal OFFSET_FW   = mode.SCHED.fw_transfer.blue    -- :262 campaign offset 2.5 min (fallback offset)\nlocal PERIOD_HC   = mode.SCHED.hc_transfer.period  -- :260 7.5min campaign / :238 10min skirmish\nlocal OFFSET_HC   = mode.SCHED.hc_transfer.blue    -- :260 campaign offset 2.0 min (fallback offset)\n\n-- \226\148\128\226\148\128 idle_group_count proxy \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- EECH: counts GROUP_MODE_IDLE groups physically attached to a keysite that match\n-- the landing type (FW or HC).\n-- DCS proxy: count alive same-side groups whose lead unit is within 5 km of the base.\n-- These represent groups currently \"at\" the base (parked / idle), matching EECH semantics.\n-- S.base_idle_groups[name] is updated by update_idle_groups() each transfer tick.\n-- Falls back to supply.available() if the idle count table is not yet populated.\nlocal IDLE_RADIUS = 5000  -- metres; groups within this radius count as \"at\" the base\n\nlocal function update_idle_groups(side)\n    S.base_idle_groups = S.base_idle_groups or {}\n    local r2 = IDLE_RADIUS * IDLE_RADIUS\n    -- Reset counts for all own bases\n    for name, owner in pairs(S.base_owner) do\n        if owner == side then S.base_idle_groups[name] = 0 end\n    end\n    -- Count alive groups near each base\n    local grps = coalition.getGroups(side)\n    if not grps then return end\n    for _, grp in ipairs(grps) do\n        if grp and grp:isExist() then\n            local u = grp:getUnit(1)\n            if u and u:isExist() then\n                local gpos = u:getPosition().p\n                for name, owner in pairs(S.base_owner) do\n                    if owner == side then\n                        local bpos = S.base_pos[name]\n                        if bpos then\n                            local dx = gpos.x - bpos.x\n                            local dz = gpos.z - bpos.z\n                            if dx*dx + dz*dz <= r2 then\n                                S.base_idle_groups[name] = (S.base_idle_groups[name] or 0) + 1\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\nend\n\nlocal function idle_fraction(base_name)\n    local count = S.base_idle_groups and S.base_idle_groups[base_name] or 0\n    local clamped = math.min(count, 4.0)\n    return clamped * 0.25  -- maps 0\226\134\1460.0, 1\226\134\1460.25, 2\226\134\1460.5, 3\226\134\1460.75, 4\226\134\1461.0\nend\n\n-- \226\148\128\226\148\128 Score (shared between FW and HC \226\128\148 formulas are identical in EECH source) \226\148\128\226\148\128\n-- rating = base_dist*4 + (1 - idle_fraction)*4\n-- IMAP_BASE_DISTANCE is queried for ENEMY side (closest to enemy base \226\134\146 most threatened)\nlocal function score_base(base_name, enemy_side, side, atype)\n    local bpos = S.base_pos[base_name]\n    if not bpos then return 0.0 end\n    -- Base must be usable: eff >= min inclusive (KEYSITE_STATE_USABLE, keysite.c:827-830)\n    local h = S.base_health[base_name] or 0.0\n    if h < cs.HEALTH_NEUTRALISED then return 0.0 end\n\n    local bdist = imap_m.get(enemy_side, imap_m.BASE_DISTANCE, bpos)\n    local idle  = idle_fraction(base_name)\n\n    -- EECH formula: base_dist*4 + (1 - min(idle,4)*0.25)*4; max=8.0\n    -- Commented-out terms (importance, airdef, surfdef) not included per source.\n    return bdist * 4.0 + (1.0 - idle) * 4.0\nend\n\n-- \226\148\128\226\148\128 Transfer one unit from donor to target \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors create_transfer_task: aircraft moves from donar keysite to target keysite.\n-- DCS proxy: consume 1 from donor supply, produce 1 at target.\nlocal function do_transfer(atype, donor_name, target_name, side, log_fn)\n    if not supply.consume(donor_name, atype, 1) then\n        log_fn(string.format(\"transfer: no %s at donor %s\", atype, donor_name))\n        cs.dbg(\"transfer\", \"%s transfer ABORT: no %s at donor %s\", cs.SIDE_NAME[side], atype, donor_name)\n        return false\n    end\n    supply.produce(target_name, atype, 1)\n    log_fn(string.format(\"%s transfer (%s): %s \226\134\146 %s\",\n        cs.SIDE_NAME[side], atype, donor_name, target_name))\n    cs.dbg(\"transfer\", \"%s transfer: 1x %s %s -> %s\", cs.SIDE_NAME[side], atype, donor_name, target_name)\n    return true\nend\n\n-- \226\148\128\226\148\128 Shared transfer scheduler for FW or HC \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal function run_transfer(side, atype, log_fn)\n    local enemy  = cs.ENEMY[side]\n    -- Update idle group count before scoring (mirrors GROUP_MODE_IDLE scan per keysite)\n    update_idle_groups(side)\n    local ratings = {}\n\n    -- Score all own bases\n    for name, owner in pairs(S.base_owner) do\n        if owner == side then\n            local r = score_base(name, enemy, side, atype)\n            if r > 0.0 then\n                ratings[#ratings + 1] = { name = name, rating = r }\n            end\n        end\n    end\n\n    if #ratings < 2 then\n        cs.dbg(\"transfer\", \"%s %s: only %d usable base(s) rated, skipping (need >=2)\", cs.SIDE_NAME[side], atype, #ratings)\n        return\n    end  -- need at least one donor and one target\n\n    -- Sort descending (highest rating first = most needs reinforcement)\n    table.sort(ratings, function(a, b) return a.rating > b.rating end)\n\n    -- keysite_count = min(count/2, CREATE_TRANSFER_TASK_COUNT)  (line 2294/2514)\n    local keysite_count = math.min(math.floor(#ratings / 2), CREATE_TRANSFER_TASK_COUNT)\n    local loop2 = #ratings  -- bottom index (lowest rating = most idle = donor)\n    local n_done = 0\n\n    for loop = 1, keysite_count do\n        local target = ratings[loop]\n        local donor  = ratings[loop2]\n        -- Mirrors: donar = target_list[loop2]; target = target_list[loop]\n        -- Guard: donor != target (EECH checks landing sites; we check names and supply)\n        if target.name ~= donor.name and supply.available(donor.name, atype) > 0 then\n            if do_transfer(atype, donor.name, target.name, side, log_fn) then n_done = n_done + 1 end\n        end\n        loop2 = loop2 - 1\n    end\n    cs.dbg(\"transfer\", \"%s %s: %d bases rated -> %d pairing slots -> %d transfers executed\",\n        cs.SIDE_NAME[side], atype, #ratings, keysite_count, n_done)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Fixed-wing transfer scheduler\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\nfunction M.schedule_fw_transfer(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    local offset = initial_offset or OFFSET_FW\n    cs.dbg(\"transfer\", \"%s FW transfer scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], offset, PERIOD_FW)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        -- Item 6: transfers keep running post-victory (EECH fc_msgs.c:163 gates only the win re-award).\n        cs.dbg(\"transfer\", \"%s FW transfer FIRE\", cs.SIDE_NAME[side])\n        local ok, err = pcall(function()\n            run_transfer(side, \"striker\", log_fn)\n            run_transfer(side, \"escort\", log_fn)\n        end)\n        if not ok then log_fn(\"FW transfer error: \" .. tostring(err)) end\n        return t + PERIOD_FW\n    end, nil, timer.getTime() + offset)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Helicopter transfer scheduler\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\nfunction M.schedule_hc_transfer(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    local offset = initial_offset or OFFSET_HC\n    cs.dbg(\"transfer\", \"%s HC transfer scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], offset, PERIOD_HC)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        -- Item 6: transfers keep running post-victory (EECH fc_msgs.c:163 gates only the win re-award).\n        cs.dbg(\"transfer\", \"%s HC transfer FIRE\", cs.SIDE_NAME[side])\n        local ok, err = pcall(function()\n            run_transfer(side, \"heli\", log_fn)\n        end)\n        if not ok then log_fn(\"HC transfer error: \" .. tostring(err)) end\n        return t + PERIOD_HC\n    end, nil, timer.getTime() + offset)\nend\n\nreturn M\n"
__modules["troop"] = "-- troop.lua\n-- EECH source: aphavoc/source/ai/highlevl/highlevl.c\n--\n-- create_troop_insertion_tasks() line 1660\n--   Period: 2.0*ONE_MINUTE (skirmish line 234) / 2.0*ONE_MINUTE (campaign line 256) \226\134\146 SAME both modes\n--   Offset: 60 s (skirmish) / 1.0*ONE_MINUTE=60 s (campaign)\n--   Targets: enemy keysites where keysite_database[type].troop_insertion_target==true\n--            AND efficiency < minimum_efficiency\n--   Score: (1-airdef)*1 + base_dist*3 + (1-efficiency)*3 + sector_ratio*2; max=9.0\n--   Limits: CREATE_TROOP_INSERTION_TASK_COUNT=2 (line 97), MIN_TASK_CREATION_RATIO=0.75\n--   FOW: fow >= 0.20 * maximum (line 1819: if fow < 0.20 \226\134\146 create recon instead)\n--   NOTE: commented-out \"low enemy importance\" term not included (line source: // rating += ...)\n--\n-- create_troop_patrol_tasks() line 2735\n--   Period: 10.0*ONE_MINUTE (skirmish line 230) / 5.0*ONE_MINUTE (campaign line 248)\n--   Offset: 5 s (both modes)\n--   Targets: own FARP, military base, airbase keysites\n--   Limit: 1 patrol group per keysite (groups_limit=1 line 2775)\n--   Group: 4 infantry units (FORMATION_COMPONENT_INFANTRY, count=4, line 2812)\n--   Spawn radius: 300 + frand1()*50 metres from keysite (line 2805-2808)\n--   Capture mechanic: patrol task \226\134\146 guard area; if enemy keysite switches \226\134\146 reaction chain\n--\n-- Capture-on-ARRIVAL (eech mb_msgs.c:2260-2325, response_to_waypoint_troop_capture_reached):\n--   EECH fires the capture roll when the insertion group physically REACHES the TROOP_CAPTURE\n--   waypoint at the destination keysite \226\128\148 NOT at dispatch, and with NO offload delay. The port\n--   mirrors this 1:1: check_landing_helis detects the \"Insert-*\" heli arriving within\n--   CAPTURE_RADIUS of ITS OWN registered target_base (never any other base the flight line passes)\n--   and rolls IMMEDIATELY \226\128\148 members = surviving units, losses = units lost en route (eech reads the\n--   GROUP's INT_TYPE_MEMBER_COUNT / INT_TYPE_LOSSES at 2293-2295), against the keysite's CURRENT\n--   efficiency (FLOAT_TYPE_EFFICIENCY read at the event, 2283) \226\128\148 a base repaired above minimum\n--   REPELS. A transport shot down en route never reaches the waypoint \226\134\146 no roll (eech: task\n--   terminates on group death), and the DEAD handler clears the task + slot. On a won roll\n--   keysite.do_capture applies side flip + instant repair + regen reseed + win re-check\n--   (eech capture_keysite, keysite.c:1289-1518).\n--\n-- EECH constants referenced:\n--   CREATE_TROOP_INSERTION_TASK_COUNT = 2 (highlevl.c line 97)\n--   MIN_TASK_CREATION_RATIO           = 0.75 (highlevl.c line 90)\n--   MAX_HIGHLEVEL_TARGET_CHECKS       = 160 (highlevl.c line 84)\n\nlocal cs      = require(\"campaign_state\")\nlocal croute  = require(\"croute\")\nlocal imap_m  = require(\"imap\")\nlocal fow_m   = require(\"fog_of_war\")\nlocal frontl  = require(\"frontline\")\nlocal keysite = require(\"keysite\")\nlocal board   = require(\"task_board\")\nlocal config  = require(\"config\")\nlocal S       = cs.S\nlocal M       = {}\n\n-- \226\148\128\226\148\128 EECH constants \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal CREATE_TROOP_INSERTION_TASK_COUNT = 2      -- highlevl.c line 97\nlocal MIN_TASK_CREATION_RATIO           = 0.75   -- highlevl.c line 90\nlocal MAX_HIGHLEVEL_TARGET_CHECKS       = 160    -- highlevl.c line 84\n\n-- \226\148\128\226\148\128 EECH FOW threshold \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- line 1819: if fow < 0.20 * maximum \226\134\146 create recon; else proceed with T.I.\n-- So T.I. requires fow >= 0.20 (matches fog_of_war.THRESHOLD_TROOP)\nlocal FOW_THRESHOLD_TI = 0.20\n\n-- \226\148\128\226\148\128 EECH minimum_efficiency \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- eech ks_dbase.c: minimum_efficiency = 0.3 for ALL keysite types (spec 03 \194\1672.3).\n-- Troop-insertion (capture) tasks are generated ONLY against enemy keysites whose\n-- efficiency < minimum_efficiency (eech highlevl.c:1724-1732). Shared constant in campaign_state.\nlocal MINIMUM_EFFICIENCY = cs.MINIMUM_EFFICIENCY   -- 0.3\n\n-- Capture-roll troop inputs (eech mb_msgs.c:2293-2297): the roll multiplies the efficiency term by\n-- member_count / (member_count + losses), read from the INSERTION GROUP (NOT the keysite garrison) \226\128\148\n-- member_count = INT_TYPE_MEMBER_COUNT (troops still alive at the waypoint), losses = INT_TYPE_LOSSES\n-- (troops killed en route). The port maps these to the DCS transport group's live census at arrival:\n--   members = grp:getSize()  (surviving units), losses = grp:getInitialSize() - grp:getSize().\n-- EECH inserts a multi-member troop division; the port stages a single transport heli, so in practice\n-- members=1/losses=0 (an insertion that loses units is shot down entirely \226\134\146 no capture attempt at all,\n-- mb_msgs path never runs). The wiring is faithful regardless of group size. Fallback if the group is\n-- gone at resolution: the 4-man infantry component (eech highlevl.c:2812).\nlocal TROOP_MEMBER_FALLBACK = 4\n\n-- \226\148\128\226\148\128 Periods (from add_high_level_ai_function; Item 5: mode-selected via campaign_mode.lua) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal mode           = require(\"campaign_mode\")\nlocal PERIOD_TI      = mode.SCHED.troop_insertion.period  -- :256 2min campaign / :234 2min skirmish\nlocal OFFSET_TI      = mode.SCHED.troop_insertion.blue    -- :256 campaign 1.0*ONE_MINUTE (fallback offset)\nlocal PERIOD_PATROL  = mode.SCHED.patrol.period           -- :248 5min campaign / :230 10min skirmish\nlocal OFFSET_PATROL  = mode.SCHED.patrol.blue             -- :248 offset 5 s (fallback offset)\n\n-- \226\148\128\226\148\128 Patrol group radius (line 2805-2808) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- pos.x = keysite_pos.x + cos(angle) * (300 + frand1()*50)\n-- pos.z = keysite_pos.z + sin(angle) * (300 + frand1()*50)\n-- frand1() \226\134\146 random float 0\226\128\1471; we use midpoint 325 m.\nlocal PATROL_BASE_RADIUS = 300   -- metres (EECH: 300 + frand1()*50)\nlocal PATROL_RADIUS_JITTER = 50  -- metres (frand1()*50)\n\n-- \226\148\128\226\148\128 Heli AC types (hoisted to config transport_heli; T.I. uses heli category) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal AC_HELI = {}\n-- Ground infantry type for patrol (config types.ground.infantry; proxy for FORMATION_COMPONENT_INFANTRY)\nlocal INFANTRY_TYPE = {}\nfor _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n    AC_HELI[side]      = { country = config.C.countries[side], heli_type = config.C.types.aircraft[side].transport_heli }\n    INFANTRY_TYPE[side] = { country = config.C.countries[side], unit = config.C.types.ground.infantry[side] }\nend\n\n-- \226\148\128\226\148\128 Sector ratio proxy (same as in cas_bai_sead.lua) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\nlocal SECTOR_RATIO_RADIUS = 200000\n\nlocal function sector_ratio(pos, side)\n    if not pos then return 0.0 end\n    local r2 = SECTOR_RATIO_RADIUS * SECTOR_RATIO_RADIUS\n    local friendly, total = 0, 0\n    for name, owner in pairs(S.base_owner) do\n        local bpos = S.base_pos[name]\n        if bpos then\n            local dx = pos.x - bpos.x\n            local dz = pos.z - bpos.z\n            if dx*dx + dz*dz <= r2 then\n                total = total + 1\n                if owner == side then friendly = friendly + 1 end\n            end\n        end\n    end\n    if total == 0 then return 0.0 end\n    return friendly / total\nend\n\nlocal function sort_targets(list)\n    table.sort(list, function(a, b) return a.rating > b.rating end)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- 1. Troop insertion (create_troop_insertion_tasks, line 1660)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Capture mechanic: when the Insert- helicopter reaches ITS designated target keysite (proximity\n-- to the registered task's target_base only), the capture roll fires IMMEDIATELY \226\128\148 EECH's\n-- response_to_waypoint_troop_capture_reached reads eff/members/losses and rolls right at the\n-- waypoint event (mb_msgs.c:2283-2305); there is no offload delay in the C.\nlocal CAPTURE_RADIUS         = 8000      -- metres; heli captures from STAND-OFF (doesn't overfly the\n                                         -- base's SAM/AAA \226\128\148 the troops air-assault the last stretch).\n                                         -- This proximity IS the TROOP_CAPTURE-waypoint-reached trigger\n                                         -- (eech mb_msgs.c:2260 response_to_waypoint_troop_capture_reached).\nlocal INSERT_PREFIX          = \"Insert\"\n\n-- Safety-net TTL for the dedup task registration of an insertion that neither arrives (opens a capture\n-- window, which clears the task on resolution) nor dies (DEAD handler clears it): after this it is\n-- force-cleared so a stuck heli can't hold the has_task_against dedup guard forever. Anchored to the\n-- board's troop_insertion unassigned-expire window (task_board.lua:78, 45 min) \226\128\148 EECH would have\n-- expired the task by then regardless (ts_updt.c UNASSIGNED expire_timer).\nlocal INSERT_TASK_TTL        = 45 * 60\n\n-- S.pending_captures (campaign_state): map group_name \226\134\146 true for insertions whose capture roll has\n-- RESOLVED (won or lost). A repelled heli loiters at its final waypoint, so without this marker it\n-- would re-roll on every 120 s tick \226\128\148 EECH's waypoint event fires exactly once per task\n-- (mb_msgs.c:2260). Lazy-init defends against a partial/older S.\nlocal function resolved_inserts()\n    S.pending_captures = S.pending_captures or {}\n    return S.pending_captures\nend\n\n-- response_to_waypoint_troop_capture_reached (mb_msgs.c:2260-2325), ported 1:1:\n-- the roll fires the moment the insertion group reaches ITS OWN designated keysite \226\128\148 the\n-- registered task's target_base, never any other base the flight line happens to pass\n-- (EECH's event carries the task's destination keysite; scanning all enemy bases let a single\n-- overflight capture non-targeted bases \226\128\148 adversarial-review CRITICAL fix).\nlocal function check_landing_helis(side, log_fn)\n    local grps = coalition.getGroups(side)\n    if not grps then return end\n    local done = resolved_inserts()\n    for _, grp in ipairs(grps) do\n        if grp and grp:isExist() then\n            local gname = grp:getName()\n            local task  = cs.get_task(gname)\n            -- Eligible insertion sorties: the campaign's own \"Insert-\" groups, OR (F4a) a PLAYER group\n            -- that bound a troop_insertion board task (task_board.assign_to_player registers it with\n            -- player=true) \226\128\148 a human-flown insertion fires the same TROOP_CAPTURE waypoint event as an\n            -- AI one (eech mb_msgs.c:2260 keys off the TASK, not the crew). Read-only on the player\n            -- unit throughout (position/size sampling only \226\128\148 guardrail).\n            local is_insert    = gname:match(\"^\" .. INSERT_PREFIX) ~= nil\n            local is_player_ti = task ~= nil and task.player == true and task.task_type == \"troop_insertion\"\n            local tbase = task and task.target_base\n            if (is_insert or is_player_ti) and not done[gname] and tbase and S.base_owner[tbase] ~= side then\n                local u = grp:getUnit(1)\n                local bpos = S.base_pos[tbase]\n                if u and u:isExist() and bpos then\n                    local hpos = u:getPosition().p\n                    local dx, dz = hpos.x - bpos.x, hpos.z - bpos.z\n                    if dx*dx + dz*dz <= CAPTURE_RADIUS * CAPTURE_RADIUS then\n                        -- Waypoint reached: sample the group's live census (INT_TYPE_MEMBER_COUNT /\n                        -- INT_TYPE_LOSSES, mb_msgs.c:2293-2295) and roll IMMEDIATELY (d vs frand1,\n                        -- :2287-2305) against the keysite's CURRENT efficiency \226\128\148 a repaired base\n                        -- repels. All capture side-effects live in keysite.do_capture.\n                        local members = TROOP_MEMBER_FALLBACK\n                        local losses  = 0\n                        local ok_sz, sz = pcall(function() return grp:getSize() end)\n                        local cur = ok_sz and tonumber(sz) or nil\n                        if cur then\n                            members = math.max(1, cur)\n                            local ok_is, isz = pcall(function() return grp:getInitialSize() end)\n                            local init = ok_is and tonumber(isz) or nil\n                            if init then losses = math.max(0, init - members) end\n                        end\n                        done[gname] = true\n                        cs.dbg(\"troop\", \"%s heli %s reached capture waypoint of %s: members=%d losses=%d \226\128\148 rolling\",\n                            cs.SIDE_NAME[side], gname, tbase, members, losses)\n                        if keysite.capture_roll(tbase, members, losses) then\n                            keysite.do_capture(tbase, side, log_fn)\n                            cs.stat_task_result(side, \"success\")   -- Item 3: capture won (eech task.c objective-message)\n                            log_fn(string.format(\"T.I. CAPTURE: %s \226\134\146 %s (members=%d losses=%d)\",\n                                tbase, cs.SIDE_NAME[side], members, losses))\n                            cs.dbg(\"troop\", \"CAPTURE ROLL WON: %s -> %s (group=%s)\", tbase, cs.SIDE_NAME[side], gname)\n                        else\n                            cs.stat_task_result(side, \"failure\")   -- Item 3: capture repelled (defence held)\n                            log_fn(string.format(\"T.I. repelled at %s (defence held)\", tbase))\n                            cs.dbg(\"troop\", \"CAPTURE ROLL LOST: %s repelled (group=%s)\", tbase, gname)\n                        end\n                        -- The insertion is spent either way: free its dedup registration and launch\n                        -- slot (the heli has no Land waypoint \226\128\148 only death or this path frees them).\n                        cs.clear_task(gname)\n                        keysite.release_slot(gname)\n                    end\n                end\n            end\n        end\n    end\nend\n\n-- \226\148\128\226\148\128 build_troop_insert(side, base_name, target_name, target_pos, log_fn) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- BUILDER (task-board contract): spawns the insertion helicopter FROM base_name toward the target\n-- keysite. The board has already consumed 1 \"heli\" from base_name's ledger (refunds on nil).\n-- Returns the group on success, nil on failure.\n-- `members` (WAVE 3 Item 3b): number of assault helis in the insertion group. EECH's assignment gate\n-- suitable_group_task_specific_checks (assign.c:366-390) refuses a troop-insertion group of < 2 members\n-- against an ENEMY AIRBASE keysite (objective_type == KEYSITE_AIRBASE && MEMBER_COUNT < 2 && objective\n-- side != group side \226\134\146 FALSE). The port stages assault helis, so an airbase capture must field a 2-ship;\n-- FARP captures and same-side (defender reinforcement) inserts stay 1-ship. Defaults to 1.\nlocal function build_troop_insert(side, base_name, target_name, target_pos, log_fn, members)\n    members = math.max(1, members or 1)\n    local home_ab = base_name\n\n    local cfg    = AC_HELI[side]\n    -- Spawn from a real airbase if the base has one, else GROUND-START from its coordinates \226\128\148 a\n    -- synthetic zone-FARP has no Airbase object (same fix as heli_war.build_attack_heli). Without this\n    -- the board could never assign a troop insertion staged from a padless FARP \226\134\146 no captures.\n    local ab     = Airbase.getByName(home_ab)\n    local ab_pos, ab_id\n    if ab then\n        ab_pos, ab_id = ab:getPosition().p, ab:getID()\n    else\n        local bp = cs.S.base_pos and cs.S.base_pos[home_ab]\n        if not bp then\n            cs.dbg(\"troop\", \"%s build_troop_insert ABORT: base %s unknown (no Airbase, no base_pos)\",\n                cs.SIDE_NAME[side], tostring(home_ab))\n            return nil   -- unknown base \226\134\146 board refunds the heli ledger\n        end\n        local gy = 0\n        pcall(function() gy = land.getHeight({ x = bp.x, y = bp.z }) or 0 end)\n        ab_pos = { x = bp.x, y = gy, z = bp.z }\n    end\n    local bx, by = cs.wp_xy(ab_pos)\n    local tx, ty = cs.wp_xy(target_pos)\n    local sid    = cs.next_id()\n    local gname  = string.format(\"Insert-%s-%d-%d\", target_name:sub(1,8), side, sid)\n\n    -- Depart via TakeOff-from-parking at a real airbase, else a ground start at the FARP coordinates.\n    local depart\n    if ab_id then\n        depart = { type=\"TakeOff\", action=\"From Parking Area\", airdromeId=ab_id,\n                   alt=ab_pos.y, alt_type=\"BARO\", speed=0, ETA=0, ETA_locked=true,\n                   x=bx, y=by, name=\"Depart\", formation_template=\"\" }\n    else\n        depart = { type=\"TakeOffGroundHot\", action=\"From Ground Area Hot\",\n                   alt=ab_pos.y, alt_type=\"BARO\", speed=0, ETA=0, ETA_locked=true,\n                   x=bx, y=by, name=\"Depart\", formation_template=\"\" }\n    end\n    -- One or more assault helis (Item 3b: airbase captures require a 2-ship, assign.c:386).\n    local units = {}\n    for i = 1, members do\n        units[i] = {\n            name = gname .. \"-\" .. i, type = cfg.heli_type, skill = \"Good\",\n            x = ab_pos.x + (i - 1) * 30, y = ab_pos.z, alt = ab_pos.y, alt_type = \"BARO\",\n            speed = 0, heading = 0,\n            payload = { fuel = 2200, flare = 60, chaff = 60, gun = 100 },\n        }\n    end\n    local gspec = {\n        name   = gname, task = \"Transport\", hidden = false,\n        units  = units,\n        route = { points = croute.expand({\n            depart,\n            { type=\"Turning Point\", action=\"Turning Point\",\n              alt=150, alt_type=\"BARO\", speed=100,   -- fast + low: cross to the target quickly, under SAM\n              ETA=0, ETA_locked=false, x=tx, y=ty, name=\"Insert\", formation_template=\"\" },\n        }, side, { alt=150, alt_type=\"BARO\", speed=100, name=\"Nav\" }) },\n    }\n    if ab_id then gspec.airdromeId = ab_id end\n    local grp = coalition.addGroup(cfg.country, Group.Category.HELICOPTER, gspec)\n\n    if grp then\n        -- Register so the T.I. dedup (has_task_against \"troop_insertion\") sees an in-progress\n        -- insertion against this base \226\128\148 stops a new heli being tasked every 2-min tick while the\n        -- base stays neutralised (drained the transport pool). Cleared after the capture window.\n        cs.register_task(gname, { task_type=\"troop_insertion\", side=side,\n            target_base=target_name, target_pos=target_pos, born_time=timer.getTime() })\n        -- Capture on ARRIVAL: NO capture window is opened here at dispatch. check_landing_helis opens it\n        -- when the heli physically reaches the keysite (eech captures at the TROOP_CAPTURE waypoint,\n        -- mb_msgs.c:2260-2325). A heli shot down en route never arrives \226\134\146 no window \226\134\146 no capture attempt.\n        -- Safety-net TTL: the insertion heli has NO Land waypoint (it stages at the target and loiters),\n        -- so nothing frees its dedup registration + landing slot except (a) the capture window resolving\n        -- (check_landing_helis) or (b) death (DEAD handler + regen slot release). If it does NEITHER \226\128\148 a stuck\n        -- heli that never reaches CAPTURE_RADIUS and never dies \226\128\148 this force-clears both after\n        -- INSERT_TASK_TTL so it can't hold the has_task_against dedup guard / launch slot forever.\n        -- Idempotent: if the window already resolved or the heli died, both calls no-op.\n        local ttl_gen = _DMT_GEN\n        timer.scheduleFunction(function()\n            if _DMT_GEN == ttl_gen and cs.get_task(gname) then\n                cs.dbg(\"troop\", \"T.I. safety-net TTL reached for %s (never arrived/died) -> clearing task+slot\", gname)\n                cs.clear_task(gname)\n                keysite.release_slot(gname)\n            end\n            return nil\n        end, nil, timer.getTime() + INSERT_TASK_TTL)\n        -- Attack-helicopter escort shepherds the insertion \226\128\148 but only when the route is dangerous\n        -- enough (assign.c:598-627: escort iff route difficulty >= troop_insertion threshold = 3).\n        -- Replaces the old unconditional escort. Difficulty logged inside cs.escort_count.\n        if cs.escort_count(\"troop_insertion\", side, ab_pos, target_pos, log_fn) > 0 then\n            pcall(function() require(\"heli_war\").spawn_escort(side, target_pos, log_fn) end)\n        end\n        log_fn(string.format(\"%s T.I. #%d \226\134\146 %s from %s (%d-ship, capture on arrival)\", cs.SIDE_NAME[side], sid, target_name, home_ab, members))\n        cs.dbg(\"troop\", \"%s T.I. #%d DISPATCHED from %s -> %s (capture window opens on arrival within %.0fm)\",\n            cs.SIDE_NAME[side], sid, home_ab, target_name, CAPTURE_RADIUS)\n        return grp\n    end\n    cs.dbg(\"troop\", \"%s T.I. #%d SPAWN FAILED from %s -> %s\", cs.SIDE_NAME[side], sid, home_ab, target_name)\n    return nil   -- spawn failed; board refunds the heli ledger\nend\n\n-- Enqueue a troop-insertion task on the board (role heli). immediate for the reaction chain.\nlocal function create_troop_insert_task(side, target_name, target_pos, log_fn, immediate)\n    -- Item 3b (assign.c:386): an OFFENSIVE capture of an enemy AIRBASE keysite needs a >= 2-member\n    -- assault group; FARP captures and same-side (defender reinforcement) inserts stay 1-ship. The board\n    -- consumes `count` of the transport role, so count == members keeps the ledger draw matched to the\n    -- ship count the builder spawns.\n    local is_airbase = (cs.S.base_kind and cs.S.base_kind[target_name]) == \"airbase\"\n    local offensive  = cs.S.base_owner and cs.S.base_owner[target_name] ~= side   -- objective side != group side\n    local members    = (is_airbase and offensive) and 2 or 1\n    cs.dbg(\"troop\", \"%s create_troop_insert_task: vs %s (immediate=%s, %d-ship \226\128\148 airbase=%s offensive=%s, assign.c:386)\",\n        cs.SIDE_NAME[side], target_name, tostring(immediate), members, tostring(is_airbase), tostring(offensive))\n    board.create_task({\n        type = \"troop_insertion\", side = side, count = members, log_fn = log_fn, immediate = immediate,\n        target = { base = target_name, pos = target_pos, objective = { kind = \"keysite\", base = target_name } },\n        builder = function(base_name)\n            return build_troop_insert(side, base_name, target_name, target_pos, log_fn, members)\n        end,\n    })\n    return true\nend\n\n-- \226\148\128\226\148\128 Defender BACKUP troop insertion (eech highlevl.c:1876-1897) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- In create_troop_insertion_tasks, right after tasking the ATTACKER's capture of a weak enemy keysite,\n-- EECH also tasks the keysite's OWNER (the defender) to reinforce it \226\128\148 but only when:\n--   (1) the keysite is enemy-owned relative to the attacker  (keysite_side != this_side, :1879)\n--       \226\128\148 always true here: the periodic scan only rates enemy keysites;\n--   (2) the defender has no existing troop_insertion / INSERT_CAPTURE / INSERT_DEFEND task there\n--       (:1880-1882) \226\128\148 the port's single \"troop_insertion\" type covers all three (one insertion\n--       pipeline), so ONE has_task_against dedup check;\n--   (3) the defender holds fewer than 2 troop patrols at the keysite (:1883). The port caps patrols\n--       at 1 per keysite (spawn_patrol/has_patrol), so this count is 0 or 1 \226\134\146 always < 2, never\n--       blocking; kept for fidelity to EECH's intent (a base already held by 2 patrols needs no backup).\n-- There is NO efficiency gate on the backup \226\128\148 it reinforces the SAME weak keysite the attacker targets.\nlocal function defender_patrol_count(base_name)\n    if S.patrol_groups and S.patrol_groups[base_name] then\n        local grp = Group.getByName(S.patrol_groups[base_name])\n        if grp and grp:isExist() then return 1 end\n    end\n    return 0\nend\n\nlocal function try_defender_backup(attacker, tname, tpos, log_fn)\n    local defender = S.base_owner[tname]\n    if defender == nil or defender == attacker then return end              -- (1) keysite_side != this_side\n    if cs.has_task_against(\"troop_insertion\", tname, defender) then return end  -- (2) dedup (all 3 EECH types)\n    if defender_patrol_count(tname) >= 2 then return end                    -- (3) < 2 patrols\n    cs.dbg(\"troop\", \"backup DEFENDER T.I.: %s reinforces its own weak keysite %s (patrols=%d)\",\n        cs.SIDE_NAME[defender], tname, defender_patrol_count(tname))\n    create_troop_insert_task(defender, tname, tpos, log_fn, true)\n    log_fn(string.format(\"%s backup T.I. \226\134\146 %s (defend own keysite under capture)\", cs.SIDE_NAME[defender], tname))\nend\n\n-- run_troop_insertion(side, log_fn, target_name):\n--   target_name given  \226\134\146 insert directly against THAT keysite (reaction chain, reaction.c:413).\n--   target_name nil    \226\134\146 periodic scan, pick top targets (create_troop_insertion_tasks).\nlocal function run_troop_insertion(side, log_fn, target_name)\n    if target_name then\n        local tpos = S.base_pos[target_name]\n        local dup  = cs.has_task_against(\"troop_insertion\", target_name, side)\n        if tpos and not dup then\n            cs.dbg(\"troop\", \"%s run_troop_insertion: DIRECTED (reaction) vs %s\", cs.SIDE_NAME[side], target_name)\n            create_troop_insert_task(side, target_name, tpos, log_fn, true)  -- reaction chain: immediate\n        else\n            cs.dbg(\"troop\", \"%s run_troop_insertion DIRECTED SKIP vs %s: tpos=%s dup=%s\",\n                cs.SIDE_NAME[side], target_name, tostring(tpos ~= nil), tostring(dup))\n        end\n        return\n    end\n    local enemy = cs.ENEMY[side]\n    -- No survival gate: EECH create_troop_insertion_tasks (highlevl.c:1780+) generates offensive\n    -- captures regardless of force strength \226\128\148 force_attitude/strength is read by no AI code. The former\n    -- STRENGTH_SURVIVAL skip was invented (Cluster E); the endgame is resolved by the strike/capture\n    -- pressure realignment (Clusters A/C/D), not a posture cutoff.\n    local rated = {}\n    local count = 0\n\n    for tname, towner in pairs(S.base_owner) do\n        if count >= MAX_HIGHLEVEL_TARGET_CHECKS then break end\n        if towner == enemy then\n            local tpos = S.base_pos[tname]\n            if tpos then\n                -- FLOAT_TYPE_EFFICIENCY proxy: composite health+ammo+fuel metric\n                -- (updated every 60 s by keysite_repair.lua; falls back to health alone)\n                local efficiency = (S.base_efficiency and S.base_efficiency[tname])\n                                   or S.base_health[tname] or 1.0\n\n                -- Filter: only troop_insertion_target keysites (proxy: health < MINIMUM_EFFICIENCY)\n                if efficiency < MINIMUM_EFFICIENCY then\n                    -- FOW check (line 1819): fow >= 0.20 * maximum\n                    local fow = fow_m.get(tname, side)\n                    if fow < FOW_THRESHOLD_TI then\n                        -- EECH highlevl.c:1819: a fogged capture target spawns a RECON to reveal it\n                        -- (was previously an empty else \226\134\146 neutralised-but-fogged bases were skipped\n                        -- forever and never captured). Recon raises FOW so a later T.I. tick proceeds.\n                        if not cs.has_task_against(\"recon\", tname, side) then\n                            local ok_r, recon = pcall(require, \"recon\")\n                            if ok_r and recon and recon.spawn_recon then\n                                pcall(recon.spawn_recon, side, tpos, \"TIscout-\" .. tname:sub(1, 8),\n                                      log_fn, { kind = \"keysite\", base = tname })\n                                log_fn(string.format(\n                                    \"T.I.: %s neutralised (%.0f%%) but FOGGED (fow=%.2f<%.2f) \226\128\148 recon dispatched\",\n                                    tname, efficiency * 100, fow, FOW_THRESHOLD_TI))\n                            end\n                        end\n                    end\n                    if fow >= FOW_THRESHOLD_TI then\n                        log_fn(string.format(\"T.I.: %s capturable (%.0f%%, fow=%.2f) \226\128\148 tasking insertion\",\n                            tname, efficiency * 100, fow))\n                        -- Orientation: AIR_DEFENCE[side] = the AA that SIDE faces (built from\n                        -- ENEMY[side]'s AA) \226\128\148 the attacker reads its OWN side's layer. get(enemy,...)\n                        -- returned the attacker's own AA, inverting the (1-airdef) term.\n                        local airdef = imap_m.get(side, imap_m.AIR_DEFENCE, tpos)\n                        local bdist  = imap_m.get(side, imap_m.BASE_DISTANCE, tpos)\n                        local sratio = sector_ratio(tpos, side)\n\n                        -- EECH formula: (1-airdef)*1 + base_dist*3 + (1-efficiency)*3 + sector_ratio*2\n                        -- Commented-out importance term not included (// rating += ...)\n                        -- max=9.0\n                        local rating = (1.0 - airdef) * 1.0\n                                     + bdist * 3.0\n                                     + (1.0 - efficiency) * 3.0\n                                     + sratio * 2.0\n\n                        if rating > 0.0 then\n                            rated[#rated + 1] = { name = tname, pos = tpos, rating = rating }\n                            count = count + 1\n                        end\n                    end\n                end\n            end\n        end\n    end\n\n    if #rated == 0 then\n        cs.dbg(\"troop\", \"%s run_troop_insertion: 0 enemy keysites below minimum-efficiency, no T.I. tasked\", cs.SIDE_NAME[side])\n        return\n    end\n    sort_targets(rated)\n\n    local max_r  = rated[1].rating\n    local n      = math.min(#rated, CREATE_TROOP_INSERTION_TASK_COUNT)\n    local n_tasked, n_dup_skip = 0, 0\n    for i = 1, n do\n        local entry = rated[i]\n        -- Dedup (highlevl.c:1853): skip if a T.I. task already exists (queued or flying) here.\n        if entry.rating / max_r >= MIN_TASK_CREATION_RATIO then\n            if not cs.has_task_against(\"troop_insertion\", entry.name, side) then\n                -- immediate=true: assign + spawn THIS tick so the active-task registration (dedup) lands\n                -- before the next 2-min tick \226\128\148 otherwise a new insertion is tasked every tick while the\n                -- board's 3-min assignment lag leaves has_task_against false (transport-pool drain).\n                create_troop_insert_task(side, entry.name, entry.pos, log_fn, true)\n                n_tasked = n_tasked + 1\n                -- eech highlevl.c:1876-1897: after the attacker's capture task, task the defender to\n                -- reinforce its own weak keysite (gated conditions in try_defender_backup).\n                try_defender_backup(side, entry.name, entry.pos, log_fn)\n            else\n                n_dup_skip = n_dup_skip + 1\n            end\n        end\n    end\n    cs.dbg(\"troop\", \"%s run_troop_insertion funnel: %d capturable rated -> top %d checked -> %d tasked, %d already-dup\",\n        cs.SIDE_NAME[side], #rated, n, n_tasked, n_dup_skip)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- 2. Infantry patrol (create_troop_patrol_tasks, line 2735)\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- mirrors: for each own FARP/military/airbase keysite:\n--   if no existing patrol group (groups_counter < groups_limit=1):\n--     create_faction_members(... INFANTRY_PATROL, count=4, ...)\n--     create_patrol_task(group, keysite, side)\n--\n-- DCS proxy: spawn 4-unit infantry group at PATROL_BASE_RADIUS from base.\n-- Patrol task \226\134\146 Guard area with radius 500m.\n-- Track S.patrol_groups[base_name] so we don't double-spawn.\n\nlocal PATROL_UNIT_COUNT  = 4     -- EECH line 2812: count=4\nlocal PATROL_GUARD_RADIUS = 500  -- metres; proxy for patrol waypoint orbit\n\nlocal function has_patrol(base_name, side)\n    if not S.patrol_groups then return false end\n    local pg = S.patrol_groups[base_name]\n    if not pg then return false end\n    local grp = Group.getByName(pg)\n    return grp and grp:isExist()\nend\n\nlocal function spawn_patrol(base_name, side, log_fn)\n    if has_patrol(base_name, side) then return end\n    local cfg   = INFANTRY_TYPE[side]\n    if not cfg then return end\n    local bpos  = S.base_pos[base_name]\n    if not bpos then return end\n\n    -- Angle: keysite index % 6 * PI2/6 (line 2803: get_local_entity_index % 6)\n    -- DCS proxy: use a fixed offset (NE of base)\n    local angle = math.random() * math.pi * 2.0\n    local r     = PATROL_BASE_RADIUS + math.random() * PATROL_RADIUS_JITTER\n\n    -- Snap the patrol ring point off water (a 300 m ring at a coastal FARP/base can be wet);\n    -- fallback = the base centre `bpos` (always land). Per-unit offsets stay relative to the snap.\n    local sp = cs.snap_land(bpos.x + math.cos(angle) * r, bpos.z + math.sin(angle) * r, bpos.x, bpos.z)\n    local px = sp.x\n    local pz = sp.z\n    local py = land.getHeight({ x = px, y = pz })   -- land.getHeight takes a single {x,y} vec2\n\n    local id    = cs.next_id()\n    local gname = string.format(\"Patrol-%s-%d\", base_name:sub(1,10), id)\n\n    local units = {}\n    for i = 1, PATROL_UNIT_COUNT do\n        units[i] = {\n            name     = gname .. \"-\" .. i,\n            type     = cfg.unit,\n            skill    = \"Good\",\n            x        = px + (i - 1) * 5.0,\n            y        = pz,\n            alt      = py,\n            alt_type = \"BARO\",\n            speed    = 0,\n            heading  = 0,\n            playerCanDrive = false,\n        }\n    end\n\n    local grp = coalition.addGroup(cfg.country, Group.Category.GROUND, {\n        name   = gname,\n        task   = \"Ground Nothing\",\n        hidden = false,\n        units  = units,\n        route  = { points = {\n            {\n                type = \"Turning Point\", action = \"Turning Point\",\n                x = px, y = pz, speed = 1.4, ETA = 0, ETA_locked = false,\n                formation_template = \"\",\n                task = {\n                    id = \"ComboTask\",\n                    params = { tasks = { [1] = {\n                        number = 1, auto = true, id = \"Guard\", enabled = true,\n                        params = { zone = { x = px, y = pz }, radius = PATROL_GUARD_RADIUS },\n                    }}},\n                },\n            },\n        }},\n    })\n\n    if grp then\n        S.patrol_groups = S.patrol_groups or {}\n        S.patrol_groups[base_name] = gname\n        log_fn(string.format(\"%s patrol spawned at %s (#%d, %d units)\",\n            cs.SIDE_NAME[side], base_name, id, PATROL_UNIT_COUNT))\n    end\nend\n\nlocal function run_troop_patrol(side, log_fn)\n    -- mirrors: for each own FARP/military/airbase keysite\n    -- DCS proxy: all friendly bases are treated as patrol-eligible\n    local n_checked, n_spawned, n_already, n_error = 0, 0, 0, 0\n    for name, owner in pairs(S.base_owner) do\n        if owner == side then\n            local h = S.base_health[name] or 1.0\n            if h >= cs.HEALTH_NEUTRALISED then   -- USABLE iff eff >= min (keysite.c:827-830, inclusive)\n                n_checked = n_checked + 1\n                local was_patrolled = has_patrol(name, side)\n                local ok, err = pcall(spawn_patrol, name, side, log_fn)\n                if not ok then\n                    log_fn(string.format(\"patrol spawn error at %s: %s\", name, tostring(err)))\n                    n_error = n_error + 1\n                elseif was_patrolled then\n                    n_already = n_already + 1\n                else\n                    n_spawned = n_spawned + 1\n                end\n            end\n        end\n    end\n    cs.dbg(\"troop\", \"%s patrol tick: %d bases checked -> %d spawned, %d already patrolled, %d errors\",\n        cs.SIDE_NAME[side], n_checked, n_spawned, n_already, n_error)\nend\n\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n-- Schedulers\n-- \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\n\n-- \226\148\128\226\148\128 Single-shot spawn (called by reaction.lua for follow-on T.I. tasks) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Mirrors create_troop_insertion_task called from create_reaction_to_recon_task_completed.\nfunction M.run_troop_insertion(side, log_fn, target_name)\n    log_fn = log_fn or function() end\n    cs.dbg(\"troop\", \"%s run_troop_insertion single-shot invoked (target=%s)\", cs.SIDE_NAME[side], tostring(target_name))\n    local ok, err = pcall(run_troop_insertion, side, log_fn, target_name)\n    if not ok then log_fn(\"run_troop_insertion error: \" .. tostring(err)) end\nend\n\nfunction M.schedule_troop_insertion(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    local offset = initial_offset or OFFSET_TI\n    cs.dbg(\"troop\", \"%s T.I. scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], offset, PERIOD_TI)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        cs.dbg(\"troop\", \"%s T.I. FIRE\", cs.SIDE_NAME[side])\n        local ok, err = pcall(function()\n            -- INFRASTRUCTURE: arrival check (waypoint-reached \226\134\146 capture roll) keeps running after\n            -- campaign-over \226\128\148 in-flight troops still capture on arrival (the world runs on, per EECH\n            -- fc_msgs.c:163 which halts only the win-check, not the sim).\n            check_landing_helis(side, log_fn)\n            -- Item 6 (LITERAL post-victory semantics): T.I. generation keeps running after the win is\n            -- declared \226\128\148 EECH fc_msgs.c:163 gates ONLY the win-check re-award, never the generators.\n            run_troop_insertion(side, log_fn)\n        end)\n        if not ok then log_fn(\"T.I. error: \" .. tostring(err)) end\n        return t + PERIOD_TI\n    end, nil, timer.getTime() + offset)\nend\n\nfunction M.schedule_patrol(side, initial_offset, log_fn)\n    log_fn = log_fn or function() end\n    local my_gen = _DMT_GEN\n    local offset = initial_offset or OFFSET_PATROL\n    cs.dbg(\"troop\", \"%s patrol scheduler REGISTERED offset=%.0fs period=%.0fs\", cs.SIDE_NAME[side], offset, PERIOD_PATROL)\n    timer.scheduleFunction(function(_, t)\n        if _DMT_GEN ~= my_gen then return nil end    -- re-injection guard: cancel superseded closure\n        -- Item 6: patrol generation keeps running post-victory (EECH fc_msgs.c:163 gates only the win re-award).\n        local ok, err = pcall(run_troop_patrol, side, log_fn)\n        if not ok then log_fn(\"patrol error: \" .. tostring(err)) end\n        return t + PERIOD_PATROL\n    end, nil, timer.getTime() + offset)\nend\n\nreturn M\n"
__modules["win_condition"] = "-- win_condition.lua\n-- Inspired by:\n--   aphavoc/source/entity/special/force/fc_msgs.c  response_to_check_campaign_objectives\n--                                                   (the LIVE, shipped win check \226\128\148 lines 144-311)\n--   aphavoc/source/ai/highlevl/setup.c             create_force_campaign_objectives (5 per side)\n--   aphavoc/source/entity/mobile/aircraft/helicop/hc_dstry.c  helicopter-kill win trigger\n--   aphavoc/source/entity/special/force/force.c    add_mobile_to_force_losses_stats (kill ledger)\n--\n-- Implements the THREE real end conditions of shipped EECH (spec 02 F26-F28 / spec 01 F13).\n-- The Razorworks campaign_criteria evaluator in fc_updt.c is DEAD CODE (its whole body is\n-- commented out); the community build ends a campaign purely event-driven, when a keysite is\n-- captured/destroyed or a helicopter is killed, via response_to_check_campaign_objectives. A side\n-- wins if ANY of:\n--   (a) OBJECTIVES  \226\128\148 it OWNS every keysite in its campaign-objective set (troop-insertion\n--                     targets must be owned; eech fc_msgs.c:180-211). See keysite.designate_objectives.\n--   (b) NO USABLE AIRBASE \226\128\148 the enemy has no alive+in-use keysite with air_force_capacity != NONE\n--                     (eech fc_msgs.c:222-249). In the port every keysite is an airbase, so this is\n--                     \"enemy owns no keysite at efficiency >= minimum\" (usable state, KEYSITE-F11).\n--   (c) NO GUNSHIPS \226\128\148 the enemy has no flyable player-controllable combat helicopter left\n--                     (eech fc_msgs.c:255-295).\n-- The invented 4-hour time limit and balance-of-power/captured-sectors criteria of the old port\n-- (which modelled the DEAD fc_updt.c system) are REMOVED \226\128\148 EECH has no time-based end.\n\nlocal cs      = require(\"campaign_state\")\nlocal keysite = require(\"keysite\")\nlocal S       = cs.S\nlocal M       = {}\n\nlocal function finish(winner, reason, log_fn)\n    S.game_over = true\n    S.winner    = winner\n    local b_own, r_own = 0, 0\n    for _, owner in pairs(S.base_owner) do\n        if owner == coalition.side.BLUE then b_own = b_own + 1\n        elseif owner == coalition.side.RED then r_own = r_own + 1 end\n    end\n    local msg = string.format(\n        \"\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144 CAMPAIGN OVER \226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\226\149\144\\n%s VICTORY \226\128\148 %s\\nBases: BLUE %d  RED %d   |   Strength: BLUE %d%%  RED %d%%\",\n        cs.SIDE_NAME[winner] or \"?\", reason, b_own, r_own,\n        S.strength[coalition.side.BLUE], S.strength[coalition.side.RED])\n    log_fn(msg)\n    trigger.action.outText(msg, 120)\n    cs.dbg(\"win\", \"GAME OVER: %s wins (%s) \226\128\148 bases BLUE=%d RED=%d, strength BLUE=%d RED=%d\",\n        cs.SIDE_NAME[winner] or \"?\", reason, b_own, r_own, S.strength[coalition.side.BLUE], S.strength[coalition.side.RED])\n\n    -- Persistence (WAVE 2): checkpoint the decided campaign so a restart restores S.game_over/winner\n    -- (a finished campaign stays finished). No-op unless persistence enabled; pcall-guarded.\n    local ok_p, persist = pcall(require, \"persist\")\n    if ok_p and persist and persist.save then pcall(persist.save, log_fn) end\n\n    -- Campaign medal (PILOT-F14, eech play_md.c:1062 award_campaign_medal; campaign.c:1128 at session\n    -- complete): every pilot who flew this campaign receives the campaign medal on the win declaration.\n    -- Deferred + pcall-guarded (pilots requires task_board/supply/frontline \226\128\148 no cycle with win_condition).\n    local ok_pc, pilots = pcall(require, \"pilots\")\n    if ok_pc and pilots and pilots.award_campaign_medals then\n        pcall(pilots.award_campaign_medals, winner, log_fn)\n    end\nend\n\n-- \226\148\128\226\148\128 (a) Objectives held \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- eech fc_msgs.c:180-211: every objective keysite of the force must be OWNED by its side\n-- (all port keysites are troop_insertion_targets \226\134\146 \"must own\", not \"must destroy\").\nlocal function holds_all_objectives(side)\n    local objs = S.objectives and S.objectives[side]\n    if not objs or #objs == 0 then return false end\n    for _, bname in ipairs(objs) do\n        if S.base_owner[bname] ~= side then return false end\n    end\n    return true\nend\n\n-- \226\148\128\226\148\128 (b) Enemy has a usable airbase \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- eech fc_msgs.c:222-249: any enemy keysite that is alive+in-use with air_force_capacity != NONE.\n-- Port: any enemy-owned keysite at efficiency >= minimum (usable state, KEYSITE-F11).\nlocal function has_usable_airbase(side)\n    for bname, owner in pairs(S.base_owner) do\n        -- Item 1: a keysite must be IN_USE (active) to count, matching fc_msgs.c:234 (ALIVE && IN_USE).\n        -- A dormant FARP does not keep a side \"alive\" for the win check.\n        if owner == side and cs.base_is_active(bname) and keysite.efficiency(bname) >= cs.MINIMUM_EFFICIENCY then\n            return true\n        end\n    end\n    return false\nend\n\n-- \226\148\128\226\148\128 (c) Enemy has a flyable combat helicopter \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- eech fc_msgs.c:255-295 walks the enemy's live air registry for a surviving player-controllable\n-- combat helicopter (view_category == VIEW_CATEGORY_COMBAT_HELICOPTERS).\n-- Port proxy: EECH's combat helis are seeded in the air registry at OOB; in the port a side's\n-- gunship capability lives in its reserve pool and regen queue (helis are spawned on demand), so a\n-- census of LIVE units alone would falsely fire at campaign start. A side therefore still \"has\"\n-- flyable combat helicopters while it can field one \226\128\148 i.e. any live attack helicopter, OR any\n-- \"heli\" reserve, OR any queued heli regen. Only when it can neither fly nor regenerate one is it\n-- out of gunships. Combat helicopter == DCS attribute \"Attack helicopters\".\nlocal function live_combat_helis(side)\n    local ok, grps = pcall(coalition.getGroups, side, Group.Category.HELICOPTER)\n    if not ok or not grps then return 0 end\n    local n = 0\n    for _, grp in ipairs(grps) do\n        if grp and grp.isExist and grp:isExist() then\n            local units = grp:getUnits()\n            if units then\n                for _, u in ipairs(units) do\n                    if u and u:isExist() then\n                        local d = u:getDesc()\n                        local a = d and d.attributes\n                        if a and a[\"Attack helicopters\"] then n = n + 1; break end\n                    end\n                end\n            end\n        end\n        if n > 0 then break end\n    end\n    return n\nend\n\nlocal function has_combat_heli_capability(side)\n    if live_combat_helis(side) > 0 then return true end\n    -- reserve pool (supply) \226\128\148 a side with heli reserves can still field gunships\n    local ok_s, supply = pcall(require, \"supply\")\n    if ok_s and supply and supply.reserve_side(side, \"heli\") > 0 then return true end\n    -- queued heli regen (a shot-down gunship waiting to respawn)\n    local q = S.regen_queue and S.regen_queue[side] and S.regen_queue[side].heli\n    if q and #q > 0 then return true end\n    return false\nend\n\n-- \226\148\128\226\148\128 Win check \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Event-driven (called from the kill handler, capture side-effect, and the admin poll), mirroring\n-- EECH's ENTITY_MESSAGE_CHECK_CAMPAIGN_OBJECTIVES fan-out to both forces (fc_msgs.c F29).\nfunction M.check_win(log_fn)\n    log_fn = log_fn or function() end\n    if S.game_over then return end\n\n    cs.recalc_strength()   -- kept for the debrief strength readout only (not a win criterion)\n\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED }) do\n        local enemy = cs.ENEMY[side]\n\n        -- Criterion telemetry (evaluated before the gates below fire so the counts are always visible,\n        -- even on the check that doesn't end the campaign).\n        local objs = S.objectives and S.objectives[side]\n        local held = 0\n        if objs then\n            for _, bname in ipairs(objs) do if S.base_owner[bname] == side then held = held + 1 end end\n        end\n        local enemy_usable = 0\n        for bname, owner in pairs(S.base_owner) do\n            if owner == enemy and cs.base_is_active(bname) and keysite.efficiency(bname) >= cs.MINIMUM_EFFICIENCY then enemy_usable = enemy_usable + 1 end\n        end\n        cs.dbg(\"win\", \"%s check: objectives %d/%d held, enemy(%s) usable-airbases=%d, enemy live-combat-helis=%d\",\n            cs.SIDE_NAME[side], held, objs and #objs or 0, cs.SIDE_NAME[enemy], enemy_usable, live_combat_helis(enemy))\n\n        -- (a) OBJECTIVES: this side owns all its objective keysites\n        if holds_all_objectives(side) then\n            finish(side, \"all objective keysites captured\", log_fn)\n            return\n        end\n\n        -- (b) NO USABLE AIRBASE on the enemy side\n        if not has_usable_airbase(enemy) then\n            finish(side, cs.SIDE_NAME[enemy] .. \" has no usable airbase\", log_fn)\n            return\n        end\n\n        -- (c) NO FLYABLE COMBAT HELICOPTERS on the enemy side\n        if not has_combat_heli_capability(enemy) then\n            finish(side, cs.SIDE_NAME[enemy] .. \" combat helicopters eliminated\", log_fn)\n            return\n        end\n\n        -- EECH has EXACTLY THREE end conditions (fc_msgs.c:180-295 \226\134\146 CAMPAIGN_COMPLETED_OBJECTIVES /\n        -- no alive+in-use air-capable keysite / no player-controllable combat helicopter). There is no\n        -- fourth. The former criterion (d) \"military collapse\" (enemy <=25% of bases AND strength <\n        -- STRENGTH_SURVIVAL) was invented \226\128\148 it modelled a strength/posture \"rout\" EECH does not have\n        -- (force_attitude is parsed but read by NO AI code; verified E:\\eech_source_code parsgen.c:1474\n        -- + fc_int.c:215, zero consumers). Removed in Cluster E. Stalemate resolution is now the job of\n        -- the realigned strike/capture pressure (Clusters A/C/D), not a synthetic strength cutoff.\n    end\nend\n\n-- \226\148\128\226\148\128 Kill event handler \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- A helicopter kill is one of EECH's three live win-check triggers (hc_dstry.c:631-643), so we\n-- re-check the win conditions on every kill. Keysite structural attrition is NOT driven from here \226\128\148\n-- EECH keysite_strength changes only when the keysite's own buildings die (Cluster G, see below).\nfunction M.make_kill_handler(log_fn)\n    log_fn = log_fn or function() end\n    local handler = {}\n\n    function handler:onEvent(event)\n        if event.id ~= world.event.S_EVENT_KILL then return end\n        local tgt = event.target\n        if not tgt then return end\n\n        -- Item 2 stats: credit the kill to the killer's side and the loss to the victim's side, bucketed\n        -- by the victim's category (eech force.c:307-361 add_mobile_to_force_kills_stats /_losses_stats:\n        -- kill \226\134\146 killer force indexed by victim category; loss \226\134\146 victim force). pcall-guarded.\n        local killer_side, victim_side\n        pcall(function() if event.initiator and event.initiator.getCoalition then killer_side = event.initiator:getCoalition() end end)\n        pcall(function() if tgt.getCoalition then victim_side = tgt:getCoalition() end end)\n        cs.stat_kill(killer_side, victim_side, cs.unit_category(tgt))\n\n        -- Re-evaluate win conditions on every kill (helicopter-exhaustion + base-count triggers,\n        -- hc_dstry.c:631-643). Keysite structural attrition is NOT driven from here anymore: EECH\n        -- keysite_strength changes only when the keysite's own buildings die, so airbase/installation\n        -- health is driven by the deterministic strike channel (keysite.strike_damage /\n        -- installations.damage) and registered-asset death (installations.register_static_death) \226\128\148 the\n        -- old generic kill-proximity bleed (both apply_kill_damage calls) was removed in Cluster G (B4).\n        M.check_win(log_fn)\n\n        -- Pilot career: credit the killer if it is a human (spec 10 PILOT-F16 player branch).\n        -- pcall-guarded so the career substrate is fully inert / harmless with zero players.\n        local ok_p, pilots = pcall(require, \"pilots\")\n        if ok_p and pilots then pcall(pilots.on_kill, event) end\n    end\n\n    return handler\nend\n\nreturn M\n"
__modules["zones"] = "-- zones.lua \226\128\148 read author-placed Mission Editor trigger zones and test points against them.\n-- Lets the campaign layout be AUTHORED in the ME (theatre bounds, side ownership, objectives, no-go\n-- areas) instead of auto-derived. Supports both CIRCLE and QUAD (box) zones.\n--\n-- Coordinate mapping: in the mission file, zone geometry uses (x, y) where x = world x (north) and\n-- y = world z (east). We normalise to world (x, z).\n\nlocal cs = require(\"campaign_state\")\nlocal M  = {}\n\nlocal loaded = {}   -- name(lower) \226\134\146 { name, color, cx, cz, [verts | radius] }\n\n-- Keysite type keywords (first word of a keysite zone's name \226\134\146 keysite type). Mirrors the EECH\n-- keysite_database sub-types (ks_dbase.c). Zones whose first word is NOT one of these (e.g. a plain\n-- \"BLUE\"/\"RED\"/\"THEATRE\" scoping box) are not keysites and are skipped by keysites()/has_keysite_zones().\nlocal KEYSITE_KINDS = {\n    airbase = true, farp = true, factory = true, refinery = true, port = true,\n    radar   = true, depot = true, power = true, command = true, fuel = true,\n}\n\n-- Leading (lower-cased) LETTERS of a zone name \226\128\148 the keysite type selector. Uses %a+ so a numbered or\n-- suffixed name resolves to its type: \"airbase-1\" / \"farp 2\" / \"factoryEast\" all \226\134\146 airbase/farp/factory.\nlocal function first_word(name)\n    if not name then return \"\" end\n    return string.lower(string.match(name, \"^%s*(%a+)\") or \"\")\nend\n\n-- Point-in-polygon (ray casting) for quad/box zones.\nlocal function point_in_poly(px, pz, verts)\n    local inside, n = false, #verts\n    local j = n\n    for i = 1, n do\n        local vi, vj = verts[i], verts[j]\n        if ((vi.z > pz) ~= (vj.z > pz)) and\n           (px < (vj.x - vi.x) * (pz - vi.z) / ((vj.z - vi.z) ~= 0 and (vj.z - vi.z) or 1e-9) + vi.x) then\n            inside = not inside\n        end\n        j = i\n    end\n    return inside\nend\n\n-- Load every ME trigger zone. Call once at init (after the mission is live).\nfunction M.load()\n    loaded = {}\n    local zs = env.mission and env.mission.triggers and env.mission.triggers.zones\n    if not zs then\n        cs.dbg(\"zones\", \"load: no env.mission.triggers.zones table found -> 0 zones\")\n        return 0\n    end\n    local n = 0\n    for _, z in ipairs(zs) do\n        if z.name then\n            local rec\n            if z.type == 2 and z.verticies then   -- QUAD / box\n                rec = { verts = {} }\n                local sx, sz = 0, 0\n                for _, v in ipairs(z.verticies) do\n                    rec.verts[#rec.verts + 1] = { x = v.x, z = v.y }\n                    sx, sz = sx + v.x, sz + v.y\n                end\n                local nv = math.max(#rec.verts, 1)\n                rec.cx, rec.cz = sx / nv, sz / nv    -- centroid = keysite location\n            else                                   -- CIRCLE\n                rec = { cx = z.x, cz = z.y, radius = z.radius or 0 }\n            end\n            rec.name  = z.name    -- original name (label + first-word type selector)\n            rec.color = z.color   -- {r,g,b,a} 0..1 \226\128\148 sets the side (side_of_color)\n            loaded[string.lower(z.name)] = rec\n            n = n + 1\n        end\n    end\n    local n_ks = 0\n    for _, rec in pairs(loaded) do\n        if KEYSITE_KINDS[first_word(rec.name)] then n_ks = n_ks + 1 end\n    end\n    cs.dbg(\"zones\", \"load: %d zones loaded (%d recognised as keysite zones)\", n, n_ks)\n    return n\nend\n\n-- Does a zone with this name exist?\nfunction M.exists(name)\n    return loaded[string.lower(name)] ~= nil\nend\n\n-- Is world point (wx,wz) inside the named zone?\nfunction M.contains(name, wx, wz)\n    local z = loaded[string.lower(name)]\n    if not z then return false end\n    if z.verts then return point_in_poly(wx, wz, z.verts) end\n    return cs.dist2d(wx, wz, z.cx, z.cz) <= (z.radius or 0)\nend\n\n-- Names of every author-placed STATIC OBJECT whose position falls inside the named zone (circle or\n-- quad). Scans all coalitions (BLUE/RED/NEUTRAL) so a keysite registers every physical asset the\n-- author dropped in its circle regardless of the static's coalition. Used by the register-not-spawn\n-- keysite layer (installations.lua / keysite.lua) \226\128\148 the campaign REGISTERS these, it spawns nothing.\nfunction M.statics_in_zone(zone_name)\n    local out = {}\n    for _, side in ipairs({ coalition.side.BLUE, coalition.side.RED, coalition.side.NEUTRAL }) do\n        local ok, objs = pcall(coalition.getStaticObjects, side)\n        if ok and objs then\n            for _, so in ipairs(objs) do\n                local ok2, p = pcall(function() return so:getPoint() end)\n                if ok2 and p and M.contains(zone_name, p.x, p.z) then\n                    local ok3, nm = pcall(function() return so:getName() end)\n                    if ok3 and nm then out[#out + 1] = nm end\n                end\n            end\n        end\n    end\n    return out\nend\n\n-- \226\148\128\226\148\128 Destroyable resource SCENERY inside a keysite zone (register-not-spawn) \226\148\128\226\148\128\226\148\128\226\148\128\n-- The Caucasus airfields ship with a few DESTROYABLE resource scenery objects (fuel-barrel dumps /\n-- GSM fuel stations / warehouses). These are author-INDEPENDENT map assets: the campaign REGISTERS\n-- them exactly like placed statics so a keysite drains as they burn. Resource scenery is SPARSE\n-- (only AIRBASE_BARRELS_01 and PAR_GSM observed live across the test airfields), so the allowlist is\n-- EXTENDABLE and backed by a fuel/warehouse/depot pattern fallback.\n--\n-- Scenery cannot be re-acquired by name (Object.getByName(sceneryName) == nil), so each returned row\n-- HOLDS the live handle; installations.lua polls handle:getLife() on that held handle to detect death.\n-- Exact Caucasus airbase resource types (upper-cased keys). These are the objects DCS shows with the\n-- fuel/warehouse resource icons at an airfield: TOPLIVO-BAK_NEW (fuel tank), AIRBASE_BARRELS_01 (fuel\n-- barrels), SKLADIK (warehouse), PAR_GSM (fuel station). NOT SKLAD_NEW \226\128\148 that is the generic civilian\n-- warehouse building (dozens across a nearby town), which must not be registered as airbase assets.\nM.RESOURCE_SCENERY = {\n    [\"AIRBASE_BARRELS_01\"] = true, [\"PAR_GSM\"] = true,\n    [\"TOPLIVO-BAK_NEW\"]    = true, [\"SKLADIK\"] = true,\n}\n\n-- True if an (upper-cased) scenery typename names a destroyable resource asset: an explicit allowlist\n-- hit, or a fuel/barrel/warehouse/depot/GSM/storage pattern (excluding poles/lights/trees/polys).\nlocal function is_resource_scenery(typename, type_set)\n    if not typename then return false end\n    local up = string.upper(typename)\n    if type_set and type_set[up] then return true end\n    if string.find(up, \"POLE\", 1, true) or string.find(up, \"POLY\", 1, true)\n       or string.find(up, \"LIGHT\", 1, true) or string.find(up, \"TREE\", 1, true) then\n        return false\n    end\n    return string.find(up, \"FUEL\", 1, true) ~= nil\n        or string.find(up, \"BARREL\", 1, true) ~= nil\n        or string.find(up, \"WARE\", 1, true) ~= nil\n        or string.find(up, \"DEPOT\", 1, true) ~= nil\n        or string.find(up, \"GSM\", 1, true) ~= nil\n        or string.find(up, \"STORAGE\", 1, true) ~= nil\n        -- TOPLIVO (Russian \"fuel\") is airbase-specific and safe to pattern-match; SKLAD (\"warehouse\") is\n        -- NOT \226\128\148 SKLAD_NEW is a generic civilian building used map-wide, so it's excluded from the pattern\n        -- and only the exact airbase warehouse type (SKLADIK) registers, via the allowlist above.\n        or string.find(up, \"TOPLIVO\", 1, true) ~= nil\nend\n\n-- Bounding-sphere radius covering a zone: the circle radius, or (for a quad) the greatest centroid\226\134\146\n-- vertex distance so the sphere fully encloses the box.\nlocal function zone_bounding_radius(z)\n    if z.radius and z.radius > 0 then return z.radius end\n    local r = 0\n    if z.verts then\n        for _, v in ipairs(z.verts) do\n            local d = cs.dist2d(z.cx, z.cz, v.x, v.z)\n            if d > r then r = d end\n        end\n    end\n    return r\nend\n\n-- Destroyable resource SCENERY whose position falls inside the named keysite zone. Searches SCENERY\n-- over the zone's bounding sphere, keeps only objects whose typename is a resource asset AND whose\n-- point is genuinely inside the zone (contains()), and returns one row per object:\n--   { id = <getName, a stable numeric map-id string>, type = <typename>, handle = <live object>,\n--     life0 = <getLife at registration> }\n-- The HANDLE is the drain key: scenery cannot be re-acquired by name, so installations.lua polls\n-- handle:getLife() on this held handle. Everything is pcall-guarded. type_set defaults to\n-- M.RESOURCE_SCENERY. Spawns nothing \226\128\148 REGISTER-only, mirroring statics_in_zone.\nfunction M.scenery_in_zone(zone_name, type_set)\n    local out = {}\n    local z = loaded[string.lower(zone_name)]\n    if not z then return out end\n    type_set = type_set or M.RESOURCE_SCENERY\n    local radius = zone_bounding_radius(z)\n    if not radius or radius <= 0 then return out end\n    local seen = {}\n    local volume = {\n        id = world.VolumeType.SPHERE,\n        params = { point = { x = z.cx, y = 0, z = z.cz }, radius = radius },\n    }\n    local handler = function(obj)\n        pcall(function()\n            local tn = obj:getTypeName()\n            if not is_resource_scenery(tn, type_set) then return end\n            local p = obj:getPoint()\n            if not (p and M.contains(zone_name, p.x, p.z)) then return end\n            local id = obj:getName()\n            if not id or seen[id] then return end\n            seen[id] = true\n            out[#out + 1] = { id = id, type = tn, handle = obj, life0 = obj:getLife() }\n        end)\n        return true   -- keep enumerating\n    end\n    pcall(world.searchObjects, Object.Category.SCENERY, volume, handler)\n    return out\nend\n\n-- List of loaded zone names (for logging/diagnostics).\nfunction M.names()\n    local out = {}\n    for k in pairs(loaded) do out[#out + 1] = k end\n    return out\nend\n\n-- \226\148\128\226\148\128 Author-placed keysite zones (the zone-based theatre) \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n-- Colour sets the side, first word of the name sets the type, centre sets the location.\n\n-- Side from a zone's colour: BLUE if blue-dominant, RED if red-dominant, nil if grey/neutral.\n-- Accepts the raw zone table (uses .color) or a bare {r,g,b,a} colour array.\nfunction M.side_of_color(zone_raw)\n    local c = zone_raw and (zone_raw.color or zone_raw)\n    if type(c) ~= \"table\" then return nil end\n    local r, b = c[1] or 0, c[3] or 0\n    if b > r then return coalition.side.BLUE\n    elseif r > b then return coalition.side.RED end\n    return nil   -- grey / neutral: not assigned to a side\nend\n\n-- List of authored keysite zones (call after load()): { type, side, x, z, label } per zone whose\n-- first word is a keysite keyword. Plain BLUE/RED/THEATRE scoping boxes are skipped.\nfunction M.keysites()\n    local out = {}\n    for _, rec in pairs(loaded) do\n        local kind = first_word(rec.name)\n        if KEYSITE_KINDS[kind] then\n            out[#out + 1] = {\n                type  = kind,\n                side  = M.side_of_color(rec),\n                x     = rec.cx,\n                z     = rec.cz,\n                label = rec.name,\n            }\n        end\n    end\n    return out\nend\n\n-- True if the author placed any keysite zone (airbase/farp/factory/...). Selects the zone-based\n-- theatre over the auto-generation fallback.\nfunction M.has_keysite_zones()\n    for _, rec in pairs(loaded) do\n        if KEYSITE_KINDS[first_word(rec.name)] then return true end\n    end\n    return false\nend\n\nreturn M\n"

return __require("Scripts.dynamic-mission-test.main")
